def _add_batch_002_observe_arguments(parser: argparse.ArgumentParser) -> None:
    parser.add_argument(
        "--cycle-store",
        type=Path,
        required=True,
        help="Acquisition store sqlite path holding the attached batch.",
    )
    parser.add_argument("--batch-id", default=_BATCH_002_DEFAULT_BATCH_ID)
    parser.add_argument(
        "--eligibility-anchor",
        default=_BATCH_002_DEFAULT_ANCHOR,
        metavar="YYYY-MM-DD",
        help="Immutable first-written-disposition eligibility anchor.",
    )
    parser.add_argument(
        "--min-interval-seconds",
        type=float,
        default=None,
        help=(
            "Minimum spacing between logical requests. The live default is "
            "derived from the selected profile's hourly ceiling (12.5s base; "
            "6.25s temporary-doubled); fixtures are unpaced."
        ),
    )
    parser.add_argument(
        "--jitter-seconds",
        type=float,
        default=0.25,
        help="Uniform random jitter added to each pause; default 0.25.",
    )
    parser.add_argument(
        "--retry-backoff-seconds",
        type=float,
        default=2.0,
        help="Backoff between 429/5xx retries; reuses the client retry loop.",
    )
    parser.add_argument("--max-retries", type=int, default=2)
    parser.add_argument(
        "--limit",
        type=int,
        default=None,
        help="Observe at most N candidates this pass (smoke runs); default all.",
    )
    parser.add_argument(
        "--refresh-reason-code",
        action="append",
        choices=cohort_reason_policy_taxonomy()["refreshable_reason_codes"],
        default=[],
        help=(
            "Re-observe current terminal candidates carrying this refreshable "
            "reason code after a documented screening correction. Repeat for "
            "multiple codes; immutable exclusions cannot be refreshed."
        ),
    )
    parser.add_argument(
        "--revalidate-candidate-id",
        action="append",
        default=[],
        help=(
            "Re-observe this exact currently accepted batch candidate after a "
            "documented false-positive screening correction. Repeat for multiple "
            "candidate ids."
        ),
    )
    parser.add_argument(
        "--refresh-campaign-cutoff",
        help=(
            "Frozen timezone-aware ISO-8601 cutoff for a refresh/revalidation "
            "campaign. Required with --refresh-reason-code or "
            "--revalidate-candidate-id; reuse the exact value on every limited "
            "resume so already refreshed observations are not selected again."
        ),
    )
    _add_batch_002_source_arguments(
        parser,
        live_help=(
            "Reconstruct and screen through authenticated CourtListener REST. "
            "Requires COURTLISTENER_API_TOKEN and --request-ledger."
        ),
    )
    parser.add_argument("--summary-output", type=Path)
    parser.set_defaults(handler=_cmd_batch_002_observe)


def _add_batch_002_observe_firecrawl_arguments(
    parser: argparse.ArgumentParser,
) -> None:
    parser.add_argument(
        "--cycle-store",
        type=Path,
        required=True,
        help="Acquisition store containing the frozen priority batch.",
    )
    parser.add_argument("--batch-id", required=True)
    parser.add_argument(
        "--run-id",
        required=True,
        help=(
            "Immutable resumable Firecrawl run identity. Reuse it with the same "
            "arguments after interruption."
        ),
    )
    parser.add_argument(
        "--eligibility-anchor",
        default=_BATCH_002_DEFAULT_ANCHOR,
        metavar="YYYY-MM-DD",
        help=(
            "Must equal the frozen cycle eligibility anchor; default "
            f"{_BATCH_002_DEFAULT_ANCHOR}."
        ),
    )
    parser.add_argument(
        "--candidate-id",
        action="append",
        default=[],
        help=(
            "Exact frozen batch candidate to observe. Repeat for a subset; "
            "caller order never changes frozen acquisition priority. Without "
            "this flag, select every candidate lacking a current observation."
        ),
    )
    parser.add_argument(
        "--limit",
        type=int,
        help=(
            "Freeze at most the first N unresolved candidates into a new run. "
            "Ignored in favor of the already frozen scope when resuming a run."
        ),
    )
    parser.add_argument(
        "--raw-artifact-dir",
        type=Path,
        required=True,
        help="Durable directory for scheduler-authenticated raw page artifacts.",
    )
    parser.add_argument(
        "--credit-cap",
        type=int,
        default=45_000,
        help="Cycle-wide Firecrawl authorization cap; maximum 45000.",
    )
    parser.add_argument(
        "--workers",
        type=int,
        choices=range(1, 11),
        default=10,
        metavar="1-10",
        help=(
            "Concurrent Firecrawl docket-page requests; default 10. Durable "
            "authorization and artifact commits remain serialized."
        ),
    )
    parser.add_argument(
        "--max-pages-per-docket",
        type=int,
        default=100,
        help=(
            "Hard pagination ceiling per docket; incomplete dockets remain "
            "transient rather than excluded. Default 100."
        ),
    )
    parser.add_argument(
        "--max-attempts-per-page",
        type=int,
        default=3,
        help="Bounded attempts per page; default 3.",
    )
    parser.add_argument(
        "--provider-breaker-threshold",
        type=int,
        default=5,
        help="Stop after this many consecutive Firecrawl provider 5xx responses.",
    )
    parser.add_argument(
        "--proxy",
        choices=("basic", "auto", "enhanced"),
        default="auto",
        help=(
            "Firecrawl proxy mode. Basic reserves one credit; auto/enhanced "
            "reserve at most five credits per request."
        ),
    )
    parser.add_argument(
        "--force-browser",
        action="store_true",
        help="Force Firecrawl's browser engine and freeze that choice in the run.",
    )
    source = parser.add_mutually_exclusive_group(required=True)
    source.add_argument(
        "--live-firecrawl",
        action="store_true",
        help="Use FIRECRAWL_API_KEY for allowlisted CourtListener docket pages.",
    )
    source.add_argument(
        "--firecrawl-fixture",
        type=Path,
        help="No-network Firecrawl response fixture for tests and rehearsal.",
    )
    parser.add_argument("--summary-output", type=Path)
    parser.set_defaults(handler=_cmd_batch_002_observe_firecrawl)


