def main(argv: Sequence[str] | None = None) -> int:
    args = list(argv) if argv is not None else sys.argv[1:]
    if args and args[0] == "freeze":
        from legalforecast.protocol.freeze import cli_freeze

        return cli_freeze(args[1:])
    if args[:2] == ["publish", "aggregate"]:
        from legalforecast.publication.official_aggregate import main as aggregate_main

        return aggregate_main(args[2:])

    parser = build_parser()
    parsed = parser.parse_args(args)
    handler = cast(CommandHandler | None, getattr(parsed, "handler", None))
    if handler is None:
        parser.print_help()
        return 0
    try:
        return handler(parsed)
    except CommandError as exc:
        _record_disclosure_command_failure(parsed, str(exc))
        print(f"legalforecast: {exc}", file=sys.stderr)
        return 2
    except FileNotFoundError as exc:
        _record_disclosure_command_failure(parsed, f"missing file: {exc.filename}")
        print(f"legalforecast: missing file: {exc.filename}", file=sys.stderr)
        return 2
    except ValueError as exc:
        _record_disclosure_command_failure(parsed, str(exc))
        print(f"legalforecast: {exc}", file=sys.stderr)
        return 2
    except OSError as exc:
        if _record_disclosure_command_failure(parsed, str(exc)):
            print(f"legalforecast: {exc}", file=sys.stderr)
            return 2
        raise
    except KeyboardInterrupt:
        _record_disclosure_command_failure(parsed, "interactive review interrupted")
        raise


def _record_disclosure_command_failure(args: argparse.Namespace, reason: str) -> bool:
    """Best-effort durable failure boundary for all disclosure-review stages."""

    command = getattr(args, "acquisition_command", None)
    context = _disclosure_failure_context(args, command)
    if context is None:
        return False
    stage, input_paths, output_paths = context
    try:
        _write_disclosure_review_failure(
            args,
            stage=stage,
            input_paths=input_paths,
            output_paths=output_paths,
            reason=reason,
        )
    except (CommandError, OSError, UnicodeError, ValueError) as exc:
        # A completed run card is deliberately never overwritten by a later
        # exception (including a phase-two log fsync failure).
        print(
            f"legalforecast: unable to publish {stage} failure metadata: {exc}",
            file=sys.stderr,
        )
    return True


def _disclosure_failure_context(
    args: argparse.Namespace, command: object
) -> tuple[str, tuple[Path, ...], tuple[Path, ...]] | None:
    disclosure_commands = {
        "prepare-disclosure-review",
        "plan-disclosure-provenance",
        "record-disclosure-review-decisions",
        "build-disclosure-review-bundle",
        "seal-disclosure-review-bundle",
        "clear-provenance-disclosures",
        "finalize-provenance-quarantine",
        "review-disclosure-exceptions",
    }
    if command not in disclosure_commands:
        return None
    command_name = cast(str, command)
    output_root = cast(Path, args.output_root)
    if command == "review-disclosure-exceptions":
        private_root = cast(Path, args.controlled_private_store_root)
        return (
            command_name,
            (
                cast(Path, args.routing_plan),
                cast(Path, args.exception_worksheet),
                cast(Path, args.plan_run_card),
                cast(Path, args.document_root),
                cast(Path, args.frozen_authority_root),
            ),
            (
                _acquisition_path(
                    args,
                    "authority_output",
                    output_root / "disclosure-model-review-authority.json",
                ),
                _acquisition_path(
                    args,
                    "private_records_output",
                    private_root / "disclosure-model-review-private-records.json",
                ),
            ),
        )
    if command == "plan-disclosure-provenance":
        return (
            command_name,
            tuple(
                cast(Path, getattr(args, name))
                for name in (
                    "review_requests",
                    "download_manifest",
                    "case_relevance",
                    "restriction_evidence",
                    "document_root",
                )
            ),
            (
                _acquisition_path(
                    args,
                    "routing_plan_output",
                    output_root / "disclosure-provenance-plan.json",
                ),
                _acquisition_path(
                    args,
                    "exception_worksheet_output",
                    output_root / "disclosure-exception-worksheet.json",
                ),
            ),
        )
    if command == "clear-provenance-disclosures":
        return (
            "clear-disclosures",
            tuple(
                cast(Path, getattr(args, name))
                for name in (
                    "review_requests",
                    "download_manifest",
                    "case_relevance",
                    "restriction_evidence",
                    "document_root",
                    "routing_plan",
                    "exception_worksheet",
                    "exception_decisions",
                    "exception_review_run_card",
                    "cohort_policy",
                )
            ),
            (
                _acquisition_path(
                    args,
                    "clearance_output",
                    output_root / "disclosure-clearance.jsonl",
                ),
                _acquisition_path(
                    args,
                    "quarantine_output",
                    output_root / "disclosure-quarantine.jsonl",
                ),
            ),
        )
    if command == "finalize-provenance-quarantine":
        plan_run_card = cast(Path | None, getattr(args, "plan_run_card", None))
        return (
            "finalize-provenance-quarantine",
            tuple(
                cast(Path, getattr(args, name))
                for name in (
                    "review_requests",
                    "download_manifest",
                    "case_relevance",
                    "restriction_evidence",
                    "document_root",
                    "routing_plan",
                    "exception_worksheet",
                    "cohort_policy",
                )
            )
            + ((plan_run_card,) if plan_run_card is not None else ()),
            (
                _acquisition_path(
                    args,
                    "clearance_output",
                    output_root / "disclosure-clearance.jsonl",
                ),
                _acquisition_path(
                    args,
                    "quarantine_output",
                    output_root / "disclosure-quarantine.jsonl",
                ),
            ),
        )
    if command == "prepare-disclosure-review":
        return (
            command_name,
            (
                cast(Path, args.review_requests),
                cast(Path, args.download_manifest),
                cast(Path, args.restriction_evidence),
                cast(Path, args.reviewer_policy),
                cast(Path, args.cohort_policy),
                cast(Path, args.document_root),
            ),
            (
                _acquisition_path(
                    args,
                    "worksheet_output",
                    output_root / "disclosure-review-worksheet.json",
                ),
            ),
        )
    if command == "record-disclosure-review-decisions":
        private_root = cast(Path, args.controlled_private_store_root).resolve()
        return (
            command_name,
            (
                cast(Path, args.review_worksheet),
                cast(Path, args.private_inspection_map),
            ),
            (
                _acquisition_path(
                    args,
                    "decisions_output",
                    private_root / "disclosure-review-decisions.jsonl",
                ),
            ),
        )
    if command == "build-disclosure-review-bundle":
        return (
            command_name,
            (
                cast(Path, args.review_worksheet),
                cast(Path, args.decisions),
                cast(Path, args.reviewer_policy),
                cast(Path, args.cohort_policy),
            ),
            (
                _acquisition_path(
                    args,
                    "reviews_output",
                    output_root / "disclosure-reviews.jsonl",
                ),
                _acquisition_path(
                    args,
                    "signing_statement_output",
                    output_root / "disclosure-review-signing-statement.json",
                ),
            ),
        )
    if command == "seal-disclosure-review-bundle":
        return (
            command_name,
            tuple(
                cast(Path, getattr(args, name))
                for name in (
                    "review_requests",
                    "download_manifest",
                    "restriction_evidence",
                    "review_worksheet",
                    "reviews",
                    "decisions",
                    "signing_statement",
                    "signature",
                    "reviewer_policy",
                    "cohort_policy",
                )
            ),
            (
                _acquisition_path(
                    args,
                    "review_receipt_output",
                    output_root / "disclosure-review-receipt.json",
                ),
            ),
        )
    return None


def _cmd_discover(args: argparse.Namespace) -> int:
    input_path = cast(Path, args.input)
    output_path = cast(Path, args.output)
    records = _read_records(input_path)
    if cast(bool, args.print_search_terms):
        print(json.dumps({"search_terms": list(mtd_discovery_search_terms())}))
    if cast(bool, args.dry_run):
        return _write_dry_run_plan(
            "discover",
            output_path,
            input_path=input_path,
            output_paths=(output_path,),
            record_count=len(records),
            log_record_count=len(records),
            search_terms=mtd_discovery_search_terms(),
        )

    candidates = [
        candidate.to_record() for candidate in discover_mtd_candidates(records)
    ]
    _write_jsonl(output_path, candidates)
    _log_event("discover", "artifact_written", output_path, len(candidates))
    return 0


