def _cmd_pilot_fallback(args: argparse.Namespace) -> int:
    smoke_report_path = cast(Path, args.smoke_report)
    output_path = cast(Path, args.output)
    generated_at_text = cast(str | None, args.generated_at)
    attempt_limit = cast(int, args.attempt_limit)
    page_size = cast(int, args.courtlistener_page_size)
    smoke_report_text = smoke_report_path.read_text(encoding="utf-8")
    credentials = FallbackCredentialStatus.from_env()
    fallback_candidates = tuple(
        candidate
        for candidate in parse_case_dev_fallback_candidates(smoke_report_text)
        if candidate.needs_docket_fallback
    )
    attempts = None
    courtlistener_fixture = cast(Path | None, args.courtlistener_fixture)
    live_courtlistener = cast(bool, args.live_courtlistener)
    if courtlistener_fixture is not None:
        attempts = run_courtlistener_fallback_attempts(
            fallback_candidates,
            client=CourtListenerClient(
                config=CourtListenerConfig.from_env(),
                transport=CourtListenerFixtureTransport.from_jsonl(
                    courtlistener_fixture
                ),
            ),
            attempt_limit=attempt_limit,
            page_size=page_size,
        )
    elif live_courtlistener and credentials.courtlistener_token_present:
        attempts = run_courtlistener_fallback_attempts(
            fallback_candidates,
            client=CourtListenerClient(config=CourtListenerConfig.from_env()),
            attempt_limit=attempt_limit,
            page_size=page_size,
        )

    report = build_fallback_reconstruction_pilot_report(
        smoke_report_text,
        credentials=credentials,
        attempts=attempts,
        attempt_limit=attempt_limit,
        generated_at=(
            _parse_datetime(generated_at_text)
            if generated_at_text is not None
            else datetime.now(UTC)
        ),
        live_courtlistener_requested=live_courtlistener,
    )
    _write_text(output_path, render_fallback_reconstruction_pilot_markdown(report))
    _log_event(
        "pilot-fallback-reconstruction",
        "artifact_written",
        output_path,
        len(report.attempts),
    )
    return 0


def _cmd_acquisition_plan(args: argparse.Namespace) -> int:
    output_root = _acquisition_output_root(args)
    input_path = cast(Path, args.core_filter_results)
    output_path = _acquisition_path(
        args,
        "budget_plan_output",
        output_root / "missing-core-budget-plan.json",
    )
    exclusions_path = _acquisition_path(
        args,
        "exclusions_output",
        output_root / "missing-core-budget-exclusions.jsonl",
    )
    records = _read_records(input_path)
    dry_run = _acquisition_dry_run(args)
    plan = plan_missing_core_document_budget(
        (_core_document_filter_result(record) for record in records),
        dry_run=dry_run,
        max_missing_core_documents_per_case=cast(
            int,
            args.max_missing_core_documents_per_case,
        ),
        cost_per_document_usd=cast(str, args.cost_per_document_usd),
        max_projected_budget_usd=cast(str, args.max_projected_budget_usd),
        truncate_to_budget=cast(bool, args.truncate_to_budget),
        target_case_count=cast(int | None, args.target_case_count),
    )
    write_missing_core_budget_plan(plan, output_path)
    exclusion_ledger = merge_exclusion_ledger_records(
        ExclusionLedgerEntry(
            candidate_id=case_plan.candidate_id,
            case_id=case_plan.candidate_id,
            stage=ExclusionStage.EXTRACTION,
            reason=case_plan.exclusion_reasons[0],
            secondary_reasons=case_plan.exclusion_reasons[1:],
            source_entry_ids=(),
            source_document_ids=case_plan.purchase_document_ids,
            notes=_missing_core_exclusion_notes(case_plan, plan),
        ).to_record()
        for case_plan in plan.excluded_case_plans
    )
    exclusion_ledger.write_jsonl(exclusions_path)
    _write_acquisition_completion(
        args,
        stage="acquisition-plan",
        input_paths=(input_path,),
        output_paths=(output_path, exclusions_path),
        record_count=len(plan.case_plans),
        dry_run=dry_run,
        paid_activity_requested=False,
        paid_activity_executed=False,
        extra={
            "total_missing_core_documents": plan.total_missing_core_documents,
            "total_estimated_cost_usd": plan.total_estimated_cost_usd,
            "frontier_truncated": plan.frontier_truncated,
            "target_case_count": plan.target_case_count,
            "target_case_count_met": plan.target_case_count_met,
            "omitted_candidate_count": len(plan.omitted_candidate_ids),
            "excluded_case_count": len(plan.excluded_case_plans),
        },
    )
    return 0


@dataclass(frozen=True, slots=True)
class _TargetPreparationProfile:
    stage: str
    label: str
    summary_filename: str
    config_filename: str
    summary_schema: str
    config_schema: str
    attempt_schema: str
    exact_target_case_count: int | None
    emit_full_candidate_frontier: bool

    def target_case_count(self, args: argparse.Namespace) -> int:
        if self.exact_target_case_count is not None:
            return self.exact_target_case_count
        return cast(int, args.target_case_count)


_TARGET_100_PREPARATION = _TargetPreparationProfile(
    stage="prepare-target-100",
    label="target-100",
    summary_filename="target-100-preparation-summary.json",
    config_filename="target-100-config.json",
    summary_schema="legalforecast.target_100_preparation.v1",
    config_schema="legalforecast.target_100_config.v1",
    attempt_schema="legalforecast.target_100_attempt.v1",
    exact_target_case_count=100,
    emit_full_candidate_frontier=False,
)
_TARGET_COHORT_PREPARATION = _TargetPreparationProfile(
    stage="prepare-target-cohort",
    label="target-cohort",
    summary_filename="target-cohort-preparation-summary.json",
    config_filename="target-cohort-config.json",
    summary_schema="legalforecast.target_cohort_preparation.v1",
    config_schema="legalforecast.target_cohort_config.v1",
    attempt_schema="legalforecast.target_cohort_attempt.v1",
    exact_target_case_count=None,
    emit_full_candidate_frontier=True,
)


def _cmd_acquisition_prepare_target_100(args: argparse.Namespace) -> int:
    """Run the exact-100 compatibility preparation command."""

    return _cmd_acquisition_prepare_target(args, profile=_TARGET_100_PREPARATION)


def _cmd_acquisition_prepare_target_cohort(args: argparse.Namespace) -> int:
    """Run generic noncharging preparation for an explicit target size."""

    return _cmd_acquisition_prepare_target(args, profile=_TARGET_COHORT_PREPARATION)


def _cmd_acquisition_prepare_target(
    args: argparse.Namespace,
    *,
    profile: _TargetPreparationProfile,
) -> int:
    """Run the shared public-first chain and emit clearance inputs."""

    output_root = cast(Path, args.output_root)
    target_case_count = profile.target_case_count(args)
    retarget_source_root = cast(
        Path | None, getattr(args, "retarget_source_preparation_root", None)
    )
    stop_after = cast(str | None, getattr(args, "stop_after", None))
    source_preparation: FailedSourcePreparation | None = None
    source_tree_before: SourceTreeCommitment | None = None
    if stop_after is not None and retarget_source_root is None:
        raise CommandError("--stop-after requires --retarget-source-preparation-root")
    if stop_after is not None and _acquisition_dry_run(args):
        raise CommandError("--stop-after retarget-import requires --execute")
    if retarget_source_root is not None:
        if profile is not _TARGET_COHORT_PREPARATION:
            raise CommandError(
                "retarget import is available only through prepare-target-cohort"
            )
        try:
            validate_retarget_preparation_roots(
                source_root=retarget_source_root,
                destination_root=output_root,
                target_case_count=target_case_count,
            )
            source_preparation = inspect_failed_source_preparation(retarget_source_root)
            source_tree_before = compute_source_tree_commitment(source_preparation.root)
        except (RetargetImportError, TargetCohortPreparationError) as exc:
            # The output path is not yet trusted. Never write a failure card into a
            # source/target alias or otherwise mutate either tree on preflight.
            raise CommandError(str(exc)) from exc
    summary_path = _acquisition_path(
        args,
        "summary_output",
        output_root / profile.summary_filename,
    )
    snapshot = cast(Path, args.snapshot)
    expected_cycle_hash = cast(str, args.expected_cycle_hash)
    try:
        _validate_target_100_paths(
            args=args,
            profile=profile,
            output_root=output_root,
            summary_path=summary_path,
            snapshot=snapshot,
            raw_html_dir=cast(Path | None, args.raw_html_dir),
            fixture_documents=cast(Path | None, args.fixture_documents),
            courtlistener_fixture=cast(Path | None, args.courtlistener_fixture),
            request_ledger=cast(Path | None, args.request_ledger),
        )
    except CommandError as exc:
        _write_target_100_attempt_failure(
            args,
            profile=profile,
            reason=str(exc),
            protected_paths=_target_100_protected_paths(args),
        )
        raise
    try:
        snapshot_view = load_verified_screening_snapshot(
            snapshot,
            expected_manifest_sha256=cast(str, args.expected_snapshot_manifest_sha256),
            expected_cycle_hash=expected_cycle_hash,
        )
        snapshot_manifest = snapshot_view.manifest
        snapshot_files = snapshot_manifest.get("files")
        if not isinstance(snapshot_files, Mapping):
            raise SnapshotVerificationError("snapshot manifest lacks file commitments")
        screened_commitment = cast(Mapping[str, object], snapshot_files).get(
            "screened-cases.jsonl"
        )
        if not isinstance(screened_commitment, Mapping):
            raise SnapshotVerificationError(
                "snapshot manifest lacks screened-cases commitment"
            )
        source_screened_cases_sha256 = cast(
            Mapping[str, object], screened_commitment
        ).get("sha256")
        if (
            not isinstance(source_screened_cases_sha256, str)
            or re.fullmatch(r"[0-9a-f]{64}", source_screened_cases_sha256) is None
        ):
            raise SnapshotVerificationError(
                "snapshot screened-cases commitment is invalid"
            )
        snapshot_firecrawl_screening_source_count(
            cast(Mapping[str, object], snapshot_manifest),
            # Retargeting authenticates the exact historical snapshot twice:
            # through its externally pinned manifest and through the immutable
            # failed-preparation config/source-tree receipt. Requiring the current
            # CLI source hash here would make the retarget implementation invalidate
            # the very snapshot it is designed to migrate. Ordinary preparations
            # continue to require the current screening implementation.
            require_current=source_preparation is None,
        )
        stage_commitments = snapshot_manifest.get("stage_commitments")
        if not isinstance(stage_commitments, Mapping):
            raise FirecrawlScreeningIdentityError(
                "snapshot lacks affirmative stage commitments"
            )
        validate_rest_terminal_subset_promotions_in_snapshot(
            cast(Mapping[str, object], stage_commitments),
            snapshot_candidates=tuple(
                {
                    "candidate_id": candidate.candidate_id,
                    "state": candidate.state,
                    "reason_code": candidate.reason_code,
                    "evidence": dict(candidate.evidence),
                    "observed_at": candidate.observed_at,
                }
                for candidate in snapshot_view.candidates
            ),
            snapshot_screened=snapshot_view.screened,
            snapshot_exclusions=snapshot_view.exclusions,
        )
    except (
        SnapshotVerificationError,
        FirecrawlScreeningIdentityError,
        ScreeningSnapshotUnionError,
    ) as exc:
        _write_target_100_attempt_failure(
            args,
            profile=profile,
            reason=str(exc),
            protected_paths=_target_100_protected_paths(args),
        )
        raise CommandError(str(exc)) from exc
    if (
        snapshot_manifest.get("provisional_frontier") is True
        or snapshot_manifest.get("final_cohort_eligible") is False
        or snapshot_manifest.get("full_source_terminal") is False
    ):
        reason = (
            "target preparation rejects provisional snapshots until the full source "
            "is terminal and final-cohort eligibility is authenticated"
        )
        _write_target_100_attempt_failure(
            args,
            profile=profile,
            reason=reason,
            protected_paths=_target_100_protected_paths(args),
        )
        raise CommandError(reason)
    retarget_snapshot_commitment: SnapshotCommitment | None = None
    if source_preparation is not None:
        retarget_snapshot_commitment = SnapshotCommitment(
            manifest_sha256="sha256:" + snapshot_view.manifest_sha256,
            cycle_hash=expected_cycle_hash,
            batch_digest=cast(str, snapshot_manifest["batch_digest"]),
        )
        try:
            retarget_snapshot_commitment.validate()
        except RetargetImportError as exc:
            raise CommandError(str(exc)) from exc
        if (
            retarget_snapshot_commitment.to_record()
            != source_preparation.snapshot.to_record()
        ):
            raise CommandError(
                "retarget source and requested snapshot commitments differ"
            )
    authenticated_screened_cases = (
        output_root / "00-authenticated-snapshot/screened-cases.jsonl"
    )
    authenticated_screened_payload = snapshot_view.payloads["screened-cases.jsonl"]
    authenticated_screened_sha256 = hashlib.sha256(
        authenticated_screened_payload
    ).hexdigest()
    try:
        _write_immutable_bytes(
            authenticated_screened_cases,
            authenticated_screened_payload,
            resume=cast(bool, args.resume),
        )
        raw_html_bytes_by_candidate = _authenticated_snapshot_raw_html_bytes(
            snapshot_view,
            requested=cast(Path | None, args.raw_html_dir),
            use_embedded_entries=cast(bool, args.use_embedded_entries),
        )
        (
            authenticated_raw_html_dir,
            authenticated_raw_html_manifest,
            authenticated_raw_html_manifest_sha256,
        ) = _materialize_target_authenticated_raw_html(
            output_root=output_root,
            raw_html_bytes_by_candidate=raw_html_bytes_by_candidate,
            resume=cast(bool, args.resume),
        )
    except (CommandError, OSError) as exc:
        _write_target_100_attempt_failure(
            args,
            profile=profile,
            reason=str(exc),
            protected_paths=_target_100_protected_paths(args),
        )
        if isinstance(exc, CommandError):
            raise
        raise CommandError(str(exc)) from exc
    candidate_pool_size = len(snapshot_view.screened)
    config_type = (
        Target100PreparationConfig
        if profile.exact_target_case_count is not None
        else TargetCohortPreparationConfig
    )
    config = config_type(
        output_root=output_root,
        snapshot=snapshot,
        expected_cycle_hash=expected_cycle_hash,
        expected_snapshot_manifest_sha256=cast(
            str, args.expected_snapshot_manifest_sha256
        ),
        candidate_pool_size=candidate_pool_size,
        target_case_count=target_case_count,
        authenticated_screened_cases=authenticated_screened_cases,
        screened_cases_sha256=authenticated_screened_sha256,
        cost_per_document_usd=cast(str, args.cost_per_document_usd),
        max_projected_budget_usd=cast(str, args.max_projected_budget_usd),
        max_missing_core_documents_per_case=cast(
            int, args.max_missing_core_documents_per_case
        ),
        raw_html_dir=authenticated_raw_html_dir,
        authenticated_raw_html_manifest=authenticated_raw_html_manifest,
        authenticated_raw_html_manifest_sha256=(authenticated_raw_html_manifest_sha256),
        requested_raw_html_dir=cast(Path | None, args.raw_html_dir),
        use_embedded_entries=cast(bool, args.use_embedded_entries),
        live_public_download=cast(bool, args.live_public_download),
        fixture_documents=cast(Path | None, args.fixture_documents),
        live_courtlistener=cast(bool, args.live_courtlistener),
        courtlistener_fixture=cast(Path | None, args.courtlistener_fixture),
        request_ledger=cast(Path | None, args.request_ledger),
        courtlistener_rate_profile=cast(str, args.courtlistener_rate_profile),
        request_budget_max_wait_seconds=cast(
            float, args.request_budget_max_wait_seconds
        ),
        resume=cast(bool, args.resume),
    )
    if retarget_source_root is not None:
        if not isinstance(config, TargetCohortPreparationConfig):
            raise CommandError("retarget import requires generic cohort preparation")
        config = replace(
            config,
            retarget_source_preparation_root=retarget_source_root,
        )
    try:
        commands = (
            build_target_100_stage_commands(cast(Target100PreparationConfig, config))
            if profile.exact_target_case_count is not None
            else build_target_cohort_stage_commands(
                cast(TargetCohortPreparationConfig, config)
            )
        )
    except (Target100PreparationError, TargetCohortPreparationError) as exc:
        _write_target_100_attempt_failure(
            args,
            profile=profile,
            reason=str(exc),
            protected_paths=_target_100_protected_paths(args),
        )
        raise CommandError(str(exc)) from exc
    command_records = [
        {"stage": command.stage, "argv": list(command.argv)} for command in commands
    ]
    config_path = output_root / profile.config_filename
    success_run_card_path = _acquisition_path(
        args,
        "run_card_output",
        output_root / f"run-cards/{profile.stage}.json",
    )
    success_log_path = _acquisition_path(
        args,
        "log_output",
        output_root / f"logs/{profile.stage}.jsonl",
    )
    try:
        config_record = _target_100_config_record(
            config,
            profile=profile,
            snapshot_manifest=snapshot_manifest,
            snapshot_manifest_sha256=snapshot_view.manifest_sha256,
            snapshot_screened_cases_sha256=authenticated_screened_sha256,
            snapshot_source_screened_cases_sha256=source_screened_cases_sha256,
            stage_commands=command_records,
            driver_execute=not _acquisition_dry_run(args),
            wrapper_artifact_paths={
                "summary": summary_path,
                "run_card": success_run_card_path,
                "log": success_log_path,
            },
            retarget_source=source_preparation,
            retarget_source_tree=source_tree_before,
        )
        if cast(bool, args.resume):
            completed_evidence_exists = (
                summary_path.exists() or success_run_card_path.exists()
            )
            if completed_evidence_exists:
                if not config_path.is_file():
                    raise CommandError(
                        f"{profile.label} committed config is missing; refusing "
                        "completed-run reconstruction"
                    )
                if not summary_path.is_file():
                    raise CommandError(
                        f"{profile.label} committed success summary is missing; "
                        "refusing child-stage resume"
                    )
                if not success_run_card_path.is_file():
                    raise CommandError(
                        f"{profile.label} committed success run card is missing"
                    )
                _ensure_target_100_config(
                    config_path,
                    config_record,
                    profile=profile,
                    resume=True,
                )
                _verify_completed_preparation_for_frontier(
                    preparation_root=output_root,
                    preparation_summary_path=summary_path,
                    preparation_config_path=config_path,
                    snapshot_manifest_path=snapshot / "manifest.json",
                )
                return 0
        _ensure_target_100_config(
            config_path,
            config_record,
            profile=profile,
            resume=cast(bool, args.resume),
        )
        _verified_target_authenticated_input_commitments(config)
    except (CommandError, OSError, UnicodeError, ValueError) as exc:
        _write_target_100_attempt_failure(
            args,
            profile=profile,
            reason=str(exc),
            protected_paths=_target_100_protected_paths(args),
        )
        if isinstance(exc, CommandError):
            raise
        raise CommandError(str(exc)) from exc
    dry_run = _acquisition_dry_run(args)
    if dry_run:
        _write_json(
            summary_path,
            {
                "schema_version": profile.summary_schema,
                "dry_run": True,
                "target_case_count": target_case_count,
                "candidate_pool_size": config.candidate_pool_size,
                "config_sha256": config_record["config_sha256"],
                "stage_commands": command_records,
                "paid_activity_requested": False,
                "paid_activity_executed": False,
            },
        )
        _write_acquisition_completion(
            args,
            stage=profile.stage,
            input_paths=(config.snapshot,),
            output_paths=(summary_path,),
            record_count=0,
            dry_run=True,
            paid_activity_requested=False,
            paid_activity_executed=False,
        )
        return 0

    if candidate_pool_size < target_case_count:
        reason = (
            f"complete snapshot contains only {candidate_pool_size} viable cases; "
            f"{target_case_count} are required"
        )
        _write_target_100_attempt_failure(
            args,
            profile=profile,
            reason=reason,
            extra={"config_sha256": config_record["config_sha256"]},
            protected_paths=_target_100_protected_paths(args),
        )
        raise CommandError(reason)

    retarget_receipt: RetargetImportReceipt | None = None
    if source_preparation is not None:
        if source_tree_before is None or retarget_snapshot_commitment is None:
            raise CommandError("retarget preflight commitments are incomplete")
        try:
            if stop_after == "retarget-import":
                _execute_target_retarget_import(
                    args=args,
                    config=cast(TargetCohortPreparationConfig, config),
                    commands=commands,
                    source=source_preparation,
                    source_tree_before=source_tree_before,
                    snapshot=retarget_snapshot_commitment,
                    config_path=config_path,
                )
                return 0
            retarget_receipt = _verify_and_seed_target_retarget_import(
                args=args,
                config=cast(TargetCohortPreparationConfig, config),
                source=source_preparation,
            )
        except (
            CommandError,
            FreeDocumentDownloadError,
            RetargetImportError,
            OSError,
            UnicodeError,
            ValueError,
        ) as exc:
            _write_target_100_attempt_failure(
                args,
                profile=profile,
                reason=str(exc),
                extra={"config_sha256": config_record["config_sha256"]},
                protected_paths=_target_100_protected_paths(args),
            )
            if isinstance(exc, CommandError):
                raise
            raise CommandError(str(exc)) from exc

    for command in commands:
        if source_preparation is not None and command.stage == "plan-public-downloads":
            # The verified import receipt already commits every stage-01 byte.
            # Re-running this otherwise deterministic stage would still rewrite
            # generated-at run-card metadata and append a log row, invalidating the
            # immutable receipt before final lineage verification.
            continue
        result = main(command.argv)
        if result != 0:
            reason = (
                f"{profile.label} preparation stopped at {command.stage}; "
                "fix the recorded failure and rerun with --resume"
            )
            _write_target_100_attempt_failure(
                args,
                profile=profile,
                reason=reason,
                extra={"config_sha256": config_record["config_sha256"]},
                protected_paths=_target_100_protected_paths(args),
            )
            raise CommandError(reason)

    try:
        _verified_target_authenticated_input_commitments(config)
        _verified_target_bridge_route_commitments(output_root)
    except (CommandError, OSError, UnicodeError, ValueError) as exc:
        _write_target_100_attempt_failure(
            args,
            profile=profile,
            reason=str(exc),
            extra={"config_sha256": config_record["config_sha256"]},
            protected_paths=_target_100_protected_paths(args),
        )
        if isinstance(exc, CommandError):
            raise
        raise CommandError(str(exc)) from exc

    try:
        _prepare_target_100_clearance_inputs(
            output_root,
            resume=cast(bool, args.resume),
        )
    except (CommandError, TargetCohortProjectionError) as exc:
        _write_target_100_attempt_failure(
            args,
            profile=profile,
            reason=str(exc),
            extra={"config_sha256": config_record["config_sha256"]},
            protected_paths=_target_100_protected_paths(args),
        )
        if isinstance(exc, CommandError):
            raise
        raise CommandError(str(exc)) from exc

    budget_plan_path = output_root / "05-budget" / "missing-core-budget-plan.json"
    budget_plan = _missing_core_budget_plan(_read_json_object(budget_plan_path))
    if budget_plan.dry_run:
        raise CommandError("target-100 budget plan must be executable, not dry-run")
    if (
        not budget_plan.target_case_count_met
        or len(budget_plan.case_plans) != target_case_count
    ):
        reason = (
            f"{profile.label} preparation did not produce exactly "
            f"{target_case_count} complete cases; "
            "acquire additional screened candidates without relaxing any gate"
        )
        _write_target_100_attempt_failure(
            args,
            profile=profile,
            reason=reason,
            extra={"config_sha256": config_record["config_sha256"]},
            protected_paths=_target_100_protected_paths(args),
        )
        raise CommandError(reason)
    full_frontier: tuple[Path, int, str] | None = None
    if profile.emit_full_candidate_frontier:
        try:
            full_frontier = _prepare_full_candidate_frontier(
                output_root,
                budget_plan=budget_plan,
                target_case_count=config.target_case_count,
                cost_per_document_usd=config.cost_per_document_usd,
                max_missing_core_documents_per_case=(
                    config.max_missing_core_documents_per_case
                ),
                snapshot_manifest_path=config.snapshot / "manifest.json",
                snapshot_manifest_sha256=snapshot_view.manifest_sha256,
                preparation_config_path=config_path,
                frontier_path=(output_root / "05-budget/full-candidate-frontier.json"),
                resume=cast(bool, args.resume),
            )
        except (CommandError, OSError, UnicodeError, ValueError) as exc:
            _write_target_100_attempt_failure(
                args,
                profile=profile,
                reason=str(exc),
                extra={"config_sha256": config_record["config_sha256"]},
                protected_paths=_target_100_protected_paths(args),
            )
            if isinstance(exc, CommandError):
                raise
            raise CommandError(str(exc)) from exc
    try:
        _verified_target_authenticated_input_commitments(config)
        _verified_target_bridge_route_commitments(output_root)
        stage_commitments = _target_100_stage_commitments(output_root)
        stage_input_commitments = _target_100_stage_input_commitments(
            output_root,
            config=config,
            frozen_config=config_record,
            snapshot_manifest_sha256=snapshot_view.manifest_sha256,
        )
    except (CommandError, OSError, UnicodeError, ValueError) as exc:
        _write_target_100_attempt_failure(
            args,
            profile=profile,
            reason=str(exc),
            extra={"config_sha256": config_record["config_sha256"]},
            protected_paths=_target_100_protected_paths(args),
        )
        if isinstance(exc, CommandError):
            raise
        raise CommandError(str(exc)) from exc
    selected_ids = [plan.candidate_id for plan in budget_plan.case_plans]
    _write_json(
        summary_path,
        {
            "schema_version": profile.summary_schema,
            "dry_run": False,
            "target_case_count": target_case_count,
            "candidate_pool_size": config.candidate_pool_size,
            "snapshot_manifest_sha256": "sha256:" + snapshot_view.manifest_sha256,
            "snapshot_batch_digest": snapshot_manifest["batch_digest"],
            "config_sha256": config_record["config_sha256"],
            "stage_input_commitments": stage_input_commitments,
            "stage_commitments": stage_commitments,
            **(
                {
                    "retarget_import_receipt_sha256": (
                        retarget_receipt.receipt_file_sha256
                    ),
                    "retarget_import_receipt_self_hash": (
                        retarget_receipt.receipt_sha256
                    ),
                }
                if retarget_receipt is not None
                else {}
            ),
            "selected_candidate_ids_sha256": _canonical_json_sha256(selected_ids),
            "frontier_sha256": _canonical_json_sha256(
                [row.to_record() for row in budget_plan.frontier_rows]
            ),
            "selected_case_count": len(budget_plan.case_plans),
            "total_missing_core_documents": (budget_plan.total_missing_core_documents),
            "total_estimated_cost_usd": budget_plan.total_estimated_cost_usd,
            "cost_per_document_usd": str(budget_plan.cost_per_document),
            "max_projected_budget_usd": budget_plan.max_projected_budget_usd,
            "max_missing_core_documents_per_case": (
                budget_plan.max_missing_core_documents_per_case
            ),
            **(
                {
                    "full_candidate_frontier": str(full_frontier[0]),
                    "full_candidate_frontier_count": full_frontier[1],
                    "full_candidate_frontier_sha256": full_frontier[2],
                }
                if full_frontier is not None
                else {}
            ),
            "budget_plan": str(budget_plan_path),
            "stage_commands": command_records,
            "paid_activity_requested": False,
            "paid_activity_executed": False,
            "budget_status": "provisional_pre_clearance",
            "next_stage": "clear-disclosures",
            "next_stage_blocked_until": (
                "authenticated human review receipts exist for every free "
                "document; then project-target-cohort must recompute the exact "
                "post-clearance frontier before any purchase"
            ),
        },
    )
    _write_acquisition_completion(
        args,
        stage=profile.stage,
        input_paths=(config.snapshot,),
        output_paths=(config_path, summary_path, budget_plan_path),
        record_count=target_case_count,
        dry_run=False,
        paid_activity_requested=False,
        paid_activity_executed=False,
        extra={
            "selected_case_count": target_case_count,
            "total_estimated_cost_usd": budget_plan.total_estimated_cost_usd,
            "config_sha256": config_record["config_sha256"],
            "completed_stages": list(stage_commitments),
            "zero_paid_activity_evidence": True,
            **(
                {
                    "retarget_import_receipt_sha256": (
                        retarget_receipt.receipt_file_sha256
                    )
                }
                if retarget_receipt is not None
                else {}
            ),
        },
    )
    return 0


@dataclass(frozen=True, slots=True)
class _VerifiedPreparationForFrontier:
    target_case_count: int
    cost_per_document_usd: str
    max_missing_core_documents_per_case: int
    budget_plan: MissingCoreBudgetPlan
    success_run_card_path: Path
    protected_paths: tuple[Path, ...]


def _cmd_acquisition_materialize_target_frontier(
    args: argparse.Namespace,
) -> int:
    """Materialize a full frontier without mutating or rerunning preparation."""

    output_root = cast(Path, args.output_root)
    preparation_root = cast(Path, args.preparation_root)
    preparation_summary_path = cast(Path, args.preparation_summary)
    preparation_config_path = cast(Path, args.preparation_config)
    snapshot_manifest_path = cast(Path, args.snapshot_manifest)
    frontier_path = output_root / "full-candidate-frontier.json"
    base_input_paths = (
        preparation_root,
        preparation_summary_path,
        preparation_config_path,
        snapshot_manifest_path,
    )
    verified = _verify_completed_preparation_for_frontier(
        preparation_root=preparation_root,
        preparation_summary_path=preparation_summary_path,
        preparation_config_path=preparation_config_path,
        snapshot_manifest_path=snapshot_manifest_path,
    )
    input_paths = (*base_input_paths, verified.success_run_card_path)
    _validate_materializer_output_paths(
        args,
        output_root=output_root,
        frontier_path=frontier_path,
        input_paths=verified.protected_paths,
    )
    dry_run = _acquisition_dry_run(args)
    run_card_path = _acquisition_path(
        args,
        "run_card_output",
        output_root / "run-cards/materialize-target-cohort-frontier.json",
    )
    if not dry_run and cast(bool, args.resume) and run_card_path.exists():
        _, expected_frontier_count, expected_frontier_sha256 = (
            _prepare_full_candidate_frontier(
                preparation_root,
                budget_plan=verified.budget_plan,
                target_case_count=verified.target_case_count,
                cost_per_document_usd=verified.cost_per_document_usd,
                max_missing_core_documents_per_case=(
                    verified.max_missing_core_documents_per_case
                ),
                snapshot_manifest_path=snapshot_manifest_path,
                preparation_config_path=preparation_config_path,
                frontier_path=frontier_path,
                resume=True,
                additional_source_commitments={
                    "preparation_summary_sha256": preparation_summary_path,
                    "preparation_success_run_card_sha256": (
                        verified.success_run_card_path
                    ),
                },
                write=False,
            )
        )
        _verify_completed_materializer_run_card(
            run_card_path=run_card_path,
            frontier_path=frontier_path,
            input_paths=input_paths,
            target_case_count=verified.target_case_count,
            preparation_summary_path=preparation_summary_path,
            preparation_config_path=preparation_config_path,
            snapshot_manifest_path=snapshot_manifest_path,
            preparation_success_run_card_path=verified.success_run_card_path,
            expected_frontier_sha256=expected_frontier_sha256,
            expected_frontier_count=expected_frontier_count,
        )
        return 0
    output_root.mkdir(parents=True, exist_ok=True)
    _, frontier_count, _ = _prepare_full_candidate_frontier(
        preparation_root,
        budget_plan=verified.budget_plan,
        target_case_count=verified.target_case_count,
        cost_per_document_usd=verified.cost_per_document_usd,
        max_missing_core_documents_per_case=(
            verified.max_missing_core_documents_per_case
        ),
        snapshot_manifest_path=snapshot_manifest_path,
        preparation_config_path=preparation_config_path,
        frontier_path=frontier_path,
        resume=cast(bool, args.resume),
        additional_source_commitments={
            "preparation_summary_sha256": preparation_summary_path,
            "preparation_success_run_card_sha256": verified.success_run_card_path,
        },
        write=not dry_run,
    )
    _write_acquisition_completion(
        args,
        stage="materialize-target-cohort-frontier",
        input_paths=input_paths,
        output_paths=(frontier_path,),
        record_count=frontier_count,
        dry_run=dry_run,
        paid_activity_requested=False,
        paid_activity_executed=False,
        extra={
            "target_case_count": verified.target_case_count,
            "frontier_sha256": (_path_sha256(frontier_path) if not dry_run else None),
            "source_commitments": {
                "preparation_summary": _path_sha256(preparation_summary_path),
                "preparation_config": _path_sha256(preparation_config_path),
                "snapshot_manifest": _path_sha256(snapshot_manifest_path),
                "preparation_success_run_card": _path_sha256(
                    verified.success_run_card_path
                ),
            },
            "output_commitments": {
                "full_candidate_frontier": (
                    _path_sha256(frontier_path) if not dry_run else None
                )
            },
            "zero_provider_activity_evidence": True,
        },
    )
    return 0


def _verify_completed_preparation_for_frontier(
    *,
    preparation_root: Path,
    preparation_summary_path: Path,
    preparation_config_path: Path,
    snapshot_manifest_path: Path,
) -> _VerifiedPreparationForFrontier:
    summary = _read_json_object(preparation_summary_path)
    config = _read_json_object(preparation_config_path)
    snapshot_manifest = _read_json_object(snapshot_manifest_path)
    summary_schema = summary.get("schema_version")
    config_schema = config.get("schema_version")
    if not isinstance(summary_schema, str) or not isinstance(config_schema, str):
        raise CommandError("preparation schema versions must be strings")
    schema_pair = (summary_schema, config_schema)
    profile_by_schema = {
        (
            "legalforecast.target_100_preparation.v1",
            "legalforecast.target_100_config.v1",
        ): _TARGET_100_PREPARATION,
        (
            "legalforecast.target_cohort_preparation.v1",
            "legalforecast.target_cohort_config.v1",
        ): _TARGET_COHORT_PREPARATION,
    }
    profile = profile_by_schema.get(schema_pair)
    if profile is None:
        raise CommandError("unsupported or mismatched preparation schema pair")
    config_payload = dict(config)
    committed_config_sha256 = config_payload.pop("config_sha256", None)
    if committed_config_sha256 != _canonical_json_sha256(config_payload):
        raise CommandError("preparation config self-hash mismatch")
    if summary.get("config_sha256") != committed_config_sha256:
        raise CommandError("preparation summary config commitment mismatch")
    if (
        summary.get("dry_run") is not False
        or summary.get("paid_activity_executed") is not False
        or config.get("driver_execute") is not True
    ):
        raise CommandError(
            "frontier materialization requires executed nonpaid preparation"
        )
    target_case_count = _target_case_count_for_materialized_frontier(
        profile=profile,
        config=config,
        summary=summary,
    )
    expected_config_path = preparation_root / profile.config_filename
    if preparation_config_path.resolve() != expected_config_path.resolve():
        raise CommandError("preparation config is outside its canonical root path")
    wrapper_paths = config.get("wrapper_artifact_paths")
    if not isinstance(wrapper_paths, Mapping):
        raise CommandError("preparation config lacks wrapper artifact paths")
    typed_wrapper_paths = cast(Mapping[str, object], wrapper_paths)
    if typed_wrapper_paths.get("summary") != str(preparation_summary_path.resolve()):
        raise CommandError("preparation summary path differs from frozen config")
    configured_snapshot = config.get("snapshot")
    if not isinstance(configured_snapshot, str):
        raise CommandError("preparation config lacks snapshot path")
    authenticated_screened_value = config.get("authenticated_screened_cases")
    if not isinstance(authenticated_screened_value, str):
        raise CommandError("preparation config lacks authenticated screened-case input")
    authenticated_screened_cases = Path(authenticated_screened_value)
    if (
        snapshot_manifest_path.resolve()
        != (Path(configured_snapshot) / "manifest.json").resolve()
    ):
        raise CommandError("snapshot manifest path differs from frozen config")
    snapshot_sha256 = _path_sha256(snapshot_manifest_path)
    if (
        config.get("snapshot_manifest_sha256") != snapshot_sha256
        or summary.get("snapshot_manifest_sha256") != snapshot_sha256
        or config.get("snapshot_cycle_hash") != snapshot_manifest.get("cycle_hash")
        or config.get("snapshot_batch_digest") != snapshot_manifest.get("batch_digest")
        or summary.get("snapshot_batch_digest") != snapshot_manifest.get("batch_digest")
    ):
        raise CommandError("preparation snapshot lineage commitment mismatch")
    committed_inputs = summary.get("stage_input_commitments")
    committed_outputs = summary.get("stage_commitments")
    if not isinstance(committed_inputs, Mapping) or not isinstance(
        committed_outputs, Mapping
    ):
        raise CommandError("preparation summary lacks exhaustive stage commitments")
    expected_inputs, independent_inputs = _expected_preparation_input_commitments(
        preparation_root=preparation_root,
        config=config,
    )
    if dict(cast(Mapping[str, Any], committed_inputs)) != expected_inputs:
        raise CommandError(
            "preparation stage input commitment mismatch or non-exhaustive mapping"
        )
    verified_retarget_receipt: RetargetImportReceipt | None = None
    raw_retarget_lineage = config.get("retarget_import")
    if raw_retarget_lineage is not None:
        retarget_lineage = _mapping(
            raw_retarget_lineage, "retarget import config lineage"
        )
        verified_retarget_receipt = verify_retarget_import_receipt(
            Path(_required_str(retarget_lineage, "receipt_path")),
            source_root=Path(
                _required_str(retarget_lineage, "source_preparation_root")
            ),
            target_root=preparation_root,
        )
        if (
            summary.get("retarget_import_receipt_sha256")
            != verified_retarget_receipt.receipt_file_sha256
            or summary.get("retarget_import_receipt_self_hash")
            != verified_retarget_receipt.receipt_sha256
        ):
            raise CommandError("preparation retarget summary commitment mismatch")
    elif (
        "retarget_import_receipt_sha256" in summary
        or "retarget_import_receipt_self_hash" in summary
    ):
        raise CommandError("preparation has unexpected retarget summary commitment")
    actual_outputs = _target_100_stage_commitments(preparation_root)
    if dict(cast(Mapping[str, Any], committed_outputs)) != actual_outputs:
        raise CommandError(
            "preparation stage output commitment mismatch; mutated or unexpected "
            "stage artifact"
        )
    budget_path = preparation_root / "05-budget/missing-core-budget-plan.json"
    budget_record = _read_json_object(budget_path)
    budget_plan = _missing_core_budget_plan(budget_record)
    recomputed_budget = plan_missing_core_document_budget(
        (
            _core_document_filter_result(record)
            for record in _read_records(
                preparation_root / "04-core-filter/core-filter-results.jsonl"
            )
        ),
        dry_run=False,
        max_missing_core_documents_per_case=_required_int(
            config, "max_missing_core_documents_per_case"
        ),
        cost_per_document_usd=_required_str(config, "cost_per_document_usd"),
        max_projected_budget_usd=_required_str(config, "max_projected_budget_usd"),
        truncate_to_budget=True,
        target_case_count=target_case_count,
    )
    if budget_record != recomputed_budget.to_record():
        raise CommandError("preparation budget differs from canonical core-filter plan")
    budget_plan = recomputed_budget
    selected_ids = [plan.candidate_id for plan in budget_plan.case_plans]
    candidate_pool_size = len(_read_records(authenticated_screened_cases))
    raw_summary_budget_path = summary.get("budget_plan")
    if (
        not isinstance(raw_summary_budget_path, str)
        or Path(raw_summary_budget_path).resolve() != budget_path.resolve()
    ):
        raise CommandError("preparation summary budget path differs")
    if (
        len(selected_ids) != target_case_count
        or summary.get("selected_candidate_ids_sha256")
        != _canonical_json_sha256(selected_ids)
        or summary.get("frontier_sha256")
        != _canonical_json_sha256(
            [row.to_record() for row in budget_plan.frontier_rows]
        )
    ):
        raise CommandError(
            "preparation budget or selected frontier commitment mismatch"
        )
    if (
        summary.get("stage_commands") is None
        or _semantic_preparation_stage_commands(summary.get("stage_commands"))
        != config.get("stage_commands")
        or summary.get("paid_activity_requested") is not False
        or summary.get("budget_status") != "provisional_pre_clearance"
        or summary.get("next_stage") != "clear-disclosures"
        or summary.get("selected_case_count") != target_case_count
        or summary.get("candidate_pool_size") != candidate_pool_size
        or config.get("candidate_pool_size") != candidate_pool_size
        or summary.get("total_missing_core_documents")
        != budget_plan.total_missing_core_documents
        or summary.get("total_estimated_cost_usd")
        != budget_plan.total_estimated_cost_usd
        or summary.get("cost_per_document_usd") != budget_plan.cost_per_document_usd
        or summary.get("max_projected_budget_usd")
        != budget_plan.max_projected_budget_usd
        or summary.get("max_missing_core_documents_per_case")
        != budget_plan.max_missing_core_documents_per_case
    ):
        raise CommandError("preparation summary differs from frozen canonical plan")
    if profile.emit_full_candidate_frontier:
        _verify_generic_preparation_frontier(
            preparation_root=preparation_root,
            preparation_summary=summary,
            preparation_config_path=preparation_config_path,
            snapshot_manifest_path=snapshot_manifest_path,
        )
    raw_run_card_path = typed_wrapper_paths.get("run_card")
    if not isinstance(raw_run_card_path, str):
        raise CommandError("preparation config lacks success run-card path")
    success_run_card_path = Path(raw_run_card_path)
    if not _completed_stage_run_card_exists(success_run_card_path, stage=profile.stage):
        raise CommandError(
            "completed preparation success run card is missing or invalid"
        )
    success_card = _read_json_object(success_run_card_path)
    if (
        success_card.get("dry_run") is not False
        or success_card.get("execute") is not True
        or success_card.get("paid_activity_requested") is not False
        or success_card.get("paid_activity_executed") is not False
        or success_card.get("record_count") != target_case_count
        or success_card.get("config_sha256") != committed_config_sha256
        or success_card.get("selected_case_count") != target_case_count
        or success_card.get("total_estimated_cost_usd")
        != budget_plan.total_estimated_cost_usd
        or success_card.get("completed_stages") != list(actual_outputs)
        or success_card.get("zero_paid_activity_evidence") is not True
    ):
        raise CommandError("completed preparation success run card is inconsistent")
    if verified_retarget_receipt is not None:
        if (
            success_card.get("retarget_import_receipt_sha256")
            != verified_retarget_receipt.receipt_file_sha256
        ):
            raise CommandError("preparation retarget run-card commitment mismatch")
    elif "retarget_import_receipt_sha256" in success_card:
        raise CommandError("preparation has unexpected retarget run-card commitment")
    committed_output_paths = success_card.get("output_paths")
    if not isinstance(committed_output_paths, Sequence) or isinstance(
        committed_output_paths, (str, bytes)
    ):
        raise CommandError("preparation success run card lacks output paths")
    raw_output_paths = cast(Sequence[object], committed_output_paths)
    if any(not isinstance(path, str) for path in raw_output_paths):
        raise CommandError("preparation success run-card output paths are malformed")
    actual_output_paths = [
        Path(path).resolve() for path in cast(Sequence[str], raw_output_paths)
    ]
    required_output_paths = [
        preparation_config_path.resolve(),
        preparation_summary_path.resolve(),
        budget_path.resolve(),
    ]
    if actual_output_paths != required_output_paths:
        raise CommandError("preparation success run card output paths differ")
    raw_input_paths = success_card.get("input_paths")
    if not isinstance(raw_input_paths, Sequence) or isinstance(
        raw_input_paths, (str, bytes)
    ):
        raise CommandError("preparation success run card lacks input paths")
    expected_success_inputs = [Path(configured_snapshot).resolve()]
    if [
        Path(str(path)).resolve() for path in cast(Sequence[object], raw_input_paths)
    ] != expected_success_inputs:
        raise CommandError("preparation success run card input paths differ")
    wrapper_protected_paths = tuple(
        Path(value) for value in typed_wrapper_paths.values() if isinstance(value, str)
    )
    protected_paths = (
        preparation_root,
        preparation_summary_path,
        preparation_config_path,
        snapshot_manifest_path,
        Path(configured_snapshot),
        success_run_card_path,
        *wrapper_protected_paths,
        *(
            Path(path)
            for stage_paths in expected_inputs.values()
            for path in stage_paths
        ),
        *independent_inputs,
    )
    return _VerifiedPreparationForFrontier(
        target_case_count=target_case_count,
        cost_per_document_usd=_required_str(config, "cost_per_document_usd"),
        max_missing_core_documents_per_case=_required_int(
            config, "max_missing_core_documents_per_case"
        ),
        budget_plan=budget_plan,
        success_run_card_path=success_run_card_path,
        protected_paths=tuple(dict.fromkeys(protected_paths)),
    )


def _verify_completed_materializer_run_card(
    *,
    run_card_path: Path,
    frontier_path: Path,
    input_paths: Sequence[Path],
    target_case_count: int,
    preparation_summary_path: Path,
    preparation_config_path: Path,
    snapshot_manifest_path: Path,
    preparation_success_run_card_path: Path,
    expected_frontier_sha256: str,
    expected_frontier_count: int,
) -> None:
    if run_card_path.is_symlink() or not run_card_path.is_file():
        raise CommandError("completed materializer run card is not a regular file")
    card = _read_json_object(run_card_path)
    expected_inputs = [str(path) for path in input_paths]
    expected_outputs = [str(frontier_path)]
    expected_sources = {
        "preparation_summary": _path_sha256(preparation_summary_path),
        "preparation_config": _path_sha256(preparation_config_path),
        "snapshot_manifest": _path_sha256(snapshot_manifest_path),
        "preparation_success_run_card": _path_sha256(preparation_success_run_card_path),
    }
    if (
        card.get("schema_version") != "legalforecast.acquisition_run_card.v1"
        or card.get("stage") != "materialize-target-cohort-frontier"
        or card.get("status") != "completed"
        or card.get("dry_run") is not False
        or card.get("execute") is not True
        or card.get("paid_activity_requested") is not False
        or card.get("paid_activity_executed") is not False
        or card.get("record_count") != expected_frontier_count
        or card.get("target_case_count") != target_case_count
        or card.get("input_paths") != expected_inputs
        or card.get("output_paths") != expected_outputs
        or card.get("source_commitments") != expected_sources
        or card.get("zero_provider_activity_evidence") is not True
    ):
        raise CommandError("completed materializer run card contract mismatch")
    if frontier_path.is_symlink() or not frontier_path.is_file():
        raise CommandError("completed materializer frontier output is missing")
    frontier_sha256 = _path_sha256(frontier_path)
    if (
        frontier_sha256 != expected_frontier_sha256
        or card.get("frontier_sha256") != frontier_sha256
        or card.get("output_commitments")
        != {"full_candidate_frontier": frontier_sha256}
    ):
        raise CommandError("completed materializer frontier commitment mismatch")


def _verify_generic_preparation_frontier(
    *,
    preparation_root: Path,
    preparation_summary: Mapping[str, Any],
    preparation_config_path: Path,
    snapshot_manifest_path: Path,
) -> None:
    resolved_candidate_pool_size = len(
        _read_records(
            preparation_root / "03-gap-bridge/public-packet-selection-reconciled.jsonl"
        )
    )
    frontier_path = preparation_root / "05-budget/full-candidate-frontier.json"
    if frontier_path.is_symlink() or not frontier_path.is_file():
        raise CommandError("generic preparation full frontier is missing")
    frontier_sha256 = _path_sha256(frontier_path)
    raw_frontier_path = preparation_summary.get("full_candidate_frontier")
    if (
        not isinstance(raw_frontier_path, str)
        or Path(raw_frontier_path).resolve() != frontier_path.resolve()
        or preparation_summary.get("full_candidate_frontier_sha256") != frontier_sha256
        or preparation_summary.get("full_candidate_frontier_count")
        != resolved_candidate_pool_size
    ):
        raise CommandError("generic preparation full frontier summary mismatch")
    artifact = _read_json_object(frontier_path)
    candidates = _verified_target_cohort_frontier_rows(artifact)
    if len(candidates) != resolved_candidate_pool_size:
        raise CommandError("generic preparation full frontier count mismatch")
    policy = cast(Mapping[str, Any], artifact["policy"])
    expected_commitments = {
        "snapshot_manifest_sha256": _path_sha256(snapshot_manifest_path),
        "preparation_config_sha256": _path_sha256(preparation_config_path),
        "reconciled_selection_sha256": _path_sha256(
            preparation_root / "03-gap-bridge/public-packet-selection-reconciled.jsonl"
        ),
        "case_relevance_sha256": _path_sha256(
            preparation_root / "03-gap-bridge/case-relevance.jsonl"
        ),
        "download_manifest_sha256": _path_sha256(
            preparation_root / "03c-merged-downloads/document-downloads-merged.jsonl"
        ),
        "core_filter_results_sha256": _path_sha256(
            preparation_root / "04-core-filter/core-filter-results.jsonl"
        ),
        "provisional_budget_plan_sha256": _path_sha256(
            preparation_root / "05-budget/missing-core-budget-plan.json"
        ),
        "restriction_evidence_sha256": _path_sha256(
            preparation_root / "06-clearance-inputs/restriction-evidence.jsonl"
        ),
        "disclosure_review_requests_sha256": _path_sha256(
            preparation_root / "06-clearance-inputs/disclosure-review-requests.jsonl"
        ),
    }
    if policy.get("source_commitments") != expected_commitments:
        raise CommandError("generic preparation full frontier lineage mismatch")


def _target_case_count_for_materialized_frontier(
    *,
    profile: _TargetPreparationProfile,
    config: Mapping[str, Any],
    summary: Mapping[str, Any],
) -> int:
    config_count = config.get("target_case_count")
    summary_count = summary.get("target_case_count")
    if (
        not isinstance(summary_count, int)
        or isinstance(summary_count, bool)
        or summary_count < 1
    ):
        raise CommandError("preparation target case count is missing or invalid")
    if profile.exact_target_case_count is not None:
        exact_count = profile.exact_target_case_count
        if summary_count != exact_count or config_count != exact_count:
            raise CommandError("preparation target case count commitment mismatch")
        return exact_count
    if (
        not isinstance(config_count, int)
        or isinstance(config_count, bool)
        or config_count < 1
        or config_count != summary_count
    ):
        raise CommandError("preparation target case count commitment mismatch")
    return config_count


def _semantic_preparation_stage_commands(raw_commands: object) -> list[JsonRecord]:
    if not isinstance(raw_commands, Sequence) or isinstance(raw_commands, (str, bytes)):
        raise CommandError("preparation stage commands are malformed")
    commands: list[Mapping[str, Any]] = []
    for raw_command in cast(Sequence[object], raw_commands):
        if not isinstance(raw_command, Mapping):
            raise CommandError("preparation stage command is malformed")
        command = cast(Mapping[str, Any], raw_command)
        argv = command.get("argv")
        if (
            not isinstance(command.get("stage"), str)
            or not isinstance(argv, Sequence)
            or isinstance(argv, (str, bytes))
            or any(not isinstance(value, str) for value in cast(Sequence[object], argv))
        ):
            raise CommandError("preparation stage command is malformed")
        commands.append(command)
    return _semantic_target_100_stage_commands(commands)


def _frozen_preparation_flag_path(
    config: Mapping[str, Any], *, flag: str
) -> Path | None:
    commands = _semantic_preparation_stage_commands(config.get("stage_commands"))
    values: list[str] = []
    for command in commands:
        argv = cast(Sequence[str], command["argv"])
        for index, argument in enumerate(argv):
            if argument == flag:
                if index + 1 >= len(argv):
                    raise CommandError(f"frozen preparation flag lacks value: {flag}")
                values.append(argv[index + 1])
    if not values:
        return None
    unique_values = set(values)
    if len(unique_values) != 1:
        raise CommandError(f"frozen preparation flag is ambiguous: {flag}")
    return Path(unique_values.pop())


def _frozen_merge_candidate_selection_path(
    *, preparation_root: Path, config: Mapping[str, Any]
) -> Path | None:
    """Return the exact reconciled selection frozen into the merge command."""

    candidate_selection = _frozen_preparation_flag_path(
        config,
        flag="--candidate-selection",
    )
    if candidate_selection is None:
        return None
    expected_candidate_selection = Path(
        os.path.abspath(
            preparation_root / "03-gap-bridge/public-packet-selection-reconciled.jsonl"
        )
    )
    lexical_candidate_selection = Path(os.path.abspath(candidate_selection))
    if lexical_candidate_selection != expected_candidate_selection:
        raise CommandError(
            "frozen merge candidate selection is outside the preparation root"
        )
    _read_singly_linked_regular_input(
        candidate_selection,
        label="frozen merge candidate selection",
    )
    return expected_candidate_selection


def _expected_preparation_input_commitments(
    *,
    preparation_root: Path,
    config: Mapping[str, Any],
) -> tuple[JsonRecord, tuple[Path, ...]]:
    snapshot_value = config.get("snapshot")
    if not isinstance(snapshot_value, str):
        raise CommandError("preparation config lacks snapshot path")
    snapshot = Path(snapshot_value)
    authenticated_screened_value = config.get("authenticated_screened_cases")
    if not isinstance(authenticated_screened_value, str):
        raise CommandError("preparation config lacks authenticated screened-case input")
    authenticated_screened_cases = Path(authenticated_screened_value)
    screened_cases_sha256 = config.get("screened_cases_sha256")
    if (
        not isinstance(screened_cases_sha256, str)
        or re.fullmatch(r"sha256:[0-9a-f]{64}", screened_cases_sha256) is None
    ):
        raise CommandError("preparation config lacks screened-case SHA-256")
    raw_html_value = config.get("raw_html_dir")
    raw_manifest_value = config.get("authenticated_raw_html_manifest")
    raw_manifest_sha256 = config.get("authenticated_raw_html_manifest_sha256")
    raw_values = (raw_html_value, raw_manifest_value, raw_manifest_sha256)
    if any(value is not None for value in raw_values) and (
        not isinstance(raw_html_value, str)
        or not isinstance(raw_manifest_value, str)
        or not isinstance(raw_manifest_sha256, str)
        or re.fullmatch(r"sha256:[0-9a-f]{64}", raw_manifest_sha256) is None
    ):
        raise CommandError(
            "preparation config has incomplete authenticated raw-HTML commitments"
        )
    authenticated_input_commitments = _verified_target_authenticated_paths(
        screened_cases=authenticated_screened_cases,
        screened_cases_sha256=screened_cases_sha256[7:],
        raw_html_dir=(
            Path(raw_html_value) if isinstance(raw_html_value, str) else None
        ),
        raw_html_manifest=(
            Path(raw_manifest_value) if isinstance(raw_manifest_value, str) else None
        ),
        raw_html_manifest_sha256=(
            raw_manifest_sha256[7:] if isinstance(raw_manifest_sha256, str) else None
        ),
    )
    bridge_route_commitments = _verified_target_bridge_route_commitments(
        preparation_root
    )
    paths: dict[str, tuple[Path, ...]] = {
        "01-public-plan": (
            snapshot / "manifest.json",
            authenticated_screened_cases,
        ),
        "02-free-download": (
            preparation_root / "01-public-plan/free-document-requests.jsonl",
        ),
        "03-gap-bridge": (
            authenticated_screened_cases,
            preparation_root / "01-public-plan/public-packet-selection.jsonl",
            preparation_root / "01-public-plan/public-packet-paid-gaps.jsonl",
            preparation_root / "02-free-download/free-document-downloads.jsonl",
        ),
        "04-core-filter": (preparation_root / "03-gap-bridge/case-relevance.jsonl",),
        "03b-bridge-free-download": (
            preparation_root / "03-gap-bridge/pacer-gap-free-document-requests.jsonl",
        ),
        "03c-merged-downloads": (
            preparation_root / "02-free-download/free-document-downloads.jsonl",
            preparation_root / "03b-bridge-free-download/free-document-downloads.jsonl",
        ),
        "05-budget": (preparation_root / "04-core-filter/core-filter-results.jsonl",),
        "06-clearance-inputs": (
            preparation_root / "03-gap-bridge/case-relevance.jsonl",
            preparation_root / "03c-merged-downloads/document-downloads-merged.jsonl",
        ),
    }
    candidate_selection = _frozen_merge_candidate_selection_path(
        preparation_root=preparation_root,
        config=config,
    )
    if candidate_selection is not None:
        paths["03c-merged-downloads"] += (candidate_selection,)
    independent_inputs: list[Path] = []
    courtlistener_fixture = _frozen_preparation_flag_path(
        config, flag="--courtlistener-fixture"
    )
    expected_courtlistener_sha256 = config.get("courtlistener_fixture_sha256")
    if courtlistener_fixture is not None:
        if _path_sha256(courtlistener_fixture) != expected_courtlistener_sha256:
            raise CommandError("frozen CourtListener fixture commitment mismatch")
        paths["03-gap-bridge"] += (courtlistener_fixture,)
        independent_inputs.append(courtlistener_fixture)
    elif expected_courtlistener_sha256 is not None:
        raise CommandError("frozen CourtListener fixture path is missing")
    fixture_documents = _frozen_preparation_flag_path(
        config, flag="--fixture-documents"
    )
    expected_fixture_sha256 = config.get("fixture_documents_sha256")
    if fixture_documents is not None:
        if _path_sha256(fixture_documents) != expected_fixture_sha256:
            raise CommandError("frozen fixture-document commitment mismatch")
        independent_inputs.append(fixture_documents)
    elif expected_fixture_sha256 is not None:
        raise CommandError("frozen fixture-document path is missing")
    for key in ("request_ledger",):
        value = config.get(key)
        if isinstance(value, str):
            independent_inputs.append(Path(value))
    expected = {
        stage: {str(path.resolve()): _path_sha256(path) for path in stage_paths}
        for stage, stage_paths in paths.items()
    }
    expected["01-public-plan"].update(authenticated_input_commitments)
    expected["03-gap-bridge"].update(authenticated_input_commitments)
    expected["03-gap-bridge"].update(bridge_route_commitments)
    retarget_commitments = _verified_retarget_final_input_commitments(
        output_root=preparation_root,
        frozen_config=config,
    )
    if retarget_commitments:
        expected["retarget-import"] = retarget_commitments
        source_root = Path(
            _required_str(
                _mapping(config.get("retarget_import"), "retarget import lineage"),
                "source_preparation_root",
            )
        )
        independent_inputs.append(source_root)
    return expected, tuple(independent_inputs)


def _completed_stage_run_card_exists(path: Path, *, stage: str) -> bool:
    if path.is_symlink() or not path.is_file():
        return False
    card = _read_json_object(path)
    return (
        card.get("schema_version") == "legalforecast.acquisition_run_card.v1"
        and card.get("stage") == stage
        and card.get("status") == "completed"
    )


def _validate_materializer_output_paths(
    args: argparse.Namespace,
    *,
    output_root: Path,
    frontier_path: Path,
    input_paths: Sequence[Path],
) -> None:
    _validate_projection_output_scope(output_root, input_paths=input_paths)
    writable_paths = (
        frontier_path,
        _acquisition_path(
            args,
            "run_card_output",
            output_root / "run-cards/materialize-target-cohort-frontier.json",
        ),
        _acquisition_path(
            args,
            "log_output",
            output_root / "logs/materialize-target-cohort-frontier.jsonl",
        ),
    )
    resolved_inputs = tuple(path.resolve() for path in input_paths)
    for index, path in enumerate(writable_paths):
        resolved = path.resolve()
        _reject_hardlinked_writable_replay_scope(
            label="materialize-target-cohort-frontier output",
            path=resolved,
            is_tree=False,
        )
        for source in resolved_inputs:
            if _replay_scopes_overlap(
                left_label="materialize-target-cohort-frontier output",
                left=resolved,
                left_tree=False,
                right_label="immutable preparation input",
                right=source,
                right_tree=source.is_dir(),
            ):
                raise CommandError(
                    "materialize-target-cohort-frontier output overlaps immutable input"
                )
        for other in writable_paths[index + 1 :]:
            if _replay_scopes_overlap(
                left_label="materialize-target-cohort-frontier output",
                left=resolved,
                left_tree=False,
                right_label="materialize-target-cohort-frontier output",
                right=other.resolve(),
                right_tree=False,
            ):
                raise CommandError("materialize-target-cohort-frontier outputs alias")


def _prepare_target_100_clearance_inputs(
    output_root: Path,
    *,
    resume: bool,
) -> None:
    relevance = _read_records(output_root / "03-gap-bridge/case-relevance.jsonl")
    manifest = _read_records(
        output_root / "03c-merged-downloads/document-downloads-merged.jsonl"
    )
    try:
        manifest_keys = _unique_frontier_document_keys(
            manifest,
            label="free document manifest",
        )
    except ValueError as exc:
        raise CommandError(
            "free document manifest contains an invalid document key"
        ) from exc
    restrictions = restriction_evidence_from_case_relevance(
        relevance,
        document_keys=manifest_keys,
        allow_unknown=True,
    )
    restriction_index = {
        (
            cast(str, row["candidate_id"]),
            cast(str, row["source_document_id"]),
        ): row
        for row in restrictions
    }
    missing = sorted(manifest_keys - set(restriction_index))
    if missing:
        raise CommandError(
            "free document lacks case-relevance restriction evidence: "
            + ", ".join(f"{candidate}/{document}" for candidate, document in missing)
        )
    exact_restrictions = tuple(restriction_index[key] for key in sorted(manifest_keys))
    manifest_index = {
        (cast(str, row["candidate_id"]), cast(str, row["source_document_id"])): row
        for row in manifest
    }
    review_requests: list[JsonRecord] = []
    for candidate_id, document_id in sorted(manifest_keys):
        manifest_record = manifest_index[(candidate_id, document_id)]
        sha256 = _required_str(manifest_record, "sha256")
        if re.fullmatch(r"[0-9a-f]{64}", sha256) is None:
            raise CommandError(
                "free document manifest has invalid sha256: "
                f"{candidate_id}/{document_id}"
            )
        byte_count = _required_int(manifest_record, "byte_count")
        if byte_count < 0:
            raise CommandError(
                "free document manifest has negative byte_count: "
                f"{candidate_id}/{document_id}"
            )
        free_or_purchased = _required_str(manifest_record, "free_or_purchased")
        if free_or_purchased not in {"free", "purchased"}:
            raise CommandError(
                "free document manifest has invalid free_or_purchased: "
                f"{candidate_id}/{document_id}"
            )
        review_requests.append(
            {
                "schema_version": "legalforecast.disclosure_review_request.v1",
                "candidate_id": candidate_id,
                "source_document_id": document_id,
                "sha256": sha256,
                "byte_count": byte_count,
                "free_or_purchased": free_or_purchased,
                "restriction_status": restriction_index[(candidate_id, document_id)][
                    "restriction_status"
                ],
                "restriction_evidence": restriction_index[(candidate_id, document_id)][
                    "restriction_evidence"
                ],
                "required_human_decision": "cleared_or_quarantined",
            }
        )
    clearance_root = output_root / "06-clearance-inputs"
    _ensure_projection_artifact(
        clearance_root / "restriction-evidence.jsonl",
        _projection_jsonl_bytes(exact_restrictions),
        resume=resume,
    )
    _ensure_projection_artifact(
        clearance_root / "disclosure-review-requests.jsonl",
        _projection_jsonl_bytes(review_requests),
        resume=resume,
    )


def _prepare_full_candidate_frontier(
    output_root: Path,
    *,
    budget_plan: MissingCoreBudgetPlan,
    target_case_count: int,
    cost_per_document_usd: str,
    max_missing_core_documents_per_case: int,
    snapshot_manifest_path: Path,
    snapshot_manifest_sha256: str | None = None,
    preparation_config_path: Path,
    frontier_path: Path,
    resume: bool,
    additional_source_commitments: Mapping[str, Path] | None = None,
    write: bool = True,
) -> tuple[Path, int, str]:
    """Freeze every ranked candidate without changing the provisional plan."""

    selection_path = (
        output_root / "03-gap-bridge/public-packet-selection-reconciled.jsonl"
    )
    case_relevance_path = output_root / "03-gap-bridge/case-relevance.jsonl"
    download_manifest_path = (
        output_root / "03c-merged-downloads/document-downloads-merged.jsonl"
    )
    filter_path = output_root / "04-core-filter/core-filter-results.jsonl"
    budget_path = output_root / "05-budget/missing-core-budget-plan.json"
    restriction_evidence_path = (
        output_root / "06-clearance-inputs/restriction-evidence.jsonl"
    )
    disclosure_requests_path = (
        output_root / "06-clearance-inputs/disclosure-review-requests.jsonl"
    )
    selections = _read_records(selection_path)
    case_relevance_records = _read_records(case_relevance_path)
    download_manifest_records = _read_records(download_manifest_path)
    restriction_records = _read_records(restriction_evidence_path)
    disclosure_request_records = _read_records(disclosure_requests_path)
    filter_records = _read_records(filter_path)
    selection_index: dict[str, JsonRecord] = {}
    for record in selections:
        candidate_id = _required_str(record, "candidate_id")
        if candidate_id in selection_index:
            raise CommandError(
                f"full candidate frontier has duplicate selection: {candidate_id}"
            )
        selection_index[candidate_id] = record
    ranked_plans = rank_missing_core_document_plans(
        (_core_document_filter_result(record) for record in filter_records),
        dry_run=False,
        max_missing_core_documents_per_case=max_missing_core_documents_per_case,
        cost_per_document_usd=cost_per_document_usd,
    )
    ranked_ids = [plan.candidate_id for plan in ranked_plans]
    if len(ranked_ids) != len(set(ranked_ids)):
        raise CommandError("full candidate frontier contains duplicate candidate IDs")
    selection_ids = set(selection_index)
    ranked_id_set = set(ranked_ids)
    if selection_ids != ranked_id_set:
        missing = sorted(selection_ids - ranked_id_set)
        extra = sorted(ranked_id_set - selection_ids)
        raise CommandError(
            "full candidate frontier does not reconcile resolved selection; "
            f"missing={missing}; extra={extra}"
        )
    relevance_ids = _unique_frontier_candidate_ids(
        case_relevance_records, label="case relevance"
    )
    if relevance_ids != selection_ids:
        raise CommandError(
            "full candidate frontier case relevance does not reconcile resolved "
            f"selection; missing={sorted(selection_ids - relevance_ids)}; "
            f"extra={sorted(relevance_ids - selection_ids)}"
        )
    manifest_keys = _unique_frontier_document_keys(
        download_manifest_records, label="download manifest"
    )
    orphan_manifest_candidates = sorted(
        {candidate_id for candidate_id, _ in manifest_keys} - selection_ids
    )
    if orphan_manifest_candidates:
        raise CommandError(
            "full candidate frontier rejects orphan download-manifest candidates: "
            + ", ".join(orphan_manifest_candidates)
        )
    restriction_keys = _unique_frontier_document_keys(
        restriction_records, label="restriction evidence"
    )
    request_keys = _unique_frontier_document_keys(
        disclosure_request_records, label="disclosure review requests"
    )
    if restriction_keys != manifest_keys or request_keys != manifest_keys:
        raise CommandError(
            "full candidate frontier clearance inputs do not exactly reconcile "
            "the download manifest"
        )
    selected_ids = {plan.candidate_id for plan in budget_plan.case_plans}
    candidates: list[JsonRecord] = []
    for rank, plan in enumerate(ranked_plans, start=1):
        selection = selection_index[plan.candidate_id]
        if plan.exclusion_reasons:
            selection_status = "excluded"
        elif plan.candidate_id in selected_ids:
            selection_status = "selected"
        else:
            selection_status = "eligible_omitted"
        candidates.append(
            {
                "rank": rank,
                "candidate_id": plan.candidate_id,
                "purchase_document_ids": list(plan.purchase_document_ids),
                "missing_core_document_count": plan.missing_core_document_count,
                "estimated_purchase_count": plan.estimated_purchase_count,
                "missing_core_roles": list(plan.missing_core_roles),
                "estimated_cost_usd": plan.estimated_cost_usd,
                "exclusion_reasons": list(plan.exclusion_reasons),
                "court": _optional_str(selection, "court"),
                "nos_macro_category": _optional_str(selection, "nos_macro_category"),
                "related_family_id": _optional_str(selection, "related_family_id"),
                "mdl_family_id": _optional_str(selection, "mdl_family_id"),
                "selection_status": selection_status,
            }
        )
    source_commitments = {
        "snapshot_manifest_sha256": (
            "sha256:" + snapshot_manifest_sha256
            if snapshot_manifest_sha256 is not None
            else _path_sha256(snapshot_manifest_path)
        ),
        "preparation_config_sha256": _path_sha256(preparation_config_path),
        "reconciled_selection_sha256": _path_sha256(selection_path),
        "case_relevance_sha256": _path_sha256(case_relevance_path),
        "download_manifest_sha256": _path_sha256(download_manifest_path),
        "core_filter_results_sha256": _path_sha256(filter_path),
        "provisional_budget_plan_sha256": _path_sha256(budget_path),
        "restriction_evidence_sha256": _path_sha256(restriction_evidence_path),
        "disclosure_review_requests_sha256": _path_sha256(disclosure_requests_path),
    }
    if additional_source_commitments is not None:
        for name, path in sorted(additional_source_commitments.items()):
            if name in source_commitments:
                raise CommandError(
                    f"duplicate full-frontier source commitment name: {name}"
                )
            source_commitments[name] = _path_sha256(path)
    policy: JsonRecord = {
        "target_case_count": target_case_count,
        "candidate_count": len(candidates),
        "selected_candidate_count": len(selected_ids),
        "frontier_truncated": False,
        "source_commitments": source_commitments,
        "clearance_contract": {
            "run_card_schema_version": "legalforecast.acquisition_run_card.v1",
            "stage": "clear-disclosures",
            "required_status": "completed",
            "required_dry_run": False,
            "required_execute": True,
            "required_paid_activity_executed": False,
            "download_manifest_sha256": _path_sha256(download_manifest_path),
            "restriction_evidence_sha256": _path_sha256(restriction_evidence_path),
            "required_source_commitments": [
                "download_manifest",
                "restriction_evidence",
                "reviews",
                "review_receipt",
            ],
            "required_output_commitments": ["disclosure_clearance"],
            "required_review_authority_fields": [
                "reviewer_id",
                "controlled_store_uri",
                "authentication_method",
                "authenticated_at",
                "review_artifact_sha256",
            ],
            "orphan_clearance_rows_allowed": False,
        },
        "candidates": candidates,
    }
    artifact: JsonRecord = {
        "schema_version": "legalforecast.target_cohort_candidate_frontier.v1",
        "policy": policy,
        "policy_sha256": _canonical_json_sha256(policy),
    }
    payload = _projection_json_bytes(artifact)
    if write:
        _ensure_projection_artifact(
            frontier_path,
            payload,
            resume=resume,
        )
    return frontier_path, len(candidates), _bytes_sha256(payload)


def _unique_frontier_candidate_ids(
    records: Sequence[Mapping[str, Any]], *, label: str
) -> set[str]:
    candidate_ids: list[str] = [
        _required_str(record, "candidate_id") for record in records
    ]
    if len(candidate_ids) != len(set(candidate_ids)):
        raise CommandError(f"full candidate frontier has duplicate {label} candidate")
    return set(candidate_ids)


def _unique_frontier_document_keys(
    records: Sequence[Mapping[str, Any]], *, label: str
) -> set[tuple[str, str]]:
    keys = [
        (
            _required_str(record, "candidate_id"),
            _required_str(record, "source_document_id"),
        )
        for record in records
    ]
    if len(keys) != len(set(keys)):
        raise CommandError(f"full candidate frontier has duplicate {label} document")
    return set(keys)


def _verify_replacement_projection_replay(
    *,
    source_paths: Mapping[str, Path],
    source_bytes: Mapping[str, bytes],
    controlled_private_root: Path,
    purchase_ledger_path: Path,
) -> JsonRecord:
    """Replay the complete approved-v2 replacement authority for a projection."""

    replacement_result = _projection_json_object(
        source_bytes["replacement_result"],
        source=source_paths["replacement_result"],
    )
    replacement_policy_artifact = _projection_json_object(
        source_bytes["replacement_replay_purchase_policy"],
        source=source_paths["replacement_replay_purchase_policy"],
    )
    replacement_policy = verify_case_dev_purchase_policy(replacement_policy_artifact)
    replacement_cohort_policy = _projection_json_object(
        source_bytes["replacement_replay_cohort_policy"],
        source=source_paths["replacement_replay_cohort_policy"],
    )
    replacement_frontier = _projection_json_object(
        source_bytes["replacement_replay_frontier"],
        source=source_paths["replacement_replay_frontier"],
    )
    replacement_clearance = _verify_replacement_clearance_evidence(
        clearance_bytes=source_bytes["replacement_replay_purchased_clearance"],
        clearance_path=source_paths["replacement_replay_purchased_clearance"],
        run_card_bytes=source_bytes["replacement_replay_clearance_run_card"],
        run_card_path=source_paths["replacement_replay_clearance_run_card"],
    )
    replacement_tranche_selection = _projection_jsonl_records(
        source_bytes["replacement_replay_tranche_selection"],
        source=source_paths["replacement_replay_tranche_selection"],
    )
    with CaseDevPurchaseJournal(
        purchase_ledger_path.resolve(),
        policy=replacement_policy,
        read_only=True,
        controlled_private_root=controlled_private_root,
        initialization_receipt_path=source_paths[
            "replacement_replay_purchase_ledger_initialization_receipt"
        ],
    ) as journal:
        replayed_plan = plan_clearance_replacements(
            cohort_policy_artifact=replacement_cohort_policy,
            purchase_policy_artifact=replacement_policy_artifact,
            frontier_artifact=replacement_frontier,
            purchase_journal=journal,
            purchased_clearance_records=replacement_clearance,
            clearance_run_card_sha256=_bytes_sha256(
                source_bytes["replacement_replay_clearance_run_card"]
            ),
            controlled_private_root=controlled_private_root,
        )
    if replayed_plan.replacement_plan.case_plans:
        raise ClearanceReplacementError(
            "replacement reprojection requires a terminal replacement plan"
        )
    replayed_result = bind_replacement_selection_outputs(
        replayed_plan,
        active_selection_sha256=_bytes_sha256(source_bytes["selection"]),
        active_selection_count=len(replayed_plan.active_candidate_ids),
        replacement_selection_sha256=_bytes_sha256(
            source_bytes["replacement_replay_tranche_selection"]
        ),
        replacement_selection_count=len(replacement_tranche_selection),
    )
    verify_bound_active_selection(
        replacement_result,
        active_selection_bytes=source_bytes["selection"],
        replayed_result=replayed_result,
    )
    return replacement_result


def _cmd_acquisition_project_target_cohort(args: argparse.Namespace) -> int:
    """Freeze exact post-clearance artifacts from the resolved candidate pool."""

    output_root = cast(Path, args.output_root)
    replacement_result_path = cast(Path | None, args.replacement_result)
    replacement_replay_arguments = {
        "replacement_replay_cohort_policy": cast(
            Path | None, args.replacement_replay_cohort_policy
        ),
        "replacement_replay_purchase_policy": cast(
            Path | None, args.replacement_replay_purchase_policy
        ),
        "replacement_replay_controlled_private_root": cast(
            Path | None, args.replacement_replay_controlled_private_root
        ),
        "replacement_replay_frontier": cast(
            Path | None, args.replacement_replay_frontier
        ),
        "replacement_replay_purchase_ledger": cast(
            Path | None, args.replacement_replay_purchase_ledger
        ),
        "replacement_replay_purchase_ledger_initialization_receipt": cast(
            Path | None,
            args.replacement_replay_purchase_ledger_initialization_receipt,
        ),
        "replacement_replay_purchased_clearance": cast(
            Path | None, args.replacement_replay_purchased_clearance
        ),
        "replacement_replay_clearance_run_card": cast(
            Path | None, args.replacement_replay_clearance_run_card
        ),
        "replacement_replay_tranche_selection": cast(
            Path | None, args.replacement_replay_tranche_selection
        ),
    }
    supplied_replay_arguments = {
        name: path
        for name, path in replacement_replay_arguments.items()
        if path is not None
    }
    if replacement_result_path is None and supplied_replay_arguments:
        raise CommandError("replacement replay evidence requires --replacement-result")
    if replacement_result_path is not None and len(supplied_replay_arguments) != len(
        replacement_replay_arguments
    ):
        missing = sorted(
            name for name, path in replacement_replay_arguments.items() if path is None
        )
        raise CommandError(
            "replacement reprojection requires complete authenticated replay "
            "evidence: " + ", ".join(missing)
        )
    source_paths = {
        "selection": cast(Path, args.selection),
        "case_relevance": cast(Path, args.case_relevance),
        "download_manifest": cast(Path, args.download_manifest),
        "disclosure_clearance": cast(Path, args.disclosure_clearance),
        "clearance_run_card": cast(Path, args.clearance_run_card),
        "restriction_evidence": cast(Path, args.restriction_evidence),
        "preparation_summary": cast(Path, args.preparation_summary),
        "preparation_config": cast(Path, args.preparation_config),
        "snapshot_manifest": cast(Path, args.snapshot_manifest),
    }
    if replacement_result_path is not None:
        source_paths["replacement_result"] = replacement_result_path
        for name in (
            "replacement_replay_cohort_policy",
            "replacement_replay_purchase_policy",
            "replacement_replay_frontier",
            "replacement_replay_purchase_ledger_initialization_receipt",
            "replacement_replay_purchased_clearance",
            "replacement_replay_clearance_run_card",
            "replacement_replay_tranche_selection",
        ):
            source_paths[name] = cast(Path, replacement_replay_arguments[name])
    replay_context_paths = tuple(
        cast(Path, replacement_replay_arguments[name])
        for name in (
            "replacement_replay_controlled_private_root",
            "replacement_replay_purchase_ledger",
        )
        if replacement_replay_arguments[name] is not None
    )
    input_paths = (*source_paths.values(), *replay_context_paths)
    _validate_projection_output_scope(output_root, input_paths=input_paths)
    source_bytes = {
        name: _read_singly_linked_regular_input(path, label=name)
        for name, path in source_paths.items()
    }
    source_sha256 = {
        name: _bytes_sha256(payload) for name, payload in source_bytes.items()
    }
    preparation_summary = _projection_json_object(
        source_bytes["preparation_summary"],
        source=source_paths["preparation_summary"],
    )
    preparation_config = _projection_json_object(
        source_bytes["preparation_config"],
        source=source_paths["preparation_config"],
    )
    snapshot_manifest = _projection_json_object(
        source_bytes["snapshot_manifest"],
        source=source_paths["snapshot_manifest"],
    )
    clearance_run_card = _projection_json_object(
        source_bytes["clearance_run_card"],
        source=source_paths["clearance_run_card"],
    )
    _projection_jsonl_records(
        source_bytes["restriction_evidence"],
        source=source_paths["restriction_evidence"],
    )
    replacement_selection_authorized = False
    replacement_result: JsonRecord | None = None
    if replacement_result_path is not None:
        try:
            replacement_result = _verify_replacement_projection_replay(
                source_paths=source_paths,
                source_bytes=source_bytes,
                controlled_private_root=cast(
                    Path,
                    replacement_replay_arguments[
                        "replacement_replay_controlled_private_root"
                    ],
                ),
                purchase_ledger_path=cast(
                    Path,
                    replacement_replay_arguments["replacement_replay_purchase_ledger"],
                ),
            )
        except (
            CaseDevPurchaseLedgerError,
            CaseDevPurchasePolicyError,
            ClearanceReplacementError,
            OSError,
            ValueError,
        ) as exc:
            raise CommandError(str(exc)) from exc
        replacement_selection_authorized = True
    _validate_projection_source_commitments(
        preparation_summary=preparation_summary,
        preparation_config=preparation_config,
        snapshot_manifest=snapshot_manifest,
        clearance_run_card=clearance_run_card,
        source_paths=source_paths,
        source_sha256=source_sha256,
        target_case_count=cast(int, args.target_case_count),
        cost_per_document_usd=cast(str, args.cost_per_document_usd),
        max_projected_budget_usd=cast(str, args.max_projected_budget_usd),
        max_missing_core_documents_per_case=cast(
            int, args.max_missing_core_documents_per_case
        ),
        replacement_selection_authorized=replacement_selection_authorized,
    )
    clearance_snapshot = _capture_clearance_artifact_snapshot(
        run_card=clearance_run_card,
        run_card_path=source_paths["clearance_run_card"],
        clearance_path=source_paths["disclosure_clearance"],
        initial_artifact_bytes={
            os.path.abspath(path): source_bytes[name]
            for name, path in source_paths.items()
        },
    )
    _verify_authenticated_clearance_run_card(
        clearance_path=source_paths["disclosure_clearance"],
        clearance_run_card_path=source_paths["clearance_run_card"],
        expected_download_manifest_path=source_paths["download_manifest"],
        expected_restriction_path=source_paths["restriction_evidence"],
        captured_artifact_bytes=clearance_snapshot,
    )
    try:
        projection = project_target_cohort(
            selections=_projection_jsonl_records(
                source_bytes["selection"], source=source_paths["selection"]
            ),
            case_relevance=_projection_jsonl_records(
                source_bytes["case_relevance"],
                source=source_paths["case_relevance"],
            ),
            download_manifest=_projection_jsonl_records(
                source_bytes["download_manifest"],
                source=source_paths["download_manifest"],
            ),
            clearance_records=_projection_jsonl_records(
                source_bytes["disclosure_clearance"],
                source=source_paths["disclosure_clearance"],
            ),
            target_case_count=cast(int, args.target_case_count),
            cost_per_document_usd=cast(str, args.cost_per_document_usd),
            max_projected_budget_usd=cast(str, args.max_projected_budget_usd),
            max_missing_core_documents_per_case=cast(
                int,
                args.max_missing_core_documents_per_case,
            ),
        )
    except TargetCohortProjectionError as exc:
        raise CommandError(str(exc)) from exc

    manifest_records = projection.download_manifest
    free_manifest = tuple(
        record
        for record in manifest_records
        if record.get("free_or_purchased") == "free"
    )
    purchased_manifest = tuple(
        record
        for record in manifest_records
        if record.get("free_or_purchased") == "purchased"
    )
    if len(free_manifest) + len(purchased_manifest) != len(manifest_records):
        raise CommandError(
            "projected manifest contains an invalid free_or_purchased value"
        )

    output_records: dict[Path, bytes] = {
        output_root / "target-cohort-selection.jsonl": _projection_jsonl_bytes(
            projection.selections
        ),
        output_root / "case-relevance.jsonl": _projection_jsonl_bytes(
            projection.case_relevance
        ),
        output_root / "free-document-downloads.jsonl": _projection_jsonl_bytes(
            free_manifest
        ),
        output_root / "purchased-document-downloads.jsonl": (
            _projection_jsonl_bytes(purchased_manifest)
        ),
        output_root / "document-downloads-merged.jsonl": _projection_jsonl_bytes(
            manifest_records
        ),
        output_root / "disclosure-clearance.jsonl": _projection_jsonl_bytes(
            projection.clearance_records
        ),
        output_root / "restriction-evidence.jsonl": _projection_jsonl_bytes(
            projection.restriction_evidence
        ),
        output_root / "core-filter-results.jsonl": _projection_jsonl_bytes(
            tuple(row.to_record() for row in projection.core_filter_results)
        ),
        output_root / "target-cohort-exclusions.jsonl": _projection_jsonl_bytes(
            projection.exclusions
        ),
        output_root / "missing-core-budget-plan.json": _projection_json_bytes(
            projection.budget_plan.to_record()
        ),
        output_root / "target-cohort-ranked-reserve.jsonl": (
            _projection_jsonl_bytes(projection.ranked_reserve)
        ),
    }
    summary = dict(projection.summary)
    summary.update(
        {
            "snapshot_cycle_hash": snapshot_manifest["cycle_hash"],
            "snapshot_batch_digest": snapshot_manifest["batch_digest"],
            "preparation_summary_sha256": source_sha256["preparation_summary"],
            "preparation_config_sha256": source_sha256["preparation_config"],
            "snapshot_manifest_sha256": source_sha256["snapshot_manifest"],
            "clearance_run_card_sha256": source_sha256["clearance_run_card"],
            "input_commitments": {
                str(path.resolve()): source_sha256[name]
                for name, path in source_paths.items()
            },
            "output_commitments": {
                str(path.relative_to(output_root)): "sha256:"
                + hashlib.sha256(payload).hexdigest()
                for path, payload in sorted(
                    output_records.items(),
                    key=lambda item: str(item[0]),
                )
            },
            "next_stage": "generate-recap-fetch-broker-policy",
            "next_stage_blocked_until": (
                "explicit human approval of this post-clearance budget and the "
                "bounded signed RECAP Fetch broker deployment"
            ),
        }
    )
    summary_path = output_root / "target-cohort-projection.json"
    output_records[summary_path] = _projection_json_bytes(summary)

    dry_run = _acquisition_dry_run(args)
    completion_extra = {
        "selected_case_count": len(projection.selected_candidate_ids),
        "excluded_case_count": len(projection.exclusions),
        "projection_sha256": projection.summary["projection_sha256"],
        "total_estimated_cost_usd": (projection.budget_plan.total_estimated_cost_usd),
        "output_commitments": {
            str(path): _bytes_sha256(payload)
            for path, payload in output_records.items()
        },
    }
    if replacement_result is not None:
        completion_extra.update(
            {
                "active_selection_sha256": source_sha256["selection"],
                "active_selection_count": replacement_result["active_selection_count"],
                "replacement_result_sha256": source_sha256["replacement_result"],
            }
        )
    if not dry_run:
        if _completed_disclosure_review_resume(
            args,
            stage="project-target-cohort",
            input_paths=input_paths,
            output_paths=tuple(output_records),
            record_count=len(projection.selected_candidate_ids),
            expected_extra=completion_extra,
        ):
            for path, payload in output_records.items():
                _ensure_projection_artifact(path, payload, resume=True)
            return 0
        for path, payload in output_records.items():
            _ensure_projection_artifact(
                path,
                payload,
                resume=cast(bool, args.resume),
            )
    _write_acquisition_completion(
        args,
        stage="project-target-cohort",
        input_paths=input_paths,
        output_paths=tuple(output_records),
        record_count=len(projection.selected_candidate_ids),
        dry_run=dry_run,
        paid_activity_requested=False,
        paid_activity_executed=False,
        extra=completion_extra,
        resumable_terminal_metadata=True,
    )
    return 0


def _cmd_acquisition_extend_target_cohort(args: argparse.Namespace) -> int:
    """Retain target 100 and emit a provider-free exact target-150 extension."""

    try:
        preflight_policy = _preflight_approved_purchase_runtime(args)
        if preflight_policy is not None:
            read_case_dev_purchase_snapshot(
                cast(Path, args.purchase_ledger).resolve(),
                policy=preflight_policy,
                controlled_private_root=cast(Path | None, args.controlled_private_root),
                initialization_receipt_path=cast(
                    Path | None, args.purchase_ledger_initialization_receipt
                ),
            )
    except (
        CaseDevPurchaseLedgerError,
        CaseDevPurchasePolicyError,
        OSError,
        sqlite3.Error,
        UnicodeError,
        ValueError,
    ) as exc:
        raise CommandError(str(exc)) from exc
    output_root = cast(Path, args.output_root)
    base_root = cast(Path, args.base_cohort_root)
    base_paths = {name: base_root / name for name in BASE_PROJECTION_ARTIFACT_NAMES}
    preparation_root = cast(Path, args.preparation_root)
    preparation_summary_path = cast(Path, args.preparation_summary)
    preparation_config_path = cast(Path, args.preparation_config)
    frontier_path = cast(Path, args.full_candidate_frontier)
    frontier_run_card_path = cast(Path, args.frontier_run_card)
    clearance_run_card_path = cast(Path, args.clearance_run_card)
    try:
        clearance_run_card_bytes = _read_retained_extension_artifact(
            clearance_run_card_path
        )
        clearance_run_card = _projection_json_object(
            clearance_run_card_bytes, source=clearance_run_card_path
        )
        disclosure_clearance_path = _named_committed_path(
            clearance_run_card,
            commitment_group="output_commitments",
            name="disclosure_clearance",
        )
        public_marker_clearance = clearance_run_card.get("schema_version") == (
            "legalforecast.provenance_public_marker_clearance_run_card.v1"
        )
        verified_public_marker_lineage: Mapping[str, object] | None = None
        public_marker_snapshot: Mapping[str, bytes] | None = None
        public_marker_input_paths: tuple[Path, ...] = ()
        raw_clearance_authority = clearance_run_card.get("clearance_authority")
        clearance_authority_kind = (
            cast(Mapping[str, object], raw_clearance_authority).get("kind")
            if isinstance(raw_clearance_authority, Mapping)
            else None
        )
        if public_marker_clearance:
            clearance_sources = clearance_run_card.get("source_commitments")
            if not isinstance(clearance_sources, Mapping):
                raise CommandError("public-marker clearance lacks source commitments")
            download_manifest_path = _named_committed_path(
                clearance_run_card,
                commitment_group="source_commitments",
                name="download_manifest",
            )
            public_marker_snapshot = _capture_clearance_artifact_snapshot(
                run_card=clearance_run_card,
                run_card_path=clearance_run_card_path,
                clearance_path=disclosure_clearance_path,
                initial_artifact_bytes={
                    os.path.abspath(clearance_run_card_path): clearance_run_card_bytes,
                    os.path.abspath(disclosure_clearance_path): (
                        _read_retained_extension_artifact(disclosure_clearance_path)
                    ),
                },
            )
            verified_public_marker_lineage = _verify_materializer_clearance_lineage(
                manifest_path=download_manifest_path,
                clearance_path=disclosure_clearance_path,
                run_card_path=clearance_run_card_path,
                captured_artifact_bytes=public_marker_snapshot,
            )
            if verified_public_marker_lineage.get("lineage_kind") != (
                "provider_free_recovered_public"
            ):
                raise CommandError(
                    "public-marker retained extension lacks recovered-public authority"
                )
            raw_verified_bytes = verified_public_marker_lineage.get(
                "verified_artifact_bytes"
            )
            if not isinstance(raw_verified_bytes, Mapping):
                raise CommandError(
                    "public-marker clearance replay lacks immutable artifact bytes"
                )
            typed_verified_bytes = cast(Mapping[object, object], raw_verified_bytes)
            if not all(
                isinstance(path, str) and isinstance(payload, bytes)
                for path, payload in typed_verified_bytes.items()
            ):
                raise CommandError(
                    "public-marker clearance replay lacks immutable artifact bytes"
                )
            public_marker_snapshot = {
                cast(str, path): cast(bytes, payload)
                for path, payload in typed_verified_bytes.items()
            }
            public_marker_input_paths = tuple(
                Path(path) for path in sorted(public_marker_snapshot)
            )
            reviews_path = None
            review_receipt_path = None
        elif clearance_authority_kind == "provenance_first_with_john_exceptions":
            reviews_path = _named_committed_path(
                clearance_run_card,
                commitment_group="source_commitments",
                name="exception_decisions",
            )
            review_receipt_path = _named_committed_path(
                clearance_run_card,
                commitment_group="source_commitments",
                name="exception_review_run_card",
            )
        else:
            reviews_path = cast(Path | None, args.reviews)
            review_receipt_path = cast(Path | None, args.review_receipt)
            if reviews_path is None or review_receipt_path is None:
                raise CommandError(
                    "legacy retained-cohort clearance requires --reviews and "
                    "--review-receipt"
                )
    except OSError as exc:
        raise CommandError(str(exc)) from exc
    restriction_evidence_path = (
        preparation_root / "06-clearance-inputs/restriction-evidence.jsonl"
    )
    full_paths = {
        "selection.jsonl": preparation_root
        / "03-gap-bridge/public-packet-selection-reconciled.jsonl",
        "case-relevance.jsonl": preparation_root / "03-gap-bridge/case-relevance.jsonl",
        "document-downloads-merged.jsonl": preparation_root
        / "03c-merged-downloads/document-downloads-merged.jsonl",
    }
    cohort_policy_path = cast(Path, args.cohort_policy)
    snapshot_path = cast(Path, args.snapshot_manifest)
    purchase_policy_path = cast(Path, args.purchase_policy)
    purchase_ledger_path = cast(Path, args.purchase_ledger)
    run_card_path = _acquisition_path(
        args,
        "run_card_output",
        output_root / "run-cards/extend-target-cohort.json",
    )
    log_path = _acquisition_path(
        args,
        "log_output",
        output_root / "logs/extend-target-cohort.jsonl",
    )
    input_paths = (
        *base_paths.values(),
        *full_paths.values(),
        restriction_evidence_path,
        preparation_root,
        preparation_summary_path,
        preparation_config_path,
        frontier_path,
        frontier_run_card_path,
        clearance_run_card_path,
        *(
            (reviews_path, review_receipt_path)
            if reviews_path is not None and review_receipt_path is not None
            else ()
        ),
        *public_marker_input_paths,
        cohort_policy_path,
        snapshot_path,
        purchase_policy_path,
        purchase_ledger_path,
    )
    expected_output_paths = _retained_extension_output_paths(output_root)
    _validate_retained_extension_output_scope(
        output_root,
        input_paths=input_paths,
        additional_output_paths=(
            run_card_path,
            log_path,
            *expected_output_paths,
        ),
    )
    if run_card_path.exists():
        if not cast(bool, args.resume):
            raise CommandError(
                "extend-target-cohort run card already exists and --no-resume was set"
            )
        _validate_retained_extension_completed_resume(
            run_card_path,
            output_root=output_root,
            input_path_prefix=input_paths,
            expected_output_paths=expected_output_paths,
            dry_run=_acquisition_dry_run(args),
            combined_max_projected_budget_usd=cast(
                str, args.combined_max_projected_budget_usd
            ),
        )
        return 0
    try:
        full_paths["disclosure-clearance.jsonl"] = disclosure_clearance_path
        input_paths = (*input_paths, disclosure_clearance_path)
        _validate_retained_extension_output_scope(
            output_root,
            input_paths=input_paths,
            additional_output_paths=(run_card_path, log_path),
        )
        base_artifacts = {
            name: _read_retained_extension_artifact(path)
            for name, path in base_paths.items()
        }
        full_artifacts = {
            name: _read_retained_extension_artifact(path)
            for name, path in full_paths.items()
        }
        cohort_policy_bytes = _read_retained_extension_artifact(cohort_policy_path)
        snapshot_bytes = _read_retained_extension_artifact(snapshot_path)
        purchase_policy_bytes = _read_retained_extension_artifact(purchase_policy_path)
        lineage_bytes = {
            "preparation_summary": _read_retained_extension_artifact(
                preparation_summary_path
            ),
            "preparation_config": _read_retained_extension_artifact(
                preparation_config_path
            ),
            "frontier": _read_retained_extension_artifact(frontier_path),
            "frontier_run_card": _read_retained_extension_artifact(
                frontier_run_card_path
            ),
            "clearance_run_card": clearance_run_card_bytes,
            "restriction_evidence": _read_retained_extension_artifact(
                restriction_evidence_path
            ),
            **(
                {
                    "reviews": _read_retained_extension_artifact(reviews_path),
                    "review_receipt": _read_retained_extension_artifact(
                        review_receipt_path
                    ),
                }
                if reviews_path is not None and review_receipt_path is not None
                else {}
            ),
        }
    except OSError as exc:
        raise CommandError(str(exc)) from exc
    cohort_policy = _projection_json_object(
        cohort_policy_bytes, source=cohort_policy_path
    )
    snapshot = _projection_json_object(snapshot_bytes, source=snapshot_path)
    purchase_policy_artifact = _projection_json_object(
        purchase_policy_bytes, source=purchase_policy_path
    )
    cycle_hash = snapshot.get("cycle_hash")
    batch_digest = snapshot.get("batch_digest")
    if not isinstance(cycle_hash, str) or not cycle_hash:
        raise CommandError("snapshot manifest lacks cycle_hash")
    if not isinstance(batch_digest, str) or not batch_digest:
        raise CommandError("snapshot manifest lacks batch_digest")
    authenticated_lineage = _authenticated_extension_lineage(
        preparation_root=preparation_root,
        preparation_summary_path=preparation_summary_path,
        preparation_config_path=preparation_config_path,
        snapshot_path=snapshot_path,
        frontier_path=frontier_path,
        frontier_run_card_path=frontier_run_card_path,
        clearance_run_card_path=clearance_run_card_path,
        reviews_path=reviews_path,
        review_receipt_path=review_receipt_path,
        verified_public_marker_lineage=verified_public_marker_lineage,
        public_marker_snapshot=public_marker_snapshot,
        cohort_policy_path=cohort_policy_path,
        restriction_evidence_path=restriction_evidence_path,
        disclosure_clearance_path=disclosure_clearance_path,
        full_paths=full_paths,
        full_artifacts=full_artifacts,
        lineage_bytes=lineage_bytes,
        snapshot_bytes=snapshot_bytes,
        preparation_target_case_count=BASE_CASE_COUNT,
    )
    try:
        purchase_policy = verify_case_dev_purchase_policy(purchase_policy_artifact)
        require_approved_case_dev_purchase_policy(
            purchase_policy,
            controlled_private_root=cast(Path | None, args.controlled_private_root),
        )
        _validate_existing_purchase_ledger(purchase_ledger_path, purchase_policy)
        with CaseDevPurchaseJournal(
            purchase_ledger_path,
            policy=purchase_policy,
            read_only=True,
            controlled_private_root=cast(Path | None, args.controlled_private_root),
            initialization_receipt_path=cast(
                Path | None, args.purchase_ledger_initialization_receipt
            ),
        ) as purchase_journal:
            obligations = purchase_obligation_snapshot(
                policy=purchase_policy,
                journal=purchase_journal,
                cohort_policy_artifact=cohort_policy,
            )
            extension = extend_target_cohort(
                base_projection_artifacts=base_artifacts,
                full_pool_artifacts=full_artifacts,
                cohort_policy_artifact=cohort_policy,
                snapshot_manifest_sha256=_bytes_sha256(snapshot_bytes),
                snapshot_cycle_hash=cycle_hash,
                snapshot_batch_digest=batch_digest,
                combined_max_projected_budget_usd=cast(
                    str, args.combined_max_projected_budget_usd
                ),
                purchase_obligations=obligations,
                authenticated_lineage=authenticated_lineage,
            )
            return _publish_retained_cohort_extension(
                args=args,
                extension=extension,
                output_root=output_root,
                input_paths=input_paths,
                run_card_path=run_card_path,
                log_path=log_path,
            )
    except (
        RetainedCohortExtensionError,
        CaseDevPurchaseLedgerError,
        CaseDevPurchasePolicyError,
    ) as exc:
        raise CommandError(str(exc)) from exc


def _named_committed_path(
    run_card: Mapping[str, Any], *, commitment_group: str, name: str
) -> Path:
    raw_group = run_card.get(commitment_group)
    if not isinstance(raw_group, Mapping):
        raise CommandError(f"run card lacks {commitment_group}")
    raw_commitment = cast(Mapping[str, object], raw_group).get(name)
    if not isinstance(raw_commitment, Mapping):
        raise CommandError(f"run card lacks {commitment_group}.{name}")
    raw_path = cast(Mapping[str, object], raw_commitment).get("path")
    if not isinstance(raw_path, str) or not raw_path:
        raise CommandError(f"run card has invalid {commitment_group}.{name} path")
    return Path(raw_path)


def _clearance_source_commitment_sha256s(
    run_card: Mapping[str, Any],
) -> dict[str, str]:
    """Return every replayed source identity without inventing review artifacts."""

    raw_sources = run_card.get("source_commitments")
    if not isinstance(raw_sources, Mapping):
        raise CommandError("clearance run card lacks source commitments")
    identities: dict[str, str] = {}
    for raw_name, raw_commitment in cast(Mapping[object, object], raw_sources).items():
        if (
            not isinstance(raw_name, str)
            or not raw_name
            or not isinstance(raw_commitment, Mapping)
        ):
            raise CommandError("clearance source commitment is invalid")
        commitment = cast(Mapping[str, object], raw_commitment)
        digest = commitment.get("sha256", commitment.get("tree_sha256"))
        if not _valid_prefixed_sha256(digest):
            raise CommandError(
                f"clearance source commitment {raw_name} lacks a SHA-256 identity"
            )
        identities[raw_name] = cast(str, digest)
    return dict(sorted(identities.items()))


def _authenticated_extension_lineage(
    *,
    preparation_root: Path,
    preparation_summary_path: Path,
    preparation_config_path: Path,
    snapshot_path: Path,
    frontier_path: Path,
    frontier_run_card_path: Path,
    clearance_run_card_path: Path,
    reviews_path: Path | None,
    review_receipt_path: Path | None,
    verified_public_marker_lineage: Mapping[str, object] | None,
    public_marker_snapshot: Mapping[str, bytes] | None,
    cohort_policy_path: Path,
    restriction_evidence_path: Path,
    disclosure_clearance_path: Path,
    full_paths: Mapping[str, Path],
    full_artifacts: Mapping[str, bytes],
    lineage_bytes: Mapping[str, bytes],
    snapshot_bytes: bytes,
    preparation_target_case_count: int,
) -> AuthenticatedPoolLineage:
    """Verify the provider-free preparation/frontier/clearance chain."""

    preparation_summary = _projection_json_object(
        lineage_bytes["preparation_summary"], source=preparation_summary_path
    )
    preparation_config = _projection_json_object(
        lineage_bytes["preparation_config"], source=preparation_config_path
    )
    snapshot = _projection_json_object(snapshot_bytes, source=snapshot_path)
    clearance_run_card = _projection_json_object(
        lineage_bytes["clearance_run_card"], source=clearance_run_card_path
    )
    frontier = _projection_json_object(lineage_bytes["frontier"], source=frontier_path)
    frontier_run_card = _projection_json_object(
        lineage_bytes["frontier_run_card"], source=frontier_run_card_path
    )
    preparation_cost_per_document_usd = _required_str(
        preparation_config, "cost_per_document_usd"
    )
    preparation_max_projected_budget_usd = _required_str(
        preparation_config, "max_projected_budget_usd"
    )
    preparation_max_missing_core_documents_per_case = preparation_config.get(
        "max_missing_core_documents_per_case"
    )
    if (
        isinstance(preparation_max_missing_core_documents_per_case, bool)
        or not isinstance(preparation_max_missing_core_documents_per_case, int)
        or preparation_max_missing_core_documents_per_case < 1
    ):
        raise CommandError(
            "preparation config has invalid max_missing_core_documents_per_case"
        )
    source_paths = {
        "selection": full_paths["selection.jsonl"],
        "case_relevance": full_paths["case-relevance.jsonl"],
        "download_manifest": full_paths["document-downloads-merged.jsonl"],
        "disclosure_clearance": disclosure_clearance_path,
        "clearance_run_card": clearance_run_card_path,
        "restriction_evidence": restriction_evidence_path,
        "preparation_summary": preparation_summary_path,
        "preparation_config": preparation_config_path,
        "snapshot_manifest": snapshot_path,
    }
    source_payloads = {
        "selection": full_artifacts["selection.jsonl"],
        "case_relevance": full_artifacts["case-relevance.jsonl"],
        "download_manifest": full_artifacts["document-downloads-merged.jsonl"],
        "disclosure_clearance": full_artifacts["disclosure-clearance.jsonl"],
        "clearance_run_card": lineage_bytes["clearance_run_card"],
        "restriction_evidence": lineage_bytes["restriction_evidence"],
        "preparation_summary": lineage_bytes["preparation_summary"],
        "preparation_config": lineage_bytes["preparation_config"],
        "snapshot_manifest": snapshot_bytes,
    }
    source_sha256 = {
        name: _bytes_sha256(payload) for name, payload in source_payloads.items()
    }
    _validate_projection_source_commitments(
        preparation_summary=preparation_summary,
        preparation_config=preparation_config,
        snapshot_manifest=snapshot,
        clearance_run_card=clearance_run_card,
        source_paths=source_paths,
        source_sha256=source_sha256,
        target_case_count=preparation_target_case_count,
        cost_per_document_usd=preparation_cost_per_document_usd,
        max_projected_budget_usd=preparation_max_projected_budget_usd,
        max_missing_core_documents_per_case=(
            preparation_max_missing_core_documents_per_case
        ),
    )
    if clearance_run_card.get("paid_activity_requested") is not False:
        raise CommandError("clear-disclosures run card requested paid activity")
    clearance_sources = clearance_run_card.get("source_commitments")
    if not isinstance(clearance_sources, Mapping):
        raise CommandError("clear-disclosures run card lacks source commitments")
    raw_clearance_authority = clearance_run_card.get("clearance_authority")
    clearance_authority_kind = (
        cast(Mapping[str, object], raw_clearance_authority).get("kind")
        if isinstance(raw_clearance_authority, Mapping)
        else None
    )
    public_marker_schema = clearance_run_card.get("schema_version") == (
        "legalforecast.provenance_public_marker_clearance_run_card.v1"
    )
    clearance_source_commitment_sha256s: Mapping[str, str] | None = None
    clearance_authority_sha256: str | None = None
    clearance_snapshot: dict[str, bytes] = {}
    if public_marker_schema:
        if (
            verified_public_marker_lineage is None
            or public_marker_snapshot is None
            or verified_public_marker_lineage.get("lineage_kind")
            != "provider_free_recovered_public"
        ):
            raise CommandError(
                "public-marker clearance lacks authenticated recovered-public replay"
            )
        clearance_snapshot = dict(public_marker_snapshot)
        if (
            clearance_snapshot.get(os.path.abspath(clearance_run_card_path))
            != (lineage_bytes["clearance_run_card"])
        ):
            raise CommandError("public-marker clearance run card changed after replay")
        clearance_source_commitment_sha256s = _clearance_source_commitment_sha256s(
            clearance_run_card
        )
        recovered_authority = clearance_run_card.get("recovered_public_authority")
        if not isinstance(recovered_authority, Mapping):
            raise CommandError(
                "public-marker clearance lacks recovered-public authority"
            )
        clearance_authority_sha256 = _bytes_sha256(
            canonical_json_bytes(cast(Mapping[str, object], recovered_authority))
        )
        clearance_reviews_sha256 = None
        clearance_review_receipt_sha256 = None
    elif clearance_authority_kind == "provenance_first_with_john_exceptions":
        if reviews_path is None or review_receipt_path is None:
            raise CommandError("provenance clearance lacks exception review artifacts")
        clearance_snapshot = _capture_clearance_artifact_snapshot(
            run_card=clearance_run_card,
            run_card_path=clearance_run_card_path,
            clearance_path=disclosure_clearance_path,
            initial_artifact_bytes={
                os.path.abspath(path): source_payloads[name]
                for name, path in source_paths.items()
            },
        )
        lineage_bytes = {
            **lineage_bytes,
            "clearance_run_card": clearance_snapshot[
                os.path.abspath(clearance_run_card_path)
            ],
            "reviews": clearance_snapshot[os.path.abspath(reviews_path)],
            "review_receipt": clearance_snapshot[os.path.abspath(review_receipt_path)],
            "restriction_evidence": clearance_snapshot[
                os.path.abspath(restriction_evidence_path)
            ],
        }
        _verify_authenticated_clearance_run_card(
            clearance_path=disclosure_clearance_path,
            clearance_run_card_path=clearance_run_card_path,
            expected_download_manifest_path=full_paths[
                "document-downloads-merged.jsonl"
            ],
            expected_restriction_path=restriction_evidence_path,
            captured_artifact_bytes=clearance_snapshot,
        )
        decisions_path = _named_committed_path(
            clearance_run_card,
            commitment_group="source_commitments",
            name="exception_decisions",
        )
        recorder_path = _named_committed_path(
            clearance_run_card,
            commitment_group="source_commitments",
            name="exception_review_run_card",
        )
        if decisions_path.resolve() != reviews_path.resolve():
            raise CommandError("clearance committed different exception decisions")
        if recorder_path.resolve() != review_receipt_path.resolve():
            raise CommandError("clearance committed different exception recorder")
        clearance_reviews_sha256 = _bytes_sha256(lineage_bytes["reviews"])
        clearance_review_receipt_sha256 = _bytes_sha256(lineage_bytes["review_receipt"])
    else:
        if reviews_path is None or review_receipt_path is None:
            raise CommandError("legacy clearance lacks review artifacts")
        clearance_reviews_sha256 = None
        clearance_review_receipt_sha256 = None
    review_requests_path = _named_committed_path(
        clearance_run_card,
        commitment_group="source_commitments",
        name="review_requests",
    )
    review_worksheet_name = (
        "exception_worksheet"
        if (
            public_marker_schema
            or clearance_authority_kind == "provenance_first_with_john_exceptions"
        )
        else "review_worksheet"
    )
    review_worksheet_path = _named_committed_path(
        clearance_run_card,
        commitment_group="source_commitments",
        name=review_worksheet_name,
    )
    committed_cohort_policy_path = _named_committed_path(
        clearance_run_card,
        commitment_group="source_commitments",
        name="cohort_policy",
    )
    if committed_cohort_policy_path.resolve() != cohort_policy_path.resolve():
        raise CommandError("clearance committed a different cohort policy")
    if (
        public_marker_schema
        or clearance_authority_kind == "provenance_first_with_john_exceptions"
    ):
        reviewer_policy_path = _named_committed_path(
            clearance_run_card,
            commitment_group="source_commitments",
            name="routing_plan",
        )
    else:
        reviewer_policy_path = _named_committed_path(
            clearance_run_card,
            commitment_group="source_commitments",
            name="reviewer_policy",
        )
    raw_review_authority = clearance_run_card.get("review_authority")
    if (
        not public_marker_schema
        and clearance_authority_kind != "provenance_first_with_john_exceptions"
        and not isinstance(raw_review_authority, Mapping)
    ):
        raise CommandError("clear-disclosures run card lacks review authority")
    if public_marker_schema:
        authority_record: Mapping[str, object] = {}
    elif clearance_authority_kind == "provenance_first_with_john_exceptions":
        authority_record = cast(Mapping[str, object], raw_clearance_authority)
    else:
        authority_record = cast(Mapping[str, object], raw_review_authority)
    legacy_disclosure_authority: DisclosureReviewAuthority | None = None
    legacy_review_authority: ReviewAuthority | None = None
    review_commitment_names = (
        ("exception_decisions", "exception_review_run_card")
        if clearance_authority_kind == "provenance_first_with_john_exceptions"
        else ("reviews", "review_receipt")
    )
    if not public_marker_schema:
        if reviews_path is None or review_receipt_path is None:
            raise CommandError("clearance review paths are missing")
        for name, path, digest in (
            (
                review_commitment_names[0],
                reviews_path,
                _bytes_sha256(lineage_bytes["reviews"]),
            ),
            (
                review_commitment_names[1],
                review_receipt_path,
                _bytes_sha256(lineage_bytes["review_receipt"]),
            ),
        ):
            _validate_named_path_commitment(
                cast(Mapping[str, object], clearance_sources),
                name=name,
                expected_path=path,
                expected_sha256=digest,
            )
    review_requests_bytes = b""
    worksheet_bytes = b""
    reviewer_policy_bytes = b""
    cohort_policy_artifact_bytes = b""
    try:
        if public_marker_schema:
            frontier_rows = _verified_target_cohort_frontier_rows(frontier)
        elif clearance_authority_kind == "provenance_first_with_john_exceptions":
            review_requests_bytes = clearance_snapshot[
                os.path.abspath(review_requests_path)
            ]
            worksheet_bytes = clearance_snapshot[os.path.abspath(review_worksheet_path)]
            reviewer_policy_bytes = clearance_snapshot[
                os.path.abspath(reviewer_policy_path)
            ]
            cohort_policy_artifact_bytes = clearance_snapshot[
                os.path.abspath(committed_cohort_policy_path)
            ]
        else:
            review_requests_bytes = _read_retained_extension_artifact(
                review_requests_path
            )
            worksheet_bytes = _read_retained_extension_artifact(review_worksheet_path)
            reviewer_policy_bytes = _read_retained_extension_artifact(
                reviewer_policy_path
            )
            cohort_policy_artifact_bytes = _read_retained_extension_artifact(
                committed_cohort_policy_path
            )
        if (
            not public_marker_schema
            and clearance_authority_kind != "provenance_first_with_john_exceptions"
        ):
            if review_receipt_path is None:
                raise CommandError("legacy clearance review receipt path is missing")
            legacy_disclosure_authority = load_main_disclosure_review_authority(
                _projection_json_object(
                    cohort_policy_artifact_bytes, source=committed_cohort_policy_path
                ),
                reviewer_policy_bytes=reviewer_policy_bytes,
            )
            clearance_lineage = validate_authenticated_clearance_lineage(
                clearance_records=_projection_jsonl_records(
                    full_artifacts["disclosure-clearance.jsonl"],
                    source=disclosure_clearance_path,
                ),
                clearance_artifact_bytes=full_artifacts["disclosure-clearance.jsonl"],
                clearance_run_card=clearance_run_card,
                clearance_run_card_bytes=lineage_bytes["clearance_run_card"],
                reviews_artifact_bytes=lineage_bytes["reviews"],
                review_receipt_artifact=_projection_json_object(
                    lineage_bytes["review_receipt"], source=review_receipt_path
                ),
                review_receipt_bytes=lineage_bytes["review_receipt"],
                review_requests_artifact_bytes=review_requests_bytes,
                review_worksheet_artifact=_projection_json_object(
                    worksheet_bytes, source=review_worksheet_path
                ),
                review_worksheet_bytes=worksheet_bytes,
                reviewer_policy_bytes=reviewer_policy_bytes,
                disclosure_authority=legacy_disclosure_authority,
                cohort_policy_artifact_bytes=cohort_policy_artifact_bytes,
                download_manifest_artifact_bytes=full_artifacts[
                    "document-downloads-merged.jsonl"
                ],
                restriction_records=_projection_jsonl_records(
                    lineage_bytes["restriction_evidence"],
                    source=restriction_evidence_path,
                ),
                restriction_artifact_bytes=lineage_bytes["restriction_evidence"],
            )
            legacy_review_authority = clearance_lineage.authority
            clearance_reviews_sha256 = _bytes_sha256(lineage_bytes["reviews"])
            clearance_review_receipt_sha256 = _bytes_sha256(
                lineage_bytes["review_receipt"]
            )
        frontier_rows = _verified_target_cohort_frontier_rows(frontier)
    except (
        DisclosureClearanceError,
        DisclosureReviewAuthorityError,
        ValueError,
    ) as exc:
        raise CommandError(str(exc)) from exc
    if (
        not public_marker_schema
        and clearance_authority_kind != "provenance_first_with_john_exceptions"
    ):
        if legacy_review_authority is None or legacy_disclosure_authority is None:
            raise CommandError("legacy disclosure authority verification failed")
        expected_authority = _clearance_review_authority_record(
            legacy_review_authority, legacy_disclosure_authority
        )
        if dict(authority_record) != expected_authority:
            raise CommandError(
                "clear-disclosures review authority differs from receipt"
            )

    policy = cast(Mapping[str, Any], frontier["policy"])
    commitments = cast(Mapping[str, object], policy["source_commitments"])
    expected_frontier_commitments = {
        "snapshot_manifest_sha256": _bytes_sha256(snapshot_bytes),
        "preparation_config_sha256": _bytes_sha256(lineage_bytes["preparation_config"]),
        "preparation_summary_sha256": _bytes_sha256(
            lineage_bytes["preparation_summary"]
        ),
        "reconciled_selection_sha256": _bytes_sha256(full_artifacts["selection.jsonl"]),
        "case_relevance_sha256": _bytes_sha256(full_artifacts["case-relevance.jsonl"]),
        "download_manifest_sha256": _bytes_sha256(
            full_artifacts["document-downloads-merged.jsonl"]
        ),
        "restriction_evidence_sha256": _bytes_sha256(
            lineage_bytes["restriction_evidence"]
        ),
    }
    for name, expected in expected_frontier_commitments.items():
        if commitments.get(name) != expected:
            raise CommandError(f"full candidate frontier {name} mismatch")
    selection_rows = _projection_jsonl_records(
        full_artifacts["selection.jsonl"], source=full_paths["selection.jsonl"]
    )
    selection_ids = {_required_str(row, "candidate_id") for row in selection_rows}
    frontier_id_order = tuple(
        _required_str(row, "candidate_id") for row in frontier_rows
    )
    frontier_ids = set(frontier_id_order)
    if frontier_ids != selection_ids or len(frontier_rows) != len(selection_ids):
        raise CommandError("full candidate frontier differs from resolved selection")
    relevance_rows = _projection_jsonl_records(
        full_artifacts["case-relevance.jsonl"],
        source=full_paths["case-relevance.jsonl"],
    )
    filter_results = filter_core_documents(relevance_rows)
    ranked_ids = tuple(
        plan.candidate_id
        for plan in rank_missing_core_document_plans(
            filter_results,
            dry_run=False,
            max_missing_core_documents_per_case=(
                preparation_max_missing_core_documents_per_case
            ),
            cost_per_document_usd=preparation_cost_per_document_usd,
        )
    )
    if frontier_id_order != ranked_ids:
        raise CommandError(
            "full candidate frontier order does not derive from case relevance"
        )
    raw_frontier_candidates = cast(
        Sequence[object], cast(Mapping[str, Any], frontier["policy"])["candidates"]
    )
    selected_frontier_ids = tuple(
        _required_str(cast(Mapping[str, Any], row), "candidate_id")
        for row in raw_frontier_candidates
        if isinstance(row, Mapping)
        and cast(Mapping[str, object], row).get("selection_status") == "selected"
    )
    canonical_preparation_plan = plan_missing_core_document_budget(
        filter_results,
        dry_run=False,
        max_missing_core_documents_per_case=(
            preparation_max_missing_core_documents_per_case
        ),
        cost_per_document_usd=preparation_cost_per_document_usd,
        max_projected_budget_usd=preparation_max_projected_budget_usd,
        truncate_to_budget=True,
        target_case_count=preparation_target_case_count,
    )
    if selected_frontier_ids != tuple(
        plan.candidate_id for plan in canonical_preparation_plan.case_plans
    ):
        raise CommandError("full candidate frontier selected boundary is not canonical")

    success_run_card_path = _validate_frontier_materialization_run_card(
        frontier_run_card,
        preparation_root=preparation_root,
        preparation_summary_path=preparation_summary_path,
        preparation_config_path=preparation_config_path,
        snapshot_path=snapshot_path,
        frontier_path=frontier_path,
        frontier_sha256=_bytes_sha256(lineage_bytes["frontier"]),
    )
    success_run_card_sha256 = _path_sha256(success_run_card_path)
    if commitments.get("preparation_success_run_card_sha256") != (
        success_run_card_sha256
    ):
        raise CommandError("frontier preparation success run-card mismatch")
    return AuthenticatedPoolLineage(
        preparation_summary_sha256=expected_frontier_commitments[
            "preparation_summary_sha256"
        ],
        preparation_config_sha256=expected_frontier_commitments[
            "preparation_config_sha256"
        ],
        snapshot_manifest_sha256=expected_frontier_commitments[
            "snapshot_manifest_sha256"
        ],
        full_candidate_frontier_sha256=_bytes_sha256(lineage_bytes["frontier"]),
        frontier_policy_sha256=cast(str, frontier["policy_sha256"]),
        frontier_run_card_sha256=_bytes_sha256(lineage_bytes["frontier_run_card"]),
        clearance_run_card_sha256=_bytes_sha256(lineage_bytes["clearance_run_card"]),
        clearance_reviews_sha256=clearance_reviews_sha256,
        clearance_review_receipt_sha256=clearance_review_receipt_sha256,
        clearance_source_commitment_sha256s=(clearance_source_commitment_sha256s),
        clearance_authority_sha256=clearance_authority_sha256,
        restriction_evidence_sha256=_bytes_sha256(
            lineage_bytes["restriction_evidence"]
        ),
        preparation_cost_per_document_usd=preparation_cost_per_document_usd,
        preparation_max_projected_budget_usd=(preparation_max_projected_budget_usd),
        preparation_max_missing_core_documents_per_case=(
            preparation_max_missing_core_documents_per_case
        ),
    )


def _validate_frontier_materialization_run_card(
    run_card: Mapping[str, Any],
    *,
    preparation_root: Path,
    preparation_summary_path: Path,
    preparation_config_path: Path,
    snapshot_path: Path,
    frontier_path: Path,
    frontier_sha256: str,
) -> Path:
    if (
        run_card.get("schema_version") != "legalforecast.acquisition_run_card.v1"
        or run_card.get("stage") != "materialize-target-cohort-frontier"
        or run_card.get("status") != "completed"
        or run_card.get("dry_run") is not False
        or run_card.get("execute") is not True
        or run_card.get("paid_activity_requested") is not False
        or run_card.get("paid_activity_executed") is not False
        or run_card.get("zero_provider_activity_evidence") is not True
        or run_card.get("frontier_sha256") != frontier_sha256
        or run_card.get("output_paths") != [str(frontier_path)]
    ):
        raise CommandError("invalid completed frontier-materialization run card")
    raw_inputs = run_card.get("input_paths")
    if not isinstance(raw_inputs, Sequence) or isinstance(raw_inputs, (str, bytes)):
        raise CommandError("frontier-materialization run card lacks inputs")
    input_values = tuple(cast(Sequence[object], raw_inputs))
    if not all(isinstance(path, str) for path in input_values):
        raise CommandError("frontier-materialization run card has invalid input path")
    input_paths = tuple(Path(cast(str, path)) for path in input_values)
    required = {
        preparation_root.resolve(),
        preparation_summary_path.resolve(),
        preparation_config_path.resolve(),
        snapshot_path.resolve(),
    }
    resolved = {path.resolve() for path in input_paths}
    remaining = resolved - required
    if not required.issubset(resolved) or len(remaining) != 1 or len(resolved) != 5:
        raise CommandError("frontier-materialization source lineage differs")
    success_run_card_path = next(iter(remaining))
    if success_run_card_path.is_symlink() or not success_run_card_path.is_file():
        raise CommandError("preparation success run card is missing")
    return success_run_card_path


def _publish_retained_cohort_extension(
    *,
    args: argparse.Namespace,
    extension: RetainedCohortExtension,
    output_root: Path,
    input_paths: Sequence[Path],
    run_card_path: Path,
    log_path: Path,
) -> int:
    """Publish or validate extension outputs while the journal lock is held."""

    output_records = {
        **{
            output_root / name: payload
            for name, payload in extension.combined_artifacts.items()
        },
        **{
            output_root / "incremental" / name: payload
            for name, payload in extension.incremental_artifacts.items()
        },
    }
    _validate_retained_extension_output_scope(
        output_root,
        input_paths=input_paths,
        additional_output_paths=(run_card_path, log_path, *output_records),
    )
    metadata_outputs = {run_card_path.resolve(), log_path.resolve()}
    artifact_outputs = {path.resolve() for path in output_records}
    collision = metadata_outputs & artifact_outputs
    if collision:
        raise CommandError(
            "extend-target-cohort metadata output aliases cohort artifact: "
            f"{sorted(str(path) for path in collision)}"
        )
    dry_run = _acquisition_dry_run(args)
    if run_card_path.exists():
        if not cast(bool, args.resume):
            raise CommandError(
                "extend-target-cohort run card already exists and --no-resume was set"
            )
        _validate_retained_extension_successful_resume(
            run_card_path,
            input_paths=input_paths,
            expected_outputs=output_records,
            dry_run=dry_run,
            extension_sha256=cast(str, extension.extension_record["extension_sha256"]),
            cumulative_obligation_usd=cast(
                str, extension.combined_budget["cumulative_obligation_usd"]
            ),
            remaining_headroom_usd=cast(
                str, extension.combined_budget["remaining_headroom_usd"]
            ),
        )
        return 0
    if not dry_run:
        for path, payload in output_records.items():
            _ensure_projection_artifact(
                path,
                payload,
                resume=cast(bool, args.resume),
                stage="extend-target-cohort",
            )
    _write_acquisition_completion(
        args,
        stage="extend-target-cohort",
        input_paths=input_paths,
        output_paths=tuple(output_records),
        record_count=len(extension.combined_candidate_ids),
        dry_run=dry_run,
        paid_activity_requested=False,
        paid_activity_executed=False,
        extra={
            "base_case_count": len(extension.base_candidate_ids),
            "incremental_case_count": len(extension.incremental_candidate_ids),
            "combined_case_count": len(extension.combined_candidate_ids),
            "extension_sha256": extension.extension_record["extension_sha256"],
            "cumulative_obligation_usd": extension.combined_budget[
                "cumulative_obligation_usd"
            ],
            "remaining_headroom_usd": extension.combined_budget[
                "remaining_headroom_usd"
            ],
            "output_commitments": {
                str(path): _bytes_sha256(payload)
                for path, payload in output_records.items()
            },
        },
    )
    return 0


def _validate_retained_extension_successful_resume(
    run_card_path: Path,
    *,
    input_paths: Sequence[Path],
    expected_outputs: Mapping[Path, bytes],
    dry_run: bool,
    extension_sha256: str,
    cumulative_obligation_usd: str,
    remaining_headroom_usd: str,
) -> None:
    run_card_bytes = _read_singly_linked_regular_input(
        run_card_path, label="target projection run card"
    )
    run_card = _projection_json_object(run_card_bytes, source=run_card_path)
    expected = {
        "schema_version": "legalforecast.acquisition_run_card.v1",
        "stage": "extend-target-cohort",
        "status": "completed",
        "dry_run": dry_run,
        "execute": not dry_run,
        "record_count": 150,
        "input_paths": [str(path) for path in input_paths],
        "output_paths": [str(path) for path in expected_outputs],
        "paid_activity_requested": False,
        "paid_activity_executed": False,
        "base_case_count": 100,
        "incremental_case_count": 50,
        "combined_case_count": 150,
        "extension_sha256": extension_sha256,
        "cumulative_obligation_usd": cumulative_obligation_usd,
        "remaining_headroom_usd": remaining_headroom_usd,
    }
    for field, value in expected.items():
        if run_card.get(field) != value:
            raise CommandError(
                f"extend-target-cohort resume run-card mismatch: {field}"
            )
    commitments = run_card.get("output_commitments")
    if not isinstance(commitments, Mapping):
        raise CommandError(
            "extend-target-cohort resume run card lacks output commitments"
        )
    expected_commitments = {
        str(path): _bytes_sha256(payload) for path, payload in expected_outputs.items()
    }
    typed_commitments = cast(Mapping[str, object], commitments)
    if dict(typed_commitments) != expected_commitments:
        raise CommandError("extend-target-cohort resume output commitments differ")
    if not dry_run:
        for path, payload in expected_outputs.items():
            if path.is_symlink() or not path.is_file() or path.read_bytes() != payload:
                raise CommandError(
                    f"extend-target-cohort committed output changed: {path}"
                )


def _retained_extension_output_paths(output_root: Path) -> tuple[Path, ...]:
    combined_names = (
        "target-cohort-selection.jsonl",
        "case-relevance.jsonl",
        "document-downloads-merged.jsonl",
        "disclosure-clearance.jsonl",
        "restriction-evidence.jsonl",
        "core-filter-results.jsonl",
        "free-document-downloads.jsonl",
        "purchased-document-downloads.jsonl",
        "target-cohort-exclusions.jsonl",
        "missing-core-budget-plan.json",
        "retained-cohort-budget.json",
        "retained-cohort-extension.json",
    )
    incremental_names = (
        "target-cohort-selection.jsonl",
        "target-cohort-ranked-reserve.jsonl",
        "case-relevance.jsonl",
        "document-downloads-merged.jsonl",
        "free-document-downloads.jsonl",
        "purchased-document-downloads.jsonl",
        "disclosure-clearance.jsonl",
        "restriction-evidence.jsonl",
        "core-filter-results.jsonl",
        "target-cohort-exclusions.jsonl",
        "missing-core-budget-plan.json",
        "target-cohort-projection.json",
    )
    return (
        *(output_root / name for name in combined_names),
        *(output_root / "incremental" / name for name in incremental_names),
    )


def _validate_retained_extension_completed_resume(
    run_card_path: Path,
    *,
    output_root: Path,
    input_path_prefix: Sequence[Path],
    expected_output_paths: Sequence[Path],
    dry_run: bool,
    combined_max_projected_budget_usd: str,
) -> None:
    """Validate committed outputs before touching mutable acquisition inputs."""

    try:
        combined_cap = Decimal(combined_max_projected_budget_usd)
    except InvalidOperation as exc:
        raise CommandError(
            "combined_max_projected_budget_usd is not valid USD"
        ) from exc
    if (
        not combined_cap.is_finite()
        or combined_cap <= 0
        or combined_cap != combined_cap.quantize(Decimal("0.01"))
    ):
        raise CommandError(
            "combined_max_projected_budget_usd must be positive USD cents"
        )
    normalized_combined_cap = f"{combined_cap:.2f}"
    run_card = _read_json_object(run_card_path)
    expected_fields = {
        "schema_version": "legalforecast.acquisition_run_card.v1",
        "stage": "extend-target-cohort",
        "status": "completed",
        "dry_run": dry_run,
        "execute": not dry_run,
        "record_count": 150,
        "paid_activity_requested": False,
        "paid_activity_executed": False,
        "base_case_count": 100,
        "incremental_case_count": 50,
        "combined_case_count": 150,
    }
    for field, expected in expected_fields.items():
        if run_card.get(field) != expected:
            raise CommandError(
                f"extend-target-cohort resume run-card mismatch: {field}"
            )
    raw_inputs = run_card.get("input_paths")
    if not isinstance(raw_inputs, Sequence) or isinstance(raw_inputs, (str, bytes)):
        raise CommandError("extend-target-cohort resume run card lacks input paths")
    committed_inputs = tuple(cast(Sequence[object], raw_inputs))
    expected_prefix = tuple(str(path) for path in input_path_prefix)
    if (
        len(committed_inputs) != len(expected_prefix) + 1
        or committed_inputs[: len(expected_prefix)] != expected_prefix
        or not isinstance(committed_inputs[-1], str)
    ):
        raise CommandError("extend-target-cohort resume input paths differ")
    raw_outputs = run_card.get("output_paths")
    expected_output_strings = tuple(str(path) for path in expected_output_paths)
    if (
        not isinstance(raw_outputs, Sequence)
        or isinstance(raw_outputs, (str, bytes))
        or set(cast(Sequence[object], raw_outputs)) != set(expected_output_strings)
        or len(cast(Sequence[object], raw_outputs)) != len(expected_output_strings)
    ):
        raise CommandError("extend-target-cohort resume output paths differ")
    if dry_run:
        return
    commitments = run_card.get("output_commitments")
    if not isinstance(commitments, Mapping):
        raise CommandError(
            "extend-target-cohort resume run card lacks exact output commitments"
        )
    typed_commitments = cast(Mapping[object, object], commitments)
    if set(typed_commitments) != set(expected_output_strings):
        raise CommandError(
            "extend-target-cohort resume run card lacks exact output commitments"
        )
    output_payloads: dict[Path, bytes] = {}
    for path in expected_output_paths:
        payload = _read_retained_extension_artifact(path)
        if typed_commitments.get(str(path)) != _bytes_sha256(payload):
            raise CommandError(f"extend-target-cohort committed output changed: {path}")
        output_payloads[path] = payload
    extension_path = output_root / "retained-cohort-extension.json"
    budget_path = output_root / "retained-cohort-budget.json"
    expected_set = set(expected_output_paths)
    if extension_path not in expected_set or budget_path not in expected_set:
        raise CommandError("extend-target-cohort resume metadata paths differ")
    extension = _projection_json_object(
        output_payloads[extension_path], source=extension_path
    )
    extension_sha256 = extension.get("extension_sha256")
    unsigned_extension = dict(extension)
    unsigned_extension.pop("extension_sha256", None)
    if (
        not isinstance(extension_sha256, str)
        or extension_sha256 != _canonical_json_sha256(unsigned_extension)
        or run_card.get("extension_sha256") != extension_sha256
    ):
        raise CommandError("extend-target-cohort resume extension hash mismatch")
    budget = _projection_json_object(output_payloads[budget_path], source=budget_path)
    budget_sha256 = budget.get("budget_sha256")
    unsigned_budget = dict(budget)
    unsigned_budget.pop("budget_sha256", None)
    if (
        not isinstance(budget_sha256, str)
        or budget_sha256 != _canonical_json_sha256(unsigned_budget)
        or budget.get("combined_max_projected_budget_usd") != normalized_combined_cap
        or run_card.get("cumulative_obligation_usd")
        != budget.get("cumulative_obligation_usd")
        or run_card.get("remaining_headroom_usd")
        != budget.get("remaining_headroom_usd")
    ):
        raise CommandError("extend-target-cohort resume budget mismatch")
    output_commitments = extension.get("output_commitments")
    if not isinstance(output_commitments, Mapping):
        raise CommandError("retained extension lacks output commitments")
    for name, digest in cast(Mapping[str, object], output_commitments).items():
        path = output_root / name
        if path not in output_payloads or digest != _bytes_sha256(
            output_payloads[path]
        ):
            raise CommandError(f"retained extension output commitment mismatch: {name}")


def _read_retained_extension_artifact(path: Path) -> bytes:
    return _read_singly_linked_regular_input(path, label="extend-target-cohort input")


def _validate_existing_purchase_ledger(
    path: Path, policy: CaseDevPurchasePolicy
) -> None:
    """Authenticate the canonical journal read-only before its lock is opened."""

    if path.is_symlink() or not path.is_file() or path.stat().st_size == 0:
        raise CommandError(
            "extend-target-cohort requires a preexisting nonempty canonical "
            f"purchase ledger: {path}"
        )
    expected = (
        policy.cycle_id,
        policy.cohort_policy_sha256,
        policy.policy_sha256,
        str(policy.canonical_ledger_path),
        f"{policy.hard_cap_usd:.2f}",
        f"{policy.opening_committed_spend_usd:.2f}",
        f"{policy.max_per_case_usd:.2f}",
        f"{policy.per_document_reservation_usd:.2f}",
    )
    try:
        with sqlite3.connect(f"{path.resolve().as_uri()}?mode=ro", uri=True) as ledger:
            ledger.row_factory = sqlite3.Row
            quick_check = ledger.execute("PRAGMA quick_check").fetchone()
            if quick_check is None or str(quick_check[0]) != "ok":
                raise CommandError("purchase ledger failed SQLite quick_check")
            tables = {
                str(row[0])
                for row in ledger.execute(
                    "SELECT name FROM sqlite_master WHERE type='table'"
                ).fetchall()
            }
            required_tables = {
                "purchase_ledger",
                "purchase_operations",
                "replacement_events",
            }
            if not required_tables.issubset(tables):
                raise CommandError("purchase ledger schema is incomplete")
            operation_schema = ledger.execute(
                "SELECT sql FROM sqlite_master WHERE type='table' "
                "AND name='purchase_operations'"
            ).fetchone()
            if operation_schema is None or "'queued'" not in str(operation_schema[0]):
                raise CommandError("purchase ledger schema is not current")
            row = ledger.execute(
                "SELECT * FROM purchase_ledger WHERE singleton=1"
            ).fetchone()
            if row is None:
                raise CommandError("purchase ledger lacks immutable policy identity")
            actual = tuple(
                str(row[field])
                for field in (
                    "cycle_id",
                    "cohort_policy_sha256",
                    "purchase_policy_sha256",
                    "canonical_ledger_path",
                    "hard_cap_usd",
                    "opening_committed_spend_usd",
                    "max_per_case_usd",
                    "per_document_reservation_usd",
                )
            )
            if actual != expected:
                raise CommandError(
                    "purchase ledger identity conflicts with immutable policy"
                )
    except sqlite3.Error as exc:
        raise CommandError(f"invalid canonical purchase ledger: {exc}") from exc


def _validate_retained_extension_output_scope(
    output_root: Path,
    *,
    input_paths: Sequence[Path],
    additional_output_paths: Sequence[Path] = (),
) -> None:
    outputs = (
        output_root.resolve(),
        *(path.resolve() for path in additional_output_paths),
    )
    for output in outputs[1:]:
        try:
            metadata = output.stat()
        except FileNotFoundError:
            continue
        except OSError as exc:
            raise CommandError(
                f"cannot inspect extend-target-cohort writable output: {output}: {exc}"
            ) from exc
        if output.is_file() and metadata.st_nlink > 1:
            raise CommandError(
                f"extend-target-cohort writable output has hard-link aliases: {output}"
            )
    for output in outputs:
        for path in input_paths:
            source = path.resolve()
            if (
                output == source
                or output.is_relative_to(source)
                or source.is_relative_to(output)
            ):
                raise CommandError(
                    "extend-target-cohort output overlaps immutable input: "
                    f"{output} vs {source}"
                )
            if output.exists() and path.exists() and output.samefile(path):
                raise CommandError(
                    "extend-target-cohort output hard-links immutable input: "
                    f"{output} vs {source}"
                )
    for index, output in enumerate(outputs):
        for other in outputs[index + 1 :]:
            if (
                output == other
                or output.is_relative_to(other)
                or other.is_relative_to(output)
            ):
                # The default run card and log are expected children of output_root.
                if output == output_root.resolve() or other == output_root.resolve():
                    continue
                raise CommandError(
                    f"extend-target-cohort writable outputs alias: {output} vs {other}"
                )
            if output.exists() and other.exists() and output.samefile(other):
                raise CommandError(
                    "extend-target-cohort writable outputs share an inode: "
                    f"{output} vs {other}"
                )


def _validate_projection_output_scope(
    output_root: Path,
    *,
    input_paths: Sequence[Path],
) -> None:
    output = output_root.resolve()
    for path in input_paths:
        source = path.resolve()
        if (
            output == source
            or output.is_relative_to(source)
            or source.is_relative_to(output)
        ):
            raise CommandError(
                "project-target-cohort output overlaps immutable input: "
                f"{output} vs {source}"
            )


def _validate_projection_source_commitments(
    *,
    preparation_summary: Mapping[str, Any],
    preparation_config: Mapping[str, Any],
    snapshot_manifest: Mapping[str, Any],
    clearance_run_card: Mapping[str, Any],
    source_paths: Mapping[str, Path],
    source_sha256: Mapping[str, str],
    target_case_count: int,
    cost_per_document_usd: str,
    max_projected_budget_usd: str,
    max_missing_core_documents_per_case: int,
    replacement_selection_authorized: bool = False,
) -> None:
    schema_pair = (
        preparation_summary.get("schema_version"),
        preparation_config.get("schema_version"),
    )
    supported_schema_pairs = {
        (
            "legalforecast.target_100_preparation.v1",
            "legalforecast.target_100_config.v1",
        ),
        (
            "legalforecast.target_cohort_preparation.v1",
            "legalforecast.target_cohort_config.v1",
        ),
    }
    if schema_pair not in supported_schema_pairs:
        raise CommandError("unsupported or mismatched preparation schema pair")
    if preparation_summary.get("dry_run") is not False:
        raise CommandError("projection requires an executed preparation summary")
    if preparation_summary.get("paid_activity_executed") is not False:
        raise CommandError("preparation summary unexpectedly claims paid activity")
    if (
        preparation_summary.get("budget_status") != "provisional_pre_clearance"
        or preparation_summary.get("next_stage") != "clear-disclosures"
    ):
        raise CommandError("preparation summary is not at the clearance boundary")
    committed_config_sha256 = preparation_config.get("config_sha256")
    config_payload = dict(preparation_config)
    config_payload.pop("config_sha256", None)
    if committed_config_sha256 != _canonical_json_sha256(config_payload):
        raise CommandError("target-100 preparation config self-hash mismatch")
    if preparation_summary.get("config_sha256") != committed_config_sha256:
        raise CommandError("preparation summary config commitment mismatch")
    if preparation_config.get("driver_execute") is not True:
        raise CommandError("projection requires an executed target-100 config")

    _validate_projection_semantic_config(
        preparation_summary=preparation_summary,
        preparation_config=preparation_config,
        target_case_count=target_case_count,
        cost_per_document_usd=cost_per_document_usd,
        max_projected_budget_usd=max_projected_budget_usd,
        max_missing_core_documents_per_case=max_missing_core_documents_per_case,
    )

    expected_snapshot_hash = preparation_summary.get("snapshot_manifest_sha256")
    if expected_snapshot_hash != source_sha256["snapshot_manifest"]:
        raise CommandError("preparation summary snapshot commitment mismatch")
    cycle_hash = snapshot_manifest.get("cycle_hash")
    batch_digest = snapshot_manifest.get("batch_digest")
    if not isinstance(cycle_hash, str) or not cycle_hash:
        raise CommandError("snapshot manifest lacks cycle_hash")
    if not isinstance(batch_digest, str) or not batch_digest:
        raise CommandError("snapshot manifest lacks batch_digest")
    if preparation_summary.get("snapshot_batch_digest") != batch_digest:
        raise CommandError("preparation summary batch digest mismatch")
    if (
        preparation_config.get("snapshot_manifest_sha256")
        != source_sha256["snapshot_manifest"]
        or preparation_config.get("snapshot_cycle_hash") != cycle_hash
        or preparation_config.get("snapshot_batch_digest") != batch_digest
    ):
        raise CommandError("target-100 config snapshot commitment mismatch")

    if not replacement_selection_authorized:
        _validate_prepared_stage_commitment(
            preparation_summary,
            stage="03-gap-bridge",
            relative_path="public-packet-selection-reconciled.jsonl",
            actual_sha256=source_sha256["selection"],
        )
    _validate_prepared_stage_commitment(
        preparation_summary,
        stage="03-gap-bridge",
        relative_path="case-relevance.jsonl",
        actual_sha256=source_sha256["case_relevance"],
    )
    _validate_prepared_stage_commitment(
        preparation_summary,
        stage="03c-merged-downloads",
        relative_path="document-downloads-merged.jsonl",
        actual_sha256=source_sha256["download_manifest"],
    )
    _validate_prepared_stage_commitment(
        preparation_summary,
        stage="06-clearance-inputs",
        relative_path="restriction-evidence.jsonl",
        actual_sha256=source_sha256["restriction_evidence"],
    )
    _validate_clearance_run_card_commitments(
        clearance_run_card,
        source_paths=source_paths,
        source_sha256=source_sha256,
    )


def _validate_projection_semantic_config(
    *,
    preparation_summary: Mapping[str, Any],
    preparation_config: Mapping[str, Any],
    target_case_count: int,
    cost_per_document_usd: str,
    max_projected_budget_usd: str,
    max_missing_core_documents_per_case: int,
) -> None:
    if (
        preparation_summary.get("target_case_count") != target_case_count
        or preparation_config.get("target_case_count") != target_case_count
    ):
        raise CommandError("projection target_case_count differs from prepared config")
    exact_values = {
        "max_missing_core_documents_per_case": max_missing_core_documents_per_case,
    }
    for field, actual in exact_values.items():
        if (
            preparation_config.get(field) != actual
            or preparation_summary.get(field) != actual
        ):
            raise CommandError(f"projection {field} differs from prepared config")
    money_values = {
        "cost_per_document_usd": cost_per_document_usd,
        "max_projected_budget_usd": max_projected_budget_usd,
    }
    for field, actual in money_values.items():
        try:
            actual_decimal = Decimal(actual)
            config_decimal = Decimal(str(preparation_config.get(field)))
            summary_decimal = Decimal(str(preparation_summary.get(field)))
        except InvalidOperation as exc:
            raise CommandError(f"projection {field} is invalid") from exc
        if actual_decimal != config_decimal or actual_decimal != summary_decimal:
            raise CommandError(f"projection {field} differs from prepared config")


def _validate_prepared_stage_commitment(
    preparation_summary: Mapping[str, Any],
    *,
    stage: str,
    relative_path: str,
    actual_sha256: str,
) -> None:
    stages = preparation_summary.get("stage_commitments")
    if not isinstance(stages, Mapping):
        raise CommandError("preparation summary lacks stage commitments")
    stage_record = cast(Mapping[str, object], stages).get(stage)
    if not isinstance(stage_record, Mapping):
        raise CommandError(f"preparation summary lacks {stage} commitment")
    if cast(Mapping[str, object], stage_record).get(relative_path) != actual_sha256:
        raise CommandError(f"prepared {stage}/{relative_path} commitment mismatch")


def _validate_clearance_run_card_commitments(
    run_card: Mapping[str, Any],
    *,
    source_paths: Mapping[str, Path],
    source_sha256: Mapping[str, str],
) -> None:
    provider_free_schema = run_card.get("schema_version")
    public_marker_schema = (
        provider_free_schema
        == "legalforecast.provenance_public_marker_clearance_run_card.v1"
    )
    if provider_free_schema in {
        "legalforecast.provenance_quarantine_clearance_run_card.v1",
        "legalforecast.provenance_public_marker_clearance_run_card.v1",
    }:
        if (
            run_card.get("stage") != "finalize-provenance-quarantine"
            or run_card.get("status") != "completed"
            or run_card.get("dry_run") is not False
            or run_card.get("execute") is not True
            or run_card.get("provider_activity_requested") is not False
            or run_card.get("provider_activity_executed") is not False
            or run_card.get("human_review_requested") is not False
            or run_card.get("human_review_executed") is not False
            or run_card.get("paid_activity_requested") is not False
            or run_card.get("paid_activity_executed") is not False
        ):
            raise CommandError(
                "projection requires an executed provider-free quarantine run card"
            )
        source_commitments = run_card.get("source_commitments")
        output_commitments = run_card.get("output_commitments")
        disposition_policy = run_card.get("disposition_policy")
        if (
            not isinstance(source_commitments, Mapping)
            or not isinstance(output_commitments, Mapping)
            or not isinstance(disposition_policy, Mapping)
        ):
            raise CommandError("provider-free quarantine run card lacks commitments")
        for card_name, source_name in (
            ("download_manifest", "download_manifest"),
            ("case_relevance", "case_relevance"),
            ("restriction_evidence", "restriction_evidence"),
        ):
            _validate_named_path_commitment(
                cast(Mapping[str, object], source_commitments),
                name=card_name,
                expected_path=source_paths[source_name],
                expected_sha256=source_sha256[source_name],
            )
        _validate_named_path_commitment(
            cast(Mapping[str, object], output_commitments),
            name="disclosure_clearance",
            expected_path=source_paths["disclosure_clearance"],
            expected_sha256=source_sha256["disclosure_clearance"],
        )
        expected_kind = (
            "v3_authenticated_recovered_public_markers_clear_else_quarantine"
            if public_marker_schema
            else "v3_auto_clear_else_quarantine"
        )
        policy = cast(Mapping[str, object], disposition_policy)
        if (
            policy.get("kind") != expected_kind
            or policy.get("human_or_model_override_permitted") is not False
            or (
                public_marker_schema
                and (
                    policy.get("public_marker_clearance_policy_schema_version")
                    != PUBLIC_MARKER_CLEARANCE_POLICY_SCHEMA_VERSION
                    or not _valid_prefixed_sha256(
                        policy.get("public_marker_clearance_policy_sha256")
                    )
                    or policy.get("markers_are_diagnostic_only") is not True
                )
            )
        ):
            raise CommandError("provider-free quarantine disposition policy is invalid")
        return
    if (
        run_card.get("schema_version") != "legalforecast.acquisition_run_card.v1"
        or run_card.get("stage") != "clear-disclosures"
        or run_card.get("status") != "completed"
        or run_card.get("dry_run") is not False
        or run_card.get("execute") is not True
        or run_card.get("paid_activity_executed") is not False
    ):
        raise CommandError("projection requires an executed clear-disclosures run card")
    source_commitments = run_card.get("source_commitments")
    output_commitments = run_card.get("output_commitments")
    if not isinstance(source_commitments, Mapping) or not isinstance(
        output_commitments, Mapping
    ):
        raise CommandError("clear-disclosures run card lacks commitments")
    for card_name, source_name in (
        ("download_manifest", "download_manifest"),
        ("restriction_evidence", "restriction_evidence"),
    ):
        _validate_named_path_commitment(
            cast(Mapping[str, object], source_commitments),
            name=card_name,
            expected_path=source_paths[source_name],
            expected_sha256=source_sha256[source_name],
        )
    _validate_named_path_commitment(
        cast(Mapping[str, object], output_commitments),
        name="disclosure_clearance",
        expected_path=source_paths["disclosure_clearance"],
        expected_sha256=source_sha256["disclosure_clearance"],
    )
    clearance_authority = run_card.get("clearance_authority")
    provenance_kind = (
        cast(Mapping[str, object], clearance_authority).get("kind")
        if isinstance(clearance_authority, Mapping)
        else None
    )
    if provenance_kind == "provenance_first_with_john_exceptions":
        authority_record = cast(Mapping[str, object], clearance_authority)
        if (
            authority_record.get("authentication_claim")
            != "interactive_hash_confirmation_only"
            or not _valid_prefixed_sha256(authority_record.get("cohort_policy_sha256"))
            or not _valid_prefixed_sha256(authority_record.get("routing_plan_sha256"))
            or not _valid_prefixed_sha256(
                authority_record.get("review_worksheet_sha256")
            )
            or not _valid_prefixed_sha256(
                authority_record.get("exception_decisions_sha256")
            )
            or not _valid_prefixed_sha256(
                authority_record.get("exception_review_run_card_sha256")
            )
            or authority_record.get("exception_reviewer_id") != "John Hughes"
        ):
            raise CommandError("clear-disclosures provenance authority is invalid")
        for name in (
            "review_requests",
            "case_relevance",
            "routing_plan",
            "exception_worksheet",
            "exception_decisions",
            "exception_review_run_card",
            "cohort_policy",
            "document_root",
        ):
            if not isinstance(
                cast(Mapping[str, object], source_commitments).get(name), Mapping
            ):
                raise CommandError(
                    f"clear-disclosures run card lacks {name} commitment"
                )
        return
    for name in ("reviews", "review_receipt"):
        commitment = cast(Mapping[str, object], source_commitments).get(name)
        if not isinstance(commitment, Mapping) or not _valid_prefixed_sha256(
            cast(Mapping[str, object], commitment).get("sha256")
        ):
            raise CommandError(f"clear-disclosures run card lacks {name} commitment")
    authority = run_card.get("review_authority")
    if not isinstance(authority, Mapping):
        raise CommandError("clear-disclosures run card lacks review authority")
    authority_record = cast(Mapping[str, object], authority)
    for field in (
        "reviewer_id",
        "controlled_store_uri",
        "authentication_method",
        "authenticated_at",
    ):
        value = authority_record.get(field)
        if not isinstance(value, str) or not value:
            raise CommandError(
                "clear-disclosures run card has invalid review authority"
            )
    if not cast(str, authority_record["controlled_store_uri"]).startswith(
        "private-store://"
    ) or authority_record["authentication_method"] not in {
        "human_hardware_ssh_signature",
        "controlled_store_service_ssh_signature",
    }:
        raise CommandError("clear-disclosures run card has invalid review authority")
    reviews_commitment = cast(
        Mapping[str, object],
        cast(Mapping[str, object], source_commitments)["reviews"],
    )
    if authority_record.get("review_artifact_sha256") != reviews_commitment.get(
        "sha256"
    ):
        raise CommandError("clear-disclosures review authority hash mismatch")
    if not _valid_prefixed_sha256(authority_record.get("reviewer_policy_sha256")):
        raise CommandError("clear-disclosures run card lacks reviewer policy pin")


def _validate_selection_run_card_commitment(
    run_card: Mapping[str, Any],
    *,
    selection_path: Path,
    selection_bytes: bytes,
    selection_sha256: str,
    selection_record_count: int,
    selection_run_card_path: Path | None = None,
    selection_run_card_bytes: bytes | None = None,
    verified_successor_selection_card: _VerifiedSuccessorSelectionCard | None = None,
) -> None:
    """Validate an ordinary selection card or a materializer-replayed successor.

    The generic acquisition run-card schema remains deliberately narrow.  A
    zero-cost successor is accepted here only when the materialization verifier
    has already replayed its complete predecessor chain and minted a capability
    for these exact card and selection bytes.
    """
    if run_card.get("schema_version") in _SUPPORTED_SUCCESSOR_STATE_SCHEMAS:
        if (
            selection_run_card_bytes is None
            or selection_run_card_path is None
            or verified_successor_selection_card is None
            or not verified_successor_selection_card.is_replay_minted()
        ):
            raise CommandError(
                "zero-cost successor selection requires completed materialization "
                "lineage replay"
            )
        verified_successor_selection_card.require_exact_match(
            run_card=run_card,
            run_card_bytes=selection_run_card_bytes,
            run_card_path=selection_run_card_path,
            selection_path=selection_path,
            selection_bytes=selection_bytes,
            selection_sha256=selection_sha256,
            selection_record_count=selection_record_count,
        )
        return
    if (
        run_card.get("schema_version") != "legalforecast.acquisition_run_card.v1"
        or run_card.get("stage")
        not in {"project-target-cohort", "extend-target-cohort"}
        or run_card.get("status") != "completed"
        or run_card.get("dry_run") is not False
        or run_card.get("execute") is not True
        or run_card.get("paid_activity_executed") is not False
    ):
        raise CommandError(
            "decision texts require an executed target-cohort selection run card"
        )
    record_count = run_card.get("record_count")
    if record_count != selection_record_count or selection_record_count <= 0:
        raise CommandError("target-cohort selection run card has invalid record count")
    _validate_path_keyed_output_commitment(
        run_card,
        path=selection_path,
        expected_sha256=selection_sha256,
        label="target-cohort selection",
    )


def _validate_parser_run_card_commitments(
    run_card: Mapping[str, Any],
    *,
    parser_manifest_path: Path,
    parser_manifest_sha256: str,
    clearance_path: Path,
    clearance_sha256: str,
    parser_record_count: int,
) -> None:
    if (
        run_card.get("schema_version") != "legalforecast.acquisition_run_card.v1"
        or run_card.get("stage") != "parse-documents"
        or run_card.get("status") != "completed"
        or run_card.get("dry_run") is not False
        or run_card.get("execute") is not True
        or run_card.get("paid_activity_requested") is not False
        or run_card.get("paid_activity_executed") is not False
    ):
        raise CommandError(
            "decision texts require an executed parse-documents run card"
        )
    if run_card.get("record_count") != parser_record_count or parser_record_count <= 0:
        raise CommandError("parse-documents run card has invalid record count")
    source_commitments = run_card.get("source_commitments")
    output_commitments = run_card.get("output_commitments")
    if not isinstance(source_commitments, Mapping) or not isinstance(
        output_commitments, Mapping
    ):
        raise CommandError("parse-documents run card lacks exact commitments")
    _validate_named_path_commitment(
        cast(Mapping[str, object], source_commitments),
        name="disclosure_clearance",
        expected_path=clearance_path,
        expected_sha256=clearance_sha256,
    )
    _validate_named_existing_file_commitment(
        cast(Mapping[str, object], source_commitments), name="requests"
    )
    _validate_named_path_commitment(
        cast(Mapping[str, object], output_commitments),
        name="parser_manifest",
        expected_path=parser_manifest_path,
        expected_sha256=parser_manifest_sha256,
    )
    execution = run_card.get("parser_execution")
    if not isinstance(execution, Mapping):
        raise CommandError("parse-documents run card lacks parser execution provenance")
    execution_record = cast(Mapping[str, object], execution)
    if (
        execution_record.get("mode") != "live_mistral"
        or execution_record.get("engine") != "mistral"
        or execution_record.get("parser_revision") != EXPECTED_PARSER_REVISION
        or execution_record.get("fixture_markdown") is not False
    ):
        raise CommandError(
            "decision texts require the pinned live Mistral parser execution"
        )
    parser_root = execution_record.get("parser_root")
    if not isinstance(parser_root, str) or not parser_root.strip():
        raise CommandError("parse-documents run card has invalid parser root")


def _validate_path_keyed_output_commitment(
    run_card: Mapping[str, Any],
    *,
    path: Path,
    expected_sha256: str,
    label: str,
) -> None:
    commitments = run_card.get("output_commitments")
    if not isinstance(commitments, Mapping):
        raise CommandError(f"{label} run card lacks output commitments")
    expected_path = path.resolve()
    matches = [
        digest
        for raw_path, digest in cast(Mapping[object, object], commitments).items()
        if isinstance(raw_path, str) and Path(raw_path).resolve() == expected_path
    ]
    if len(matches) != 1 or matches[0] != expected_sha256:
        raise CommandError(f"{label} commitment mismatch")


def _validate_named_existing_file_commitment(
    commitments: Mapping[str, object], *, name: str
) -> None:
    commitment = commitments.get(name)
    if not isinstance(commitment, Mapping):
        raise CommandError(f"parse-documents run card lacks {name} commitment")
    record = cast(Mapping[str, object], commitment)
    raw_path = record.get("path")
    expected_sha256 = record.get("sha256")
    if not isinstance(raw_path, str) or not _valid_prefixed_sha256(expected_sha256):
        raise CommandError(f"parse-documents run card has invalid {name} commitment")
    path = Path(raw_path)
    payload = _require_materializer_artifact(
        path, label=f"parse-documents committed {name}"
    )
    if _bytes_sha256(payload) != expected_sha256:
        raise CommandError(f"parse-documents committed {name} file changed")


def _validate_named_path_commitment(
    commitments: Mapping[str, object],
    *,
    name: str,
    expected_path: Path,
    expected_sha256: str,
) -> None:
    commitment = commitments.get(name)
    if not isinstance(commitment, Mapping):
        raise CommandError(f"clear-disclosures run card lacks {name} commitment")
    record = cast(Mapping[str, object], commitment)
    if (
        record.get("path") != str(expected_path.resolve())
        or record.get("sha256") != expected_sha256
    ):
        raise CommandError(f"clear-disclosures {name} commitment mismatch")


def _valid_prefixed_sha256(value: object) -> bool:
    return (
        isinstance(value, str)
        and re.fullmatch(r"sha256:[0-9a-f]{64}", value) is not None
    )


def _projection_jsonl_bytes(records: Iterable[Mapping[str, Any]]) -> bytes:
    return "".join(
        f"{json.dumps(dict(record), sort_keys=True, allow_nan=False)}\n"
        for record in records
    ).encode("utf-8")


def _projection_jsonl_records(payload: bytes, *, source: Path) -> list[JsonRecord]:
    records: list[JsonRecord] = []
    try:
        text = payload.decode("utf-8")
    except UnicodeDecodeError as exc:
        raise CommandError(f"projection input is not UTF-8: {source}") from exc
    for line_number, line in enumerate(text.splitlines(), start=1):
        if not line.strip():
            continue
        try:
            loaded = _loads_json(line)
        except ValueError as exc:
            raise CommandError(
                f"projection input has invalid JSON: {source}:{line_number}"
            ) from exc
        if not isinstance(loaded, Mapping):
            raise CommandError(
                f"projection input must contain JSON objects: {source}:{line_number}"
            )
        records.append(dict(cast(Mapping[str, Any], loaded)))
    return records


def _projection_committed_records(payload: bytes, *, source: Path) -> list[JsonRecord]:
    """Decode a committed JSON or JSONL artifact into records for replay."""

    try:
        text = payload.decode("utf-8")
    except UnicodeDecodeError as exc:
        raise CommandError(f"projection input is not UTF-8: {source}") from exc
    try:
        loaded = _loads_json(text)
    except ValueError:
        return _projection_jsonl_records(payload, source=source)
    if isinstance(loaded, Mapping):
        return [dict(cast(Mapping[str, Any], loaded))]
    if isinstance(loaded, Sequence) and not isinstance(loaded, (str, bytes)):
        records: list[JsonRecord] = []
        for index, item in enumerate(cast(Sequence[object], loaded)):
            if not isinstance(item, Mapping):
                raise CommandError(
                    f"projection input JSON array must contain objects: "
                    f"{source}:{index}"
                )
            records.append(dict(cast(Mapping[str, Any], item)))
        return records
    raise CommandError(f"projection input must contain JSON records: {source}")


def _projection_json_object(payload: bytes, *, source: Path) -> JsonRecord:
    try:
        loaded = _loads_json(payload.decode("utf-8"))
    except (UnicodeDecodeError, ValueError) as exc:
        raise CommandError(
            f"projection input has invalid JSON object: {source}"
        ) from exc
    if not isinstance(loaded, Mapping):
        raise CommandError(f"projection input must be a JSON object: {source}")
    return dict(cast(Mapping[str, Any], loaded))


def _bytes_sha256(payload: bytes) -> str:
    return "sha256:" + hashlib.sha256(payload).hexdigest()


def _require_packet_raw_provenance_bridge_commitment(
    bridge: VerifiedTargetRawDocketAuxiliaryProvenanceBridge,
    committed_payload: bytes,
) -> None:
    """Require the bridge's raw-hex descriptor digest in the card commitment."""

    if bridge.bridge_sha256 != _bytes_sha256(committed_payload).removeprefix("sha256:"):
        raise CommandError("packet planner raw-provenance bridge differs")


def _projection_json_bytes(payload: Mapping[str, Any]) -> bytes:
    return (
        json.dumps(dict(payload), indent=2, sort_keys=True, allow_nan=False) + "\n"
    ).encode("utf-8")


def _ensure_projection_artifact(
    path: Path,
    payload: bytes,
    *,
    resume: bool,
    stage: str = "project-target-cohort",
) -> None:
    if path.exists():
        if not resume:
            raise CommandError(f"{stage} output already exists: {path}")
        if path.is_symlink() or not path.is_file() or path.read_bytes() != payload:
            raise CommandError(f"{stage} resume artifact mismatch: {path}")
        return
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary_path: Path | None = None
    try:
        with tempfile.NamedTemporaryFile(
            mode="wb",
            dir=path.parent,
            prefix=f".{path.name}.",
            suffix=".tmp",
            delete=False,
        ) as handle:
            temporary_path = Path(handle.name)
            handle.write(payload)
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(temporary_path, path)
        directory_fd = os.open(path.parent, os.O_RDONLY)
        try:
            os.fsync(directory_fd)
        finally:
            os.close(directory_fd)
    finally:
        if temporary_path is not None and temporary_path.exists():
            temporary_path.unlink()


def _validate_disclosure_review_paths(
    *,
    input_paths: Sequence[Path],
    output_paths: Sequence[Path],
    protected_roots: Sequence[Path] = (),
) -> None:
    """Reject aliases, links, and writable overlap before private review work."""

    resolved_inputs: list[Path] = []
    for source in input_paths:
        _reject_existing_parent_symlink(source)
        if source.is_symlink() or not source.is_file():
            raise CommandError(
                f"disclosure review input is not a regular file: {source}"
            )
        metadata = source.stat(follow_symlinks=False)
        if metadata.st_nlink != 1:
            raise CommandError(
                f"disclosure review input has hard-link aliases: {source}"
            )
        resolved_inputs.append(source.resolve())
    resolved_outputs: list[Path] = []
    for output in output_paths:
        _reject_existing_parent_symlink(output)
        if output.is_symlink():
            raise CommandError(f"disclosure review output is a symlink: {output}")
        resolved = output.resolve()
        if output.exists():
            if not output.is_file():
                raise CommandError(
                    f"disclosure review output is not a regular file: {output}"
                )
            if output.stat(follow_symlinks=False).st_nlink != 1:
                raise CommandError(
                    f"disclosure review output has hard-link aliases: {output}"
                )
        if resolved in resolved_inputs:
            raise CommandError(f"disclosure review output aliases an input: {output}")
        for source, source_resolved in zip(input_paths, resolved_inputs, strict=True):
            if output.exists() and output.samefile(source):
                raise CommandError(
                    f"disclosure review output hard-links input: {output} vs {source}"
                )
            if resolved.is_relative_to(source_resolved):
                raise CommandError(
                    f"disclosure review output is nested under input: {output}"
                )
        for protected in protected_roots:
            protected_resolved = protected.resolve()
            if resolved == protected_resolved or resolved.is_relative_to(
                protected_resolved
            ):
                raise CommandError(
                    "disclosure review output overlaps protected document root: "
                    f"{output}"
                )
        resolved_outputs.append(resolved)
    if len(set(resolved_outputs)) != len(resolved_outputs):
        raise CommandError("disclosure review outputs alias one another")
    for index, output in enumerate(output_paths):
        for other in output_paths[index + 1 :]:
            if output.exists() and other.exists() and output.samefile(other):
                raise CommandError("disclosure review outputs share an inode")


def _require_controlled_private_review_root(
    private_root: Path,
    *,
    output_root: Path,
    document_root: Path,
    authenticated_inputs: Sequence[Path],
) -> None:
    """Keep private inspection material outside every acquisition source tree."""

    if not private_root.is_absolute():
        raise CommandError("controlled private review store must be an absolute path")
    _reject_existing_parent_symlink(private_root, label="controlled private root")
    resolved_private = private_root.resolve()
    resolved_output = output_root.resolve()
    resolved_document = document_root.resolve()
    common_source = Path(
        os.path.commonpath(
            [
                *(str(path.resolve().parent) for path in authenticated_inputs),
                str(resolved_document),
            ]
        )
    )
    if common_source == Path(common_source.anchor):
        raise CommandError(
            "authenticated disclosure inputs lack a bounded common source tree"
        )
    for label, root in (
        ("acquisition output", resolved_output),
        ("document root", resolved_document),
        ("authenticated preparation/source tree", common_source),
    ):
        if (
            resolved_private == root
            or resolved_private.is_relative_to(root)
            or root.is_relative_to(resolved_private)
        ):
            raise CommandError(
                f"controlled private review store must be separate from {label}"
            )


def _reject_existing_parent_symlink(
    path: Path, *, label: str = "disclosure review output"
) -> None:
    # Preserve the caller's original components, including ``..``. Resolving or
    # applying ``abspath`` first would erase ``symlink/..`` even though the
    # kernel follows the symlink before processing the parent traversal.
    parent = path.parent
    if parent.is_absolute():
        current = Path(parent.anchor)
        components = parent.parts[1:]
    else:
        current = Path.cwd()
        components = parent.parts
    for component in components:
        if component in {"", "."}:
            continue
        if component == "..":
            current = current.parent
            continue
        current = current / component
        if current.is_symlink():
            raise CommandError(f"{label} parent is a symlink: {current}")


def _stable_regular_file_identity(value: os.stat_result) -> tuple[int, ...]:
    return (
        value.st_dev,
        value.st_ino,
        value.st_mode,
        value.st_size,
        value.st_mtime_ns,
        value.st_ctime_ns,
        value.st_nlink,
    )


def _read_singly_linked_regular_input(path: Path, *, label: str) -> bytes:
    """Read one immutable input without following a final symlink."""

    _reject_existing_parent_symlink(path, label=label)
    try:
        lexical_before = path.lstat()
    except OSError as exc:
        raise CommandError(
            f"{label} must be a singly linked regular non-symlink file: {path}"
        ) from exc
    if not stat.S_ISREG(lexical_before.st_mode) or lexical_before.st_nlink != 1:
        raise CommandError(
            f"{label} must be a singly linked regular non-symlink file: {path}"
        )
    flags = os.O_RDONLY | getattr(os, "O_CLOEXEC", 0) | getattr(os, "O_NOFOLLOW", 0)
    try:
        descriptor = os.open(path, flags)
    except OSError as exc:
        raise CommandError(
            f"{label} must be a singly linked regular non-symlink file: {path}"
        ) from exc
    try:
        before = os.fstat(descriptor)
        if not stat.S_ISREG(before.st_mode) or before.st_nlink != 1:
            raise CommandError(
                f"{label} must be a singly linked regular non-symlink file: {path}"
            )
        with os.fdopen(descriptor, "rb", closefd=False) as handle:
            payload = handle.read()
        after = os.fstat(descriptor)
        lexical_after = path.lstat()
        stable_identity = (
            _stable_regular_file_identity(lexical_before)
            == _stable_regular_file_identity(before)
            == _stable_regular_file_identity(after)
            == _stable_regular_file_identity(lexical_after)
        )
        if (
            not stable_identity
            or not stat.S_ISREG(after.st_mode)
            or after.st_nlink != 1
        ):
            raise CommandError(f"{label} changed while it was being read: {path}")
        collector = _VERIFIED_PROJECTION_BYTE_COLLECTOR.get()
        if collector is not None:
            key = os.path.abspath(path)
            existing = collector.get(key)
            if existing is not None and existing != payload:
                raise CommandError("verified projection byte closure conflicts")
            collector[key] = payload
        return payload
    except OSError as exc:
        raise CommandError(f"{label} could not be read safely: {path}: {exc}") from exc
    finally:
        os.close(descriptor)


def _captured_or_stable_input(
    path: Path,
    *,
    label: str,
    captured_artifact_bytes: Mapping[str, bytes] | None,
) -> bytes:
    """Return caller-captured bytes or take one descriptor-stable snapshot."""

    key = os.path.abspath(path)
    if captured_artifact_bytes is not None:
        if key not in captured_artifact_bytes:
            raise CommandError(f"verified input snapshot lacks {label}: {path}")
        return captured_artifact_bytes[key]
    return _read_singly_linked_regular_input(path, label=label)


def _clearance_snapshot_paths(
    run_card: Mapping[str, Any],
    *,
    run_card_path: Path,
    clearance_path: Path,
) -> set[Path]:
    paths = {run_card_path, clearance_path}
    for group_name in ("source_commitments", "output_commitments"):
        group = run_card.get(group_name)
        if not isinstance(group, Mapping):
            raise CommandError(f"clearance run card lacks {group_name}")
        for raw in cast(Mapping[str, object], group).values():
            if not isinstance(raw, Mapping):
                continue
            record = cast(Mapping[str, object], raw)
            path_text = record.get("path")
            if (
                isinstance(path_text, str)
                and path_text
                and isinstance(record.get("sha256"), str)
            ):
                paths.add(Path(path_text))
    return paths


def _capture_clearance_artifact_snapshot(
    *,
    run_card: Mapping[str, Any],
    run_card_path: Path,
    clearance_path: Path,
    initial_artifact_bytes: Mapping[str, bytes],
) -> dict[str, bytes]:
    """Finish one immutable snapshot before any clearance replay begins."""

    snapshot = dict(initial_artifact_bytes)
    for path in _clearance_snapshot_paths(
        run_card, run_card_path=run_card_path, clearance_path=clearance_path
    ):
        key = os.path.abspath(path)
        if key not in snapshot:
            snapshot[key] = _read_singly_linked_regular_input(
                path, label="committed clearance artifact"
            )
    return snapshot


def _complete_clearance_artifact_snapshot(
    *,
    run_card: Mapping[str, Any],
    run_card_path: Path,
    run_card_bytes: bytes,
    clearance_path: Path,
    captured_artifact_bytes: Mapping[str, bytes] | None,
) -> dict[str, bytes]:
    """Require a supplied snapshot to be complete; otherwise capture it once."""

    if captured_artifact_bytes is None:
        return _capture_clearance_artifact_snapshot(
            run_card=run_card,
            run_card_path=run_card_path,
            clearance_path=clearance_path,
            initial_artifact_bytes={os.path.abspath(run_card_path): run_card_bytes},
        )
    snapshot = dict(captured_artifact_bytes)
    required = {
        os.path.abspath(path)
        for path in _clearance_snapshot_paths(
            run_card, run_card_path=run_card_path, clearance_path=clearance_path
        )
    }
    missing = sorted(required - set(snapshot))
    if missing:
        raise CommandError(
            "verified clearance snapshot lacks committed artifacts: " + repr(missing)
        )
    if snapshot[os.path.abspath(run_card_path)] != run_card_bytes:
        raise CommandError("verified clearance snapshot run card changed")
    return snapshot


def _open_disclosure_review_parent(path: Path, *, create: bool) -> int:
    """Open one lexical directory path without following any component."""

    nofollow = getattr(os, "O_NOFOLLOW", None)
    directory = getattr(os, "O_DIRECTORY", None)
    if nofollow is None or directory is None:
        raise CommandError("disclosure review publication requires no-follow support")
    absolute = Path(os.path.abspath(path))
    flags = os.O_RDONLY | os.O_CLOEXEC | nofollow | directory
    directory_fd: int | None = None
    try:
        directory_fd = os.open(absolute.anchor, flags)
        for component in absolute.parts[1:]:
            try:
                next_fd = os.open(component, flags, dir_fd=directory_fd)
            except FileNotFoundError:
                if not create:
                    raise
                os.mkdir(component, mode=0o700, dir_fd=directory_fd)
                next_fd = os.open(component, flags, dir_fd=directory_fd)
            os.close(directory_fd)
            directory_fd = next_fd
        return directory_fd
    except CommandError:
        if directory_fd is not None:
            os.close(directory_fd)
        raise
    except OSError as exc:
        if directory_fd is not None:
            os.close(directory_fd)
        raise CommandError(
            f"disclosure review output parent is unsafe: {path}"
        ) from exc


def _disclosure_review_parent_is_current(path: Path, directory_fd: int) -> bool:
    try:
        live_fd = _open_disclosure_review_parent(path, create=False)
    except CommandError:
        return False
    try:
        held = os.fstat(directory_fd)
        live = os.fstat(live_fd)
        return (
            stat.S_ISDIR(held.st_mode)
            and stat.S_ISDIR(live.st_mode)
            and (held.st_dev, held.st_ino) == (live.st_dev, live.st_ino)
        )
    finally:
        os.close(live_fd)


def _read_disclosure_review_artifact_at(directory_fd: int, name: str) -> bytes | None:
    flags = os.O_RDONLY | os.O_NONBLOCK | os.O_CLOEXEC | getattr(os, "O_NOFOLLOW", 0)
    try:
        file_fd = os.open(name, flags, dir_fd=directory_fd)
    except FileNotFoundError:
        return None
    except OSError as exc:
        raise CommandError(
            f"disclosure review output must be a unique regular file: {name}"
        ) from exc
    try:
        before = os.fstat(file_fd)
        if not stat.S_ISREG(before.st_mode) or before.st_nlink != 1:
            raise CommandError(
                f"disclosure review output must be a unique regular file: {name}"
            )
        chunks: list[bytes] = []
        while chunk := os.read(file_fd, 1024 * 1024):
            chunks.append(chunk)
        payload = b"".join(chunks)
        after = os.fstat(file_fd)
        try:
            named = os.stat(name, dir_fd=directory_fd, follow_symlinks=False)
        except OSError as exc:
            raise CommandError(
                f"disclosure review output changed while being read: {name}"
            ) from exc
        if (
            _stable_regular_file_identity(before)
            != _stable_regular_file_identity(after)
            or _stable_regular_file_identity(named)
            != _stable_regular_file_identity(after)
            or len(payload) != after.st_size
        ):
            raise CommandError(
                f"disclosure review output changed while being read: {name}"
            )
        return payload
    finally:
        os.close(file_fd)


def _recover_disclosure_review_publish_alias_at(directory_fd: int, name: str) -> None:
    """Remove only same-inode private temp links left by an interrupted publish."""

    try:
        metadata = os.stat(name, dir_fd=directory_fd, follow_symlinks=False)
    except FileNotFoundError:
        return
    if not stat.S_ISREG(metadata.st_mode) or metadata.st_nlink <= 1:
        return
    aliases: list[str] = []
    prefix = f".{name}."
    for candidate in os.listdir(directory_fd):
        if not candidate.startswith(prefix) or not candidate.endswith(".tmp"):
            continue
        try:
            candidate_metadata = os.stat(
                candidate, dir_fd=directory_fd, follow_symlinks=False
            )
        except OSError:
            continue
        if (
            stat.S_ISREG(candidate_metadata.st_mode)
            and candidate_metadata.st_ino == metadata.st_ino
            and candidate_metadata.st_dev == metadata.st_dev
        ):
            aliases.append(candidate)
    for alias in aliases:
        os.unlink(alias, dir_fd=directory_fd)
    if aliases:
        os.fsync(directory_fd)


def _recover_disclosure_review_publish_alias(path: Path) -> None:
    """Recover an interrupted alias while preserving the lexical parent binding."""

    directory_fd = _open_disclosure_review_parent(path.parent, create=False)
    try:
        _recover_disclosure_review_publish_alias_at(directory_fd, path.name)
        if not _disclosure_review_parent_is_current(path.parent, directory_fd):
            raise CommandError(
                "disclosure review output parent path binding changed "
                f"during recovery: {path.parent}"
            )
    finally:
        os.close(directory_fd)


def _ensure_disclosure_review_artifact(
    path: Path, payload: bytes, *, resume: bool
) -> None:
    """Publish one immutable artifact through one authenticated parent fd."""

    _reject_existing_parent_symlink(path)
    directory_fd = _open_disclosure_review_parent(path.parent, create=True)
    temporary_name = f".{path.name}.{uuid.uuid4().hex}.tmp"
    temporary_created = False
    published_identity: tuple[int, int] | None = None
    try:
        if resume:
            _recover_disclosure_review_publish_alias_at(directory_fd, path.name)
        existing_payload = _read_disclosure_review_artifact_at(directory_fd, path.name)
        if existing_payload is not None:
            if not resume:
                raise CommandError(f"disclosure review output already exists: {path}")
            if existing_payload != payload:
                raise CommandError(
                    f"disclosure review resume artifact mismatch: {path}"
                )
            if not _disclosure_review_parent_is_current(path.parent, directory_fd):
                raise CommandError(
                    "disclosure review output parent path binding changed "
                    f"during publication: {path.parent}"
                )
            return

        flags = (
            os.O_WRONLY
            | os.O_CREAT
            | os.O_EXCL
            | os.O_CLOEXEC
            | getattr(os, "O_NOFOLLOW", 0)
        )
        temporary_fd = os.open(temporary_name, flags, 0o600, dir_fd=directory_fd)
        temporary_created = True
        try:
            view = memoryview(payload)
            while view:
                written = os.write(temporary_fd, view)
                if written <= 0:  # pragma: no cover - OS invariant
                    raise CommandError(f"disclosure review output short write: {path}")
                view = view[written:]
            os.fsync(temporary_fd)
            temporary_metadata = os.fstat(temporary_fd)
            published_identity = (
                temporary_metadata.st_dev,
                temporary_metadata.st_ino,
            )
        finally:
            os.close(temporary_fd)
        try:
            os.link(
                temporary_name,
                path.name,
                src_dir_fd=directory_fd,
                dst_dir_fd=directory_fd,
                follow_symlinks=False,
            )
        except FileExistsError:
            published_identity = None
            competing = _read_disclosure_review_artifact_at(directory_fd, path.name)
            if not resume or competing != payload:
                raise CommandError(
                    f"disclosure review output appeared concurrently: {path}"
                ) from None
        os.unlink(temporary_name, dir_fd=directory_fd)
        temporary_created = False
        os.fsync(directory_fd)
        if _read_disclosure_review_artifact_at(directory_fd, path.name) != payload:
            raise CommandError(
                f"disclosure review output changed during publication: {path}"
            )
        if not _disclosure_review_parent_is_current(path.parent, directory_fd):
            if published_identity is not None:
                try:
                    target = os.stat(
                        path.name, dir_fd=directory_fd, follow_symlinks=False
                    )
                except FileNotFoundError:
                    target = None
                if (
                    target is not None
                    and (
                        target.st_dev,
                        target.st_ino,
                    )
                    == published_identity
                ):
                    os.unlink(path.name, dir_fd=directory_fd)
                    os.fsync(directory_fd)
            raise CommandError(
                "disclosure review output parent path binding changed "
                f"during publication: {path.parent}"
            )
    except CommandError:
        raise
    except OSError as exc:
        raise CommandError(
            f"disclosure review output cannot be safely published: {path}"
        ) from exc
    finally:
        if temporary_created:
            try:
                os.unlink(temporary_name, dir_fd=directory_fd)
                os.fsync(directory_fd)
            except FileNotFoundError:
                # The successful hard-link path already consumed the temp name.
                pass
        os.close(directory_fd)


def _disclosure_review_metadata_paths(
    args: argparse.Namespace, *, output_root: Path, stage: str
) -> tuple[Path, Path]:
    return (
        _acquisition_path(
            args, "run_card_output", output_root / "run-cards" / f"{stage}.json"
        ),
        _acquisition_path(args, "log_output", output_root / "logs" / f"{stage}.jsonl"),
    )


def _append_disclosure_review_log(
    path: Path, records: Iterable[Mapping[str, Any]]
) -> None:
    """Durably append disclosure metadata without following filesystem links."""

    nofollow = getattr(os, "O_NOFOLLOW", None)
    if nofollow is None:
        raise CommandError("disclosure metadata requires O_NOFOLLOW")
    payload = "".join(
        f"{json.dumps(dict(record), sort_keys=True, allow_nan=False)}\n"
        for record in records
    ).encode()
    _reject_existing_parent_symlink(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    _reject_existing_parent_symlink(path)
    file_fd: int | None = None
    try:
        file_fd = os.open(
            path,
            os.O_WRONLY | os.O_APPEND | os.O_CREAT | os.O_CLOEXEC | nofollow,
            0o600,
        )
        before = os.fstat(file_fd)
        if not stat.S_ISREG(before.st_mode) or before.st_nlink != 1:
            raise CommandError(f"disclosure review log is unsafe: {path}")
        remaining = memoryview(payload)
        while remaining:
            written = os.write(file_fd, remaining)
            if written <= 0:
                raise OSError("disclosure review log append made no progress")
            remaining = remaining[written:]
        os.fsync(file_fd)
        after = os.fstat(file_fd)
        if (
            after.st_dev != before.st_dev
            or after.st_ino != before.st_ino
            or not stat.S_ISREG(after.st_mode)
            or after.st_nlink != 1
            or after.st_size < before.st_size + len(payload)
        ):
            raise CommandError(f"disclosure review log changed while appending: {path}")
    finally:
        if file_fd is not None:
            os.close(file_fd)
    directory_fd = os.open(path.parent, os.O_RDONLY | os.O_DIRECTORY | os.O_CLOEXEC)
    try:
        os.fsync(directory_fd)
    finally:
        os.close(directory_fd)


def _completed_disclosure_review_resume(
    args: argparse.Namespace,
    *,
    stage: str,
    input_paths: Sequence[Path],
    output_paths: Sequence[Path],
    record_count: int,
    expected_extra: Mapping[str, object] | None = None,
    expected_log_extra: Mapping[str, object] | None = None,
    repair_terminal_metadata: bool = True,
    validate_without_resume: bool = False,
) -> bool:
    """Return without mutating an already completed exact stage record."""

    if not validate_without_resume and (
        not cast(bool, args.resume) or _acquisition_dry_run(args)
    ):
        return False
    output_root = _acquisition_output_root(args)
    run_card_path, log_path = _disclosure_review_metadata_paths(
        args, output_root=output_root, stage=stage
    )
    if not run_card_path.exists() and not log_path.exists():
        return False
    regular_inputs = tuple(
        path for path in (*input_paths, *output_paths) if path.is_file()
    )
    protected_roots = tuple(path for path in input_paths if path.is_dir())
    _validate_disclosure_review_paths(
        input_paths=regular_inputs,
        output_paths=(run_card_path, log_path),
        protected_roots=protected_roots,
    )
    expected: dict[str, object] = {
        "schema_version": "legalforecast.acquisition_run_card.v1",
        "stage": stage,
        "status": "completed",
        "dry_run": False,
        "execute": True,
        "record_count": record_count,
        "input_paths": [str(path) for path in input_paths],
        "output_paths": [str(path) for path in output_paths],
        "paid_activity_requested": False,
        "paid_activity_executed": False,
    }
    if expected_extra is not None:
        for name, value in expected_extra.items():
            if name in expected:
                raise CommandError(f"{stage} resume expectation repeats {name}")
            expected[name] = value
    run_card: JsonRecord | None = None
    card_completed = False
    if run_card_path.exists():
        if not run_card_path.is_file():
            raise CommandError(f"{stage} resume run card is unsafe")
        run_card = _read_json_object(run_card_path)
        status = run_card.get("status")
        if status == "completed":
            planning_card = (
                run_card.get("dry_run") is True and run_card.get("execute") is False
            )
            if set(run_card) != {*expected, "resume", "generated_at"}:
                raise CommandError(f"{stage} completed resume metadata mismatch")
            card_expectation = (
                {
                    "schema_version": "legalforecast.acquisition_run_card.v1",
                    "stage": stage,
                    "status": "completed",
                    "dry_run": True,
                    "execute": False,
                    "paid_activity_requested": False,
                    "paid_activity_executed": False,
                }
                if planning_card
                else expected
            )
            if any(
                run_card.get(name) != value for name, value in card_expectation.items()
            ):
                raise CommandError(f"{stage} completed resume metadata mismatch")
            if not isinstance(run_card.get("resume"), bool):
                raise CommandError(f"{stage} completed resume flag is invalid")
            generated_at = run_card.get("generated_at")
            if not isinstance(generated_at, str):
                raise CommandError(f"{stage} completed resume timestamp is invalid")
            try:
                _parse_datetime(generated_at)
            except (TypeError, ValueError) as exc:
                raise CommandError(
                    f"{stage} completed resume timestamp is invalid"
                ) from exc
            card_completed = not planning_card
        elif status == "failed":
            expected_failure: dict[str, object] = {
                **{
                    name: value
                    for name, value in expected.items()
                    if name not in {"status", "record_count"}
                    and (expected_extra is None or name not in expected_extra)
                },
                "status": "failed",
                "record_count": 0,
            }
            if set(run_card) != {
                *expected_failure,
                "resume",
                "generated_at",
                "failure_reason",
            } or any(
                run_card.get(name) != value for name, value in expected_failure.items()
            ):
                raise CommandError(f"{stage} failed resume metadata mismatch")
            if not isinstance(run_card.get("resume"), bool) or not isinstance(
                run_card.get("failure_reason"), str
            ):
                raise CommandError(f"{stage} failed resume metadata mismatch")
            try:
                _parse_datetime(cast(str, run_card.get("generated_at")))
            except (TypeError, ValueError) as exc:
                raise CommandError(
                    f"{stage} failed resume timestamp is invalid"
                ) from exc
        else:
            raise CommandError(f"{stage} resume metadata mismatch")
    log_records = _read_records(log_path) if log_path.exists() else []
    log_extra = dict(expected_log_extra or {})
    log_completed = _validate_disclosure_review_resume_log(
        log_records,
        stage=stage,
        run_card_path=run_card_path,
        record_count=record_count,
        expected_log_schema_version=(
            _DISCLOSURE_PROVENANCE_STAGE_LOG_SCHEMA_VERSION
            if expected_log_extra
            else _ACQUISITION_STAGE_LOG_SCHEMA_VERSION
        ),
        expected_log_extra=expected_log_extra,
    )
    if card_completed and log_completed:
        return True
    if not card_completed and not log_completed:
        # A durable failure history is retryable after its inputs are repaired.
        return False
    if not repair_terminal_metadata:
        return True
    if card_completed:
        _append_disclosure_review_log(
            log_path,
            [
                {
                    "schema_version": (
                        _DISCLOSURE_PROVENANCE_STAGE_LOG_SCHEMA_VERSION
                        if log_extra
                        else _ACQUISITION_STAGE_LOG_SCHEMA_VERSION
                    ),
                    "event": "stage_completed",
                    "stage": stage,
                    "status": "completed",
                    "dry_run": False,
                    "run_card_path": str(run_card_path),
                    "record_count": record_count,
                    "paid_activity_requested": False,
                    "paid_activity_executed": False,
                    **log_extra,
                }
            ],
        )
        return True
    repaired_card: JsonRecord = {
        **expected,
        "resume": cast(bool, args.resume),
        "generated_at": _iso_datetime(datetime.now(UTC)),
    }
    _atomic_write_json(run_card_path, repaired_card)
    return True


def _validate_disclosure_review_resume_log(
    log_records: Sequence[Mapping[str, object]],
    *,
    stage: str,
    run_card_path: Path,
    record_count: int,
    expected_log_schema_version: str,
    expected_log_extra: Mapping[str, object] | None,
) -> bool:
    """Validate the complete closed terminal-log history without writing."""

    base_log_fields = {
        "schema_version",
        "event",
        "stage",
        "status",
        "dry_run",
        "run_card_path",
        "record_count",
        "paid_activity_requested",
        "paid_activity_executed",
    }
    log_extra = dict(expected_log_extra or {})
    if set(log_extra) & base_log_fields:
        raise CommandError(f"{stage} resume log expectation repeats a base field")
    log_completed = False
    for index, record in enumerate(log_records):
        status = record.get("status")
        if status not in {"failed", "completed"}:
            raise CommandError(f"{stage} completed resume log mismatch")
        planning_record = record.get("dry_run") is True
        if status == "completed" and not planning_record:
            if log_completed or index != len(log_records) - 1:
                raise CommandError(f"{stage} completed resume log mismatch")
            log_completed = True
        event = "stage_completed" if status == "completed" else "stage_failed"
        count = record_count if status == "completed" else 0
        common_log_expectation = {
            "schema_version": (
                expected_log_schema_version
                if status == "completed"
                else _ACQUISITION_STAGE_LOG_SCHEMA_VERSION
            ),
            "stage": stage,
            "status": status,
            "event": event,
            "run_card_path": str(run_card_path),
            "paid_activity_requested": False,
            "paid_activity_executed": False,
        }
        expected_log_fields = (
            base_log_fields | set(log_extra)
            if status == "completed"
            else base_log_fields
        )
        expected_log_values = (
            {**common_log_expectation, **log_extra}
            if status == "completed"
            else common_log_expectation
        )
        if set(record) != expected_log_fields or any(
            record.get(name) != value for name, value in expected_log_values.items()
        ):
            raise CommandError(f"{stage} completed resume log mismatch")
        if planning_record:
            if (
                type(record.get("record_count")) is not int
                or cast(int, record.get("record_count")) < 0
                or (status == "failed" and record.get("record_count") != 0)
            ):
                raise CommandError(f"{stage} completed resume log mismatch")
            continue
        if record.get("dry_run") is not False or record.get("record_count") != count:
            raise CommandError(f"{stage} completed resume log mismatch")
    return log_completed


def _write_disclosure_review_failure(
    args: argparse.Namespace,
    *,
    stage: str,
    input_paths: Sequence[Path],
    output_paths: Sequence[Path],
    reason: str,
) -> None:
    """Never replace or append to an already completed disclosure stage record."""

    output_root = _acquisition_output_root(args)
    run_card_path, log_path = _disclosure_review_metadata_paths(
        args, output_root=output_root, stage=stage
    )
    regular_inputs = tuple(
        path for path in (*input_paths, *output_paths) if path.is_file()
    )
    protected_roots = tuple(path for path in input_paths if path.is_dir())
    _validate_disclosure_review_paths(
        input_paths=regular_inputs,
        output_paths=(run_card_path, log_path),
        protected_roots=protected_roots,
    )
    completed = False
    if run_card_path.exists():
        try:
            completed = _read_json_object(run_card_path).get("status") == "completed"
        except (OSError, UnicodeError, ValueError):
            completed = True
    if log_path.exists():
        try:
            completed = completed or any(
                row.get("status") == "completed" for row in _read_records(log_path)
            )
        except (OSError, UnicodeError, ValueError):
            completed = True
    if completed:
        raise CommandError(
            f"{stage} already has terminal completion metadata; refusing failure write"
        )
    _write_acquisition_failure(
        args,
        stage=stage,
        input_paths=input_paths,
        output_paths=output_paths,
        reason=reason,
        paid_activity_requested=False,
        resumable_terminal_metadata=True,
    )


def _target_100_protected_scopes(
    args: argparse.Namespace,
) -> list[tuple[str, Path, bool]]:
    snapshot = cast(Path, args.snapshot)
    scopes: list[tuple[str, Path, bool]] = [("--snapshot", snapshot, True)]
    for label, path, is_tree in (
        ("snapshot manifest", snapshot / "manifest.json", False),
        ("--raw-html-dir", cast(Path | None, args.raw_html_dir), True),
        ("--fixture-documents", cast(Path | None, args.fixture_documents), False),
        (
            "--courtlistener-fixture",
            cast(Path | None, args.courtlistener_fixture),
            False,
        ),
        ("--request-ledger", cast(Path | None, args.request_ledger), False),
    ):
        if path is not None:
            scopes.append((label, path, is_tree))
    request_ledger = cast(Path | None, args.request_ledger)
    if request_ledger is not None:
        scopes.extend(
            (f"--request-ledger {suffix}", Path(f"{request_ledger}{suffix}"), False)
            for suffix in ("-wal", "-shm", "-journal")
        )
    return scopes


def _target_100_protected_paths(args: argparse.Namespace) -> tuple[Path, ...]:
    return tuple(path for _, path, _ in _target_100_protected_scopes(args))


def _validate_target_100_paths(
    *,
    args: argparse.Namespace,
    profile: _TargetPreparationProfile,
    output_root: Path,
    summary_path: Path,
    snapshot: Path,
    raw_html_dir: Path | None,
    fixture_documents: Path | None,
    courtlistener_fixture: Path | None,
    request_ledger: Path | None,
) -> None:
    """Reject every preparation writable/protected alias before writing."""

    del snapshot, raw_html_dir, fixture_documents, courtlistener_fixture, request_ledger
    writable_scopes: list[tuple[str, Path, bool]] = [
        ("--output-root", output_root, True),
        (f"{profile.label} attempt tree", output_root / "attempts", True),
        ("--summary-output", summary_path, False),
        (
            "--run-card-output",
            _acquisition_path(
                args,
                "run_card_output",
                output_root / f"run-cards/{profile.stage}.json",
            ),
            False,
        ),
        (
            "--log-output",
            _acquisition_path(
                args,
                "log_output",
                output_root / f"logs/{profile.stage}.jsonl",
            ),
            False,
        ),
    ]
    protected_scopes = _target_100_protected_scopes(args)
    controlled_defaults = {
        "summary_output": output_root / profile.summary_filename,
        "run_card_output": output_root / f"run-cards/{profile.stage}.json",
        "log_output": output_root / f"logs/{profile.stage}.jsonl",
    }
    for attribute, default in controlled_defaults.items():
        configured = cast(Path | None, getattr(args, attribute))
        if (
            configured is not None
            and configured.resolve() != default.resolve()
            and configured.resolve().is_relative_to(output_root.resolve())
        ):
            raise CommandError(
                f"--{attribute.replace('_', '-')} custom path must be outside the "
                f"controlled {profile.label} output tree"
            )
    for writable_label, writable_path, writable_tree in writable_scopes:
        writable = writable_path.resolve()
        if not writable_tree:
            _reject_hardlinked_writable_replay_scope(
                label=writable_label,
                path=writable,
                is_tree=False,
            )
        for protected_label, protected_path, protected_tree in protected_scopes:
            protected = protected_path.resolve()
            if _replay_scopes_overlap(
                left_label=writable_label,
                left=writable,
                left_tree=writable_tree,
                right_label=protected_label,
                right=protected,
                right_tree=protected_tree,
            ):
                raise CommandError(
                    f"{profile.label} writable output overlaps protected input: "
                    f"{writable_label} vs {protected_label}: "
                    f"{writable} vs {protected}"
                )

    file_writes = [scope for scope in writable_scopes if not scope[2]]
    for index, (label, path, _) in enumerate(file_writes):
        resolved = path.resolve()
        for other_label, other_path, _ in file_writes[index + 1 :]:
            other = other_path.resolve()
            if _replay_scopes_overlap(
                left_label=label,
                left=resolved,
                left_tree=False,
                right_label=other_label,
                right=other,
                right_tree=False,
            ):
                raise CommandError(
                    f"{profile.label} writable outputs alias: "
                    f"{label} vs {other_label}: {resolved} vs {other}"
                )

    _reject_target_100_tree_hardlink_aliases(
        output_root=output_root,
        protected_scopes=protected_scopes,
    )


def _reject_target_100_tree_hardlink_aliases(
    *,
    output_root: Path,
    protected_scopes: Sequence[tuple[str, Path, bool]],
) -> None:
    if not output_root.exists() or not output_root.is_dir():
        return
    protected_identities: dict[tuple[int, int], str] = {}
    for label, path, is_tree in protected_scopes:
        candidates = path.rglob("*") if is_tree and path.is_dir() else (path,)
        for candidate in candidates:
            if not candidate.is_file():
                continue
            try:
                metadata = candidate.stat()
            except OSError as exc:
                raise CommandError(
                    f"cannot inspect {label} for hard-link aliases: {candidate}: {exc}"
                ) from exc
            protected_identities[(metadata.st_dev, metadata.st_ino)] = label
    for candidate in output_root.rglob("*"):
        if not candidate.is_file():
            continue
        try:
            metadata = candidate.stat()
        except OSError as exc:
            raise CommandError(
                f"cannot inspect --output-root for hard-link aliases: "
                f"{candidate}: {exc}"
            ) from exc
        protected_label = protected_identities.get((metadata.st_dev, metadata.st_ino))
        if protected_label is not None:
            raise CommandError(
                "target-100 output tree contains a hard-link alias to protected "
                f"input {protected_label}: {candidate}"
            )


def _write_target_100_attempt_failure(
    args: argparse.Namespace,
    *,
    profile: _TargetPreparationProfile,
    reason: str,
    protected_paths: Sequence[Path],
    extra: Mapping[str, Any] | None = None,
) -> Path:
    """Write a unique nonpaid failure card without replacing canonical success."""

    output_root = cast(Path, args.output_root).resolve()
    candidates = (
        (output_root / "attempts").resolve(),
        (Path(tempfile.gettempdir()) / "legalforecast-attempts").resolve(),
        (Path.cwd() / ".legalforecast-attempts").resolve(),
        (Path.home() / ".cache/legalforecast/attempts").resolve(),
    )
    protected = tuple(path.resolve() for path in protected_paths)
    output_tree_safe = all(
        output_root != path
        and not output_root.is_relative_to(path)
        and not path.is_relative_to(output_root)
        for path in protected
    )
    attempt_parent = next(
        (
            candidate
            for candidate in candidates
            if (candidate != candidates[0] or output_tree_safe)
            and all(
                candidate != path
                and not candidate.is_relative_to(path)
                and not path.is_relative_to(candidate)
                for path in protected
            )
        ),
        None,
    )
    if attempt_parent is None:
        raise CommandError(
            f"{profile.label} failure could not select a safe attempt-card directory"
        )
    attempt_id = f"{datetime.now(UTC).strftime('%Y%m%dT%H%M%S.%fZ')}-{uuid.uuid4().hex}"
    attempt_root = attempt_parent / profile.stage / attempt_id
    run_card_path = attempt_root / "run-card.json"
    record: JsonRecord = {
        "schema_version": profile.attempt_schema,
        "attempt_id": attempt_id,
        "stage": profile.stage,
        "status": "failed",
        "failure_reason": reason,
        "dry_run": _acquisition_dry_run(args),
        "paid_activity_requested": False,
        "paid_activity_executed": False,
        "requested_output_root": str(output_root),
        "generated_at": _iso_datetime(datetime.now(UTC)),
    }
    if extra is not None:
        record.update(extra)
    _write_json(run_card_path, record)
    _log_event(profile.stage, "attempt_failed", run_card_path, 0)
    return run_card_path


def _materialize_target_authenticated_raw_html(
    *,
    output_root: Path,
    raw_html_bytes_by_candidate: Mapping[str, bytes] | None,
    resume: bool,
) -> tuple[Path | None, Path | None, str | None]:
    """Own the exact snapshot-admitted raw bytes used by target child stages."""

    if raw_html_bytes_by_candidate is None:
        return None, None, None
    if not raw_html_bytes_by_candidate:
        raise CommandError("authenticated raw-HTML projection is unexpectedly empty")
    raw_html_dir = output_root / "00-authenticated-snapshot/raw-html"
    manifest_path = output_root / "00-authenticated-snapshot/raw-html-manifest.jsonl"
    manifest_rows: list[JsonRecord] = []
    for candidate_id, payload in sorted(raw_html_bytes_by_candidate.items()):
        if (
            not candidate_id
            or candidate_id in {".", ".."}
            or "/" in candidate_id
            or "\\" in candidate_id
            or "\x00" in candidate_id
        ):
            raise CommandError(
                f"authenticated raw-HTML candidate identity is unsafe: {candidate_id!r}"
            )
        relative_path = f"{candidate_id}.html"
        destination = raw_html_dir / relative_path
        _write_immutable_bytes(destination, payload, resume=resume)
        manifest_rows.append(
            {
                "candidate_id": candidate_id,
                "relative_path": relative_path,
                "sha256": "sha256:" + hashlib.sha256(payload).hexdigest(),
                "byte_count": len(payload),
            }
        )
    manifest_payload = _jsonl_bytes(manifest_rows)
    _write_immutable_bytes(manifest_path, manifest_payload, resume=resume)
    return (
        raw_html_dir,
        manifest_path,
        hashlib.sha256(manifest_payload).hexdigest(),
    )


def _verified_target_authenticated_input_commitments(
    config: TargetCohortPreparationConfig | Target100PreparationConfig,
) -> dict[str, str]:
    """Reauthenticate target-owned screened and raw inputs without source rereads."""

    return _verified_target_authenticated_paths(
        screened_cases=config.authenticated_screened_cases,
        screened_cases_sha256=config.screened_cases_sha256,
        raw_html_dir=config.raw_html_dir,
        raw_html_manifest=config.authenticated_raw_html_manifest,
        raw_html_manifest_sha256=config.authenticated_raw_html_manifest_sha256,
    )


def _verified_target_authenticated_paths(
    *,
    screened_cases: Path,
    screened_cases_sha256: str,
    raw_html_dir: Path | None,
    raw_html_manifest: Path | None,
    raw_html_manifest_sha256: str | None,
) -> dict[str, str]:
    """Verify the exact owned files represented by a frozen target config."""

    if (
        screened_cases.is_symlink()
        or not screened_cases.is_file()
        or screened_cases.stat().st_nlink != 1
    ):
        raise CommandError(
            "authenticated screened-cases input is not a singly linked regular file"
        )
    screened_payload = screened_cases.read_bytes()
    screened_digest = hashlib.sha256(screened_payload).hexdigest()
    if screened_digest != screened_cases_sha256:
        raise CommandError("authenticated screened-cases commitment mismatch")
    commitments = {str(screened_cases.resolve()): "sha256:" + screened_cases_sha256}

    raw_values = (
        raw_html_dir,
        raw_html_manifest,
        raw_html_manifest_sha256,
    )
    if all(value is None for value in raw_values):
        return commitments
    if any(value is None for value in raw_values):
        raise CommandError(
            "authenticated raw-HTML directory, manifest, and digest must be paired"
        )
    raw_html_dir = cast(Path, raw_html_dir)
    manifest_path = cast(Path, raw_html_manifest)
    expected_manifest_sha256 = cast(str, raw_html_manifest_sha256)
    if raw_html_dir.is_symlink() or not raw_html_dir.is_dir():
        raise CommandError("authenticated raw-HTML directory is missing or a symlink")
    if (
        manifest_path.is_symlink()
        or not manifest_path.is_file()
        or manifest_path.stat().st_nlink != 1
    ):
        raise CommandError(
            "authenticated raw-HTML manifest is not a singly linked regular file"
        )
    manifest_payload = manifest_path.read_bytes()
    if hashlib.sha256(manifest_payload).hexdigest() != expected_manifest_sha256:
        raise CommandError("authenticated raw-HTML manifest commitment mismatch")
    try:
        manifest_rows = _read_jsonl_payload(
            manifest_payload,
            label="authenticated raw-HTML manifest",
        )
    except ValueError as exc:
        raise CommandError(str(exc)) from exc
    if not manifest_rows:
        raise CommandError("authenticated raw-HTML manifest must not be empty")
    if manifest_payload != _jsonl_bytes(manifest_rows):
        raise CommandError("authenticated raw-HTML manifest is not canonical JSONL")

    expected_names: set[str] = set()
    prior_candidate_id: str | None = None
    for row in manifest_rows:
        if set(row) != {
            "candidate_id",
            "relative_path",
            "sha256",
            "byte_count",
        }:
            raise CommandError(
                "authenticated raw-HTML manifest rows require exactly candidate_id, "
                "relative_path, sha256, and byte_count"
            )
        candidate_id = _required_str(row, "candidate_id")
        relative_path = _required_str(row, "relative_path")
        sha256 = _required_str(row, "sha256")
        byte_count = row.get("byte_count")
        if (
            not candidate_id
            or candidate_id in {".", ".."}
            or "/" in candidate_id
            or "\\" in candidate_id
            or "\x00" in candidate_id
            or relative_path != f"{candidate_id}.html"
        ):
            raise CommandError(
                "authenticated raw-HTML manifest contains an unsafe identity or path"
            )
        if prior_candidate_id is not None and candidate_id <= prior_candidate_id:
            raise CommandError(
                "authenticated raw-HTML manifest candidates must be unique and sorted"
            )
        prior_candidate_id = candidate_id
        if re.fullmatch(r"sha256:[0-9a-f]{64}", sha256) is None:
            raise CommandError(
                "authenticated raw-HTML manifest contains an invalid SHA-256"
            )
        if (
            not isinstance(byte_count, int)
            or isinstance(byte_count, bool)
            or byte_count < 0
        ):
            raise CommandError(
                "authenticated raw-HTML manifest contains an invalid byte count"
            )
        raw_path = raw_html_dir / relative_path
        if (
            raw_path.is_symlink()
            or not raw_path.is_file()
            or raw_path.stat().st_nlink != 1
        ):
            raise CommandError(
                f"authenticated raw-HTML artifact is not a regular file: {raw_path}"
            )
        raw_payload = raw_path.read_bytes()
        if len(raw_payload) != byte_count:
            raise CommandError(
                f"authenticated raw-HTML byte-count mismatch: {candidate_id}"
            )
        if "sha256:" + hashlib.sha256(raw_payload).hexdigest() != sha256:
            raise CommandError(
                f"authenticated raw-HTML content commitment mismatch: {candidate_id}"
            )
        expected_names.add(relative_path)
        commitments[str(raw_path.resolve())] = sha256

    actual_names = {path.name for path in raw_html_dir.iterdir()}
    if actual_names != expected_names:
        raise CommandError(
            "authenticated raw-HTML directory does not exactly match its manifest"
        )
    commitments[str(manifest_path.resolve())] = "sha256:" + expected_manifest_sha256
    return commitments


def _verified_target_bridge_route_commitments(
    preparation_root: Path,
) -> dict[str, str]:
    """Prove target route files still equal the exact bytes admitted by bridge."""

    progress_config_path = (
        preparation_root
        / "03-gap-bridge/checkpoints/pacer-gap-bridge-progress-config.json"
    )
    progress_payload = _read_regular_non_symlink_bytes(
        progress_config_path,
        "PACER-gap bridge progress config",
    )
    try:
        progress_config = _read_json_object_payload(
            progress_payload,
            label="PACER-gap bridge progress config",
        )
    except ValueError as exc:
        raise CommandError(str(exc)) from exc
    if (
        progress_config.get("schema_version") != _PACER_GAP_PROGRESS_CONFIG_SCHEMA
        or progress_config.get("mode") != "public_first"
    ):
        raise CommandError(
            "target preparation requires current public-first bridge progress config"
        )
    routed_inputs = {
        "public_selection_sha256": (
            preparation_root / "01-public-plan/public-packet-selection.jsonl"
        ),
        "paid_gaps_sha256": (
            preparation_root / "01-public-plan/public-packet-paid-gaps.jsonl"
        ),
        "free_download_manifest_sha256": (
            preparation_root / "02-free-download/free-document-downloads.jsonl"
        ),
    }
    commitments: dict[str, str] = {}
    for field_name, path in routed_inputs.items():
        expected_sha256 = progress_config.get(field_name)
        if (
            not isinstance(expected_sha256, str)
            or re.fullmatch(r"sha256:[0-9a-f]{64}", expected_sha256) is None
        ):
            raise CommandError(f"PACER-gap bridge progress config lacks {field_name}")
        payload = _read_regular_non_symlink_bytes(
            path,
            field_name.removesuffix("_sha256").replace("_", " "),
        )
        actual_sha256 = "sha256:" + hashlib.sha256(payload).hexdigest()
        if actual_sha256 != expected_sha256:
            raise CommandError(
                f"target route input differs from PACER-gap bridge admission: {path}"
            )
        commitments[str(path.resolve())] = expected_sha256
    return commitments


def _target_100_config_record(
    config: TargetCohortPreparationConfig | Target100PreparationConfig,
    *,
    profile: _TargetPreparationProfile,
    snapshot_manifest: Mapping[str, Any],
    snapshot_manifest_sha256: str,
    snapshot_screened_cases_sha256: str,
    snapshot_source_screened_cases_sha256: str,
    stage_commands: Sequence[Mapping[str, Any]],
    driver_execute: bool,
    wrapper_artifact_paths: Mapping[str, Path],
    retarget_source: FailedSourcePreparation | None = None,
    retarget_source_tree: SourceTreeCommitment | None = None,
) -> JsonRecord:
    record: JsonRecord = {
        "schema_version": profile.config_schema,
        "snapshot": str(config.snapshot.resolve()),
        "authenticated_screened_cases": str(
            config.authenticated_screened_cases.resolve()
        ),
        "snapshot_manifest_sha256": "sha256:" + snapshot_manifest_sha256,
        "snapshot_screened_cases_sha256": ("sha256:" + snapshot_screened_cases_sha256),
        "snapshot_source_screened_cases_sha256": (
            "sha256:" + snapshot_source_screened_cases_sha256
        ),
        "snapshot_cycle_hash": snapshot_manifest["cycle_hash"],
        "snapshot_batch_digest": snapshot_manifest["batch_digest"],
        "candidate_pool_size": config.candidate_pool_size,
        "target_case_count": config.target_case_count,
        "cost_per_document_usd": config.cost_per_document_usd,
        "max_projected_budget_usd": config.max_projected_budget_usd,
        "max_missing_core_documents_per_case": (
            config.max_missing_core_documents_per_case
        ),
        "use_embedded_entries": config.use_embedded_entries,
        "screened_cases_sha256": "sha256:" + config.screened_cases_sha256,
        "raw_html_dir": (
            str(config.raw_html_dir.resolve())
            if config.raw_html_dir is not None
            else None
        ),
        "authenticated_raw_html_manifest": (
            str(config.authenticated_raw_html_manifest.resolve())
            if config.authenticated_raw_html_manifest is not None
            else None
        ),
        "authenticated_raw_html_manifest_sha256": (
            "sha256:" + config.authenticated_raw_html_manifest_sha256
            if config.authenticated_raw_html_manifest_sha256 is not None
            else None
        ),
        "requested_raw_html_dir": (
            str(config.requested_raw_html_dir.resolve())
            if config.requested_raw_html_dir is not None
            else None
        ),
        "public_download_provider": (
            "courtlistener_live" if config.live_public_download else "fixture"
        ),
        "fixture_documents_sha256": (
            _path_sha256(config.fixture_documents)
            if config.fixture_documents is not None
            else None
        ),
        "paid_gap_authority": "courtlistener_rest",
        "courtlistener_mode": ("live" if config.live_courtlistener else "fixture"),
        "courtlistener_fixture_sha256": (
            _path_sha256(config.courtlistener_fixture)
            if config.courtlistener_fixture is not None
            else None
        ),
        "request_ledger": (
            str(config.request_ledger.resolve())
            if config.request_ledger is not None
            else None
        ),
        "courtlistener_rate_profile": config.courtlistener_rate_profile,
        "request_budget_max_wait_seconds": config.request_budget_max_wait_seconds,
        "driver_execute": driver_execute,
        "wrapper_artifact_paths": {
            name: str(path.resolve())
            for name, path in sorted(wrapper_artifact_paths.items())
        },
        "stage_commands": _semantic_target_100_stage_commands(stage_commands),
    }
    if (retarget_source is None) != (retarget_source_tree is None):
        raise CommandError("retarget source and tree commitments must be paired")
    if retarget_source is not None and retarget_source_tree is not None:
        expected_root = getattr(config, "retarget_source_preparation_root", None)
        if expected_root is None or expected_root.resolve() != retarget_source.root:
            raise CommandError("retarget source config root commitment mismatch")
        record["retarget_import"] = {
            "source_preparation_root": str(retarget_source.root),
            "source_config_file_sha256": retarget_source.config_file_sha256,
            "source_config_self_hash": retarget_source.config_self_hash,
            "source_tree_commitment": retarget_source_tree.to_record(),
            "receipt_path": str(
                (config.output_root / RETARGET_IMPORT_RECEIPT_FILENAME).resolve()
            ),
            "immutable_baseline_root": str(
                (config.output_root / "retarget-import").resolve()
            ),
        }
    record["config_sha256"] = _canonical_json_sha256(record)
    return record


def _ensure_target_100_config(
    path: Path,
    record: Mapping[str, Any],
    *,
    profile: _TargetPreparationProfile,
    resume: bool,
) -> None:
    if path.exists():
        if not resume:
            raise CommandError(
                f"{profile.label} config already exists; use --resume or a new "
                "output root"
            )
        existing = _read_json_object(path)
        if existing != record:
            raise CommandError(
                f"{profile.label} config mismatch: refusing changed-config resume"
            )
        return
    _atomic_write_json(path, record)


_RETARGET_IMPORT_ROOT = "retarget-import"
_RETARGET_IMPORTED_DOCUMENTS = "imported-free-documents.jsonl"
_RETARGET_DOCUMENT_REUSE_RECEIPT = "free-document-reuse-receipt.json"
_RETARGET_BRIDGE_BASELINE = "bridge-baseline"
_RETARGET_LIVE_SEED_RECEIPT = "live-bridge-seed-receipt.json"


def _retarget_owned_source_path(
    source: FailedSourcePreparation,
    field_name: str,
) -> Path:
    raw_path = source.config_record.get(field_name)
    if not isinstance(raw_path, str) or not raw_path:
        raise CommandError(f"retarget source config lacks {field_name}")
    try:
        path = Path(raw_path).resolve(strict=True)
        path.relative_to(source.root)
    except (OSError, ValueError) as exc:
        raise CommandError(
            f"retarget source config {field_name} is outside the failed root"
        ) from exc
    return path


def _retarget_source_stage_paths(
    source: FailedSourcePreparation,
) -> tuple[tuple[str, ...], tuple[str, ...], tuple[str, ...]]:
    authenticated = (
        "00-authenticated-snapshot/screened-cases.jsonl",
        "00-authenticated-snapshot/raw-html-manifest.jsonl",
    )
    public_plan_root = source.root / "01-public-plan"
    public_plan = tuple(
        path.relative_to(source.root).as_posix()
        for path in sorted(public_plan_root.rglob("*"))
        if path.is_file()
    )
    bridge_paths = (
        "02-free-download/free-document-downloads.jsonl",
        "03b-bridge-free-download/free-document-downloads.jsonl",
        "documents/free/.download-checkpoint.jsonl",
        "03-gap-bridge/checkpoints/pacer-gap-bridge-progress-config.json",
        *tuple(
            path.relative_to(source.root).as_posix()
            for path in sorted(
                (source.root / "03-gap-bridge/checkpoints/pacer-gap-bridge").glob(
                    "*.json"
                )
            )
        ),
    )
    return authenticated, public_plan, bridge_paths


def _verified_retarget_source_downloads(
    source: FailedSourcePreparation,
) -> tuple[
    tuple[FreeDocumentDownloadRequest, ...],
    tuple[FreeDocumentDownloadRecord, ...],
    int,
]:
    source_document_root = source.root / "documents/free"
    stage_02_requests = tuple(
        _free_document_download_request(record)
        for record in _read_records(
            source.root / "01-public-plan/free-document-requests.jsonl"
        )
    )
    stage_02_records = verify_completed_free_document_manifest(
        stage_02_requests,
        output_root=source_document_root,
        manifest_path=(source.root / "02-free-download/free-document-downloads.jsonl"),
    )
    stage_03b_requests = tuple(
        _free_document_download_request(record)
        for record in _read_records(
            source.root / "03-gap-bridge/pacer-gap-free-document-requests.jsonl"
        )
    )
    stage_03b_records = verify_completed_free_document_manifest(
        stage_03b_requests,
        output_root=source_document_root,
        manifest_path=(
            source.root / "03b-bridge-free-download/free-document-downloads.jsonl"
        ),
    )
    request_keys = [
        (request.candidate_id, request.source_provider, request.source_document_id)
        for request in (*stage_02_requests, *stage_03b_requests)
    ]
    if len(request_keys) != len(set(request_keys)):
        raise CommandError(
            "retarget source stage-02 and stage-03b document requests overlap"
        )
    return (
        (*stage_02_requests, *stage_03b_requests),
        (*stage_02_records, *stage_03b_records),
        len(stage_02_records),
    )


def _retarget_rebase_namespace(
    *,
    args: argparse.Namespace,
    config: TargetCohortPreparationConfig,
    source: FailedSourcePreparation,
    baseline_root: Path,
) -> argparse.Namespace:
    return argparse.Namespace(
        output_root=baseline_root,
        execute=True,
        resume=cast(bool, args.resume),
        log_output=None,
        run_card_output=None,
        previous_screened_cases=(
            source.root / "00-authenticated-snapshot/screened-cases.jsonl"
        ),
        current_screened_cases=config.authenticated_screened_cases,
        previous_public_selection=(
            source.root / "01-public-plan/public-packet-selection.jsonl"
        ),
        current_public_selection=(
            config.output_root / "01-public-plan/public-packet-selection.jsonl"
        ),
        previous_paid_gaps=(
            source.root / "01-public-plan/public-packet-paid-gaps.jsonl"
        ),
        current_paid_gaps=(
            config.output_root / "01-public-plan/public-packet-paid-gaps.jsonl"
        ),
        previous_free_download_manifest=(
            source.root / "02-free-download/free-document-downloads.jsonl"
        ),
        current_free_download_manifest=(
            config.output_root / "02-free-download/free-document-downloads.jsonl"
        ),
        previous_checkpoint_dir=(
            source.root / "03-gap-bridge/checkpoints/pacer-gap-bridge"
        ),
        previous_checkpoint_config=(
            source.root
            / "03-gap-bridge/checkpoints/pacer-gap-bridge-progress-config.json"
        ),
        current_raw_html_dir=config.raw_html_dir,
        current_authenticated_raw_html_manifest=(
            config.authenticated_raw_html_manifest
        ),
        checkpoint_dir=None,
        checkpoint_config_output=None,
        receipt_output=None,
        previous_snapshot=None,
        expected_previous_snapshot_manifest_sha256=None,
        current_snapshot=None,
        expected_current_snapshot_manifest_sha256=None,
        expected_added_candidate_id=None,
        expected_invalidated_candidate_id=None,
    )


def _semantic_replay_plan_from_rebase(
    *,
    receipt: Mapping[str, Any],
    source_checkpoint_dir: Path,
) -> SemanticReplayPlan:
    raw_ids = receipt.get("semantic_replay_candidate_ids")
    if not isinstance(raw_ids, list):
        raise CommandError("retarget rebase receipt has invalid semantic replay IDs")
    raw_candidate_ids = cast(list[object], raw_ids)
    if not all(isinstance(candidate_id, str) for candidate_id in raw_candidate_ids):
        raise CommandError("retarget rebase receipt has invalid semantic replay IDs")
    candidate_ids = tuple(cast(list[str], raw_candidate_ids))
    if (
        receipt.get("missing_replay_candidate_count") != 0
        or receipt.get("missing_replay_candidate_ids") != []
    ):
        raise CommandError(
            "retarget import refuses previously uncheckpointed replay candidates"
        )
    invalidations = receipt.get("invalidated_checkpoints")
    if not isinstance(invalidations, list):
        raise CommandError("retarget rebase receipt lacks checkpoint invalidations")
    invalidation_by_id = {
        _required_str(
            _mapping(row, "checkpoint invalidation"), "candidate_id"
        ): _mapping(row, "checkpoint invalidation")
        for row in cast(list[object], invalidations)
    }
    source_revisions: set[str] = set()
    target_revisions: set[str] = set()
    source_by_id: dict[str, JsonRecord] = {}
    for path in sorted(source_checkpoint_dir.glob("*.json")):
        checkpoint = _read_json_object(path)
        source_by_id[_required_str(checkpoint, "candidate_id")] = checkpoint
    for candidate_id in candidate_ids:
        checkpoint = source_by_id.get(candidate_id)
        invalidation = invalidation_by_id.get(candidate_id)
        if checkpoint is None or invalidation is None:
            raise CommandError(
                f"retarget semantic replay lacks checkpoint evidence: {candidate_id}"
            )
        exclusion = _mapping(
            _mapping(checkpoint.get("payload"), "checkpoint payload").get(
                "exclusion_record"
            ),
            "checkpoint exclusion",
        )
        if (
            checkpoint.get("outcome") != "exclusion"
            or exclusion.get("primary_exclusion_reason") != "text_missing"
            or exclusion.get("exclusion_reasons") != ["text_missing"]
            or invalidation.get("reason") != "stale_bridge_semantic_revision"
        ):
            raise CommandError(
                f"retarget semantic replay is not an exact text_missing transition: "
                f"{candidate_id}"
            )
        source_revision = invalidation.get("previous_bridge_semantic_revision")
        target_revision = invalidation.get("current_bridge_semantic_revision")
        if not isinstance(source_revision, str) or not isinstance(target_revision, str):
            raise CommandError("retarget semantic replay revision is invalid")
        source_revisions.add(source_revision)
        target_revisions.add(target_revision)
    if len(source_revisions) != 1 or target_revisions != {
        _PACER_GAP_BRIDGE_SEMANTIC_REVISION
    }:
        raise CommandError("retarget semantic replay revisions are not exact")
    plan = SemanticReplayPlan(
        source_semantic_revision=next(iter(source_revisions)),
        target_semantic_revision=_PACER_GAP_BRIDGE_SEMANTIC_REVISION,
        reason_code="text_missing",
        candidate_ids=candidate_ids,
    )
    plan.validate()
    return plan


def _run_retarget_public_plan(command: Target100StageCommand) -> int:
    """Run the exact authenticated historical snapshot through today's planner."""

    public_plan_args = build_parser().parse_args(command.argv)
    if getattr(public_plan_args, "handler", None) is not (
        _cmd_acquisition_plan_public_downloads
    ):
        raise CommandError("retarget import public-plan command identity differs")
    return _cmd_acquisition_plan_public_downloads(
        public_plan_args,
        require_current_screening=False,
    )


def _require_retarget_public_plan_success(command: Target100StageCommand) -> None:
    """Make the provider-free planning stage's success contract explicit."""

    if _run_retarget_public_plan(command) != 0:
        raise CommandError("retarget import public-plan stage failed")


def _retarget_checkpoint_commitments(
    *,
    source_checkpoint_sha256: str,
    destination_checkpoint_sha256: str,
) -> dict[str, str]:
    """Publish checkpoint commitments with one canonical digest prefix."""

    return {
        "source_checkpoint_sha256": prefixed_sha256(source_checkpoint_sha256),
        "destination_checkpoint_sha256": prefixed_sha256(destination_checkpoint_sha256),
    }


def _execute_target_retarget_import(
    *,
    args: argparse.Namespace,
    config: TargetCohortPreparationConfig,
    commands: Sequence[Target100StageCommand],
    source: FailedSourcePreparation,
    source_tree_before: SourceTreeCommitment,
    snapshot: SnapshotCommitment,
    config_path: Path,
) -> RetargetImportReceipt:
    receipt_path = config.output_root / RETARGET_IMPORT_RECEIPT_FILENAME
    if receipt_path.exists() or receipt_path.is_symlink():
        receipt = verify_retarget_import_receipt(
            receipt_path,
            source_root=source.root,
            target_root=config.output_root,
        )
        imported_manifest = (
            config.output_root / _RETARGET_IMPORT_ROOT / _RETARGET_IMPORTED_DOCUMENTS
        )
        imported_records = _read_records(imported_manifest)
        verify_completed_free_document_manifest(
            tuple(
                _free_document_download_request(record) for record in imported_records
            ),
            output_root=config.output_root / "documents/free",
            manifest_path=imported_manifest,
        )
        return receipt
    source_screened = _retarget_owned_source_path(
        source, "authenticated_screened_cases"
    )
    source_raw_dir = _retarget_owned_source_path(source, "raw_html_dir")
    source_raw_manifest = _retarget_owned_source_path(
        source, "authenticated_raw_html_manifest"
    )
    source_screened_sha = _required_str(source.config_record, "screened_cases_sha256")
    source_raw_manifest_sha = _required_str(
        source.config_record, "authenticated_raw_html_manifest_sha256"
    )
    _verified_target_authenticated_paths(
        screened_cases=source_screened,
        screened_cases_sha256=source_screened_sha.removeprefix("sha256:"),
        raw_html_dir=source_raw_dir,
        raw_html_manifest=source_raw_manifest,
        raw_html_manifest_sha256=source_raw_manifest_sha.removeprefix("sha256:"),
    )
    if not commands or commands[0].stage != "plan-public-downloads":
        raise CommandError("retarget import lacks the provider-free public-plan stage")
    _require_retarget_public_plan_success(commands[0])

    source_requests, source_records, stage_02_count = (
        _verified_retarget_source_downloads(source)
    )
    _verify_retarget_public_plan_matches_source(
        output_root=config.output_root,
        source_requests=source_requests,
        stage_02_count=stage_02_count,
    )
    destination_document_root = config.output_root / "documents/free"
    reuse = reuse_authenticated_free_documents(
        source_requests,
        authenticated_source_records=source_records,
        source_output_root=source.root / "documents/free",
        destination_output_root=destination_document_root,
    )
    imported_manifest_path = (
        config.output_root / _RETARGET_IMPORT_ROOT / _RETARGET_IMPORTED_DOCUMENTS
    )
    imported_manifest_payload = _jsonl_bytes(
        record.to_record() for record in reuse.records
    )
    _write_immutable_bytes(
        imported_manifest_path,
        imported_manifest_payload,
        resume=cast(bool, args.resume),
    )
    stage_02_manifest_path = (
        config.output_root / "02-free-download/free-document-downloads.jsonl"
    )
    _write_immutable_bytes(
        stage_02_manifest_path,
        _jsonl_bytes(record.to_record() for record in reuse.records[:stage_02_count]),
        resume=cast(bool, args.resume),
    )
    reuse_receipt_path = (
        config.output_root / _RETARGET_IMPORT_ROOT / _RETARGET_DOCUMENT_REUSE_RECEIPT
    )
    reuse_record: JsonRecord = {
        "schema_version": "legalforecast.target_retarget_document_reuse.v1",
        "source_preparation_root": str(source.root),
        "destination_document_root": str(destination_document_root.resolve()),
        **_retarget_checkpoint_commitments(
            source_checkpoint_sha256=reuse.source_checkpoint_sha256,
            destination_checkpoint_sha256=reuse.destination_checkpoint_sha256,
        ),
        "source_checkpoint_record_count": reuse.source_checkpoint_record_count,
        "imported_record_count": len(reuse.records),
        "stage_02_record_count": stage_02_count,
        "imported_manifest_sha256": _bytes_sha256(imported_manifest_payload),
        "provider_client_constructed": False,
        "provider_request_count": 0,
        "network_request_count": 0,
        "paid_activity_requested": False,
        "paid_activity_executed": False,
    }
    reuse_record["receipt_sha256"] = _canonical_json_sha256(reuse_record)
    _write_immutable_bytes(
        reuse_receipt_path,
        _projection_json_bytes(reuse_record),
        resume=cast(bool, args.resume),
    )

    baseline_root = (
        config.output_root / _RETARGET_IMPORT_ROOT / _RETARGET_BRIDGE_BASELINE
    )
    rebase_args = _retarget_rebase_namespace(
        args=args,
        config=config,
        source=source,
        baseline_root=baseline_root,
    )
    rebase_receipt = _rebase_pacer_gap_checkpoints(rebase_args)
    if (
        rebase_receipt.get("provider_request_count") != 0
        or rebase_receipt.get("network_request_count") != 0
        or rebase_receipt.get("provider_client_constructed") is not False
        or rebase_receipt.get("paid_activity_requested") is not False
        or rebase_receipt.get("paid_activity_executed") is not False
    ):
        raise CommandError(
            "retarget checkpoint rebase recorded provider or paid activity"
        )
    semantic_replay = _semantic_replay_plan_from_rebase(
        receipt=rebase_receipt,
        source_checkpoint_dir=(
            source.root / "03-gap-bridge/checkpoints/pacer-gap-bridge"
        ),
    )

    source_authenticated, source_public, source_bridge = _retarget_source_stage_paths(
        source
    )
    source_stages = (
        build_stage_commitment(
            source.root,
            stage="source-authenticated-inputs",
            relative_paths=source_authenticated,
        ),
        build_stage_commitment(
            source.root,
            stage="source-public-plan",
            relative_paths=source_public,
        ),
        build_stage_commitment(
            source.root,
            stage="source-download-and-bridge-evidence",
            relative_paths=source_bridge,
        ),
    )
    target_stable_paths = (
        "00-authenticated-snapshot/screened-cases.jsonl",
        "00-authenticated-snapshot/raw-html-manifest.jsonl",
        "02-free-download/free-document-downloads.jsonl",
        f"{_RETARGET_IMPORT_ROOT}/{_RETARGET_IMPORTED_DOCUMENTS}",
        f"{_RETARGET_IMPORT_ROOT}/{_RETARGET_DOCUMENT_REUSE_RECEIPT}",
        *tuple(
            path.relative_to(config.output_root).as_posix()
            for path in sorted((config.output_root / "01-public-plan").rglob("*"))
            if path.is_file()
        ),
    )
    baseline_paths = tuple(
        path.relative_to(config.output_root).as_posix()
        for path in sorted(baseline_root.rglob("*"))
        if path.is_file()
    )
    target_stages = (
        build_stage_commitment(
            config.output_root,
            stage="target-stable-import-artifacts",
            relative_paths=target_stable_paths,
        ),
        build_stage_commitment(
            config.output_root,
            stage="target-immutable-bridge-baseline",
            relative_paths=baseline_paths,
        ),
        build_stage_commitment(
            config.output_root,
            stage="target-config",
            relative_paths=(config_path.relative_to(config.output_root).as_posix(),),
        ),
    )
    source_tree_after = compute_source_tree_commitment(source.root)
    receipt_path = write_retarget_import_receipt(
        source=source,
        target_root=config.output_root,
        snapshot=snapshot,
        source_stage_commitments=source_stages,
        target_stage_commitments=target_stages,
        semantic_replay=semantic_replay,
        source_before=source_tree_before,
        source_after=source_tree_after,
    )
    return verify_retarget_import_receipt(
        receipt_path,
        source_root=source.root,
        target_root=config.output_root,
    )


def _baseline_seed_bindings(
    baseline_root: Path,
) -> tuple[tuple[str, str], ...]:
    rebase_receipt = _read_json_object(
        baseline_root / "run-cards/rebase-pacer-gap-checkpoints-receipt.json"
    )
    raw_bindings = rebase_receipt.get("checkpoint_bindings")
    if not isinstance(raw_bindings, list):
        raise CommandError("retarget bridge baseline lacks checkpoint bindings")
    bindings: list[tuple[str, str]] = []
    for raw_binding in cast(list[object], raw_bindings):
        binding = _mapping(raw_binding, "retarget bridge checkpoint binding")
        filename = _required_str(binding, "current_filename")
        digest = _required_str(binding, "current_sha256")
        if not re.fullmatch(r"[0-9]{6}-[0-9a-f]{16}\.json", filename):
            raise CommandError("retarget bridge checkpoint filename is invalid")
        if re.fullmatch(r"sha256:[0-9a-f]{64}", digest) is None:
            raise CommandError("retarget bridge checkpoint digest is invalid")
        bindings.append((filename, digest))
    bindings.sort()
    filenames = [filename for filename, _ in bindings]
    if len(filenames) != len(set(filenames)) or rebase_receipt.get(
        "checkpoint_count"
    ) != len(bindings):
        raise CommandError("retarget bridge checkpoint bindings do not reconcile")
    return tuple(bindings)


def _retarget_live_seed_record(
    *,
    baseline_root: Path,
    live_checkpoint_root: Path,
    live_config: Path,
    bindings: Sequence[tuple[str, str]],
    baseline_config_payload: bytes,
) -> JsonRecord:
    record: JsonRecord = {
        "schema_version": "legalforecast.target_retarget_live_seed.v1",
        "baseline_root": str(baseline_root.resolve()),
        "live_checkpoint_root": str(live_checkpoint_root.resolve()),
        "live_checkpoint_config": str(live_config.resolve()),
        "checkpoint_count": len(bindings),
        "checkpoint_bindings": [
            {"filename": filename, "sha256": digest} for filename, digest in bindings
        ],
        "checkpoint_config_sha256": _bytes_sha256(baseline_config_payload),
        "source_files_hardlinked": False,
        "provider_client_constructed": False,
        "provider_request_count": 0,
        "network_request_count": 0,
        "paid_activity_requested": False,
        "paid_activity_executed": False,
    }
    record["receipt_sha256"] = _canonical_json_sha256(record)
    return record


def _verify_target_retarget_live_seed(
    *,
    output_root: Path,
) -> Path:
    import_root = output_root / _RETARGET_IMPORT_ROOT
    baseline_root = import_root / _RETARGET_BRIDGE_BASELINE
    baseline_checkpoint_root = baseline_root / "checkpoints/pacer-gap-bridge"
    baseline_config = (
        baseline_root / "checkpoints/pacer-gap-bridge-progress-config.json"
    )
    live_checkpoint_root = output_root / "03-gap-bridge/checkpoints/pacer-gap-bridge"
    live_config = (
        output_root / "03-gap-bridge/checkpoints/pacer-gap-bridge-progress-config.json"
    )
    seed_receipt_path = import_root / _RETARGET_LIVE_SEED_RECEIPT
    bindings = _baseline_seed_bindings(baseline_root)
    baseline_config_payload = _read_regular_non_symlink_bytes(
        baseline_config, "retarget bridge baseline config"
    )
    expected_receipt = _retarget_live_seed_record(
        baseline_root=baseline_root,
        live_checkpoint_root=live_checkpoint_root,
        live_config=live_config,
        bindings=bindings,
        baseline_config_payload=baseline_config_payload,
    )
    if _read_json_object(seed_receipt_path) != expected_receipt:
        raise CommandError("retarget live-seed receipt commitment mismatch")
    for filename, digest in bindings:
        baseline_path = baseline_checkpoint_root / filename
        live_path = live_checkpoint_root / filename
        baseline_payload = _read_regular_non_symlink_bytes(
            baseline_path, "retarget bridge baseline checkpoint"
        )
        live_payload = _read_regular_non_symlink_bytes(
            live_path, "retarget live bridge checkpoint"
        )
        if _bytes_sha256(baseline_payload) != digest:
            raise CommandError("retarget bridge baseline checkpoint hash mismatch")
        if live_payload != baseline_payload:
            raise CommandError(
                "retarget live bridge checkpoint contradicts its immutable seed"
            )
        if os.path.samestat(baseline_path.stat(), live_path.stat()):
            raise CommandError("retarget live bridge checkpoint hard-links baseline")
    if (
        _read_regular_non_symlink_bytes(
            live_config, "retarget live bridge checkpoint config"
        )
        != baseline_config_payload
    ):
        raise CommandError("retarget live bridge checkpoint config drifted")
    if os.path.samestat(baseline_config.stat(), live_config.stat()):
        raise CommandError("retarget live bridge config hard-links baseline")
    return seed_receipt_path


def _seed_target_retarget_bridge(
    *,
    config: TargetCohortPreparationConfig,
) -> Path:
    import_root = config.output_root / _RETARGET_IMPORT_ROOT
    baseline_root = import_root / _RETARGET_BRIDGE_BASELINE
    baseline_checkpoint_root = baseline_root / "checkpoints/pacer-gap-bridge"
    baseline_config = (
        baseline_root / "checkpoints/pacer-gap-bridge-progress-config.json"
    )
    live_checkpoint_root = (
        config.output_root / "03-gap-bridge/checkpoints/pacer-gap-bridge"
    )
    live_config = (
        config.output_root
        / "03-gap-bridge/checkpoints/pacer-gap-bridge-progress-config.json"
    )
    seed_receipt_path = import_root / _RETARGET_LIVE_SEED_RECEIPT
    bindings = _baseline_seed_bindings(baseline_root)
    baseline_config_payload = _read_regular_non_symlink_bytes(
        baseline_config, "retarget bridge baseline config"
    )
    allowed_names = {filename for filename, _ in bindings}
    seed_record = _retarget_live_seed_record(
        baseline_root=baseline_root,
        live_checkpoint_root=live_checkpoint_root,
        live_config=live_config,
        bindings=bindings,
        baseline_config_payload=baseline_config_payload,
    )
    if seed_receipt_path.exists() or seed_receipt_path.is_symlink():
        if _read_json_object(seed_receipt_path) != seed_record:
            raise CommandError("retarget live-seed receipt commitment mismatch")
    else:
        existing_names: set[str] = (
            {path.name for path in live_checkpoint_root.glob("*.json")}
            if live_checkpoint_root.is_dir()
            else set[str]()
        )
        if existing_names - allowed_names:
            raise CommandError(
                "retarget live checkpoints progressed before seed receipt publication"
            )
        for filename, digest in bindings:
            baseline_path = baseline_checkpoint_root / filename
            payload = _read_regular_non_symlink_bytes(
                baseline_path, "retarget bridge baseline checkpoint"
            )
            if _bytes_sha256(payload) != digest:
                raise CommandError("retarget bridge baseline checkpoint hash mismatch")
            _write_immutable_bytes(
                live_checkpoint_root / filename,
                payload,
                resume=True,
            )
        _write_immutable_bytes(live_config, baseline_config_payload, resume=True)
        _write_immutable_bytes(
            seed_receipt_path,
            _projection_json_bytes(seed_record),
            resume=False,
        )
    return _verify_target_retarget_live_seed(output_root=config.output_root)


def _verify_and_seed_target_retarget_import(
    *,
    args: argparse.Namespace,
    config: TargetCohortPreparationConfig,
    source: FailedSourcePreparation,
) -> RetargetImportReceipt:
    receipt_path = config.output_root / RETARGET_IMPORT_RECEIPT_FILENAME
    if not receipt_path.is_file() or receipt_path.is_symlink():
        raise CommandError(
            "retarget import receipt is missing; rerun with "
            "--stop-after retarget-import before normal resume"
        )
    receipt = verify_retarget_import_receipt(
        receipt_path,
        source_root=source.root,
        target_root=config.output_root,
    )
    imported_manifest = (
        config.output_root / _RETARGET_IMPORT_ROOT / _RETARGET_IMPORTED_DOCUMENTS
    )
    imported_records = _read_records(imported_manifest)
    imported_requests = tuple(
        _free_document_download_request(record) for record in imported_records
    )
    verify_completed_free_document_manifest(
        imported_requests,
        output_root=config.output_root / "documents/free",
        manifest_path=imported_manifest,
    )
    _seed_target_retarget_bridge(config=config)
    return receipt


def _verify_retarget_public_plan_matches_source(
    *,
    output_root: Path,
    source_requests: tuple[FreeDocumentDownloadRequest, ...],
    stage_02_count: int,
) -> None:
    """Bind today's provider-free plan to the authenticated imported prefix."""

    target_stage_02_requests = tuple(
        _free_document_download_request(record)
        for record in _read_records(
            output_root / "01-public-plan/free-document-requests.jsonl"
        )
    )
    if target_stage_02_requests != source_requests[:stage_02_count]:
        raise CommandError(
            "retarget current public plan differs from authenticated source requests"
        )


def _path_sha256(path: Path) -> str:
    return prefixed_sha256(hashlib.sha256(path.read_bytes()).hexdigest())


def _path_matches_sha256(path: Path, expected: str) -> bool:
    """Compare a file digest across legacy raw and canonical prefixed forms."""

    return _path_sha256(path).removeprefix("sha256:") == expected.removeprefix(
        "sha256:"
    )


def _replacement_source_commitments(
    values: Sequence[str], *, fixed: Mapping[str, bytes]
) -> dict[str, str]:
    """Hash one captured byte snapshot for every replacement-frontier input."""

    commitments = {name: _bytes_sha256(payload) for name, payload in fixed.items()}
    for value in values:
        name, separator, raw_path = value.partition("=")
        if (
            not separator
            or not name
            or name.strip() != name
            or not raw_path
            or name in commitments
        ):
            raise ValueError("--source must be a unique canonical NAME=PATH commitment")
        path = Path(raw_path)
        commitments[name] = _bytes_sha256(read_unique_regular_file(path))
    return commitments


def _replacement_initial_candidate_ids(
    payload: bytes, *, source: Path
) -> tuple[str, ...]:
    if source.suffix != ".jsonl":
        mapping = cast(
            Mapping[object, object],
            _projection_json_object(payload, source=source),
        )
        raw_ids = mapping.get("selected_candidate_ids")
        if isinstance(raw_ids, Sequence) and not isinstance(raw_ids, (str, bytes)):
            ids = tuple(cast(Sequence[object], raw_ids))
            if all(isinstance(item, str) for item in ids):
                return cast(tuple[str, ...], ids)
    return tuple(
        _required_str(record, "candidate_id")
        for record in _projection_jsonl_records(payload, source=source)
    )


def _replacement_frontier_rows(
    payload: bytes, *, source: Path
) -> tuple[JsonRecord, ...]:
    path = source
    if path.suffix != ".jsonl":
        try:
            loaded = _loads_json(payload.decode("utf-8"))
        except (UnicodeDecodeError, ValueError) as exc:
            raise CommandError(f"candidate frontier has invalid JSON: {path}") from exc
        if isinstance(loaded, Mapping):
            mapping = cast(Mapping[object, object], loaded)
            if mapping.get("schema_version") == (
                "legalforecast.target_cohort_candidate_frontier.v1"
            ):
                return _verified_target_cohort_frontier_rows(
                    cast(Mapping[str, Any], loaded)
                )
            raw_rows = mapping.get("case_plans")
            if isinstance(raw_rows, Sequence) and not isinstance(
                raw_rows, (str, bytes)
            ):
                return tuple(
                    _mapping(item, "candidate frontier case_plan")
                    for item in cast(Sequence[object], raw_rows)
                )
        elif isinstance(loaded, Sequence) and not isinstance(loaded, (str, bytes)):
            return tuple(
                _mapping(item, "candidate frontier row")
                for item in cast(Sequence[object], loaded)
            )
    return tuple(_projection_jsonl_records(payload, source=path))


def _verified_target_frontier_selected_candidate_ids(
    artifact: Mapping[str, Any],
) -> tuple[str, ...]:
    """Return the selected IDs only after full target-frontier verification."""

    _verified_target_cohort_frontier_rows(artifact)
    policy = _mapping(artifact.get("policy"), "target-cohort candidate frontier policy")
    return tuple(
        _required_str(candidate, "candidate_id")
        for candidate in cast(Sequence[Mapping[str, Any]], policy["candidates"])
        if candidate.get("selection_status") == "selected"
    )


def _reconciled_candidate_ids(payload: bytes, *, source: Path) -> tuple[str, ...]:
    """Extract the unique candidate order from captured reconciled-selection bytes."""

    records = _projection_jsonl_records(payload, source=source)
    candidate_ids: list[str] = []
    for record in records:
        value = record.get("selected")
        if not isinstance(value, bool):
            raise ValueError("reconciled selection row requires boolean selected")
        candidate_ids.append(_required_str(record, "candidate_id"))
    if len(candidate_ids) != len(set(candidate_ids)):
        raise ValueError("reconciled selection has duplicate candidates")
    return tuple(candidate_ids)


def _verify_replacement_initial_selection_lineage(
    *,
    initial_candidate_ids: tuple[str, ...],
    target_frontier_artifact: Mapping[str, Any],
    reconciled_selection_bytes: bytes,
    reconciled_selection_path: Path,
) -> tuple[JsonRecord, ...]:
    """Prove initial IDs came from the authenticated ranked/reconciled frontier."""

    candidate_rows = _verified_target_cohort_frontier_rows(target_frontier_artifact)
    frontier_policy = _mapping(
        target_frontier_artifact.get("policy"),
        "target-cohort candidate frontier policy",
    )
    frontier_commitments = _mapping(
        frontier_policy.get("source_commitments"),
        "target-cohort candidate frontier source commitments",
    )
    if frontier_commitments.get("reconciled_selection_sha256") != _bytes_sha256(
        reconciled_selection_bytes
    ):
        raise ClearanceReplacementError(
            "candidate selection differs from the authenticated target frontier"
        )
    reconciled_ids = _reconciled_candidate_ids(
        reconciled_selection_bytes,
        source=reconciled_selection_path,
    )
    initial_set = set(initial_candidate_ids)
    reconciled_initial_order = tuple(
        candidate_id for candidate_id in reconciled_ids if candidate_id in initial_set
    )
    if (
        initial_candidate_ids
        != _verified_target_frontier_selected_candidate_ids(target_frontier_artifact)
        or initial_candidate_ids != reconciled_initial_order
    ):
        raise ClearanceReplacementError(
            "initial selection differs from the verified target-frontier "
            "reconciled projection"
        )
    return candidate_rows


def _verified_target_cohort_frontier_rows(
    artifact: Mapping[str, Any],
) -> tuple[JsonRecord, ...]:
    if set(artifact) != {"schema_version", "policy", "policy_sha256"}:
        raise ValueError("target-cohort frontier artifact fields differ")
    policy = artifact.get("policy")
    if not isinstance(policy, Mapping):
        raise ValueError("target-cohort frontier policy must be an object")
    typed_policy = cast(Mapping[str, Any], policy)
    expected_policy_fields = {
        "target_case_count",
        "candidate_count",
        "selected_candidate_count",
        "frontier_truncated",
        "source_commitments",
        "clearance_contract",
        "candidates",
    }
    if set(typed_policy) != expected_policy_fields:
        raise ValueError("target-cohort frontier policy fields differ")
    if artifact.get("policy_sha256") != _canonical_json_sha256(typed_policy):
        raise ValueError("target-cohort frontier policy hash mismatch")
    if typed_policy.get("frontier_truncated") is not False:
        raise ValueError("target-cohort candidate frontier must be untruncated")
    commitments = typed_policy.get("source_commitments")
    if not isinstance(commitments, Mapping):
        raise ValueError("target-cohort candidate frontier lacks source commitments")
    typed_commitments = cast(Mapping[str, object], commitments)
    required_commitments = {
        "snapshot_manifest_sha256",
        "preparation_config_sha256",
        "reconciled_selection_sha256",
        "case_relevance_sha256",
        "download_manifest_sha256",
        "core_filter_results_sha256",
        "provisional_budget_plan_sha256",
        "restriction_evidence_sha256",
        "disclosure_review_requests_sha256",
    }
    posthoc_commitments = {
        "preparation_summary_sha256",
        "preparation_success_run_card_sha256",
    }
    commitment_keys = frozenset(typed_commitments)
    if commitment_keys not in {
        frozenset(required_commitments),
        frozenset(required_commitments | posthoc_commitments),
    }:
        raise ValueError("target-cohort frontier source commitments differ")
    for digest in typed_commitments.values():
        if (
            not isinstance(digest, str)
            or re.fullmatch(r"sha256:[0-9a-f]{64}", digest) is None
        ):
            raise ValueError(
                "target-cohort candidate frontier has invalid source commitment"
            )
    clearance_contract = typed_policy.get("clearance_contract")
    if not isinstance(clearance_contract, Mapping):
        raise ValueError("target-cohort frontier lacks clearance contract")
    typed_contract = cast(Mapping[str, Any], clearance_contract)
    expected_contract = {
        "run_card_schema_version": "legalforecast.acquisition_run_card.v1",
        "stage": "clear-disclosures",
        "required_status": "completed",
        "required_dry_run": False,
        "required_execute": True,
        "required_paid_activity_executed": False,
        "download_manifest_sha256": typed_commitments["download_manifest_sha256"],
        "restriction_evidence_sha256": typed_commitments["restriction_evidence_sha256"],
        "required_source_commitments": [
            "download_manifest",
            "restriction_evidence",
            "reviews",
            "review_receipt",
        ],
        "required_output_commitments": ["disclosure_clearance"],
        "required_review_authority_fields": [
            "reviewer_id",
            "controlled_store_uri",
            "authentication_method",
            "authenticated_at",
            "review_artifact_sha256",
        ],
        "orphan_clearance_rows_allowed": False,
    }
    if dict(typed_contract) != expected_contract:
        raise ValueError("target-cohort frontier clearance contract differs")
    raw_candidates = typed_policy.get("candidates")
    if not isinstance(raw_candidates, Sequence) or isinstance(
        raw_candidates, (str, bytes)
    ):
        raise ValueError("target-cohort frontier candidates must be a list")
    candidates: list[JsonRecord] = []
    selected_count = 0
    for expected_rank, raw_candidate in enumerate(
        cast(Sequence[object], raw_candidates), start=1
    ):
        if not isinstance(raw_candidate, Mapping):
            raise ValueError("target-cohort frontier candidate must be an object")
        candidate = dict(cast(Mapping[str, Any], raw_candidate))
        status = candidate.pop("selection_status", None)
        if status not in {
            "selected",
            "eligible_omitted",
            "excluded",
        }:
            raise ValueError("target-cohort frontier selection_status is invalid")
        if status == "selected":
            selected_count += 1
        exclusions = candidate.get("exclusion_reasons")
        if not isinstance(exclusions, Sequence) or isinstance(exclusions, (str, bytes)):
            raise ValueError("target-cohort frontier exclusions must be a list")
        if (status == "excluded") != bool(cast(Sequence[object], exclusions)):
            raise ValueError(
                "target-cohort frontier exclusion status conflicts with reasons"
            )
        if candidate.get("rank") != expected_rank:
            raise ValueError("target-cohort frontier rank sequence is not canonical")
        candidates.append(candidate)
    if typed_policy.get("candidate_count") != len(candidates):
        raise ValueError("target-cohort frontier candidate_count mismatch")
    if typed_policy.get("selected_candidate_count") != selected_count:
        raise ValueError("target-cohort frontier selected count mismatch")
    target_case_count = typed_policy.get("target_case_count")
    if (
        not isinstance(target_case_count, int)
        or isinstance(target_case_count, bool)
        or target_case_count < 1
        or target_case_count != selected_count
    ):
        raise ValueError("target-cohort frontier target count mismatch")
    return tuple(candidates)


def _semantic_target_100_stage_commands(
    stage_commands: Sequence[Mapping[str, Any]],
) -> list[JsonRecord]:
    """Exclude execution-only resume toggles from the frozen semantic config."""

    return [
        {
            "stage": command["stage"],
            "argv": [
                argument
                for argument in cast(Sequence[str], command["argv"])
                if argument not in {"--resume", "--no-resume"}
            ],
        }
        for command in stage_commands
    ]


def _target_100_stage_commitments(output_root: Path) -> JsonRecord:
    commitments: JsonRecord = {}
    for stage_name in (
        "01-public-plan",
        "02-free-download",
        "03-gap-bridge",
        "03b-bridge-free-download",
        "03c-merged-downloads",
        "04-core-filter",
        "05-budget",
        "06-clearance-inputs",
        "documents",
    ):
        stage_root = output_root / stage_name
        commitments[stage_name] = {
            str(path.relative_to(stage_root)): _path_sha256(path)
            for path in sorted(stage_root.rglob("*"))
            if path.is_file()
        }
    retarget_root = output_root / "retarget-import"
    retarget_receipt = output_root / RETARGET_IMPORT_RECEIPT_FILENAME
    if retarget_root.is_dir() or retarget_receipt.is_file():
        retarget_paths = [
            path for path in sorted(retarget_root.rglob("*")) if path.is_file()
        ]
        if retarget_receipt.is_file():
            retarget_paths.append(retarget_receipt)
        commitments["retarget-import"] = {
            str(path.relative_to(output_root)): _path_sha256(path)
            for path in retarget_paths
        }
    return commitments


def _verified_retarget_final_input_commitments(
    *,
    output_root: Path,
    frozen_config: Mapping[str, Any],
) -> dict[str, str]:
    raw_lineage = frozen_config.get("retarget_import")
    if raw_lineage is None:
        return {}
    lineage = _mapping(raw_lineage, "retarget import config lineage")
    if set(lineage) != {
        "source_preparation_root",
        "source_config_file_sha256",
        "source_config_self_hash",
        "source_tree_commitment",
        "receipt_path",
        "immutable_baseline_root",
    }:
        raise CommandError("retarget import config lineage fields differ")
    source_root = Path(_required_str(lineage, "source_preparation_root"))
    receipt_path = Path(_required_str(lineage, "receipt_path"))
    expected_receipt_path = output_root / RETARGET_IMPORT_RECEIPT_FILENAME
    baseline_root = output_root / _RETARGET_IMPORT_ROOT
    if (
        receipt_path.resolve() != expected_receipt_path.resolve()
        or Path(_required_str(lineage, "immutable_baseline_root")).resolve()
        != baseline_root.resolve()
    ):
        raise CommandError("retarget import config paths differ from target root")
    receipt = verify_retarget_import_receipt(
        receipt_path,
        source_root=source_root,
        target_root=output_root,
    )
    if (
        lineage.get("source_config_file_sha256") != receipt.source.config_file_sha256
        or lineage.get("source_config_self_hash") != receipt.source.config_self_hash
        or lineage.get("source_tree_commitment") != receipt.source_after.to_record()
    ):
        raise CommandError("retarget import source lineage commitment mismatch")
    imported_manifest = baseline_root / _RETARGET_IMPORTED_DOCUMENTS
    imported_records = _read_records(imported_manifest)
    imported_requests = tuple(
        _free_document_download_request(record) for record in imported_records
    )
    verified_imported = verify_completed_free_document_manifest(
        imported_requests,
        output_root=output_root / "documents/free",
        manifest_path=imported_manifest,
    )
    reuse_receipt_path = baseline_root / _RETARGET_DOCUMENT_REUSE_RECEIPT
    reuse_receipt = _read_json_object(reuse_receipt_path)
    if (
        reuse_receipt.get("schema_version")
        != "legalforecast.target_retarget_document_reuse.v1"
        or reuse_receipt.get("source_preparation_root") != str(receipt.source_root)
        or reuse_receipt.get("destination_document_root")
        != str((output_root / "documents/free").resolve())
        or reuse_receipt.get("imported_record_count") != len(verified_imported)
        or reuse_receipt.get("imported_manifest_sha256")
        != _path_sha256(imported_manifest)
        or reuse_receipt.get("provider_client_constructed") is not False
        or reuse_receipt.get("provider_request_count") != 0
        or reuse_receipt.get("network_request_count") != 0
        or reuse_receipt.get("paid_activity_requested") is not False
        or reuse_receipt.get("paid_activity_executed") is not False
    ):
        raise CommandError("retarget document-reuse receipt is inconsistent")
    _verify_retarget_reuse_checkpoint_commitments(
        reuse_receipt=reuse_receipt,
        source_document_root=receipt.source_root / "documents/free",
        destination_document_root=output_root / "documents/free",
        imported_records=verified_imported,
    )
    claimed_reuse_hash = reuse_receipt.get("receipt_sha256")
    unhashed_reuse = dict(reuse_receipt)
    unhashed_reuse.pop("receipt_sha256", None)
    if claimed_reuse_hash != _canonical_json_sha256(unhashed_reuse):
        raise CommandError("retarget document-reuse receipt self-hash mismatch")
    seed_receipt_path = _verify_target_retarget_live_seed(output_root=output_root)
    paths = (
        expected_receipt_path,
        imported_manifest,
        reuse_receipt_path,
        seed_receipt_path,
        *tuple(
            path
            for path in sorted((baseline_root / _RETARGET_BRIDGE_BASELINE).rglob("*"))
            if path.is_file()
        ),
    )
    return {str(path.resolve()): _path_sha256(path) for path in paths}


def _verify_retarget_reuse_checkpoint_commitments(
    *,
    reuse_receipt: Mapping[str, Any],
    source_document_root: Path,
    destination_document_root: Path,
    imported_records: tuple[FreeDocumentDownloadRecord, ...],
) -> None:
    """Verify source bytes and the canonical imported destination projection."""

    source_checkpoint = source_document_root / ".download-checkpoint.jsonl"
    destination_checkpoint = destination_document_root / ".download-checkpoint.jsonl"
    source_records = _read_records(source_checkpoint)
    try:
        destination_projection_sha256 = verified_checkpoint_projection_sha256(
            imported_records,
            checkpoint_path=destination_checkpoint,
        )
    except FreeDocumentDownloadError as exc:
        raise CommandError(
            "retarget document-reuse checkpoint commitment mismatch"
        ) from exc
    if (
        reuse_receipt.get("source_checkpoint_sha256") != _path_sha256(source_checkpoint)
        or reuse_receipt.get("source_checkpoint_record_count") != len(source_records)
        or reuse_receipt.get("destination_checkpoint_sha256")
        != destination_projection_sha256
    ):
        raise CommandError("retarget document-reuse checkpoint commitment mismatch")


def _target_100_stage_input_commitments(
    output_root: Path,
    *,
    config: TargetCohortPreparationConfig | Target100PreparationConfig,
    frozen_config: Mapping[str, Any],
    snapshot_manifest_sha256: str,
) -> JsonRecord:
    """Hash the authoritative inputs consumed at each preparation boundary."""

    screened_cases = config.authenticated_screened_cases
    authenticated_input_commitments = _verified_target_authenticated_input_commitments(
        config
    )
    bridge_route_commitments = _verified_target_bridge_route_commitments(output_root)
    paths: dict[str, tuple[Path, ...]] = {
        "01-public-plan": (
            config.snapshot / "manifest.json",
            screened_cases,
        ),
        "02-free-download": (
            output_root / "01-public-plan/free-document-requests.jsonl",
        ),
        "03-gap-bridge": (
            screened_cases,
            output_root / "01-public-plan/public-packet-selection.jsonl",
            output_root / "01-public-plan/public-packet-paid-gaps.jsonl",
            output_root / "02-free-download/free-document-downloads.jsonl",
        ),
        "04-core-filter": (output_root / "03-gap-bridge/case-relevance.jsonl",),
        "03b-bridge-free-download": (
            output_root / "03-gap-bridge/pacer-gap-free-document-requests.jsonl",
        ),
        "03c-merged-downloads": (
            output_root / "02-free-download/free-document-downloads.jsonl",
            output_root / "03b-bridge-free-download/free-document-downloads.jsonl",
        ),
        "05-budget": (output_root / "04-core-filter/core-filter-results.jsonl",),
        "06-clearance-inputs": (
            output_root / "03-gap-bridge/case-relevance.jsonl",
            output_root / "03c-merged-downloads/document-downloads-merged.jsonl",
        ),
    }
    candidate_selection = _frozen_merge_candidate_selection_path(
        preparation_root=output_root,
        config=frozen_config,
    )
    if candidate_selection is not None:
        paths["03c-merged-downloads"] += (candidate_selection,)
    if config.courtlistener_fixture is not None:
        paths["03-gap-bridge"] += (config.courtlistener_fixture,)
    commitments = {
        stage: {str(path.resolve()): _path_sha256(path) for path in stage_paths}
        for stage, stage_paths in paths.items()
    }
    commitments["01-public-plan"] = {
        str((config.snapshot / "manifest.json").resolve()): (
            "sha256:" + snapshot_manifest_sha256
        ),
        str(screened_cases.resolve()): "sha256:" + config.screened_cases_sha256,
    }
    commitments["01-public-plan"].update(authenticated_input_commitments)
    commitments["03-gap-bridge"].update(authenticated_input_commitments)
    commitments["03-gap-bridge"].update(bridge_route_commitments)
    retarget_commitments = _verified_retarget_final_input_commitments(
        output_root=output_root,
        frozen_config=frozen_config,
    )
    if retarget_commitments:
        commitments["retarget-import"] = retarget_commitments
    return commitments


def _missing_core_exclusion_notes(
    case_plan: CaseMissingCorePurchasePlan,
    plan: MissingCoreBudgetPlan,
) -> str:
    if "missing_core_document_cap_exceeded" in case_plan.exclusion_reasons:
        return (
            f"Candidate requires {case_plan.missing_core_document_count} missing "
            "core documents; configured per-case cap is "
            f"{plan.max_missing_core_documents_per_case}."
        )
    return "Candidate failed the core-document acquisition gate."


def _cmd_acquisition_filter_core_documents(args: argparse.Namespace) -> int:
    output_root = _acquisition_output_root(args)
    input_path = cast(Path, args.case_relevance)
    output_path = _acquisition_path(
        args,
        "results_output",
        output_root / "core-filter-results.jsonl",
    )
    results = filter_core_documents(read_case_relevance_jsonl(input_path))
    dry_run = _acquisition_dry_run(args)
    if dry_run:
        _write_jsonl(
            output_path,
            [
                {
                    "stage": "filter-core-documents",
                    "dry_run": True,
                    "result_count": len(results),
                }
            ],
        )
    else:
        write_core_document_filter_results(results, output_path)
    _write_acquisition_completion(
        args,
        stage="filter-core-documents",
        input_paths=(input_path,),
        output_paths=(output_path,),
        record_count=len(results),
        dry_run=dry_run,
        paid_activity_requested=False,
        paid_activity_executed=False,
        extra={
            "purchase_document_count": sum(
                len(result.purchase_document_ids) for result in results
            ),
            "excluded_case_count": sum(result.excluded for result in results),
        },
    )
    return 0


def _cmd_acquisition_discover_case_dev(args: argparse.Namespace) -> int:
    output_root = _acquisition_output_root(args)
    batch_id = cast(str, args.batch_id)
    store_path = _acquisition_path(
        args,
        "cycle_store",
        output_root / "cycle-acquisition.sqlite3",
    )
    candidates_path = _acquisition_path(
        args,
        "candidates_output",
        output_root / "checkpoints" / f"{batch_id}-case-dev-candidates.partial.jsonl",
    )
    summary_path = _acquisition_path(
        args,
        "summary_output",
        output_root / "checkpoints" / f"{batch_id}-case-dev-summary.partial.json",
    )
    anchor = _iso_date_argument(
        cast(str, args.decision_filed_on_or_after),
        "--decision-filed-on-or-after",
    )
    window_end = _iso_date_argument(
        cast(str, args.decision_filed_on_or_before),
        "--decision-filed-on-or-before",
    )
    if window_end < anchor:
        raise CommandError(
            "--decision-filed-on-or-before cannot precede the eligibility anchor"
        )
    query_terms = tuple(cast(Sequence[str] | None, args.query_terms) or ())
    if not query_terms:
        query_terms = case_dev_smoke_query_terms()
    per_term_limit = cast(int, args.per_term_limit)
    search_page_size = cast(int, args.search_page_size)
    if per_term_limit <= 0:
        raise CommandError("--per-term-limit must be positive")
    if search_page_size <= 0:
        raise CommandError("--search-page-size must be positive")
    fixture_path = cast(Path | None, args.case_dev_fixture)
    live = cast(bool, args.live)
    dry_run = _acquisition_dry_run(args)
    input_paths = () if fixture_path is None else (fixture_path,)
    output_paths = (store_path, candidates_path, summary_path)
    policy = _cycle_acquisition_policy(anchor=anchor)
    batch_config: JsonRecord = {
        "provider": "case.dev",
        "decision_window_start": anchor.isoformat(),
        "decision_window_end": window_end.isoformat(),
        "query_terms": list(query_terms),
        "query_term_order_is_frozen": True,
        "per_term_limit": per_term_limit,
        "search_page_size": search_page_size,
    }

    if dry_run:
        _write_json(
            summary_path,
            {
                "schema_version": "legalforecast.case_dev_discovery_summary.v1",
                "dry_run": True,
                "batch_id": batch_id,
                "query_terms": list(query_terms),
                "checkpoint_only": True,
                "complete": False,
                "saturated": False,
                "anchored_disposition_discovery": False,
                **batch_config,
            },
        )
        _write_acquisition_completion(
            args,
            stage="discover-case-dev",
            input_paths=input_paths,
            output_paths=output_paths,
            record_count=0,
            dry_run=True,
            paid_activity_requested=False,
            paid_activity_executed=False,
            extra={"batch_id": batch_id, "per_term_limit": per_term_limit},
        )
        return 0

    if live and fixture_path is not None:
        raise CommandError("choose --case-dev-fixture or --live, not both")
    try:
        client = _case_dev_client(
            command="discover-case-dev",
            fixture_path=fixture_path,
            live=live,
        )
        with CycleAcquisitionStore(store_path) as store:
            cycle_hash = store.ensure_cycle(policy)
            batch_digest = store.ensure_batch(batch_id, batch_config)
            result = materialize_independent_term_sets(
                source=CaseDevDiscoverySource(client),
                store=store,
                batch_id=batch_id,
                query_terms=query_terms,
                top_k_per_term=per_term_limit,
                page_size=search_page_size,
            )
            checkpoint_records = [
                case_dev_firecrawl_candidate_record(hit)
                for hit in store.candidate_discovery_hits(batch_id)
            ]
    except (
        CaseDevClientError,
        ConfigMismatchError,
        CycleAcquisitionStoreError,
        DiscoverySchedulerError,
        ValueError,
    ) as exc:
        _write_acquisition_failure(
            args,
            stage="discover-case-dev",
            input_paths=input_paths,
            output_paths=output_paths,
            reason=str(exc),
            paid_activity_requested=False,
        )
        raise CommandError(str(exc)) from exc

    _write_jsonl(candidates_path, checkpoint_records)
    summary: JsonRecord = {
        "schema_version": "legalforecast.case_dev_discovery_summary.v1",
        "dry_run": False,
        "batch_id": batch_id,
        "cycle_hash": cycle_hash,
        "batch_digest": batch_digest,
        "query_terms": list(query_terms),
        "candidate_count": len(checkpoint_records),
        "complete": False,
        "saturated": False,
        "provider_pagination_end_observed": result.complete,
        "provider_completeness_status": "unknown",
        "provider_saturation_status": "unproven",
        "anchored_disposition_discovery": False,
        "candidate_count_semantics": (
            "exploratory case/party metadata leads only; not post-anchor "
            "dispositions or clean corpus cases"
        ),
        "terminal_status_by_term": {
            term: status.value
            for term, status in result.terminal_status_by_term.items()
        },
        "checkpoint_only": True,
        "case_dev_request_count": client.request_count,
        **batch_config,
    }
    _write_json(summary_path, summary)
    _write_acquisition_completion(
        args,
        stage="discover-case-dev",
        input_paths=input_paths,
        output_paths=output_paths,
        record_count=len(checkpoint_records),
        dry_run=False,
        paid_activity_requested=False,
        paid_activity_executed=False,
        extra=summary,
    )
    return 0


def _validate_decision_recap_artifact(raw_html: str, source_url: str) -> None:
    """Reject malformed decision-search HTML before it becomes a success."""

    parse_decision_recap_search_html(raw_html, source_url=source_url)


class _BudgetedRecapSearchTransport:
    """Adapt page-at-a-time RECAP discovery to the durable scheduler."""

    def __init__(
        self,
        scheduler: BudgetedFirecrawlScheduler,
        *,
        inherited_pages: Sequence[FirecrawlPageRecord] = (),
        continuation_scheduler: BudgetedFirecrawlScheduler | None = None,
        fallback_source_urls: frozenset[str] = frozenset(),
        parse_search_url: Callable[[str], RecapSearchTarget] = parse_recap_search_url,
    ) -> None:
        self.scheduler = scheduler
        self.continuation_scheduler = continuation_scheduler or scheduler
        self._fallback_source_urls = fallback_source_urls
        self._parse_search_url = parse_search_url
        self._traversed_fallback_urls: set[str] = set()
        self._ordinals: dict[str, int] = {}
        self._pages: dict[str, FirecrawlPageRecord] = {}
        self._inherited_pages = {page.source_url: page for page in inherited_pages}
        if len(self._inherited_pages) != len(inherited_pages):
            raise ValueError("recovery parent contains duplicate successful page URLs")

    @property
    def pages(self) -> tuple[FirecrawlPageRecord, ...]:
        return tuple(
            self._pages[url]
            for url, _ordinal in sorted(
                self._ordinals.items(), key=lambda item: item[1]
            )
        )

    @property
    def unrecovered_fallback_urls(self) -> frozenset[str]:
        return self._fallback_source_urls - self._traversed_fallback_urls

    def fetch(self, *, source_url: str) -> str:
        target = self._parse_search_url(source_url)
        ordinal = self._ordinals.setdefault(source_url, len(self._ordinals))
        inherited = self._inherited_pages.get(source_url)
        if inherited is not None:
            if inherited.target_kind != "search":
                raise RecapSearchError(
                    "recovery parent page is not a RECAP search target"
                )
            self._pages[source_url] = inherited
            return inherited.raw_html
        target_id = (
            "recap-search-"
            + hashlib.sha256(source_url.encode("utf-8")).hexdigest()[:24]
        )
        use_fallback = source_url in self._fallback_source_urls
        selected_scheduler = (
            self.scheduler if use_fallback else self.continuation_scheduler
        )
        result = selected_scheduler.run(
            (
                FirecrawlTargetSpec(
                    target_id=target_id,
                    target_kind="search",
                    source_url=source_url,
                    page_number=target.page,
                    ordinal=ordinal,
                ),
            )
        )
        page = next(
            (record for record in result.pages if record.target_id == target_id),
            None,
        )
        if page is None:
            raise RecapSearchError(
                "Firecrawl retries were exhausted before a complete RECAP page "
                f"was acquired: {target.term} page {target.page}"
            )
        if use_fallback:
            self._traversed_fallback_urls.add(source_url)
        self._pages[source_url] = page
        return page.raw_html


def _cmd_acquisition_project_firecrawl_recap_checkpoint(
    args: argparse.Namespace,
) -> int:
    """Materialize verified successful pages without claiming search completion."""

    output_root = _acquisition_output_root(args)
    store_path = cast(Path, args.cycle_store)
    run_ids = tuple(cast(Sequence[str], args.run_ids))
    if len(set(run_ids)) != len(run_ids):
        raise CommandError("--run-id values must be unique")
    run_id = run_ids[0]
    projection_id = run_id
    if len(run_ids) > 1:
        digest = hashlib.sha256("\0".join(run_ids).encode("utf-8")).hexdigest()[:12]
        projection_id = f"{run_id}-union-{digest}"
    pages_path = _acquisition_path(
        args,
        "pages_output",
        output_root / "checkpoints" / f"{projection_id}-partial-recap-pages.jsonl",
    )
    entries_path = _acquisition_path(
        args,
        "entries_output",
        output_root / "checkpoints" / f"{projection_id}-partial-recap-entries.jsonl",
    )
    dockets_path = _acquisition_path(
        args,
        "dockets_output",
        output_root / "checkpoints" / f"{projection_id}-partial-recap-dockets.jsonl",
    )
    summary_path = _acquisition_path(
        args,
        "summary_output",
        output_root / "checkpoints" / f"{projection_id}-partial-recap-summary.json",
    )
    input_paths = (store_path,)
    output_paths = (pages_path, entries_path, dockets_path, summary_path)
    dry_run = _acquisition_dry_run(args)
    if dry_run:
        summary: JsonRecord = {
            "schema_version": "legalforecast.recap_partial_checkpoint_summary.v1",
            "dry_run": True,
            "run_id": run_id,
            "run_ids": list(run_ids),
            "store_projection_committed": False,
            "acquired_page_count": 0,
            "raw_hit_count": 0,
            "unique_entry_count": 0,
            "duplicate_entry_count": 0,
            "unique_docket_count": 0,
            "potential_candidate_count": 0,
            "clean_corpus_count": 0,
            "provider_completeness_status": "unproven",
            "provider_saturation_status": "unproven",
            "checkpoint_only": True,
            "complete": False,
            "saturated": False,
            "candidate_count_semantics": (
                "potential dockets only; full eligibility, documents, leakage, "
                "parsing, unitization, and labeling remain required"
            ),
            "firecrawl_metered_activity_requested": False,
            "firecrawl_metered_activity_executed": False,
            "pacer_paid_activity_requested": False,
            "pacer_paid_activity_executed": False,
        }
        _write_jsonl(pages_path, [])
        _write_jsonl(entries_path, [])
        _write_jsonl(dockets_path, [])
        _write_json(summary_path, summary)
        _write_acquisition_completion(
            args,
            stage="project-firecrawl-recap-checkpoint",
            input_paths=input_paths,
            output_paths=output_paths,
            record_count=0,
            dry_run=True,
            paid_activity_requested=False,
            paid_activity_executed=False,
            extra=summary,
        )
        return 0

    try:
        with CycleAcquisitionStore(store_path) as store:
            credit_summaries = {
                source_run_id: dict(store.firecrawl_run_summary(source_run_id))
                for source_run_id in run_ids
            }
            credit_summary = credit_summaries[run_id]
            batch_id_value = credit_summary.get("batch_id")
            if not isinstance(batch_id_value, str) or not batch_id_value:
                raise CycleAcquisitionStoreError(
                    "durable Firecrawl run has no valid batch identity"
                )
            batch_id = batch_id_value
            pages_by_url: dict[str, FirecrawlPageRecord] = {}
            for source_run_id in run_ids:
                source_summary = credit_summaries[source_run_id]
                if source_summary.get("batch_id") != batch_id:
                    raise ConfigMismatchError(
                        "Firecrawl checkpoint union crosses frozen batches"
                    )
                for page in load_successful_firecrawl_pages(
                    store=store, run_id=source_run_id
                ):
                    prior = pages_by_url.get(page.source_url)
                    if (
                        prior is not None
                        and prior.artifact_sha256 != page.artifact_sha256
                    ):
                        raise FirecrawlArtifactError(
                            "conflicting verified bytes for checkpoint search URL "
                            f"{page.source_url}"
                        )
                    pages_by_url.setdefault(page.source_url, page)
            pages = tuple(pages_by_url.values())
            if not pages:
                raise RecapPartialProjectionError(
                    "durable Firecrawl run contains no successful search pages"
                )
            frozen_config = store.batch_config(batch_id)
            frozen_terms_value = frozen_config.get("query_terms")
            if frozen_terms_value is None:
                frozen_terms_value = frozen_config.get("terms")
            if not isinstance(frozen_terms_value, list):
                raise ConfigMismatchError(
                    "frozen batch has no valid ordered search-term plan"
                )
            frozen_term_items = cast(list[object], frozen_terms_value)
            frozen_terms = tuple(
                term for term in frozen_term_items if isinstance(term, str)
            )
            if len(frozen_terms) != len(frozen_term_items):
                raise ConfigMismatchError(
                    "frozen batch has no valid ordered search-term plan"
                )
            frozen_term_ordinals = {
                term: ordinal for ordinal, term in enumerate(frozen_terms)
            }
            frozen_query_plan = frozen_config.get("courtlistener_query_plan_version")
            if frozen_query_plan == DECISION_FIRST_RECAP_QUERY_PLAN_VERSION:
                parse_search_url = parse_decision_recap_search_url
                parse_search_html = parse_decision_recap_search_html
            elif frozen_query_plan in (None, COURTLISTENER_QUERY_PLAN_VERSION):
                parse_search_url = parse_recap_search_url
                parse_search_html = parse_recap_search_html
            else:
                raise ConfigMismatchError(
                    "frozen batch has an unknown CourtListener query plan"
                )
            parsed_targets = {
                page.source_url: parse_search_url(page.source_url) for page in pages
            }
            if any(
                target.term not in frozen_term_ordinals
                for target in parsed_targets.values()
            ):
                raise ConfigMismatchError(
                    "verified page term is absent from the frozen batch plan"
                )
            pages = tuple(
                replace(page, ordinal=ordinal)
                for ordinal, page in enumerate(
                    sorted(
                        pages,
                        key=lambda item: (
                            frozen_term_ordinals[parsed_targets[item.source_url].term],
                            parsed_targets[item.source_url].page,
                            item.source_url,
                        ),
                    )
                )
            )
            projection = project_partial_recap_checkpoint(
                pages,
                parse_search_html=parse_search_html,
            )
            _commit_recap_discovery_pages(
                store=store,
                batch_id=batch_id,
                pages=pages,
                parse_search_html=parse_search_html,
            )
            projected_candidate_ids = {
                candidate.candidate_id for candidate in projection.candidates
            }
            stored_candidate_ids = set(store.candidate_ids(batch_id))
            if stored_candidate_ids != projected_candidate_ids:
                raise CycleAcquisitionStoreError(
                    "partial checkpoint candidates do not reconcile to the "
                    "durable batch projection"
                )
            cycle_hash = store.cycle_hash
            batch_digest = store.batch_digest(batch_id)
            cycle_policy = store.cycle_policy
            frozen_batch_config = store.batch_config(batch_id)
    except (
        BudgetedDocketAcquisitionError,
        CycleAcquisitionStoreError,
        FirecrawlArtifactError,
        KeyError,
        OSError,
        RecapPartialProjectionError,
        ValueError,
    ) as exc:
        _write_acquisition_failure(
            args,
            stage="project-firecrawl-recap-checkpoint",
            input_paths=input_paths,
            output_paths=output_paths,
            reason=str(exc),
            paid_activity_requested=False,
            paid_activity_executed=False,
            extra={
                "run_id": run_id,
                "run_ids": list(run_ids),
                "checkpoint_only": True,
                "complete": False,
                "saturated": False,
                "firecrawl_metered_activity_requested": False,
                "firecrawl_metered_activity_executed": False,
                "pacer_paid_activity_requested": False,
                "pacer_paid_activity_executed": False,
            },
        )
        raise CommandError(str(exc)) from exc

    page_records = [asdict(page) for page in projection.pages]
    entry_records = [asdict(entry) for entry in projection.entries]
    docket_records = [
        {**asdict(candidate), "eligibility_status": "potential_unverified"}
        for candidate in projection.candidates
    ]
    summary = {
        "schema_version": "legalforecast.recap_partial_checkpoint_summary.v1",
        "dry_run": False,
        "cycle_hash": cycle_hash,
        "batch_digest": batch_digest,
        "eligibility_anchor": cycle_policy.get("eligibility_anchor"),
        "search_window_start": frozen_batch_config.get("search_window_start"),
        "search_window_end": frozen_batch_config.get("search_window_end"),
        "store_projection_committed": True,
        "run_ids": list(run_ids),
        "source_run_credit_summaries": credit_summaries,
        "potential_candidate_count": len(docket_records),
        "clean_corpus_count": 0,
        "candidate_count_semantics": (
            "potential dockets only; full eligibility, documents, leakage, parsing, "
            "unitization, and labeling remain required"
        ),
        "firecrawl_metered_activity_requested": False,
        "firecrawl_metered_activity_executed": False,
        "pacer_paid_activity_requested": False,
        "pacer_paid_activity_executed": False,
        "recap_fetch_authorized": False,
        "document_purchase_authorized": False,
        "model_calls_authorized": False,
        "evaluation_authorized": False,
        "freeze_or_dispatch_authorized": False,
        **asdict(projection.summary),
        **credit_summary,
    }
    _write_jsonl(pages_path, page_records)
    _write_jsonl(entries_path, entry_records)
    _write_jsonl(dockets_path, docket_records)
    _write_json(summary_path, summary)
    _write_acquisition_completion(
        args,
        stage="project-firecrawl-recap-checkpoint",
        input_paths=input_paths,
        output_paths=output_paths,
        record_count=len(docket_records),
        dry_run=False,
        paid_activity_requested=False,
        paid_activity_executed=False,
        extra=summary,
    )
    return 0


def _cmd_acquisition_render_cycle_config(args: argparse.Namespace) -> int:
    """Render a complete canonical cycle config without executing any stage."""

    try:
        receipt = render_cycle_config(
            template_path=cast(Path, args.template),
            output_path=cast(Path, args.output),
            variable_assignments=cast(list[str], args.variable),
            argument_validator=_validate_rendered_cycle_arguments,
        )
    except CycleManifestTemplateError as exc:
        raise CommandError(str(exc)) from exc
    print(json.dumps(receipt, sort_keys=True))
    return 0


def _cmd_acquisition_cycle_path_metadata(args: argparse.Namespace) -> int:
    """Publish the verified machine-local path map for a frozen cycle."""

    try:
        record = materialize_cycle_path_metadata(
            approval_checkpoint=cast(Path, args.approval_checkpoint),
            expected_approval_checkpoint_sha256=cast(
                str, args.expected_approval_checkpoint_sha256
            ),
            parser_root=cast(Path, args.parser_root),
            expected_parser_commit=cast(str, args.expected_parser_commit),
            output=cast(Path, args.output),
        )
    except CyclePathMetadataError as exc:
        raise CommandError(str(exc)) from exc
    print(json.dumps(record, sort_keys=True))
    return 0


def _cycle_lineage_index_path(args: argparse.Namespace) -> Path:
    configured = cast(Path | None, args.index)
    if configured is not None:
        return configured
    environment_value = os.environ.get(INDEX_ENVIRONMENT_VARIABLE)
    if not environment_value:
        raise CommandError(
            "cycle lineage index is not configured; pass --index or set "
            f"{INDEX_ENVIRONMENT_VARIABLE}"
        )
    return Path(environment_value)


def _cmd_acquisition_register_cycle_lineage(args: argparse.Namespace) -> int:
    """Verify and add one candidate to the rebuildable advisory index."""

    try:
        result = register_cycle_lineage(
            index_path=_cycle_lineage_index_path(args),
            config_path=cast(Path, args.config),
            state_root=cast(Path, args.state_root),
            code_commit=cast(str, args.code_commit),
            supersedes_config_sha256=cast(str | None, args.supersedes_config_sha256),
        )
    except CycleLineageIndexError as exc:
        raise CommandError(str(exc)) from exc
    if cast(bool, args.json) or not sys.stdout.isatty():
        print(json.dumps(result, sort_keys=True))
    else:
        print(
            f"registered {result['cycle_id']} config {result['config_sha256']} "
            f"({result['completed_stage_count']}/{result['stage_count']} stages)"
        )
    return 0


def _cmd_acquisition_locate_cycle_lineage(args: argparse.Namespace) -> int:
    """Locate and authenticate the unique current lineage."""

    try:
        result = locate_cycle_lineage(
            index_path=_cycle_lineage_index_path(args),
            cycle_id=cast(str | None, args.cycle_id),
        )
    except CycleLineageIndexError as exc:
        raise CommandError(str(exc)) from exc
    if cast(bool, args.json) or not sys.stdout.isatty():
        print(json.dumps(result, sort_keys=True))
    else:
        print(
            f"{result['cycle_id']}: {result['verification']} "
            f"stage={result['stage']} status={result['stage_status']}"
        )
        decisions = cast(list[object], result["human_decisions"])
        for raw_decision in decisions:
            if isinstance(raw_decision, Mapping):
                decision = cast(Mapping[str, object], raw_decision)
                print(
                    f"human decision {decision['stage']}: {decision['status']} "
                    f"({decision['verification']})"
                )
    return 0


def _authenticate_current_v4_eligibility(
    *,
    card: Mapping[str, Any],
    lineage: _StageAUnitizationLineage,
) -> tuple[Path, Path, dict[Path, bytes]]:
    """Replay the v4 gate before its paths can be recommended for reuse."""

    raw_eligibility = card.get("target_document_eligibility_audit")
    if not isinstance(raw_eligibility, Mapping):
        raise SuccessorRerunImpactError(
            "authenticated v4 unitization card lacks eligibility commitments"
        )
    eligibility = cast(Mapping[str, object], raw_eligibility)
    audit_path = _stage_a_committed_path(eligibility, "audit")
    run_card_path = _stage_a_committed_path(eligibility, "run_card")
    snapshots = {
        path: _read_singly_linked_regular_input(
            path, label=f"authenticated v4 eligibility {name}"
        )
        for name, path in (("audit", audit_path), ("run_card", run_card_path))
    }
    try:
        run_card = _read_json_object_payload(
            snapshots[run_card_path],
            label="target-document eligibility audit run card",
        )
    except ValueError as exc:
        raise SuccessorRerunImpactError(
            "target-document eligibility audit run card is invalid"
        ) from exc
    raw_replay_paths = run_card.get("replay_paths")
    if not isinstance(raw_replay_paths, Mapping):
        raise SuccessorRerunImpactError(
            "target-document eligibility audit replay paths are invalid"
        )
    typed_replay_paths = cast(Mapping[object, object], raw_replay_paths)
    if set(typed_replay_paths) != {
        "controlled_private_root",
        "purchase_ledger_initialization_receipt",
    }:
        raise SuccessorRerunImpactError(
            "target-document eligibility audit replay paths are invalid"
        )
    replay_paths: dict[str, Path | None] = {}
    for raw_name, raw_path in typed_replay_paths.items():
        if not isinstance(raw_name, str):
            raise SuccessorRerunImpactError(
                "target-document eligibility audit replay paths are invalid"
            )
        name = raw_name
        if raw_path is None:
            replay_paths[name] = None
        elif isinstance(raw_path, str) and raw_path.strip():
            replay_paths[name] = Path(raw_path)
        else:
            raise SuccessorRerunImpactError(
                "target-document eligibility audit replay paths are invalid"
            )
    parse_args = argparse.Namespace(
        selection=_stage_a_committed_path(lineage.input_commitments, "selection"),
        selection_run_card=_stage_a_committed_path(
            lineage.input_commitments, "selection_run_card"
        ),
        download_manifest=_stage_a_committed_path(
            lineage.input_commitments, "download_manifest"
        ),
        disclosure_clearance=_stage_a_committed_path(
            lineage.input_commitments, "disclosure_clearance"
        ),
        materialization_run_card=_stage_a_committed_path(
            lineage.input_commitments, "materialization_run_card"
        ),
        document_root=lineage.document_root,
        parse_requests=_stage_a_committed_path(
            lineage.input_commitments, "parse_requests"
        ),
        parser_manifest=_stage_a_committed_path(
            lineage.input_commitments, "parser_manifest"
        ),
        parser_run_card=_stage_a_committed_path(
            lineage.input_commitments, "parser_run_card"
        ),
        controlled_private_root=replay_paths["controlled_private_root"],
        purchase_ledger_initialization_receipt=replay_paths[
            "purchase_ledger_initialization_receipt"
        ],
    )
    parse_lineage = _verify_verified_stage_a_parse_lineage(
        parse_args, markdown_root=lineage.markdown_root
    )
    _require_v4_eligibility_lineage_matches_unitization(parse_lineage, lineage)
    replayed = _require_clean_v4_target_document_eligibility_audit(
        audit_path=audit_path,
        run_card_path=run_card_path,
        lineage=parse_lineage,
        replay_paths=replay_paths,
    )
    if dict(eligibility) != replayed:
        raise SuccessorRerunImpactError(
            "authenticated v4 eligibility commitment differs from semantic replay"
        )
    return audit_path, run_card_path, snapshots


def _cmd_acquisition_successor_rerun_impact(args: argparse.Namespace) -> int:
    """Print a provider-free advisory comparison of successor Stage A inputs."""

    cycle_id = cast(str, args.cycle_id)
    run_card_path = cast(Path, args.llm_unitize_run_card).resolve()
    proposal_path = cast(Path, args.proposed_inputs)
    exit_code = 0
    try:
        index_path = _cycle_lineage_index_path(args)
        lineage_status = locate_cycle_lineage(index_path=index_path, cycle_id=cycle_id)
        chain = _active_head_chain(index_path, cycle_id)
        matching_heads = [
            head
            for head in chain
            if Path(cast(str, head["run_card_path"])).resolve() == run_card_path
            and head.get("stage") == "llm-unitize"
        ]
        if len(matching_heads) != 1:
            raise SuccessorRerunImpactError(
                "llm-unitize run card is not unique in the active lineage"
            )
        run_card_bytes = _read_singly_linked_regular_input(
            run_card_path, label="llm-unitize run card"
        )
        card = _projection_json_object(run_card_bytes, source=run_card_path)
        outputs = card.get("output_commitments")
        if not isinstance(outputs, Mapping):
            raise SuccessorRerunImpactError(
                "llm-unitize run card lacks output commitments"
            )
        output_records = cast(Mapping[str, object], outputs)
        raw_path = _stage_a_committed_path(output_records, "prediction_units")
        audit_path = _stage_a_committed_path(output_records, "llm_unitization_audit")
        queue_path = _stage_a_committed_path(output_records, "unitization_review_queue")
        terminal_snapshots = {
            run_card_path: run_card_bytes,
            raw_path: _read_singly_linked_regular_input(
                raw_path, label="llm-unitize prediction units"
            ),
            audit_path: _read_singly_linked_regular_input(
                audit_path, label="llm-unitize audit"
            ),
            queue_path: _read_singly_linked_regular_input(
                queue_path, label="llm-unitize review queue"
            ),
        }
        terminal_captured = {
            os.path.abspath(path): payload
            for path, payload in terminal_snapshots.items()
        }
        roots = card.get("lineage_roots")
        if not isinstance(roots, Mapping):
            raise SuccessorRerunImpactError(
                "llm-unitize run card lacks provider journal root"
            )
        typed_roots = cast(Mapping[str, object], roots)
        if not isinstance(typed_roots.get("provider_journal"), str):
            raise SuccessorRerunImpactError(
                "llm-unitize run card lacks provider journal root"
            )
        journal_path = Path(cast(str, typed_roots["provider_journal"]))
        journal_state = _provider_journal_durable_bytes(journal_path)
        journal_snapshot = open_provider_journal_snapshot(journal_path)
        try:
            lineage = _verify_stage_a_unitization_run_card(
                run_card_path,
                expected_prediction_units_path=raw_path,
                expected_review_queue_path=queue_path,
                expected_audit_path=audit_path,
                journal_snapshot=journal_snapshot,
                captured_input_bytes=terminal_captured,
            )
        finally:
            journal_snapshot.close()
        namespace = _stage_a_provider_attempt_namespace_from_unitization_card_record(
            card
        )
        selection_path = _stage_a_committed_path(lineage.input_commitments, "selection")
        selection_run_card_path = _stage_a_committed_path(
            lineage.input_commitments, "selection_run_card"
        )
        download_manifest_path = _stage_a_committed_path(
            lineage.input_commitments, "download_manifest"
        )
        disclosure_clearance_path = _stage_a_committed_path(
            lineage.input_commitments, "disclosure_clearance"
        )
        materialization_run_card_path = _stage_a_committed_path(
            lineage.input_commitments, "materialization_run_card"
        )
        parse_requests_path = _stage_a_committed_path(
            lineage.input_commitments, "parse_requests"
        )
        parser_manifest_path = _stage_a_committed_path(
            lineage.input_commitments, "parser_manifest"
        )
        parser_run_card_path = _stage_a_committed_path(
            lineage.input_commitments, "parser_run_card"
        )
        eligibility_audit_path: Path | None = None
        eligibility_run_card_path: Path | None = None
        eligibility_snapshots: dict[Path, bytes] = {}
        if namespace in {
            STAGE_A_CLAIM_ONTOLOGY_V4_PROMPT_CONTRACT,
            STAGE_A_CLAIM_ONTOLOGY_V5_PROMPT_CONTRACT,
        }:
            (
                eligibility_audit_path,
                eligibility_run_card_path,
                eligibility_snapshots,
            ) = _authenticate_current_v4_eligibility(card=card, lineage=lineage)
        parser_reuse = _authenticate_live_mistral_parse_reuse(
            prior_run_card_path=parser_run_card_path,
            prior_markdown_root=lineage.markdown_root,
        )
        proposal_envelope = load_successor_proposal(proposal_path)
        proposed_materialization = _verify_materialized_downstream_lineage(
            run_card_path=proposal_envelope.materialization_run_card_path,
            manifest_path=proposal_envelope.download_manifest_path,
            clearance_path=proposal_envelope.disclosure_clearance_path,
            document_root=proposal_envelope.document_root,
            selection_path=proposal_envelope.selection_path,
        )
        proposed_selection_bytes = proposed_materialization.artifact_bytes[
            os.path.abspath(proposal_envelope.selection_path)
        ]
        proposed_selection_card_bytes = _read_singly_linked_regular_input(
            proposal_envelope.selection_run_card_path,
            label="proposed selection run card",
        )
        proposed_selection_card = _projection_json_object(
            proposed_selection_card_bytes,
            source=proposal_envelope.selection_run_card_path,
        )
        _validate_selection_run_card_commitment(
            proposed_selection_card,
            selection_path=proposal_envelope.selection_path,
            selection_bytes=proposed_selection_bytes,
            selection_sha256=_bytes_sha256(proposed_selection_bytes),
            selection_record_count=len(proposed_materialization.selection_records),
            selection_run_card_path=proposal_envelope.selection_run_card_path,
            selection_run_card_bytes=proposed_selection_card_bytes,
            verified_successor_selection_card=(
                proposed_materialization.verified_successor_selection_card
            ),
        )
        proposed_registry_bytes = _read_singly_linked_regular_input(
            proposal_envelope.model_registry_path, label="proposed model registry"
        )
        proposed_entries, proposed_registry_sha256 = _registry_entries_for_keys_bytes(
            proposed_registry_bytes, (proposal_envelope.model_key,)
        )
        proposed_policy_bytes = _read_singly_linked_regular_input(
            proposal_envelope.policy_path, label="proposed provider policy"
        )
        proposed_caps = load_provider_cycle_caps_bytes(
            proposed_policy_bytes, source=proposal_envelope.policy_path
        )
        proposed_cycle_id = _materialization_cohort_cycle_id(
            proposal_envelope.materialization_run_card_path,
            captured_artifact_bytes=proposed_materialization.artifact_bytes,
        )
        if proposed_caps.cycle_id != proposed_cycle_id:
            raise SuccessorRerunImpactError("proposed provider policy cycle_id differs")
        proposed_account = _local_provider_account(
            proposed_caps, proposed_entries[0].provider
        )
        proposal = bind_verified_successor_proposal(
            proposal_envelope,
            cycle_id=proposed_cycle_id,
            selection_records=proposed_materialization.selection_records,
            download_records=proposed_materialization.manifest_records,
            model_provider=proposed_entries[0].provider,
            provider_account=proposed_account,
            model_registry_sha256=proposed_registry_sha256,
            policy_sha256=hashlib.sha256(proposed_policy_bytes).hexdigest(),
        )
        current_documents = verified_documents_from_records(
            lineage.selection_records,
            lineage.download_records,
            document_root=lineage.document_root,
        )
        current = RerunInputs(
            cycle_id=lineage.cohort_cycle_id,
            selection_records=lineage.selection_records,
            documents=current_documents,
            provider_attempt_namespace=namespace,
            model_key=lineage.registry_entry.registry_key,
            model_provider=lineage.registry_entry.provider,
            provider_account=_local_provider_account(
                lineage.provider_caps, lineage.registry_entry.provider
            ),
            model_registry_sha256=lineage.registry_sha256,
            policy_sha256=lineage.provider_caps_sha256,
            parser_reuse_by_document=(
                parser_reuse_evidence_from_authenticated_artifacts(
                    parser_reuse.artifacts_by_key
                )
            ),
            provider_reuse_by_candidate=provider_reuse_evidence_from_verified_rows(
                lineage.verified_provider_attempt_rows
            ),
            selection_path=selection_path,
            selection_run_card_path=selection_run_card_path,
            download_manifest_path=download_manifest_path,
            disclosure_clearance_path=disclosure_clearance_path,
            materialization_run_card_path=materialization_run_card_path,
            document_root=lineage.document_root,
            parse_requests_path=parse_requests_path,
            parser_manifest_path=parser_manifest_path,
            parser_run_card_path=parser_run_card_path,
            markdown_root=lineage.markdown_root,
            target_eligibility_audit_path=eligibility_audit_path,
            target_eligibility_audit_run_card_path=eligibility_run_card_path,
            provider_journal_path=lineage.provider_journal_path,
        )
        parser_reuse_paths_list: list[Path] = []
        for name in (
            "prior_run_card",
            "prior_requests",
            "prior_parser_manifest",
        ):
            raw_source = parser_reuse.source.get(name)
            if not isinstance(raw_source, Mapping):
                continue
            source_path = cast(Mapping[str, object], raw_source).get("path")
            if isinstance(source_path, str):
                parser_reuse_paths_list.append(Path(source_path))
        parser_reuse_paths = tuple(parser_reuse_paths_list)
        journal_sidecar_paths = tuple(
            Path(f"{journal_path}{suffix}")
            for suffix in _PROVIDER_JOURNAL_SIDECAR_SUFFIXES
        )
        current_input_paths = (
            *lineage.input_paths,
            *lineage.file_snapshots,
            lineage.document_root,
            lineage.markdown_root,
            parser_run_card_path,
            *parser_reuse_paths,
            *terminal_snapshots,
            journal_path,
            *journal_sidecar_paths,
        )
        require_isolated_successor_outputs(
            proposal.successor_output_root,
            authenticated_inputs=current_input_paths,
            input_label="authenticated current input",
            root_alias=proposal.successor_output_root_alias,
        )
        proposed_input_paths = (
            *proposed_materialization.authenticated_paths,
            *(Path(path) for path in proposed_materialization.artifact_bytes),
            *proposed_materialization.paths,
            proposal.document_root,
        )
        require_isolated_successor_outputs(
            proposal.successor_output_root,
            authenticated_inputs=proposed_input_paths,
            input_label="authenticated proposed input",
            root_alias=proposal.successor_output_root_alias,
        )
        report = plan_successor_rerun_impact(
            current=current,
            proposed=proposal,
        )
        _validate_successor_rerun_commands(report.record)
        # Close every current/proposed TOCTOU interval immediately before output.
        _require_stage_a_lineage_unchanged(lineage)
        if (
            _authenticate_live_mistral_parse_reuse(
                prior_run_card_path=parser_run_card_path,
                prior_markdown_root=lineage.markdown_root,
            )
            != parser_reuse
        ):
            raise SuccessorRerunImpactError(
                "authenticated parser reuse changed during planning"
            )
        _require_snapshot_unchanged(
            terminal_snapshots, label="llm-unitize terminal replay"
        )
        if eligibility_snapshots:
            _require_snapshot_unchanged(
                eligibility_snapshots,
                label="authenticated v4 eligibility",
            )
        _require_materialized_downstream_lineage_unchanged(
            proposed_materialization, document_root=proposal.document_root
        )
        _require_snapshot_unchanged(
            {proposal.policy_path: proposed_policy_bytes},
            label="authenticated proposed provider policy",
        )
        if load_successor_proposal(proposal_path) != proposal_envelope:
            raise SuccessorRerunImpactError(
                "successor proposal changed during planning"
            )
        if _provider_journal_durable_bytes(journal_path) != journal_state:
            raise SuccessorRerunImpactError(
                "provider journal changed during successor planning"
            )
        if (
            locate_cycle_lineage(index_path=index_path, cycle_id=cycle_id)
            != lineage_status
        ):
            raise SuccessorRerunImpactError(
                "active lineage changed during successor planning"
            )
        require_isolated_successor_outputs(
            proposal.successor_output_root,
            authenticated_inputs=current_input_paths,
            input_label="authenticated current input",
            root_alias=proposal.successor_output_root_alias,
        )
        require_isolated_successor_outputs(
            proposal.successor_output_root,
            authenticated_inputs=proposed_input_paths,
            input_label="authenticated proposed input",
            root_alias=proposal.successor_output_root_alias,
        )
    except (
        CommandError,
        CycleLineageIndexError,
        CyclePreflightManifestError,
        ProviderJournalError,
        SuccessorRerunImpactError,
    ) as exc:
        report = failed_successor_rerun_impact(str(exc))
        exit_code = 1
    if cast(str, args.format) == "json":
        sys.stdout.write(report.json_text())
    else:
        sys.stdout.write(report.text())
    return exit_code


def _validate_successor_rerun_commands(record: Mapping[str, object]) -> None:
    """Prove every derived argv is a complete invocation of its named command."""

    raw_commands = record.get("next_commands")
    if not isinstance(raw_commands, Sequence) or isinstance(raw_commands, (str, bytes)):
        raise SuccessorRerunImpactError("derived next commands are malformed")
    forbidden = {"freeze", "dispatch", "publish", "finalize-corpus"}
    parser = build_parser()
    for raw_command in cast(Sequence[object], raw_commands):
        if not isinstance(raw_command, Mapping):
            raise SuccessorRerunImpactError("derived next command is malformed")
        command = cast(Mapping[str, object], raw_command)
        stage = command.get("stage")
        argv = command.get("argv")
        if (
            not isinstance(stage, str)
            or not isinstance(argv, list)
            or not all(isinstance(item, str) for item in cast(list[object], argv))
            or command.get("execution_authority") is not False
            or not isinstance(command.get("requires_separate_authorization"), bool)
        ):
            raise SuccessorRerunImpactError("derived next command is malformed")
        typed_argv = cast(list[str], argv)
        if (
            typed_argv[:4] != ["uv", "run", "legalforecast", "acquisition"]
            or len(typed_argv) < 5
            or typed_argv[4] != stage
            or stage in forbidden
            or any(token in forbidden for token in typed_argv)
            or (
                "--execute" in typed_argv
                and command.get("requires_separate_authorization") is not True
            )
        ):
            raise SuccessorRerunImpactError(
                "derived next command stage or authority differs"
            )
        stderr = io.StringIO()
        stdout = io.StringIO()
        try:
            with redirect_stdout(stdout), redirect_stderr(stderr):
                parsed = parser.parse_args(typed_argv[3:])
        except SystemExit as exc:
            detail = (stderr.getvalue() or stdout.getvalue()).strip()
            raise SuccessorRerunImpactError(
                "derived next command is not accepted by the acquisition CLI"
                + (f": {detail}" if detail else "")
            ) from exc
        if getattr(parsed, "handler", None) is None:
            raise SuccessorRerunImpactError(
                "derived next command has no acquisition handler"
            )


def _cmd_acquisition_register_cycle_stage_head(args: argparse.Namespace) -> int:
    """Verify and add one directly executed completion to the advisory index."""

    try:
        result = register_cycle_stage_head(
            index_path=_cycle_lineage_index_path(args),
            cycle_id=cast(str, args.cycle_id),
            command=cast(str, args.command),
            run_card_path=cast(Path, args.run_card),
            code_commit=cast(str, args.code_commit),
            supersedes_root_identity_sha256=cast(
                str | None, args.supersedes_root_identity_sha256
            ),
        )
    except CycleLineageIndexError as exc:
        raise CommandError(str(exc)) from exc
    if cast(bool, args.json) or not sys.stdout.isatty():
        print(json.dumps(result, sort_keys=True))
    else:
        print(
            f"registered {result['cycle_id']} stage {result['stage']} "
            f"root {result['root_identity_sha256']}"
        )
    return 0


def _validate_rendered_cycle_arguments(config: AcquisitionCycleConfig) -> None:
    parser = build_parser()
    for stage in config.stages:
        stderr = io.StringIO()
        stdout = io.StringIO()
        try:
            with redirect_stdout(stdout), redirect_stderr(stderr):
                parsed = parser.parse_args(
                    ["acquisition", stage.command, *stage.arguments]
                )
        except SystemExit as exc:
            detail = (stderr.getvalue() or stdout.getvalue()).strip()
            raise CycleManifestTemplateError(
                f"stage {stage.stage_id} arguments are invalid"
                + (f": {detail}" if detail else "")
            ) from exc
        if getattr(parsed, "handler", None) is None:
            raise CycleManifestTemplateError(
                f"stage {stage.stage_id} has no executable acquisition handler"
            )


def _cmd_acquisition_run_cycle(args: argparse.Namespace) -> int:
    """Inspect or advance a receipt-backed acquisition-only cycle."""

    allow_network = cast(bool, args.allow_network)
    allow_model_provider = cast(bool, args.allow_model_provider)
    allow_paid = cast(bool, args.allow_paid)
    adopt_next_completed = cast(bool, args.adopt_next_completed)
    if adopt_next_completed and (
        cast(bool, args.execute)
        or allow_network
        or cast(bool, args.allow_human)
        or allow_model_provider
        or allow_paid
    ):
        raise CommandError(
            "--adopt-next-completed cannot be combined with --execute or "
            "--allow-* flags"
        )
    if allow_model_provider and not allow_network:
        raise CommandError("--allow-model-provider requires --allow-network")
    if allow_paid and not allow_network:
        raise CommandError("--allow-paid requires --allow-network")

    def execute_existing_acquisition_stage(
        command: str,
        arguments: tuple[str, ...],
    ) -> int:
        # Keep the cycle status as the sole stdout record. Delegated output is
        # consistently routed to stderr for both interactive and piped callers.
        with redirect_stdout(sys.stderr):
            try:
                return main(("acquisition", command, *arguments))
            except SystemExit as exc:
                if exc.code is None:
                    return 0
                return exc.code if isinstance(exc.code, int) else 2

    try:
        status = run_acquisition_cycle(
            config_path=cast(Path, args.config),
            state_root=cast(Path, args.state_root),
            execute=cast(bool, args.execute),
            adopt_next_completed=adopt_next_completed,
            external_stage_verifier=_verify_external_completed_cycle_stage,
            permissions=BoundaryPermissions(
                network=allow_network,
                human=cast(bool, args.allow_human),
                model_provider=allow_model_provider,
                paid=allow_paid,
            ),
            executor=execute_existing_acquisition_stage,
        )
    except CycleOrchestratorError as exc:
        raise CommandError(str(exc)) from exc

    if cast(bool, args.json) or not sys.stdout.isatty():
        print(json.dumps(status, sort_keys=True))
    else:
        print(
            f"cycle {status['cycle_id']}: {status['status']} "
            f"({status['completed_stage_count']}/{status['stage_count']} stages)"
        )
        next_stage = status.get("next_stage")
        if isinstance(next_stage, Mapping):
            next_stage_record = cast(Mapping[str, object], next_stage)
            invocation = next_stage_record.get("invocation")
            if isinstance(invocation, Sequence) and not isinstance(
                invocation, (str, bytes)
            ):
                invocation_items = cast(Sequence[object], invocation)
                print("next: " + " ".join(str(item) for item in invocation_items))
            boundary = next_stage_record.get("boundary")
            if isinstance(boundary, str):
                print(f"boundary: {boundary}")
    return 0


def _cycle_stage_flag_values(stage: CycleStage, flag: str) -> tuple[str, ...]:
    values: list[str] = []
    index = 0
    joined_prefix = f"{flag}="
    while index < len(stage.arguments):
        argument = stage.arguments[index]
        if argument.startswith(joined_prefix):
            values.append(argument[len(joined_prefix) :])
            index += 1
        elif argument == flag:
            if index + 1 >= len(stage.arguments):
                raise CycleOrchestratorError(
                    f"stage {stage.stage_id} {flag} has no value"
                )
            values.append(stage.arguments[index + 1])
            index += 2
        else:
            index += 1
    return tuple(values)


def _cycle_stage_path(
    stage: CycleStage,
    flag: str,
    *,
    default_name: str | None = None,
) -> Path:
    values = _cycle_stage_flag_values(stage, flag)
    if len(values) > 1:
        raise CycleOrchestratorError(f"stage {stage.stage_id} repeats {flag}")
    if values:
        return Path(values[0])
    if default_name is None:
        raise CycleOrchestratorError(f"stage {stage.stage_id} omits {flag}")
    return _cycle_stage_path(stage, "--output-root") / default_name


def _cycle_stage_optional_path(stage: CycleStage, flag: str) -> Path | None:
    values = _cycle_stage_flag_values(stage, flag)
    if len(values) > 1:
        raise CycleOrchestratorError(f"stage {stage.stage_id} repeats {flag}")
    return Path(values[0]) if values else None


def _cycle_stage_path_in_root(
    stage: CycleStage,
    flag: str,
    *,
    default_root_flag: str,
    default_name: str,
) -> Path:
    values = _cycle_stage_flag_values(stage, flag)
    if len(values) > 1:
        raise CycleOrchestratorError(f"stage {stage.stage_id} repeats {flag}")
    if values:
        return Path(values[0])
    return _cycle_stage_path(stage, default_root_flag) / default_name


def _verify_external_completed_cycle_stage(
    stage: CycleStage,
    run_card: Mapping[str, object],
) -> None:
    """Replay existing local producer verifiers before protected-stage adoption."""

    try:
        if stage.command == "parse-documents":
            manifest_path = _cycle_stage_path(
                stage,
                "--manifest-output",
                default_name="mistral-markdown-conversions.jsonl",
            )
            clearance_path = _cycle_stage_path(stage, "--disclosure-clearance")
            selection_path = _cycle_stage_path(stage, "--selection")
            requests_path = _cycle_stage_path(stage, "--requests")
            materialization_card_path = _cycle_stage_path(
                stage, "--materialization-run-card"
            )
            manifest_payload = _read_singly_linked_regular_input(
                manifest_path, label="external parser manifest"
            )
            selection_payload = _read_singly_linked_regular_input(
                selection_path, label="external parser selection"
            )
            requests_payload = _read_singly_linked_regular_input(
                requests_path, label="external parser requests"
            )
            clearance_payload = _read_singly_linked_regular_input(
                clearance_path, label="external parser clearance"
            )
            parser_card_payload = _read_singly_linked_regular_input(
                stage.run_card, label="external parser run card"
            )
            parser_records = _projection_jsonl_records(
                manifest_payload, source=manifest_path
            )
            materialization_card = _read_json_object(materialization_card_path)
            raw_materialization_outputs = materialization_card.get("output_paths")
            if not isinstance(raw_materialization_outputs, Sequence) or isinstance(
                raw_materialization_outputs, (str, bytes)
            ):
                raise CommandError("materialization run card lacks exact outputs")
            materialization_outputs = tuple(
                Path(str(path))
                for path in cast(Sequence[object], raw_materialization_outputs)
            )
            if len(materialization_outputs) != 6:
                raise CommandError("materialization run card output paths differ")
            materialization = _verify_materialized_downstream_lineage(
                run_card_path=materialization_card_path,
                manifest_path=materialization_outputs[0],
                clearance_path=clearance_path,
                document_root=materialization_outputs[5],
                selection_path=selection_path,
                controlled_private_root=_cycle_stage_optional_path(
                    stage, "--controlled-private-root"
                ),
                initialization_receipt_path=_cycle_stage_optional_path(
                    stage, "--purchase-ledger-initialization-receipt"
                ),
            )
            markdown_root = _cycle_stage_path(stage, "--output-root") / "markdown"
            _markdown_tree, markdown_bytes = _stage_a_markdown_tree_snapshot(
                parser_records,
                markdown_root=markdown_root,
            )
            _verify_stage_a_parse_lineage(
                selection_path=selection_path,
                manifest_path=materialization_outputs[0],
                clearance_path=clearance_path,
                document_root=materialization_outputs[5],
                materialization_paths=materialization.paths,
                requests_path=requests_path,
                parser_manifest_path=manifest_path,
                parser_records=parser_records,
                parser_run_card_path=stage.run_card,
                selection_bytes=selection_payload,
                requests_bytes=requests_payload,
                parser_manifest_bytes=manifest_payload,
                parser_run_card_bytes=parser_card_payload,
                markdown_root=markdown_root,
                download_records=materialization.manifest_records,
                clearance_bytes=clearance_payload,
                markdown_bytes=markdown_bytes,
            )
            return

        if stage.command == "review-disclosure-exceptions":
            plan_path = _cycle_stage_path(stage, "--routing-plan")
            worksheet_path = _cycle_stage_path(stage, "--exception-worksheet")
            plan_run_card_path = _cycle_stage_path(stage, "--plan-run-card")
            document_root = _cycle_stage_path(stage, "--document-root")
            authority_path = _cycle_stage_path_in_root(
                stage,
                "--authority-output",
                default_root_flag="--output-root",
                default_name="disclosure-model-review-authority.json",
            )
            private_path = _cycle_stage_path_in_root(
                stage,
                "--private-records-output",
                default_root_flag="--controlled-private-store-root",
                default_name="disclosure-model-review-private-records.json",
            )
            plan_bytes = _read_singly_linked_regular_input(
                plan_path, label="external disclosure routing plan"
            )
            worksheet_bytes = _read_singly_linked_regular_input(
                worksheet_path, label="external disclosure worksheet"
            )
            plan_run_card_bytes = _read_singly_linked_regular_input(
                plan_run_card_path, label="external disclosure plan run card"
            )
            authority_bytes = _read_singly_linked_regular_input(
                authority_path, label="external disclosure review authority"
            )
            private_bytes = _read_singly_linked_regular_input(
                private_path, label="external disclosure private records"
            )
            plan = _projection_json_object(plan_bytes, source=plan_path)
            worksheet = _projection_json_object(worksheet_bytes, source=worksheet_path)
            documents = validate_exception_review_worksheet_v3(
                worksheet,
                routing_plan=plan,
                routing_plan_bytes=plan_bytes,
                worksheet_bytes=worksheet_bytes,
            )
            raw_plan_documents = plan.get("documents")
            if not isinstance(raw_plan_documents, list) or not all(
                isinstance(document, Mapping)
                for document in cast(list[object], raw_plan_documents)
            ):
                raise CommandError("external v3 routing plan documents are malformed")
            document_snapshot = _capture_provenance_document_snapshot(
                cast(list[Mapping[str, Any]], raw_plan_documents),
                document_root=document_root,
            )
            document_map = _model_review_document_map(worksheet, document_snapshot)
            if set(document_map) != {
                (
                    cast(str, document["candidate_id"]),
                    cast(str, document["source_document_id"]),
                )
                for document in documents
            }:
                raise CommandError(
                    "external disclosure worksheet byte coverage changed"
                )
            document_tree = _provenance_document_tree_from_snapshot(document_snapshot)
            _verify_model_review_plan_run_card(
                run_card_bytes=plan_run_card_bytes,
                run_card_path=plan_run_card_path,
                plan_path=plan_path,
                plan_bytes=plan_bytes,
                worksheet_path=worksheet_path,
                worksheet_bytes=worksheet_bytes,
                document_root=document_root,
                document_tree=document_tree,
            )
            raw_sources = run_card.get("source_commitments")
            if not isinstance(raw_sources, Mapping):
                raise CommandError("external disclosure sources are missing")
            raw_document_commitment = cast(Mapping[str, object], raw_sources).get(
                "document_root"
            )
            if not isinstance(raw_document_commitment, Mapping):
                raise CommandError("external disclosure document tree changed")
            document_commitment = cast(Mapping[str, object], raw_document_commitment)
            if dict(document_commitment) != {
                "path": str(document_root.resolve()),
                "tree_sha256": _canonical_json_sha256(document_tree),
                "document_count": len(document_tree),
            }:
                raise CommandError("external disclosure document tree changed")
            _validate_named_path_commitment(
                cast(Mapping[str, object], raw_sources),
                name="plan_run_card",
                expected_path=plan_run_card_path,
                expected_sha256=_bytes_sha256(plan_run_card_bytes),
            )
            capability = replay_authenticated_disclosure_model_review(
                routing_plan=plan,
                routing_plan_bytes=plan_bytes,
                worksheet=worksheet,
                worksheet_bytes=worksheet_bytes,
                document_bytes_by_key=document_map,
                provider_journal_path=_cycle_stage_path(stage, "--provider-journal"),
                provider_spend_authority_path=_cycle_stage_path(
                    stage, "--provider-spend-authority"
                ),
                source_root=_cycle_stage_path(stage, "--frozen-authority-root"),
            )
            _require_provenance_document_snapshot_unchanged(
                document_snapshot, document_root=document_root
            )
            replayed_authority = public_disclosure_model_review_record(capability)
            replayed_private = private_disclosure_model_review_records(capability)
            if (
                canonical_json_bytes(replayed_authority) != authority_bytes
                or canonical_json_bytes(list(replayed_private)) != private_bytes
                or run_card.get("model_review_authority") != replayed_authority
                or run_card.get("record_count")
                != replayed_authority.get("decision_count")
            ):
                raise CommandError("external disclosure authority replay differs")
            return

        unitization_card_path = (
            stage.run_card
            if stage.command == "llm-unitize"
            else _cycle_stage_path(stage, "--llm-unitization-run-card")
        )
        raw_units_path = (
            _cycle_stage_path(
                stage,
                "--prediction-units-output",
                default_name="prediction-units.jsonl",
            )
            if stage.command == "llm-unitize"
            else _cycle_stage_path(stage, "--prediction-units")
        )
        unitization_queue_path = (
            _cycle_stage_path(
                stage,
                "--unitization-review-queue-output",
                default_name="unitization-review-queue.jsonl",
            )
            if stage.command == "llm-unitize"
            else (
                _cycle_stage_path(stage, "--unitization-review-queue")
                if stage.command == "llm-review-stage-a"
                else None
            )
        )
        unitization_audit_path = (
            _cycle_stage_path(
                stage,
                "--audit-output",
                default_name="llm-unitization-audit.jsonl",
            )
            if stage.command == "llm-unitize"
            else None
        )
        lineage = _verify_stage_a_unitization_run_card(
            unitization_card_path,
            expected_prediction_units_path=raw_units_path,
            expected_review_queue_path=unitization_queue_path,
            expected_audit_path=unitization_audit_path,
            controlled_private_root=_cycle_stage_optional_path(
                stage, "--controlled-private-root"
            ),
            initialization_receipt_path=_cycle_stage_optional_path(
                stage, "--purchase-ledger-initialization-receipt"
            ),
        )
        if stage.command == "llm-unitize":
            return
        if stage.command == "llm-review-stage-a":
            model_keys = _cycle_stage_flag_values(stage, "--model-key")
            if len(model_keys) != 1:
                raise CycleOrchestratorError(
                    f"stage {stage.stage_id} must provide exactly one --model-key"
                )
            _verify_stage_a_review_run_card(
                stage.run_card,
                lineage=lineage,
                llm_unitization_run_card_path=unitization_card_path,
                expected_review_queue_path=_cycle_stage_path(
                    stage,
                    "--review-queue-output",
                    default_name="unitization-review-queue-reviewed.jsonl",
                ),
                expected_structural_flags_path=_cycle_stage_path(
                    stage,
                    "--structural-flags-output",
                    default_name="stage-a-structural-flags.jsonl",
                ),
                expected_audit_path=_cycle_stage_path(
                    stage,
                    "--audit-output",
                    default_name="stage-a-structural-review-audit.jsonl",
                ),
                expected_registry_path=_cycle_stage_path(stage, "--model-registry"),
                expected_model_key=model_keys[0],
            )
            return
        selection_path = _cycle_stage_path(stage, "--selection")
        parser_manifest_path = _cycle_stage_path(stage, "--parser-manifest")
        decision_texts_path = _cycle_stage_path(stage, "--decision-texts")
        decision_texts_manifest_path = _cycle_stage_path(
            stage, "--decision-texts-manifest"
        )
        decision_texts_run_card_path = _cycle_stage_path(
            stage, "--decision-texts-run-card"
        )
        llm_review_stage_a_run_card_path = _cycle_stage_path(
            stage, "--llm-review-stage-a-run-card"
        )
        unitization_review_run_card_path = _cycle_stage_path(
            stage, "--unitization-review-run-card"
        )
        model_registry_path = _cycle_stage_path(stage, "--model-registry")
        evaluated_model_registry_path = _cycle_stage_path(
            stage, "--evaluated-model-registry"
        )
        provider_cycle_caps_path = _cycle_stage_path(stage, "--provider-cycle-caps")
        labels_path = _cycle_stage_path(
            stage, "--labels-output", default_name="labels.jsonl"
        )
        audit_path = _cycle_stage_path(
            stage, "--audit-output", default_name="llm-label-audit.jsonl"
        )
        lawyer_review_queue_path = _cycle_stage_path(
            stage,
            "--lawyer-review-queue-output",
            default_name="lawyer-review-queue.jsonl",
        )
        if stage.run_card_stage == "llm-label-provider-shard":
            if run_card.get("stage") != stage.run_card_stage:
                raise CommandError("llm-label provider-shard stage changed")
            output_commitments = run_card.get("output_commitments")
            expected_output_commitments = {
                "labels": _stage_a_file_commitment(labels_path),
                "audit": _stage_a_file_commitment(audit_path),
                "lawyer_review_queue": _stage_a_file_commitment(
                    lawyer_review_queue_path
                ),
            }
            if (
                not isinstance(output_commitments, Mapping)
                or dict(cast(Mapping[str, object], output_commitments))
                != expected_output_commitments
            ):
                raise CommandError("llm-label provider-shard output commitment changed")
            expected_providers = _cycle_stage_flag_values(stage, "--execution-provider")
            if len(expected_providers) != 1:
                raise CycleOrchestratorError(
                    f"stage {stage.stage_id} must provide exactly one "
                    "--execution-provider"
                )
            observed_provider = _verify_llm_label_provider_shard_run_card(
                stage.run_card,
                audit_path=audit_path,
                lineage=lineage,
                selection_path=selection_path,
                parser_manifest_path=parser_manifest_path,
                decision_texts_path=decision_texts_path,
                decision_texts_manifest_path=decision_texts_manifest_path,
                decision_texts_run_card_path=decision_texts_run_card_path,
                finalized_prediction_units_path=raw_units_path,
                llm_unitization_run_card_path=unitization_card_path,
                llm_review_stage_a_run_card_path=llm_review_stage_a_run_card_path,
                unitization_review_run_card_path=unitization_review_run_card_path,
                model_registry_path=model_registry_path,
                evaluated_model_registry_path=evaluated_model_registry_path,
                provider_cycle_caps_path=provider_cycle_caps_path,
            )
            if observed_provider != expected_providers[0]:
                raise CommandError("llm-label provider-shard provider changed")
            return
        _verify_llm_label_run_card(
            stage.run_card,
            lineage=lineage,
            selection_path=selection_path,
            parser_manifest_path=parser_manifest_path,
            decision_texts_path=decision_texts_path,
            decision_texts_manifest_path=decision_texts_manifest_path,
            decision_texts_run_card_path=decision_texts_run_card_path,
            finalized_prediction_units_path=raw_units_path,
            llm_unitization_run_card_path=unitization_card_path,
            llm_review_stage_a_run_card_path=llm_review_stage_a_run_card_path,
            unitization_review_run_card_path=unitization_review_run_card_path,
            model_registry_path=model_registry_path,
            evaluated_model_registry_path=evaluated_model_registry_path,
            provider_cycle_caps_path=provider_cycle_caps_path,
            labels_path=labels_path,
            audit_path=audit_path,
        )
    except (CommandError, OSError, UnicodeError, ValueError) as exc:
        raise CycleOrchestratorError(
            f"stage {stage.stage_id} semantic replay failed: {exc}"
        ) from exc


def _cmd_acquisition_init_cycle(args: argparse.Namespace) -> int:
    """Freeze or verify acquisition identity before any provider-backed stage."""

    output_root = _acquisition_output_root(args)
    store_path = _acquisition_path(
        args,
        "cycle_store",
        output_root / "cycle-acquisition.sqlite3",
    )
    identity_path = _acquisition_path(
        args,
        "identity_output",
        output_root / "cycle-identity.json",
    )
    anchor = _iso_date_argument(
        cast(str, args.eligibility_anchor),
        "--eligibility-anchor",
    )
    policy = _cycle_acquisition_policy(anchor=anchor)
    dry_run = _acquisition_dry_run(args)
    output_paths = (store_path, identity_path)
    zero_activity: JsonRecord = {
        "provider_activity_requested": False,
        "provider_activity_executed": False,
        "firecrawl_metered_activity_requested": False,
        "firecrawl_metered_activity_executed": False,
        "pacer_paid_activity_requested": False,
        "pacer_paid_activity_executed": False,
    }
    if dry_run:
        summary: JsonRecord = {
            "schema_version": "legalforecast.cycle_acquisition_identity.v1",
            "dry_run": True,
            "eligibility_anchor": anchor.isoformat(),
            "cycle_store": str(store_path),
            "policy": policy,
            "initialized_or_verified": False,
            **zero_activity,
        }
        _write_json(identity_path, summary)
        _write_acquisition_completion(
            args,
            stage="init-cycle",
            input_paths=(),
            output_paths=output_paths,
            record_count=0,
            dry_run=True,
            paid_activity_requested=False,
            paid_activity_executed=False,
            extra=summary,
        )
        return 0

    try:
        if store_path.exists() and not cast(bool, args.resume):
            raise CycleAcquisitionStoreError(
                "cycle store already exists and --no-resume forbids verification"
            )
        with CycleAcquisitionStore(store_path) as store:
            cycle_hash = store.ensure_cycle(policy)
            _validate_frozen_screening_policy(policy=store.cycle_policy, anchor=anchor)
    except (
        ConfigMismatchError,
        CycleAcquisitionStoreError,
        OSError,
        ValueError,
    ) as exc:
        _write_acquisition_failure(
            args,
            stage="init-cycle",
            input_paths=(),
            output_paths=output_paths,
            reason=str(exc),
            paid_activity_requested=False,
            paid_activity_executed=False,
            extra=zero_activity,
        )
        raise CommandError(str(exc)) from exc

    identity: JsonRecord = {
        "schema_version": "legalforecast.cycle_acquisition_identity.v1",
        "dry_run": False,
        "eligibility_anchor": anchor.isoformat(),
        "cycle_hash": cycle_hash,
        "cycle_store": str(store_path),
        "policy": policy,
        "initialized_or_verified": True,
        **zero_activity,
    }
    _write_json(identity_path, identity)
    _write_acquisition_completion(
        args,
        stage="init-cycle",
        input_paths=(),
        output_paths=output_paths,
        record_count=1,
        dry_run=False,
        paid_activity_requested=False,
        paid_activity_executed=False,
        extra=identity,
    )
    return 0


def _cmd_acquisition_materialize_provider_caps(args: argparse.Namespace) -> int:
    """Publish authority-enabled caps from exact provider-free smoke evidence."""

    try:
        materialize_provider_cycle_caps_successor_files(
            legacy_caps_path=cast(Path, args.legacy_provider_cycle_caps),
            expected_legacy_caps_sha256=cast(str, args.expected_legacy_caps_sha256),
            authority_smoke_path=cast(Path, args.authority_smoke_receipt),
            expected_authority_smoke_sha256=cast(
                str, args.expected_authority_smoke_sha256
            ),
            expected_smoke_release_sha=cast(str, args.expected_smoke_release_sha),
            policy_path=cast(Path, args.provider_caps_successor_policy),
            expected_policy_sha256=cast(str, args.expected_provider_policy_sha256),
            output_root=cast(Path, args.output_root),
        )
    except ProviderCycleCapsMaterializationError as exc:
        raise CommandError(str(exc)) from exc
    return 0


def _cmd_acquisition_discover_firecrawl_recap(args: argparse.Namespace) -> int:
    output_root = _acquisition_output_root(args)
    decision_first = cast(str, args.recap_search_plan) == "decision-first-r"
    stage_name = (
        "discover-firecrawl-recap-decisions"
        if decision_first
        else "discover-firecrawl-recap"
    )
    default_terms = (
        DECISION_FIRST_RECAP_SEARCH_TERMS if decision_first else FROZEN_MTD_SEARCH_TERMS
    )
    query_plan_version = (
        DECISION_FIRST_RECAP_QUERY_PLAN_VERSION
        if decision_first
        else COURTLISTENER_QUERY_PLAN_VERSION
    )
    query_expression: Callable[[str], str] = (
        decision_recap_query_expression
        if decision_first
        else courtlistener_query_expression
    )
    search_type = "r"
    run_purpose = (
        "anchored-recap-decision-discovery"
        if decision_first
        else "anchored-recap-entry-discovery"
    )
    batch_id = cast(str, args.batch_id)
    run_id = cast(str, args.run_id)
    recovery_of_run_id = cast(str | None, args.recover_terminal_errors_from_run)
    additional_recovery_source_run_ids = tuple(
        cast(Sequence[str], args.recovery_source_run_ids)
    )
    if additional_recovery_source_run_ids and recovery_of_run_id is None:
        raise CommandError(
            "--reuse-verified-pages-from-run requires "
            "--recover-terminal-errors-from-run"
        )
    recovery_source_run_ids = (
        ()
        if recovery_of_run_id is None
        else (recovery_of_run_id, *additional_recovery_source_run_ids)
    )
    if len(set(recovery_source_run_ids)) != len(recovery_source_run_ids):
        raise CommandError("terminal recovery source run IDs must be unique")
    if run_id in recovery_source_run_ids:
        raise CommandError("recovery --run-id must differ from every source run")
    default_output_identity = batch_id
    if recovery_of_run_id is not None:
        try:
            default_output_identity = safe_path_component(run_id, field_name="run_id")
        except ValueError as exc:
            raise CommandError(str(exc)) from exc
        if cast(Path | None, args.run_card_output) is None:
            args.run_card_output = (
                output_root
                / "run-cards"
                / f"{stage_name}-{default_output_identity}.json"
            )
        if cast(Path | None, args.log_output) is None:
            args.log_output = (
                output_root / "logs" / f"{stage_name}-{default_output_identity}.jsonl"
            )
    store_path = _acquisition_path(
        args, "cycle_store", output_root / "cycle-acquisition.sqlite3"
    )
    entries_path = _acquisition_path(
        args,
        "entries_output",
        output_root / "checkpoints" / f"{default_output_identity}-recap-entries.jsonl",
    )
    dockets_path = _acquisition_path(
        args,
        "dockets_output",
        output_root / "checkpoints" / f"{default_output_identity}-recap-dockets.jsonl",
    )
    summary_path = _acquisition_path(
        args,
        "summary_output",
        output_root / "checkpoints" / f"{default_output_identity}-recap-summary.json",
    )
    configured_raw_search_html_dir = cast(Path | None, args.raw_search_html_dir)
    if configured_raw_search_html_dir is None:
        try:
            raw_run_id = safe_path_component(run_id, field_name="run_id")
        except ValueError as exc:
            raise CommandError(str(exc)) from exc
        raw_search_html_dir = output_root / "raw-recap-search-html" / raw_run_id
    else:
        raw_search_html_dir = configured_raw_search_html_dir
    anchor = _iso_date_argument(
        cast(str, args.eligibility_anchor),
        "--eligibility-anchor",
    )
    window_start = _iso_date_argument(
        cast(str, args.search_window_start),
        "--search-window-start",
    )
    window_end = _iso_date_argument(
        cast(str, args.search_window_end),
        "--search-window-end",
    )
    if window_start < anchor:
        raise CommandError("--search-window-start cannot precede --eligibility-anchor")
    if window_end < window_start:
        raise CommandError("--search-window-end cannot precede --search-window-start")
    terms = tuple(cast(Sequence[str] | None, args.query_terms) or ())
    if not terms:
        terms = default_terms
    max_pages_per_term = cast(int, args.max_pages_per_term)
    max_attempts = cast(int, args.max_attempts_per_page)
    breaker_threshold = cast(int, args.provider_breaker_threshold)
    credit_cap = cast(int, args.credit_cap)
    if max_pages_per_term <= 0:
        raise CommandError("--max-pages-per-term must be positive")
    if max_attempts <= 0:
        raise CommandError("--max-attempts-per-page must be positive")
    if breaker_threshold <= 0:
        raise CommandError("--provider-breaker-threshold must be positive")
    if credit_cap <= 0 or credit_cap > 45_000:
        raise CommandError("--credit-cap must be between 1 and 45000")
    worst_case_authorized_credits: int | None = None
    frozen_combined_worst_case_credits: int | None = None
    if decision_first:
        if max_pages_per_term > DECISION_FIRST_RECAP_MAX_PAGES_PER_TERM:
            raise CommandError(
                "decision-first Firecrawl plan exceeds the frozen 12000-credit "
                "decision-rescue bound: --max-pages-per-term cannot exceed 100"
            )
        try:
            worst_case_authorized_credits = decision_rescue_worst_case_credits(
                terms=terms,
                max_pages_per_term=max_pages_per_term,
                max_attempts_per_page=max_attempts,
            )
        except ValueError as exc:
            raise CommandError(str(exc)) from exc
        if worst_case_authorized_credits > DECISION_FIRST_RECAP_MAX_AUTHORIZED_CREDITS:
            raise CommandError(
                "decision-first Firecrawl plan exceeds the frozen 12000-credit "
                "decision-rescue bound"
            )
        frozen_combined_worst_case_credits = (
            worst_case_authorized_credits
            + FROZEN_EXISTING_FIRECRAWL_COMMITMENT_CREDITS
            + FROZEN_OTHER_RESCUE_COMMITMENT_CREDITS
        )
        if (
            frozen_combined_worst_case_credits
            >= FROZEN_COMBINED_FIRECRAWL_CREDIT_CEILING
        ):
            raise CommandError(
                "combined frozen Firecrawl plans must remain below 45000 credits"
            )
    proxy = cast(str, args.proxy)
    force_browser = cast(bool, args.force_browser)
    if recovery_of_run_id is not None and (proxy != "enhanced" or not force_browser):
        raise CommandError(
            "terminal target recovery requires --proxy enhanced --force-browser"
        )
    fixture_path = cast(Path | None, args.firecrawl_fixture)
    live = cast(bool, args.live_firecrawl)
    if live == (fixture_path is not None):
        raise CommandError(
            "choose exactly one of --firecrawl-fixture or --live-firecrawl"
        )
    dry_run = _acquisition_dry_run(args)
    input_paths = () if fixture_path is None else (fixture_path,)
    output_paths = (
        store_path,
        entries_path,
        dockets_path,
        summary_path,
        raw_search_html_dir,
    )
    policy = _cycle_acquisition_policy(anchor=anchor)
    batch_config: JsonRecord = {
        "provider": (
            "courtlistener-recap-decision-web-via-firecrawl"
            if decision_first
            else "courtlistener-recap-web-via-firecrawl"
        ),
        "eligibility_anchor": anchor.isoformat(),
        "search_window_start": window_start.isoformat(),
        "search_window_end": window_end.isoformat(),
        "query_terms": list(terms),
        "courtlistener_query_plan_version": query_plan_version,
        "courtlistener_query_expressions": [query_expression(term) for term in terms],
        "query_term_order_is_frozen": True,
        "max_pages_per_term": max_pages_per_term,
    }
    if decision_first:
        assert worst_case_authorized_credits is not None
        assert frozen_combined_worst_case_credits is not None
        batch_config.update(
            {
                "worst_case_authorized_credits": worst_case_authorized_credits,
                "courtlistener_search_type": search_type,
                "frozen_existing_firecrawl_commitment_credits": (
                    FROZEN_EXISTING_FIRECRAWL_COMMITMENT_CREDITS
                ),
                "frozen_other_rescue_commitment_credits": (
                    FROZEN_OTHER_RESCUE_COMMITMENT_CREDITS
                ),
                "frozen_combined_worst_case_credits": (
                    frozen_combined_worst_case_credits
                ),
                "next_stage": "acquisition enrich-recap-case-dev",
                "downstream_stages": [
                    "acquisition enrich-recap-case-dev",
                    "acquisition acquire-ranked-firecrawl-dockets",
                    "acquisition screen-firecrawl-dockets",
                ],
            }
        )
    run_config: JsonRecord = {
        "purpose": run_purpose,
        "proxy": proxy,
        "force_browser": force_browser,
        "max_attempts_per_page": max_attempts,
        "provider_breaker_threshold": breaker_threshold,
        "query_terms": list(terms),
        "courtlistener_query_plan_version": query_plan_version,
        "courtlistener_query_expressions": [query_expression(term) for term in terms],
        "raw_artifact_root": str(raw_search_html_dir.resolve()),
    }
    if decision_first:
        assert worst_case_authorized_credits is not None
        assert frozen_combined_worst_case_credits is not None
        run_config.update(
            {
                "worst_case_authorized_credits": worst_case_authorized_credits,
                "courtlistener_search_type": search_type,
                "frozen_existing_firecrawl_commitment_credits": (
                    FROZEN_EXISTING_FIRECRAWL_COMMITMENT_CREDITS
                ),
                "frozen_other_rescue_commitment_credits": (
                    FROZEN_OTHER_RESCUE_COMMITMENT_CREDITS
                ),
                "frozen_combined_worst_case_credits": (
                    frozen_combined_worst_case_credits
                ),
                "next_stage": "acquisition enrich-recap-case-dev",
                "downstream_stages": [
                    "acquisition enrich-recap-case-dev",
                    "acquisition acquire-ranked-firecrawl-dockets",
                    "acquisition screen-firecrawl-dockets",
                ],
            }
        )
    if recovery_of_run_id is not None:
        run_config["recovery_of_run_id"] = recovery_of_run_id
        run_config["recovery_source_run_ids"] = list(recovery_source_run_ids)
        run_config["recovery_generation"] = 1
    if dry_run:
        summary: JsonRecord = {
            "schema_version": "legalforecast.firecrawl_recap_discovery_summary.v1",
            "dry_run": True,
            "batch_id": batch_id,
            "run_id": run_id,
            "query_terms": list(terms),
            "potential_candidate_count": 0,
            "clean_corpus_count": 0,
            "credit_cap": credit_cap,
            "reserved_credits_per_attempt": 5,
            **batch_config,
            **run_config,
        }
        _write_jsonl(entries_path, [])
        _write_jsonl(dockets_path, [])
        _write_json(summary_path, summary)
        _write_acquisition_completion(
            args,
            stage=stage_name,
            input_paths=input_paths,
            output_paths=output_paths,
            record_count=0,
            dry_run=True,
            paid_activity_requested=False,
            paid_activity_executed=False,
            extra=summary,
        )
        return 0

    recovery_parent_credit_summary: Mapping[str, object] = {}
    try:
        fixture_transport = (
            None if live else _firecrawl_fixture_transport(cast(Path, fixture_path))
        )

        def make_source(
            *, source_proxy: str, source_force_browser: bool
        ) -> FirecrawlCourtListenerHTMLSource:
            if live:
                return FirecrawlCourtListenerHTMLSource(
                    FirecrawlConfig.from_env(
                        proxy=cast(Any, source_proxy),
                        force_browser=source_force_browser,
                    )
                )
            return FirecrawlCourtListenerHTMLSource(
                FirecrawlConfig(
                    api_key="offline-fixture",
                    proxy=cast(Any, source_proxy),
                    force_browser=source_force_browser,
                ),
                transport=fixture_transport,
            )

        source = make_source(source_proxy=proxy, source_force_browser=force_browser)
        with CycleAcquisitionStore(store_path) as store:
            cycle_hash = store.ensure_cycle(policy)
            batch_digest = store.ensure_batch(batch_id, batch_config)
            store.ensure_terms(batch_id, terms)
            inherited_pages: tuple[FirecrawlPageRecord, ...] = ()
            recovery_terminal_target_count = 0
            terminal_source_urls: frozenset[str] = frozenset()
            continuation_scheduler: BudgetedFirecrawlScheduler | None = None
            if recovery_of_run_id is not None:
                frozen_parent_run_fields = (
                    "query_terms",
                    "courtlistener_query_plan_version",
                    "courtlistener_query_expressions",
                )
                if decision_first:
                    frozen_parent_run_fields = (
                        *frozen_parent_run_fields,
                        "courtlistener_search_type",
                    )
                pages_by_url: dict[str, FirecrawlPageRecord] = {}
                all_terminal_source_urls: set[str] = set()
                primary_config: Mapping[str, object] | None = None
                primary_terminal_count = 0
                source_summaries: dict[str, Mapping[str, object]] = {}
                for source_run_id in recovery_source_run_ids:
                    source_summary = store.firecrawl_run_summary(source_run_id)
                    source_summaries[source_run_id] = source_summary
                    source_config = store.firecrawl_run_config(source_run_id)
                    if source_summary.get("batch_id") != batch_id:
                        raise ConfigMismatchError(
                            "recovery source does not belong to the frozen batch"
                        )
                    if "recovery_of_run_id" in source_config:
                        raise ConfigMismatchError(
                            "cannot recover a fallback run; recovery is limited to one "
                            "bounded generation"
                        )
                    if source_config.get("purpose") != run_purpose:
                        raise ConfigMismatchError(
                            "recovery source is not the same anchored RECAP "
                            "discovery plan"
                        )
                    if any(
                        source_config.get(field) != run_config.get(field)
                        for field in frozen_parent_run_fields
                    ):
                        raise ConfigMismatchError(
                            "recovery source query plan does not match the frozen batch"
                        )
                    terminal_targets = tuple(
                        target
                        for target in store.firecrawl_targets(source_run_id)
                        if target.status == "terminal_error"
                    )
                    if source_run_id == recovery_of_run_id:
                        primary_config = source_config
                        primary_terminal_count = len(terminal_targets)
                    if any(
                        target.target_kind != "search" for target in terminal_targets
                    ):
                        raise ConfigMismatchError(
                            "recovery source contains a non-search terminal target"
                        )
                    source_attempts = store.firecrawl_attempts(source_run_id)
                    terminal_target_ids = {
                        target.target_id for target in terminal_targets
                    }
                    evidenced_target_ids = {
                        attempt.target_id
                        for attempt in source_attempts
                        if attempt.target_id in terminal_target_ids
                        and attempt.status == "target_error"
                        and attempt.failure_transient is False
                    }
                    if evidenced_target_ids != terminal_target_ids:
                        raise ConfigMismatchError(
                            "recovery source terminal targets lack nontransient "
                            "target-error evidence"
                        )
                    all_terminal_source_urls.update(
                        target.source_url for target in terminal_targets
                    )
                    for page in load_successful_firecrawl_pages(
                        store=store, run_id=source_run_id
                    ):
                        prior = pages_by_url.get(page.source_url)
                        if (
                            prior is not None
                            and prior.artifact_sha256 != page.artifact_sha256
                        ):
                            raise FirecrawlArtifactError(
                                "conflicting verified bytes for recovery search URL "
                                f"{page.source_url}"
                            )
                        pages_by_url.setdefault(page.source_url, page)
                if primary_terminal_count == 0:
                    raise ConfigMismatchError(
                        "recovery parent has no terminal target errors"
                    )
                recovery_parent_credit_summary = {"source_runs": source_summaries}
                inherited_pages = tuple(pages_by_url.values())
                terminal_source_urls = frozenset(
                    all_terminal_source_urls - pages_by_url.keys()
                )
                recovery_terminal_target_count = len(terminal_source_urls)
                assert primary_config is not None
                parent_config = primary_config
                parent_proxy = parent_config.get("proxy")
                parent_force_browser = parent_config.get("force_browser")
                parent_max_attempts = parent_config.get("max_attempts_per_page")
                parent_breaker_threshold = parent_config.get(
                    "provider_breaker_threshold"
                )
                parent_artifact_root = parent_config.get("raw_artifact_root")
                if (
                    parent_proxy not in {"basic", "auto", "enhanced"}
                    or not isinstance(parent_force_browser, bool)
                    or not isinstance(parent_max_attempts, int)
                    or isinstance(parent_max_attempts, bool)
                    or not isinstance(parent_breaker_threshold, int)
                    or isinstance(parent_breaker_threshold, bool)
                    or not isinstance(parent_artifact_root, str)
                ):
                    raise ConfigMismatchError(
                        "recovery parent has an invalid immutable scheduler config"
                    )
                continuation_scheduler = BudgetedFirecrawlScheduler(
                    store=store,
                    source=make_source(
                        source_proxy=cast(str, parent_proxy),
                        source_force_browser=parent_force_browser,
                    ),
                    run_id=recovery_of_run_id,
                    artifact_dir=parent_artifact_root,
                    max_attempts=parent_max_attempts,
                    provider_5xx_circuit_threshold=parent_breaker_threshold,
                    artifact_validator=(
                        _validate_decision_recap_artifact if decision_first else None
                    ),
                    semantic_failure_quarantine_dir=(
                        raw_search_html_dir / "semantic-failure-quarantine"
                        if decision_first
                        else None
                    ),
                )
            run_digest = store.ensure_firecrawl_run(
                run_id,
                batch_id=batch_id,
                config=run_config,
                credit_cap=credit_cap,
                reserved_credits_per_attempt=5,
            )
            scheduler = BudgetedFirecrawlScheduler(
                store=store,
                source=source,
                run_id=run_id,
                artifact_dir=raw_search_html_dir,
                max_attempts=max_attempts,
                provider_5xx_circuit_threshold=breaker_threshold,
                artifact_validator=(
                    _validate_decision_recap_artifact if decision_first else None
                ),
                semantic_failure_quarantine_dir=(
                    raw_search_html_dir / "semantic-failure-quarantine"
                    if decision_first
                    else None
                ),
            )
            transport = _BudgetedRecapSearchTransport(
                scheduler,
                inherited_pages=inherited_pages,
                continuation_scheduler=continuation_scheduler,
                fallback_source_urls=terminal_source_urls,
                parse_search_url=(
                    parse_decision_recap_search_url
                    if decision_first
                    else parse_recap_search_url
                ),
            )
            if decision_first:
                discovery = discover_decision_recap_entries(
                    transport=transport,
                    entry_date_filed_after=window_start,
                    entry_date_filed_before=window_end,
                    terms=terms,
                    max_pages_per_term=max_pages_per_term,
                )
            else:
                discovery = discover_recap_mtd_entries(
                    transport=transport,
                    entry_date_filed_after=window_start,
                    entry_date_filed_before=window_end,
                    terms=terms,
                    max_pages_per_term=max_pages_per_term,
                )
            if transport.unrecovered_fallback_urls:
                raise RecapSearchError(
                    "recovery did not traverse every frozen terminal target"
                )
            if recovery_of_run_id is not None:
                fallback_targets = store.firecrawl_targets(run_id)
                if (
                    frozenset(target.source_url for target in fallback_targets)
                    != terminal_source_urls
                ):
                    raise RecapSearchError(
                        "fallback run acquired a target outside the frozen terminal set"
                    )
            _commit_recap_discovery_pages(
                store=store,
                batch_id=batch_id,
                pages=transport.pages,
                parse_search_html=(
                    parse_decision_recap_search_html
                    if decision_first
                    else parse_recap_search_html
                ),
            )
            credit_summary = dict(store.firecrawl_run_summary(run_id))
    except (
        ConfigMismatchError,
        CycleAcquisitionStoreError,
        FirecrawlArtifactError,
        FirecrawlCircuitOpenError,
        FirecrawlError,
        RecapSearchError,
        ValueError,
    ) as exc:
        failure_credit_summary = _firecrawl_credit_summary_if_available(
            store_path=store_path,
            run_id=run_id,
        )
        firecrawl_run_status = failure_credit_summary.pop("status", None)
        metered_executed = _firecrawl_metered_activity_executed(
            live=live,
            summary=failure_credit_summary,
        )
        _write_acquisition_failure(
            args,
            stage=stage_name,
            input_paths=input_paths,
            output_paths=output_paths,
            reason=str(exc),
            paid_activity_requested=live,
            paid_activity_executed=metered_executed,
            extra={
                "firecrawl_metered_activity_requested": live,
                "firecrawl_metered_activity_executed": metered_executed,
                "pacer_paid_activity_requested": False,
                "pacer_paid_activity_executed": False,
                "recovery_of_run_id": recovery_of_run_id,
                "recovery_parent_credit_summary": dict(recovery_parent_credit_summary),
                **(
                    {"firecrawl_run_status": firecrawl_run_status}
                    if isinstance(firecrawl_run_status, str)
                    else {}
                ),
                **failure_credit_summary,
            },
        )
        raise CommandError(str(exc)) from exc

    entry_records = [
        _recap_discovered_entry_record(entry) for entry in discovery.entries
    ]
    docket_records = [
        {
            "candidate_id": f"courtlistener-docket-{docket.docket_id}",
            "docket_id": docket.docket_id,
            "docket_url": docket.docket_url,
            "entry_keys": list(docket.entry_keys),
            "matched_terms": list(docket.matched_terms),
            "eligibility_status": "potential_unverified",
        }
        for docket in discovery.dockets
    ]
    _write_jsonl(entries_path, entry_records)
    _write_jsonl(dockets_path, docket_records)
    summary = {
        "schema_version": "legalforecast.firecrawl_recap_discovery_summary.v1",
        "dry_run": False,
        "batch_id": batch_id,
        "run_id": run_id,
        "cycle_hash": cycle_hash,
        "batch_digest": batch_digest,
        "run_digest": run_digest,
        "recovery_of_run_id": recovery_of_run_id,
        "recovery_terminal_target_count": recovery_terminal_target_count,
        "recovery_parent_credit_summary": dict(recovery_parent_credit_summary),
        "proxy": proxy,
        "force_browser": force_browser,
        "query_terms": list(discovery.terms),
        "pages_fetched": discovery.pages_fetched,
        "raw_hit_count": discovery.raw_hit_count,
        "duplicate_entry_count": discovery.duplicate_entry_count,
        "entry_count": len(entry_records),
        "potential_candidate_count": len(docket_records),
        "clean_corpus_count": 0,
        "complete": discovery.complete,
        "saturated": discovery.complete,
        "candidate_count_semantics": (
            "potential dockets only; full eligibility, documents, leakage, parsing, "
            "unitization, and labeling remain required"
        ),
        "firecrawl_metered_activity_requested": live,
        "firecrawl_metered_activity_executed": (
            _firecrawl_metered_activity_executed(
                live=live,
                summary=credit_summary,
            )
        ),
        "pacer_paid_activity_requested": False,
        "pacer_paid_activity_executed": False,
        **credit_summary,
        **batch_config,
    }
    _write_json(summary_path, summary)
    run_card_summary: JsonRecord = dict(summary)
    run_card_summary.pop("status", None)
    _write_acquisition_completion(
        args,
        stage=stage_name,
        input_paths=input_paths,
        output_paths=output_paths,
        record_count=len(docket_records),
        dry_run=False,
        paid_activity_requested=live,
        paid_activity_executed=_firecrawl_metered_activity_executed(
            live=live,
            summary=credit_summary,
        ),
        extra=run_card_summary,
    )
    return 0


def _commit_recap_discovery_pages(
    *,
    store: CycleAcquisitionStore,
    batch_id: str,
    pages: Sequence[FirecrawlPageRecord],
    parse_search_html: Callable[..., RecapSearchPage] = parse_recap_search_html,
) -> None:
    """Project verified raw RECAP pages into durable discovery progress."""

    for record in pages:
        page = parse_search_html(record.raw_html, source_url=record.source_url)
        hits = tuple(
            DiscoveryHit(
                provider_hit_id=_recap_provider_hit_id(hit),
                candidate_id=f"courtlistener-docket-{hit.docket_id}",
                payload=_recap_search_hit_record(hit),
            )
            for hit in page.hits
        )
        store.commit_search_page(
            batch_id,
            page.target.term,
            None if page.target.page == 1 else str(page.target.page),
            hits,
            next_cursor=(
                str(page.target.page + 1) if page.next_url is not None else None
            ),
            terminal_status=(
                None if page.next_url is not None else TermTerminalStatus.EXHAUSTED
            ),
        )


def _recap_provider_hit_id(hit: RecapSearchHit) -> str:
    # This identifies one provider occurrence, not the underlying docket entry.
    # CourtListener can repeat an entry at identical ordinal positions on later
    # pages; semantic entry reconciliation remains the checkpoint deduper's job.
    identity = "\0".join(
        (
            hit.entry_key,
            hit.document_url,
            hit.provenance.query_term,
            str(hit.provenance.page),
            str(hit.provenance.result_ordinal),
            str(hit.provenance.entry_ordinal),
        )
    )
    return hashlib.sha256(identity.encode("utf-8")).hexdigest()


def _recap_search_hit_record(hit: RecapSearchHit) -> JsonRecord:
    return {
        "entry_key": hit.entry_key,
        "docket_id": hit.docket_id,
        "docket_entry_id": hit.docket_entry_id,
        "document_number": hit.document_number,
        "attachment_number": hit.attachment_number,
        "docket_url": hit.docket_url,
        "document_url": hit.document_url,
        "entry_date_filed": hit.entry_date_filed.isoformat(),
        "case_name": hit.case_name,
        "description": hit.description,
        "is_available": hit.is_available,
        "provenance": {
            "query_term": hit.provenance.query_term,
            "search_url": hit.provenance.search_url,
            "page": hit.provenance.page,
            "result_ordinal": hit.provenance.result_ordinal,
            "entry_ordinal": hit.provenance.entry_ordinal,
            "raw_html_sha256": hit.provenance.raw_html_sha256,
        },
    }


def _recap_discovered_entry_record(entry: RecapDiscoveredEntry) -> JsonRecord:
    return {
        "entry_key": entry.entry_key,
        "candidate_id": f"courtlistener-docket-{entry.docket_id}",
        "docket_id": entry.docket_id,
        "docket_entry_id": entry.docket_entry_id,
        "document_number": entry.document_number,
        "attachment_number": entry.attachment_number,
        "docket_url": entry.docket_url,
        "document_url": entry.document_url,
        "entry_date_filed": entry.entry_date_filed.isoformat(),
        "case_name": entry.case_name,
        "description": entry.description,
        "is_available": entry.is_available,
        "matched_terms": list(entry.matched_terms),
        "provenance": [
            {
                "query_term": provenance.query_term,
                "search_url": provenance.search_url,
                "page": provenance.page,
                "result_ordinal": provenance.result_ordinal,
                "entry_ordinal": provenance.entry_ordinal,
                "raw_html_sha256": provenance.raw_html_sha256,
            }
            for provenance in entry.provenances
        ],
        "eligibility_status": "potential_unverified",
    }


def _case_dev_progress_is_retryable(progress: Mapping[str, object]) -> bool:
    if progress.get("outcome") == "transient":
        return True
    payload = progress.get("payload")
    failure_payload = (
        cast(Mapping[str, object], payload) if isinstance(payload, Mapping) else None
    )
    return (
        progress.get("outcome") == "failure"
        and failure_payload is not None
        and failure_payload.get("reason")
        in {
            "case_dev_duplicate_entry_conflict",
            "case_dev_duplicate_entry_semantic_conflict",
        }
    )


_CASE_DEV_MAX_TRANSIENT_DOCKET_ATTEMPTS = 3


def _bound_case_dev_transient_progress(
    progress: JsonRecord,
    *,
    transient_attempts_by_index: Counter[int],
) -> JsonRecord:
    if progress.get("outcome") != "transient":
        return progress
    input_index = cast(int, progress["input_index"])
    transient_attempts_by_index[input_index] += 1
    attempt_count = transient_attempts_by_index[input_index]
    if attempt_count < _CASE_DEV_MAX_TRANSIENT_DOCKET_ATTEMPTS:
        return progress
    return {
        "input_index": input_index,
        "outcome": "failure",
        "payload": {
            "input_index": input_index,
            "reason": "case_dev_server_error_retries_exhausted",
            "detail": (
                "Case.dev docket enrichment exhausted "
                f"{attempt_count} resumable attempts"
            ),
        },
    }


def _case_dev_failure_output_record(
    progress: Mapping[str, object],
    *,
    source_record: Mapping[str, object],
) -> JsonRecord:
    """Bind an exhausted-provider terminal failure to its source identity."""

    payload = progress.get("payload")
    if not isinstance(payload, Mapping):  # pragma: no cover - progress is prevalidated
        raise CommandError("Case.dev terminal failure payload is invalid")
    failure = dict(cast(Mapping[str, Any], payload))
    if failure.get("reason") != "case_dev_server_error_retries_exhausted":
        return failure
    input_index = progress.get("input_index")
    candidate_id = source_record.get("candidate_id")
    docket_id = source_record.get("docket_id")
    if (
        type(input_index) is not int
        or not isinstance(candidate_id, str)
        or not candidate_id
        or not isinstance(docket_id, str)
        or not docket_id
    ):
        raise CommandError(
            "Case.dev exhausted-provider failure lacks a canonical source identity"
        )
    failure.update(
        {
            "input_index": input_index,
            "candidate_id": candidate_id,
            "docket_id": docket_id,
            "stage": "case_dev_enrichment",
        }
    )
    return failure


def _enrich_case_dev_progress_record(
    *,
    input_index: int,
    record: Mapping[str, Any],
    fixture_path: Path | None,
    live: bool,
    page_size: int,
    max_pages: int,
    eligibility_anchor: date | None,
    allow_source_bound: bool = False,
    client: CaseDevClient | None = None,
    rate_limiter: CaseDevRateLimiter | None = None,
) -> tuple[JsonRecord, int]:
    active_client = client or _case_dev_client(
        command="enrich-recap-case-dev",
        fixture_path=fixture_path,
        live=live,
        rate_limiter=rate_limiter,
    )
    request_count_before = active_client.request_count
    try:
        one = enrich_recap_discovery_batch(
            client=active_client,
            records=(record,),
            page_size=page_size,
            max_pages=max_pages,
            allow_source_bound=allow_source_bound,
            eligibility_anchor=eligibility_anchor,
        )
    except CaseDevServerError as exc:
        return (
            {
                "input_index": input_index,
                "outcome": "transient",
                "payload": {
                    "reason": "case_dev_server_error",
                    "detail": str(exc),
                },
            },
            active_client.request_count - request_count_before,
        )
    if one.successes:
        enrichment = one.successes[0]
        source_lineage = record.get("source_lineage")
        if isinstance(source_lineage, Mapping):
            typed_source_lineage = cast(Mapping[str, object], source_lineage)
            raw_lead_commitment = typed_source_lineage.get("lead_commitment")
            if not isinstance(raw_lead_commitment, Mapping):
                raise ValueError(
                    "source-bound Case.dev enrichment lacks lead commitment"
                )
            lead_commitment = cast(Mapping[str, object], raw_lead_commitment)
            screening_metadata = dict(enrichment.screening_metadata)
            screening_metadata.update(
                {
                    "case_id": enrichment.courtlistener_docket_id,
                    "court_id": lead_commitment.get("court_id"),
                    "docket_number": lead_commitment.get("docket_number"),
                    "case_name": lead_commitment.get("case_name"),
                }
            )
            enrichment = replace(
                enrichment,
                screening_metadata=screening_metadata,
            )
        payload = enrichment.to_record()
        if isinstance(source_lineage, Mapping):
            payload["source_lineage"] = dict(cast(Mapping[str, Any], source_lineage))
        progress: JsonRecord = {
            "input_index": input_index,
            "outcome": "success",
            "payload": payload,
        }
    else:
        failure = one.failures[0].to_record()
        failure["input_index"] = input_index
        progress = {
            "input_index": input_index,
            "outcome": "failure",
            "payload": failure,
        }
    return progress, active_client.request_count - request_count_before


def _cmd_acquisition_enrich_recap_case_dev(args: argparse.Namespace) -> int:
    output_root = _acquisition_output_root(args)
    dockets_arg = cast(Path | None, args.dockets)
    source_store_path = cast(Path | None, args.source_store)
    source_batch_id = cast(str | None, args.source_batch_id)
    source_mode_requested = source_store_path is not None or source_batch_id is not None
    if (dockets_arg is not None) == source_mode_requested:
        raise CommandError(
            "choose exactly one input mode: --dockets or "
            "--source-store with --source-batch-id"
        )
    if source_mode_requested and (source_store_path is None or source_batch_id is None):
        raise CommandError(
            "--source-store and --source-batch-id must be supplied together"
        )
    projection_path = _acquisition_path(
        args,
        "source_projection_output",
        output_root / "checkpoints" / "case-dev-recap-source-projection.jsonl",
    )
    source_commitments: JsonRecord = {}
    projection_bytes: bytes | None = None
    eligibility_anchor: date | None = None
    if source_store_path is not None and source_batch_id is not None:
        try:
            source = read_saturated_direct_search_leads(
                source_store_path,
                source_batch_id=source_batch_id,
            )
        except RecapApiBatchDriverError as exc:
            raise CommandError(str(exc)) from exc
        try:
            records = list(project_case_dev_opinion_source(source))
        except RecapApiBatchDriverError as exc:
            raise CommandError(str(exc)) from exc
        projection_bytes = _jsonl_bytes(records)
        projection_sha256 = hashlib.sha256(projection_bytes).hexdigest()
        eligibility_anchor = CYCLE_1_ELIGIBILITY_ANCHOR
        source_commitments = {
            **case_dev_source_authority_commitments(source),
            "source_projection_sha256": projection_sha256,
            "eligibility_anchor": eligibility_anchor.isoformat(),
        }
        dockets_path = projection_path
        source_input_paths = (source_store_path,)
        source_output_paths = (projection_path,)
        allow_source_bound = True
    else:
        if dockets_arg is None:  # pragma: no cover - guarded above
            raise CommandError("--dockets is required")
        dockets_path = dockets_arg
        records = _read_records(dockets_path)
        if any(
            record.get("schema_version") == CASE_DEV_SOURCE_DOCKET_SCHEMA
            for record in records
        ):
            raise CommandError(
                "source-bound exact-ID schema is accepted only from a verified "
                "--source-store/--source-batch-id projection"
            )
        source_input_paths = (dockets_path,)
        source_output_paths = ()
        allow_source_bound = False
    fixture_path = cast(Path | None, args.case_dev_fixture)
    live = cast(bool, args.live_case_dev)
    page_size = cast(int, args.page_size)
    max_pages = cast(int, args.max_pages_per_docket)
    workers = cast(int, args.workers)
    if page_size <= 0 or page_size > 100:
        raise CommandError("--page-size must be between 1 and 100")
    if max_pages <= 0:
        raise CommandError("--max-pages-per-docket must be positive")
    if workers <= 0 or workers > 5:
        raise CommandError("--workers must be between 1 and 5")
    if live == (fixture_path is not None):
        raise CommandError(
            "choose exactly one of --case-dev-fixture or --live-case-dev"
        )
    if fixture_path is not None and workers != 1:
        raise CommandError("--workers must be 1 with --case-dev-fixture")
    ranked_path = _acquisition_path(
        args,
        "ranked_output",
        output_root / "checkpoints" / "case-dev-recap-ranked.jsonl",
    )
    failures_path = _acquisition_path(
        args,
        "failures_output",
        output_root / "checkpoints" / "case-dev-recap-failures.jsonl",
    )
    summary_path = _acquisition_path(
        args,
        "summary_output",
        output_root / "checkpoints" / "case-dev-recap-summary.json",
    )
    progress_path = output_root / "checkpoints" / "case-dev-recap-progress.jsonl"
    progress_config_path = (
        output_root / "checkpoints" / "case-dev-recap-progress-config.json"
    )
    input_paths = (
        source_input_paths
        if fixture_path is None
        else (*source_input_paths, fixture_path)
    )
    output_paths = (
        *source_output_paths,
        ranked_path,
        failures_path,
        summary_path,
        progress_path,
        progress_config_path,
    )
    dry_run = _acquisition_dry_run(args)
    resume = cast(bool, args.resume)
    run_card_path = _acquisition_path(
        args,
        "run_card_output",
        output_root / "run-cards" / "enrich-recap-case-dev.json",
    )
    log_path = _acquisition_path(
        args,
        "log_output",
        output_root / "logs" / "enrich-recap-case-dev.jsonl",
    )
    _validate_ranked_handoff_paths(
        protected_paths=input_paths,
        writable_paths=(
            *output_paths,
            run_card_path,
            log_path,
        ),
        sqlite_paths=(source_store_path,) if source_store_path is not None else (),
        context="Case.dev enrichment",
    )
    dockets_sha256 = (
        hashlib.sha256(projection_bytes).hexdigest()
        if projection_bytes is not None
        else hashlib.sha256(dockets_path.read_bytes()).hexdigest()
    )
    progress_config: JsonRecord = {
        "schema_version": "legalforecast.case_dev_recap_progress.v1",
        "ranking_policy_version": CASE_DEV_RANKING_POLICY_VERSION,
        "dockets_sha256": "sha256:" + dockets_sha256,
        "input_record_count": len(records),
        "page_size": page_size,
        "max_pages_per_docket": max_pages,
        "free_lookup_only": True,
        **source_commitments,
    }
    if projection_bytes is not None and projection_path.exists():
        if projection_path.read_bytes() != projection_bytes:
            raise CommandError(
                "existing Case.dev source projection does not match the verified source"
            )
    if not dry_run:
        if progress_config_path.exists():
            if not resume:
                raise CommandError(
                    "Case.dev enrichment progress exists; use --resume or remove it"
                )
            if _read_json_object(progress_config_path) != progress_config:
                raise CommandError(
                    "Case.dev enrichment progress does not match the current "
                    "input/config"
                )
        elif progress_path.exists():
            raise CommandError("Case.dev enrichment progress is missing its config")
    if projection_bytes is not None and not projection_path.exists():
        projection_path.parent.mkdir(parents=True, exist_ok=True)
        projection_path.write_bytes(projection_bytes)
    if dry_run:
        summary: JsonRecord = {
            "schema_version": "legalforecast.case_dev_recap_batch_summary.v1",
            "ranking_policy_version": CASE_DEV_RANKING_POLICY_VERSION,
            "dry_run": True,
            "input_record_count": len(records),
            "page_size": page_size,
            "max_pages_per_docket": max_pages,
            "free_lookup_only": True,
            "pacer_fee_acknowledgment_allowed": False,
            **source_commitments,
        }
        _write_jsonl(ranked_path, [])
        _write_jsonl(failures_path, [])
        summary.update(
            {
                "ranked_output_sha256": hashlib.sha256(
                    ranked_path.read_bytes()
                ).hexdigest(),
                "failures_output_sha256": hashlib.sha256(
                    failures_path.read_bytes()
                ).hexdigest(),
            }
        )
        _write_json(summary_path, summary)
        _write_acquisition_completion(
            args,
            stage="enrich-recap-case-dev",
            input_paths=input_paths,
            output_paths=output_paths,
            record_count=0,
            dry_run=True,
            paid_activity_requested=False,
            paid_activity_executed=False,
            extra=summary,
        )
        return 0

    if not progress_config_path.exists():
        _write_json(progress_config_path, progress_config)

    progress_records = _read_records(progress_path) if progress_path.exists() else []
    progress_by_index: dict[int, JsonRecord] = {}
    transient_attempts_by_index: Counter[int] = Counter()
    for progress in progress_records:
        input_index = progress.get("input_index")
        if (
            not isinstance(input_index, int)
            or isinstance(input_index, bool)
            or input_index < 0
            or input_index >= len(records)
            or progress.get("outcome") not in {"success", "failure", "transient"}
            or not isinstance(progress.get("payload"), Mapping)
        ):
            raise CommandError("Case.dev enrichment progress is invalid or duplicated")
        prior = progress_by_index.get(input_index)
        if prior is not None and not _case_dev_progress_is_retryable(prior):
            raise CommandError("Case.dev enrichment progress repeats a terminal index")
        if progress["outcome"] == "transient":
            transient_attempts_by_index[input_index] += 1
        progress_by_index[input_index] = progress

    for input_index, progress in tuple(progress_by_index.items()):
        attempt_count = transient_attempts_by_index[input_index]
        if (
            progress["outcome"] == "transient"
            and attempt_count >= _CASE_DEV_MAX_TRANSIENT_DOCKET_ATTEMPTS
        ):
            exhausted: JsonRecord = {
                "input_index": input_index,
                "outcome": "failure",
                "payload": {
                    "input_index": input_index,
                    "reason": "case_dev_server_error_retries_exhausted",
                    "detail": (
                        "Case.dev docket enrichment exhausted "
                        f"{attempt_count} resumable attempts"
                    ),
                },
            }
            _append_jsonl(progress_path, (exhausted,))
            progress_by_index[input_index] = exhausted

    try:
        pending = [
            (input_index, record)
            for input_index, record in enumerate(records)
            if input_index not in progress_by_index
            or _case_dev_progress_is_retryable(progress_by_index[input_index])
        ]
        pending.sort(
            key=lambda item: case_dev_enrichment_schedule_key(
                input_index=item[0],
                record=item[1],
            )
        )
        request_count = 0
        if workers == 1:
            serial_client = _case_dev_client(
                command="enrich-recap-case-dev",
                fixture_path=fixture_path,
                live=live,
            )
            completed = (
                _enrich_case_dev_progress_record(
                    input_index=input_index,
                    record=record,
                    fixture_path=fixture_path,
                    live=live,
                    page_size=page_size,
                    max_pages=max_pages,
                    eligibility_anchor=eligibility_anchor,
                    allow_source_bound=allow_source_bound,
                    client=serial_client,
                )
                for input_index, record in pending
            )
            for progress, one_request_count in completed:
                request_count += one_request_count
                progress = _bound_case_dev_transient_progress(
                    progress,
                    transient_attempts_by_index=transient_attempts_by_index,
                )
                _append_jsonl(progress_path, (progress,))
                progress_by_index[cast(int, progress["input_index"])] = progress
        else:
            live_config = CaseDevConfig.from_env(require_api_key=True)
            aggregate_rate_limiter = CaseDevRateLimiter(
                rate_limit_per_minute=live_config.rate_limit_per_minute
            )
            with ThreadPoolExecutor(max_workers=workers) as executor:
                pending_iter = iter(pending)

                def submit_one() -> Future[tuple[JsonRecord, int]] | None:
                    try:
                        input_index, record = next(pending_iter)
                    except StopIteration:
                        return None
                    return executor.submit(
                        _enrich_case_dev_progress_record,
                        input_index=input_index,
                        record=record,
                        fixture_path=fixture_path,
                        live=live,
                        page_size=page_size,
                        max_pages=max_pages,
                        eligibility_anchor=eligibility_anchor,
                        allow_source_bound=allow_source_bound,
                        rate_limiter=aggregate_rate_limiter,
                    )

                futures = {
                    future
                    for _ in range(workers)
                    if (future := submit_one()) is not None
                }
                fatal_error: CaseDevClientError | ValueError | None = None
                while futures:
                    first_completed = next(as_completed(futures))
                    completed = {first_completed}
                    completed.update(future for future in futures if future.done())
                    futures.difference_update(completed)
                    available_slots = 0
                    for future in completed:
                        try:
                            progress, one_request_count = future.result()
                        except (CaseDevClientError, ValueError) as exc:
                            if fatal_error is None:
                                fatal_error = exc
                            continue
                        request_count += one_request_count
                        progress = _bound_case_dev_transient_progress(
                            progress,
                            transient_attempts_by_index=transient_attempts_by_index,
                        )
                        _append_jsonl(progress_path, (progress,))
                        progress_by_index[cast(int, progress["input_index"])] = progress
                        available_slots += 1
                    if fatal_error is None:
                        for _ in range(available_slots):
                            if (replacement := submit_one()) is not None:
                                futures.add(replacement)
                if fatal_error is not None:
                    raise fatal_error
    except (CaseDevClientError, ValueError) as exc:
        _write_acquisition_failure(
            args,
            stage="enrich-recap-case-dev",
            input_paths=input_paths,
            output_paths=output_paths,
            reason=str(exc),
            paid_activity_requested=False,
            extra=source_commitments,
        )
        raise CommandError(str(exc)) from exc

    if len(progress_by_index) != len(records):
        raise CommandError("Case.dev enrichment progress did not reconcile to inputs")
    transient_count = sum(
        progress["outcome"] == "transient" for progress in progress_by_index.values()
    )
    if transient_count:
        reason = (
            f"Case.dev enrichment retained {transient_count} transient docket(s); "
            "rerun with --resume"
        )
        _write_acquisition_failure(
            args,
            stage="enrich-recap-case-dev",
            input_paths=input_paths,
            output_paths=output_paths,
            reason=reason,
            paid_activity_requested=False,
            extra={
                "transient_docket_count": transient_count,
                **source_commitments,
            },
        )
        raise CommandError(reason)
    ranked_records = sorted(
        (
            dict(cast(Mapping[str, Any], progress["payload"]))
            for progress in progress_by_index.values()
            if progress["outcome"] == "success"
        ),
        key=lambda record: tuple(cast(Sequence[object], record["ranking_key"])),
    )
    failure_records = [
        _case_dev_failure_output_record(
            progress_by_index[index],
            source_record=records[index],
        )
        for index in sorted(progress_by_index)
        if progress_by_index[index]["outcome"] == "failure"
    ]
    conversion_failure_count = sum(
        record.get("stage") == "discovery_record" for record in failure_records
    )
    enrichment_failure_count = len(failure_records) - conversion_failure_count
    summary = {
        "schema_version": "legalforecast.case_dev_recap_batch_summary.v1",
        "ranking_policy_version": CASE_DEV_RANKING_POLICY_VERSION,
        "dry_run": False,
        "case_dev_request_count": request_count,
        "page_size": page_size,
        "max_pages_per_docket": max_pages,
        "free_lookup_only": True,
        "pacer_fee_acknowledgment_allowed": False,
        "pacer_spend_usd": "0.00",
        "input_record_count": len(records),
        "converted_docket_count": len(ranked_records) + enrichment_failure_count,
        "enrichment_attempt_count": len(ranked_records) + enrichment_failure_count,
        "successful_docket_count": len(ranked_records),
        "failure_count": len(failure_records),
        "conversion_failure_count": conversion_failure_count,
        "enrichment_failure_count": enrichment_failure_count,
        "failure_reason_counts": dict(
            Counter(cast(str, record["reason"]) for record in failure_records)
        ),
        "structural_priority_tier_counts": dict(
            Counter(
                cast(str, record["structural_priority_reason"])
                for record in ranked_records
            )
        ),
        "decision_signal_priority_tier_counts": dict(
            Counter(
                cast(str, record["decision_signal_priority_reason"])
                for record in ranked_records
            )
        ),
        "eligibility_priority_tier_counts": dict(
            Counter(
                cast(str, record["eligibility_priority_reason"])
                for record in ranked_records
            )
        ),
        "actual_free_required_document_count": sum(
            cast(int, record["actual_free_required_document_count"])
            for record in ranked_records
        ),
        "missing_required_document_count": sum(
            cast(int, record["missing_required_document_count"])
            for record in ranked_records
        ),
        "resumed_terminal_record_count": len(progress_records),
        "reconciled": True,
        **source_commitments,
    }
    _write_jsonl(ranked_path, ranked_records)
    _write_jsonl(failures_path, failure_records)
    summary.update(
        {
            "ranked_output_sha256": hashlib.sha256(
                ranked_path.read_bytes()
            ).hexdigest(),
            "failures_output_sha256": hashlib.sha256(
                failures_path.read_bytes()
            ).hexdigest(),
        }
    )
    _write_json(summary_path, summary)
    _write_acquisition_completion(
        args,
        stage="enrich-recap-case-dev",
        input_paths=input_paths,
        output_paths=output_paths,
        record_count=len(ranked_records),
        dry_run=False,
        paid_activity_requested=False,
        paid_activity_executed=False,
        extra=summary,
    )
    return 0


def _cmd_acquisition_acquire_ranked_dockets(args: argparse.Namespace) -> int:
    output_root = _acquisition_output_root(args)
    store_path = cast(Path, args.cycle_store)
    ranked_path = cast(Path, args.ranked)
    fixture_path = cast(Path | None, args.firecrawl_fixture)
    live = cast(bool, args.live_firecrawl)
    workers = cast(int, args.workers)
    if live == (fixture_path is not None):
        raise CommandError(
            "choose exactly one of --firecrawl-fixture or --live-firecrawl"
        )
    if not _acquisition_dry_run(args) and fixture_path is not None and workers != 1:
        raise CommandError("--firecrawl-fixture execution requires --workers 1")
    credit_cap = cast(int, args.credit_cap)
    if credit_cap <= 0 or credit_cap > 45_000:
        raise CommandError("--credit-cap must be between 1 and 45000")
    anchor = _iso_date_argument(
        cast(str, args.decision_filed_on_or_after),
        "--decision-filed-on-or-after",
    )
    raw_dir = _acquisition_path(args, "raw_html_dir", output_root / "raw-docket-html")
    successes_path = _acquisition_path(
        args, "successes_output", output_root / "firecrawl-docket-successes.jsonl"
    )
    exclusions_path = _acquisition_path(
        args, "exclusions_output", output_root / "firecrawl-docket-exclusions.jsonl"
    )
    summary_path = _acquisition_path(
        args, "summary_output", output_root / "firecrawl-docket-summary.json"
    )
    records = _read_records(ranked_path)
    selection_run_card_path = cast(Path | None, args.ranked_selection_run_card)
    expected_selection_sha256 = cast(
        str | None,
        args.expected_ranked_selection_run_card_sha256,
    )
    if (selection_run_card_path is None) != (expected_selection_sha256 is None):
        raise CommandError(
            "--ranked-selection-run-card and "
            "--expected-ranked-selection-run-card-sha256 are required together"
        )
    if _acquisition_dry_run(args) and not store_path.exists():
        source_bound = False
        provisional_flags: JsonRecord = {}
    else:
        try:
            with CycleAcquisitionStore(store_path) as store:
                parent_config = store.batch_config(cast(str, args.parent_batch_id))
                source_bound = ranked_parent_requires_authenticated_handoff(
                    store,
                    cast(str, args.parent_batch_id),
                )
                provisional_flags = provisional_lineage_flags(parent_config)
                recovery_authority = parent_config.get("ranked_recovery_authority")
                typed_recovery_authority = (
                    cast(Mapping[str, object], recovery_authority)
                    if isinstance(recovery_authority, Mapping)
                    else None
                )
                if typed_recovery_authority is not None and (
                    typed_recovery_authority.get("partition") == "unresolved"
                    and typed_recovery_authority.get(
                        "authorized_fresh_recovery_credit_cap"
                    )
                    != credit_cap
                ):
                    raise BudgetedDocketAcquisitionError(
                        "--credit-cap must exactly equal the sealed fresh-recovery "
                        "authorization"
                    )
        except (
            BudgetedDocketAcquisitionError,
            CycleAcquisitionStoreError,
            KeyError,
        ) as exc:
            raise CommandError(str(exc)) from exc
    if source_bound and selection_run_card_path is None:
        raise CommandError(
            "source-bound parent batch requires an authenticated ranked-selection "
            "run card and external SHA-256"
        )
    if selection_run_card_path is not None and expected_selection_sha256 is not None:
        try:
            with CycleAcquisitionStore(store_path) as store:
                records = list(
                    verify_authenticated_ranked_firecrawl_handoff(
                        store=store,
                        parent_batch_id=cast(str, args.parent_batch_id),
                        ranked_path=ranked_path,
                        selection_run_card_path=selection_run_card_path,
                        expected_selection_run_card_sha256=(expected_selection_sha256),
                        max_candidates=cast(int, args.max_candidates),
                    )
                )
        except (BudgetedDocketAcquisitionError, CycleAcquisitionStoreError) as exc:
            raise CommandError(str(exc)) from exc
    base_input_paths = (
        (ranked_path,)
        if selection_run_card_path is None
        else (ranked_path, selection_run_card_path)
    )
    input_paths = (
        base_input_paths if fixture_path is None else (*base_input_paths, fixture_path)
    )
    output_paths = (successes_path, exclusions_path, summary_path)
    metadata_by_docket: dict[str, Mapping[str, object]] = {}
    for record in records:
        identity = record.get("identity")
        metadata = record.get("screening_metadata")
        if not isinstance(identity, Mapping) or not isinstance(metadata, Mapping):
            raise CommandError(
                "ranked records require identity and screening_metadata objects"
            )
        docket_id = cast(Mapping[str, object], identity).get("courtlistener_docket_id")
        if not isinstance(docket_id, str):
            raise CommandError("ranked record has invalid CourtListener docket ID")
        metadata_by_docket[docket_id] = cast(Mapping[str, object], metadata)
    proxy = cast(FirecrawlProxy, args.proxy)
    force_browser = cast(bool, args.force_browser)
    max_attempts = cast(int, args.max_attempts_per_page)
    breaker_threshold = cast(int, args.provider_breaker_threshold)
    if max_attempts <= 0:
        raise CommandError("--max-attempts-per-page must be positive")
    if breaker_threshold <= 0:
        raise CommandError("--provider-breaker-threshold must be positive")
    if _acquisition_dry_run(args):
        summary: JsonRecord = {
            "dry_run": True,
            "selected_batch_id": cast(str, args.selected_batch_id),
            "input_record_count": len(records),
            "max_candidates": cast(int, args.max_candidates),
            "workers": workers,
            "credit_cap": credit_cap,
            "firecrawl_proxy": proxy,
            "firecrawl_force_browser": force_browser,
            "reserved_credits": 0,
            "success_count": 0,
            "exclusion_count": 0,
            "pagination_complete_before_screening": False,
            **provisional_flags,
        }
        _write_jsonl(successes_path, [])
        _write_jsonl(exclusions_path, [])
        _write_json(summary_path, summary)
        _write_acquisition_completion(
            args,
            stage="acquire-ranked-firecrawl-dockets",
            input_paths=input_paths,
            output_paths=output_paths,
            record_count=0,
            dry_run=True,
            paid_activity_requested=live,
            paid_activity_executed=False,
            extra=summary,
        )
        return 0
    config = (
        FirecrawlConfig.from_env(proxy=proxy, force_browser=force_browser)
        if live
        else FirecrawlConfig(
            api_key="offline-fixture",
            proxy=proxy,
            force_browser=force_browser,
        )
    )
    source = FirecrawlCourtListenerHTMLSource(
        config,
        **(
            {"transport": _firecrawl_fixture_transport(cast(Path, fixture_path))}
            if not live
            else {}
        ),
    )
    with CycleAcquisitionStore(store_path) as store:
        materialize_selected_slice_batch(
            store=store,
            parent_batch_id=cast(str, args.parent_batch_id),
            selected_batch_id=cast(str, args.selected_batch_id),
            records=records,
            limit=cast(int, args.max_candidates),
        )
        run_config: JsonRecord = {
            "purpose": "ranked-complete-docket-acquisition",
            "decision_anchor": anchor.isoformat(),
            "max_pages_per_docket": cast(int, args.max_pages_per_docket),
            "raw_artifact_root": str(raw_dir.resolve()),
            "firecrawl_proxy": config.proxy,
            "firecrawl_force_browser": config.force_browser,
            "firecrawl_max_credits_per_scrape": config.max_credits_per_scrape,
            **provisional_flags,
        }
        run_id = cast(str, args.run_id)
        try:
            existing_run_config = store.firecrawl_run_config(run_id)
        except KeyError:
            run_config.update(
                {
                    "workers": workers,
                    "max_attempts_per_page": max_attempts,
                    "provider_breaker_threshold": breaker_threshold,
                    "target_http_pressure_policy_version": (
                        TARGET_HTTP_PRESSURE_POLICY_VERSION
                    ),
                }
            )
        else:
            if "workers" in existing_run_config:
                run_config["workers"] = workers
            elif workers != 1:
                raise CommandError(
                    "legacy Firecrawl runs require --workers 1; use a new --run-id "
                    "to freeze concurrent acquisition"
                )
            legacy_scheduler_values = {
                "max_attempts_per_page": (max_attempts, 3),
                "provider_breaker_threshold": (breaker_threshold, 5),
            }
            for field, (requested, legacy_value) in legacy_scheduler_values.items():
                if field in existing_run_config:
                    run_config[field] = requested
                elif requested != legacy_value:
                    raise CommandError(
                        f"legacy Firecrawl run requires --{field.replace('_', '-')} "
                        f"{legacy_value}"
                    )
            if "target_http_pressure_policy_version" in existing_run_config:
                run_config["target_http_pressure_policy_version"] = (
                    TARGET_HTTP_PRESSURE_POLICY_VERSION
                )
        store.ensure_firecrawl_run(
            run_id,
            batch_id=cast(str, args.selected_batch_id),
            config=run_config,
            credit_cap=credit_cap,
            reserved_credits_per_attempt=config.max_credits_per_scrape,
        )
        result = acquire_ranked_dockets(
            records=records,
            scheduler=BudgetedFirecrawlScheduler(
                store=store,
                source=source,
                run_id=run_id,
                artifact_dir=raw_dir / "pages",
                max_attempts=max_attempts,
                provider_5xx_circuit_threshold=breaker_threshold,
                max_workers=workers,
            ),
            limit=cast(int, args.max_candidates),
            max_pages_per_docket=cast(int, args.max_pages_per_docket),
            decision_anchor=anchor,
        )
    successes: list[JsonRecord] = []
    retrieved_at = datetime.now(UTC).isoformat()
    for bundle in result.bundles:
        raw_html = render_complete_docket_html(bundle)
        raw_bytes = raw_html.encode()
        raw_path = raw_dir / f"{bundle.docket_id}.html"
        _write_text(raw_path, raw_html)
        metadata = dict(metadata_by_docket[bundle.docket_id])
        candidate_id = f"courtlistener-docket-{bundle.docket_id}"
        metadata["case_id"] = candidate_id
        successes.append(
            {
                "case_id": candidate_id,
                "candidate_id": candidate_id,
                "source_url": bundle.base_url,
                "docket_id": bundle.docket_id,
                "raw_html_path": str(raw_path.resolve()),
                "case_metadata": metadata,
                "raw_html_sha256": "sha256:" + hashlib.sha256(raw_bytes).hexdigest(),
                "raw_html_bytes": len(raw_bytes),
                "retrieved_at": retrieved_at,
                "pagination_complete_for_anchor_window": True,
                "page_count": len(bundle.pages),
                **provisional_flags,
            }
        )
    exclusions = [
        {**failure.as_record(), **provisional_flags} for failure in result.failures
    ]
    _write_jsonl(successes_path, successes)
    _write_jsonl(exclusions_path, exclusions)
    summary = {
        **dict(result.credit_summary),
        "selected_batch_id": cast(str, args.selected_batch_id),
        "success_count": len(successes),
        "exclusion_count": len(exclusions),
        "failure_reason_counts": dict(
            Counter(failure.failure_reason for failure in result.failures)
        ),
        "pagination_complete_before_screening": True,
        "workers": workers,
        **provisional_flags,
    }
    _write_json(summary_path, summary)
    _write_acquisition_completion(
        args,
        stage="acquire-ranked-firecrawl-dockets",
        input_paths=input_paths,
        output_paths=output_paths,
        record_count=len(successes),
        dry_run=False,
        paid_activity_requested=live,
        paid_activity_executed=_firecrawl_metered_activity_executed(
            live=live, summary=summary
        ),
        extra=summary,
    )
    return 0


