def _cmd_acquisition_execute_target_raw_docket_recovery(
    args: argparse.Namespace,
) -> int:
    successor_path = cast(Path | None, getattr(args, "successor_plan", None))
    provider_contract_retry_path = cast(
        Path | None, getattr(args, "provider_contract_retry_plan", None)
    )
    successor: TargetRawDocketRecoverySuccessorPlan | None = None
    parent: TargetRawDocketRecoveryPlan | None = None
    preloaded_plan: TargetRawDocketRecoveryPlan | None = None
    provider_contract_retry: TargetRawDocketRecoveryProviderContractRetryPlan | None = (
        None
    )
    if successor_path is not None and provider_contract_retry_path is not None:
        raise CommandError("choose only one target raw recovery authority")
    if provider_contract_retry_path is not None:
        provider_contract_retry = (
            load_target_raw_docket_recovery_provider_contract_retry_plan(
                provider_contract_retry_path,
                cast(str, args.expected_provider_contract_retry_plan_sha256),
            )
        )
        _, preloaded_plan, successor = (
            resolve_target_raw_docket_recovery_provider_contract_retry(
                provider_contract_retry
            )
        )
        parent = replace(
            preloaded_plan,
            batch_id=successor.batch_id,
            run_id=successor.run_id,
        )
        args.cycle_store = Path(preloaded_plan.cycle_store_path)
        args.batch_id = preloaded_plan.batch_id
        args.run_id = preloaded_plan.run_id
        args.workers = preloaded_plan.workers
        args.selection = Path(preloaded_plan.selection_path)
        args.expected_selection_sha256 = preloaded_plan.selection_sha256
        args.source_snapshot = Path(preloaded_plan.source_snapshot_path)
        args.expected_source_snapshot_manifest_sha256 = (
            preloaded_plan.source_snapshot_manifest_sha256
        )
        args.expected_cycle_hash = preloaded_plan.cycle_hash
        args.source_snapshot_run_card = Path(
            preloaded_plan.source_snapshot_run_card_path
        )
        args.expected_source_snapshot_run_card_sha256 = (
            preloaded_plan.source_snapshot_run_card_sha256
        )
        args.source_raw_manifest = Path(preloaded_plan.source_raw_manifest_path)
        args.expected_source_raw_manifest_sha256 = (
            preloaded_plan.source_raw_manifest_sha256
        )
        args.credit_cap = preloaded_plan.credit_cap
        args.max_pages_per_docket = preloaded_plan.max_pages_per_docket
        args.max_attempts_per_page = preloaded_plan.max_attempts_per_page
        args.provider_breaker_threshold = preloaded_plan.provider_breaker_threshold
        args.proxy = preloaded_plan.proxy
        args.force_browser = preloaded_plan.force_browser
        plan_input = provider_contract_retry_path
        plan_sha256 = cast(str, args.expected_provider_contract_retry_plan_sha256)
        successor_inputs = (
            Path(provider_contract_retry.root_plan_path),
            Path(provider_contract_retry.root_failure_run_card_path),
            Path(provider_contract_retry.direct_successor_plan_path),
            Path(provider_contract_retry.direct_successor_failure_run_card_path),
            Path(provider_contract_retry.direct_successor_raw_html_dir),
            Path(provider_contract_retry.provider_contract_defect_authorization_path),
        )
    elif successor_path is not None:
        successor = load_target_raw_docket_recovery_successor_plan(
            successor_path, cast(str, args.expected_successor_plan_sha256)
        )
        parent, preloaded_plan = resolve_target_raw_docket_recovery_successor(successor)
        args.cycle_store = Path(preloaded_plan.cycle_store_path)
        args.batch_id = preloaded_plan.batch_id
        args.run_id = preloaded_plan.run_id
        args.workers = preloaded_plan.workers
        args.selection = Path(preloaded_plan.selection_path)
        args.expected_selection_sha256 = preloaded_plan.selection_sha256
        args.source_snapshot = Path(preloaded_plan.source_snapshot_path)
        args.expected_source_snapshot_manifest_sha256 = (
            preloaded_plan.source_snapshot_manifest_sha256
        )
        args.expected_cycle_hash = preloaded_plan.cycle_hash
        args.source_snapshot_run_card = Path(
            preloaded_plan.source_snapshot_run_card_path
        )
        args.expected_source_snapshot_run_card_sha256 = (
            preloaded_plan.source_snapshot_run_card_sha256
        )
        args.source_raw_manifest = Path(preloaded_plan.source_raw_manifest_path)
        args.expected_source_raw_manifest_sha256 = (
            preloaded_plan.source_raw_manifest_sha256
        )
        args.credit_cap = preloaded_plan.credit_cap
        args.max_pages_per_docket = preloaded_plan.max_pages_per_docket
        args.max_attempts_per_page = preloaded_plan.max_attempts_per_page
        args.provider_breaker_threshold = preloaded_plan.provider_breaker_threshold
        args.proxy = preloaded_plan.proxy
        args.force_browser = preloaded_plan.force_browser
        plan_input = successor_path
        plan_sha256 = cast(str, args.expected_successor_plan_sha256)
        successor_inputs: tuple[Path, ...] = (
            Path(successor.parent_plan_path),
            Path(successor.parent_failure_run_card_path),
            Path(successor.parent_raw_html_dir),
        )
    else:
        plan_input = cast(Path, args.plan)
        plan_sha256 = cast(str, args.expected_plan_sha256)
        successor_inputs = ()
    inputs = (
        plan_input,
        *successor_inputs,
        cast(Path, args.selection),
        cast(Path, args.source_snapshot) / "manifest.json",
        cast(Path, args.source_snapshot_run_card),
        cast(Path, args.source_raw_manifest),
    )
    protected_paths = (
        plan_input,
        *successor_inputs,
        cast(Path, args.selection),
        cast(Path, args.source_snapshot),
        cast(Path, args.source_snapshot_run_card),
        cast(Path, args.source_raw_manifest),
    )
    terminal_paths = (
        cast(Path, args.successes_output),
        cast(Path, args.exclusions_output),
        cast(Path, args.summary_output),
        cast(Path, args.receipt_output),
    )
    existing_terminal_count = sum(path.exists() for path in terminal_paths)
    if cast(bool, args.resume) and existing_terminal_count not in {0, 4}:
        raise CommandError(
            "resume requires either no terminal outputs or the complete terminal set"
        )
    completed_resume = cast(bool, args.resume) and existing_terminal_count == 4
    _preflight_target_raw_docket_recovery_paths(
        args,
        stage="execute-target-raw-docket-recovery",
        protected_paths=protected_paths,
        writable_paths=terminal_paths,
        raw_html_dir=cast(Path, args.raw_html_dir),
        allow_completed_raw_files=cast(bool, args.resume),
    )
    live = cast(bool, args.live_firecrawl)
    fixture = cast(Path | None, args.firecrawl_fixture)
    if _acquisition_dry_run(args):
        live = False
        fixture = None
    elif live == (fixture is not None):
        raise CommandError(
            "choose exactly one of --live-firecrawl or --firecrawl-fixture"
        )
    if fixture is not None and cast(int, args.workers) != 1:
        raise CommandError("Firecrawl fixture execution requires --workers 1")
    try:
        if preloaded_plan is None:
            reconstructed = _target_raw_docket_recovery_plan_from_args(args)
            plan = load_target_raw_docket_recovery_plan(plan_input, plan_sha256)
            if plan != reconstructed:
                raise TargetRawDocketRecoveryError(
                    "pinned plan differs from current inputs"
                )
        else:
            plan = preloaded_plan
        _acquisition_output_root(args)
        outputs = terminal_paths
        if _acquisition_dry_run(args):
            summary: JsonRecord = {
                "schema_version": TARGET_RAW_DOCKET_RECOVERY_SUMMARY_SCHEMA,
                "dry_run": True,
                "target_count": len(plan.targets),
                "provider_activity_requested": False,
            }
            resume = cast(bool, args.resume)
            _write_immutable_bytes(outputs[0], _jsonl_bytes([]), resume=resume)
            _write_immutable_bytes(outputs[1], _jsonl_bytes([]), resume=resume)
            _write_immutable_bytes(outputs[2], _json_bytes(summary), resume=resume)
            _write_immutable_bytes(
                outputs[3],
                target_raw_docket_recovery_receipt_bytes(
                    {
                        "schema_version": TARGET_RAW_DOCKET_RECOVERY_RECEIPT_SCHEMA,
                        "dry_run": True,
                        "plan_sha256": plan_sha256,
                    }
                ),
                resume=resume,
            )
            _write_acquisition_completion(
                args,
                stage="execute-target-raw-docket-recovery",
                input_paths=inputs,
                output_paths=outputs,
                record_count=0,
                dry_run=True,
                paid_activity_requested=False,
                paid_activity_executed=False,
                extra=summary,
            )
            return 0
        if completed_resume:
            expected_receipt_sha256 = cast(str | None, args.expected_receipt_sha256)
            if (
                expected_receipt_sha256 is None
                or re.fullmatch(r"[0-9a-f]{64}", expected_receipt_sha256) is None
            ):
                raise TargetRawDocketRecoveryError(
                    "completed resume requires --expected-receipt-sha256 as an "
                    "external lowercase SHA-256 anchor"
                )
            receipt = verify_target_raw_docket_recovery_receipt(
                receipt_path=outputs[3],
                expected_receipt_sha256=expected_receipt_sha256,
                expected_plan_sha256=plan_sha256,
                successes_path=outputs[0],
                exclusions_path=outputs[1],
                summary_path=outputs[2],
                raw_html_dir=cast(Path, args.raw_html_dir),
            )
            with CycleAcquisitionStore(Path(plan.cycle_store_path)) as store:
                if (
                    receipt.get("cycle_hash") != plan.cycle_hash
                    or receipt.get("run_id") != plan.run_id
                ):
                    raise TargetRawDocketRecoveryError(
                        "recovery receipt differs from the authenticated plan"
                    )
                _verify_target_raw_recovery_store_authority(
                    store=store,
                    receipt=receipt,
                    cycle_store_path=Path(plan.cycle_store_path),
                    batch_id=plan.batch_id,
                )
                if provider_contract_retry is not None and (
                    parent is None
                    or store.firecrawl_run_config(plan.run_id)
                    != provider_contract_retry_run_config(
                        retry_plan=provider_contract_retry,
                        direct_successor_run_id=parent.run_id,
                        recovered_plan=plan,
                        raw_html_dir=cast(Path, args.raw_html_dir),
                    )
                ):
                    raise TargetRawDocketRecoveryError(
                        "provider-contract retry receipt differs from durable "
                        "request authority"
                    )
            summary = _read_json_object(outputs[2])
            _write_acquisition_completion(
                args,
                stage="execute-target-raw-docket-recovery",
                input_paths=inputs,
                output_paths=outputs,
                record_count=cast(int, summary["success_count"]),
                dry_run=False,
                paid_activity_requested=False,
                paid_activity_executed=False,
                extra={**summary, "resumed_complete_receipt": True},
            )
            return 0
        raw_dir = cast(Path, args.raw_html_dir)
        with CycleAcquisitionStore(Path(plan.cycle_store_path)) as store:
            if store.cycle_hash != plan.cycle_hash:
                raise TargetRawDocketRecoveryError(
                    "cycle store hash differs from authenticated source snapshot"
                )
            if store.batch_digest(plan.source_batch_id) != plan.source_batch_digest:
                raise TargetRawDocketRecoveryError(
                    "cycle store source batch differs from authenticated snapshot"
                )
            if not cast(bool, args.resume):
                try:
                    store.batch_digest(plan.batch_id)
                except KeyError:
                    pass
                else:
                    raise TargetRawDocketRecoveryError(
                        "--no-resume forbids an existing recovery batch"
                    )
                try:
                    store.firecrawl_run_status(plan.run_id)
                except KeyError:
                    pass
                else:
                    raise TargetRawDocketRecoveryError(
                        "--no-resume forbids an existing Firecrawl run"
                    )
            else:
                _verify_target_raw_recovery_page_residue(
                    store=store,
                    run_id=plan.run_id,
                    raw_html_dir=raw_dir,
                )
                _verify_target_raw_recovery_terminal_residue(
                    store=store,
                    plan=plan,
                    raw_html_dir=raw_dir,
                )
            materialize_selected_slice_batch(
                store=store,
                parent_batch_id=plan.source_batch_id,
                selected_batch_id=plan.batch_id,
                records=plan.targets,
                limit=len(plan.targets),
                purpose="target-raw-docket-recovery",
            )
            config = (
                FirecrawlConfig.from_env(
                    proxy=cast(FirecrawlProxy, plan.proxy),
                    force_browser=plan.force_browser,
                )
                if live
                else FirecrawlConfig(
                    api_key="offline-fixture",
                    proxy=cast(FirecrawlProxy, plan.proxy),
                    force_browser=plan.force_browser,
                )
            )
            source = FirecrawlCourtListenerHTMLSource(
                config,
                **(
                    {"transport": _firecrawl_fixture_transport(fixture)}
                    if fixture
                    else {}
                ),
            )
            run_config: JsonRecord = (
                dict(
                    provider_contract_retry_run_config(
                        retry_plan=provider_contract_retry,
                        direct_successor_run_id=parent.run_id,
                        recovered_plan=plan,
                        raw_html_dir=raw_dir,
                    )
                )
                if provider_contract_retry is not None
                and successor is not None
                and parent is not None
                else {
                    "purpose": "target-raw-docket-recovery",
                    "recovery_of_run_id": (
                        parent.run_id
                        if parent is not None
                        else plan.source_snapshot_manifest_sha256
                    ),
                    **(
                        {
                            "parent_plan_sha256": successor.parent_plan_sha256,
                            "parent_failure_run_card_sha256": (
                                successor.parent_failure_run_card_sha256
                            ),
                        }
                        if successor is not None
                        else {}
                    ),
                    "max_pages_per_docket": plan.max_pages_per_docket,
                    "raw_artifact_root": str((raw_dir / "pages").resolve()),
                    "firecrawl_proxy": config.proxy,
                    "firecrawl_force_browser": config.force_browser,
                    "workers": plan.workers,
                    "max_attempts_per_page": plan.max_attempts_per_page,
                    "provider_breaker_threshold": plan.provider_breaker_threshold,
                }
            )
            store.ensure_firecrawl_run(
                plan.run_id,
                batch_id=plan.batch_id,
                config=run_config,
                credit_cap=plan.credit_cap,
                reserved_credits_per_attempt=config.max_credits_per_scrape,
            )
            successes, exclusions, execution_summary = (
                execute_target_raw_docket_recovery(
                    plan=plan,
                    scheduler=BudgetedFirecrawlScheduler(
                        store=store,
                        source=source,
                        run_id=plan.run_id,
                        artifact_dir=raw_dir / "pages",
                        max_attempts=plan.max_attempts_per_page,
                        provider_5xx_circuit_threshold=plan.provider_breaker_threshold,
                        max_workers=plan.workers,
                    ),
                    raw_html_dir=raw_dir,
                )
            )
            recovery_batch_digest = store.batch_digest(plan.batch_id)
            authenticated_run_config = dict(store.firecrawl_run_config(plan.run_id))
        summary = dict(execution_summary)
        summary["plan_sha256"] = plan_sha256
        summary["raw_artifacts"] = [
            {
                "candidate_id": record["candidate_id"],
                "sha256": record["raw_html_sha256"],
                "byte_count": record["raw_html_bytes"],
                "retrieved_at": record["retrieved_at"],
            }
            for record in successes
        ]
        recovery_provenance = {
            "schema_version": TARGET_RAW_DOCKET_RECOVERY_PROVENANCE_SCHEMA,
            "plan_sha256": plan_sha256,
            "batch_id": plan.batch_id,
            "run_id": plan.run_id,
        }
        successes = [
            {**dict(record), "target_raw_docket_recovery": recovery_provenance}
            for record in successes
        ]
        exclusions = [
            {**dict(record), "target_raw_docket_recovery": recovery_provenance}
            for record in exclusions
        ]
        resume = cast(bool, args.resume)
        successes_bytes = _jsonl_bytes(successes)
        exclusions_bytes = _jsonl_bytes(exclusions)
        summary_bytes = _json_bytes(summary)
        _write_immutable_bytes(outputs[0], successes_bytes, resume=resume)
        _write_immutable_bytes(outputs[1], exclusions_bytes, resume=resume)
        _write_immutable_bytes(outputs[2], summary_bytes, resume=resume)
        receipt_bytes = target_raw_docket_recovery_receipt_bytes(
            {
                "schema_version": TARGET_RAW_DOCKET_RECOVERY_RECEIPT_SCHEMA,
                "dry_run": False,
                "plan_sha256": plan_sha256,
                "source_snapshot_manifest_sha256": (
                    plan.source_snapshot_manifest_sha256
                ),
                "source_batch_id": plan.source_batch_id,
                "source_batch_digest": plan.source_batch_digest,
                "cycle_hash": plan.cycle_hash,
                "cycle_store_path": str(Path(plan.cycle_store_path).resolve()),
                "batch_id": plan.batch_id,
                "batch_digest": recovery_batch_digest,
                "run_id": plan.run_id,
                "run_config": authenticated_run_config,
                "credit_cap": plan.credit_cap,
                "reserved_credits_per_attempt": config.max_credits_per_scrape,
                "successes_path": str(outputs[0].resolve()),
                "exclusions_path": str(outputs[1].resolve()),
                "summary_path": str(outputs[2].resolve()),
                "raw_html_dir": str(raw_dir.resolve()),
                "successes_sha256": hashlib.sha256(successes_bytes).hexdigest(),
                "exclusions_sha256": hashlib.sha256(exclusions_bytes).hexdigest(),
                "summary_sha256": hashlib.sha256(summary_bytes).hexdigest(),
                "raw_artifacts": summary["raw_artifacts"],
            }
        )
        _write_immutable_bytes(outputs[3], receipt_bytes, resume=resume)
        receipt_sha256 = hashlib.sha256(receipt_bytes).hexdigest()
        _write_acquisition_completion(
            args,
            stage="execute-target-raw-docket-recovery",
            input_paths=inputs,
            output_paths=outputs,
            record_count=len(successes),
            dry_run=False,
            paid_activity_requested=live,
            paid_activity_executed=_firecrawl_metered_activity_executed(
                live=live, summary=summary
            ),
            extra={**summary, "receipt_sha256": receipt_sha256},
        )
    except (
        CycleAcquisitionStoreError,
        FirecrawlError,
        OSError,
        TargetRawDocketRecoveryError,
        ValueError,
    ) as exc:
        failure_credit_summary = _firecrawl_credit_summary_if_available(
            store_path=cast(Path, args.cycle_store),
            run_id=cast(str, args.run_id),
        )
        firecrawl_run_status = failure_credit_summary.pop("status", None)
        metered_executed = _firecrawl_metered_activity_executed(
            live=live,
            summary=failure_credit_summary,
        )
        _write_acquisition_failure(
            args,
            stage="execute-target-raw-docket-recovery",
            input_paths=inputs,
            output_paths=(
                cast(Path, args.successes_output),
                cast(Path, args.exclusions_output),
                cast(Path, args.summary_output),
                cast(Path, args.receipt_output),
            ),
            reason=str(exc),
            paid_activity_requested=live,
            paid_activity_executed=metered_executed,
            extra={
                "firecrawl_metered_activity_requested": live,
                "firecrawl_metered_activity_executed": metered_executed,
                "pacer_paid_activity_requested": False,
                "pacer_paid_activity_executed": False,
                **(
                    {"firecrawl_run_status": firecrawl_run_status}
                    if isinstance(firecrawl_run_status, str)
                    else {}
                ),
                **failure_credit_summary,
            },
        )
        raise CommandError(str(exc)) from exc
    return 0


def _cmd_acquisition_plan_target_public_gaps(args: argparse.Namespace) -> int:
    try:
        plan = _target_public_gap_plan_from_args(args)
        plan_output = cast(Path, args.plan_output).absolute()
        resolved_plan_output = plan_output.resolve(strict=False)
        for label, path in (
            ("target root", plan.target_cohort_root.resolve()),
            ("final output root", plan.execution_identity.output_root.resolve()),
            ("raw HTML root", plan.execution_identity.raw_html_root.resolve()),
            (
                "document output root",
                plan.execution_identity.document_output_root.resolve(),
            ),
        ):
            if (
                resolved_plan_output == path
                or resolved_plan_output.is_relative_to(path)
                or path.is_relative_to(resolved_plan_output)
            ):
                raise TargetPublicGapRefreshError(f"plan output overlaps {label}")
        publish_target_public_gap_plan(plan_output, plan)
    except (CommandError, OSError, TargetPublicGapRefreshError) as exc:
        raise CommandError(str(exc)) from exc
    return 0


def _cmd_acquisition_execute_target_public_gaps(args: argparse.Namespace) -> int:
    firecrawl_fixture = cast(Path | None, args.firecrawl_fixture)
    live_firecrawl = cast(bool, args.live_firecrawl)
    document_fixture = cast(Path | None, args.fixture_documents)
    live_download = cast(bool, args.live_public_download)
    if live_firecrawl != (cast(str, args.firecrawl_mode) == "live"):
        raise CommandError("provider flags differ from plan-bound Firecrawl mode")
    if live_download != (cast(str, args.document_mode) == "live"):
        raise CommandError("provider flags differ from plan-bound document mode")
    if live_firecrawl == (firecrawl_fixture is not None):
        raise CommandError(
            "execution requires exactly one of --live-firecrawl or --firecrawl-fixture"
        )
    if live_download == (document_fixture is not None):
        raise CommandError(
            "execution requires exactly one of --live-public-download or "
            "--fixture-documents"
        )
    if firecrawl_fixture is not None and cast(int, args.workers) != 1:
        raise CommandError("Firecrawl fixture execution requires --workers 1")
    try:
        plan, authenticated_sources = _target_public_gap_plan_with_sources_from_args(
            args
        )
        role_adjudications = _verified_packet_role_adjudications_from_args(args)
        packet_role_replay = _packet_role_replay_receipt_from_args(
            args,
            role_adjudications,
        )
        expected_plan_sha256 = cast(str, args.expected_plan_sha256)
        verify_target_public_gap_plan(
            cast(Path, args.plan),
            expected_sha256=expected_plan_sha256,
            reconstructed=plan,
        )
    except (
        CommandError,
        OSError,
        PacketRoleAdjudicationError,
        ReviewBundleError,
        TargetPublicGapRefreshError,
    ) as exc:
        raise CommandError(str(exc)) from exc

    def firecrawl_source_factory() -> FirecrawlCourtListenerHTMLSource:
        firecrawl_config = (
            FirecrawlConfig.from_env(
                proxy=cast(FirecrawlProxy, args.proxy),
                force_browser=cast(bool, args.force_browser),
            )
            if live_firecrawl
            else FirecrawlConfig(
                api_key="offline-fixture",
                proxy=cast(FirecrawlProxy, args.proxy),
                force_browser=cast(bool, args.force_browser),
            )
        )
        return FirecrawlCourtListenerHTMLSource(
            firecrawl_config,
            **(
                {"transport": _firecrawl_fixture_transport(firecrawl_fixture)}
                if firecrawl_fixture is not None
                else {}
            ),
        )

    def document_source_factory() -> FreeDocumentSource:
        return (
            UrlLibFreeDocumentSource()
            if live_download
            else _fixture_free_document_source(cast(Path, document_fixture))
        )

    try:
        prevalidated_execution = _prevalidate_target_public_gap_execution(
            plan=plan,
            expected_plan_sha256=expected_plan_sha256,
            packet_role_replay=packet_role_replay,
            authenticated_sources=authenticated_sources,
        )
        prepared_execution = _prepare_target_public_gap_execution(
            plan=plan,
            expected_plan_sha256=expected_plan_sha256,
            packet_role_replay=packet_role_replay,
            prevalidated_execution=prevalidated_execution,
            firecrawl_source_factory=firecrawl_source_factory,
        )
        with bind_target_public_gap_execution(plan) as binding:
            validated_execution = _validate_target_public_gap_execution(
                plan=plan,
                expected_plan_sha256=expected_plan_sha256,
                packet_role_replay=packet_role_replay,
                execution_binding=binding,
                prevalidated_execution=prevalidated_execution,
                prepared_execution=prepared_execution,
            )
            execution = _execute_target_public_gap_refresh(
                plan=plan,
                expected_plan_sha256=expected_plan_sha256,
                firecrawl_source_factory=firecrawl_source_factory,
                document_source_factory=document_source_factory,
                allow_existing_downloads=cast(bool, args.resume),
                role_adjudications=role_adjudications,
                packet_role_replay=packet_role_replay,
                execution_binding=binding,
                validated_execution=validated_execution,
            )
            binding.require_current(plan)
            with bind_verified_target_public_gap_downloads(
                execution_binding=binding,
                requests=execution.refresh.download_requests,
                downloads=execution.downloads,
            ):
                # The initial preflight above authenticated the source closure
                # and pinned writable namespaces for this invocation.  Recheck
                # both exact bindings immediately before any terminal bytes are
                # published; intermediate execute phases only consume that
                # in-process evidence.
                binding.require_current(plan)
                require_target_public_gap_sources_unchanged(plan)
                payloads = _target_public_gap_terminal_payloads(
                    plan=plan,
                    plan_path=cast(Path, args.plan),
                    plan_sha256=expected_plan_sha256,
                    execution=execution,
                    live_firecrawl=live_firecrawl,
                    live_download=live_download,
                    packet_role_replay=packet_role_replay,
                )
                publish_target_public_gap_outputs(
                    plan=plan,
                    plan_sha256=expected_plan_sha256,
                    payloads=payloads,
                    execution_binding=binding,
                )
            binding.require_current(plan)
            require_target_public_gap_sources_unchanged(plan)
    except (
        CycleAcquisitionStoreError,
        FirecrawlError,
        FreeDocumentDownloadError,
        OSError,
        TargetPublicGapRefreshError,
    ) as exc:
        raise CommandError(str(exc)) from exc
    return 0


def _target_public_gap_terminal_payloads(
    *,
    plan: TargetPublicGapPlan,
    plan_path: Path,
    plan_sha256: str,
    execution: TargetPublicGapExecutionResult,
    live_firecrawl: bool,
    live_download: bool,
    packet_role_replay: Mapping[str, object] | None = None,
) -> Mapping[str, bytes]:
    refresh = execution.refresh
    core: dict[str, bytes] = {
        "target-public-gap-outcomes.jsonl": _jsonl_bytes(execution.outcomes),
        "target-public-gap-discovered-transitions.jsonl": _jsonl_bytes(
            refresh.transitions
        ),
        "free-document-requests.jsonl": _jsonl_bytes(
            request.to_record() for request in refresh.download_requests
        ),
        "free-document-downloads.jsonl": _jsonl_bytes(
            record.to_record() for record in execution.downloads
        ),
    }
    core_commitments = {
        name: hashlib.sha256(payload).hexdigest()
        for name, payload in sorted(core.items())
    }
    terminal_commitments = dict(execution.terminal_commitments)
    if terminal_commitments.get("plan_sha256") != plan_sha256:
        raise TargetPublicGapRefreshError(
            "terminal commitments differ from the externally pinned plan"
        )
    no_authority = {
        "pacer_authorized": False,
        "recap_fetch_authorized": False,
        "document_purchase_authorized": False,
        "model_calls_authorized": False,
        "evaluation_authorized": False,
        "freeze_or_dispatch_authorized": False,
    }
    summary: JsonRecord = {
        "schema_version": "legalforecast.target_public_gap_execution_summary.v1",
        "plan_sha256": plan_sha256,
        "terminal_commitments": terminal_commitments,
        "output_commitments": core_commitments,
        "provider_activity_requested": live_firecrawl or live_download,
        "firecrawl_metered_activity_requested": live_firecrawl,
        "public_download_activity_requested": live_download,
        "purchased_document_count": 0,
        "purchased_activity_requested": False,
        "purchased_activity_executed": False,
        "terminal_reconciliation": True,
        **no_authority,
    }
    summary_bytes = _projection_json_bytes(summary)
    core["target-public-gap-execution-summary.json"] = summary_bytes
    committed_outputs = {
        name: hashlib.sha256(payload).hexdigest()
        for name, payload in sorted(core.items())
    }
    run_card: JsonRecord = {
        "schema_version": "legalforecast.target_public_gap_execution_receipt.v1",
        "stage": "execute-target-public-gaps",
        "status": "completed",
        "plan_path": str(plan_path.absolute()),
        "plan_sha256": plan_sha256,
        "execution_identity": dict(plan.execution_identity.to_record()),
        "fresh_credit_cap": plan.fresh_credit_cap,
        "input_paths": sorted(plan.source_artifact_commitments),
        "source_artifact_commitments": dict(plan.source_artifact_commitments),
        "output_paths": [
            str(plan.execution_identity.output_root / name)
            for name in sorted(
                [
                    *core,
                    "run-cards/execute-target-public-gaps.json",
                    "logs/execute-target-public-gaps.jsonl",
                ]
            )
        ],
        "output_commitments": committed_outputs,
        "terminal_commitments": terminal_commitments,
        "provider_activity_requested": live_firecrawl or live_download,
        "purchased_document_count": 0,
        "purchased_activity_requested": False,
        "purchased_activity_executed": False,
        **no_authority,
    }
    if packet_role_replay is not None:
        run_card["packet_role_replay"] = dict(packet_role_replay)
    run_card_bytes = _projection_json_bytes(run_card)
    core["run-cards/execute-target-public-gaps.json"] = run_card_bytes
    core["logs/execute-target-public-gaps.jsonl"] = _jsonl_bytes(
        (
            {
                "schema_version": ("legalforecast.target_public_gap_execution_log.v1"),
                "event": "completed",
                "plan_sha256": plan_sha256,
                "run_card_sha256": hashlib.sha256(run_card_bytes).hexdigest(),
            },
        )
    )
    return core


def _cmd_acquisition_seal_ranked_dockets(args: argparse.Namespace) -> int:
    """Seal one exhausted Firecrawl ledger without touching providers or source."""

    # Do not create any output directory until every source-overlap gate passes.
    output_root = cast(Path, args.output_root)
    source_store = cast(Path, args.source_cycle_store)
    ranked_path = cast(Path, args.ranked)
    selection_card_path = cast(Path, args.ranked_selection_run_card)
    selection_card_sha256 = cast(str, args.expected_ranked_selection_run_card_sha256)
    run_id = cast(str, args.run_id)
    max_candidates = cast(int, args.max_candidates)
    max_pages = cast(int, args.max_pages_per_docket)
    fresh_recovery_cap = cast(int, args.authorized_fresh_recovery_credit_cap)
    total_prior_authorized_credits = cast(
        int, args.expected_total_prior_authorized_firecrawl_credits
    )
    anchor = _iso_date_argument(
        cast(str, args.decision_filed_on_or_after),
        "--decision-filed-on-or-after",
    )
    raw_dir = _acquisition_path(args, "raw_html_dir", output_root / "raw-docket-html")
    successes_path = _acquisition_path(
        args, "successes_output", output_root / "firecrawl-docket-successes.jsonl"
    )
    exclusions_path = _acquisition_path(
        args, "exclusions_output", output_root / "firecrawl-docket-exclusions.jsonl"
    )
    terminal_path = _acquisition_path(
        args,
        "terminal_manifest_output",
        output_root / "firecrawl-terminal-partition.jsonl",
    )
    unresolved_path = _acquisition_path(
        args,
        "unresolved_manifest_output",
        output_root / "firecrawl-unresolved-partition.jsonl",
    )
    summary_path = _acquisition_path(
        args, "summary_output", output_root / "firecrawl-docket-seal-summary.json"
    )
    run_card_path = _acquisition_path(
        args,
        "run_card_output",
        output_root / "run-cards" / "seal-ranked-firecrawl-run.json",
    )
    log_path = _acquisition_path(
        args,
        "log_output",
        output_root / "logs" / "seal-ranked-firecrawl-run.jsonl",
    )
    output_paths = (
        successes_path,
        exclusions_path,
        terminal_path,
        unresolved_path,
        summary_path,
        run_card_path,
    )
    validation_writable_paths = (*output_paths, log_path)
    _validate_ranked_handoff_paths(
        protected_paths=(source_store, ranked_path, selection_card_path),
        writable_paths=validation_writable_paths,
        sqlite_paths=(source_store,),
        context="ranked Firecrawl seal",
    )
    if max_candidates <= 0:
        raise CommandError("--max-candidates must be positive")
    if not source_store.is_file():
        raise CommandError("--source-cycle-store must be an existing store")

    try:
        with CycleAcquisitionStore(source_store, read_only=True) as store:
            source_summary = dict(store.firecrawl_run_summary(run_id))
            source_batch_id = source_summary.get("batch_id")
            if not isinstance(source_batch_id, str) or not source_batch_id:
                raise RankedFirecrawlRecoveryError(
                    "source Firecrawl run lacks a valid selected batch"
                )
            authenticated_parent_batch_id = authenticated_handoff_parent_batch_id(
                store,
                source_batch_id,
            )
            records = list(
                verify_authenticated_ranked_firecrawl_handoff(
                    store=store,
                    parent_batch_id=authenticated_parent_batch_id,
                    ranked_path=ranked_path,
                    selection_run_card_path=selection_card_path,
                    expected_selection_run_card_sha256=selection_card_sha256,
                    max_candidates=max_candidates,
                )
            )
            verify_authenticated_acquisition_slice(
                store=store,
                acquisition_batch_id=source_batch_id,
                authenticated_parent_batch_id=authenticated_parent_batch_id,
                records=records,
            )
            source_batch_digest = store.batch_digest(source_batch_id)
            source_parent_batch_digest = store.batch_digest(
                authenticated_parent_batch_id
            )
            source_slice_config = store.batch_config(source_batch_id)
            source_selection_count = source_slice_config.get("selection_count")
            source_selection_hash = source_slice_config.get("selection_hash")
            if len(records) != max_candidates:
                raise RankedFirecrawlRecoveryError(
                    "authenticated ranked selection does not contain exactly "
                    "--max-candidates records"
                )
            sealed = seal_ranked_firecrawl_run(
                store=store,
                run_id=run_id,
                records=records,
                expected_cycle_hash=cast(str, args.expected_cycle_hash),
                expected_run_config_sha256=cast(str, args.expected_run_config_sha256),
                expected_credit_cap=cast(int, args.expected_credit_cap),
                max_pages_per_docket=max_pages,
                decision_anchor=anchor,
            )
            source_config = store.firecrawl_run_config(run_id)
            source_raw_root_value = source_config.get("raw_artifact_root")
            if not isinstance(source_raw_root_value, str):
                raise RankedFirecrawlRecoveryError(
                    "source Firecrawl run lacks a raw artifact root"
                )
            source_raw_root = Path(source_raw_root_value)
            _reject_recovery_artifact_overlap(
                source_raw_root=source_raw_root,
                writable_paths=(raw_dir, *validation_writable_paths),
            )
            lineage_flags = provisional_lineage_flags(
                store.batch_config(source_batch_id)
            )
            artifacts = build_sealed_ranked_firecrawl_artifacts(
                sealed=sealed,
                records=records,
                raw_html_dir=raw_dir,
                lineage_flags=lineage_flags,
            )
            reserved_per_attempt = sealed.credit_summary.get(
                "reserved_credits_per_attempt"
            )
            if type(reserved_per_attempt) is not int:
                raise RankedFirecrawlRecoveryError(
                    "source run lacks valid Firecrawl reservation authority"
                )
            validate_fresh_recovery_credit_authority(
                source_credit_cap=sealed.source_credit_cap,
                total_prior_authorized_credits=total_prior_authorized_credits,
                fresh_recovery_credit_cap=fresh_recovery_cap,
                reserved_credits_per_attempt=reserved_per_attempt,
            )
    except (
        BudgetedDocketAcquisitionError,
        CycleAcquisitionStoreError,
        RankedFirecrawlRecoveryError,
        KeyError,
        OSError,
        UnicodeError,
        ValueError,
    ) as exc:
        raise CommandError(str(exc)) from exc

    selection_card_bytes = read_pinned_regular_file(
        selection_card_path,
        expected_sha256=selection_card_sha256,
        label="ranked-selection run card",
    )
    try:
        selection_card_value = json.loads(selection_card_bytes)
    except (UnicodeError, json.JSONDecodeError) as exc:
        raise CommandError("ranked-selection run card is not valid JSON") from exc
    if not isinstance(selection_card_value, Mapping):
        raise CommandError("ranked-selection run card must be an object")
    selection_card = cast(Mapping[str, object], selection_card_value)
    successes_bytes = _jsonl_bytes(artifacts.successes)
    exclusions_bytes = _jsonl_bytes(artifacts.exclusions)
    terminal_bytes = _jsonl_bytes(artifacts.terminal_manifest)
    unresolved_bytes = _jsonl_bytes(artifacts.unresolved_manifest)
    terminal_set_sha256 = canonical_recovery_commitment(
        [record["candidate_id"] for record in artifacts.terminal_manifest]
    )
    unresolved_set_sha256 = canonical_recovery_commitment(
        [record["candidate_id"] for record in artifacts.unresolved_manifest]
    )
    summary: JsonRecord = {
        "schema_version": RANKED_FIRECRAWL_SEAL_SCHEMA,
        "partition_schema_version": RANKED_FIRECRAWL_PARTITION_SCHEMA,
        "dry_run": _acquisition_dry_run(args),
        "source_cycle_hash": sealed.source_cycle_hash,
        "source_batch_id": sealed.source_batch_id,
        "source_batch_digest": source_batch_digest,
        "source_parent_batch_id": authenticated_parent_batch_id,
        "source_parent_batch_digest": source_parent_batch_digest,
        "source_selection_count": source_selection_count,
        "source_selection_hash": source_selection_hash,
        "source_run_id": sealed.run_id,
        "source_run_config_sha256": sealed.source_run_config_sha256,
        "source_credit_cap": sealed.source_credit_cap,
        "total_prior_authorized_firecrawl_credits": (total_prior_authorized_credits),
        "authorized_fresh_recovery_credit_cap": fresh_recovery_cap,
        "combined_firecrawl_credit_ceiling": (RANKED_FIRECRAWL_COMBINED_CREDIT_CEILING),
        "source_ledger_as_of": sealed.source_ledger_as_of,
        "source_candidate_count": sealed.source_candidate_count,
        "success_count": len(artifacts.successes),
        "exclusion_count": len(artifacts.exclusions),
        "terminal_count": len(artifacts.terminal_manifest),
        "unresolved_count": len(artifacts.unresolved_manifest),
        "terminal_candidate_set_sha256": terminal_set_sha256,
        "unresolved_candidate_set_sha256": unresolved_set_sha256,
        "target_commitment_sha256": sealed.target_commitment_sha256,
        "attempt_commitment_sha256": sealed.attempt_commitment_sha256,
        "recovery_required": bool(artifacts.unresolved_manifest),
        "provider_activity_requested": False,
        "provider_activity_executed": False,
        "paid_activity_requested": False,
        "paid_activity_executed": False,
        **dict(sealed.credit_summary),
        **lineage_flags,
    }
    if _acquisition_dry_run(args):
        _write_acquisition_completion(
            args,
            stage="seal-ranked-firecrawl-run",
            input_paths=(source_store, ranked_path, selection_card_path),
            output_paths=output_paths[:-1],
            record_count=len(artifacts.terminal_manifest),
            dry_run=True,
            paid_activity_requested=False,
            paid_activity_executed=False,
            extra=summary,
        )
        print(json.dumps(summary, sort_keys=True))
        return 0

    output_commitments: JsonRecord = {
        "successes": _sealed_output_commitment(
            successes_path, successes_bytes, len(artifacts.successes)
        ),
        "exclusions": _sealed_output_commitment(
            exclusions_path, exclusions_bytes, len(artifacts.exclusions)
        ),
        "terminal_manifest": _sealed_output_commitment(
            terminal_path, terminal_bytes, len(artifacts.terminal_manifest)
        ),
        "unresolved_manifest": _sealed_output_commitment(
            unresolved_path, unresolved_bytes, len(artifacts.unresolved_manifest)
        ),
    }
    summary.update({"dry_run": False, "outputs": dict(output_commitments)})
    summary_bytes = _json_bytes(summary)
    output_commitments["summary"] = _sealed_output_commitment(
        summary_path, summary_bytes, 1
    )
    run_card: JsonRecord = {
        "schema_version": RANKED_FIRECRAWL_SEAL_SCHEMA,
        "stage": "seal-ranked-firecrawl-run",
        "status": "completed",
        "execute": True,
        "dry_run": False,
        "sealed_at": sealed.source_ledger_as_of,
        "provider_activity_requested": False,
        "provider_activity_executed": False,
        "paid_activity_requested": False,
        "paid_activity_executed": False,
        "source_cycle_store": str(source_store.resolve()),
        "source_cycle_hash": sealed.source_cycle_hash,
        "source_batch_id": sealed.source_batch_id,
        "source_batch_digest": source_batch_digest,
        "source_parent_batch_id": authenticated_parent_batch_id,
        "source_parent_batch_digest": source_parent_batch_digest,
        "source_selection_count": source_selection_count,
        "source_selection_hash": source_selection_hash,
        "source_run_id": sealed.run_id,
        "source_run_config_sha256": sealed.source_run_config_sha256,
        "source_credit_cap": sealed.source_credit_cap,
        "total_prior_authorized_firecrawl_credits": (total_prior_authorized_credits),
        "authorized_fresh_recovery_credit_cap": fresh_recovery_cap,
        "combined_firecrawl_credit_ceiling": (RANKED_FIRECRAWL_COMBINED_CREDIT_CEILING),
        "source_candidate_count": sealed.source_candidate_count,
        "ranked_path": str(ranked_path.resolve()),
        "ranked_sha256": hashlib.sha256(ranked_path.read_bytes()).hexdigest(),
        "ranked_selection_run_card_path": str(selection_card_path.resolve()),
        "ranked_selection_run_card_sha256": selection_card_sha256,
        "ranking_authority": selection_card,
        "raw_html_dir": str(raw_dir.resolve()),
        "decision_filed_on_or_after": anchor.isoformat(),
        "max_pages_per_docket": max_pages,
        "target_commitment_sha256": sealed.target_commitment_sha256,
        "attempt_commitment_sha256": sealed.attempt_commitment_sha256,
        "terminal_candidate_set_sha256": terminal_set_sha256,
        "unresolved_candidate_set_sha256": unresolved_set_sha256,
        "terminal_count": len(artifacts.terminal_manifest),
        "unresolved_count": len(artifacts.unresolved_manifest),
        "outputs": output_commitments,
        **lineage_flags,
    }
    resume = cast(bool, args.resume)
    for docket_id, payload in artifacts.raw_html_by_docket.items():
        _write_immutable_bytes(raw_dir / f"{docket_id}.html", payload, resume=resume)
    for path, payload in (
        (successes_path, successes_bytes),
        (exclusions_path, exclusions_bytes),
        (terminal_path, terminal_bytes),
        (unresolved_path, unresolved_bytes),
        (summary_path, summary_bytes),
    ):
        _write_immutable_bytes(path, payload, resume=resume)
    # The authenticated run card is intentionally the final artifact published.
    _write_immutable_bytes(run_card_path, _json_bytes(run_card), resume=resume)
    print(json.dumps(summary, sort_keys=True))
    return 0


def _cmd_acquisition_funnel_report(args: argparse.Namespace) -> int:
    try:
        discovery_path = cast(Path | None, args.discovery_summary)
        screening_path = cast(Path | None, args.firecrawl_screening_summary)
        recap_path = cast(Path | None, args.recap_discovery_summary)
        if screening_path is not None and recap_path is None:
            raise FunnelReportError(
                "--recap-discovery-summary is required with "
                "--firecrawl-screening-summary"
            )
        if discovery_path is not None and recap_path is not None:
            raise FunnelReportError(
                "--recap-discovery-summary is only valid with "
                "--firecrawl-screening-summary"
            )
        report = build_acquisition_funnel_report(
            discovery_summary=(
                _read_json_object(discovery_path)
                if discovery_path is not None
                else None
            ),
            firecrawl_screening_summary=(
                _read_json_object(screening_path)
                if screening_path is not None
                else None
            ),
            recap_discovery_summary=(
                _read_json_object(recap_path) if recap_path is not None else None
            ),
            exclusions=_read_records(cast(Path, args.exclusions)),
            public_download_summary=_read_json_object(
                cast(Path, args.public_download_summary)
            ),
        )
    except (FunnelReportError, OSError, UnicodeError, ValueError) as exc:
        raise CommandError(str(exc)) from exc
    _write_json(cast(Path, args.output), report)
    return 0


def _cmd_acquisition_generate_labeling_policy(args: argparse.Namespace) -> int:
    """Publish the canonical pre-labeling policy without invoking freeze state."""

    artifact = generate_labeling_policy(
        cycle_id=cast(str, args.cycle_id),
        judge_registry_path=cast(Path, args.judge_registry),
        published_at=_parse_datetime(cast(str, args.published_at)),
        threshold_source=cast(str, args.threshold_source),
    )
    output = cast(Path, args.output)
    write_labeling_policy(output, artifact)
    verify_labeling_policy(
        _read_json_object(output),
        judge_registry_path=cast(Path, args.judge_registry),
        expected_cycle_id=cast(str, args.cycle_id),
    )
    print(json.dumps(artifact, sort_keys=True))
    return 0


def _cmd_acquisition_verify_labeling_policy(args: argparse.Namespace) -> int:
    policy_sha256 = verify_labeling_policy(
        _read_json_object(cast(Path, args.artifact)),
        judge_registry_path=cast(Path, args.judge_registry),
        expected_cycle_id=cast(str | None, args.cycle_id),
    )
    print(policy_sha256)
    return 0


# ---------------------------------------------------------------------------
# batch-002 RECAP API acquisition driver handlers.
# ---------------------------------------------------------------------------


def _batch_002_client(
    args: argparse.Namespace,
    *,
    require_token: bool,
) -> tuple[CourtListenerClient, CourtListenerRequestBudget | None]:
    """Build a live or fixture CourtListener client for a batch-002 phase."""

    live = cast(bool, args.live)
    fixture = cast(Path | None, args.courtlistener_fixture)
    config = CourtListenerConfig.from_env()
    max_retries = cast(int, getattr(args, "max_retries", 2))
    retry_backoff = cast(float, getattr(args, "retry_backoff_seconds", 0.0))
    if require_token and config.api_token is None:
        raise CommandError(f"{COURTLISTENER_API_TOKEN_ENV} is required")
    if live:
        ledger_path = cast(Path | None, args.request_ledger)
        if ledger_path is None:
            raise CommandError("--request-ledger is required with --live")
        max_wait = cast(float, args.request_budget_max_wait_seconds)
        if max_wait < 0:
            raise CommandError("--request-budget-max-wait-seconds cannot be negative")
        profile = cast(str, args.courtlistener_rate_profile)
        if profile == "temporary-doubled" and config.api_token is None:
            raise CommandError(
                "--courtlistener-rate-profile temporary-doubled requires "
                f"{COURTLISTENER_API_TOKEN_ENV}"
            )
        try:
            budget = CourtListenerRequestBudget(
                ledger_path,
                limits=_COURTLISTENER_RATE_PROFILES[profile],
                max_wait_seconds=max_wait,
            )
        except (CourtListenerRequestBudgetError, OSError) as exc:
            raise CommandError(str(exc)) from exc
        return (
            CourtListenerClient(
                config=config,
                max_retries=max_retries,
                retry_backoff_seconds=retry_backoff,
                before_request=budget.before_request,
            ),
            budget,
        )
    assert fixture is not None
    return (
        CourtListenerClient(
            config=config,
            transport=CourtListenerFixtureTransport.from_jsonl(fixture),
            max_retries=max_retries,
            retry_backoff_seconds=retry_backoff,
        ),
        None,
    )


def _courtlistener_bridge_client(
    args: argparse.Namespace,
    *,
    fixture_path: Path | None,
    live: bool,
) -> tuple[CourtListenerClient, CourtListenerRequestBudget | None]:
    """Build the paid-gap metadata client with durable live request accounting."""

    config = CourtListenerConfig.from_env()
    if fixture_path is not None:
        return (
            CourtListenerClient(
                config=config,
                transport=CourtListenerFixtureTransport.from_jsonl(fixture_path),
            ),
            None,
        )
    if not live:
        raise CommandError(
            "CourtListener bridge requires --courtlistener-fixture or "
            "--live-courtlistener"
        )
    if config.api_token is None:
        raise CommandError(
            f"{COURTLISTENER_API_TOKEN_ENV} is required with --live-courtlistener"
        )
    ledger_path = cast(Path | None, args.request_ledger)
    if ledger_path is None:
        raise CommandError("--request-ledger is required with --live-courtlistener")
    max_wait = cast(float, args.request_budget_max_wait_seconds)
    if max_wait < 0:
        raise CommandError("--request-budget-max-wait-seconds cannot be negative")
    profile = cast(str, args.courtlistener_rate_profile)
    try:
        budget = CourtListenerRequestBudget(
            ledger_path,
            limits=_COURTLISTENER_RATE_PROFILES[profile],
            max_wait_seconds=max_wait,
        )
    except (CourtListenerRequestBudgetError, OSError) as exc:
        raise CommandError(str(exc)) from exc
    return (
        CourtListenerClient(config=config, before_request=budget.before_request),
        budget,
    )


def _courtlistener_bridge_rate_evidence(
    args: argparse.Namespace,
    client: CourtListenerClient,
    budget: CourtListenerRequestBudget | None,
) -> JsonRecord:
    if budget is None:
        return {
            "courtlistener_live": False,
            "courtlistener_physical_requests": client.request_count,
        }
    return {
        "courtlistener_live": True,
        "courtlistener_rate_profile": cast(str, args.courtlistener_rate_profile),
        "courtlistener_request_ledger": str(budget.path.resolve()),
        "courtlistener_physical_requests": client.request_count,
        "courtlistener_reservations_this_phase": budget.local_reservations,
        "courtlistener_reservations_total": budget.total_reservations(),
        "courtlistener_limits": {
            "per_minute": budget.limits.per_minute,
            "per_hour": budget.limits.per_hour,
            "per_day": budget.limits.per_day,
        },
    }


def _recap_fetch_rate_evidence(
    args: argparse.Namespace,
    *,
    client: CourtListenerRecapFetchClient | None,
    budget: CourtListenerRequestBudget | None,
    live: bool,
) -> JsonRecord:
    """Return request-ledger evidence for RECAP verification and polling GETs."""

    evidence: JsonRecord = {
        "courtlistener_live": live,
        "courtlistener_physical_requests": (
            0 if client is None else client.courtlistener_request_count
        ),
    }
    if not live:
        return evidence
    evidence.update(
        {
            "courtlistener_rate_profile": cast(str, args.courtlistener_rate_profile),
            "courtlistener_request_budget_max_wait_seconds": cast(
                float, args.request_budget_max_wait_seconds
            ),
        }
    )
    request_ledger = cast(Path | None, args.request_ledger)
    if request_ledger is not None:
        evidence["courtlistener_request_ledger"] = str(request_ledger.resolve())
    if budget is not None:
        evidence.update(
            {
                "courtlistener_reservations_this_phase": budget.local_reservations,
                "courtlistener_reservations_total": budget.total_reservations(),
                "courtlistener_limits": {
                    "per_minute": budget.limits.per_minute,
                    "per_hour": budget.limits.per_hour,
                    "per_day": budget.limits.per_day,
                },
            }
        )
    return evidence


def _batch_002_rate_evidence(
    args: argparse.Namespace,
    client: CourtListenerClient,
    budget: CourtListenerRequestBudget | None,
) -> dict[str, object]:
    """Return auditable request-budget evidence for a phase summary."""

    if budget is None:
        return {
            "courtlistener_live": False,
            "courtlistener_physical_requests": client.request_count,
        }
    total = budget.total_reservations()
    return {
        "courtlistener_live": True,
        "courtlistener_rate_profile": cast(str, args.courtlistener_rate_profile),
        "courtlistener_request_ledger": str(budget.path.resolve()),
        "courtlistener_physical_requests": client.request_count,
        "courtlistener_reservations_this_phase": budget.local_reservations,
        "courtlistener_reservations_total": total,
        "courtlistener_limits": {
            "per_minute": budget.limits.per_minute,
            "per_hour": budget.limits.per_hour,
            "per_day": budget.limits.per_day,
        },
    }


def _batch_002_default_live_interval(args: argparse.Namespace) -> float:
    """Return quarter-second-rounded spacing that honors the hourly profile."""

    profile = cast(str, args.courtlistener_rate_profile)
    per_hour = _COURTLISTENER_RATE_PROFILES[profile].per_hour
    return math.ceil((3_600.0 / per_hour) * 4.0) / 4.0


def _batch_002_observe_pacer(args: argparse.Namespace) -> RequestPacer | None:
    """Build a conservatively spaced pacer, or None when pacing is disabled."""

    configured = cast(float | None, args.min_interval_seconds)
    jitter = cast(float, args.jitter_seconds)
    if configured is not None and configured < 0:
        raise CommandError("--min-interval-seconds cannot be negative")
    if jitter < 0:
        raise CommandError("--jitter-seconds cannot be negative")
    if configured is None and not cast(bool, args.live):
        return None
    min_interval = (
        _batch_002_default_live_interval(args) if configured is None else configured
    )
    if min_interval <= 0 and jitter <= 0:
        return None
    if jitter <= 0:
        return RequestPacer(min_interval_seconds=max(min_interval, 0.0))
    rng = random.Random()
    base_sleep = time.sleep

    def jittered_sleep(seconds: float) -> None:
        base_sleep(seconds + rng.uniform(0.0, jitter))

    return RequestPacer(
        min_interval_seconds=max(min_interval, 0.0),
        sleep=jittered_sleep,
    )


def _cmd_batch_002_discover(args: argparse.Namespace) -> int:
    cycle_store = cast(Path, args.cycle_store)
    batch_id = cast(str, args.batch_id)
    anchor = _iso_date_argument(
        cast(str, args.eligibility_anchor), "--eligibility-anchor"
    )
    window_start = _iso_date_argument(
        cast(str, args.decision_window_start), "--decision-window-start"
    )
    window_end = _iso_date_argument(
        cast(str, args.decision_window_end), "--decision-window-end"
    )
    if window_end < window_start:
        raise CommandError(
            "--decision-window-end cannot precede --decision-window-start"
        )
    override = cast(float | None, args.min_interval_seconds)
    if override is not None and override < 0:
        raise CommandError("--min-interval-seconds cannot be negative")
    client, budget = _batch_002_client(args, require_token=False)
    if override is not None:
        pacer: RequestPacer | None = RequestPacer(min_interval_seconds=override)
    elif cast(bool, args.live):
        pacer = RequestPacer(
            min_interval_seconds=_batch_002_default_live_interval(args)
        )
    else:
        pacer = None
    try:
        with CycleAcquisitionStore(cycle_store) as store:
            store.ensure_cycle(_cycle_acquisition_policy(anchor=anchor))
            funnel = run_discover(
                store,
                batch_id=batch_id,
                client=client,
                decision_window_start=window_start,
                decision_window_end=window_end,
                top_k_per_term=cast(int, args.top_k_per_term),
                page_size=cast(int, args.page_size),
                pacer=pacer,
            )
    except (
        CycleAcquisitionStoreError,
        CourtListenerRequestBudgetError,
        RecapApiBatchDriverError,
        ValueError,
    ) as exc:
        raise CommandError(str(exc)) from exc
    record = {
        **funnel.to_record(),
        **_batch_002_rate_evidence(args, client, budget),
    }
    summary_output = cast(Path | None, args.summary_output)
    if summary_output is not None:
        _write_json(summary_output, record)
    print(json.dumps(record, sort_keys=True))
    return 0


