def _cmd_batch_002_opinion_resolve(args: argparse.Namespace) -> int:
    source_store = cast(Path, args.source_store)
    source_batch_id = cast(str, args.source_batch_id)
    resolver_journal = cast(Path, args.resolver_journal)
    cycle_store = cast(Path, args.cycle_store)
    batch_id = cast(str, args.batch_id)
    prior_paths = tuple(cast(list[Path], args.prior_snapshot))
    prior_hashes = tuple(cast(list[str], args.prior_snapshot_manifest_sha256))
    courtlistener_only = cast(bool, args.courtlistener_only)
    case_dev_fixture = cast(Path | None, args.case_dev_fixture)
    live = cast(bool, args.live)
    firecrawl_enabled = cast(bool, args.firecrawl_on_budget_exhaustion)
    firecrawl_credit_cap = cast(int | None, args.firecrawl_credit_cap)
    firecrawl_run_id = cast(str | None, args.firecrawl_run_id)
    firecrawl_artifact_dir = cast(Path | None, args.firecrawl_artifact_dir)
    firecrawl_attempt_override = cast(int | None, args.firecrawl_max_attempts)
    if courtlistener_only and case_dev_fixture is not None:
        raise CommandError(
            "--case-dev-fixture cannot be combined with --courtlistener-only"
        )
    if not courtlistener_only and not live and case_dev_fixture is None:
        raise CommandError(
            "offline Case.dev-first resolution requires --case-dev-fixture; "
            "otherwise pass --courtlistener-only"
        )
    firecrawl_values_present = any(
        value is not None
        for value in (
            firecrawl_credit_cap,
            firecrawl_run_id,
            firecrawl_artifact_dir,
            firecrawl_attempt_override,
        )
    )
    if firecrawl_enabled:
        if not live:
            raise CommandError("--firecrawl-on-budget-exhaustion requires --live")
        if (
            firecrawl_credit_cap is None
            or firecrawl_run_id is None
            or not firecrawl_run_id.strip()
            or firecrawl_artifact_dir is None
        ):
            raise CommandError(
                "--firecrawl-on-budget-exhaustion requires "
                "--firecrawl-credit-cap, --firecrawl-run-id, and "
                "--firecrawl-artifact-dir"
            )
        if not 1 <= firecrawl_credit_cap <= 45_000:
            raise CommandError("--firecrawl-credit-cap must be between 1 and 45000")
        if firecrawl_attempt_override is not None and firecrawl_attempt_override <= 0:
            raise CommandError("--firecrawl-max-attempts must be positive")
        if source_store.resolve() != cycle_store.resolve():
            raise CommandError(
                "Firecrawl opinion fallback currently requires --source-store "
                "and --cycle-store to identify the same cycle store"
            )
    else:
        if firecrawl_values_present:
            raise CommandError(
                "Firecrawl fallback options require --firecrawl-on-budget-exhaustion"
            )
    try:
        snapshots = (
            read_verified_priority_dedupe_snapshots(
                prior_paths,
                expected_manifest_sha256=prior_hashes,
            )
            if prior_paths or prior_hashes
            else ()
        )
        prior_candidate_ids = frozenset(
            candidate_id
            for snapshot in snapshots
            for candidate_id in snapshot.candidate_ids
        )
        prior_commitment = (
            hashlib.sha256(
                json.dumps(
                    [
                        {
                            "manifest_sha256": snapshot.manifest_sha256,
                            "cycle_hash": snapshot.cycle_hash,
                            "batch_digest": snapshot.batch_digest,
                            "candidate_set_sha256": snapshot.candidate_set_sha256,
                        }
                        for snapshot in snapshots
                    ],
                    sort_keys=True,
                    separators=(",", ":"),
                ).encode()
            ).hexdigest()
            if snapshots
            else None
        )
        courtlistener_client, budget = _batch_002_client(args, require_token=live)
        if courtlistener_only:
            case_dev_client: CaseDevClient | None = None
        elif case_dev_fixture is not None:
            case_dev_client = CaseDevClient(
                config=CaseDevConfig.from_env(),
                transport=CaseDevFixtureTransport.from_jsonl(case_dev_fixture),
                max_retries=0,
            )
        else:
            case_dev_client = CaseDevClient(
                config=CaseDevConfig.from_env(require_api_key=True),
                max_retries=0,
            )
        firecrawl_resolver: BudgetedOpinionRecapFirecrawlResolver | None = None
        if firecrawl_enabled:
            assert (
                firecrawl_credit_cap is not None
                and firecrawl_run_id is not None
                and firecrawl_artifact_dir is not None
            )
            firecrawl_resolver = BudgetedOpinionRecapFirecrawlResolver(
                store_path=cycle_store,
                source_batch_id=source_batch_id,
                output_batch_id=batch_id,
                run_id=firecrawl_run_id,
                artifact_dir=firecrawl_artifact_dir,
                source=OpinionRecapFirecrawlPageSource(
                    FirecrawlConfig.from_env(proxy="basic")
                ),
                credit_cap=firecrawl_credit_cap,
                max_attempts=firecrawl_attempt_override or 3,
                max_pages_per_lead=cast(int, args.max_pages_per_lead),
            )
        summary = resolve_opinion_recap_batch(
            source_store_path=source_store,
            source_batch_id=source_batch_id,
            journal_path=resolver_journal,
            output_store_path=cycle_store,
            output_batch_id=batch_id,
            case_dev_client=case_dev_client,
            courtlistener_client=courtlistener_client,
            firecrawl_resolver=firecrawl_resolver,
            prior_candidate_ids=prior_candidate_ids,
            prior_snapshot_commitment_sha256=prior_commitment,
            max_pages_per_lead=cast(int, args.max_pages_per_lead),
            case_name_similarity_threshold=cast(
                float, args.case_name_similarity_threshold
            ),
        )
    except (
        CaseDevClientError,
        CourtListenerClientError,
        CourtListenerRequestBudgetError,
        CycleAcquisitionStoreError,
        FirecrawlArtifactError,
        FirecrawlCircuitOpenError,
        FirecrawlError,
        OpinionRecapResolutionError,
        RecapApiBatchDriverError,
        OSError,
        ValueError,
    ) as exc:
        raise CommandError(str(exc)) from exc
    record = {
        **summary.to_record(),
        "prior_snapshot_count": len(snapshots),
        "prior_candidate_count": len(prior_candidate_ids),
        "prior_snapshot_commitment_sha256": prior_commitment,
        **_batch_002_rate_evidence(args, courtlistener_client, budget),
    }
    summary_output = cast(Path | None, args.summary_output)
    if summary_output is not None:
        _write_json(summary_output, record)
    print(json.dumps(record, sort_keys=True))
    return 0


def _cmd_batch_002_observe(args: argparse.Namespace) -> int:
    cycle_store = cast(Path, args.cycle_store)
    batch_id = cast(str, args.batch_id)
    anchor = _iso_date_argument(
        cast(str, args.eligibility_anchor), "--eligibility-anchor"
    )
    limit = cast(int | None, args.limit)
    refresh_reason_codes = tuple(cast(list[str], args.refresh_reason_code))
    revalidate_candidate_ids = tuple(cast(list[str], args.revalidate_candidate_id))
    refresh_campaign_cutoff = cast(str | None, args.refresh_campaign_cutoff)
    if limit is not None and limit <= 0:
        raise CommandError("--limit must be a positive integer")
    if (
        refresh_reason_codes or revalidate_candidate_ids
    ) and refresh_campaign_cutoff is None:
        raise CommandError(
            "--refresh-campaign-cutoff is required with refresh/revalidation"
        )
    try:
        with CycleAcquisitionStore(cycle_store) as store:
            _validate_frozen_screening_policy(
                policy=store.cycle_policy,
                anchor=anchor,
            )
            store.batch_digest(batch_id)
    except (CycleAcquisitionStoreError, KeyError, ValueError) as exc:
        raise CommandError(str(exc)) from exc
    client, budget = _batch_002_client(args, require_token=True)
    pacer = _batch_002_observe_pacer(args)
    try:
        with CycleAcquisitionStore(cycle_store) as store:
            # Repeat after constructing the provider client so no future command
            # refactor can introduce a time-of-check/time-of-use gap.
            _validate_frozen_screening_policy(
                policy=store.cycle_policy,
                anchor=anchor,
            )
            tally = run_observe(
                store,
                batch_id=batch_id,
                client=client,
                eligibility_anchor=anchor,
                pacer=pacer,
                limit=limit,
                refresh_reason_codes=refresh_reason_codes,
                revalidate_candidate_ids=revalidate_candidate_ids,
                refresh_campaign_cutoff=refresh_campaign_cutoff,
            )
    except (
        CycleAcquisitionStoreError,
        CourtListenerRequestBudgetError,
        RecapApiBatchDriverError,
        RecapApiDiscoveryError,
        KeyError,
        ValueError,
    ) as exc:
        raise CommandError(str(exc)) from exc
    record = {
        **tally.to_record(),
        "refresh_reason_codes": list(refresh_reason_codes),
        "revalidate_candidate_ids": list(revalidate_candidate_ids),
        "refresh_campaign_cutoff": refresh_campaign_cutoff,
        **_batch_002_rate_evidence(args, client, budget),
    }
    summary_output = cast(Path | None, args.summary_output)
    if summary_output is not None:
        _write_json(summary_output, record)
    print(json.dumps(record, sort_keys=True))
    return 0


def _cmd_batch_002_observe_firecrawl(args: argparse.Namespace) -> int:
    cycle_store = cast(Path, args.cycle_store)
    batch_id = cast(str, args.batch_id)
    run_id = cast(str, args.run_id)
    raw_artifact_dir = cast(Path, args.raw_artifact_dir)
    anchor = _iso_date_argument(
        cast(str, args.eligibility_anchor),
        "--eligibility-anchor",
    )
    candidate_ids = tuple(cast(list[str], args.candidate_id))
    limit = cast(int | None, args.limit)
    credit_cap = cast(int, args.credit_cap)
    workers = cast(int, args.workers)
    max_pages = cast(int, args.max_pages_per_docket)
    max_attempts = cast(int, args.max_attempts_per_page)
    breaker_threshold = cast(int, args.provider_breaker_threshold)
    proxy = cast(FirecrawlProxy, args.proxy)
    force_browser = cast(bool, args.force_browser)
    fixture = cast(Path | None, args.firecrawl_fixture)
    live = cast(bool, args.live_firecrawl)

    if credit_cap <= 0:
        raise CommandError("--credit-cap must be positive")
    if credit_cap > 45_000:
        raise CommandError("--credit-cap must not exceed 45000")
    if max_pages <= 0:
        raise CommandError("--max-pages-per-docket must be positive")
    if max_attempts <= 0:
        raise CommandError("--max-attempts-per-page must be positive")
    if breaker_threshold <= 0:
        raise CommandError("--provider-breaker-threshold must be positive")
    if limit is not None and limit <= 0:
        raise CommandError("--limit must be positive")

    preflight_config = FirecrawlConfig(
        api_key="preflight-only",
        proxy=proxy,
        force_browser=force_browser,
    )
    try:
        with CycleAcquisitionStore(cycle_store) as store:
            _validate_frozen_screening_policy(
                policy=store.cycle_policy,
                anchor=anchor,
            )
            plan_frozen_firecrawl_observation(
                store,
                batch_id=batch_id,
                run_id=run_id,
                eligibility_anchor=anchor,
                artifact_dir=raw_artifact_dir,
                max_pages_per_docket=max_pages,
                max_attempts_per_page=max_attempts,
                provider_breaker_threshold=breaker_threshold,
                max_workers=workers,
                requested_candidate_ids=candidate_ids,
                limit=limit,
                firecrawl_proxy=preflight_config.proxy,
                firecrawl_force_browser=preflight_config.force_browser,
                reserved_credits_per_attempt=(preflight_config.max_credits_per_scrape),
            )
    except (
        CycleAcquisitionStoreError,
        FrozenBatchFirecrawlObservationError,
        KeyError,
        OSError,
        ValueError,
    ) as exc:
        raise CommandError(str(exc)) from exc

    try:
        config = (
            FirecrawlConfig.from_env(proxy=proxy, force_browser=force_browser)
            if live
            else FirecrawlConfig(
                api_key="offline-fixture",
                proxy=proxy,
                force_browser=force_browser,
            )
        )
    except (FirecrawlError, ValueError) as exc:
        raise CommandError(str(exc)) from exc
    source = FirecrawlCourtListenerHTMLSource(
        config,
        **(
            {"transport": _firecrawl_fixture_transport(fixture)}
            if fixture is not None
            else {}
        ),
    )
    try:
        with CycleAcquisitionStore(cycle_store) as store:
            # Repeat after constructing the provider client so no future command
            # refactor can introduce a time-of-check/time-of-use gap.
            _validate_frozen_screening_policy(
                policy=store.cycle_policy,
                anchor=anchor,
            )
            plan = plan_frozen_firecrawl_observation(
                store,
                batch_id=batch_id,
                run_id=run_id,
                eligibility_anchor=anchor,
                artifact_dir=raw_artifact_dir,
                max_pages_per_docket=max_pages,
                max_attempts_per_page=max_attempts,
                provider_breaker_threshold=breaker_threshold,
                max_workers=workers,
                requested_candidate_ids=candidate_ids,
                limit=limit,
                firecrawl_proxy=config.proxy,
                firecrawl_force_browser=config.force_browser,
                reserved_credits_per_attempt=config.max_credits_per_scrape,
            )
            store.ensure_firecrawl_run(
                run_id,
                batch_id=batch_id,
                config=plan.run_config,
                credit_cap=credit_cap,
                reserved_credits_per_attempt=config.max_credits_per_scrape,
            )
            tally = run_frozen_firecrawl_observation(
                store,
                batch_id=batch_id,
                scheduler=BudgetedFirecrawlScheduler(
                    store=store,
                    source=source,
                    run_id=run_id,
                    artifact_dir=raw_artifact_dir,
                    max_attempts=max_attempts,
                    provider_5xx_circuit_threshold=breaker_threshold,
                    max_workers=workers,
                ),
                plan=plan,
                eligibility_anchor=anchor,
                max_pages_per_docket=max_pages,
            )
    except (
        CycleAcquisitionStoreError,
        FirecrawlArtifactError,
        FirecrawlCircuitOpenError,
        FirecrawlError,
        FrozenBatchFirecrawlObservationError,
        KeyError,
        OSError,
        ValueError,
    ) as exc:
        raise CommandError(str(exc)) from exc

    record = {
        **tally.to_record(),
        "batch_id": batch_id,
        "run_id": run_id,
        "eligibility_anchor": anchor.isoformat(),
        "requested_candidate_ids": list(candidate_ids),
        "live_firecrawl": live,
        "firecrawl_activity_executed": _firecrawl_metered_activity_executed(
            live=live,
            summary=tally.credit_summary,
        ),
        "pacer_activity_executed": False,
    }
    summary_output = cast(Path | None, args.summary_output)
    if summary_output is not None:
        _write_json(summary_output, record)
    print(json.dumps(record, sort_keys=True))
    return 0


def _cmd_batch_002_seed(args: argparse.Namespace) -> int:
    source_store = cast(Path, args.source_store)
    cycle_store = cast(Path, args.cycle_store)
    batch_id = cast(str, args.batch_id)
    source_batch_id = cast(str | None, args.source_batch_id)
    try:
        leads = read_batch_001_enrichment_failure_leads(
            source_store, source_batch_id=source_batch_id
        )
        with CycleAcquisitionStore(cycle_store) as store:
            result = seed_batch_001_leads(store, batch_id=batch_id, leads=leads)
    except (
        CycleAcquisitionStoreError,
        RecapApiBatchDriverError,
        KeyError,
        ValueError,
    ) as exc:
        raise CommandError(str(exc)) from exc
    record = result.to_record()
