def _cmd_batch_002_ranked_selection(args: argparse.Namespace) -> int:
    source_store = cast(Path, args.source_store)
    source_batch_id = cast(str, args.source_batch_id)
    source_projection = cast(Path, args.source_projection)
    ranked_path = cast(Path, args.ranked)
    terminal_exclusion_path = cast(Path, args.failures)
    enrichment_run_card = cast(Path, args.enrichment_run_card)
    expected_enrichment_run_card_sha256 = cast(
        str, args.expected_enrichment_run_card_sha256
    )
    cycle_store = cast(Path, args.cycle_store)
    batch_id = cast(str, args.batch_id)
    anchor = _iso_date_argument(
        cast(str, args.eligibility_anchor), "--eligibility-anchor"
    )
    top_n = cast(int | None, getattr(args, "top_n", None))
    selected_docket_ids = cast(
        Sequence[str] | None,
        getattr(args, "docket_id", None),
    )
    unresolved_manifest = cast(
        Path | None,
        getattr(args, "sealed_unresolved_manifest", None),
    )
    terminal_manifest = cast(
        Path | None,
        getattr(args, "sealed_terminal_manifest", None),
    )
    expected_unresolved_sha256 = cast(
        str | None,
        getattr(args, "expected_sealed_unresolved_manifest_sha256", None),
    )
    expected_terminal_sha256 = cast(
        str | None,
        getattr(args, "expected_sealed_terminal_manifest_sha256", None),
    )
    recovery_seal_card = cast(
        Path | None,
        getattr(args, "recovery_seal_run_card", None),
    )
    expected_recovery_seal_sha256 = cast(
        str | None,
        getattr(args, "expected_recovery_seal_run_card_sha256", None),
    )
    recovery_source_store = cast(
        Path | None,
        getattr(args, "recovery_source_cycle_store", None),
    )
    recovery_partition = (
        "unresolved"
        if unresolved_manifest is not None
        else ("terminal" if terminal_manifest is not None else None)
    )
    partition_manifest = unresolved_manifest or terminal_manifest
    expected_partition_sha256 = (
        expected_unresolved_sha256
        if recovery_partition == "unresolved"
        else expected_terminal_sha256
    )
    recovery_values = (
        partition_manifest,
        expected_partition_sha256,
        recovery_seal_card,
        expected_recovery_seal_sha256,
        recovery_source_store,
    )
    recovery_mode = recovery_partition is not None
    if recovery_mode != all(value is not None for value in recovery_values):
        raise CommandError(
            "the sealed partition manifest, its matching expected SHA-256, "
            "--recovery-seal-run-card, its expected SHA-256, and "
            "--recovery-source-cycle-store are required together"
        )
    if unresolved_manifest is None and expected_unresolved_sha256 is not None:
        raise CommandError(
            "--expected-sealed-unresolved-manifest-sha256 requires its manifest"
        )
    if terminal_manifest is None and expected_terminal_sha256 is not None:
        raise CommandError(
            "--expected-sealed-terminal-manifest-sha256 requires its manifest"
        )
    if recovery_mode and top_n is not None:
        raise CommandError(
            "sealed recovery authority is only valid for subset selection"
        )
    if recovery_mode and (
        cast(Path, recovery_source_store).resolve(strict=False)
        == cycle_store.resolve(strict=False)
    ):
        raise CommandError(
            "recovery --cycle-store must be a fresh store distinct from the "
            "budget-exhausted source store"
        )
    if recovery_mode:
        try:
            if cast(Path, recovery_source_store).samefile(cycle_store):
                raise CommandError(
                    "recovery --cycle-store hard-links the budget-exhausted "
                    "source store; a fresh same-policy store is required"
                )
        except FileNotFoundError:
            # The target store's required-existence gate below reports absence;
            # without both files, there is no inode alias to compare here.
            pass
        except OSError as exc:
            raise CommandError(f"cannot verify recovery store identity: {exc}") from exc
    page_size = cast(int, args.page_size)
    run_card_output = cast(Path, args.run_card_output)
    summary_output = cast(Path | None, args.summary_output)
    _validate_ranked_handoff_paths(
        protected_paths=(
            source_store,
            source_projection,
            ranked_path,
            terminal_exclusion_path,
            enrichment_run_card,
            cycle_store,
            *(
                (
                    cast(Path, partition_manifest),
                    cast(Path, recovery_seal_card),
                    cast(Path, recovery_source_store),
                )
                if recovery_mode
                else ()
            ),
        ),
        writable_paths=(
            run_card_output,
            *((summary_output,) if summary_output is not None else ()),
        ),
        sqlite_paths=(
            source_store,
            cycle_store,
            *((cast(Path, recovery_source_store),) if recovery_mode else ()),
        ),
        context="ranked Case.dev selection",
    )
    if not cycle_store.is_file():
        raise CommandError(
            "--cycle-store must be an existing current-cycle acquisition store"
        )
    try:
        source = read_saturated_direct_search_leads(
            source_store,
            source_batch_id=source_batch_id,
        )
        recovery_authority: Mapping[str, object] | None = None
        if recovery_mode:
            seal_card_bytes = cast(Path, recovery_seal_card).read_bytes()
            if (
                hashlib.sha256(seal_card_bytes).hexdigest()
                != expected_recovery_seal_sha256
            ):
                raise RankedFirecrawlRecoveryError(
                    "recovery seal run card SHA-256 does not match"
                )
            seal_card = _read_json_object(cast(Path, recovery_seal_card))
            original_selection_card_value = seal_card.get(
                "ranked_selection_run_card_path"
            )
            original_selection_sha256 = seal_card.get(
                "ranked_selection_run_card_sha256"
            )
            source_firecrawl_batch = seal_card.get("source_batch_id")
            source_candidate_count = seal_card.get("source_candidate_count")
            if (
                not isinstance(original_selection_card_value, str)
                or not isinstance(original_selection_sha256, str)
                or not isinstance(source_firecrawl_batch, str)
                or type(source_candidate_count) is not int
            ):
                raise RankedFirecrawlRecoveryError(
                    "recovery seal lacks original ranked-selection authority"
                )
            with CycleAcquisitionStore(
                cast(Path, recovery_source_store), read_only=True
            ) as recovery_store:
                authenticated_parent_batch_id = authenticated_handoff_parent_batch_id(
                    recovery_store,
                    source_firecrawl_batch,
                )
                original_records = list(
                    verify_authenticated_ranked_firecrawl_handoff(
                        store=recovery_store,
                        parent_batch_id=authenticated_parent_batch_id,
                        ranked_path=ranked_path,
                        selection_run_card_path=Path(original_selection_card_value),
                        expected_selection_run_card_sha256=(original_selection_sha256),
                        max_candidates=source_candidate_count,
                    )
                )
                verify_authenticated_acquisition_slice(
                    store=recovery_store,
                    acquisition_batch_id=source_firecrawl_batch,
                    authenticated_parent_batch_id=authenticated_parent_batch_id,
                    records=original_records,
                )
                verified_recovery = verify_recovery_partition(
                    store=recovery_store,
                    records=original_records,
                    ranked_path=ranked_path,
                    seal_run_card_path=cast(Path, recovery_seal_card),
                    expected_seal_run_card_sha256=cast(
                        str, expected_recovery_seal_sha256
                    ),
                    partition_manifest_path=cast(Path, partition_manifest),
                    expected_partition_manifest_sha256=cast(
                        str, expected_partition_sha256
                    ),
                    partition=recovery_partition,
                )
            if (
                recovery_partition == "unresolved"
                and verified_recovery.authority.get("firecrawl_reacquisition_allowed")
                is not True
            ):
                raise RankedFirecrawlRecoveryError(
                    "zero-cap unresolved recovery is not authorized for "
                    "subset materialization"
                )
            selected_docket_ids = verified_recovery.docket_ids
            recovery_authority = verified_recovery.authority
        selection = verify_case_dev_ranked_selection(
            source=source,
            source_store_path=source_store,
            source_projection_path=source_projection,
            ranked_path=ranked_path,
            terminal_exclusion_path=terminal_exclusion_path,
            enrichment_run_card_path=enrichment_run_card,
            expected_enrichment_run_card_sha256=(expected_enrichment_run_card_sha256),
            top_n=top_n,
            selected_docket_ids=selected_docket_ids,
        )
        with CycleAcquisitionStore(cycle_store) as store:
            _validate_frozen_screening_policy(
                policy=store.cycle_policy,
                anchor=anchor,
            )
            target_cycle_hash = store.cycle_hash
        if (
            recovery_authority is not None
            and recovery_authority.get("source_cycle_hash") != target_cycle_hash
        ):
            raise RankedFirecrawlRecoveryError(
                "fresh recovery store does not use the sealed source cycle policy"
            )
        plan = build_case_dev_ranked_target_plan(
            batch_id=batch_id,
            target_cycle_hash=target_cycle_hash,
            selection=selection,
            page_size=page_size,
            recovery_authority=recovery_authority,
        )
        frozen_run_card = plan.run_card_record()
        if run_card_output.exists():
            existing = _read_json_object(run_card_output)
            if existing != frozen_run_card:
                raise RecapApiBatchDriverError(
                    "existing ranked-selection run card does not match this invocation"
                )
        with CycleAcquisitionStore(cycle_store) as store:
            result = seed_case_dev_ranked_selection(
                store,
                plan=plan,
                page_size=page_size,
            )
        if result.run_card_record() != frozen_run_card:
            raise RecapApiBatchDriverError(
                "materialized ranked selection differs from its frozen plan"
            )
        if not run_card_output.exists():
            _write_json(run_card_output, frozen_run_card)
    except (
        CycleAcquisitionStoreError,
        RecapApiBatchDriverError,
        KeyError,
        OSError,
        ValueError,
    ) as exc:
        raise CommandError(str(exc)) from exc
    record = result.to_record()
    if summary_output is not None:
        _write_json(summary_output, record)
    print(json.dumps(record, sort_keys=True))
    return 0


def _cmd_batch_002_provisional_frontier(args: argparse.Namespace) -> int:
    source_store = cast(Path, args.source_store)
    source_batch_id = cast(str, args.source_batch_id)
    source_projection = cast(Path, args.source_projection)
    progress_config = cast(Path, args.progress_config)
    expected_progress_config_sha256 = cast(str, args.expected_progress_config_sha256)
    progress_path = cast(Path, args.progress)
    expected_progress_sha256 = cast(str, args.expected_progress_sha256)
    cycle_store = cast(Path, args.cycle_store)
    batch_id = cast(str, args.batch_id)
    anchor = _iso_date_argument(
        cast(str, args.eligibility_anchor), "--eligibility-anchor"
    )
    page_size = cast(int, args.page_size)
    ranked_output = cast(Path, args.ranked_output)
    run_card_output = cast(Path, args.run_card_output)
    summary_output = cast(Path | None, args.summary_output)
    _validate_ranked_handoff_paths(
        protected_paths=(
            source_store,
            source_projection,
            progress_config,
            progress_path,
            cycle_store,
        ),
        writable_paths=(
            ranked_output,
            run_card_output,
            *((summary_output,) if summary_output is not None else ()),
        ),
        sqlite_paths=(source_store, cycle_store),
        context="provisional Case.dev frontier",
    )
    if not cycle_store.is_file():
        raise CommandError(
            "--cycle-store must be an existing current-cycle acquisition store"
        )
    try:
        source = read_saturated_direct_search_leads(
            source_store,
            source_batch_id=source_batch_id,
        )
        frontier = verify_case_dev_provisional_frontier(
            source=source,
            source_store_path=source_store,
            source_projection_path=source_projection,
            progress_config_path=progress_config,
            progress_path=progress_path,
            expected_progress_config_sha256=expected_progress_config_sha256,
            expected_progress_sha256=expected_progress_sha256,
        )
        ranked_records = ranked_records_for_provisional_frontier(frontier)
        ranked_bytes = _jsonl_bytes(ranked_records)
        ranked_output_sha256 = hashlib.sha256(ranked_bytes).hexdigest()
        if ranked_output.exists():
            if ranked_output.read_bytes() != ranked_bytes:
                raise RecapApiBatchDriverError(
                    "existing provisional ranked output differs from authenticated "
                    "progress"
                )
        with CycleAcquisitionStore(cycle_store) as store:
            _validate_frozen_screening_policy(policy=store.cycle_policy, anchor=anchor)
            planned_run_card = provisional_frontier_run_card_record(
                frontier=frontier,
                batch_id=batch_id,
                target_cycle_hash=store.cycle_hash,
                target_batch_digest=provisional_frontier_batch_digest(
                    frontier=frontier,
                    page_size=page_size,
                ),
            )
            frozen_run_card = {
                **planned_run_card,
                "ranked_path": str(ranked_output),
                "ranked_output_sha256": ranked_output_sha256,
            }
            if run_card_output.exists() and (
                _read_json_object(run_card_output) != frozen_run_card
            ):
                raise RecapApiBatchDriverError(
                    "existing provisional-frontier run card does not match this "
                    "invocation"
                )
            if not ranked_output.exists():
                ranked_output.parent.mkdir(parents=True, exist_ok=True)
                ranked_output.write_bytes(ranked_bytes)
            # Every mutation below is identity-bound and resumable. If a page or
            # final run-card write is interrupted, the same plan resumes exactly.
            result = materialize_case_dev_provisional_frontier(
                store,
                batch_id=batch_id,
                frontier=frontier,
                page_size=page_size,
            )
            if (
                result.run_card_record() != planned_run_card
                or result.target_batch_digest != planned_run_card["target_batch_digest"]
            ):
                raise RecapApiBatchDriverError(
                    "materialized provisional batch changed its planned identity"
                )
        if not run_card_output.exists():
            _write_json(run_card_output, frozen_run_card)
    except (
        CycleAcquisitionStoreError,
        RecapApiBatchDriverError,
        KeyError,
        OSError,
        ValueError,
    ) as exc:
        raise CommandError(str(exc)) from exc
    record = {
        **result.to_record(),
        "ranked_path": str(ranked_output),
        "ranked_output_sha256": ranked_output_sha256,
    }
    if summary_output is not None:
        _write_json(summary_output, record)
    print(json.dumps(record, sort_keys=True))
    return 0


def _validate_ranked_handoff_paths(
    *,
    protected_paths: Sequence[Path],
    writable_paths: Sequence[Path],
    sqlite_paths: Sequence[Path],
    context: str,
) -> None:
    """Reject writable aliases before checkpoint or cycle-store mutation."""

    reserved_paths = list(protected_paths)
    for store_path in sqlite_paths:
        reserved_paths.extend(
            Path(f"{store_path}{suffix}")
            for suffix in (".lock", "-wal", "-shm", "-journal")
        )
    try:
        protected = tuple((path, path.resolve(strict=False)) for path in reserved_paths)
        writable = tuple((path, path.resolve(strict=False)) for path in writable_paths)
    except OSError as exc:
        raise CommandError(f"cannot resolve {context} paths: {exc}") from exc

    seen: dict[Path, Path] = {}
    for path, identity in writable:
        previous = seen.get(identity)
        if previous is not None:
            raise CommandError(
                f"{context} writable outputs alias: {previous} and {path}"
            )
        seen[identity] = path
        if path.is_symlink():
            raise CommandError(f"{context} writable output is a symlink: {path}")
        if path.exists():
            try:
                metadata = path.stat()
            except OSError as exc:
                raise CommandError(
                    f"cannot inspect {context} writable output {path}: {exc}"
                ) from exc
            if not path.is_file() or metadata.st_nlink != 1:
                raise CommandError(
                    f"{context} writable output is not a singly linked file: {path}"
                )
        for protected_path, protected_identity in protected:
            if identity == protected_identity:
                raise CommandError(
                    f"{context} writable output aliases protected input: "
                    f"{path} and {protected_path}"
                )
            if path.exists() and protected_path.exists():
                try:
                    aliases = path.samefile(protected_path)
                except OSError as exc:
                    raise CommandError(
                        f"cannot inspect {context} path aliases: {exc}"
                    ) from exc
                if aliases:
                    raise CommandError(
                        f"{context} writable output hard-links protected input: "
                        f"{path} and {protected_path}"
                    )


def _cmd_batch_002_snapshot(args: argparse.Namespace) -> int:
    cycle_store = cast(Path, args.cycle_store)
    batch_id = cast(str, args.batch_id)
    snapshot_id = cast(str, args.snapshot_id)
    output_root = cast(Path, args.output_root)
    try:
        with CycleAcquisitionStore(cycle_store) as store:
            cycle_hash = store.cycle_hash
            batch_digest = store.batch_digest(batch_id)
            batch_config = store.batch_config(batch_id)
            if not store.snapshot_is_saturated(batch_id):
                raise SnapshotVerificationError(
                    "batch-002 snapshot requires every discovery term to be "
                    "exhausted before publication"
                )
            stage_commitments: dict[str, object] = {
                "courtlistener_rest_screen_inputs": {
                    "schema_version": (
                        "legalforecast.courtlistener_rest_screen_inputs.v1"
                    )
                }
            }
            if (
                batch_config.get("discovery_mode")
                == DIRECT_SEARCH_PRIORITY_TRANCHE_SCHEMA
            ):
                priority_fields = (
                    "source_batch_id",
                    "source_batch_digest",
                    "source_cycle_hash",
                    "source_candidate_count",
                    "source_candidate_set_sha256",
                    "source_candidate_id_set_sha256",
                    "source_lineage_commitment_sha256",
                    "ranking_policy_sha256",
                    "tranche_ordinal",
                    "requested_tranche_size",
                    "predecessor_frontier_sha256",
                    "selected_candidate_count",
                    "selected_candidate_set_sha256",
                    "cumulative_selected_count",
                    "deferred_candidate_count",
                    "deferred_candidate_set_sha256",
                    "deferred_frontier_sha256",
                    "chain_terminal",
                    "ranking_frontier_exhausted",
                    "global_source_saturated",
                    "strict_screen_is_sole_eligibility_and_exclusion_authority",
                    "ranking_metadata_visibility",
                )
                stage_commitments["direct_search_priority_tranche"] = {
                    "schema_version": DIRECT_SEARCH_PRIORITY_TRANCHE_SCHEMA,
                    **{
                        field: batch_config[field]
                        for field in priority_fields
                        if field in batch_config
                    },
                }
            snapshot_path = store.export_snapshot(
                output_root,
                snapshot_id=snapshot_id,
                batch_id=batch_id,
                complete=True,
                stage_commitments=stage_commitments,
            )
        manifest = verify_snapshot(
            snapshot_path,
            expected_cycle_hash=cycle_hash,
            expected_batch_digest=batch_digest,
            require_complete=True,
            require_saturated=True,
        )
        if (
            snapshot_firecrawl_screening_source_count(
                manifest,
                require_current=True,
            )
            != 0
        ):
            raise FirecrawlScreeningIdentityError(
                "CourtListener REST snapshot unexpectedly contains Firecrawl "
                "screening sources"
            )
        validate_verified_snapshot_rest_terminal_subset_promotions(
            snapshot_path,
            cast(Mapping[str, object], manifest),
        )
    except (
        CycleAcquisitionStoreError,
        FileExistsError,
        FirecrawlScreeningIdentityError,
        KeyError,
        OSError,
        SnapshotVerificationError,
        ValueError,
    ) as exc:
        raise CommandError(str(exc)) from exc
    record = {
        "schema_version": "legalforecast.batch_002_snapshot_result.v1",
        "batch_id": batch_id,
        "snapshot_id": snapshot_id,
        "snapshot_path": str(snapshot_path.resolve()),
        "cycle_hash": cycle_hash,
        "batch_digest": batch_digest,
        "verified": True,
        "saturated": manifest.get("saturated") is True,
    }
    summary_output = cast(Path | None, args.summary_output)
    if summary_output is not None:
        _write_json(summary_output, record)
    print(json.dumps(record, sort_keys=True))
    return 0


