def _cmd_init_purchase_ledger(args: argparse.Namespace) -> int:
    """Exclusively initialize or authenticate one pristine purchase ledger."""

    _preflight_approved_purchase_runtime(args)
    output_root = cast(Path, args.output_root)
    purchase_policy_path = cast(Path, args.purchase_policy)
    cohort_policy_path = cast(Path, args.cohort_policy)
    ledger_path = cast(Path, args.purchase_ledger)
    receipt_path = _acquisition_path(
        args,
        "initialization_receipt_output",
        output_root / "purchase-ledger-initialization.json",
    )
    run_card_path = _acquisition_path(
        args,
        "run_card_output",
        output_root / "run-cards/init-purchase-ledger.json",
    )
    log_path = _acquisition_path(
        args,
        "log_output",
        output_root / "logs/init-purchase-ledger.jsonl",
    )
    input_paths = (purchase_policy_path, cohort_policy_path)
    output_paths = (ledger_path, receipt_path)
    zero_activity: JsonRecord = {
        "provider_activity_requested": False,
        "provider_activity_executed": False,
        "pacer_paid_activity_requested": False,
        "pacer_paid_activity_executed": False,
        "paid_activity_requested": False,
        "paid_activity_executed": False,
    }
    try:
        _validate_init_purchase_ledger_no_mutation_paths(
            output_root=output_root,
            ledger_path=ledger_path,
            purchase_policy_path=purchase_policy_path,
            cohort_policy_path=cohort_policy_path,
            receipt_path=receipt_path,
            run_card_path=run_card_path,
            log_path=log_path,
        )
    except (OSError, ValueError) as exc:
        # These paths carry the failure record itself. If they are unsafe, do
        # not touch them in an attempt to report that they are unsafe.
        raise CommandError(str(exc)) from exc
    try:
        purchase_policy = verify_case_dev_purchase_policy(
            _read_json_object(purchase_policy_path)
        )
        require_approved_case_dev_purchase_policy(
            purchase_policy,
            controlled_private_root=cast(Path | None, args.controlled_private_root),
        )
        verify_case_dev_purchase_policy_cohort_binding(
            purchase_policy,
            _read_json_object(cohort_policy_path),
        )
        _validate_init_purchase_ledger_paths(
            ledger_path=ledger_path,
            canonical_ledger_path=purchase_policy.canonical_ledger_path,
            purchase_policy_path=purchase_policy_path,
            cohort_policy_path=cohort_policy_path,
            receipt_path=receipt_path,
            run_card_path=run_card_path,
            log_path=log_path,
        )
    except (
        CaseDevPurchaseLedgerError,
        CaseDevPurchasePolicyError,
        OSError,
        UnicodeError,
        ValueError,
    ) as exc:
        _write_acquisition_failure(
            args,
            stage="init-purchase-ledger",
            input_paths=input_paths,
            output_paths=output_paths,
            reason=str(exc),
            paid_activity_requested=False,
            paid_activity_executed=False,
            extra=zero_activity,
        )
        raise CommandError(str(exc)) from exc

    if _acquisition_dry_run(args):
        _write_acquisition_completion(
            args,
            stage="init-purchase-ledger",
            input_paths=input_paths,
            output_paths=output_paths,
            record_count=0,
            dry_run=True,
            paid_activity_requested=False,
            paid_activity_executed=False,
            extra={
                **zero_activity,
                "canonical_ledger_path": str(ledger_path),
                "purchase_policy_sha256": purchase_policy.policy_sha256,
                "cohort_policy_sha256": purchase_policy.cohort_policy_sha256,
                "initialized_or_verified": False,
            },
        )
        return 0

    try:
        if receipt_path.exists() or receipt_path.is_symlink():
            if not cast(bool, args.resume):
                raise CaseDevPurchaseLedgerError(
                    "initialization receipt already exists and --no-resume "
                    "forbids verification"
                )
            receipt = verify_case_dev_purchase_journal_initialization(
                ledger_path,
                policy=purchase_policy,
                receipt_path=receipt_path,
                purchase_policy_file_sha256=_path_sha256(purchase_policy_path),
                cohort_policy_file_sha256=_path_sha256(cohort_policy_path),
                controlled_private_root=cast(Path, args.controlled_private_root),
            )
        else:
            receipt = initialize_case_dev_purchase_journal(
                ledger_path,
                policy=purchase_policy,
                receipt_path=receipt_path,
                purchase_policy_file_sha256=_path_sha256(purchase_policy_path),
                cohort_policy_file_sha256=_path_sha256(cohort_policy_path),
                initialized_at=_iso_datetime(datetime.now(UTC)),
                controlled_private_root=cast(Path, args.controlled_private_root),
            )
    except (
        CaseDevPurchaseLedgerError,
        CaseDevPurchasePolicyError,
        OSError,
        sqlite3.Error,
        UnicodeError,
        ValueError,
    ) as exc:
        _write_acquisition_failure(
            args,
            stage="init-purchase-ledger",
            input_paths=input_paths,
            output_paths=output_paths,
            reason=str(exc),
            paid_activity_requested=False,
            paid_activity_executed=False,
            extra=zero_activity,
        )
        raise CommandError(str(exc)) from exc

    try:
        _write_acquisition_completion(
            args,
            stage="init-purchase-ledger",
            input_paths=input_paths,
            output_paths=output_paths,
            record_count=1,
            dry_run=False,
            paid_activity_requested=False,
            paid_activity_executed=False,
            extra={**receipt, **zero_activity},
        )
    except (OSError, ValueError) as exc:
        raise CommandError(
            "purchase ledger initialization is durable, but completion "
            f"artifact publication failed: {exc}"
        ) from exc
    return 0


def _validate_init_purchase_ledger_no_mutation_paths(
    *,
    output_root: Path,
    ledger_path: Path,
    purchase_policy_path: Path,
    cohort_policy_path: Path,
    receipt_path: Path,
    run_card_path: Path,
    log_path: Path,
) -> None:
    named = {
        "purchase policy": purchase_policy_path,
        "cohort policy": cohort_policy_path,
        "initialization receipt": receipt_path,
        "run card": run_card_path,
        "stage log": log_path,
    }
    ledger = ledger_path.resolve(strict=False)
    output = output_root.resolve(strict=False)
    if output == ledger or ledger in output.parents:
        raise ValueError(
            "--output-root must not equal or descend from --purchase-ledger"
        )
    reserved = tuple(
        path.resolve(strict=False)
        for path in (
            ledger_path,
            Path(f"{ledger_path}.lock"),
            Path(f"{ledger_path}-wal"),
            Path(f"{ledger_path}-shm"),
            Path(f"{ledger_path}-journal"),
        )
    )
    resolved: dict[Path, str] = {}
    existing: list[tuple[str, Path]] = []
    for label, path in named.items():
        identity = path.resolve(strict=False)
        for reserved_path in reserved:
            if (
                identity == reserved_path
                or identity in reserved_path.parents
                or reserved_path in identity.parents
            ):
                raise ValueError(
                    "init-purchase-ledger path conflicts with reserved ledger "
                    f"namespace: {label}: {path}"
                )
        previous = resolved.get(identity)
        if previous is not None:
            raise ValueError(
                f"init-purchase-ledger writable paths alias: {previous} and {label}"
            )
        resolved[identity] = label
        if path.is_symlink():
            raise ValueError(
                f"init-purchase-ledger writable path must not be a symlink: "
                f"{label}: {path}"
            )
        if path.exists():
            metadata = path.stat()
            if not path.is_file() or metadata.st_nlink != 1:
                raise ValueError(
                    "init-purchase-ledger writable path must be a singly linked "
                    f"regular file: {label}: {path}"
                )
            existing.append((label, path))
    for index, (left_label, left_path) in enumerate(existing):
        for right_label, right_path in existing[index + 1 :]:
            if left_path.samefile(right_path):
                raise ValueError(
                    f"init-purchase-ledger writable paths alias: {left_label} and "
                    f"{right_label}"
                )


def _validate_init_purchase_ledger_paths(
    *,
    ledger_path: Path,
    canonical_ledger_path: Path,
    purchase_policy_path: Path,
    cohort_policy_path: Path,
    receipt_path: Path,
    run_card_path: Path,
    log_path: Path,
) -> None:
    if not ledger_path.is_absolute() or ledger_path != canonical_ledger_path:
        raise CaseDevPurchasePolicyError(
            "purchase ledger path conflicts with canonical policy locator"
        )
    named_paths = {
        "purchase ledger": ledger_path,
        "purchase policy": purchase_policy_path,
        "cohort policy": cohort_policy_path,
        "initialization receipt": receipt_path,
        "run card": run_card_path,
        "stage log": log_path,
    }
    resolved: dict[Path, str] = {}
    for label, path in named_paths.items():
        identity = path.resolve()
        previous = resolved.get(identity)
        if previous is not None:
            raise CaseDevPurchaseLedgerError(
                f"init-purchase-ledger paths alias: {previous} and {label}"
            )
        resolved[identity] = label
    existing = [(label, path) for label, path in named_paths.items() if path.exists()]
    for index, (left_label, left_path) in enumerate(existing):
        left_stat = left_path.stat()
        if (
            left_label
            in {
                "purchase ledger",
                "initialization receipt",
                "run card",
                "stage log",
            }
            and left_stat.st_nlink > 1
        ):
            raise CaseDevPurchaseLedgerError(
                f"{left_label} must not be hard-linked: {left_path}"
            )
        for right_label, right_path in existing[index + 1 :]:
            if left_path.samefile(right_path):
                raise CaseDevPurchaseLedgerError(
                    f"init-purchase-ledger paths alias: {left_label} and {right_label}"
                )


def _cmd_build_clearance_replacement_frontier(args: argparse.Namespace) -> int:
    projection_path = cast(Path, args.projection)
    initial_selection_path = cast(Path, args.initial_selection)
    candidate_frontier_path = cast(Path, args.candidate_frontier)
    candidate_selection_path = cast(Path, args.candidate_selection)
    try:
        purchase_artifact = _read_json_object(cast(Path, args.purchase_policy))
        purchase_policy = verify_case_dev_purchase_policy(purchase_artifact)
        projection_bytes = read_unique_regular_file(projection_path)
        initial_selection_bytes = read_unique_regular_file(initial_selection_path)
        candidate_selection_bytes = read_unique_regular_file(candidate_selection_path)
        candidate_frontier_bytes = read_unique_regular_file(candidate_frontier_path)
        initial_candidate_ids = _replacement_initial_candidate_ids(
            initial_selection_bytes,
            source=initial_selection_path,
        )
        if purchase_policy.has_verified_approval:
            candidate_frontier_artifact = _projection_json_object(
                candidate_frontier_bytes,
                source=candidate_frontier_path,
            )
            candidate_rows = _verify_replacement_initial_selection_lineage(
                initial_candidate_ids=initial_candidate_ids,
                target_frontier_artifact=candidate_frontier_artifact,
                reconciled_selection_bytes=candidate_selection_bytes,
                reconciled_selection_path=candidate_selection_path,
            )
        else:
            candidate_rows = _replacement_frontier_rows(
                candidate_frontier_bytes,
                source=candidate_frontier_path,
            )
        commitments = _replacement_source_commitments(
            cast(Sequence[str], args.source),
            fixed={
                "projection_artifact": projection_bytes,
                "initial_selection": initial_selection_bytes,
                "candidate_frontier": candidate_frontier_bytes,
                "candidate_selection": candidate_selection_bytes,
            },
        )
        artifact = build_replacement_frontier(
            cohort_policy_artifact=_read_json_object(cast(Path, args.cohort_policy)),
            purchase_policy_artifact=purchase_artifact,
            projection_sha256=_bytes_sha256(projection_bytes),
            initial_selected_candidate_ids=initial_candidate_ids,
            candidate_rows=candidate_rows,
            case_mix_max_per_bucket=cast(int | None, args.case_mix_max_per_bucket),
            source_commitments=commitments,
            controlled_private_root=cast(Path, args.controlled_private_root),
        )
        write_replacement_frontier(cast(Path, args.output), artifact)
        broad_allowlist = build_broad_broker_allowlist_plan(
            cohort_policy_artifact=_read_json_object(cast(Path, args.cohort_policy)),
            purchase_policy_artifact=purchase_artifact,
            frontier_artifact=artifact,
            controlled_private_root=cast(Path, args.controlled_private_root),
        )
        _atomic_write_json(
            cast(Path, args.broker_allowlist_plan_output),
            broad_allowlist.to_record(),
        )
    except (
        ClearanceReplacementError,
        OSError,
        UnicodeError,
        ValueError,
    ) as exc:
        raise CommandError(str(exc)) from exc
    print(
        json.dumps(
            {
                "output": str(cast(Path, args.output)),
                "frontier_sha256": artifact["policy_sha256"],
                "candidate_count": artifact["policy"]["candidate_count"],
                "frontier_truncated": artifact["policy"]["frontier_truncated"],
                "broad_allowlist_candidate_count": len(broad_allowlist.case_plans),
            },
            sort_keys=True,
        )
    )
    return 0


def _cmd_plan_clearance_replacements(args: argparse.Namespace) -> int:
    output = cast(Path, args.output)
    replacement_output = cast(Path, args.replacement_budget_plan_output)
    allowlist_output = cast(Path, args.broker_allowlist_plan_output)
    exclusions_output = cast(Path, args.exclusions_output)
    active_selection_output = cast(Path, args.active_selection_output)
    replacement_selection_output = cast(Path, args.replacement_selection_output)
    try:
        purchase_policy_path = cast(Path, args.purchase_policy)
        cohort_policy_path = cast(Path, args.cohort_policy)
        frontier_path = cast(Path, args.frontier)
        candidate_selection_path = cast(Path, args.candidate_selection)
        purchased_clearance_path = cast(Path, args.purchased_clearance)
        clearance_run_card_path = cast(Path, args.clearance_run_card)
        purchase_artifact = _projection_json_object(
            read_unique_regular_file(purchase_policy_path),
            source=purchase_policy_path,
        )
        cohort_artifact = _projection_json_object(
            read_unique_regular_file(cohort_policy_path),
            source=cohort_policy_path,
        )
        frontier_bytes = read_unique_regular_file(frontier_path)
        frontier_artifact = _projection_json_object(
            frontier_bytes,
            source=frontier_path,
        )
        candidate_selection_bytes = read_unique_regular_file(candidate_selection_path)
        purchased_clearance_bytes = read_unique_regular_file(purchased_clearance_path)
        clearance_run_card_bytes = read_unique_regular_file(clearance_run_card_path)
        purchase_policy = verify_case_dev_purchase_policy(purchase_artifact)
        purchased_clearance_records = (
            _verify_replacement_clearance_evidence(
                clearance_bytes=purchased_clearance_bytes,
                clearance_path=purchased_clearance_path,
                run_card_bytes=clearance_run_card_bytes,
                run_card_path=clearance_run_card_path,
            )
            if purchase_policy.has_verified_approval
            else _projection_jsonl_records(
                purchased_clearance_bytes,
                source=purchased_clearance_path,
            )
        )
        require_approved_case_dev_purchase_policy(
            purchase_policy,
            controlled_private_root=cast(Path | None, args.controlled_private_root),
        )
        with CaseDevPurchaseJournal(
            cast(Path, args.purchase_ledger).resolve(),
            policy=purchase_policy,
            controlled_private_root=cast(Path | None, args.controlled_private_root),
            initialization_receipt_path=cast(
                Path, args.purchase_ledger_initialization_receipt
            ),
        ) as journal:
            result = plan_clearance_replacements(
                cohort_policy_artifact=cohort_artifact,
                purchase_policy_artifact=purchase_artifact,
                frontier_artifact=frontier_artifact,
                purchase_journal=journal,
                purchased_clearance_records=purchased_clearance_records,
                clearance_run_card_sha256=_bytes_sha256(clearance_run_card_bytes),
                controlled_private_root=cast(Path | None, args.controlled_private_root),
            )
        frontier_policy = _mapping(
            frontier_artifact.get("policy"),
            "replacement frontier policy",
        )
        source_commitments = _mapping(
            frontier_policy.get("source_commitments"),
            "replacement frontier source commitments",
        )
        if source_commitments.get("candidate_selection") != _bytes_sha256(
            candidate_selection_bytes
        ):
            raise ClearanceReplacementError(
                "candidate selection differs from the frozen replacement frontier"
            )
        selection_records = _projection_jsonl_records(
            candidate_selection_bytes,
            source=candidate_selection_path,
        )
        selection_by_candidate: dict[str, Mapping[str, object]] = {}
        for record in selection_records:
            candidate_id = _required_str(record, "candidate_id")
            if candidate_id in selection_by_candidate:
                raise ClearanceReplacementError(
                    "candidate selection contains duplicate candidate IDs"
                )
            selection_by_candidate[candidate_id] = record
        replacement_candidate_ids = tuple(
            plan.candidate_id for plan in result.replacement_plan.case_plans
        )
        if any(
            candidate_id not in selection_by_candidate
            for candidate_id in (
                *result.active_candidate_ids,
                *replacement_candidate_ids,
            )
        ):
            raise ClearanceReplacementError(
                "active replacement candidates do not exactly reconcile selection"
            )
        active_selection = tuple(
            selection_by_candidate[candidate_id]
            for candidate_id in result.active_candidate_ids
        )
        replacement_selection = tuple(
            selection_by_candidate[candidate_id]
            for candidate_id in replacement_candidate_ids
        )
        active_selection_bytes = _projection_jsonl_bytes(active_selection)
        replacement_selection_bytes = _projection_jsonl_bytes(replacement_selection)
        result_record = bind_replacement_selection_outputs(
            result,
            active_selection_sha256=_bytes_sha256(active_selection_bytes),
            active_selection_count=len(active_selection),
            replacement_selection_sha256=_bytes_sha256(replacement_selection_bytes),
            replacement_selection_count=len(replacement_selection),
        )
        _atomic_write_json(output, result_record)
        _atomic_write_json(replacement_output, result.replacement_plan.to_record())
        _atomic_write_json(allowlist_output, result.broker_allowlist_plan.to_record())
        _write_jsonl(exclusions_output, result.derived_exclusions)
        _write_jsonl(active_selection_output, active_selection)
        _write_jsonl(replacement_selection_output, replacement_selection)
    except (
        CaseDevPurchaseLedgerError,
        CaseDevPurchasePolicyError,
        ClearanceReplacementError,
        OSError,
        UnicodeError,
        ValueError,
    ) as exc:
        raise CommandError(str(exc)) from exc
    print(
        json.dumps(
            {
                "output": str(output),
                "active_candidate_count": len(result.active_candidate_ids),
                "replacement_candidate_count": len(result.replacement_plan.case_plans),
                "broad_allowlist_candidate_count": len(
                    result.broker_allowlist_plan.case_plans
                ),
                "stop_reason": result.stop_reason,
                "paid_activity_requested": False,
                "paid_activity_executed": False,
            },
            sort_keys=True,
        )
    )
    return 0


def _cmd_plan_ranked_reserve_replacements(args: argparse.Namespace) -> int:
    target_root = cast(Path, args.target_cohort_root)
    terminal_path = cast(Path | None, args.terminal_exclusions)
    terminal_digest_path = cast(Path | None, args.terminal_exclusions_sha256_file)
    purchase_result_path = cast(Path | None, args.purchase_result)
    purchase_run_card_path = cast(Path | None, args.purchase_run_card)
    snapshot_manifest_path = cast(Path | None, args.screening_snapshot_manifest)
    legacy_ranked_result_path = cast(Path | None, args.legacy_ranked_result)
    post_purchase_paths = {
        "prior_ranked_result": cast(Path | None, args.prior_ranked_result),
        "prior_replacement_selection": cast(
            Path | None, args.prior_replacement_selection
        ),
        "prior_replacement_budget_plan": cast(
            Path | None, args.prior_replacement_budget_plan
        ),
        "replacement_purchase_authority": cast(
            Path | None, args.replacement_purchase_authority
        ),
        "replacement_controlled_private_root": cast(
            Path | None, args.replacement_controlled_private_root
        ),
        "cohort_policy": cast(Path | None, args.cohort_policy),
    }
    resolved_transition_card_paths = tuple(
        cast(list[Path], getattr(args, "resolved_post_recovery_run_card", []))
    )
    policy_path = cast(Path, args.purchase_policy)
    output = cast(Path, args.output)
    active_output = cast(Path, args.active_selection_output)
    replacement_output = cast(Path, args.replacement_selection_output)
    exclusions_output = cast(Path, args.successor_exclusions_output)
    budget_output = cast(Path, args.replacement_budget_plan_output)
    try:
        legacy_terminal_mode = (
            terminal_path is not None and terminal_digest_path is not None
        )
        authenticated_values = (
            purchase_result_path,
            purchase_run_card_path,
            snapshot_manifest_path,
        )
        authenticated_terminal_mode = all(
            value is not None for value in authenticated_values
        )
        if (terminal_path is None) != (terminal_digest_path is None):
            raise RankedReserveReplacementError(
                "terminal exclusions and digest must be supplied together"
            )
        if any(value is not None for value in authenticated_values) and not (
            authenticated_terminal_mode
        ):
            raise RankedReserveReplacementError(
                "purchase result, purchase run card, and screening snapshot manifest "
                "must be supplied together"
            )
        if legacy_terminal_mode == authenticated_terminal_mode:
            raise RankedReserveReplacementError(
                "select exactly one terminal-evidence mode"
            )
        if legacy_ranked_result_path is not None and not authenticated_terminal_mode:
            raise RankedReserveReplacementError(
                "legacy ranked replay requires authenticated purchase disposition"
            )
        supplied_post_purchase_paths = {
            name: path for name, path in post_purchase_paths.items() if path is not None
        }
        if supplied_post_purchase_paths and len(supplied_post_purchase_paths) != len(
            post_purchase_paths
        ):
            missing = sorted(
                set(post_purchase_paths) - set(supplied_post_purchase_paths)
            )
            raise RankedReserveReplacementError(
                "post-purchase ranked replay requires the complete authority bundle; "
                "missing " + ", ".join(missing)
            )
        if supplied_post_purchase_paths and not authenticated_terminal_mode:
            raise RankedReserveReplacementError(
                "post-purchase ranked replay requires authenticated purchase "
                "disposition"
            )
        if resolved_transition_card_paths and not supplied_post_purchase_paths:
            raise RankedReserveReplacementError(
                "resolved transition cards require the complete post-purchase "
                "authority bundle"
            )
        if legacy_ranked_result_path is not None and supplied_post_purchase_paths:
            raise RankedReserveReplacementError(
                "legacy v2 and post-purchase v3 replay modes are mutually exclusive"
            )
        writable_paths = (
            output,
            active_output,
            replacement_output,
            exclusions_output,
            budget_output,
        )
        protected_roots = (
            target_root.resolve(strict=False),
            cast(Path, args.controlled_private_root).resolve(strict=False),
            *(
                (
                    cast(
                        Path,
                        post_purchase_paths["replacement_controlled_private_root"],
                    ).resolve(strict=False),
                )
                if supplied_post_purchase_paths
                else ()
            ),
        )
        protected_files = {
            policy_path.resolve(strict=False),
            cast(Path, args.purchase_ledger).resolve(strict=False),
            cast(Path, args.purchase_ledger_initialization_receipt).resolve(
                strict=False
            ),
            *(
                path.resolve(strict=False)
                for path in (
                    terminal_path,
                    terminal_digest_path,
                    purchase_result_path,
                    purchase_run_card_path,
                    snapshot_manifest_path,
                    legacy_ranked_result_path,
                    *(
                        tuple(supplied_post_purchase_paths.values())
                        if supplied_post_purchase_paths
                        else ()
                    ),
                    *resolved_transition_card_paths,
                )
                if path is not None
            ),
        }
        for writable_path in writable_paths:
            resolved = writable_path.resolve(strict=False)
            if resolved in protected_files or any(
                resolved == root or resolved.is_relative_to(root)
                for root in protected_roots
            ):
                raise RankedReserveReplacementError(
                    "ranked-reserve continuation output overlaps protected evidence"
                )
        if len({path.resolve(strict=False) for path in writable_paths}) != len(
            writable_paths
        ):
            raise RankedReserveReplacementError(
                "ranked-reserve continuation outputs must be distinct"
            )
        for writable_path in writable_paths:
            prepare_non_symlink_directory(writable_path.parent)
        verified = verify_completed_target_cohort_projection_for_purchase_approval(
            target_root
        )
        summary = _mapping(verified.get("summary"), "target projection summary")
        verified_bytes = cast(
            Mapping[str, bytes],
            _mapping(
                verified.get("verified_artifact_bytes"),
                "verified target artifact bytes",
            ),
        )
        summary_path = cast(Path, verified["summary_path"])
        selection_path = cast(Path, verified["selection_path"])
        reserve_path = target_root / "target-cohort-ranked-reserve.jsonl"
        original_exclusions_path = target_root / "target-cohort-exclusions.jsonl"
        source_commitments = _mapping(
            summary.get("input_commitments"), "target projection input commitments"
        )
        source_paths = [
            Path(str(path))
            for path in source_commitments
            if str(path).endswith("/public-packet-selection-reconciled.jsonl")
        ]
        if len(source_paths) != 1:
            raise RankedReserveReplacementError(
                "target projection lacks one frozen source-pool commitment"
            )

        def authenticated_bytes(path: Path) -> bytes:
            try:
                return verified_bytes[os.path.abspath(path)]
            except KeyError as exc:
                raise RankedReserveReplacementError(
                    f"full projection replay did not authenticate {path}"
                ) from exc

        # Explicitly require the summary itself to be part of the full replayed
        # artifact set before trusting its semantic commitments below.
        authenticated_bytes(summary_path)
        selected_bytes = authenticated_bytes(selection_path)
        reserve_bytes = authenticated_bytes(reserve_path)
        original_exclusions_bytes = authenticated_bytes(original_exclusions_path)
        source_pool_bytes = authenticated_bytes(source_paths[0])
        terminal_bytes = b""
        terminal_digest = ""
        legacy_ranked_result: Mapping[str, object] | None = None
        legacy_ranked_result_sha256: str | None = None
        legacy_ranked_result_bytes: bytes | None = None
        if legacy_ranked_result_path is not None:
            legacy_ranked_result_bytes = read_unique_regular_file(
                legacy_ranked_result_path
            )
            legacy_ranked_result = _projection_json_object(
                legacy_ranked_result_bytes,
                source=legacy_ranked_result_path,
            )
            if ranked_reserve_result_bytes(legacy_ranked_result) != (
                legacy_ranked_result_bytes
            ):
                raise RankedReserveReplacementError(
                    "legacy ranked result is not canonical JSON"
                )
            legacy_ranked_result_sha256 = _bytes_sha256(legacy_ranked_result_bytes)
        if legacy_terminal_mode:
            assert terminal_path is not None
            assert terminal_digest_path is not None
            terminal_bytes = read_unique_regular_file(terminal_path)
            terminal_digest_bytes = read_unique_regular_file(terminal_digest_path)
            try:
                terminal_digest = terminal_digest_bytes.decode("ascii").removesuffix(
                    "\n"
                )
            except UnicodeDecodeError as exc:
                raise RankedReserveReplacementError(
                    "terminal exclusion digest file must contain ASCII"
                ) from exc
            if terminal_digest_bytes != f"{terminal_digest}\n".encode("ascii"):
                raise RankedReserveReplacementError(
                    "terminal exclusion digest file must have one terminal newline"
                )
        purchase_policy_artifact = _projection_json_object(
            read_unique_regular_file(policy_path), source=policy_path
        )
        purchase_policy = verify_case_dev_purchase_policy(purchase_policy_artifact)
        require_approved_case_dev_purchase_policy(
            purchase_policy,
            controlled_private_root=cast(Path, args.controlled_private_root),
        )
        verified_post_purchase_replay: (
            VerifiedRankedReservePostPurchaseReplay | None
        ) = None
        prior_ranked_result_bytes: bytes | None = None
        post_purchase_source_snapshots: dict[Path, bytes] = {}
        if supplied_post_purchase_paths:
            prior_ranked_result_path = cast(
                Path, post_purchase_paths["prior_ranked_result"]
            )
            post_purchase_source_snapshots = {
                path: read_unique_regular_file(path)
                for name, path in supplied_post_purchase_paths.items()
                if name != "replacement_controlled_private_root"
            }
            prior_ranked_result_bytes = post_purchase_source_snapshots[
                prior_ranked_result_path
            ]
            prior_ranked_result = _projection_json_object(
                prior_ranked_result_bytes, source=prior_ranked_result_path
            )
            prior_selection_path = cast(
                Path, post_purchase_paths["prior_replacement_selection"]
            )
            prior_budget_path = cast(
                Path, post_purchase_paths["prior_replacement_budget_plan"]
            )
            replacement_authority_path = cast(
                Path, post_purchase_paths["replacement_purchase_authority"]
            )
            cohort_policy_path = cast(Path, post_purchase_paths["cohort_policy"])
            resolved_transition_capability_factory = (
                _issue_resolved_transition_capability_factory(
                    purchase_ledger_path=cast(Path, args.purchase_ledger),
                    policy=purchase_policy,
                    controlled_private_root=cast(Path, args.controlled_private_root),
                    initialization_receipt_path=cast(
                        Path, args.purchase_ledger_initialization_receipt
                    ),
                    run_card_paths=resolved_transition_card_paths,
                )
                if resolved_transition_card_paths
                else None
            )
            verified_post_purchase_replay = verify_ranked_reserve_post_purchase_replay(
                prior_result=prior_ranked_result,
                prior_result_bytes=prior_ranked_result_bytes,
                authority_artifact=_projection_json_object(
                    post_purchase_source_snapshots[replacement_authority_path],
                    source=replacement_authority_path,
                ),
                controlled_private_root=cast(
                    Path,
                    post_purchase_paths["replacement_controlled_private_root"],
                ),
                initial_purchase_policy_artifact=purchase_policy_artifact,
                initial_controlled_private_root=cast(
                    Path, args.controlled_private_root
                ),
                cohort_policy_artifact=_projection_json_object(
                    post_purchase_source_snapshots[cohort_policy_path],
                    source=cohort_policy_path,
                ),
                budget_plan_bytes=post_purchase_source_snapshots[prior_budget_path],
                selection_bytes=post_purchase_source_snapshots[prior_selection_path],
                purchase_ledger_path=cast(Path, args.purchase_ledger),
                purchase_ledger_initialization_receipt_path=cast(
                    Path, args.purchase_ledger_initialization_receipt
                ),
                _verified_resolved_authority_capability=(
                    resolved_transition_capability_factory()
                    if resolved_transition_capability_factory is not None
                    else None
                ),
                _verified_resolved_snapshot_capability=(
                    resolved_transition_capability_factory()
                    if resolved_transition_capability_factory is not None
                    else None
                ),
            )
        docket_descriptor: _MaterializerDocketDecisionAuthority | None = None
        authenticated_terminal_snapshots: dict[Path, bytes] = {}
        with CaseDevPurchaseJournal(
            cast(Path, args.purchase_ledger).resolve(),
            policy=purchase_policy,
            controlled_private_root=cast(Path, args.controlled_private_root),
            initialization_receipt_path=cast(
                Path, args.purchase_ledger_initialization_receipt
            ),
        ) as journal:
            disposition_authority: (
                VerifiedTerminalPurchaseDispositionAuthority | None
            ) = None
            precommit_revalidator: Callable[[], None] | None = None
            if authenticated_terminal_mode:
                assert purchase_result_path is not None
                assert purchase_run_card_path is not None
                assert snapshot_manifest_path is not None
                authenticated_terminal_snapshots = {
                    purchase_result_path: read_unique_regular_file(
                        purchase_result_path
                    ),
                    purchase_run_card_path: read_unique_regular_file(
                        purchase_run_card_path
                    ),
                    snapshot_manifest_path: read_unique_regular_file(
                        snapshot_manifest_path
                    ),
                    **(
                        {legacy_ranked_result_path: legacy_ranked_result_bytes}
                        if legacy_ranked_result_path is not None
                        and legacy_ranked_result_bytes is not None
                        else {}
                    ),
                    **(
                        post_purchase_source_snapshots
                        if supplied_post_purchase_paths
                        else {}
                    ),
                }
                selected_records = _projection_jsonl_records(
                    selected_bytes,
                    source=selection_path,
                )
                selected_document_count = 0
                for record in selected_records:
                    documents = record.get("documents")
                    if not isinstance(documents, list):
                        raise RankedReserveReplacementError(
                            "frozen selection documents must be a JSON list"
                        )
                    selected_document_count += len(cast(list[object], documents))
                docket_descriptor = _verify_materializer_docket_decision_authority(
                    selection_payload=selected_bytes,
                    snapshot_manifest_path=snapshot_manifest_path,
                    purchase_result_path=purchase_result_path,
                    purchase_run_card_path=purchase_run_card_path,
                    purchase_journal=journal,
                    purchase_policy=purchase_policy,
                    ledger_path=cast(Path, args.purchase_ledger).resolve(),
                    controlled_private_root=cast(Path, args.controlled_private_root),
                    initialization_receipt_path=cast(
                        Path, args.purchase_ledger_initialization_receipt
                    ),
                    selected_document_count=selected_document_count,
                )
                disposition_authority = docket_descriptor.authority
                terminal_bytes = residual_terminal_exclusions_bytes(
                    disposition_authority,
                    purchase_journal=journal,
                )
                terminal_digest = _bytes_sha256(terminal_bytes)

                def revalidate_terminal_disposition() -> None:
                    assert docket_descriptor is not None
                    _require_snapshot_unchanged(
                        {
                            **authenticated_terminal_snapshots,
                            **docket_descriptor.source_snapshots,
                        },
                        label="ranked-reserve terminal disposition authority",
                    )
                    _replay_materialized_docket_decision_authority_in_open_journal(
                        docket_descriptor,
                        purchase_journal=journal,
                    )

                precommit_revalidator = revalidate_terminal_disposition
                precommit_revalidator()
            plan = plan_ranked_reserve_replacements(
                projection=summary,
                selected_bytes=selected_bytes,
                reserve_bytes=reserve_bytes,
                source_pool_bytes=source_pool_bytes,
                original_exclusions_bytes=original_exclusions_bytes,
                terminal_exclusions_bytes=terminal_bytes,
                expected_terminal_exclusions_sha256=terminal_digest,
                purchase_journal=journal,
                terminal_purchase_disposition_authority=disposition_authority,
                precommit_revalidator=precommit_revalidator,
                legacy_ranked_result=legacy_ranked_result,
                legacy_ranked_result_sha256=legacy_ranked_result_sha256,
                verified_post_purchase_replay=verified_post_purchase_replay,
                allow_new_replacement_events=(
                    legacy_ranked_result is None
                    and verified_post_purchase_replay is None
                ),
            )
        if docket_descriptor is not None:
            _require_snapshot_unchanged(
                {
                    **authenticated_terminal_snapshots,
                    **docket_descriptor.source_snapshots,
                },
                label="ranked-reserve terminal disposition authority",
            )
            _replay_materialized_docket_decision_authority(docket_descriptor)
        active_bytes = _projection_jsonl_bytes(plan.active_selection)
        replacement_bytes = _projection_jsonl_bytes(plan.replacement_selection)
        exclusions_bytes = _projection_jsonl_bytes(plan.successor_exclusions)
        budget_bytes = _projection_json_bytes(plan.replacement_plan.to_record())
        result = bind_ranked_reserve_outputs(
            plan,
            active_selection_bytes=active_bytes,
            replacement_selection_bytes=replacement_bytes,
            successor_exclusions_bytes=exclusions_bytes,
            replacement_budget_plan_bytes=budget_bytes,
        )
        if verified_post_purchase_replay is not None:
            final_purchase_snapshot = read_case_dev_purchase_snapshot(
                cast(Path, args.purchase_ledger),
                policy=purchase_policy,
                controlled_private_root=cast(Path, args.controlled_private_root),
                initialization_receipt_path=cast(
                    Path, args.purchase_ledger_initialization_receipt
                ),
            )
            if final_purchase_snapshot != verified_post_purchase_replay.live_snapshot:
                raise RankedReserveReplacementError(
                    "purchase journal changed during post-purchase ranked replay"
                )
        resume = cast(bool, args.resume)
        _write_immutable_bytes(active_output, active_bytes, resume=resume)
        _write_immutable_bytes(replacement_output, replacement_bytes, resume=resume)
        _write_immutable_bytes(exclusions_output, exclusions_bytes, resume=resume)
        _write_immutable_bytes(budget_output, budget_bytes, resume=resume)
        _write_immutable_bytes(
            output, ranked_reserve_result_bytes(result), resume=resume
        )
    except (
        CaseDevPurchaseLedgerError,
        CaseDevPurchasePolicyError,
        CommandError,
        OSError,
        RankedReserveReplacementError,
        UnicodeError,
        ValueError,
    ) as exc:
        raise CommandError(str(exc)) from exc
    print(
        json.dumps(
            {
                "output": str(output),
                "active_candidate_count": len(plan.active_selection),
                "replacement_candidate_count": len(plan.replacement_selection),
                "successor_approval_required": plan.successor_approval_required,
                "provider_activity_requested": False,
                "paid_activity_requested": False,
                "paid_activity_executed": False,
            },
            sort_keys=True,
        )
    )
    return 0


def _authenticate_ranked_reserve_precursor(
    *,
    projection: Mapping[str, object],
    selection_payload: bytes,
    reserve_payload: bytes,
    source_pool_payload: bytes,
    original_exclusions_payload: bytes,
    active_selection_payload: bytes,
    replacement_selection_payload: bytes,
    successor_exclusions_payload: bytes,
    replacement_budget_plan_payload: bytes,
    purchase_policy_path: Path,
    controlled_private_root: Path,
    purchase_ledger_path: Path,
    purchase_ledger_initialization_receipt_path: Path,
    purchase_result_path: Path,
    purchase_run_card_path: Path,
    screening_snapshot_manifest_path: Path,
    ranked_result: Mapping[str, object],
    verified_post_purchase_replay: VerifiedRankedReservePostPurchaseReplay
    | None = None,
    verified_legacy_ranked_replay: VerifiedLegacyRankedReserveReplay | None = None,
    _authenticated_precursor: _AuthenticatedRankedReservePrecursor | None = None,
) -> _AuthenticatedRankedReservePrecursor:
    """Substantively replay the producer authority behind the ranked result."""

    policy_bytes = read_unique_regular_file(purchase_policy_path)
    policy = verify_case_dev_purchase_policy(
        _projection_json_object(policy_bytes, source=purchase_policy_path)
    )
    require_approved_case_dev_purchase_policy(
        policy, controlled_private_root=controlled_private_root
    )
    if ranked_result.get("purchase_policy_sha256") != "sha256:" + policy.policy_sha256:
        raise ZeroCostSuccessorError(
            "ranked result differs from authenticated purchase policy"
        )
    selection_records = _projection_jsonl_records(
        selection_payload, source=Path("authenticated-target-selection.jsonl")
    )
    selected_document_count = 0
    for record in selection_records:
        documents = record.get("documents")
        if not isinstance(documents, list):
            raise ZeroCostSuccessorError(
                "frozen selection documents must be a JSON list"
            )
        selected_document_count += len(cast(list[object], documents))
    if _authenticated_precursor is not None:
        if (
            _bytes_sha256(selection_payload)
            != _authenticated_precursor.selection_sha256
        ):
            raise ZeroCostSuccessorError(
                "ranked precursor selection changed before publication"
            )
        if (
            _bytes_sha256(policy_bytes)
            != _authenticated_precursor.purchase_policy_sha256
        ):
            raise ZeroCostSuccessorError(
                "ranked precursor purchase policy changed before publication"
            )
        descriptor = _authenticated_precursor.docket_decision_authority
        if (
            descriptor.purchase_policy.policy_sha256 != policy.policy_sha256
            or descriptor.ledger_path != purchase_ledger_path.resolve()
            or descriptor.controlled_private_root != controlled_private_root
            or descriptor.initialization_receipt_path
            != purchase_ledger_initialization_receipt_path
        ):
            raise ZeroCostSuccessorError(
                "ranked precursor authenticated authority changed before publication"
            )
    else:
        descriptor = None
    with CaseDevPurchaseJournal(
        purchase_ledger_path.resolve(),
        policy=policy,
        read_only=True,
        controlled_private_root=controlled_private_root,
        initialization_receipt_path=purchase_ledger_initialization_receipt_path,
    ) as journal:
        if descriptor is None:
            descriptor = _verify_materializer_docket_decision_authority(
                selection_payload=selection_payload,
                snapshot_manifest_path=screening_snapshot_manifest_path,
                purchase_result_path=purchase_result_path,
                purchase_run_card_path=purchase_run_card_path,
                purchase_journal=journal,
                purchase_policy=policy,
                ledger_path=purchase_ledger_path.resolve(),
                controlled_private_root=controlled_private_root,
                initialization_receipt_path=purchase_ledger_initialization_receipt_path,
                selected_document_count=selected_document_count,
            )
        disposition = dict(
            verified_terminal_purchase_disposition_record(
                descriptor.authority, purchase_journal=journal
            )
        )
        residual_bytes = residual_terminal_exclusions_bytes(
            descriptor.authority, purchase_journal=journal
        )

        def revalidate_disposition() -> None:
            verified_terminal_purchase_disposition_record(
                descriptor.authority, purchase_journal=journal
            )

        legacy_bridge_mode = verified_legacy_ranked_replay is not None
        if legacy_bridge_mode and (
            verified_post_purchase_replay is not None
            or ranked_result.get("schema_version")
            != "legalforecast.ranked_reserve_replacement_result.v2"
        ):
            raise ZeroCostSuccessorError(
                "legacy ranked bridge requires the exact frozen v2 result"
            )
        if not legacy_bridge_mode and (
            (
                ranked_result.get("schema_version")
                == POST_PURCHASE_REPLAY_RESULT_SCHEMA_VERSION
            )
            != (verified_post_purchase_replay is not None)
        ):
            raise ZeroCostSuccessorError(
                "post-purchase v4 replay requires its complete verified authority "
                "bundle"
            )
        plan = plan_ranked_reserve_replacements(
            projection=projection,
            selected_bytes=selection_payload,
            reserve_bytes=reserve_payload,
            source_pool_bytes=source_pool_payload,
            original_exclusions_bytes=original_exclusions_payload,
            terminal_exclusions_bytes=residual_bytes,
            expected_terminal_exclusions_sha256=_bytes_sha256(residual_bytes),
            purchase_journal=journal,
            terminal_purchase_disposition_authority=descriptor.authority,
            precommit_revalidator=revalidate_disposition,
            allow_new_replacement_events=False,
            authenticated_legacy_replay=(
                cast(Mapping[str, object], ranked_result["authenticated_legacy_replay"])
                if "authenticated_legacy_replay" in ranked_result
                and verified_post_purchase_replay is None
                and verified_legacy_ranked_replay is None
                else None
            ),
            verified_post_purchase_replay=verified_post_purchase_replay,
            verified_legacy_ranked_replay=verified_legacy_ranked_replay,
        )
        authenticated_result = bind_ranked_reserve_outputs(
            plan,
            active_selection_bytes=active_selection_payload,
            replacement_selection_bytes=replacement_selection_payload,
            successor_exclusions_bytes=successor_exclusions_payload,
            replacement_budget_plan_bytes=replacement_budget_plan_payload,
        )
        if _authenticated_precursor is not None:
            _replay_materialized_docket_decision_authority_in_open_journal(
                descriptor, purchase_journal=journal
            )
    expected_result = (
        verified_legacy_ranked_replay.bridge_result
        if verified_legacy_ranked_replay is not None
        else ranked_result
    )
    # A v2-to-v3 bridge deliberately crosses a later terminal-material
    # transition.  Its historical disposition is reconstructed and bound by
    # ``plan_ranked_reserve_replacements`` below; the live descriptor's
    # disposition is therefore not expected to equal the frozen bridge value.
    if verified_legacy_ranked_replay is None and disposition != expected_result.get(
        "terminal_disposition"
    ):
        raise ZeroCostSuccessorError(
            "ranked terminal disposition differs from authenticated replay"
        )
    if authenticated_result != expected_result:
        differing_fields = sorted(
            key
            for key in set(authenticated_result) | set(expected_result)
            if authenticated_result.get(key) != expected_result.get(key)
        )
        raise ZeroCostSuccessorError(
            "ranked result differs from authenticated ranked-reserve replay: "
            + ", ".join(differing_fields)
        )
    result: Mapping[str, object] | VerifiedPostPurchaseRankedResult
    if verified_legacy_ranked_replay is not None:
        result = dict(ranked_result)
    elif verified_post_purchase_replay is not None:
        result = _mint_verified_post_purchase_ranked_result(
            authenticated_result, verified_post_purchase_replay
        )
    else:
        result = authenticated_result
    return _AuthenticatedRankedReservePrecursor(
        result=result,
        docket_decision_authority=descriptor,
        selection_sha256=_bytes_sha256(selection_payload),
        purchase_policy_sha256=_bytes_sha256(policy_bytes),
    )


def _cmd_project_zero_cost_successor(args: argparse.Namespace) -> int:
    target_root = cast(Path, args.target_cohort_root)
    result_path = cast(Path, args.ranked_reserve_result)
    active_path = cast(Path, args.active_selection)
    replacement_path = cast(Path, args.replacement_selection)
    exclusions_path = cast(Path, args.successor_exclusions)
    budget_path = cast(Path, args.replacement_budget_plan)
    clearance_path = cast(Path, args.disclosure_clearance)
    clearance_card_path = cast(Path, args.disclosure_clearance_run_card)
    purchase_policy_path = cast(Path, args.purchase_policy)
    controlled_private_root = cast(Path, args.controlled_private_root)
    purchase_ledger_path = cast(Path, args.purchase_ledger)
    purchase_ledger_receipt_path = cast(
        Path, args.purchase_ledger_initialization_receipt
    )
    purchase_result_path = cast(Path, args.purchase_result)
    purchase_run_card_path = cast(Path, args.purchase_run_card)
    snapshot_manifest_path = cast(Path, args.screening_snapshot_manifest)
    verified_legacy_ranked_replay = cast(
        VerifiedLegacyRankedReserveReplay | None,
        getattr(args, "_verified_legacy_ranked_replay", None),
    )
    verified_clearance_relocations = cast(
        Mapping[str, tuple[Path, bytes]] | None,
        getattr(args, "_verified_clearance_relocations", None),
    )
    verified_clearance_source_roots = cast(
        Mapping[str, Path] | None,
        getattr(args, "_verified_clearance_source_roots", None),
    )
    post_purchase_paths = {
        "prior_ranked_result": cast(
            Path | None, getattr(args, "prior_ranked_result", None)
        ),
        "prior_replacement_selection": cast(
            Path | None, getattr(args, "prior_replacement_selection", None)
        ),
        "prior_replacement_budget_plan": cast(
            Path | None, getattr(args, "prior_replacement_budget_plan", None)
        ),
        "replacement_purchase_authority": cast(
            Path | None, getattr(args, "replacement_purchase_authority", None)
        ),
        "replacement_controlled_private_root": cast(
            Path | None, getattr(args, "replacement_controlled_private_root", None)
        ),
        "cohort_policy": cast(Path | None, getattr(args, "cohort_policy", None)),
    }
    supplied_post_purchase_paths = {
        name: path for name, path in post_purchase_paths.items() if path is not None
    }
    resolved_transition_card_paths = tuple(
        cast(list[Path], getattr(args, "resolved_post_recovery_run_card", []))
    )
    output_root = cast(Path, args.output_root)
    output_paths = {
        "selection": output_root / "target-cohort-selection.jsonl",
        "config": output_root / "target-cohort-projection.json",
        "state": output_root / "run-cards/project-target-cohort.json",
        "case_relevance": output_root / "case-relevance.jsonl",
        "download_manifest": output_root / "document-downloads-merged.jsonl",
        "free_manifest": output_root / "free-document-downloads.jsonl",
        "purchased_manifest": output_root / "purchased-document-downloads.jsonl",
        "clearance": output_root / "disclosure-clearance.jsonl",
        "restriction": output_root / "restriction-evidence.jsonl",
        "core_filter": output_root / "core-filter-results.jsonl",
        "budget": output_root / "missing-core-budget-plan.json",
        "exclusions": output_root / "target-cohort-exclusions.jsonl",
        "ranked_reserve": output_root / "target-cohort-ranked-reserve.jsonl",
    }
    protected_inputs = (
        result_path,
        active_path,
        replacement_path,
        exclusions_path,
        budget_path,
        clearance_path,
        clearance_card_path,
        purchase_policy_path,
        controlled_private_root,
        purchase_ledger_path,
        purchase_ledger_receipt_path,
        purchase_result_path,
        purchase_run_card_path,
        snapshot_manifest_path,
        *supplied_post_purchase_paths.values(),
        *resolved_transition_card_paths,
    )
    try:
        if supplied_post_purchase_paths and len(supplied_post_purchase_paths) != len(
            post_purchase_paths
        ):
            missing = sorted(
                set(post_purchase_paths) - set(supplied_post_purchase_paths)
            )
            raise ZeroCostSuccessorError(
                "post-purchase v4 replay requires the complete authority bundle; "
                "missing " + ", ".join(missing)
            )
        if resolved_transition_card_paths and not supplied_post_purchase_paths:
            raise ZeroCostSuccessorError(
                "resolved transition cards require the complete post-purchase "
                "authority bundle"
            )
        resolved_output = output_root.resolve(strict=False)
        resolved_target = target_root.resolve(strict=False)
        if (
            resolved_output == resolved_target
            or resolved_output.is_relative_to(resolved_target)
            or resolved_target.is_relative_to(resolved_output)
        ):
            raise ZeroCostSuccessorError(
                "successor output overlaps the frozen target cohort"
            )
        for path in protected_inputs:
            resolved_input = path.resolve(strict=False)
            if (
                resolved_output == resolved_input
                or resolved_output.is_relative_to(resolved_input)
                or resolved_input.is_relative_to(resolved_output)
            ):
                raise ZeroCostSuccessorError(
                    "successor output overlaps protected input evidence"
                )
        _reject_unexpected_materializer_outputs(
            output_root, expected_files=set(output_paths.values())
        )
        for output_path in output_paths.values():
            prepare_non_symlink_directory(output_path.parent)
        verified = verify_completed_target_cohort_projection_for_purchase_approval(
            target_root
        )
        projection = _mapping(verified.get("summary"), "target projection summary")
        verified_bytes = cast(
            Mapping[str, bytes],
            _mapping(
                verified.get("verified_artifact_bytes"),
                "verified target artifact bytes",
            ),
        )
        summary_path = cast(Path, verified["summary_path"])
        selection_path = cast(Path, verified["selection_path"])
        reserve_path = target_root / "target-cohort-ranked-reserve.jsonl"
        original_exclusions_path = target_root / "target-cohort-exclusions.jsonl"
        source_commitments = _mapping(
            projection.get("input_commitments"), "target input commitments"
        )
        source_paths = tuple(
            Path(str(path))
            for path in source_commitments
            if str(path).endswith("/public-packet-selection-reconciled.jsonl")
        )
        if len(source_paths) != 1:
            raise ZeroCostSuccessorError(
                "target projection lacks one frozen source-pool commitment"
            )

        def authenticated_target_bytes(path: Path) -> bytes:
            try:
                return verified_bytes[os.path.abspath(path)]
            except KeyError as exc:
                raise ZeroCostSuccessorError(
                    f"target projection replay did not authenticate {path}"
                ) from exc

        authenticated_target_bytes(summary_path)
        original_selection_bytes = authenticated_target_bytes(selection_path)
        reserve_bytes = authenticated_target_bytes(reserve_path)
        original_exclusions_bytes = authenticated_target_bytes(original_exclusions_path)
        source_pool_bytes = authenticated_target_bytes(source_paths[0])

        result_bytes = read_unique_regular_file(result_path)
        ranked_result = _projection_json_object(result_bytes, source=result_path)
        active_bytes = read_unique_regular_file(active_path)
        replacement_bytes = read_unique_regular_file(replacement_path)
        exclusions_bytes = read_unique_regular_file(exclusions_path)
        budget_bytes = read_unique_regular_file(budget_path)
        is_post_purchase_v4 = (
            ranked_result.get("schema_version")
            == POST_PURCHASE_REPLAY_RESULT_SCHEMA_VERSION
        )
        if is_post_purchase_v4 != bool(supplied_post_purchase_paths):
            raise ZeroCostSuccessorError(
                "post-purchase v4 replay requires exactly its complete authority bundle"
            )
        verified_post_purchase_replay: (
            VerifiedRankedReservePostPurchaseReplay | None
        ) = None
        post_purchase_source_snapshots: dict[Path, bytes] = {}
        verify_post_purchase_bundle: (
            Callable[[], VerifiedRankedReservePostPurchaseReplay] | None
        ) = None
        if supplied_post_purchase_paths:
            post_purchase_source_snapshots = {
                path: read_unique_regular_file(path)
                for name, path in supplied_post_purchase_paths.items()
                if name != "replacement_controlled_private_root"
            }
            prior_result_path = cast(Path, post_purchase_paths["prior_ranked_result"])
            prior_selection_path = cast(
                Path, post_purchase_paths["prior_replacement_selection"]
            )
            prior_budget_path = cast(
                Path, post_purchase_paths["prior_replacement_budget_plan"]
            )
            authority_path = cast(
                Path, post_purchase_paths["replacement_purchase_authority"]
            )
            cohort_policy_path = cast(Path, post_purchase_paths["cohort_policy"])
            prior_result_bytes = post_purchase_source_snapshots[prior_result_path]
            initial_policy_artifact = _projection_json_object(
                read_unique_regular_file(purchase_policy_path),
                source=purchase_policy_path,
            )
            resolved_transition_capability_factory = None
            if resolved_transition_card_paths:
                initial_policy = verify_case_dev_purchase_policy(
                    initial_policy_artifact
                )
                require_approved_case_dev_purchase_policy(
                    initial_policy, controlled_private_root=controlled_private_root
                )
                resolved_transition_capability_factory = (
                    _issue_resolved_transition_capability_factory(
                        purchase_ledger_path=purchase_ledger_path,
                        policy=initial_policy,
                        controlled_private_root=controlled_private_root,
                        initialization_receipt_path=purchase_ledger_receipt_path,
                        run_card_paths=resolved_transition_card_paths,
                    )
                )

            def replay_post_purchase_bundle() -> (
                VerifiedRankedReservePostPurchaseReplay
            ):
                return verify_ranked_reserve_post_purchase_replay(
                    prior_result=_projection_json_object(
                        prior_result_bytes, source=prior_result_path
                    ),
                    prior_result_bytes=prior_result_bytes,
                    authority_artifact=_projection_json_object(
                        post_purchase_source_snapshots[authority_path],
                        source=authority_path,
                    ),
                    controlled_private_root=cast(
                        Path,
                        post_purchase_paths["replacement_controlled_private_root"],
                    ),
                    initial_purchase_policy_artifact=initial_policy_artifact,
                    initial_controlled_private_root=controlled_private_root,
                    cohort_policy_artifact=_projection_json_object(
                        post_purchase_source_snapshots[cohort_policy_path],
                        source=cohort_policy_path,
                    ),
                    budget_plan_bytes=post_purchase_source_snapshots[prior_budget_path],
                    selection_bytes=post_purchase_source_snapshots[
                        prior_selection_path
                    ],
                    purchase_ledger_path=purchase_ledger_path,
                    purchase_ledger_initialization_receipt_path=(
                        purchase_ledger_receipt_path
                    ),
                    _verified_resolved_authority_capability=(
                        resolved_transition_capability_factory()
                        if resolved_transition_capability_factory is not None
                        else None
                    ),
                    _verified_resolved_snapshot_capability=(
                        resolved_transition_capability_factory()
                        if resolved_transition_capability_factory is not None
                        else None
                    ),
                )

            verify_post_purchase_bundle = replay_post_purchase_bundle
            verified_post_purchase_replay = verify_post_purchase_bundle()
        authenticated_precursor = _authenticate_ranked_reserve_precursor(
            projection=projection,
            selection_payload=original_selection_bytes,
            reserve_payload=reserve_bytes,
            source_pool_payload=source_pool_bytes,
            original_exclusions_payload=original_exclusions_bytes,
            active_selection_payload=active_bytes,
            replacement_selection_payload=replacement_bytes,
            successor_exclusions_payload=exclusions_bytes,
            replacement_budget_plan_payload=budget_bytes,
            purchase_policy_path=purchase_policy_path,
            controlled_private_root=controlled_private_root,
            purchase_ledger_path=purchase_ledger_path,
            purchase_ledger_initialization_receipt_path=purchase_ledger_receipt_path,
            purchase_result_path=purchase_result_path,
            purchase_run_card_path=purchase_run_card_path,
            screening_snapshot_manifest_path=snapshot_manifest_path,
            ranked_result=ranked_result,
            verified_post_purchase_replay=verified_post_purchase_replay,
            verified_legacy_ranked_replay=verified_legacy_ranked_replay,
        )
        authenticated_ranked_result = authenticated_precursor.result
        clearance_bytes = read_unique_regular_file(clearance_path)
        clearance_card_bytes = read_unique_regular_file(clearance_card_path)
        clearance_card = _projection_json_object(
            clearance_card_bytes, source=clearance_card_path
        )
        clearance_sources = _mapping(
            clearance_card.get("source_commitments"),
            "disclosure clearance source commitments",
        )
        relevance_path = _materializer_committed_path(
            clearance_sources, "case_relevance"
        )
        manifest_path = _materializer_committed_path(
            clearance_sources, "download_manifest"
        )
        restriction_path = _materializer_committed_path(
            clearance_sources, "restriction_evidence"
        )
        clearance_snapshot = (
            _capture_clearance_artifact_snapshot(
                run_card=clearance_card,
                run_card_path=clearance_card_path,
                clearance_path=clearance_path,
                initial_artifact_bytes={
                    old_path: payload
                    for old_path, (_stable_path, payload) in (
                        verified_clearance_relocations or {}
                    ).items()
                },
            )
            if verified_clearance_relocations
            else None
        )
        _verify_authenticated_clearance_run_card(
            clearance_path=clearance_path,
            clearance_run_card_path=clearance_card_path,
            expected_download_manifest_path=manifest_path,
            expected_restriction_path=restriction_path,
            captured_artifact_bytes=clearance_snapshot,
            _verified_source_root_relocations=verified_clearance_source_roots,
        )
        relevance_bytes = read_unique_regular_file(relevance_path)
        manifest_bytes = read_unique_regular_file(manifest_path)
        restriction_bytes = read_unique_regular_file(restriction_path)
        snapshots = {
            result_path: result_bytes,
            active_path: active_bytes,
            replacement_path: replacement_bytes,
            exclusions_path: exclusions_bytes,
            budget_path: budget_bytes,
            clearance_path: clearance_bytes,
            clearance_card_path: clearance_card_bytes,
            relevance_path: relevance_bytes,
            manifest_path: manifest_bytes,
            restriction_path: restriction_bytes,
            **post_purchase_source_snapshots,
        }
        successor = project_zero_cost_successor(
            target_projection=projection,
            original_selection=_projection_jsonl_records(
                original_selection_bytes, source=selection_path
            ),
            ranked_reserve=_projection_jsonl_records(
                reserve_bytes, source=reserve_path
            ),
            source_pool=_projection_jsonl_records(
                source_pool_bytes, source=source_paths[0]
            ),
            ranked_result=ranked_result,
            ranked_result_bytes=result_bytes,
            authenticated_ranked_result=authenticated_ranked_result,
            active_selection=_projection_jsonl_records(
                active_bytes, source=active_path
            ),
            active_selection_bytes=active_bytes,
            replacement_selection=_projection_jsonl_records(
                replacement_bytes, source=replacement_path
            ),
            replacement_selection_bytes=replacement_bytes,
            successor_exclusions_bytes=exclusions_bytes,
            replacement_budget_plan_bytes=budget_bytes,
            disclosure_clearance=_projection_jsonl_records(
                clearance_bytes, source=clearance_path
            ),
            disclosure_clearance_bytes=clearance_bytes,
            disclosure_clearance_run_card_bytes=clearance_card_bytes,
            case_relevance=_projection_jsonl_records(
                relevance_bytes, source=relevance_path
            ),
            download_manifest=_projection_jsonl_records(
                manifest_bytes, source=manifest_path
            ),
            restriction_evidence=_projection_jsonl_records(
                restriction_bytes, source=restriction_path
            ),
        )
        _require_snapshot_unchanged(snapshots, label="zero-cost successor authority")
        if (
            _authenticate_ranked_reserve_precursor(
                projection=projection,
                selection_payload=original_selection_bytes,
                reserve_payload=reserve_bytes,
                source_pool_payload=source_pool_bytes,
                original_exclusions_payload=original_exclusions_bytes,
                active_selection_payload=active_bytes,
                replacement_selection_payload=replacement_bytes,
                successor_exclusions_payload=exclusions_bytes,
                replacement_budget_plan_payload=budget_bytes,
                purchase_policy_path=purchase_policy_path,
                controlled_private_root=controlled_private_root,
                purchase_ledger_path=purchase_ledger_path,
                purchase_ledger_initialization_receipt_path=(
                    purchase_ledger_receipt_path
                ),
                purchase_result_path=purchase_result_path,
                purchase_run_card_path=purchase_run_card_path,
                screening_snapshot_manifest_path=snapshot_manifest_path,
                ranked_result=ranked_result,
                verified_post_purchase_replay=(
                    verify_post_purchase_bundle()
                    if verify_post_purchase_bundle is not None
                    else None
                ),
                verified_legacy_ranked_replay=verified_legacy_ranked_replay,
                _authenticated_precursor=authenticated_precursor,
            ).result
            != authenticated_ranked_result
        ):
            raise ZeroCostSuccessorError(
                "ranked precursor authority changed before publication"
            )

        def successor_jsonl(records: Iterable[Mapping[str, Any]]) -> bytes:
            return b"".join(canonical_json_bytes(record) for record in records)

        selection_output_bytes = successor_jsonl(successor.selection)
        config_output_bytes = canonical_json_bytes(successor.config)
        input_paths = (
            target_root,
            result_path,
            active_path,
            replacement_path,
            exclusions_path,
            budget_path,
            clearance_path,
            clearance_card_path,
            purchase_policy_path,
            controlled_private_root,
            purchase_ledger_path,
            purchase_ledger_receipt_path,
            purchase_result_path,
            purchase_run_card_path,
            snapshot_manifest_path,
            *supplied_post_purchase_paths.values(),
            *resolved_transition_card_paths,
        )
        state_record = {
            **successor.state,
            "stage": "project-zero-cost-successor",
            "dry_run": False,
            "execute": True,
            "record_count": len(successor.selection),
            "input_paths": [str(path.resolve()) for path in input_paths],
            "output_paths": [str(path.resolve()) for path in output_paths.values()],
            "output_commitments": {
                **cast(Mapping[str, object], successor.config["output_commitments"]),
                "target-cohort-projection.json": _bytes_sha256(config_output_bytes),
            },
        }
        state_output_bytes = _projection_json_bytes(state_record)
        resume = cast(bool, args.resume)
        output_payloads = {
            "selection": selection_output_bytes,
            "config": config_output_bytes,
            "state": state_output_bytes,
            "case_relevance": successor_jsonl(successor.case_relevance),
            "download_manifest": successor_jsonl(successor.download_manifest),
            "free_manifest": successor_jsonl(
                row
                for row in successor.download_manifest
                if row.get("free_or_purchased") == "free"
            ),
            "purchased_manifest": successor_jsonl(
                row
                for row in successor.download_manifest
                if row.get("free_or_purchased") == "purchased"
            ),
            "clearance": successor_jsonl(successor.disclosure_clearance),
            "restriction": successor_jsonl(successor.restriction_evidence),
            "core_filter": successor_jsonl(successor.core_filter_results),
            "budget": budget_bytes,
            "exclusions": exclusions_bytes,
            "ranked_reserve": b"",
        }
        for name, payload in output_payloads.items():
            _write_immutable_bytes(output_paths[name], payload, resume=resume)
    except (
        CommandError,
        OSError,
        TargetCohortProjectionError,
        UnicodeError,
        ValueError,
        ZeroCostSuccessorError,
    ) as exc:
        raise CommandError(str(exc)) from exc
    print(
        json.dumps(
            {
                "output_root": str(output_root),
                "selected_case_count": len(successor.selection),
                "selected_zero_cost_candidate_id": successor.config[
                    "selected_zero_cost_candidate_id"
                ],
                "provider_activity_requested": False,
                "paid_activity_requested": False,
                "paid_activity_executed": False,
                "evaluation_authorized": False,
                "freeze_authorized": False,
                "dispatch_authorized": False,
            },
            sort_keys=True,
        )
    )
    return 0


_REPLACEMENT_CLEARANCE_ACCUMULATION_SCHEMA = (
    "legalforecast.replacement_clearance_accumulation_run_card.v1"
)
_REPLACEMENT_EXCLUSION_CARD_SCHEMA = (
    "legalforecast.replacement_successor_exclusion_run_card.v1"
)


@dataclass(frozen=True, slots=True)
class _ReplacementExclusionPublication:
    records: tuple[JsonRecord, ...]
    input_paths: tuple[Path, ...]
    source_snapshots: Mapping[Path, bytes]
    selected_candidate_ids: tuple[str, ...]
    screened_candidate_ids: tuple[str, ...]


def _prepare_replacement_exclusions(
    *,
    target_root: Path,
    screened_cases_path: Path,
    exclusion_paths: Sequence[Path],
    verified_projection: Mapping[str, object] | None = None,
    captured_source_bytes: Mapping[str, bytes] | None = None,
) -> _ReplacementExclusionPublication:
    projection = (
        verified_projection
        if verified_projection is not None
        else verify_completed_target_cohort_projection_for_purchase_approval(
            target_root
        )
    )
    source_bytes = dict(captured_source_bytes or {})
    for path, label in (
        (screened_cases_path, "replacement screened cases"),
        *((path, "replacement exclusion source") for path in exclusion_paths),
    ):
        absolute = os.path.abspath(path)
        if absolute not in source_bytes:
            source_bytes[absolute] = _read_singly_linked_regular_input(
                path, label=label
            )
    selection_path = cast(Path, projection["selection_path"])
    selection_records = cast(
        Sequence[Mapping[str, Any]], projection["selection_records"]
    )
    selected_ids = tuple(
        _required_str(record, "candidate_id") for record in selection_records
    )
    if len(selected_ids) != len(set(selected_ids)):
        raise ClearanceReplacementError(
            "replacement successor selection repeats a candidate"
        )
    screened_bytes = source_bytes[os.path.abspath(screened_cases_path)]
    screened_records = _projection_jsonl_records(
        screened_bytes, source=screened_cases_path
    )
    screened_ids = tuple(
        _required_str(_required_record(record, "candidate"), "docket_id")
        for record in screened_records
    )
    if len(screened_ids) != len(set(screened_ids)):
        raise ClearanceReplacementError("screened pool repeats a candidate")
    run_card = cast(Mapping[str, object], projection["run_card"])
    raw_inputs = run_card.get("input_paths")
    if not isinstance(raw_inputs, Sequence) or isinstance(raw_inputs, (str, bytes)):
        raise ClearanceReplacementError(
            "successor exclusions require an authenticated replacement projection"
        )
    replacement_inputs = cast(Sequence[object], raw_inputs)
    verified_projection_bytes = cast(
        Mapping[str, bytes], projection["verified_artifact_bytes"]
    )
    derived_rows: tuple[JsonRecord, ...] = ()
    quarantined_rows: list[JsonRecord] = []
    is_zero_cost_successor = (
        run_card.get("schema_version") == ZERO_COST_SUCCESSOR_STATE_SCHEMA
    )
    if is_zero_cost_successor:
        if (
            run_card.get("stage") != "project-zero-cost-successor"
            or len(replacement_inputs) != 23
        ):
            raise ClearanceReplacementError(
                "successor exclusions require an authenticated zero-cost successor "
                "projection"
            )
        # These slots are committed by the completed successor-state schema;
        # accepting an adjacent or copied sidecar would reopen its lineage.
        replacement_result_path = Path(str(replacement_inputs[1]))
        historical_exclusion_path = Path(str(replacement_inputs[4]))
        historical_exclusion_bytes = verified_projection_bytes.get(
            os.path.abspath(historical_exclusion_path)
        )
        matching_historical_sources = tuple(
            path
            for path in exclusion_paths
            if path.resolve() == historical_exclusion_path.resolve()
        )
        if historical_exclusion_bytes is None or len(matching_historical_sources) != 1:
            raise ClearanceReplacementError(
                "zero-cost successor exclusions require exactly one authenticated "
                "historical exclusion source"
            )
        if (
            source_bytes[os.path.abspath(matching_historical_sources[0])]
            != historical_exclusion_bytes
        ):
            raise ClearanceReplacementError(
                "authenticated historical exclusion source commitment changed"
            )
        # The source is re-read only to detect a mutation.  Downstream ledger
        # construction must consume the verifier-owned snapshot, not caller
        # supplied bytes from this point forward.
        source_bytes[os.path.abspath(matching_historical_sources[0])] = (
            historical_exclusion_bytes
        )
    else:
        if len(replacement_inputs) != 19:
            raise ClearanceReplacementError(
                "successor exclusions require an authenticated replacement projection"
            )
        replacement_result_path = Path(str(replacement_inputs[9]))
    replacement_result_bytes = verified_projection_bytes.get(
        os.path.abspath(replacement_result_path)
    )
    if replacement_result_bytes is None:
        raise ClearanceReplacementError(
            "authenticated replacement projection lacks replacement result bytes"
        )
    if not is_zero_cost_successor:
        replacement_result = _projection_json_object(
            replacement_result_bytes,
            source=replacement_result_path,
        )
        raw_ledger = replacement_result.get("ledger_records")
        raw_derived = replacement_result.get("derived_exclusions")
        if (
            not isinstance(raw_ledger, Sequence)
            or isinstance(raw_ledger, (str, bytes))
            or not isinstance(raw_derived, Sequence)
            or isinstance(raw_derived, (str, bytes))
        ):
            raise ClearanceReplacementError(
                "replacement result lacks exclusion lineage"
            )
        for raw_event in cast(Sequence[object], raw_ledger):
            event = _mapping(raw_event, "replacement ledger event")
            candidate_id = _required_str(event, "quarantined_candidate_id")
            quarantined_rows.append(
                {
                    "candidate_id": candidate_id,
                    "case_id": candidate_id,
                    "stage": "eligibility",
                    "reason": "purchased_document_quarantined",
                    "source_document_ids": list(
                        _required_str_tuple(event, "quarantined_document_ids")
                    ),
                    "source_entry_ids": [
                        _required_str(event, "record_sha256"),
                    ],
                    "notes": (
                        "Removed from the active cohort by the authenticated "
                        "purchased-clearance replacement ledger."
                    ),
                }
            )
        derived_rows = tuple(
            dict(_mapping(row, "replacement derived exclusion"))
            for row in cast(Sequence[object], raw_derived)
        )
    source_groups = tuple(
        _projection_jsonl_records(
            (source_bytes[os.path.abspath(path)]),
            source=path,
        )
        for path in exclusion_paths
    )
    ledger = merge_exclusion_ledger_records(
        *source_groups,
        derived_rows,
        quarantined_rows,
    )
    selected_set = set(selected_ids)
    records = tuple(
        dict(record)
        for record in ledger.to_records()
        if _required_str(record, "candidate_id") not in selected_set
    )
    excluded_ids = {_required_str(record, "candidate_id") for record in records}
    screened_set = set(screened_ids)
    if selected_set & excluded_ids:
        raise ClearanceReplacementError(
            "replacement successor candidate is both selected and excluded"
        )
    if selected_set | excluded_ids != screened_set:
        raise ClearanceReplacementError(
            "replacement successor exclusions do not exactly reconcile screened "
            f"pool; missing={sorted(screened_set - selected_set - excluded_ids)}; "
            f"unknown={sorted((selected_set | excluded_ids) - screened_set)}"
        )
    source_paths = (
        cast(Path, projection["run_card_path"]),
        selection_path,
        replacement_result_path,
        screened_cases_path,
        *exclusion_paths,
    )
    snapshots = {
        path: (
            source_bytes[os.path.abspath(path)]
            if os.path.abspath(path) in source_bytes
            else verified_projection_bytes[os.path.abspath(path)]
            if os.path.abspath(path) in verified_projection_bytes
            else _read_singly_linked_regular_input(
                path, label="replacement successor exclusion input"
            )
        )
        for path in source_paths
    }
    return _ReplacementExclusionPublication(
        records=records,
        input_paths=source_paths,
        source_snapshots=snapshots,
        selected_candidate_ids=tuple(sorted(selected_set)),
        screened_candidate_ids=tuple(sorted(screened_set)),
    )


def _cmd_build_replacement_exclusions(args: argparse.Namespace) -> int:
    output_root = cast(Path, args.output_root).absolute()
    output_path = (
        cast(Path, args.exclusions_output).absolute()
        if args.exclusions_output is not None
        else output_root / "successor-target-exclusions.jsonl"
    )
    run_card_path = (
        cast(Path, args.run_card_output).absolute()
        if args.run_card_output is not None
        else output_root / "run-cards" / "build-replacement-exclusions.json"
    )
    try:
        prepared = _prepare_replacement_exclusions(
            target_root=cast(Path, args.target_cohort_root).absolute(),
            screened_cases_path=cast(Path, args.screened_cases).absolute(),
            exclusion_paths=tuple(
                path.absolute() for path in cast(Sequence[Path], args.exclusion_source)
            ),
        )
        payload = _projection_jsonl_bytes(prepared.records)
        card: JsonRecord = {
            "schema_version": _REPLACEMENT_EXCLUSION_CARD_SCHEMA,
            "stage": "build-replacement-exclusions",
            "status": "completed",
            "dry_run": not cast(bool, args.execute),
            "execute": cast(bool, args.execute),
            "resume": cast(bool, args.resume),
            "record_count": len(prepared.records),
            "input_paths": [str(path) for path in prepared.input_paths],
            "output_paths": [str(output_path)],
            "source_commitments": {
                str(path.resolve()): _bytes_sha256(source)
                for path, source in prepared.source_snapshots.items()
            },
            "output_commitments": {str(output_path.resolve()): _bytes_sha256(payload)},
            "selected_candidate_ids": list(prepared.selected_candidate_ids),
            "screened_candidate_ids": list(prepared.screened_candidate_ids),
            "paid_activity_requested": False,
            "paid_activity_executed": False,
            "provider_activity_requested": False,
            "provider_activity_executed": False,
        }
        if not cast(bool, args.execute):
            print(json.dumps(card, sort_keys=True))
            return 0
        _ensure_projection_artifact(
            output_path, payload, resume=cast(bool, args.resume)
        )
        _ensure_projection_artifact(
            run_card_path,
            _projection_json_bytes(card),
            resume=cast(bool, args.resume),
        )
    except (
        ClearanceReplacementError,
        CommandError,
        OSError,
        UnicodeError,
        ValueError,
    ) as exc:
        raise CommandError(str(exc)) from exc
    print(
        json.dumps(
            {
                "output": str(output_path),
                "excluded_candidate_count": len(prepared.records),
                "selected_candidate_count": len(prepared.selected_candidate_ids),
                "paid_activity_requested": False,
                "paid_activity_executed": False,
            },
            sort_keys=True,
        )
    )
    return 0


def _verify_replacement_exclusion_card(
    *,
    run_card_path: Path,
    output_path: Path,
    selection_path: Path,
    screened_cases_path: Path,
) -> tuple[JsonRecord, ...]:
    card_bytes = _read_singly_linked_regular_input(
        run_card_path, label="replacement successor exclusion run card"
    )
    card = _projection_json_object(card_bytes, source=run_card_path)
    if (
        card.get("schema_version") != _REPLACEMENT_EXCLUSION_CARD_SCHEMA
        or card.get("stage") != "build-replacement-exclusions"
        or card.get("status") != "completed"
        or card.get("dry_run") is not False
        or card.get("execute") is not True
        or card.get("paid_activity_requested") is not False
        or card.get("paid_activity_executed") is not False
        or card.get("provider_activity_requested") is not False
        or card.get("provider_activity_executed") is not False
    ):
        raise CommandError("invalid completed replacement successor exclusion card")
    raw_inputs = card.get("input_paths")
    if not isinstance(raw_inputs, Sequence) or isinstance(raw_inputs, (str, bytes)):
        raise CommandError("replacement successor exclusion card lacks exact inputs")
    inputs = tuple(Path(str(value)) for value in cast(Sequence[object], raw_inputs))
    if (
        len(inputs) < 5
        or inputs[1].resolve() != selection_path.resolve()
        or inputs[3].resolve() != screened_cases_path.resolve()
    ):
        raise CommandError("replacement successor exclusion inputs differ")
    source_commitments = card.get("source_commitments")
    if not isinstance(source_commitments, Mapping):
        raise CommandError(
            "replacement successor exclusion card lacks source commitments"
        )
    captured_inputs: dict[str, bytes] = {}
    for path in inputs:
        payload = _read_singly_linked_regular_input(
            path, label="replacement successor exclusion input"
        )
        if cast(Mapping[str, object], source_commitments).get(
            str(path.resolve())
        ) != _bytes_sha256(payload):
            raise CommandError(
                "replacement successor exclusion source commitment changed"
            )
        captured_inputs[os.path.abspath(path)] = payload
    if card.get("output_paths") != [str(output_path)]:
        raise CommandError("replacement successor exclusion output path differs")
    output_bytes = _read_singly_linked_regular_input(
        output_path, label="replacement successor exclusions"
    )
    if card.get("output_commitments") != {
        str(output_path.resolve()): _bytes_sha256(output_bytes)
    }:
        raise CommandError("replacement successor exclusion output commitment changed")
    projection = verify_completed_target_cohort_projection_for_purchase_approval(
        inputs[0].parent.parent
    )
    verified_projection_bytes = cast(
        Mapping[str, bytes], projection["verified_artifact_bytes"]
    )
    for path in inputs[:3]:
        if (
            verified_projection_bytes.get(os.path.abspath(path))
            != captured_inputs[os.path.abspath(path)]
        ):
            raise CommandError(
                "replacement successor projection changed during exclusion replay"
            )
    replay = _prepare_replacement_exclusions(
        target_root=inputs[0].parent.parent,
        screened_cases_path=inputs[3],
        exclusion_paths=inputs[4:],
        verified_projection=projection,
        captured_source_bytes=captured_inputs,
    )
    records = tuple(_projection_jsonl_records(output_bytes, source=output_path))
    if (
        records != replay.records
        or card.get("record_count") != len(records)
        or card.get("selected_candidate_ids") != list(replay.selected_candidate_ids)
        or card.get("screened_candidate_ids") != list(replay.screened_candidate_ids)
    ):
        raise CommandError("replacement successor exclusions do not reproduce")
    return records


def _replacement_finalization_exclusion_groups(
    *,
    exclusion_paths: Sequence[Path],
    replacement_exclusion_card_path: Path | None,
    selection_path: Path,
    screened_cases_path: Path,
) -> tuple[list[JsonRecord], ...]:
    matching_successor_sources = tuple(
        path
        for path in exclusion_paths
        if path.name == "successor-target-exclusions.jsonl"
    )
    if replacement_exclusion_card_path is None:
        if matching_successor_sources:
            raise CommandError(
                "replacement successor exclusion source requires "
                "--replacement-exclusion-run-card"
            )
        return tuple(_read_records(path) for path in exclusion_paths)
    if len(matching_successor_sources) != 1:
        raise CommandError(
            "replacement finalization requires exactly one successor "
            "target exclusion source"
        )
    successor_path = matching_successor_sources[0]
    successor_records = _verify_replacement_exclusion_card(
        run_card_path=replacement_exclusion_card_path,
        output_path=successor_path,
        selection_path=selection_path,
        screened_cases_path=screened_cases_path,
    )
    return tuple(
        (
            list(successor_records)
            if path.resolve() == successor_path.resolve()
            else _read_records(path)
        )
        for path in exclusion_paths
    )


def _clearance_card_artifact_snapshots(
    card: Mapping[str, object],
) -> tuple[tuple[Path, bytes], tuple[Path, bytes]]:
    sources = card.get("source_commitments")
    if not isinstance(sources, Mapping):
        raise ClearanceReplacementError(
            "replacement clearance run card lacks source commitments"
        )
    try:
        manifest = _packet_card_committed_snapshot(
            cast(Mapping[str, object], sources),
            name="download_manifest",
        )
        restrictions = _packet_card_committed_snapshot(
            cast(Mapping[str, object], sources),
            name="restriction_evidence",
        )
    except CommandError as exc:
        raise ClearanceReplacementError(str(exc)) from exc
    return manifest, restrictions


def _merge_exact_document_records(
    groups: Sequence[Sequence[Mapping[str, Any]]], *, label: str
) -> tuple[JsonRecord, ...]:
    merged: dict[tuple[str, str], JsonRecord] = {}
    for group in groups:
        for record in group:
            key = _materializer_record_key(record)
            current = dict(record)
            previous = merged.get(key)
            if previous is not None and previous != current:
                raise ClearanceReplacementError(
                    f"cumulative replacement {label} conflicts for {key[0]}/{key[1]}"
                )
            merged[key] = current
    return tuple(merged[key] for key in sorted(merged))


def _verified_accumulated_replacement_clearance(
    *,
    clearance_path: Path,
    run_card_path: Path,
    clearance_bytes: bytes,
    run_card_bytes: bytes,
) -> list[JsonRecord]:
    card = _projection_json_object(run_card_bytes, source=run_card_path)
    if (
        card.get("schema_version") != _REPLACEMENT_CLEARANCE_ACCUMULATION_SCHEMA
        or card.get("stage") != "accumulate-replacement-clearance"
        or card.get("status") != "completed"
        or card.get("dry_run") is not False
        or card.get("execute") is not True
        or card.get("paid_activity_requested") is not False
        or card.get("paid_activity_executed") is not False
        or card.get("provider_activity_requested") is not False
        or card.get("provider_activity_executed") is not False
    ):
        raise ClearanceReplacementError(
            "invalid completed replacement clearance accumulation card"
        )
    raw_inputs = card.get("input_paths")
    if not isinstance(raw_inputs, Sequence) or isinstance(raw_inputs, (str, bytes)):
        raise ClearanceReplacementError(
            "replacement clearance accumulation lacks exact inputs"
        )
    inputs = tuple(Path(str(value)) for value in cast(Sequence[object], raw_inputs))
    if len(inputs) != 8:
        raise ClearanceReplacementError(
            "replacement clearance accumulation input paths differ"
        )
    source_commitments = card.get("input_commitments")
    if not isinstance(source_commitments, Mapping):
        raise ClearanceReplacementError(
            "replacement clearance accumulation lacks input commitments"
        )
    source_bytes: dict[Path, bytes] = {}
    for path in (inputs[0], inputs[1], inputs[2], inputs[3], inputs[4], inputs[7]):
        payload = _read_singly_linked_regular_input(
            path, label="replacement clearance accumulation input"
        )
        if cast(Mapping[str, object], source_commitments).get(
            str(path.resolve())
        ) != _bytes_sha256(payload):
            raise ClearanceReplacementError(
                "replacement clearance accumulation input commitment changed"
            )
        source_bytes[path] = payload
    prior = _verify_replacement_clearance_evidence(
        clearance_bytes=source_bytes[inputs[0]],
        clearance_path=inputs[0],
        run_card_bytes=source_bytes[inputs[1]],
        run_card_path=inputs[1],
    )
    current = _verify_replacement_clearance_evidence(
        clearance_bytes=source_bytes[inputs[2]],
        clearance_path=inputs[2],
        run_card_bytes=source_bytes[inputs[3]],
        run_card_path=inputs[3],
    )
    merged_clearance = _merge_exact_document_records(
        (prior, current), label="clearance"
    )
    output_root = clearance_path.parent
    manifest_path = output_root / "purchased-document-downloads.jsonl"
    restriction_path = output_root / "restriction-evidence.jsonl"
    expected_outputs = (
        manifest_path,
        clearance_path,
        restriction_path,
    )
    raw_outputs = card.get("output_paths")
    if (
        not isinstance(raw_outputs, Sequence)
        or isinstance(raw_outputs, (str, bytes))
        or tuple(
            Path(str(value)).resolve() for value in cast(Sequence[object], raw_outputs)
        )
        != tuple(path.resolve() for path in expected_outputs)
    ):
        raise ClearanceReplacementError(
            "replacement clearance accumulation output paths differ"
        )
    prior_card = _projection_json_object(source_bytes[inputs[1]], source=inputs[1])
    current_card = _projection_json_object(source_bytes[inputs[3]], source=inputs[3])
    (
        (prior_manifest_path, prior_manifest_bytes),
        (
            prior_restriction_path,
            prior_restriction_bytes,
        ),
    ) = _clearance_card_artifact_snapshots(prior_card)
    (
        (current_manifest_path, current_manifest_bytes),
        (
            current_restriction_path,
            current_restriction_bytes,
        ),
    ) = _clearance_card_artifact_snapshots(current_card)
    merged_manifest = _merge_exact_document_records(
        (
            _projection_jsonl_records(prior_manifest_bytes, source=prior_manifest_path),
            _projection_jsonl_records(
                current_manifest_bytes, source=current_manifest_path
            ),
        ),
        label="manifest",
    )
    merged_restrictions = _merge_exact_document_records(
        (
            _projection_jsonl_records(
                prior_restriction_bytes, source=prior_restriction_path
            ),
            _projection_jsonl_records(
                current_restriction_bytes, source=current_restriction_path
            ),
        ),
        label="restriction evidence",
    )
    expected_payloads = {
        manifest_path: _projection_jsonl_bytes(merged_manifest),
        clearance_path: _projection_jsonl_bytes(merged_clearance),
        restriction_path: _projection_jsonl_bytes(merged_restrictions),
    }
    output_commitments = card.get("output_commitments")
    if not isinstance(output_commitments, Mapping):
        raise ClearanceReplacementError(
            "replacement clearance accumulation lacks output commitments"
        )
    for path, expected in expected_payloads.items():
        observed = (
            clearance_bytes
            if path == clearance_path
            else read_unique_regular_file(path)
        )
        if observed != expected or cast(Mapping[str, object], output_commitments).get(
            path.name
        ) != _bytes_sha256(expected):
            raise ClearanceReplacementError(
                "replacement clearance accumulation does not reproduce"
            )
    if card.get("record_count") != len(merged_clearance):
        raise ClearanceReplacementError(
            "replacement clearance accumulation record count differs"
        )
    return list(merged_clearance)


def _cmd_accumulate_replacement_clearance(args: argparse.Namespace) -> int:
    output_root = cast(Path, args.output_root).absolute()
    input_paths = (
        cast(Path, args.prior_purchased_clearance).absolute(),
        cast(Path, args.prior_clearance_run_card).absolute(),
        cast(Path, args.current_purchased_clearance).absolute(),
        cast(Path, args.current_clearance_run_card).absolute(),
        cast(Path, args.purchase_policy).absolute(),
        cast(Path, args.purchase_ledger).resolve(),
        cast(Path, args.controlled_private_root).absolute(),
        cast(Path, args.purchase_ledger_initialization_receipt).absolute(),
    )
    manifest_path = output_root / "purchased-document-downloads.jsonl"
    clearance_path = output_root / "disclosure-clearance.jsonl"
    restriction_path = output_root / "restriction-evidence.jsonl"
    run_card_path = (
        cast(Path, args.run_card_output).absolute()
        if args.run_card_output is not None
        else output_root / "run-cards" / "accumulate-replacement-clearance.json"
    )
    try:
        source_bytes = {
            path: _read_singly_linked_regular_input(
                path, label="replacement clearance accumulation input"
            )
            for path in (
                input_paths[0],
                input_paths[1],
                input_paths[2],
                input_paths[3],
                input_paths[4],
                input_paths[7],
            )
        }
        prior = _verify_replacement_clearance_evidence(
            clearance_bytes=source_bytes[input_paths[0]],
            clearance_path=input_paths[0],
            run_card_bytes=source_bytes[input_paths[1]],
            run_card_path=input_paths[1],
        )
        current = _verify_replacement_clearance_evidence(
            clearance_bytes=source_bytes[input_paths[2]],
            clearance_path=input_paths[2],
            run_card_bytes=source_bytes[input_paths[3]],
            run_card_path=input_paths[3],
        )
        merged_clearance = _merge_exact_document_records(
            (prior, current), label="clearance"
        )
        prior_card = _projection_json_object(
            source_bytes[input_paths[1]], source=input_paths[1]
        )
        current_card = _projection_json_object(
            source_bytes[input_paths[3]], source=input_paths[3]
        )
        (
            (prior_manifest, prior_manifest_bytes),
            (
                prior_restriction,
                prior_restriction_bytes,
            ),
        ) = _clearance_card_artifact_snapshots(prior_card)
        (
            (current_manifest, current_manifest_bytes),
            (
                current_restriction,
                current_restriction_bytes,
            ),
        ) = _clearance_card_artifact_snapshots(current_card)
        merged_manifest = _merge_exact_document_records(
            (
                _projection_jsonl_records(prior_manifest_bytes, source=prior_manifest),
                _projection_jsonl_records(
                    current_manifest_bytes, source=current_manifest
                ),
            ),
            label="manifest",
        )
        merged_restrictions = _merge_exact_document_records(
            (
                _projection_jsonl_records(
                    prior_restriction_bytes, source=prior_restriction
                ),
                _projection_jsonl_records(
                    current_restriction_bytes, source=current_restriction
                ),
            ),
            label="restriction evidence",
        )
        policy = verify_case_dev_purchase_policy(
            _projection_json_object(source_bytes[input_paths[4]], source=input_paths[4])
        )
        require_approved_case_dev_purchase_policy(
            policy, controlled_private_root=input_paths[6]
        )
        snapshot = read_case_dev_purchase_snapshot(
            input_paths[5],
            policy=policy,
            controlled_private_root=input_paths[6],
            initialization_receipt_path=input_paths[7],
        )
        confirmed_keys = {
            (
                _required_str(operation, "candidate_id"),
                _required_str(operation, "source_document_id"),
            )
            for operation in snapshot.operations
            if operation.get("status") == "confirmed"
        }
        clearance_keys = {
            _materializer_record_key(record) for record in merged_clearance
        }
        if clearance_keys != confirmed_keys:
            raise ClearanceReplacementError(
                "cumulative purchased clearance does not exactly cover confirmed "
                "purchase operations"
            )
        if {
            _materializer_record_key(record) for record in merged_manifest
        } != confirmed_keys or {
            _materializer_record_key(record) for record in merged_restrictions
        } != confirmed_keys:
            raise ClearanceReplacementError(
                "cumulative purchased manifest or restriction coverage differs"
            )
        payloads = {
            manifest_path: _projection_jsonl_bytes(merged_manifest),
            clearance_path: _projection_jsonl_bytes(merged_clearance),
            restriction_path: _projection_jsonl_bytes(merged_restrictions),
        }
        card: JsonRecord = {
            "schema_version": _REPLACEMENT_CLEARANCE_ACCUMULATION_SCHEMA,
            "stage": "accumulate-replacement-clearance",
            "status": "completed",
            "dry_run": not cast(bool, args.execute),
            "execute": cast(bool, args.execute),
            "resume": cast(bool, args.resume),
            "record_count": len(merged_clearance),
            "input_paths": [str(path) for path in input_paths],
            "output_paths": [str(path) for path in payloads],
            "input_commitments": {
                str(path.resolve()): _bytes_sha256(payload)
                for path, payload in source_bytes.items()
            },
            "source_commitments": {
                "download_manifest": _file_commitment_from_bytes(
                    manifest_path, payloads[manifest_path]
                ),
                "restriction_evidence": _file_commitment_from_bytes(
                    restriction_path, payloads[restriction_path]
                ),
            },
            "output_commitments": {
                path.name: _bytes_sha256(payload) for path, payload in payloads.items()
            },
            "purchase_state_sha256": snapshot.purchase_state_sha256,
            "paid_activity_requested": False,
            "paid_activity_executed": False,
            "provider_activity_requested": False,
            "provider_activity_executed": False,
        }
        if not cast(bool, args.execute):
            print(json.dumps(card, sort_keys=True))
            return 0
        for path, payload in payloads.items():
            _ensure_projection_artifact(path, payload, resume=cast(bool, args.resume))
        _ensure_projection_artifact(
            run_card_path,
            _projection_json_bytes(card),
            resume=cast(bool, args.resume),
        )
        _verified_accumulated_replacement_clearance(
            clearance_path=clearance_path,
            run_card_path=run_card_path,
            clearance_bytes=payloads[clearance_path],
            run_card_bytes=read_unique_regular_file(run_card_path),
        )
    except (
        CaseDevPurchaseLedgerError,
        CaseDevPurchasePolicyError,
        ClearanceReplacementError,
        CommandError,
        OSError,
        UnicodeError,
        ValueError,
    ) as exc:
        raise CommandError(str(exc)) from exc
    print(
        json.dumps(
            {
                "output_root": str(output_root),
                "record_count": len(merged_clearance),
                "paid_activity_requested": False,
                "paid_activity_executed": False,
            },
            sort_keys=True,
        )
    )
    return 0


def _verify_replacement_clearance_evidence(
    *,
    clearance_bytes: bytes,
    clearance_path: Path,
    run_card_bytes: bytes,
    run_card_path: Path,
) -> list[JsonRecord]:
    """Authenticate purchased-clearance bytes before replacement planning."""

    run_card = _projection_json_object(run_card_bytes, source=run_card_path)
    if run_card.get("schema_version") == _REPLACEMENT_CLEARANCE_ACCUMULATION_SCHEMA:
        return _verified_accumulated_replacement_clearance(
            clearance_path=clearance_path,
            run_card_path=run_card_path,
            clearance_bytes=clearance_bytes,
            run_card_bytes=run_card_bytes,
        )
    sources = run_card.get("source_commitments")
    if not isinstance(sources, Mapping):
        raise ClearanceReplacementError(
            "replacement clearance run card lacks source commitments"
        )
    try:
        manifest_path = _materializer_committed_path(
            cast(Mapping[str, object], sources), "download_manifest"
        )
        restriction_path = _materializer_committed_path(
            cast(Mapping[str, object], sources), "restriction_evidence"
        )
        snapshot = _capture_clearance_artifact_snapshot(
            run_card=run_card,
            run_card_path=run_card_path,
            clearance_path=clearance_path,
            initial_artifact_bytes={
                os.path.abspath(run_card_path): run_card_bytes,
                os.path.abspath(clearance_path): clearance_bytes,
            },
        )
        _verify_authenticated_clearance_run_card(
            clearance_path=clearance_path,
            clearance_run_card_path=run_card_path,
            expected_download_manifest_path=manifest_path,
            expected_restriction_path=restriction_path,
            captured_artifact_bytes=snapshot,
        )
    except (CommandError, OSError, ValueError) as exc:
        raise ClearanceReplacementError(str(exc)) from exc
    return _projection_jsonl_records(clearance_bytes, source=clearance_path)


