def _require_exact100_v2_authority_payload(payload: bytes, *, surface: str) -> None:
    expected = _EXACT100_V2_AUTHORITY_SHA256[surface]
    if _bytes_sha256(payload) != expected:
        raise CommandError(f"exact100 v2 {surface} differs from sealed authority")


def _replay_exact100_v2_predecessor_surface(
    root: Path,
) -> tuple[dict[str, tuple[JsonRecord, ...]], dict[Path, bytes]]:
    """Bind the frozen root-30 outputs while root 32 proves live completeness."""

    output_names = (
        "target-cohort-selection.jsonl",
        "target-cohort-projection.json",
        "case-relevance.jsonl",
        "core-filter-results.jsonl",
    )
    run_card_path = root / "run-cards/project-target-cohort.json"
    snapshots = {
        path: _read_singly_linked_regular_input(
            path, label="exact100 v2 predecessor surface"
        )
        for path in (run_card_path, *(root / name for name in output_names))
    }
    _require_exact100_v2_authority_payload(
        snapshots[run_card_path], surface="predecessor_run_card"
    )
    _require_exact100_v2_authority_payload(
        snapshots[root / "target-cohort-selection.jsonl"],
        surface="predecessor_selection",
    )
    _require_exact100_v2_authority_payload(
        snapshots[root / "target-cohort-projection.json"],
        surface="predecessor_projection",
    )
    run_card = _projection_json_object(snapshots[run_card_path], source=run_card_path)
    projection_path = root / "target-cohort-projection.json"
    projection = _projection_json_object(
        snapshots[projection_path], source=projection_path
    )
    run_commitments = _mapping(
        run_card.get("output_commitments"), "exact100 v2 predecessor commitments"
    )
    projection_commitments = _mapping(
        projection.get("output_commitments"),
        "exact100 v2 predecessor projection commitments",
    )
    if (
        run_card.get("schema_version") != ZERO_COST_SUCCESSOR_STATE_SCHEMA
        or run_card.get("stage") != "project-zero-cost-successor"
        or run_card.get("status") != "completed"
        or run_card.get("selected_case_count") != 100
        or projection.get("schema_version") != str(ZERO_COST_SUCCESSOR_CONFIG_V1)
    ):
        raise CommandError("exact100 v2 predecessor card differs")
    for name in output_names:
        payload = snapshots[root / name]
        commitment = _bytes_sha256(payload)
        if run_commitments.get(name) != commitment or (
            name != "target-cohort-projection.json"
            and projection_commitments.get(name) != commitment
        ):
            raise CommandError(f"exact100 v2 predecessor output changed: {name}")
    selection_path = root / "target-cohort-selection.jsonl"
    case_relevance_path = root / "case-relevance.jsonl"
    core_path = root / "core-filter-results.jsonl"
    selection = tuple(
        _projection_jsonl_records(snapshots[selection_path], source=selection_path)
    )
    if len(selection) != 100:
        raise CommandError("exact100 v2 predecessor selection count differs")
    return (
        {
            "selection": selection,
            "case_relevance": tuple(
                _projection_jsonl_records(
                    snapshots[case_relevance_path], source=case_relevance_path
                )
            ),
            "core_filter": tuple(
                _projection_jsonl_records(snapshots[core_path], source=core_path)
            ),
        },
        snapshots,
    )


def _replay_exact100_successor_replacement_v2_inputs(
    args: argparse.Namespace,
) -> tuple[
    VerifiedExact100V2Base,
    VerifiedPostSelectionTerminalExclusions,
    VerifiedExact100SuccessorSemanticRepairs,
    VerifiedExact100SuccessorWiderRank,
]:
    """Authenticate the complete provider-free v2 replacement horizon."""

    predecessor_root = cast(Path, args.predecessor_root).absolute()
    materialization_root = cast(Path, args.complete_materialization_root).absolute()
    stipulated_root = cast(Path, args.stipulated_evidence_root).absolute()
    final153_snapshot = cast(Path, args.final153_snapshot).absolute()
    wider_plan_root = cast(Path, args.wider_plan_root).absolute()
    wider_exclusion_root = cast(Path, args.wider_exclusion_root).absolute()
    historical_root = cast(Path, args.historical_packet_root).absolute()

    predecessor_surface, predecessor_snapshots = (
        _replay_exact100_v2_predecessor_surface(predecessor_root)
    )
    predecessor_selection = predecessor_surface["selection"]
    predecessor_selection_bytes = predecessor_snapshots[
        predecessor_root / "target-cohort-selection.jsonl"
    ]
    audit_card_path = (
        stipulated_root / "run-cards/audit-stage-a-target-eligibility.json"
    )
    audit_card_bytes = _read_singly_linked_regular_input(
        audit_card_path, label="v2 stipulated eligibility audit run card"
    )
    _require_exact100_v2_authority_payload(
        audit_card_bytes, surface="stipulated_audit_run_card"
    )
    audit_card = _projection_json_object(audit_card_bytes, source=audit_card_path)
    replay_paths = _mapping(
        audit_card.get("replay_paths"), "v2 stipulated eligibility replay paths"
    )
    controlled_private_root = Path(
        _required_str(replay_paths, "controlled_private_root")
    )
    initialization_receipt = Path(
        _required_str(replay_paths, "purchase_ledger_initialization_receipt")
    )

    materialized_root = materialization_root / "01-materialized"
    materialization_card_path = (
        materialized_root / "run-cards/materialize-cohort-documents.json"
    )
    materialization_manifest_path = (
        materialized_root / "document-downloads-merged.jsonl"
    )
    _require_exact100_v2_authority_payload(
        _read_singly_linked_regular_input(
            materialization_card_path,
            label="exact100 v2 materialization authority run card",
        ),
        surface="materialization_run_card",
    )
    _require_exact100_v2_authority_payload(
        _read_singly_linked_regular_input(
            materialization_manifest_path,
            label="exact100 v2 materialization authority manifest",
        ),
        surface="materialization_manifest",
    )
    verified_materialization = _verify_materialized_downstream_lineage(
        run_card_path=materialization_card_path,
        manifest_path=materialization_manifest_path,
        clearance_path=materialized_root / "disclosure-clearance.jsonl",
        document_root=materialized_root / "documents",
        selection_path=predecessor_root / "target-cohort-selection.jsonl",
        controlled_private_root=controlled_private_root,
        initialization_receipt_path=initialization_receipt,
    )
    closure = _VERIFIED_PROJECTION_BYTE_COLLECTOR.get()
    if closure is not None:
        materialization_snapshots = {
            **dict(verified_materialization.artifact_bytes),
            **{
                os.path.abspath(materialized_root / "documents" / relative): payload
                for relative, payload in verified_materialization.document_tree.items()
            },
        }
        for path, payload in materialization_snapshots.items():
            existing = closure.get(path)
            if existing is not None and existing != payload:
                raise CommandError("verified projection byte closure conflicts")
            closure[path] = payload
    if tuple(verified_materialization.selection_records) != predecessor_selection:
        raise CommandError("v2 complete materialization selection differs")
    restriction_path = materialized_root / "restriction-evidence.jsonl"
    restriction_bytes = verified_materialization.artifact_bytes.get(
        os.path.abspath(restriction_path)
    )
    if not isinstance(restriction_bytes, bytes):
        raise CommandError("v2 complete materialization lacks restriction evidence")
    restriction_records = _projection_jsonl_records(
        restriction_bytes, source=restriction_path
    )
    base = _mint_verified_exact100_v2_base(
        predecessor_projection_bytes=predecessor_snapshots[
            predecessor_root / "target-cohort-projection.json"
        ],
        selection_rows=predecessor_selection,
        case_relevance_rows=predecessor_surface["case_relevance"],
        download_manifest_rows=verified_materialization.manifest_records,
        disclosure_rows=verified_materialization.clearance_records,
        restriction_rows=restriction_records,
        core_filter_rows=predecessor_surface["core_filter"],
        source_commitments={
            "predecessor_projection": _bytes_sha256(
                predecessor_snapshots[
                    predecessor_root / "target-cohort-projection.json"
                ]
            ),
            "predecessor_selection": _bytes_sha256(predecessor_selection_bytes),
            "complete_materialization_run_card": _bytes_sha256(
                verified_materialization.artifact_bytes[
                    os.path.abspath(
                        materialized_root
                        / "run-cards/materialize-cohort-documents.json"
                    )
                ]
            ),
            "complete_materialization_document_tree": _bytes_sha256(
                _projection_json_bytes(
                    {
                        path: _bytes_sha256(payload)
                        for path, payload in sorted(
                            verified_materialization.document_tree.items()
                        )
                    }
                )
            ),
        },
    )

    final153_rows, final153_snapshots = _replay_exact100_v2_snapshot(
        final153_snapshot,
        authority_surface="final153_manifest",
        expected_count=153,
    )
    wider_rows, wider_plan_snapshots = _replay_exact100_v2_public_plan(
        plan_root=wider_plan_root / "01-public-plan",
        snapshot_root=final153_snapshot,
        expected_target_count=153,
        authority_prefix="wider_plan",
        snapshot_authority_surface="final153_manifest",
        snapshot_expected_count=153,
        expected_candidate_count=153,
    )
    exclusion_path = wider_exclusion_root / "successor-target-exclusions.jsonl"
    exclusion_card_path = (
        wider_exclusion_root / "run-cards/build-replacement-exclusions.json"
    )
    _require_exact100_v2_authority_payload(
        _read_singly_linked_regular_input(
            exclusion_card_path, label="exact100 v2 wider-exclusion run card"
        ),
        surface="wider_exclusion_run_card",
    )
    _require_exact100_v2_authority_payload(
        _read_singly_linked_regular_input(
            exclusion_path, label="exact100 v2 wider exclusions"
        ),
        surface="wider_exclusions",
    )
    exclusion_rows = _verify_replacement_exclusion_card(
        run_card_path=exclusion_card_path,
        output_path=exclusion_path,
        selection_path=predecessor_root / "target-cohort-selection.jsonl",
        screened_cases_path=final153_snapshot / "screened-cases.jsonl",
    )

    (
        historical_rows,
        historical_manifest,
        historical_document_bytes,
        historical_snapshots,
    ) = _replay_exact100_v2_historical_packet(historical_root)
    historical_roles: dict[str, set[str]] = defaultdict(set)
    for record in historical_manifest:
        historical_roles[_required_str(record, "candidate_id")].add(
            _required_str(record, "document_role")
        )
    repair_source_ids = {
        candidate_id
        for candidate_id, roles in historical_roles.items()
        if {
            "complaint",
            "motion_to_dismiss_notice",
            "opposition",
            "decision",
        }
        <= roles
    }
    if len(repair_source_ids) != 1:
        raise CommandError(
            "historical packet must contain one complete semantic-repair surface"
        )
    repair_source_id = next(iter(repair_source_ids))
    semantic_source_manifest = tuple(
        record
        for record in historical_manifest
        if _required_str(record, "candidate_id") == repair_source_id
    )
    repairs = _mint_verified_exact100_successor_semantic_repairs(
        document_records=semantic_source_manifest,
        document_bytes_by_key={
            (
                _required_str(record, "candidate_id"),
                _required_str(record, "source_document_id"),
            ): historical_document_bytes[_required_str(record, "local_path")]
            for record in semantic_source_manifest
        },
    )
    repaired_ids = {_required_str(record, "candidate_id") for record in repairs.records}
    if len(repairs.records) != 2 or len(repaired_ids) != 1:
        raise CommandError(
            "historical packet must yield exactly one two-role semantic repair"
        )
    repaired_id = next(iter(repaired_ids))
    selected_historical_rows = tuple(
        row
        for row in historical_rows
        if _required_str(row, "candidate_id") == repaired_id
    )
    if len(selected_historical_rows) != 1:
        raise CommandError("semantic repair candidate lacks one historical plan row")
    historical_selection = selected_historical_rows[0]
    candidate_manifest = tuple(
        row
        for row in historical_manifest
        if _required_str(row, "candidate_id") == repaired_id
    )
    if len(candidate_manifest) != 5:
        raise CommandError("semantic repair candidate lacks its five-document packet")
    candidate_bytes = {
        _required_str(row, "local_path"): historical_document_bytes[
            _required_str(row, "local_path")
        ]
        for row in candidate_manifest
    }
    restriction_records, clearance_records = _exact100_v2_provider_free_clearance(
        selection=historical_selection,
        manifest=candidate_manifest,
        document_root=historical_root / "documents",
        document_bytes=candidate_bytes,
    )
    effective_relevance = _exact100_v2_effective_relevance(
        historical_selection, repairs.records
    )
    core_rows = tuple(
        result.to_record() for result in filter_core_documents((effective_relevance,))
    )

    exact_ids = {_required_str(row, "candidate_id") for row in predecessor_selection}
    exclusion_ids = {_required_str(row, "candidate_id") for row in exclusion_rows}
    materialized_by_id = {
        _required_str(row, "candidate_id"): dict(row) for row in wider_rows
    }
    if set(materialized_by_id) != {
        _required_str(_mapping(row.get("candidate"), "final153 candidate"), "docket_id")
        for row in final153_rows
    }:
        raise CommandError("v2 wider public plan does not cover the final153 snapshot")
    materialized_nonselected = tuple(
        materialized_by_id[candidate_id] for candidate_id in sorted(exclusion_ids)
    )
    if set(materialized_by_id) != exact_ids | exclusion_ids:
        raise CommandError("v2 exact100 and wider exclusions do not partition final153")

    identity_rows = tuple(
        {
            "snapshot_candidate_id": _required_str(row, "candidate_id"),
            "canonical_candidate_id": _required_str(
                _mapping(row.get("candidate"), "final153 candidate"), "docket_id"
            ),
            "snapshot_row_sha256": str(
                ARTIFACT_RAW_SHA256_V1.commit(
                    row,
                    domain=EXACT100_SUCCESSOR_WIDER_RANK_LEDGER_V1,
                ).digest
            ),
        }
        for row in final153_rows
    )
    wider = _mint_verified_exact100_successor_wider_rank(
        final153_rows=final153_rows,
        exact100_rows=predecessor_selection,
        exclusion_rows=exclusion_rows,
        materialized_selection_rows=materialized_nonselected,
        case_relevance_rows=(historical_selection,),
        download_manifest_rows=candidate_manifest,
        disclosure_rows=clearance_records,
        restriction_rows=restriction_records,
        core_filter_rows=core_rows,
        identity_mapping_rows=identity_rows,
        semantic_repair_rows=repairs.records,
        source_commitments={
            "final153_snapshot": _bytes_sha256(
                final153_snapshots[final153_snapshot / "manifest.json"]
            ),
            "wider_public_plan": _bytes_sha256(_projection_jsonl_bytes(wider_rows)),
            "wider_exclusions": _path_sha256(exclusion_path),
            "historical_public_plan": _bytes_sha256(
                _projection_jsonl_bytes(historical_rows)
            ),
            "historical_download_manifest": _bytes_sha256(
                historical_snapshots[historical_root / "free-document-downloads.jsonl"]
            ),
        },
    )
    if wider.selected_candidate_id != repaired_id:
        raise CommandError(
            "deterministic wider rank did not select the semantic repair candidate"
        )

    terminal_evidence = _replay_exact100_stipulated_eligibility_unchecked(
        stipulated_root, predecessor_selection_bytes
    )
    terminal = verify_post_selection_terminal_exclusions(
        selection_bytes=predecessor_selection_bytes,
        evidence=(terminal_evidence,),
    )
    if terminal.candidate_ids != (_EXACT100_V2_TERMINAL_CANDIDATE_ID,):
        raise CommandError(
            "exact100 v2 terminal candidate differs from sealed authority"
        )

    _require_snapshot_unchanged(
        {
            audit_card_path: audit_card_bytes,
            **final153_snapshots,
            **wider_plan_snapshots,
            **historical_snapshots,
            **predecessor_snapshots,
        },
        label="exact100 v2 authenticated replay input",
    )
    _require_materialized_downstream_lineage_unchanged(
        verified_materialization,
        document_root=materialized_root / "documents",
    )
    return base, terminal, repairs, wider


def _replay_exact100_v2_snapshot(
    snapshot_root: Path, *, authority_surface: str, expected_count: int | None
) -> tuple[tuple[JsonRecord, ...], dict[Path, bytes]]:
    manifest_path = snapshot_root / "manifest.json"
    screened_path = snapshot_root / "screened-cases.jsonl"
    manifest_bytes = _read_singly_linked_regular_input(
        manifest_path, label=f"exact100 v2 {authority_surface} manifest"
    )
    _require_exact100_v2_authority_payload(manifest_bytes, surface=authority_surface)
    screened_bytes = _read_singly_linked_regular_input(
        screened_path, label=f"exact100 v2 {authority_surface} screened cases"
    )
    manifest = _projection_json_object(manifest_bytes, source=manifest_path)
    verified = load_verified_screening_snapshot(
        snapshot_root,
        expected_manifest_sha256=hashlib.sha256(manifest_bytes).hexdigest(),
        expected_cycle_hash=_required_str(manifest, "cycle_hash"),
    )
    rows = tuple(_projection_jsonl_records(screened_bytes, source=screened_path))
    if (
        not rows
        or len(rows) != len(verified.screened)
        or (expected_count is not None and len(rows) != expected_count)
    ):
        raise CommandError(
            f"exact100 v2 {authority_surface} authenticated snapshot count differs"
        )
    return rows, {manifest_path: manifest_bytes, screened_path: screened_bytes}


def _replay_exact100_v2_public_plan(
    *,
    plan_root: Path,
    snapshot_root: Path,
    expected_target_count: int,
    authority_prefix: str,
    snapshot_authority_surface: str,
    snapshot_expected_count: int | None,
    expected_candidate_count: int | None,
) -> tuple[tuple[JsonRecord, ...], dict[Path, bytes]]:
    run_card_path = plan_root / "run-cards/plan-public-downloads.json"
    summary_path = plan_root / "public-packet-plan-summary.json"
    output_paths = {
        "requests": plan_root / "free-document-requests.jsonl",
        "selection": plan_root / "public-packet-selection.jsonl",
        "paid_gaps": plan_root / "public-packet-paid-gaps.jsonl",
        "exclusions": plan_root / "public-packet-exclusions.jsonl",
    }
    snapshots = {
        path: _read_singly_linked_regular_input(path, label="exact100 v2 public plan")
        for path in (run_card_path, summary_path, *output_paths.values())
    }
    _require_exact100_v2_authority_payload(
        snapshots[run_card_path], surface=f"{authority_prefix}_run_card"
    )
    _require_exact100_v2_authority_payload(
        snapshots[summary_path], surface=f"{authority_prefix}_summary"
    )
    card = _projection_json_object(snapshots[run_card_path], source=run_card_path)
    summary = _projection_json_object(snapshots[summary_path], source=summary_path)
    raw_inputs = card.get("input_paths")
    if not isinstance(raw_inputs, Sequence) or isinstance(raw_inputs, (str, bytes)):
        raise CommandError("exact100 v2 public-plan run card lacks inputs")
    input_paths = tuple(
        Path(str(value)) for value in cast(Sequence[object], raw_inputs)
    )
    if (
        not input_paths
        or input_paths[0].resolve() != snapshot_root.resolve()
        or card.get("stage") != "plan-public-downloads"
        or card.get("status") != "completed"
        or card.get("dry_run") is not False
        or card.get("execute") is not True
        or card.get("paid_activity_requested") is not False
        or card.get("paid_activity_executed") is not False
        or card.get("target_clean_cases") != expected_target_count
        or summary.get("use_embedded_entries") is not True
    ):
        raise CommandError("exact100 v2 public-plan run card differs")
    snapshot_rows, snapshot_files = _replay_exact100_v2_snapshot(
        snapshot_root,
        authority_surface=snapshot_authority_surface,
        expected_count=snapshot_expected_count,
    )
    raw_html_bytes: Mapping[str, bytes] | None = None
    screened_pin = summary.get("authenticated_screened_cases_sha256")
    raw_manifest_pin = summary.get("authenticated_raw_html_manifest_sha256")
    if isinstance(screened_pin, str) and isinstance(raw_manifest_pin, str):
        if len(input_paths) < 4:
            raise CommandError("exact100 v2 authenticated public-plan inputs differ")
        (
            authenticated_rows,
            authenticated_screened_bytes,
            _,
            raw_html_bytes,
            _,
        ) = _read_authenticated_bridge_inputs(
            screened_cases_path=input_paths[1],
            expected_screened_cases_sha256=screened_pin.removeprefix("sha256:"),
            public_first=True,
            raw_html_dir=input_paths[2],
            raw_html_manifest_path=input_paths[3],
            expected_raw_html_manifest_sha256=raw_manifest_pin.removeprefix("sha256:"),
        )
        if tuple(authenticated_rows) != snapshot_rows:
            raise CommandError(
                "exact100 v2 authenticated screened cases differ from snapshot"
            )
        snapshot_files[input_paths[1]] = authenticated_screened_bytes
        snapshot_files[input_paths[3]] = _read_singly_linked_regular_input(
            input_paths[3], label="exact100 v2 raw HTML manifest"
        )
        if raw_html_bytes is None:
            raise CommandError("exact100 v2 authenticated raw HTML replay failed")
        snapshot_files.update(
            {
                input_paths[2] / f"{candidate_id}.html": payload
                for candidate_id, payload in raw_html_bytes.items()
            }
        )
    plan = plan_public_packet_downloads(
        snapshot_rows,
        raw_html_bytes_by_candidate=raw_html_bytes,
        target_clean_cases=expected_target_count,
        use_embedded_entries=True,
    )
    expected = {
        "requests": _projection_jsonl_bytes(
            request.to_record() for request in plan.download_requests
        ),
        "selection": _projection_jsonl_bytes(
            candidate.to_record() for candidate in plan.selected_cases
        ),
        "paid_gaps": _projection_jsonl_bytes(
            candidate.to_record() for candidate in plan.paid_gap_cases
        ),
        "exclusions": _projection_jsonl_bytes(
            candidate.to_record() for candidate in plan.final_exclusions
        ),
    }
    if plan.target_clean_cases != expected_target_count:
        raise CommandError("exact100 v2 current public plan target differs")
    rows = tuple(
        record
        for name in ("selection", "paid_gaps", "exclusions")
        for record in _projection_jsonl_records(
            expected[name], source=output_paths[name]
        )
    )
    if not rows or (
        expected_candidate_count is not None and len(rows) != expected_candidate_count
    ):
        raise CommandError("exact100 v2 public plan candidate count differs")
    return rows, {**snapshot_files, **snapshots}


def _replay_exact100_v2_historical_packet(
    root: Path,
) -> tuple[
    tuple[JsonRecord, ...],
    tuple[JsonRecord, ...],
    dict[str, bytes],
    dict[Path, bytes],
]:
    plan_card_path = root / "run-cards/plan-public-downloads.json"
    plan_card_bytes = _read_singly_linked_regular_input(
        plan_card_path, label="exact100 v2 historical public-plan card"
    )
    _require_exact100_v2_authority_payload(
        plan_card_bytes, surface="historical_plan_run_card"
    )
    plan_card = _projection_json_object(plan_card_bytes, source=plan_card_path)
    raw_inputs = plan_card.get("input_paths")
    if not isinstance(raw_inputs, Sequence) or isinstance(raw_inputs, (str, bytes)):
        raise CommandError("historical public-plan card lacks inputs")
    plan_inputs = tuple(
        Path(str(value)) for value in cast(Sequence[object], raw_inputs)
    )
    if len(plan_inputs) != 3:
        raise CommandError("historical public-plan inputs differ")
    plan_rows, plan_snapshots = _replay_exact100_v2_public_plan(
        plan_root=root,
        snapshot_root=plan_inputs[0],
        expected_target_count=_required_int(plan_card, "target_clean_cases"),
        authority_prefix="historical_plan",
        snapshot_authority_surface="historical_snapshot_manifest",
        snapshot_expected_count=None,
        expected_candidate_count=None,
    )
    paid_gaps_path = root / "public-packet-paid-gaps.jsonl"
    paid_gaps_bytes = plan_snapshots[paid_gaps_path]
    _require_exact100_v2_authority_payload(
        paid_gaps_bytes, surface="historical_paid_gaps"
    )
    historical_rows = tuple(
        _projection_jsonl_records(paid_gaps_bytes, source=paid_gaps_path)
    )
    if {_required_str(row, "candidate_id") for row in historical_rows} != {
        _required_str(row, "candidate_id") for row in plan_rows
    }:
        raise CommandError("historical and current public-plan candidates differ")
    requests_path = root / "free-document-requests.jsonl"
    manifest_path = root / "free-document-downloads.jsonl"
    merged_path = root / "document-downloads-merged.jsonl"
    download_card_path = root / "run-cards/download-free.json"
    direct = {
        path: _read_singly_linked_regular_input(path, label="historical free download")
        for path in (requests_path, manifest_path, merged_path, download_card_path)
    }
    _require_exact100_v2_authority_payload(
        direct[download_card_path], surface="historical_download_run_card"
    )
    _require_exact100_v2_authority_payload(
        direct[manifest_path], surface="historical_download_manifest"
    )
    request_records = _projection_jsonl_records(
        direct[requests_path], source=requests_path
    )
    requests = tuple(_free_document_download_request(row) for row in request_records)
    verified_records = verify_completed_free_document_manifest(
        requests,
        output_root=root / "documents",
        manifest_path=manifest_path,
    )
    manifest = tuple(dict(record.to_record()) for record in verified_records)
    if (
        _projection_jsonl_bytes(manifest) != direct[manifest_path]
        or direct[merged_path] != direct[manifest_path]
    ):
        raise CommandError("historical free-document manifests differ")
    download_card = _projection_json_object(
        direct[download_card_path], source=download_card_path
    )
    if (
        download_card.get("stage") != "download-free"
        or download_card.get("status") != "completed"
        or download_card.get("dry_run") is not False
        or download_card.get("execute") is not True
        or download_card.get("paid_activity_requested") is not False
        or download_card.get("paid_activity_executed") is not False
        or download_card.get("record_count") != len(manifest)
    ):
        raise CommandError("historical free-document run card differs")
    document_bytes = {
        _required_str(record, "local_path"): _read_singly_linked_regular_input(
            root / "documents" / _required_str(record, "local_path"),
            label="historical free document",
        )
        for record in manifest
    }
    snapshots = {
        **plan_snapshots,
        **direct,
        **{
            root / "documents" / relative: payload
            for relative, payload in document_bytes.items()
        },
    }
    return historical_rows, manifest, document_bytes, snapshots


def _exact100_v2_provider_free_clearance(
    *,
    selection: Mapping[str, Any],
    manifest: Sequence[Mapping[str, Any]],
    document_root: Path,
    document_bytes: Mapping[str, bytes],
) -> tuple[tuple[JsonRecord, ...], tuple[JsonRecord, ...]]:
    candidate_id = _required_str(selection, "candidate_id")
    selection_documents = {
        _required_str(document, "source_document_id"): document
        for document in cast(Sequence[Mapping[str, Any]], selection["documents"])
    }
    restrictions: list[JsonRecord] = []
    relevance_documents: list[JsonRecord] = []
    requests: list[JsonRecord] = []
    for source in manifest:
        source_id = _required_str(source, "source_document_id")
        selection_document = selection_documents.get(source_id)
        if selection_document is None:
            raise CommandError("historical plan omits a downloaded packet document")
        evidence = ["courtlistener_public_download_record_checked"]
        restrictions.append(
            {
                "candidate_id": candidate_id,
                "source_document_id": source_id,
                "restriction_status": "public",
                "restriction_evidence": evidence,
                "is_sealed": None,
                "is_private": None,
            }
        )
        relevance_documents.append(
            {
                "source_document_id": source_id,
                "source_url_or_reference": _required_str(source, "source_url"),
                "model_visible": selection_document.get("model_visible"),
                "contains_target_outcome": selection_document.get(
                    "contains_target_outcome"
                ),
            }
        )
        requests.append(
            {
                "schema_version": "legalforecast.disclosure_review_request.v1",
                "candidate_id": candidate_id,
                "source_document_id": source_id,
                "sha256": _required_str(source, "sha256"),
                "byte_count": _required_int(source, "byte_count"),
                "free_or_purchased": "free",
                "restriction_status": "public",
                "restriction_evidence": evidence,
                "required_human_decision": "cleared_or_quarantined",
            }
        )
    relevance = ({"candidate_id": candidate_id, "documents": relevance_documents},)
    request_bytes = _projection_jsonl_bytes(requests)
    manifest_bytes = _projection_jsonl_bytes(manifest)
    restriction_bytes = _projection_jsonl_bytes(restrictions)
    relevance_bytes = _projection_jsonl_bytes(relevance)
    plan = build_provenance_clearance_plan(
        requests,
        manifest,
        restrictions,
        relevance,
        document_root=document_root,
        review_requests_bytes=request_bytes,
        download_manifest_bytes=manifest_bytes,
        restriction_evidence_bytes=restriction_bytes,
        case_relevance_bytes=relevance_bytes,
        document_bytes_by_relative_path=document_bytes,
    )
    if plan.get("john_review_count") != 0:
        raise CommandError("historical public packet requires human clearance")
    routing_sha = str(
        ARTIFACT_RAW_SHA256_V1.commit(
            plan,
            domain=DISCLOSURE_CLEARANCE_V1,
        ).digest
    )
    clearance = tuple(
        dict(record.to_record())
        for record in build_provenance_clearance_records(
            plan, (), routing_plan_sha256=routing_sha
        )
    )
    return tuple(restrictions), clearance


def _exact100_v2_effective_relevance(
    selection: Mapping[str, Any], repairs: Sequence[Mapping[str, Any]]
) -> JsonRecord:
    derived = {
        _required_str(record, "source_document_id"): _required_str(
            record, "derived_document_role"
        )
        for record in repairs
    }
    result = dict(selection)
    result["documents"] = [
        {
            **dict(document),
            "document_role": derived.get(
                _required_str(document, "source_document_id"),
                _required_str(document, "document_role"),
            ),
            "setup_runner_label": (
                "core_mtd"
                if document.get("model_visible") is True
                else "other_substantive"
            ),
            "availability_status": "available",
            "requires_paid_recovery": False,
            "source_url_or_reference": _required_str(document, "source_url"),
        }
        for document in cast(Sequence[Mapping[str, Any]], selection["documents"])
    ]
    return result


def _authenticated_projection_snapshot(
    snapshots: Mapping[str, bytes], path: Path, *, label: str
) -> bytes:
    """Return one verifier-owned snapshot with a boundary-specific error."""

    payload = snapshots.get(os.path.abspath(path))
    if not isinstance(payload, bytes):
        raise CommandError(f"authenticated projection lacks {label}")
    return payload


def _exact100_successor_v2_replay_args(
    run_card: Mapping[str, object],
) -> argparse.Namespace:
    """Recover only the seven closed v2 evidence roots from its completed card."""

    raw_inputs = run_card.get("input_paths")
    if not isinstance(raw_inputs, Sequence) or isinstance(raw_inputs, (str, bytes)):
        raise CommandError("exact100 v2 successor run card lacks exact inputs")
    values = tuple(cast(Sequence[object], raw_inputs))
    if len(values) != 7 or not all(
        isinstance(value, str) and value for value in values
    ):
        raise CommandError("exact100 v2 successor input paths differ")
    return argparse.Namespace(
        predecessor_root=Path(cast(str, values[0])),
        complete_materialization_root=Path(cast(str, values[1])),
        stipulated_evidence_root=Path(cast(str, values[2])),
        final153_snapshot=Path(cast(str, values[3])),
        wider_plan_root=Path(cast(str, values[4])),
        wider_exclusion_root=Path(cast(str, values[5])),
        historical_packet_root=Path(cast(str, values[6])),
    )


def _require_zero_cost_successor_commitment_keysets(
    *,
    config_commitments: Mapping[str, object],
    run_card_commitments: Mapping[str, object],
) -> None:
    config_keys = {
        "target-cohort-selection.jsonl",
        "case-relevance.jsonl",
        "document-downloads-merged.jsonl",
        "free-document-downloads.jsonl",
        "purchased-document-downloads.jsonl",
        "disclosure-clearance.jsonl",
        "restriction-evidence.jsonl",
        "core-filter-results.jsonl",
        "missing-core-budget-plan.json",
        "target-cohort-exclusions.jsonl",
        "target-cohort-ranked-reserve.jsonl",
    }
    if set(config_commitments) != config_keys or set(run_card_commitments) != {
        *config_keys,
        "target-cohort-projection.json",
    }:
        raise CommandError("zero-cost successor commitment keyset differs")


def _approved_v4_legacy_quarantine_is_pinned(
    *,
    projection_summary_bytes: bytes,
    projection_run_card_bytes: bytes,
    clearance_run_card_bytes: bytes,
) -> bool:
    """Recognize only the frozen pre-explicit-mode v4 evidence chain."""

    return (
        _bytes_sha256(projection_summary_bytes) == _APPROVED_V4_LEGACY_PROJECTION_SHA256
        and _bytes_sha256(projection_run_card_bytes)
        == _APPROVED_V4_LEGACY_PROJECTION_RUN_CARD_SHA256
        and _bytes_sha256(clearance_run_card_bytes)
        == _APPROVED_V4_LEGACY_CLEARANCE_RUN_CARD_SHA256
    )


def _verify_materializer_projection(
    *,
    target_root: Path,
    free_clearance_path: Path,
    preparation_summary_path: Path,
    preparation_config_path: Path,
    snapshot_manifest_path: Path,
    expected_target_count: int,
    _verified_legacy_ranked_replay: VerifiedLegacyRankedReserveReplay | None = None,
    _verified_clearance_relocations: (Mapping[str, tuple[Path, bytes]] | None) = None,
    _verified_clearance_source_roots: Mapping[str, Path] | None = None,
    _verified_projection_operation: _VerifiedProjectionOperation | None = None,
) -> dict[str, object]:
    run_card_path = target_root / "run-cards/project-target-cohort.json"
    supporting_card_path = (
        target_root / "run-cards/project-exact100-supporting-document-successor.json"
    )
    if supporting_card_path.is_file() and not supporting_card_path.is_symlink():
        return _verify_supporting_document_downstream_projection(
            target_root=target_root,
            free_clearance_path=free_clearance_path,
            expected_target_count=expected_target_count,
        )
    if run_card_path.is_file() and not run_card_path.is_symlink():
        candidate_card = _projection_json_object(
            _read_singly_linked_regular_input(
                run_card_path, label="target projection run card"
            ),
            source=run_card_path,
        )
        if candidate_card.get("schema_version") == ZERO_COST_SUCCESSOR_STATE_SCHEMA:
            return _verify_zero_cost_successor_projection(
                target_root=target_root,
                free_clearance_path=free_clearance_path,
                expected_target_count=expected_target_count,
                _verified_legacy_ranked_replay=_verified_legacy_ranked_replay,
                _verified_clearance_relocations=_verified_clearance_relocations,
                _verified_clearance_source_roots=_verified_clearance_source_roots,
            )
        if candidate_card.get("schema_version") == str(
            EXACT100_SUCCESSOR_REPLACEMENT_STATE_V1
        ):
            try:
                return _mint_verified_successor_selection_card_from_projection(
                    verify_exact100_successor_replacement_projection(
                        target_root=target_root,
                        free_clearance_path=free_clearance_path,
                        expected_target_count=expected_target_count,
                        replay_inputs=_replay_exact100_successor_inputs,
                        recovery_replay=_replay_exact100_terminal_recovery,
                        stipulated_replay=_replay_exact100_stipulated_eligibility,
                    ),
                    replay_attestation=_EXACT100_SUCCESSOR_REPLAY_ATTESTATION,
                )
            except Exact100SuccessorReplacementCliError as exc:
                raise CommandError(str(exc)) from exc
        if candidate_card.get("schema_version") == str(
            EXACT100_SUCCESSOR_REPLACEMENT_STATE_V2
        ):
            if (
                free_clearance_path.resolve()
                != (target_root / "disclosure-clearance.jsonl").resolve()
                or candidate_card.get("selected_case_count") != expected_target_count
            ):
                raise CommandError("exact100 v2 materializer inputs differ")
            try:
                replay_args = _exact100_successor_v2_replay_args(candidate_card)
                return _mint_verified_successor_selection_card_from_projection(
                    verify_exact100_successor_replacement_v2_projection(
                        target_root,
                        replay=_replay_exact100_successor_replacement_v2_inputs,
                        args=replay_args,
                    ),
                    replay_attestation=_EXACT100_SUCCESSOR_V2_REPLAY_ATTESTATION,
                )
            except Exact100SuccessorReplacementV2CliError as exc:
                raise CommandError(str(exc)) from exc
    paths = {name: target_root / name for name in BASE_PROJECTION_ARTIFACT_NAMES}
    output_snapshots = {
        path: _require_materializer_artifact(path, label=f"target projection {label}")
        for label, path in (*paths.items(), ("run card", run_card_path))
    }
    if free_clearance_path.resolve() != paths["disclosure-clearance.jsonl"].resolve():
        raise CommandError(
            "--free-disclosure-clearance must be the exact target projection output"
        )
    run_card_bytes = output_snapshots[run_card_path]
    run_card = _projection_json_object(run_card_bytes, source=run_card_path)
    expected_outputs = tuple(paths.values())
    if (
        run_card.get("schema_version") != "legalforecast.acquisition_run_card.v1"
        or run_card.get("stage") != "project-target-cohort"
        or run_card.get("status") != "completed"
        or run_card.get("dry_run") is not False
        or run_card.get("execute") is not True
        or run_card.get("paid_activity_requested") is not False
        or run_card.get("paid_activity_executed") is not False
        or run_card.get("record_count") != expected_target_count
    ):
        raise CommandError("invalid completed target-cohort projection run card")
    raw_inputs = run_card.get("input_paths")
    if not isinstance(raw_inputs, Sequence) or isinstance(raw_inputs, (str, bytes)):
        raise CommandError("target projection run card lacks input paths")
    projection_inputs = tuple(
        Path(str(path)) for path in cast(Sequence[object], raw_inputs)
    )
    base_input_names = (
        "selection",
        "case_relevance",
        "download_manifest",
        "disclosure_clearance",
        "clearance_run_card",
        "restriction_evidence",
        "preparation_summary",
        "preparation_config",
        "snapshot_manifest",
    )
    replacement_input_names = (
        "replacement_result",
        "replacement_replay_cohort_policy",
        "replacement_replay_purchase_policy",
        "replacement_replay_frontier",
        "replacement_replay_purchase_ledger_initialization_receipt",
        "replacement_replay_purchased_clearance",
        "replacement_replay_clearance_run_card",
        "replacement_replay_tranche_selection",
    )
    replacement_projection = len(projection_inputs) == (
        len(base_input_names) + len(replacement_input_names) + 2
    )
    if len(projection_inputs) != len(base_input_names) and not replacement_projection:
        raise CommandError("target projection run card input paths differ")
    regular_input_names = (
        *base_input_names,
        *(replacement_input_names if replacement_projection else ()),
    )
    source_paths: dict[str, Path] = dict(
        zip(
            regular_input_names,
            projection_inputs[: len(regular_input_names)],
            strict=True,
        )
    )
    expected_lineage_paths = {
        "preparation_summary": preparation_summary_path,
        "preparation_config": preparation_config_path,
        "snapshot_manifest": snapshot_manifest_path,
    }
    for name, expected_path in expected_lineage_paths.items():
        if source_paths[name].resolve() != expected_path.resolve():
            raise CommandError(f"target projection {name} lineage differs")
    source_bytes = {
        name: _require_materializer_artifact(
            path, label=f"target projection input {name}"
        )
        for name, path in source_paths.items()
    }
    source_sha256 = {
        name: _bytes_sha256(payload) for name, payload in source_bytes.items()
    }
    preparation_summary = _projection_json_object(
        source_bytes["preparation_summary"], source=source_paths["preparation_summary"]
    )
    preparation_config = _projection_json_object(
        source_bytes["preparation_config"], source=source_paths["preparation_config"]
    )
    snapshot_manifest = _projection_json_object(
        source_bytes["snapshot_manifest"], source=source_paths["snapshot_manifest"]
    )
    clearance_run_card = _projection_json_object(
        source_bytes["clearance_run_card"], source=source_paths["clearance_run_card"]
    )
    replacement_result: JsonRecord | None = None
    if replacement_projection:
        try:
            replacement_result = _verify_replacement_projection_replay(
                source_paths=source_paths,
                source_bytes=source_bytes,
                controlled_private_root=projection_inputs[-2],
                purchase_ledger_path=projection_inputs[-1],
            )
        except (
            CaseDevPurchaseLedgerError,
            CaseDevPurchasePolicyError,
            ClearanceReplacementError,
            OSError,
            ValueError,
        ) as exc:
            raise CommandError(str(exc)) from exc
        if (
            run_card.get("active_selection_sha256") != source_sha256["selection"]
            or run_card.get("active_selection_count")
            != replacement_result.get("active_selection_count")
            or run_card.get("replacement_result_sha256")
            != source_sha256["replacement_result"]
        ):
            raise CommandError(
                "target projection replacement selection commitment differs"
            )
    legacy_quarantine_is_pinned = _approved_v4_legacy_quarantine_is_pinned(
        projection_summary_bytes=_read_singly_linked_regular_input(
            paths["target-cohort-projection.json"],
            label="target projection summary",
        ),
        projection_run_card_bytes=run_card_bytes,
        clearance_run_card_bytes=source_bytes["clearance_run_card"],
    )
    clearance_snapshot = _capture_clearance_artifact_snapshot(
        run_card=clearance_run_card,
        run_card_path=source_paths["clearance_run_card"],
        clearance_path=source_paths["disclosure_clearance"],
        initial_artifact_bytes={
            os.path.abspath(path): source_bytes[name]
            for name, path in source_paths.items()
        },
    )
    clearance_lineage = _verify_materializer_clearance_lineage(
        manifest_path=source_paths["download_manifest"],
        clearance_path=source_paths["disclosure_clearance"],
        run_card_path=source_paths["clearance_run_card"],
        captured_artifact_bytes=clearance_snapshot,
        # Pre-explicit-mode cards remain readable only through a completed outer
        # projection that matches the frozen approved-v4 summary and run-card pins.
        # New producers and standalone verification keep the default false.
        allow_legacy_implicit_quarantine=legacy_quarantine_is_pinned,
    )
    _validate_projection_source_commitments(
        preparation_summary=preparation_summary,
        preparation_config=preparation_config,
        snapshot_manifest=snapshot_manifest,
        clearance_run_card=clearance_run_card,
        source_paths=source_paths,
        source_sha256=source_sha256,
        target_case_count=expected_target_count,
        cost_per_document_usd=_required_str(
            preparation_config, "cost_per_document_usd"
        ),
        max_projected_budget_usd=_required_str(
            preparation_config, "max_projected_budget_usd"
        ),
        max_missing_core_documents_per_case=_required_int(
            preparation_config, "max_missing_core_documents_per_case"
        ),
        replacement_selection_authorized=replacement_projection,
    )
    raw_outputs = run_card.get("output_paths")
    if not isinstance(raw_outputs, Sequence) or isinstance(raw_outputs, (str, bytes)):
        raise CommandError("target projection run card lacks output paths")
    actual_output_paths = {
        Path(str(path)).resolve() for path in cast(Sequence[object], raw_outputs)
    }
    if actual_output_paths != {path.resolve() for path in expected_outputs} or len(
        cast(Sequence[object], raw_outputs)
    ) != len(expected_outputs):
        raise CommandError("target projection run card output paths differ")
    output_bytes = {
        name: _read_singly_linked_regular_input(
            path, label=f"target projection output {name}"
        )
        for name, path in paths.items()
    }
    commitments = run_card.get("output_commitments")
    if not isinstance(commitments, Mapping):
        raise CommandError("target projection run card lacks output commitments")
    for path in expected_outputs:
        _validate_path_keyed_output_commitment(
            run_card,
            path=path,
            expected_sha256=_bytes_sha256(output_bytes[path.name]),
            label="target projection",
        )

    summary_path = paths["target-cohort-projection.json"]
    summary = _projection_json_object(
        output_bytes["target-cohort-projection.json"], source=summary_path
    )
    if (
        summary.get("schema_version") != "legalforecast.target_cohort_projection.v1"
        or summary.get("target_case_count") != expected_target_count
        or summary.get("selected_case_count") != expected_target_count
        or summary.get("paid_activity_requested") is not False
        or summary.get("paid_activity_executed") is not False
        or summary.get("preparation_summary_sha256")
        != source_sha256["preparation_summary"]
        or summary.get("preparation_config_sha256")
        != source_sha256["preparation_config"]
        or summary.get("snapshot_manifest_sha256") != source_sha256["snapshot_manifest"]
    ):
        raise CommandError("target projection lineage or target commitment differs")
    expected_input_commitments = {
        str(path.resolve()): source_sha256[name] for name, path in source_paths.items()
    }
    if summary.get("input_commitments") != expected_input_commitments:
        raise CommandError("target projection input commitments differ")
    summary_outputs = summary.get("output_commitments")
    if not isinstance(summary_outputs, Mapping):
        raise CommandError("target projection summary lacks output commitments")
    expected_summary_names = set(paths) - {"target-cohort-projection.json"}
    if set(cast(Mapping[object, object], summary_outputs)) != expected_summary_names:
        raise CommandError("target projection summary output commitments differ")
    for name in expected_summary_names:
        if cast(Mapping[object, object], summary_outputs).get(name) != _bytes_sha256(
            output_bytes[name]
        ):
            raise CommandError(f"target projection output changed: {name}")

    try:
        reproduced = project_target_cohort(
            selections=_projection_jsonl_records(
                source_bytes["selection"], source=source_paths["selection"]
            ),
            case_relevance=_projection_jsonl_records(
                source_bytes["case_relevance"],
                source=source_paths["case_relevance"],
            ),
            download_manifest=_projection_jsonl_records(
                source_bytes["download_manifest"],
                source=source_paths["download_manifest"],
            ),
            clearance_records=_projection_jsonl_records(
                source_bytes["disclosure_clearance"],
                source=source_paths["disclosure_clearance"],
            ),
            target_case_count=expected_target_count,
            cost_per_document_usd=_required_str(
                preparation_config, "cost_per_document_usd"
            ),
            max_projected_budget_usd=_required_str(
                preparation_config, "max_projected_budget_usd"
            ),
            max_missing_core_documents_per_case=_required_int(
                preparation_config, "max_missing_core_documents_per_case"
            ),
        )
    except TargetCohortProjectionError as exc:
        raise CommandError(f"target projection does not reproduce: {exc}") from exc
    reproduced_manifest = tuple(reproduced.download_manifest)
    reproduced_outputs = {
        "target-cohort-selection.jsonl": _projection_jsonl_bytes(reproduced.selections),
        "case-relevance.jsonl": _projection_jsonl_bytes(reproduced.case_relevance),
        "free-document-downloads.jsonl": _projection_jsonl_bytes(
            record
            for record in reproduced_manifest
            if record.get("free_or_purchased") == "free"
        ),
        "purchased-document-downloads.jsonl": _projection_jsonl_bytes(
            record
            for record in reproduced_manifest
            if record.get("free_or_purchased") == "purchased"
        ),
        "document-downloads-merged.jsonl": _projection_jsonl_bytes(reproduced_manifest),
        "disclosure-clearance.jsonl": _projection_jsonl_bytes(
            reproduced.clearance_records
        ),
        "restriction-evidence.jsonl": _projection_jsonl_bytes(
            reproduced.restriction_evidence
        ),
        "core-filter-results.jsonl": _projection_jsonl_bytes(
            row.to_record() for row in reproduced.core_filter_results
        ),
        "target-cohort-exclusions.jsonl": _projection_jsonl_bytes(
            reproduced.exclusions
        ),
        "missing-core-budget-plan.json": _projection_json_bytes(
            reproduced.budget_plan.to_record()
        ),
        "target-cohort-ranked-reserve.jsonl": _projection_jsonl_bytes(
            reproduced.ranked_reserve
        ),
    }
    for name, payload in reproduced_outputs.items():
        if output_bytes[name] != payload:
            raise CommandError(f"target projection does not reproduce: {name}")
    if summary.get("projection_sha256") != reproduced.summary.get("projection_sha256"):
        raise CommandError("target projection digest does not reproduce")

    selection_records = _projection_jsonl_records(
        output_bytes["target-cohort-selection.jsonl"],
        source=paths["target-cohort-selection.jsonl"],
    )
    if len(selection_records) != expected_target_count:
        raise CommandError("target selection count differs from authenticated target")
    candidate_ids: set[str] = set()
    selected_document_keys: set[tuple[str, str]] = set()
    for selection in selection_records:
        candidate_id = _required_str(selection, "candidate_id")
        if candidate_id in candidate_ids:
            raise CommandError(f"duplicate target selection candidate: {candidate_id}")
        candidate_ids.add(candidate_id)
        documents = selection.get("documents")
        if not isinstance(documents, Sequence) or isinstance(documents, (str, bytes)):
            raise CommandError("target selection documents must be a list")
        for item in cast(Sequence[object], documents):
            document = _mapping(item, "target selection document")
            key = (candidate_id, _required_str(document, "source_document_id"))
            if key in selected_document_keys:
                raise CommandError(
                    f"duplicate target selection document: {key[0]}/{key[1]}"
                )
            selected_document_keys.add(key)

    free_manifest = _projection_jsonl_records(
        output_bytes["free-document-downloads.jsonl"],
        source=paths["free-document-downloads.jsonl"],
    )
    free_clearance = _projection_jsonl_records(
        output_bytes["disclosure-clearance.jsonl"], source=free_clearance_path
    )
    merged_manifest = _projection_jsonl_records(
        output_bytes["document-downloads-merged.jsonl"],
        source=paths["document-downloads-merged.jsonl"],
    )
    projected_purchased = _projection_jsonl_records(
        output_bytes["purchased-document-downloads.jsonl"],
        source=paths["purchased-document-downloads.jsonl"],
    )
    _require_unique_materializer_keys(free_manifest, label="projected free manifest")
    _require_unique_materializer_keys(
        projected_purchased, label="projected purchased manifest"
    )
    _require_unique_materializer_keys(
        merged_manifest, label="projected merged manifest"
    )
    expected_merged = sorted(
        [*free_manifest, *projected_purchased],
        key=_materializer_record_key,
    )
    if sorted(merged_manifest, key=_materializer_record_key) != expected_merged:
        raise CommandError("target projection free/purchased partition differs")
    if any(record.get("free_or_purchased") != "free" for record in free_manifest):
        raise CommandError("target projection free manifest has invalid phase")
    for record in free_manifest:
        if _materializer_record_key(record) not in selected_document_keys:
            raise CommandError("projected free document is outside target selection")
    _require_snapshot_unchanged(
        {
            run_card_path: run_card_bytes,
            **{path: source_bytes[name] for name, path in source_paths.items()},
            **{path: output_bytes[name] for name, path in paths.items()},
        },
        label="target projection artifact",
    )
    result: dict[str, object] = {
        "run_card": run_card,
        "run_card_bytes": run_card_bytes,
        "summary": summary,
        "summary_path": summary_path,
        "run_card_path": run_card_path,
        "selection_path": paths["target-cohort-selection.jsonl"],
        "selection_records": selection_records,
        "free_manifest_path": paths["free-document-downloads.jsonl"],
        "free_manifest": free_manifest,
        "purchased_manifest": projected_purchased,
        "free_clearance": free_clearance,
        "restriction_path": paths["restriction-evidence.jsonl"],
        "restriction_records": _projection_jsonl_records(
            output_bytes["restriction-evidence.jsonl"],
            source=paths["restriction-evidence.jsonl"],
        ),
        "selected_document_keys": selected_document_keys,
        "authenticated_input_paths": dict(source_paths),
        "verified_artifact_bytes": {
            os.path.abspath(run_card_path): run_card_bytes,
            **{
                os.path.abspath(path): source_bytes[name]
                for name, path in source_paths.items()
            },
            **{
                os.path.abspath(path): output_bytes[name]
                for name, path in paths.items()
            },
        },
    }
    if (
        _verified_projection_operation is not None
        and _verified_projection_operation.is_live_owner()
    ):
        raw_lineage_snapshots = clearance_lineage.get("verified_artifact_bytes")
        if isinstance(raw_lineage_snapshots, Mapping):
            cache_snapshots = dict(clearance_snapshot)
            for raw_path, payload in cast(
                Mapping[object, object], raw_lineage_snapshots
            ).items():
                if not isinstance(raw_path, str) or not isinstance(payload, bytes):
                    raise CommandError("target projection cache evidence is invalid")
                existing = cache_snapshots.get(raw_path)
                if existing is not None and existing != payload:
                    raise CommandError("target projection cache evidence conflicts")
                cache_snapshots[raw_path] = payload
            if (
                clearance_lineage.get("lineage_kind")
                == "provider_free_recovered_public"
            ):
                recovery_capability = clearance_lineage.get(
                    "authenticated_recovery_capability"
                )
                recovery_snapshots = cast(
                    Mapping[object, object],
                    _consume_recovered_public_source_snapshots(recovery_capability),
                )
                for path, payload in recovery_snapshots.items():
                    if not isinstance(path, Path) or not isinstance(payload, bytes):
                        raise CommandError("recovered-public cache evidence is invalid")
                    key = os.path.abspath(path)
                    existing = cache_snapshots.get(key)
                    if existing is not None and existing != payload:
                        raise CommandError(
                            "recovered-public clearance and recovery snapshots conflict"
                        )
                    cache_snapshots[key] = payload
            _verified_projection_operation.record_byte_closure(
                target_root=target_root,
                run_card_bytes=run_card_bytes,
                snapshots=cache_snapshots,
            )
    return result


def _verify_supporting_document_downstream_projection(
    *,
    target_root: Path,
    free_clearance_path: Path,
    expected_target_count: int,
    _verified_byte_closure: dict[str, bytes] | None = None,
) -> dict[str, object]:
    """Replay one supporting-document successor for downstream consumers."""

    card_path = (
        target_root / "run-cards/project-exact100-supporting-document-successor.json"
    )
    card = _projection_json_object(
        _read_singly_linked_regular_input(
            card_path, label="supporting-document successor run card"
        ),
        source=card_path,
    )
    if (
        card.get("schema_version") != SUPPORTING_DOCUMENT_SUCCESSOR_SCHEMA_VERSION
        or card.get("selected_case_count") != expected_target_count
        or free_clearance_path.resolve()
        != (target_root / "disclosure-clearance.jsonl").resolve()
    ):
        raise CommandError("supporting-document materializer inputs differ")

    def verify_v2(root: Path) -> Mapping[str, object]:
        v2_card_path = root / "run-cards/project-target-cohort.json"
        v2_card = _projection_json_object(
            _read_singly_linked_regular_input(
                v2_card_path, label="supporting-document v2 run card"
            ),
            source=v2_card_path,
        )
        return verify_exact100_successor_replacement_v2_projection(
            root,
            replay=_replay_exact100_successor_replacement_v2_inputs,
            args=_exact100_successor_v2_replay_args(v2_card),
        )

    try:
        return _mint_verified_successor_selection_card_from_projection(
            verify_supporting_document_successor_projection(
                target_root,
                verifier=verify_v2,
                _verified_byte_closure=_verified_byte_closure,
            ),
            replay_attestation=_SUPPORTING_DOCUMENT_SUCCESSOR_REPLAY_ATTESTATION,
        )
    except (
        Exact100SuccessorReplacementV2CliError,
        SupportingDocumentSuccessorCliError,
    ) as exc:
        raise CommandError(str(exc)) from exc


def _materializer_consolidated_target_inputs(
    *,
    target_root: Path,
    free_clearance_path: Path,
    preparation_summary_path: Path,
    preparation_config_path: Path,
    snapshot_manifest_path: Path,
    expected_target_count: int,
) -> tuple[dict[str, object] | None, Path, list[dict[str, Any]]]:
    """Select the authenticated projection that purchased recovery predates."""

    supporting_card = (
        target_root / "run-cards/project-exact100-supporting-document-successor.json"
    )
    if not supporting_card.is_file() or supporting_card.is_symlink():
        selection_path = target_root / "target-cohort-selection.jsonl"
        return (
            None,
            selection_path,
            _projection_jsonl_records(
                _read_singly_linked_regular_input(
                    selection_path, label="consolidated recovery target selection"
                ),
                source=selection_path,
            ),
        )
    projection = _verify_materializer_projection(
        target_root=target_root,
        free_clearance_path=free_clearance_path,
        preparation_summary_path=preparation_summary_path,
        preparation_config_path=preparation_config_path,
        snapshot_manifest_path=snapshot_manifest_path,
        expected_target_count=expected_target_count,
    )
    base = projection.get("base_v2_projection")
    if not isinstance(base, Mapping):
        raise CommandError("supporting-document successor lacks base v2 projection")
    base_record = cast(Mapping[str, object], base)
    selection_path = base_record.get("selection_path")
    selection_records = base_record.get("selection_records")
    if (
        not isinstance(selection_path, Path)
        or not isinstance(selection_records, Sequence)
        or isinstance(selection_records, (str, bytes))
    ):
        raise CommandError("supporting-document successor base selection differs")
    normalized_selection = _normalized_materializer_selection_records(
        cast(Sequence[object], selection_records),
        label="supporting-document successor base selection",
    )
    return (
        projection,
        selection_path,
        normalized_selection,
    )


def _normalized_materializer_selection_records(
    records: object,
    *,
    label: str,
) -> list[dict[str, Any]]:
    """Normalize an authenticated ordered selection without dropping rows."""

    if not isinstance(records, Sequence) or isinstance(records, (str, bytes)):
        raise CommandError(f"{label} must be a list")
    rows = list(cast(Sequence[object], records))
    if not all(isinstance(row, Mapping) for row in rows):
        raise CommandError(f"{label} must contain only objects")
    return [dict(cast(Mapping[str, Any], row)) for row in rows]


def _select_materializer_projection_after_recovery(
    *,
    outer_projection: dict[str, object] | None,
    recovery_projection: Mapping[str, object],
    recovery_selection: Sequence[Mapping[str, Any]],
) -> dict[str, object]:
    """Retain the outer free successor after proving its purchased base."""

    if outer_projection is None:
        return dict(recovery_projection)
    expected_records = [dict(row) for row in recovery_selection]
    base = outer_projection.get("base_v2_projection")
    base_records = (
        cast(Mapping[str, object], base).get("selection_records")
        if isinstance(base, Mapping)
        else None
    )
    try:
        normalized_base_records = _normalized_materializer_selection_records(
            base_records,
            label="supporting-document successor base selection",
        )
    except CommandError as exc:
        raise CommandError(
            "supporting-document successor base selection differs from "
            "consolidated recovery"
        ) from exc
    if normalized_base_records != expected_records:
        raise CommandError(
            "supporting-document successor base selection differs from "
            "consolidated recovery"
        )
    recovery_records = recovery_projection.get("selection_records")
    try:
        normalized_recovery_records = _normalized_materializer_selection_records(
            recovery_records,
            label="consolidated recovery projection selection",
        )
    except CommandError as exc:
        raise CommandError(
            "consolidated recovery projection selection differs from its "
            "authenticated input"
        ) from exc
    if normalized_recovery_records != expected_records:
        raise CommandError(
            "consolidated recovery projection selection differs from its "
            "authenticated input"
        )
    return outer_projection


@dataclass(frozen=True)
class _VerifiedProjectionCacheEntry:
    result: dict[str, object]
    snapshots: tuple[tuple[str, bytes], ...]


def _current_asyncio_task_id() -> int | None:
    try:
        task = asyncio.current_task()
    except RuntimeError:
        return None
    return id(task) if task is not None else None


@dataclass
class _VerifiedProjectionOperation:
    owner_thread_id: int
    cache: dict[tuple[str, str, str], _VerifiedProjectionCacheEntry]
    byte_closures: dict[tuple[str, str, str], dict[str, bytes]]
    owner_task_id: int | None = None
    alive: bool = True

    def is_live_owner(self) -> bool:
        return (
            self.alive
            and self.owner_thread_id == get_ident()
            and self.owner_task_id == _current_asyncio_task_id()
        )

    def invalidate(self) -> None:
        self.alive = False
        self.cache.clear()
        self.byte_closures.clear()

    def record_byte_closure(
        self,
        *,
        target_root: Path,
        run_card_bytes: bytes,
        snapshots: Mapping[str, bytes],
        lineage_kind: str = "legalforecast.acquisition_run_card.v1",
    ) -> None:
        if not self.is_live_owner():
            raise RuntimeError(
                "verified projection operation is not live for this thread"
            )
        key = (
            lineage_kind,
            str(target_root.resolve()),
            _bytes_sha256(run_card_bytes),
        )
        self.byte_closures[key] = dict(snapshots)


_VERIFIED_PROJECTION_OPERATION: ContextVar[_VerifiedProjectionOperation | None] = (
    ContextVar("verified_projection_cache", default=None)
)
_VERIFIED_PROJECTION_BYTE_COLLECTOR: ContextVar[dict[str, bytes] | None] = ContextVar(
    "verified_projection_byte_collector", default=None
)


def verify_completed_target_cohort_projection_for_purchase_approval(
    target_root: Path,
    *,
    _verified_legacy_ranked_replay: VerifiedLegacyRankedReserveReplay | None = None,
    _verified_clearance_relocations: (Mapping[str, tuple[Path, bytes]] | None) = None,
    _verified_clearance_source_roots: Mapping[str, Path] | None = None,
) -> dict[str, object]:
    """Run the full authenticated projection verifier for purchase approval.

    This deliberately reuses the materializer's fail-closed verifier so approval
    cannot drift into a weaker parallel interpretation of preparation,
    disclosure-clearance, snapshot, run-card, or output commitments.

    Recursive producer replay can encounter the same byte-closed base root more
    than once. Keep its fully verified evidence only for this top-level call;
    cache hits still reread every authenticated byte before reuse, preserving
    the existing mutation check without repeating recursive lineage computation.
    """

    operation = _VERIFIED_PROJECTION_OPERATION.get()
    if operation is not None and operation.is_live_owner():
        return _verify_completed_target_cohort_projection_in_operation(
            target_root,
            operation=operation,
            _verified_legacy_ranked_replay=_verified_legacy_ranked_replay,
            _verified_clearance_relocations=_verified_clearance_relocations,
            _verified_clearance_source_roots=_verified_clearance_source_roots,
        )
    operation = _VerifiedProjectionOperation(
        owner_thread_id=get_ident(),
        cache={},
        byte_closures={},
        owner_task_id=_current_asyncio_task_id(),
    )
    token = _VERIFIED_PROJECTION_OPERATION.set(operation)
    try:
        return _verify_completed_target_cohort_projection_in_operation(
            target_root,
            operation=operation,
            _verified_legacy_ranked_replay=_verified_legacy_ranked_replay,
            _verified_clearance_relocations=_verified_clearance_relocations,
            _verified_clearance_source_roots=_verified_clearance_source_roots,
        )
    finally:
        operation.invalidate()
        _VERIFIED_PROJECTION_OPERATION.reset(token)


def _verify_completed_target_cohort_projection_in_operation(
    target_root: Path,
    *,
    operation: _VerifiedProjectionOperation,
    _verified_legacy_ranked_replay: VerifiedLegacyRankedReserveReplay | None = None,
    _verified_clearance_relocations: (Mapping[str, tuple[Path, bytes]] | None) = None,
    _verified_clearance_source_roots: Mapping[str, Path] | None = None,
) -> dict[str, object]:
    if not operation.is_live_owner():  # pragma: no cover - guarded by public entry
        raise RuntimeError("verified projection operation is not live for this thread")

    supporting_card_path = (
        target_root / "run-cards/project-exact100-supporting-document-successor.json"
    )
    if supporting_card_path.is_file() and not supporting_card_path.is_symlink():
        supporting_card_bytes = _read_singly_linked_regular_input(
            supporting_card_path, label="supporting-document successor run card"
        )
        supporting_card = _projection_json_object(
            supporting_card_bytes, source=supporting_card_path
        )
        cache_key = (
            str(SUPPORTING_DOCUMENT_SUCCESSOR_SCHEMA_VERSION),
            str(target_root.resolve()),
            _bytes_sha256(supporting_card_bytes),
        )
        cached = operation.cache.get(cache_key)
        if cached is not None:
            _require_snapshot_unchanged(
                {Path(path): payload for path, payload in cached.snapshots},
                label="cached supporting-document projection artifact",
            )
            return copy.deepcopy(cached.result)
        closure: dict[str, bytes] = {}
        token = _VERIFIED_PROJECTION_BYTE_COLLECTOR.set(closure)
        try:
            result = _verify_supporting_document_downstream_projection(
                target_root=target_root,
                free_clearance_path=target_root / "disclosure-clearance.jsonl",
                expected_target_count=_required_int(
                    supporting_card, "selected_case_count"
                ),
                _verified_byte_closure=closure,
            )
        finally:
            _VERIFIED_PROJECTION_BYTE_COLLECTOR.reset(token)
        raw_snapshots: object = result.get("verified_artifact_bytes")
        base = result.get("base_v2_projection")
        base_record: Mapping[str, object]
        if isinstance(base, Mapping):
            base_record = cast(Mapping[str, object], base)
        else:
            base_record = {}
        raw_base_snapshots: object = base_record.get("verified_artifact_bytes", {})
        snapshot_groups: tuple[object, ...] = (raw_snapshots, raw_base_snapshots)
        for raw_group in snapshot_groups:
            if not isinstance(raw_group, Mapping):
                raise CommandError(
                    "supporting-document projection cache evidence is incomplete"
                )
            for raw_path, payload in cast(Mapping[object, object], raw_group).items():
                if not isinstance(raw_path, str) or not isinstance(payload, bytes):
                    raise CommandError(
                        "supporting-document projection cache evidence is invalid"
                    )
                existing = closure.get(raw_path)
                if existing is not None and existing != payload:
                    raise CommandError(
                        "supporting-document projection cache evidence conflicts"
                    )
                closure[raw_path] = payload
        operation.cache[cache_key] = _VerifiedProjectionCacheEntry(
            result=copy.deepcopy(result), snapshots=tuple(sorted(closure.items()))
        )
        return result

    run_card_path = target_root / "run-cards/project-target-cohort.json"
    run_card_bytes = _read_singly_linked_regular_input(
        run_card_path, label="target projection run card"
    )
    run_card = _projection_json_object(run_card_bytes, source=run_card_path)
    cache_key = (
        "legalforecast.acquisition_run_card.v1",
        str(target_root.resolve()),
        _bytes_sha256(run_card_bytes),
    )
    raw_inputs_for_cache = run_card.get("input_paths")
    cache_input_count = (
        len(cast(Sequence[object], raw_inputs_for_cache))
        if isinstance(raw_inputs_for_cache, Sequence)
        and not isinstance(raw_inputs_for_cache, (str, bytes))
        else None
    )
    cacheable = (
        run_card.get("schema_version") == "legalforecast.acquisition_run_card.v1"
        and cache_input_count == 9
        and _verified_legacy_ranked_replay is None
        and _verified_clearance_relocations is None
        and _verified_clearance_source_roots is None
    )
    cached = operation.cache.get(cache_key) if cacheable else None
    if cached is not None:
        snapshots: dict[Path, bytes] = {}
        for raw_path, payload in cached.snapshots:
            snapshots[Path(raw_path)] = payload
        _require_snapshot_unchanged(
            snapshots, label="cached target projection artifact"
        )
        return copy.deepcopy(cached.result)

    def verified(result: dict[str, object]) -> dict[str, object]:
        if cacheable:
            byte_closure = operation.byte_closures.pop(cache_key, None)
            if byte_closure is None:
                return result
            raw_snapshots = result.get("verified_artifact_bytes")
            if not isinstance(raw_snapshots, Mapping):
                raise CommandError("target projection cache evidence is incomplete")
            typed_raw_snapshots = cast(Mapping[object, object], raw_snapshots)
            snapshots = {
                str(raw_path): payload
                for raw_path, payload in typed_raw_snapshots.items()
                if isinstance(raw_path, str) and isinstance(payload, bytes)
            }
            if len(snapshots) != len(typed_raw_snapshots):
                raise CommandError("target projection cache evidence is invalid")
            for raw_path, payload in byte_closure.items():
                existing = snapshots.get(raw_path)
                if existing is not None and existing != payload:
                    raise CommandError("target projection cache evidence conflicts")
                snapshots[raw_path] = payload
            operation.cache[cache_key] = _VerifiedProjectionCacheEntry(
                result=copy.deepcopy(result), snapshots=tuple(sorted(snapshots.items()))
            )
        return result

    if run_card.get("schema_version") == ZERO_COST_SUCCESSOR_STATE_SCHEMA:
        return verified(
            _verify_zero_cost_successor_projection(
                target_root=target_root,
                free_clearance_path=target_root / "disclosure-clearance.jsonl",
                expected_target_count=_required_int(run_card, "selected_case_count"),
                _verified_legacy_ranked_replay=_verified_legacy_ranked_replay,
                _verified_clearance_relocations=_verified_clearance_relocations,
                _verified_clearance_source_roots=_verified_clearance_source_roots,
            )
        )
    if run_card.get("schema_version") == str(EXACT100_SUCCESSOR_REPLACEMENT_STATE_V1):
        try:
            return verified(
                _mint_verified_successor_selection_card_from_projection(
                    verify_exact100_successor_replacement_projection(
                        target_root=target_root,
                        free_clearance_path=target_root / "disclosure-clearance.jsonl",
                        expected_target_count=_required_int(
                            run_card, "selected_case_count"
                        ),
                        replay_inputs=_replay_exact100_successor_inputs,
                        recovery_replay=_replay_exact100_terminal_recovery,
                        stipulated_replay=_replay_exact100_stipulated_eligibility,
                    ),
                    replay_attestation=_EXACT100_SUCCESSOR_REPLAY_ATTESTATION,
                )
            )
        except Exact100SuccessorReplacementCliError as exc:
            raise CommandError(str(exc)) from exc
    if run_card.get("schema_version") == str(EXACT100_SUCCESSOR_REPLACEMENT_STATE_V2):
        try:
            return verified(
                _mint_verified_successor_selection_card_from_projection(
                    verify_exact100_successor_replacement_v2_projection(
                        target_root,
                        replay=_replay_exact100_successor_replacement_v2_inputs,
                        args=_exact100_successor_v2_replay_args(run_card),
                    ),
                    replay_attestation=_EXACT100_SUCCESSOR_V2_REPLAY_ATTESTATION,
                )
            )
        except Exact100SuccessorReplacementV2CliError as exc:
            raise CommandError(str(exc)) from exc
    raw_inputs = run_card.get("input_paths")
    if not isinstance(raw_inputs, Sequence) or isinstance(raw_inputs, (str, bytes)):
        raise CommandError("target projection run card lacks exact inputs")
    input_paths = tuple(
        Path(str(value)) for value in cast(Sequence[object], raw_inputs)
    )
    if len(input_paths) not in {9, 19}:
        raise CommandError("target projection run card input paths differ")
    config_path = input_paths[7]
    config = _projection_json_object(
        _read_singly_linked_regular_input(config_path, label="preparation config"),
        source=config_path,
    )
    target_count = _required_int(config, "target_case_count")
    return verified(
        _verify_materializer_projection(
            target_root=target_root,
            free_clearance_path=target_root / "disclosure-clearance.jsonl",
            preparation_summary_path=input_paths[6],
            preparation_config_path=config_path,
            snapshot_manifest_path=input_paths[8],
            expected_target_count=target_count,
            _verified_projection_operation=operation,
        )
    )


def _verify_materializer_recovery(
    *,
    recovery_root: Path,
    selection_path: object,
    selected_document_keys: object,
    purchase_policy_path: Path | None = None,
    cohort_policy_path: Path | None = None,
    ledger_path: Path | None = None,
    purchase_operations: Sequence[Mapping[str, Any]] | None = None,
    purchase_committed_amount_usd: str | None = None,
    purchase_state_sha256: str | None = None,
) -> dict[str, object]:
    legacy_card = recovery_root / "run-cards/recover-purchased.json"
    quarantine_card = recovery_root / "run-cards/recover-recap-fetch-quarantine.json"
    consolidated_card = (
        recovery_root / "run-cards/consolidate-replacement-recovery.json"
    )
    present = tuple(
        path
        for path in (legacy_card, quarantine_card, consolidated_card)
        if path.exists()
    )
    if len(present) != 1:
        raise CommandError(
            "purchased recovery root must contain exactly one supported completed "
            "recovery run card"
        )
    if present[0] == consolidated_card:
        if (
            purchase_policy_path is None
            or cohort_policy_path is None
            or ledger_path is None
        ):
            raise CommandError(
                "consolidated recovery verification requires current purchase lineage"
            )
        return _verify_materializer_consolidated_recovery(
            recovery_root=recovery_root,
            run_card_path=consolidated_card,
            selection_path=selection_path,
            selected_document_keys=selected_document_keys,
            purchase_policy_path=purchase_policy_path,
            cohort_policy_path=cohort_policy_path,
            ledger_path=ledger_path,
        )
    if present[0] == quarantine_card:
        if (
            purchase_policy_path is None
            or cohort_policy_path is None
            or ledger_path is None
        ):
            raise CommandError(
                "quarantine recovery verification requires current purchase lineage"
            )
        return _verify_materializer_quarantine_recovery(
            recovery_root=recovery_root,
            run_card_path=quarantine_card,
            selection_path=selection_path,
            selected_document_keys=selected_document_keys,
            purchase_policy_path=purchase_policy_path,
            cohort_policy_path=cohort_policy_path,
            ledger_path=ledger_path,
            purchase_operations=purchase_operations,
            purchase_committed_amount_usd=purchase_committed_amount_usd,
            purchase_state_sha256=purchase_state_sha256,
        )
    return _verify_materializer_legacy_recovery(
        recovery_root=recovery_root,
        selection_path=selection_path,
        selected_document_keys=selected_document_keys,
    )


def _verify_materializer_consolidated_recovery(
    *,
    recovery_root: Path,
    run_card_path: Path,
    selection_path: object,
    selected_document_keys: object,
    purchase_policy_path: Path,
    cohort_policy_path: Path,
    ledger_path: Path,
) -> dict[str, object]:
    if not isinstance(selection_path, Path) or not isinstance(
        selected_document_keys, set
    ):
        raise CommandError("internal target projection verification failed")
    run_card_bytes = _read_singly_linked_regular_input(
        run_card_path, label="consolidated replacement recovery run card"
    )
    card = _projection_json_object(run_card_bytes, source=run_card_path)
    schema_version = card.get("schema_version")
    target_root_mode = schema_version == _REPLACEMENT_RECOVERY_CARD_SCHEMA_V2
    if (
        schema_version
        not in {
            _REPLACEMENT_RECOVERY_CARD_SCHEMA,
            _REPLACEMENT_RECOVERY_CARD_SCHEMA_V2,
        }
        or card.get("stage") != "consolidate-replacement-recovery"
        or card.get("status") != "completed"
        or card.get("dry_run") is not False
        or card.get("execute") is not True
        or card.get("paid_activity_requested") is not False
        or card.get("paid_activity_executed") is not False
        or card.get("provider_activity_requested") is not False
        or card.get("provider_activity_executed") is not False
    ):
        raise CommandError("invalid completed consolidated replacement recovery card")
    if target_root_mode != (
        card.get("target_projection_mode") == "exact100_successor_replacement_v2"
    ):
        raise CommandError("consolidated replacement recovery target mode differs")
    raw_inputs = card.get("input_paths")
    if not isinstance(raw_inputs, Sequence) or isinstance(raw_inputs, (str, bytes)):
        raise CommandError("consolidated replacement recovery lacks exact inputs")
    inputs = tuple(Path(str(path)) for path in cast(Sequence[object], raw_inputs))
    if (
        len(inputs) < 9
        or inputs[2].resolve() != selection_path.resolve()
        or inputs[4].resolve() != purchase_policy_path.resolve()
        or inputs[5].resolve() != cohort_policy_path.resolve()
        or inputs[6].resolve() != ledger_path.resolve()
    ):
        raise CommandError(
            "consolidated replacement recovery differs from materializer inputs"
        )
    source_commitments = card.get("source_commitments")
    if not isinstance(source_commitments, Mapping):
        raise CommandError("consolidated replacement recovery lacks source commitments")
    raw_terminal_inputs = card.get("terminal_omission_inputs")
    raw_partition = card.get("docket_decision_partition")
    terminal_input_paths: dict[str, Path] | None = None
    if raw_terminal_inputs is not None:
        if not isinstance(raw_terminal_inputs, Mapping):
            raise CommandError(
                "consolidated replacement recovery terminal inputs differ"
            )
        terminal_inputs_record = cast(Mapping[str, Any], raw_terminal_inputs)
        if set(terminal_inputs_record) != {
            "snapshot_manifest",
            "purchase_result",
            "purchase_run_card",
        }:
            raise CommandError(
                "consolidated replacement recovery terminal inputs differ"
            )
        terminal_input_paths = {
            name: Path(_required_str(terminal_inputs_record, name)).absolute()
            for name in (
                "snapshot_manifest",
                "purchase_result",
                "purchase_run_card",
            )
        }
        if not isinstance(raw_partition, Mapping):
            raise CommandError(
                "consolidated replacement recovery lacks terminal partition"
            )
    elif raw_partition is not None:
        raise CommandError(
            "consolidated replacement recovery terminal partition lacks inputs"
        )
    verified_bytes: dict[str, bytes] = {os.path.abspath(run_card_path): run_card_bytes}
    for raw_path, expected_sha256 in cast(
        Mapping[object, object], source_commitments
    ).items():
        if not isinstance(raw_path, str) or not _valid_prefixed_sha256(expected_sha256):
            raise CommandError(
                "consolidated replacement recovery source commitment is invalid"
            )
        path = Path(raw_path)
        payload = _read_singly_linked_regular_input(
            path, label="consolidated replacement recovery source"
        )
        if _bytes_sha256(payload) != expected_sha256:
            raise CommandError(
                "consolidated replacement recovery source commitment changed"
            )
        verified_bytes[os.path.abspath(path)] = payload
    for required in (
        selection_path,
        *((inputs[3],) if not target_root_mode else ()),
        purchase_policy_path,
        cohort_policy_path,
        inputs[8],
        *(
            tuple(terminal_input_paths.values())
            if terminal_input_paths is not None
            else ()
        ),
    ):
        if os.path.abspath(required) not in verified_bytes:
            raise CommandError(
                "consolidated replacement recovery omitted a common source commitment"
            )
    policy = verify_case_dev_purchase_policy(
        _projection_json_object(
            verified_bytes[os.path.abspath(purchase_policy_path)],
            source=purchase_policy_path,
        )
    )
    require_approved_case_dev_purchase_policy(policy, controlled_private_root=inputs[7])
    verify_case_dev_purchase_policy_cohort_binding(
        policy,
        _projection_json_object(
            verified_bytes[os.path.abspath(cohort_policy_path)],
            source=cohort_policy_path,
        ),
    )
    snapshot = read_case_dev_purchase_snapshot(
        ledger_path.resolve(),
        policy=policy,
        controlled_private_root=inputs[7],
        initialization_receipt_path=inputs[8],
    )
    if card.get("purchase_state_sha256") != snapshot.purchase_state_sha256:
        raise CommandError("consolidated replacement recovery purchase state changed")
    manifest_path = recovery_root / "purchased-document-downloads.jsonl"
    clearance_path = recovery_root / "disclosure-clearance.jsonl"
    restriction_path = recovery_root / "restriction-evidence.jsonl"
    resolved_path = recovery_root / "resolved-post-recovery-documents.jsonl"
    document_root = recovery_root / "documents/purchased"
    output_paths = {
        manifest_path.resolve(),
        clearance_path.resolve(),
        restriction_path.resolve(),
        resolved_path.resolve(),
        document_root.resolve(),
    }
    raw_outputs = card.get("output_paths")
    if (
        not isinstance(raw_outputs, Sequence)
        or isinstance(raw_outputs, (str, bytes))
        or {Path(str(path)).resolve() for path in cast(Sequence[object], raw_outputs)}
        != output_paths
    ):
        raise CommandError("consolidated replacement recovery output paths differ")
    output_commitments = card.get("output_commitments")
    if not isinstance(output_commitments, Mapping):
        raise CommandError("consolidated replacement recovery lacks output commitments")
    output_snapshots = {
        path: _read_singly_linked_regular_input(
            path, label="consolidated replacement recovery output"
        )
        for path in (manifest_path, clearance_path, restriction_path, resolved_path)
    }
    for path, payload in output_snapshots.items():
        if cast(Mapping[str, object], output_commitments).get(
            path.name
        ) != _bytes_sha256(payload):
            raise CommandError(
                "consolidated replacement recovery output commitment changed"
            )
        verified_bytes[os.path.abspath(path)] = payload
    tree = _materializer_tree_snapshot(document_root)
    if cast(Mapping[str, object], output_commitments).get("document_tree") != {
        relative: _bytes_sha256(payload) for relative, payload in tree.items()
    }:
        raise CommandError("consolidated replacement recovery document tree changed")
    manifest_records = _projection_jsonl_records(
        output_snapshots[manifest_path], source=manifest_path
    )
    clearance_records = _projection_jsonl_records(
        output_snapshots[clearance_path], source=clearance_path
    )
    manifest_index = _materializer_record_index(
        manifest_records, label="consolidated replacement recovery manifest"
    )
    clearance_index = _materializer_record_index(
        clearance_records, label="consolidated replacement recovery clearance"
    )
    operation_keys = {
        (
            _required_str(operation, "candidate_id"),
            _required_str(operation, "source_document_id"),
        )
        for operation in snapshot.operations
    }
    partition_omission_keys: set[tuple[str, str]] = set()
    if isinstance(raw_partition, Mapping):
        raw_omissions = cast(Mapping[str, object], raw_partition).get(
            "audit_only_document_keys"
        )
        if not isinstance(raw_omissions, Sequence) or isinstance(
            raw_omissions, (str, bytes)
        ):
            raise CommandError(
                "consolidated replacement recovery terminal partition differs"
            )
        for raw_omission in cast(Sequence[object], raw_omissions):
            omission = _mapping(raw_omission, "terminal partition omission")
            partition_omission_keys.add(
                (
                    _required_str(omission, "candidate_id"),
                    _required_str(omission, "source_document_id"),
                )
            )
    expected_keys = (
        cast(set[tuple[str, str]], selected_document_keys) & operation_keys
    ) - partition_omission_keys
    if set(manifest_index) != expected_keys or set(clearance_index) != expected_keys:
        raise CommandError(
            "consolidated replacement recovery coverage differs from active cohort"
        )
    for key, record in manifest_index.items():
        relative = Path(_required_str(record, "local_path"))
        payload = tree.get(relative.as_posix())
        if (
            payload is None
            or hashlib.sha256(payload).hexdigest() != _required_str(record, "sha256")
            or len(payload) != _required_int(record, "byte_count")
        ):
            raise CommandError(f"consolidated replacement document bytes differ: {key}")
    if card.get("record_count") != len(expected_keys):
        raise CommandError("consolidated replacement recovery record count differs")
    replay = _prepare_replacement_recovery_consolidation(
        argparse.Namespace(
            output_root=recovery_root,
            tranche_index=inputs[0],
            tranche_index_run_card=inputs[1],
            selection=inputs[2],
            target_purchased_manifest=(None if target_root_mode else inputs[3]),
            target_cohort_root=(inputs[3] if target_root_mode else None),
            purchase_policy=inputs[4],
            cohort_policy=inputs[5],
            purchase_ledger=inputs[6],
            controlled_private_root=inputs[7],
            purchase_ledger_initialization_receipt=inputs[8],
            snapshot_manifest=(
                terminal_input_paths["snapshot_manifest"]
                if terminal_input_paths is not None
                else None
            ),
            purchase_result=(
                terminal_input_paths["purchase_result"]
                if terminal_input_paths is not None
                else None
            ),
            purchase_run_card=(
                terminal_input_paths["purchase_run_card"]
                if terminal_input_paths is not None
                else None
            ),
        ),
        authenticated_source_snapshots={
            Path(path): payload for path, payload in verified_bytes.items()
        },
    )
    if (
        tuple(manifest_records) != replay.manifest_records
        or tuple(clearance_records) != replay.clearance_records
        or _projection_jsonl_records(
            output_snapshots[restriction_path], source=restriction_path
        )
        != list(replay.restriction_records)
        or _projection_jsonl_records(
            output_snapshots[resolved_path], source=resolved_path
        )
        != list(replay.resolved_records)
        or tree != dict(replay.document_bytes)
        or card.get("purchase_state_sha256") != replay.purchase_state_sha256
        or raw_terminal_inputs != replay.terminal_omission_inputs
        or raw_partition != replay.docket_decision_partition
    ):
        raise CommandError(
            "consolidated replacement recovery does not reproduce from tranches"
        )
    replay_source_commitments = {
        str(path.resolve()): _bytes_sha256(payload)
        for path, payload in sorted(
            replay.source_snapshots.items(), key=lambda item: str(item[0])
        )
    }
    if source_commitments != replay_source_commitments:
        raise CommandError(
            "consolidated replacement recovery source commitments do not reproduce"
        )
    _require_snapshot_unchanged(
        {Path(path): payload for path, payload in verified_bytes.items()},
        label="consolidated replacement recovery verification input",
    )
    return {
        "recovery_stage": "consolidate-replacement-recovery",
        "manifest_path": manifest_path,
        "manifest_records": manifest_records,
        "recovery_path": restriction_path,
        "document_root": document_root,
        "run_card_path": run_card_path,
        "restriction_path": restriction_path,
        "resolved_path": resolved_path,
        "verified_artifact_bytes": verified_bytes,
        "target_projection": dict(replay.target_projection),
        "_consolidated_resolved_capability_inputs": {
            "selection_records": replay.target_projection["selection_records"],
            "manifest_records": manifest_records,
            "clearance_records": clearance_records,
            "resolved_records": _projection_jsonl_records(
                output_snapshots[resolved_path], source=resolved_path
            ),
            "purchase_operations": snapshot.operations,
            "purchase_policy_sha256": policy.policy_sha256,
        },
    }


_verify_materializer_consolidated_recovery = _wrap_consolidated_resolved_verifier(
    _verify_materializer_consolidated_recovery
)
del _wrap_consolidated_resolved_verifier


def _verify_materializer_legacy_recovery(
    *,
    recovery_root: Path,
    selection_path: object,
    selected_document_keys: object,
) -> dict[str, object]:
    if not isinstance(selection_path, Path) or not isinstance(
        selected_document_keys, set
    ):
        raise CommandError("internal target projection verification failed")
    manifest_path = recovery_root / "purchased-document-downloads.jsonl"
    recovery_path = recovery_root / "purchased-document-recovery.jsonl"
    document_root = recovery_root / "documents/purchased"
    run_card_path = recovery_root / "run-cards/recover-purchased.json"
    artifact_bytes = {
        path: _require_materializer_artifact(path, label=label)
        for label, path in (
            ("purchased manifest", manifest_path),
            ("recovery audit", recovery_path),
            ("recovery run card", run_card_path),
        )
    }
    if document_root.is_symlink() or not document_root.is_dir():
        raise CommandError("purchased recovery document root is missing or unsafe")
    run_card = _read_json_object_payload(
        artifact_bytes[run_card_path], label="purchased recovery run card"
    )
    raw_inputs = run_card.get("input_paths")
    if not isinstance(raw_inputs, Sequence) or isinstance(raw_inputs, (str, bytes)):
        raise CommandError("recover-purchased run card lacks exact inputs")
    recovery_inputs = tuple(
        Path(str(path)) for path in cast(Sequence[object], raw_inputs)
    )
    if (
        len(recovery_inputs) != 2
        or recovery_inputs[1].resolve() != selection_path.resolve()
    ):
        raise CommandError("recover-purchased selection differs from target selection")
    purchase_result_path = recovery_inputs[0]
    purchase_result_bytes = _require_materializer_artifact(
        purchase_result_path, label="purchase result"
    )
    manifest_records = _read_jsonl_payload(
        artifact_bytes[manifest_path], label=str(manifest_path)
    )
    recovery_records = _read_jsonl_payload(
        artifact_bytes[recovery_path], label=str(recovery_path)
    )
    selection_records = _read_records(selection_path)
    try:
        requests = purchased_document_recovery_requests_from_records(
            _read_json_object_payload(
                purchase_result_bytes, label=str(purchase_result_path)
            ),
            selection_records,
        )
    except PurchasedDocumentRecoveryError as exc:
        raise CommandError(str(exc)) from exc
    successful_keys = {
        (
            request.purchase_attempt.candidate_id,
            request.purchase_attempt.source_document_id,
        )
        for request in requests
        if request.purchase_attempt.status is CaseDevPacerPurchaseStatus.PURCHASED
    }
    manifest_index = _materializer_record_index(
        manifest_records, label="purchased recovery manifest"
    )
    recovery_index = _materializer_record_index(
        recovery_records, label="purchased recovery audit"
    )
    if set(manifest_index) != successful_keys or set(recovery_index) != successful_keys:
        raise CommandError("purchased recovery identities do not reconcile")
    for key, manifest in manifest_index.items():
        if key not in cast(set[tuple[str, str]], selected_document_keys):
            raise CommandError(
                "purchased recovery document is outside target selection"
            )
        audit = recovery_index[key]
        if audit.get("status") not in {"recovered", "recovered_audit_only"}:
            raise CommandError(f"purchased document was not recovered: {key}")
        for field in ("local_path", "sha256", "byte_count", "free_or_purchased"):
            if audit.get(field) != manifest.get(field):
                raise CommandError(
                    f"purchased recovery audit conflicts with manifest: {key}/{field}"
                )
    if (
        run_card.get("schema_version") != "legalforecast.acquisition_run_card.v1"
        or run_card.get("stage") != "recover-purchased"
        or run_card.get("status") != "completed"
        or run_card.get("dry_run") is not False
        or run_card.get("execute") is not True
        or run_card.get("paid_activity_requested") is not False
        or run_card.get("paid_activity_executed") is not False
        or run_card.get("record_count") != len(requests)
        or run_card.get("recovered_count") != len(successful_keys)
    ):
        raise CommandError("invalid completed recover-purchased run card")
    source_commitments = run_card.get("source_commitments")
    output_commitments = run_card.get("output_commitments")
    if not isinstance(source_commitments, Mapping) or not isinstance(
        output_commitments, Mapping
    ):
        raise CommandError("recover-purchased run card lacks exact commitments")
    _validate_named_path_commitment(
        cast(Mapping[str, object], source_commitments),
        name="purchase_result",
        expected_path=purchase_result_path,
        expected_sha256=_path_sha256(purchase_result_path),
    )
    _validate_named_path_commitment(
        cast(Mapping[str, object], source_commitments),
        name="selection",
        expected_path=selection_path,
        expected_sha256=_path_sha256(selection_path),
    )
    _validate_named_path_commitment(
        cast(Mapping[str, object], output_commitments),
        name="purchased_document_manifest",
        expected_path=manifest_path,
        expected_sha256=_path_sha256(manifest_path),
    )
    _validate_named_path_commitment(
        cast(Mapping[str, object], output_commitments),
        name="purchased_document_recovery",
        expected_path=recovery_path,
        expected_sha256=_path_sha256(recovery_path),
    )
    if cast(Mapping[str, object], output_commitments).get(
        "document_tree"
    ) != _materializer_tree_commitments(document_root):
        raise CommandError("recover-purchased document-tree commitment mismatch")
    raw_outputs = run_card.get("output_paths")
    if not isinstance(raw_outputs, Sequence) or isinstance(raw_outputs, (str, bytes)):
        raise CommandError("recover-purchased run card lacks outputs")
    expected_outputs = {
        manifest_path.resolve(),
        recovery_path.resolve(),
        document_root.resolve(),
    }
    actual_outputs = {
        Path(str(path)).resolve() for path in cast(Sequence[object], raw_outputs)
    }
    if (
        actual_outputs != expected_outputs
        or len(cast(Sequence[object], raw_outputs)) != 3
    ):
        raise CommandError("recover-purchased run card output paths differ")
    return {
        "recovery_stage": "recover-purchased",
        "manifest_path": manifest_path,
        "manifest_records": manifest_records,
        "recovery_path": recovery_path,
        "document_root": document_root,
        "run_card_path": run_card_path,
        "purchase_result_path": purchase_result_path,
    }


def _historical_quarantine_recovery_purchase_state(
    *,
    purchase_policy: CaseDevPurchasePolicy,
    purchase_operations: Sequence[Mapping[str, Any]],
    committed_amount_usd: str,
    recovered_document_keys: set[tuple[str, str]],
) -> tuple[tuple[Mapping[str, Any], ...], str]:
    """Reconstruct the exact purchase state committed when recovery completed.

    The only later mutation accepted here is the resolver's authenticated
    transition for a recovered manifest row.  Reversing precisely that
    transition preserves the recovery-era commitment while every unrelated
    purchase field remains hash-bound.
    """

    historical: list[Mapping[str, Any]] = []
    seen: set[tuple[str, str]] = set()
    for raw_operation in purchase_operations:
        operation = dict(raw_operation)
        key = _materializer_record_key(operation)
        if key in seen:
            raise CommandError("authenticated purchase snapshot repeats an operation")
        seen.add(key)
        if key in recovered_document_keys:
            material_state = operation.get("material_state")
            if material_state == "cleared_public":
                material = operation.get("material_evidence")
                if not isinstance(material, Mapping):
                    raise CommandError(
                        "resolved recovery purchase operation lacks material evidence"
                    )
                normalized_material = dict(cast(Mapping[str, Any], material))
                clearance_sha256 = normalized_material.pop(
                    "clearance_record_sha256", None
                )
                resolved_sha256 = operation.get("resolved_document_sha256")
                if (
                    not isinstance(clearance_sha256, str)
                    or re.fullmatch(r"[0-9a-f]{64}", clearance_sha256) is None
                    or not isinstance(resolved_sha256, str)
                    or re.fullmatch(r"[0-9a-f]{64}", resolved_sha256) is None
                ):
                    raise CommandError(
                        "resolved recovery purchase operation is not authenticated"
                    )
                operation["material_state"] = "recovered_pending_clearance"
                operation["material_evidence"] = normalized_material
                operation["resolved_document_sha256"] = None
            elif material_state != "recovered_pending_clearance":
                raise CommandError(
                    "recovered document purchase state has an unsupported transition"
                )
        historical.append(operation)
    historical_operations = tuple(historical)
    return historical_operations, canonical_purchase_state_sha256(
        purchase_policy,
        committed_amount_usd=committed_amount_usd,
        operations=historical_operations,
    )


def _verify_materializer_quarantine_recovery(
    *,
    recovery_root: Path,
    run_card_path: Path,
    selection_path: object,
    selected_document_keys: object,
    purchase_policy_path: Path,
    cohort_policy_path: Path,
    ledger_path: Path,
    purchase_operations: Sequence[Mapping[str, Any]] | None,
    purchase_committed_amount_usd: str | None,
    purchase_state_sha256: str | None,
) -> dict[str, object]:
    if not isinstance(selection_path, Path) or not isinstance(
        selected_document_keys, set
    ):
        raise CommandError("internal target projection verification failed")
    run_card_bytes = _read_singly_linked_regular_input(
        run_card_path, label="quarantine recovery run card"
    )
    run_card = _projection_json_object(run_card_bytes, source=run_card_path)
    schema_version = run_card.get("schema_version")
    legacy_card = schema_version == "legalforecast.acquisition_run_card.v1"
    terminal_aware_card = schema_version == _RECAP_FETCH_QUARANTINE_RECOVERY_CARD_SCHEMA
    if (
        not (legacy_card or terminal_aware_card)
        or run_card.get("stage") != "recover-recap-fetch-quarantine"
        or run_card.get("status") != "completed"
        or run_card.get("dry_run") is not False
        or run_card.get("execute") is not True
        or run_card.get("paid_activity_requested") is not False
        or run_card.get("paid_activity_executed") is not False
    ):
        raise CommandError("invalid completed quarantine recovery run card")
    raw_inputs = run_card.get("input_paths")
    if not isinstance(raw_inputs, Sequence) or isinstance(raw_inputs, (str, bytes)):
        raise CommandError("quarantine recovery run card lacks exact inputs")
    recovery_inputs = tuple(
        Path(str(path)) for path in cast(Sequence[object], raw_inputs)
    )
    replacement_mode = run_card.get("authority_mode") == "replacement_successor"
    if len(recovery_inputs) not in {8, 10}:
        raise CommandError("quarantine recovery run card input paths differ")
    expected_inputs = (
        (
            selection_path,
            recovery_inputs[1],
            purchase_policy_path,
            cohort_policy_path,
            recovery_inputs[4],
            ledger_path,
            recovery_inputs[6],
            recovery_inputs[7],
        )
        if replacement_mode
        else (
            selection_path,
            recovery_inputs[1],
            recovery_inputs[2],
            purchase_policy_path,
            cohort_policy_path,
            recovery_inputs[5],
            ledger_path,
            recovery_inputs[7],
        )
    )
    if tuple(path.resolve() for path in recovery_inputs[:8]) != tuple(
        path.resolve() for path in expected_inputs
    ):
        raise CommandError("quarantine recovery lineage differs from target inputs")
    source_commitments = run_card.get("source_commitments")
    output_commitments = run_card.get("output_commitments")
    if not isinstance(source_commitments, Mapping) or not isinstance(
        output_commitments, Mapping
    ):
        raise CommandError("quarantine recovery run card lacks exact commitments")
    typed_output_commitments = cast(Mapping[str, object], output_commitments)
    source_paths: dict[str, Path] = (
        {
            "selection": selection_path,
            "case_relevance": recovery_inputs[1],
            "purchase_policy": purchase_policy_path,
            "cohort_policy": cohort_policy_path,
            "budget_plan": recovery_inputs[4],
            "attempt_policy": recovery_inputs[6],
            "replacement_purchase_authority": recovery_inputs[7],
        }
        if replacement_mode
        else {
            "selection": selection_path,
            "case_relevance": recovery_inputs[1],
            "target_projection_run_card": recovery_inputs[2],
            "purchase_policy": purchase_policy_path,
            "cohort_policy": cohort_policy_path,
            "budget_plan": recovery_inputs[5],
            "attempt_policy": recovery_inputs[7],
        }
    )
    if len(recovery_inputs) == 10:
        source_paths.update(
            {
                "courtlistener_fixture": recovery_inputs[8],
                "fixture_documents": recovery_inputs[9],
            }
        )
    source_snapshot = {
        name: _read_singly_linked_regular_input(
            path, label=f"quarantine recovery {name}"
        )
        for name, path in source_paths.items()
    }
    for name, path in source_paths.items():
        _validate_named_path_commitment(
            cast(Mapping[str, object], source_commitments),
            name=name,
            expected_path=path,
            expected_sha256=_bytes_sha256(source_snapshot[name]),
        )
    manifest_path, manifest_bytes = _snapshot_committed_file(
        typed_output_commitments,
        "quarantine_download_manifest",
        label="quarantine recovery",
    )
    purchased_case_relevance_path, purchased_case_relevance_bytes = (
        _snapshot_committed_file(
            typed_output_commitments,
            "purchased_case_relevance",
            label="quarantine recovery",
        )
    )
    restriction_path, restriction_bytes = _snapshot_committed_file(
        typed_output_commitments,
        "fresh_restriction_evidence",
        label="quarantine recovery",
    )
    terminal_unavailable_path: Path | None = None
    terminal_unavailable_bytes = b""
    if terminal_aware_card:
        terminal_unavailable_path, terminal_unavailable_bytes = (
            _snapshot_committed_file(
                typed_output_commitments,
                "terminal_unavailable_operations",
                label="quarantine recovery",
            )
        )
    elif (
        "terminal_unavailable_operations" in typed_output_commitments
        or "terminal_unavailable_document_count" in run_card
        or "authorized_document_count" in run_card
        or "recovered_document_count" in run_card
    ):
        raise CommandError("legacy quarantine recovery card mixes terminal fields")
    review_requests_path, review_requests_bytes = _snapshot_committed_file(
        typed_output_commitments,
        "disclosure_review_requests",
        label="quarantine recovery",
    )
    raw_outputs = run_card.get("output_paths")
    if not isinstance(raw_outputs, Sequence) or isinstance(raw_outputs, (str, bytes)):
        raise CommandError("quarantine recovery run card lacks outputs")
    output_paths = tuple(
        Path(str(path)) for path in cast(Sequence[object], raw_outputs)
    )
    expected_output_count = 7 if terminal_aware_card else 6
    if len(output_paths) != expected_output_count:
        raise CommandError("quarantine recovery run card output paths differ")
    committed_file_outputs = {
        manifest_path.resolve(),
        purchased_case_relevance_path.resolve(),
        restriction_path.resolve(),
        *((terminal_unavailable_path.resolve(),) if terminal_unavailable_path else ()),
        review_requests_path.resolve(),
        ledger_path.resolve(),
    }
    document_roots = tuple(
        path for path in output_paths if path.resolve() not in committed_file_outputs
    )
    if len(document_roots) != 1:
        raise CommandError("quarantine recovery document root is missing or ambiguous")
    document_root = document_roots[0]
    expected_outputs = {
        manifest_path.resolve(),
        purchased_case_relevance_path.resolve(),
        restriction_path.resolve(),
        *((terminal_unavailable_path.resolve(),) if terminal_unavailable_path else ()),
        review_requests_path.resolve(),
        document_root.resolve(),
        ledger_path.resolve(),
    }
    if {path.resolve() for path in output_paths} != expected_outputs:
        raise CommandError("quarantine recovery run card output paths differ")
    if typed_output_commitments.get("document_tree") != _materializer_tree_commitments(
        document_root
    ):
        raise CommandError("quarantine recovery document-tree commitment mismatch")
    state_sha256 = typed_output_commitments.get("purchase_state_sha256")
    if (
        not isinstance(state_sha256, str)
        or len(state_sha256) != 64
        or any(character not in "0123456789abcdef" for character in state_sha256)
    ):
        raise CommandError("quarantine recovery lacks purchase-state commitment")
    manifest_records = _projection_jsonl_records(manifest_bytes, source=manifest_path)
    terminal_unavailable_records = (
        _projection_jsonl_records(
            terminal_unavailable_bytes,
            source=terminal_unavailable_path,
        )
        if terminal_unavailable_path is not None
        else []
    )
    normalized_source_snapshot = {
        os.path.abspath(path): source_snapshot[name]
        for name, path in source_paths.items()
    }
    if replacement_mode:
        if selection_path.resolve() != recovery_inputs[1].resolve():
            raise CommandError(
                "replacement recovery selection and case relevance differ"
            )
        selection_bytes = source_snapshot["selection"]
        case_relevance_bytes = source_snapshot["case_relevance"]
    else:
        selection_bytes, case_relevance_bytes = _authenticated_target_projection_inputs(
            selection_path=selection_path,
            case_relevance_path=recovery_inputs[1],
            run_card_path=recovery_inputs[2],
            captured_artifact_bytes=normalized_source_snapshot,
        )
    _projection_jsonl_records(selection_bytes, source=selection_path)
    expected_purchased_relevance = _projection_jsonl_bytes(
        _project_purchased_case_relevance(
            _projection_jsonl_records(case_relevance_bytes, source=recovery_inputs[1]),
            manifest_records,
        )
    )
    if purchased_case_relevance_bytes != expected_purchased_relevance:
        raise CommandError("purchased case relevance does not reproduce")
    restriction_records = _projection_jsonl_records(
        restriction_bytes, source=restriction_path
    )
    review_requests = _projection_jsonl_records(
        review_requests_bytes, source=review_requests_path
    )
    reproduced_requests = build_recap_fetch_disclosure_review_requests(
        manifest_records, restriction_records
    )
    if review_requests != list(reproduced_requests):
        raise CommandError("quarantine disclosure-review requests do not reproduce")
    manifest_index = _materializer_record_index(
        manifest_records, label="quarantine recovery manifest"
    )
    attempt_policy_artifact = _projection_json_object(
        source_snapshot["attempt_policy"], source=source_paths["attempt_policy"]
    )
    purchase_policy_artifact = _projection_json_object(
        source_snapshot["purchase_policy"], source=source_paths["purchase_policy"]
    )
    try:
        purchase_policy = verify_case_dev_purchase_policy(purchase_policy_artifact)
    except CaseDevPurchasePolicyError as exc:
        raise CommandError(str(exc)) from exc
    if (
        purchase_operations is None
        or purchase_committed_amount_usd is None
        or purchase_state_sha256 is None
    ):
        raise CommandError(
            "quarantine recovery lacks authenticated current purchase state"
        )
    if (
        canonical_purchase_state_sha256(
            purchase_policy,
            committed_amount_usd=purchase_committed_amount_usd,
            operations=purchase_operations,
        )
        != purchase_state_sha256
    ):
        raise CommandError("authenticated current purchase state does not reproduce")
    attempt_policy_sha256 = _required_str(attempt_policy_artifact, "policy_sha256")
    attempt_policy_body = attempt_policy_artifact.get("policy")
    if (
        set(attempt_policy_artifact) != {"schema_version", "policy", "policy_sha256"}
        or attempt_policy_artifact.get("schema_version")
        != "legalforecast.recap_fetch_attempt_policy.v1"
        or not isinstance(attempt_policy_body, Mapping)
        or hashlib.sha256(
            json.dumps(
                attempt_policy_body,
                sort_keys=True,
                separators=(",", ":"),
                allow_nan=False,
            ).encode("utf-8")
        ).hexdigest()
        != attempt_policy_sha256
    ):
        raise CommandError("quarantine recovery attempt policy is invalid")
    try:
        terminal_index = validate_terminal_unavailable_records(
            terminal_unavailable_records,
            attempt_policy_sha256=attempt_policy_sha256,
        )
        if terminal_index:
            terminal_index = verify_terminal_unavailable_ledger_bindings(
                terminal_unavailable_records,
                purchase_operations=purchase_operations,
                attempt_policy_sha256=attempt_policy_sha256,
                expected_cycle_id=purchase_policy.cycle_id,
                expected_purchase_policy_sha256=purchase_policy.policy_sha256,
            )
    except RecapFetchQuarantineRecoveryError as exc:
        raise CommandError(str(exc)) from exc
    historical_operations, historical_purchase_state_sha256 = (
        _historical_quarantine_recovery_purchase_state(
            purchase_policy=purchase_policy,
            purchase_operations=purchase_operations,
            committed_amount_usd=purchase_committed_amount_usd,
            recovered_document_keys=set(manifest_index),
        )
    )
    allowed_documents_value = cast(Mapping[str, object], attempt_policy_body).get(
        "allowed_documents"
    )
    if not isinstance(allowed_documents_value, list):
        raise CommandError("quarantine recovery attempt policy lacks documents")
    authorized_documents: dict[tuple[str, str], str] = {}
    for raw_document in cast(list[object], allowed_documents_value):
        if not isinstance(raw_document, Mapping):
            raise CommandError("quarantine recovery attempt document is invalid")
        document = cast(Mapping[str, object], raw_document)
        candidate_id = document.get("case_id")
        document_id = document.get("recap_document")
        selection_sha256 = document.get("selection_document_sha256")
        if (
            set(document)
            != {
                "case_id",
                "recap_document",
                "evidence_class",
                "selection_document_sha256",
            }
            or document.get("evidence_class") != "unknown_status_quarantine"
            or not isinstance(candidate_id, str)
            or not candidate_id
            or not isinstance(document_id, str)
            or not document_id
            or not document_id.isdigit()
            or document_id.startswith("0")
            or not isinstance(selection_sha256, str)
            or len(selection_sha256) != 64
            or any(
                character not in "0123456789abcdef" for character in selection_sha256
            )
        ):
            raise CommandError("quarantine recovery attempt document is invalid")
        key = (candidate_id, document_id)
        if key in authorized_documents:
            raise CommandError("quarantine recovery attempt policy repeats a document")
        authorized_documents[key] = selection_sha256
    if (
        state_sha256 != historical_purchase_state_sha256
        or set(manifest_index) & set(terminal_index)
        or set(manifest_index) | set(terminal_index) != set(authorized_documents)
        or any(
            record.get("attempt_document_sha256") != authorized_documents[key]
            for key, record in terminal_index.items()
        )
        or any(
            record.get("reservation_usd")
            != cast(Mapping[str, object], attempt_policy_body).get("reservation_usd")
            for record in terminal_index.values()
        )
    ):
        raise CommandError(
            "quarantine recovery outputs do not partition its attempt authority"
        )
    count_mismatch = run_card.get("record_count") != len(manifest_index)
    if terminal_aware_card:
        count_mismatch = count_mismatch or (
            run_card.get("authorized_document_count") != len(authorized_documents)
            or run_card.get("recovered_document_count") != len(manifest_index)
            or run_card.get("terminal_unavailable_document_count")
            != len(terminal_index)
        )
    if count_mismatch:
        raise CommandError("quarantine recovery record count differs")
    for key, record in manifest_index.items():
        if key not in cast(set[tuple[str, str]], selected_document_keys):
            raise CommandError(
                "quarantine recovery document is outside target selection"
            )
        if (
            record.get("recovery_origin") != "unknown_status_attempt"
            or record.get("free_or_purchased") != "purchased"
            or record.get("parser_eligible") is not False
            or record.get("packet_eligible") is not False
            or "source_url" in record
        ):
            raise CommandError(f"invalid quarantine recovery record: {key}")
    if any(
        key not in cast(set[tuple[str, str]], selected_document_keys)
        for key in terminal_index
    ):
        raise CommandError("terminal unavailable operation is outside target selection")
    _require_snapshot_unchanged(
        {
            run_card_path: run_card_bytes,
            **{path: source_snapshot[name] for name, path in source_paths.items()},
            manifest_path: manifest_bytes,
            purchased_case_relevance_path: purchased_case_relevance_bytes,
            restriction_path: restriction_bytes,
            review_requests_path: review_requests_bytes,
            **(
                {terminal_unavailable_path: terminal_unavailable_bytes}
                if terminal_unavailable_path is not None
                else {}
            ),
        },
        label="quarantine recovery artifact",
    )
    return {
        "recovery_stage": "recover-recap-fetch-quarantine",
        "manifest_path": manifest_path,
        "manifest_records": manifest_records,
        "recovery_path": restriction_path,
        "document_root": document_root,
        "run_card_path": run_card_path,
        "restriction_path": restriction_path,
        "review_requests_path": review_requests_path,
        "terminal_unavailable_path": terminal_unavailable_path,
        "case_relevance_path": purchased_case_relevance_path,
        "target_case_relevance_path": recovery_inputs[1],
        **(
            {
                "replacement_purchase_authority_path": recovery_inputs[7],
                "attempt_policy_path": recovery_inputs[6],
            }
            if replacement_mode
            else {
                "target_projection_run_card_path": recovery_inputs[2],
                "attempt_policy_path": recovery_inputs[7],
            }
        ),
        "verified_artifact_bytes": {
            os.path.abspath(run_card_path): run_card_bytes,
            **normalized_source_snapshot,
            os.path.abspath(manifest_path): manifest_bytes,
            os.path.abspath(purchased_case_relevance_path): (
                purchased_case_relevance_bytes
            ),
            os.path.abspath(restriction_path): restriction_bytes,
            os.path.abspath(review_requests_path): review_requests_bytes,
            **(
                {
                    os.path.abspath(terminal_unavailable_path): (
                        terminal_unavailable_bytes
                    )
                }
                if terminal_unavailable_path is not None
                else {}
            ),
        },
        "historical_purchase_operations": historical_operations,
        "historical_purchase_state_sha256": historical_purchase_state_sha256,
        "purchase_policy_sha256": purchase_policy.policy_sha256,
    }


def _materializer_recovery_source_commitments(
    recovery: Mapping[str, object],
) -> dict[str, object]:
    raw_verified_bytes = recovery.get("verified_artifact_bytes")
    verified_bytes: Mapping[str, bytes]
    if isinstance(raw_verified_bytes, Mapping):
        verified_bytes = cast(Mapping[str, bytes], raw_verified_bytes)
    else:
        verified_bytes = {}

    def committed(path: Path) -> dict[str, str]:
        payload = verified_bytes.get(os.path.abspath(path))
        if payload is None:
            return _materializer_file_commitment(path)
        return _file_commitment_from_bytes(path, payload)

    commitments: dict[str, object] = {
        "purchased_recovery_run_card": committed(cast(Path, recovery["run_card_path"])),
        "purchased_download_manifest": committed(cast(Path, recovery["manifest_path"])),
    }
    stage = recovery.get("recovery_stage")
    if stage == "recover-purchased":
        commitments["purchased_recovery_manifest"] = _materializer_file_commitment(
            cast(Path, recovery["recovery_path"])
        )
        commitments["purchase_result"] = _materializer_file_commitment(
            cast(Path, recovery["purchase_result_path"])
        )
    elif stage == "recover-recap-fetch-quarantine":
        commitments["purchased_recovery_restriction_evidence"] = committed(
            cast(Path, recovery["restriction_path"])
        )
        commitments["purchased_recovery_review_requests"] = committed(
            cast(Path, recovery["review_requests_path"])
        )
        commitments["purchased_recovery_case_relevance"] = committed(
            cast(Path, recovery["case_relevance_path"])
        )
        terminal_path = recovery.get("terminal_unavailable_path")
        if isinstance(terminal_path, Path):
            commitments["purchased_recovery_terminal_unavailable"] = committed(
                terminal_path
            )
        if "target_projection_run_card_path" in recovery:
            commitments["target_projection_run_card"] = committed(
                cast(Path, recovery["target_projection_run_card_path"])
            )
        else:
            commitments["replacement_purchase_authority"] = committed(
                cast(Path, recovery["replacement_purchase_authority_path"])
            )
        commitments["purchased_recovery_attempt_policy"] = committed(
            cast(Path, recovery["attempt_policy_path"])
        )
    elif stage == "consolidate-replacement-recovery":
        commitments["purchased_recovery_restriction_evidence"] = committed(
            cast(Path, recovery["restriction_path"])
        )
        commitments["purchased_recovery_resolved_documents"] = committed(
            cast(Path, recovery["resolved_path"])
        )
    else:
        raise CommandError("unsupported materializer recovery stage")
    return commitments


def _verify_materializer_recovery_clearance_binding(
    *,
    recovery: Mapping[str, object],
    clearance_lineage: Mapping[str, object],
) -> None:
    """Require quarantine clearance to consume the recovery-produced inputs."""

    if recovery.get("recovery_stage") in {
        "recover-purchased",
        "consolidate-replacement-recovery",
    }:
        return
    if recovery.get("recovery_stage") != "recover-recap-fetch-quarantine":
        raise CommandError("unsupported materializer recovery stage")
    recovery_requests = recovery.get("review_requests_path")
    clearance_requests = clearance_lineage.get("requests_path")
    recovery_restrictions = recovery.get("restriction_path")
    clearance_restrictions = clearance_lineage.get("restriction_path")
    recovery_relevance = recovery.get("case_relevance_path")
    clearance_relevance = clearance_lineage.get("case_relevance_path")
    if not isinstance(recovery_requests, Path) or not isinstance(
        clearance_requests, Path
    ):
        raise CommandError("quarantine clearance lacks review-request lineage")
    if recovery_requests.resolve() != clearance_requests.resolve():
        raise CommandError("quarantine clearance committed different review requests")
    if not isinstance(recovery_restrictions, Path) or not isinstance(
        clearance_restrictions, Path
    ):
        raise CommandError("quarantine clearance lacks restriction-evidence lineage")
    if recovery_restrictions.resolve() != clearance_restrictions.resolve():
        raise CommandError(
            "quarantine clearance committed different restriction evidence"
        )
    if not isinstance(recovery_relevance, Path) or not isinstance(
        clearance_relevance, Path
    ):
        raise CommandError("quarantine clearance lacks case-relevance lineage")
    if recovery_relevance.resolve() != clearance_relevance.resolve():
        raise CommandError("quarantine clearance committed different case relevance")


def _verify_materializer_clearance_lineage(
    *,
    manifest_path: Path,
    clearance_path: Path,
    run_card_path: Path,
    captured_artifact_bytes: Mapping[str, bytes] | None = None,
    allow_legacy_implicit_quarantine: bool = False,
    authority_transition_capability: object | None = None,
    attempt_transition_capability: object | None = None,
    resolved_transition_prior_snapshot: CaseDevPurchaseSnapshot | None = None,
    recovery_authority_transition_capability: object | None = None,
    recovery_attempt_transition_capability: object | None = None,
) -> dict[str, object]:
    _require_materializer_artifact(clearance_path, label="purchased clearance")
    validated_run_card_bytes = _require_materializer_artifact(
        run_card_path, label="purchased clearance run card"
    )
    run_card_bytes = (
        _captured_or_stable_input(
            run_card_path,
            label="purchased clearance run card",
            captured_artifact_bytes=captured_artifact_bytes,
        )
        if captured_artifact_bytes is not None
        else validated_run_card_bytes
    )
    run_card = _projection_json_object(run_card_bytes, source=run_card_path)
    if run_card.get("schema_version") in {
        _REPLACEMENT_RECOVERY_CARD_SCHEMA,
        _REPLACEMENT_RECOVERY_CARD_SCHEMA_V2,
    }:
        expected_root = run_card_path.parents[1]
        restriction_path = expected_root / "restriction-evidence.jsonl"
        resolved_path = expected_root / "resolved-post-recovery-documents.jsonl"
        expected_paths = (
            expected_root / "purchased-document-downloads.jsonl",
            expected_root / "disclosure-clearance.jsonl",
            restriction_path,
            resolved_path,
        )
        if (
            manifest_path.resolve() != expected_paths[0].resolve()
            or clearance_path.resolve() != expected_paths[1].resolve()
        ):
            raise CommandError(
                "consolidated replacement clearance paths differ from recovery"
            )
        output_commitments = run_card.get("output_commitments")
        if not isinstance(output_commitments, Mapping):
            raise CommandError(
                "consolidated replacement clearance lacks output commitments"
            )
        snapshots = {
            path: _captured_or_stable_input(
                path,
                label="consolidated replacement clearance output",
                captured_artifact_bytes=captured_artifact_bytes,
            )
            for path in expected_paths
        }
        for path, payload in snapshots.items():
            if cast(Mapping[str, object], output_commitments).get(
                path.name
            ) != _bytes_sha256(payload):
                raise CommandError(
                    "consolidated replacement clearance commitment changed"
                )
        manifest_records = _projection_jsonl_records(
            snapshots[expected_paths[0]], source=expected_paths[0]
        )
        clearance_records = _projection_jsonl_records(
            snapshots[expected_paths[1]], source=expected_paths[1]
        )
        if set(
            _materializer_record_index(
                manifest_records,
                label="consolidated replacement manifest",
            )
        ) != set(
            _materializer_record_index(
                clearance_records,
                label="consolidated replacement clearance",
            )
        ):
            raise CommandError("consolidated replacement clearance coverage differs")
        return {
            "lineage_kind": "replacement_recovery_consolidation",
            "verified_artifact_bytes": {
                os.path.abspath(run_card_path): run_card_bytes,
                **{
                    os.path.abspath(path): payload
                    for path, payload in snapshots.items()
                },
            },
            "clearance_records": clearance_records,
            "manifest_path": manifest_path,
            "restriction_path": restriction_path,
            "restriction_records": _projection_jsonl_records(
                snapshots[restriction_path], source=restriction_path
            ),
            "resolved_path": resolved_path,
        }
    verified_snapshot = _complete_clearance_artifact_snapshot(
        run_card=run_card,
        run_card_path=run_card_path,
        run_card_bytes=run_card_bytes,
        clearance_path=clearance_path,
        captured_artifact_bytes=captured_artifact_bytes,
    )
    sources = run_card.get("source_commitments")
    if not isinstance(sources, Mapping):
        raise CommandError("purchased clearance run card lacks source commitments")
    source_records = cast(Mapping[str, object], sources)
    committed_manifest = _materializer_committed_path(
        source_records,
        "download_manifest",
        captured_artifact_bytes=verified_snapshot,
    )
    if committed_manifest.resolve() != manifest_path.resolve():
        raise CommandError("purchased clearance committed a different manifest")
    provider_free_schema = run_card.get("schema_version")
    if provider_free_schema in {
        "legalforecast.provenance_quarantine_clearance_run_card.v1",
        "legalforecast.provenance_public_marker_clearance_run_card.v1",
    }:
        case_relevance_path = _materializer_committed_path(
            source_records,
            "case_relevance",
            captured_artifact_bytes=verified_snapshot,
        )
        restriction_path = _materializer_committed_path(
            source_records,
            "restriction_evidence",
            captured_artifact_bytes=verified_snapshot,
        )
        requests_path = _materializer_committed_path(
            source_records,
            "review_requests",
            captured_artifact_bytes=verified_snapshot,
        )
        worksheet_path = _materializer_committed_path(
            source_records,
            "exception_worksheet",
            captured_artifact_bytes=verified_snapshot,
        )
        cohort_policy_path = _materializer_committed_path(
            source_records,
            "cohort_policy",
            captured_artifact_bytes=verified_snapshot,
        )
        routing_plan_path = _materializer_committed_path(
            source_records,
            "routing_plan",
            captured_artifact_bytes=verified_snapshot,
        )
        public_marker_policy_path = (
            _materializer_committed_path(
                source_records,
                "public_marker_clearance_policy",
                captured_artifact_bytes=verified_snapshot,
            )
            if provider_free_schema
            == "legalforecast.provenance_public_marker_clearance_run_card.v1"
            else None
        )
        _, authenticated_recovery_capability = (
            _verify_authenticated_clearance_run_card_with_capability(
                clearance_path=clearance_path,
                clearance_run_card_path=run_card_path,
                expected_download_manifest_path=manifest_path,
                expected_restriction_path=restriction_path,
                captured_artifact_bytes=verified_snapshot,
                allow_legacy_implicit_quarantine=allow_legacy_implicit_quarantine,
                authority_transition_capability=authority_transition_capability,
                attempt_transition_capability=attempt_transition_capability,
                resolved_transition_prior_snapshot=(resolved_transition_prior_snapshot),
                recovery_authority_transition_capability=(
                    recovery_authority_transition_capability
                ),
                recovery_attempt_transition_capability=(
                    recovery_attempt_transition_capability
                ),
            )
        )
        clearance_records = _projection_jsonl_records(
            verified_snapshot[os.path.abspath(clearance_path)],
            source=clearance_path,
        )
        return {
            "lineage_kind": (
                "provider_free_recovered_public"
                if authenticated_recovery_capability is not None
                else "provider_free_exception_quarantine"
            ),
            "verified_artifact_bytes": verified_snapshot,
            "clearance_records": clearance_records,
            **(
                {
                    "authenticated_recovery_capability": (
                        authenticated_recovery_capability
                    )
                }
                if authenticated_recovery_capability is not None
                else {}
            ),
            "manifest_path": manifest_path,
            "case_relevance_path": case_relevance_path,
            "restriction_path": restriction_path,
            "restriction_records": _projection_jsonl_records(
                verified_snapshot[os.path.abspath(restriction_path)],
                source=restriction_path,
            ),
            "requests_path": requests_path,
            "worksheet_path": worksheet_path,
            "cohort_policy_path": cohort_policy_path,
            "routing_plan_path": routing_plan_path,
            **(
                {"public_marker_policy_path": public_marker_policy_path}
                if public_marker_policy_path is not None
                else {}
            ),
        }
    clearance_authority = run_card.get("clearance_authority")
    authority_kind = (
        cast(Mapping[str, object], clearance_authority).get("kind")
        if isinstance(clearance_authority, Mapping)
        else None
    )
    if authority_kind == "provenance_first_with_john_exceptions":
        case_relevance_path = _materializer_committed_path(
            source_records,
            "case_relevance",
            captured_artifact_bytes=verified_snapshot,
        )
        restriction_path = _materializer_committed_path(
            source_records,
            "restriction_evidence",
            captured_artifact_bytes=verified_snapshot,
        )
        requests_path = _materializer_committed_path(
            source_records,
            "review_requests",
            captured_artifact_bytes=verified_snapshot,
        )
        worksheet_path = _materializer_committed_path(
            source_records,
            "exception_worksheet",
            captured_artifact_bytes=verified_snapshot,
        )
        cohort_policy_path = _materializer_committed_path(
            source_records,
            "cohort_policy",
            captured_artifact_bytes=verified_snapshot,
        )
        decisions_path = _materializer_committed_path(
            source_records,
            "exception_decisions",
            captured_artifact_bytes=verified_snapshot,
        )
        recorder_path = _materializer_committed_path(
            source_records,
            "exception_review_run_card",
            captured_artifact_bytes=verified_snapshot,
        )
        routing_plan_path = _materializer_committed_path(
            source_records,
            "routing_plan",
            captured_artifact_bytes=verified_snapshot,
        )
        for label, path in (
            ("purchased review requests", requests_path),
            ("purchased exception worksheet", worksheet_path),
            ("purchased cohort policy", cohort_policy_path),
            ("purchased restriction evidence", restriction_path),
        ):
            _require_materializer_artifact(path, label=label)
        authenticated_clearance_capability = _issue_verified_lineage_capability(
            clearance_path=clearance_path,
            clearance_run_card_path=run_card_path,
            expected_download_manifest_path=manifest_path,
            expected_restriction_path=restriction_path,
            captured_artifact_bytes=verified_snapshot,
        )
        return {
            "lineage_kind": "provenance_first_with_john_exceptions",
            "verified_artifact_bytes": verified_snapshot,
            "authenticated_clearance_capability": (authenticated_clearance_capability),
            "clearance_records": _projection_jsonl_records(
                _captured_or_stable_input(
                    clearance_path,
                    label="purchased disclosure clearance",
                    captured_artifact_bytes=verified_snapshot,
                ),
                source=clearance_path,
            ),
            "manifest_path": manifest_path,
            "case_relevance_path": case_relevance_path,
            "restriction_path": restriction_path,
            "restriction_records": _projection_jsonl_records(
                _captured_or_stable_input(
                    restriction_path,
                    label="purchased restriction evidence",
                    captured_artifact_bytes=verified_snapshot,
                ),
                source=restriction_path,
            ),
            "requests_path": requests_path,
            "worksheet_path": worksheet_path,
            "cohort_policy_path": cohort_policy_path,
            "decisions_path": decisions_path,
            "recorder_path": recorder_path,
            "routing_plan_path": routing_plan_path,
        }
    reviews_path = _materializer_committed_path(
        source_records, "reviews", captured_artifact_bytes=verified_snapshot
    )
    receipt_path = _materializer_committed_path(
        source_records, "review_receipt", captured_artifact_bytes=verified_snapshot
    )
    requests_path = _materializer_committed_path(
        source_records, "review_requests", captured_artifact_bytes=verified_snapshot
    )
    worksheet_path = _materializer_committed_path(
        source_records, "review_worksheet", captured_artifact_bytes=verified_snapshot
    )
    reviewer_policy_path = _materializer_committed_path(
        source_records,
        "reviewer_policy",
        captured_artifact_bytes=verified_snapshot,
    )
    cohort_policy_path = _materializer_committed_path(
        source_records, "cohort_policy", captured_artifact_bytes=verified_snapshot
    )
    restriction_path = _materializer_committed_path(
        source_records,
        "restriction_evidence",
        captured_artifact_bytes=verified_snapshot,
    )
    for label, path in (
        ("purchased review", reviews_path),
        ("purchased review receipt", receipt_path),
        ("purchased review requests", requests_path),
        ("purchased review worksheet", worksheet_path),
        ("purchased reviewer policy", reviewer_policy_path),
        ("purchased cohort policy", cohort_policy_path),
        ("purchased restriction evidence", restriction_path),
    ):
        _require_materializer_artifact(path, label=label)
    clearance_bytes = verified_snapshot[os.path.abspath(clearance_path)]
    restriction_bytes = verified_snapshot[os.path.abspath(restriction_path)]
    clearance_records = _projection_jsonl_records(
        clearance_bytes, source=clearance_path
    )
    restriction_records = _projection_jsonl_records(
        restriction_bytes, source=restriction_path
    )
    authority_record = run_card.get("review_authority")
    if not isinstance(authority_record, Mapping):
        raise CommandError("purchased clearance run card lacks review authority")
    reviewer_policy_bytes = verified_snapshot[os.path.abspath(reviewer_policy_path)]
    try:
        disclosure_authority = load_main_disclosure_review_authority(
            _projection_json_object(
                verified_snapshot[os.path.abspath(cohort_policy_path)],
                source=cohort_policy_path,
            ),
            reviewer_policy_bytes=reviewer_policy_bytes,
        )
    except DisclosureReviewAuthorityError as exc:
        raise CommandError(str(exc)) from exc
    _validate_clearance_run_card_commitments(
        run_card,
        source_paths={
            "download_manifest": manifest_path,
            "restriction_evidence": restriction_path,
            "disclosure_clearance": clearance_path,
        },
        source_sha256={
            "download_manifest": _bytes_sha256(
                verified_snapshot[os.path.abspath(manifest_path)]
            ),
            "restriction_evidence": _bytes_sha256(restriction_bytes),
            "disclosure_clearance": _bytes_sha256(clearance_bytes),
        },
    )
    validate_authenticated_clearance_lineage(
        clearance_records=clearance_records,
        clearance_artifact_bytes=clearance_bytes,
        clearance_run_card=run_card,
        clearance_run_card_bytes=run_card_bytes,
        reviews_artifact_bytes=verified_snapshot[os.path.abspath(reviews_path)],
        review_receipt_artifact=_projection_json_object(
            verified_snapshot[os.path.abspath(receipt_path)], source=receipt_path
        ),
        review_receipt_bytes=verified_snapshot[os.path.abspath(receipt_path)],
        review_requests_artifact_bytes=verified_snapshot[
            os.path.abspath(requests_path)
        ],
        review_worksheet_artifact=_projection_json_object(
            verified_snapshot[os.path.abspath(worksheet_path)], source=worksheet_path
        ),
        review_worksheet_bytes=verified_snapshot[os.path.abspath(worksheet_path)],
        reviewer_policy_bytes=reviewer_policy_bytes,
        disclosure_authority=disclosure_authority,
        cohort_policy_artifact_bytes=verified_snapshot[
            os.path.abspath(cohort_policy_path)
        ],
        download_manifest_artifact_bytes=verified_snapshot[
            os.path.abspath(manifest_path)
        ],
        restriction_records=restriction_records,
        restriction_artifact_bytes=restriction_bytes,
    )
    return {
        "lineage_kind": "legacy_authenticated_review",
        "verified_artifact_bytes": verified_snapshot,
        "clearance_records": clearance_records,
        "manifest_path": manifest_path,
        "restriction_path": restriction_path,
        "restriction_records": restriction_records,
        "reviews_path": reviews_path,
        "receipt_path": receipt_path,
        "requests_path": requests_path,
        "worksheet_path": worksheet_path,
        "reviewer_policy_path": reviewer_policy_path,
        "cohort_policy_path": cohort_policy_path,
        "disclosure_authority": disclosure_authority,
    }


def _materializer_clearance_lineage_kwargs(
    *,
    clearance_path: Path,
    run_card_path: Path,
    lineage: Mapping[str, object],
) -> dict[str, Any]:
    if lineage.get("lineage_kind") == "provider_free_recovered_public":
        restriction_path = cast(Path, lineage["restriction_path"])
        routing_plan_path = cast(Path, lineage["routing_plan_path"])
        worksheet_path = cast(Path, lineage["worksheet_path"])
        cohort_policy_path = cast(Path, lineage["cohort_policy_path"])
        manifest_path = cast(Path, lineage["manifest_path"])
        authenticated_verified_bytes = dict(
            cast(Mapping[str, bytes], lineage["verified_artifact_bytes"])
        )
        recovery_capability = lineage["authenticated_recovery_capability"]
        for path, payload in _consume_recovered_public_source_snapshots(
            recovery_capability
        ).items():
            key = os.path.abspath(path)
            existing = authenticated_verified_bytes.get(key)
            if existing is not None and existing != payload:
                raise CommandError(
                    "recovered-public clearance and recovery snapshots conflict"
                )
            authenticated_verified_bytes[key] = payload

        def snapshot_bytes(path: Path) -> bytes:
            key = os.path.abspath(path)
            try:
                return authenticated_verified_bytes[key]
            except KeyError:
                raise CommandError(
                    f"verified recovered-public snapshot lacks downstream input: {path}"
                ) from None

        return {
            "clearance_artifact_bytes": snapshot_bytes(clearance_path),
            "clearance_run_card": _projection_json_object(
                snapshot_bytes(run_card_path), source=run_card_path
            ),
            "clearance_run_card_bytes": snapshot_bytes(run_card_path),
            "reviews_artifact_bytes": b"",
            "review_receipt_artifact": {},
            "review_receipt_bytes": b"",
            "review_requests_artifact_bytes": b"",
            "review_worksheet_artifact": _projection_json_object(
                snapshot_bytes(worksheet_path), source=worksheet_path
            ),
            "review_worksheet_bytes": snapshot_bytes(worksheet_path),
            "reviewer_policy_bytes": snapshot_bytes(routing_plan_path),
            "disclosure_authority": None,
            "cohort_policy_artifact_bytes": snapshot_bytes(cohort_policy_path),
            "download_manifest_artifact_bytes": snapshot_bytes(manifest_path),
            "restriction_records": cast(
                Sequence[Mapping[str, Any]], lineage["restriction_records"]
            ),
            "restriction_artifact_bytes": snapshot_bytes(restriction_path),
            "_verified_recovery_capability": lineage[
                "authenticated_recovery_capability"
            ],
            "_verified_clearance_source_snapshots": authenticated_verified_bytes,
        }
    if lineage.get("lineage_kind") == "provenance_first_with_john_exceptions":
        requests_path = cast(Path, lineage["requests_path"])
        worksheet_path = cast(Path, lineage["worksheet_path"])
        restriction_path = cast(Path, lineage["restriction_path"])
        decisions_path = cast(Path, lineage["decisions_path"])
        recorder_path = cast(Path, lineage["recorder_path"])
        routing_plan_path = cast(Path, lineage["routing_plan_path"])
        cohort_policy_path = cast(Path, lineage["cohort_policy_path"])
        verified_bytes = cast(Mapping[str, bytes], lineage["verified_artifact_bytes"])

        def snapshot_bytes(path: Path) -> bytes:
            try:
                return verified_bytes[os.path.abspath(path)]
            except KeyError as exc:
                raise CommandError(
                    f"verified provenance snapshot lacks downstream input: {path}"
                ) from exc

        return {
            "clearance_artifact_bytes": snapshot_bytes(clearance_path),
            "clearance_run_card": _projection_json_object(
                snapshot_bytes(run_card_path), source=run_card_path
            ),
            "clearance_run_card_bytes": snapshot_bytes(run_card_path),
            "reviews_artifact_bytes": snapshot_bytes(decisions_path),
            "review_receipt_artifact": _projection_json_object(
                snapshot_bytes(recorder_path), source=recorder_path
            ),
            "review_receipt_bytes": snapshot_bytes(recorder_path),
            "review_requests_artifact_bytes": snapshot_bytes(requests_path),
            "review_worksheet_artifact": _projection_json_object(
                snapshot_bytes(worksheet_path), source=worksheet_path
            ),
            "review_worksheet_bytes": snapshot_bytes(worksheet_path),
            "reviewer_policy_bytes": snapshot_bytes(routing_plan_path),
            "disclosure_authority": None,
            "cohort_policy_artifact_bytes": snapshot_bytes(cohort_policy_path),
            "download_manifest_artifact_bytes": snapshot_bytes(
                cast(Path, lineage["manifest_path"])
            ),
            "restriction_records": cast(
                Sequence[Mapping[str, Any]], lineage["restriction_records"]
            ),
            "restriction_artifact_bytes": snapshot_bytes(restriction_path),
            "_verified_provenance_capability": lineage[
                "authenticated_clearance_capability"
            ],
        }
    if lineage.get("lineage_kind") == "replacement_recovery_consolidation":
        capability = lineage.get("consolidated_resolved_capability")
        if capability is None:
            raise CommandError(
                "consolidated clearance lacks verifier-issued resolved authority"
            )
        return {"_verified_consolidated_recovery_capability": capability}
    if lineage.get("lineage_kind") != "legacy_authenticated_review":
        raise CommandError("unsupported clearance lineage kind")
    reviews_path = cast(Path, lineage["reviews_path"])
    receipt_path = cast(Path, lineage["receipt_path"])
    requests_path = cast(Path, lineage["requests_path"])
    worksheet_path = cast(Path, lineage["worksheet_path"])
    reviewer_policy_path = cast(Path, lineage["reviewer_policy_path"])
    restriction_path = cast(Path, lineage["restriction_path"])
    return {
        "clearance_artifact_bytes": clearance_path.read_bytes(),
        "clearance_run_card": _read_json_object(run_card_path),
        "clearance_run_card_bytes": run_card_path.read_bytes(),
        "reviews_artifact_bytes": reviews_path.read_bytes(),
        "review_receipt_artifact": _read_json_object(receipt_path),
        "review_receipt_bytes": receipt_path.read_bytes(),
        "review_requests_artifact_bytes": requests_path.read_bytes(),
        "review_worksheet_artifact": _read_json_object(worksheet_path),
        "review_worksheet_bytes": worksheet_path.read_bytes(),
        "reviewer_policy_bytes": reviewer_policy_path.read_bytes(),
        "disclosure_authority": cast(
            DisclosureReviewAuthority, lineage["disclosure_authority"]
        ),
        "cohort_policy_artifact_bytes": cast(
            Path, lineage["cohort_policy_path"]
        ).read_bytes(),
        "download_manifest_artifact_bytes": cast(
            Path, lineage["manifest_path"]
        ).read_bytes(),
        "restriction_records": cast(
            Sequence[Mapping[str, Any]], lineage["restriction_records"]
        ),
        "restriction_artifact_bytes": restriction_path.read_bytes(),
    }


def _build_resolved_post_recovery_dispatch(
    **kwargs: Any,
) -> tuple[dict[str, object], ...]:
    """Use the private provenance path only after the CLI fully replayed it."""

    values = dict(kwargs)
    verified = values.pop("_verified_provenance_capability", None)
    recovered = values.pop("_verified_recovery_capability", None)
    terminal_disposition = values.pop("_verified_terminal_disposition_capability", None)
    values.pop("_verified_clearance_source_snapshots", None)
    if recovered is not None:
        if verified is not None:
            raise CommandError("conflicting resolved clearance capabilities")
        return _build_resolved_recovered_public(
            **values,
            verified_recovery_capability=recovered,
            verified_terminal_disposition_capability=terminal_disposition,
        )
    if verified is None:
        return build_resolved_post_recovery_documents(**values)
    return _build_resolved_post_recovery_documents_with_authenticated_lineage(
        **values,
        verified_lineage_capability=verified,
    )


def _require_resolved_post_recovery_dispatch(**kwargs: Any) -> None:
    """Replay resolved lineage through the verifier-owned provenance path."""

    values = dict(kwargs)
    verified = values.pop("_verified_provenance_capability", None)
    recovered = values.pop("_verified_recovery_capability", None)
    consolidated = values.pop("_verified_consolidated_recovery_capability", None)
    terminal_disposition = values.pop("_verified_terminal_disposition_capability", None)
    values.pop("_verified_clearance_source_snapshots", None)
    if consolidated is not None:
        if recovered is not None or verified is not None:
            raise CommandError("conflicting resolved clearance capabilities")
        authority = _consume_consolidated_resolved_capability(consolidated)
        expected = {
            "selection_bytes": _projection_jsonl_bytes(
                cast(Sequence[Mapping[str, Any]], values["selection_records"])
            ),
            "manifest_bytes": _projection_jsonl_bytes(
                cast(Sequence[Mapping[str, Any]], values["download_records"])
            ),
            "clearance_bytes": _projection_jsonl_bytes(
                cast(Sequence[Mapping[str, Any]], values["clearance_records"])
            ),
            "resolved_bytes": _projection_jsonl_bytes(
                cast(Sequence[Mapping[str, Any]], values["resolved_records"])
            ),
        }
        if any(authority[name] != payload for name, payload in expected.items()):
            raise CommandError("consolidated resolved clearance inputs differ")
        return
    if recovered is not None:
        if verified is not None:
            raise CommandError("conflicting resolved clearance capabilities")
        _require_resolved_recovered_public(
            **values,
            verified_recovery_capability=recovered,
            verified_terminal_disposition_capability=terminal_disposition,
        )
        return
    if verified is None:
        require_resolved_post_recovery_documents(**values)
        return
    _require_resolved_post_recovery_documents_with_authenticated_lineage(
        **values,
        verified_lineage_capability=verified,
    )


def _require_resolved_operation_bindings_dispatch(
    *,
    clearance_kwargs: Mapping[str, Any],
    purchase_operation_records: Sequence[Mapping[str, Any]],
    resolved_records: Sequence[Mapping[str, Any]],
    expected_purchase_policy_sha256: str,
) -> None:
    """Replay direct-queue bindings only through recovered-public authority."""

    recovered = clearance_kwargs.get("_verified_recovery_capability")
    consolidated = clearance_kwargs.get("_verified_consolidated_recovery_capability")
    terminal_disposition = clearance_kwargs.get(
        "_verified_terminal_disposition_capability"
    )
    requires_recovered_authority = any(
        record.get("schema_version") == RESOLVED_POST_RECOVERY_SCHEMA_VERSION_V4
        for record in resolved_records
    )
    if consolidated is not None:
        if recovered is not None:
            raise ResolvedPostRecoveryError(
                "conflicting resolved clearance capabilities"
            )
        authority = _consume_consolidated_resolved_capability(consolidated)
        if (
            authority["purchase_operations_bytes"]
            != _projection_jsonl_bytes(purchase_operation_records)
            or authority["resolved_bytes"] != _projection_jsonl_bytes(resolved_records)
            or authority["purchase_policy_sha256"] != expected_purchase_policy_sha256
        ):
            raise ResolvedPostRecoveryError(
                "consolidated resolved operation inputs differ"
            )
        return
    if recovered is None:
        if requires_recovered_authority:
            raise ResolvedPostRecoveryError(
                "V4 resolved records require verifier-issued recovery authority"
            )
        require_resolved_post_recovery_operation_bindings(
            purchase_operation_records=purchase_operation_records,
            resolved_records=resolved_records,
            expected_purchase_policy_sha256=expected_purchase_policy_sha256,
        )
        return
    _require_resolved_recovered_public_operation_bindings(
        purchase_operation_records=purchase_operation_records,
        resolved_records=resolved_records,
        expected_purchase_policy_sha256=expected_purchase_policy_sha256,
        verified_recovery_capability=recovered,
        verified_terminal_disposition_capability=terminal_disposition,
    )


def _require_resolved_parse_requests_dispatch(
    *,
    clearance_kwargs: Mapping[str, Any],
    selection_records: Sequence[Mapping[str, Any]],
    request_records: Sequence[Mapping[str, Any]],
    resolved_records: Sequence[Mapping[str, Any]],
) -> None:
    """Replay direct-queue parse bindings only through verifier authority."""

    recovered = clearance_kwargs.get("_verified_recovery_capability")
    consolidated = clearance_kwargs.get("_verified_consolidated_recovery_capability")
    terminal_disposition = clearance_kwargs.get(
        "_verified_terminal_disposition_capability"
    )
    requires_recovered_authority = any(
        record.get("schema_version") == RESOLVED_POST_RECOVERY_SCHEMA_VERSION_V4
        for record in resolved_records
    )
    arguments = {
        "selection_records": selection_records,
        "request_records": request_records,
        "resolved_records": resolved_records,
    }
    if consolidated is not None:
        if recovered is not None:
            raise ResolvedPostRecoveryError(
                "conflicting resolved clearance capabilities"
            )
        authority = _consume_consolidated_resolved_capability(consolidated)
        if authority["selection_bytes"] != _projection_jsonl_bytes(
            selection_records
        ) or authority["resolved_bytes"] != _projection_jsonl_bytes(resolved_records):
            raise ResolvedPostRecoveryError("consolidated resolved parse inputs differ")
        requests = _materializer_record_index(
            request_records, label="consolidated resolved parse requests"
        )
        for record in resolved_records:
            key = _materializer_record_key(record)
            request = requests.get(key)
            if request is None or (
                request.get("expected_sha256") != record.get("content_sha256")
                or request.get("expected_byte_count") != record.get("byte_count")
                or request.get("resolved_post_recovery_sha256")
                != record.get("record_sha256")
            ):
                raise ResolvedPostRecoveryError(
                    f"parse request does not bind consolidated resolved material: {key}"
                )
        return
    if recovered is None:
        if requires_recovered_authority:
            raise ResolvedPostRecoveryError(
                "V4 resolved records require verifier-issued recovery authority"
            )
        require_resolved_post_recovery_parse_requests(**arguments)
        return
    _require_resolved_recovered_public_parse_requests(
        **arguments,
        verified_recovery_capability=recovered,
        verified_terminal_disposition_capability=terminal_disposition,
    )


def _verify_materializer_purchase_operations(
    operations: Sequence[Mapping[str, Any]],
    *,
    purchased_manifest: Sequence[Mapping[str, Any]],
) -> None:
    operation_index = _materializer_record_index(
        operations, label="purchase ledger operations"
    )
    for record in purchased_manifest:
        key = _materializer_record_key(record)
        operation = operation_index.get(key)
        if operation is None:
            raise CommandError(f"purchase ledger lacks recovered document: {key}")
        operation_key = operation.get("operation_key")
        if not isinstance(operation_key, str) or not operation_key:
            raise CommandError(
                f"purchase ledger lacks broker operation identity: {key}"
            )
        evidence = operation.get("material_evidence")
        if record.get("recovery_origin") == "unknown_status_attempt":
            if "source_url" in record:
                raise CommandError(
                    f"unknown-origin recovery must remain URL-free: {key}"
                )
            if (
                operation.get("material_authority") != "unknown_status_attempt"
                or operation.get("material_state") != "cleared_public"
                or not isinstance(operation.get("resolved_document_sha256"), str)
                or record.get("purchase_operation_key") != operation_key
                or record.get("attempt_policy_sha256")
                != operation.get("attempt_policy_sha256")
                or not isinstance(evidence, Mapping)
            ):
                raise CommandError(
                    f"unknown-origin recovery lacks exact operation lineage: {key}"
                )
            material = cast(Mapping[str, object], evidence)
            if (
                material.get("content_sha256") != _required_str(record, "sha256")
                or material.get("byte_count") != _required_int(record, "byte_count")
                or material.get("provider_detail_sha256")
                != record.get("fresh_recap_detail_sha256")
            ):
                raise CommandError(
                    f"unknown-origin recovery content lineage differs: {key}"
                )
            continue
        if operation.get("status") != "confirmed":
            raise CommandError(f"purchase ledger document is not confirmed: {key}")
        source_url = _required_str(record, "source_url")
        recorded_urls = _materializer_operation_download_urls(operation, key=key)
        url_hash_matches = False
        if isinstance(evidence, Mapping):
            material = cast(Mapping[str, object], evidence)
            url_sha256 = material.get("download_url_sha256")
            if url_sha256 is not None:
                url_hash_matches = (
                    url_sha256 == hashlib.sha256(source_url.encode()).hexdigest()
                )
                if not url_hash_matches:
                    raise CommandError(
                        f"purchase ledger download URL hash differs: {key}"
                    )
            content_sha256 = material.get("content_sha256")
            if content_sha256 is not None and content_sha256 != _required_str(
                record, "sha256"
            ):
                raise CommandError(f"purchase ledger content hash differs: {key}")
            byte_count = material.get("byte_count")
            if byte_count is not None and byte_count != _required_int(
                record, "byte_count"
            ):
                raise CommandError(f"purchase ledger byte count differs: {key}")
        if source_url not in recorded_urls and not url_hash_matches:
            raise CommandError(
                f"purchase ledger lacks authoritative download URL evidence: {key}"
            )


def _build_materializer_derivations(
    *,
    materialization: Any,
    free_manifest: Sequence[Mapping[str, Any]],
    free_clearance: Sequence[Mapping[str, Any]],
    purchased_manifest: Sequence[Mapping[str, Any]],
    purchased_clearance: Sequence[Mapping[str, Any]],
    resolved_records: Sequence[Mapping[str, Any]] = (),
) -> tuple[dict[str, object], ...]:
    source_manifests = {
        **_materializer_record_index(free_manifest, label="free source manifest"),
        **_materializer_record_index(
            purchased_manifest, label="purchased source manifest"
        ),
    }
    source_clearances = {
        **_materializer_record_index(free_clearance, label="free source clearance"),
        **_materializer_record_index(
            purchased_clearance, label="purchased source clearance"
        ),
    }
    output_manifests = _materializer_record_index(
        materialization.manifest, label="materialized manifest"
    )
    output_clearances = _materializer_record_index(
        materialization.clearance, label="materialized clearance"
    )
    expected_keys = set(source_manifests)
    resolved_by_key = _materializer_record_index(
        resolved_records, label="resolved post-recovery documents"
    )
    if set(resolved_by_key) - expected_keys:
        raise CommandError("resolved post-recovery derivation coverage differs")
    if (
        set(source_clearances) != expected_keys
        or set(output_manifests) != expected_keys
        or set(output_clearances) != expected_keys
    ):
        raise CommandError("materialization derivation coverage differs")
    records: list[dict[str, object]] = []
    for key in sorted(expected_keys):
        source_manifest = source_manifests[key]
        source_clearance = source_clearances[key]
        output_manifest = output_manifests[key]
        output_clearance = output_clearances[key]
        record: dict[str, object] = {
            "schema_version": "legalforecast.materialized_document_derivation.v1",
            "candidate_id": key[0],
            "source_document_id": key[1],
            "free_or_purchased": _required_str(source_manifest, "free_or_purchased"),
            "source_manifest_record_sha256": _canonical_json_sha256(source_manifest),
            "source_clearance_record_sha256": _canonical_json_sha256(source_clearance),
            "materialized_manifest_record_sha256": _canonical_json_sha256(
                output_manifest
            ),
            "materialized_clearance_record_sha256": _canonical_json_sha256(
                output_clearance
            ),
            "content_sha256": _required_str(output_manifest, "sha256"),
            "byte_count": _required_int(output_manifest, "byte_count"),
            "source_local_path": _required_str(source_manifest, "local_path"),
            "materialized_local_path": _required_str(output_manifest, "local_path"),
        }
        resolved = resolved_by_key.get(key)
        if resolved is not None:
            record["recovery_origin"] = "unknown_status_attempt"
            record["resolved_post_recovery_sha256"] = _required_str(
                resolved, "record_sha256"
            )
        record["record_sha256"] = _canonical_json_sha256(record)
        records.append(record)
    return tuple(records)


def _verify_materializer_resume(
    *,
    run_card_path: Path,
    input_paths: Sequence[Path],
    manifest_path: Path,
    manifest_bytes: bytes,
    clearance_path: Path,
    clearance_bytes: bytes,
    restriction_path: Path,
    restriction_bytes: bytes,
    derivations_path: Path,
    derivations_bytes: bytes,
    summary_path: Path,
    summary_bytes: bytes,
    document_root: Path,
    materialization: Any,
    source_commitments: Mapping[str, object],
    output_commitments: Mapping[str, object],
    dry_run: bool,
    authority_mode: str | None = None,
    docket_decision_partition: Mapping[str, object] | None = None,
) -> None:
    run_card_bytes = _read_singly_linked_regular_input(
        run_card_path, label="materialization resume run card"
    )
    card = _projection_json_object(run_card_bytes, source=run_card_path)
    if "authority_mode" in card and not isinstance(card["authority_mode"], str):
        raise CommandError(
            "materialize-cohort-documents resume mismatch: authority_mode"
        )
    expected = {
        "schema_version": "legalforecast.acquisition_run_card.v1",
        "stage": "materialize-cohort-documents",
        "status": "completed",
        "dry_run": dry_run,
        "execute": not dry_run,
        "record_count": len(materialization.manifest),
        "input_paths": [str(path) for path in input_paths],
        "output_paths": [
            str(manifest_path),
            str(clearance_path),
            str(restriction_path),
            str(derivations_path),
            str(summary_path),
            str(document_root),
        ],
        "paid_activity_requested": False,
        "paid_activity_executed": False,
        "source_commitments": dict(source_commitments),
        "output_commitments": dict(output_commitments) if not dry_run else {},
        "source_roots_mutated": False,
        "zero_provider_activity_evidence": True,
        **({"authority_mode": authority_mode} if authority_mode is not None else {}),
        **(
            {"docket_decision_partition": dict(docket_decision_partition)}
            if docket_decision_partition is not None
            else {}
        ),
    }
    for field, value in expected.items():
        if card.get(field) != value:
            raise CommandError(f"materialize-cohort-documents resume mismatch: {field}")
    if card.get("authority_mode") != authority_mode:
        raise CommandError(
            "materialize-cohort-documents resume mismatch: authority_mode"
        )
    if card.get("docket_decision_partition") != docket_decision_partition:
        raise CommandError(
            "materialize-cohort-documents resume mismatch: docket_decision_partition"
        )
    if dry_run:
        return
    output_snapshots = {
        path: _read_singly_linked_regular_input(
            path, label="materialization resume output"
        )
        for path in (
            manifest_path,
            clearance_path,
            restriction_path,
            derivations_path,
            summary_path,
        )
    }
    for path, payload in (
        (manifest_path, manifest_bytes),
        (clearance_path, clearance_bytes),
        (restriction_path, restriction_bytes),
        (derivations_path, derivations_bytes),
        (summary_path, summary_bytes),
    ):
        if output_snapshots[path] != payload:
            raise CommandError(
                f"materialize-cohort-documents committed output changed: {path}"
            )
    try:
        require_cleared_documents(
            materialization.manifest,
            document_root=document_root,
            clearance_records=materialization.clearance,
        )
    except DisclosureClearanceError as exc:
        raise CommandError(str(exc)) from exc
    _require_snapshot_unchanged(
        {run_card_path: run_card_bytes, **output_snapshots},
        label="materialization resume artifact",
    )


@dataclass(frozen=True, slots=True)
class _VerifiedMaterializedDownstreamLineage:
    paths: tuple[Path, ...]
    artifact_bytes: Mapping[str, bytes]
    manifest_records: tuple[Mapping[str, Any], ...]
    clearance_records: tuple[Mapping[str, Any], ...]
    selection_records: tuple[Mapping[str, Any], ...]
    resolved_records: tuple[Mapping[str, Any], ...]
    document_tree: Mapping[str, bytes]
    resolved_lineage_selection_records: tuple[Mapping[str, Any], ...] | None = None
    recovered_public_capability: object | None = None
    consolidated_recovery_capability: object | None = None
    fresh_ledger_namespace: Path | None = None
    docket_decision_authority: _MaterializerDocketDecisionAuthority | None = None
    verified_successor_selection_card: _VerifiedSuccessorSelectionCard | None = None
    authenticated_paths: tuple[Path, ...] = ()

    def __len__(self) -> int:
        return len(self.paths)

    @overload
    def __getitem__(self, index: int) -> Path: ...

    @overload
    def __getitem__(self, index: slice) -> tuple[Path, ...]: ...

    def __getitem__(self, index: int | slice) -> Path | tuple[Path, ...]:
        return self.paths[index]

    def __iter__(self) -> Iterator[Path]:
        return iter(self.paths)


def _authenticated_path_aliases(paths: Sequence[Path]) -> tuple[Path, ...]:
    """Keep absolute authenticated path spellings without resolving aliases."""

    return tuple(Path(os.path.abspath(path)) for path in paths)


def _downstream_docket_decision_descriptor(
    verified: object,
) -> _MaterializerDocketDecisionAuthority | None:
    """Return authority metadata from a replay-verified downstream lineage."""

    if verified is None:
        return None
    if isinstance(verified, _VerifiedMaterializedDownstreamLineage):
        return verified.docket_decision_authority
    raise CommandError("materialization downstream lineage has an invalid type")


def _require_materialized_downstream_lineage_unchanged(
    verified: _VerifiedMaterializedDownstreamLineage,
    *,
    document_root: Path,
) -> None:
    """Recheck captured bytes without replaying materialization authority."""

    _require_snapshot_unchanged(
        {
            Path(raw_path): payload
            for raw_path, payload in verified.artifact_bytes.items()
        },
        label="materialization downstream lineage artifact",
    )
    if _materializer_tree_snapshot(document_root) != verified.document_tree:
        raise CommandError("materialization document tree changed during execution")
    if verified.fresh_ledger_namespace is not None:
        try:
            require_fresh_purchase_ledger_namespace(verified.fresh_ledger_namespace)
        except (OSError, PurchaseApprovalError, ValueError) as exc:
            raise CommandError(str(exc)) from exc
    if verified.docket_decision_authority is not None:
        _replay_materialized_docket_decision_authority(
            verified.docket_decision_authority
        )


def _verify_materialized_downstream_lineage(
    *,
    run_card_path: Path,
    manifest_path: Path,
    clearance_path: Path,
    document_root: Path,
    selection_path: Path | None = None,
    controlled_private_root: Path | None = None,
    initialization_receipt_path: Path | None = None,
) -> _VerifiedMaterializedDownstreamLineage:
    run_card_bytes = _require_materializer_artifact(
        run_card_path, label="materialization lineage run card"
    )
    card = _projection_json_object(run_card_bytes, source=run_card_path)
    if (
        card.get("schema_version") != "legalforecast.acquisition_run_card.v1"
        or card.get("stage") != "materialize-cohort-documents"
        or card.get("status") != "completed"
        or card.get("dry_run") is not False
        or card.get("execute") is not True
        or card.get("paid_activity_requested") is not False
        or card.get("paid_activity_executed") is not False
        or card.get("source_roots_mutated") is not False
        or card.get("zero_provider_activity_evidence") is not True
    ):
        raise CommandError("invalid completed materialization lineage run card")
    raw_inputs = card.get("input_paths")
    if not isinstance(raw_inputs, Sequence) or isinstance(raw_inputs, (str, bytes)):
        raise CommandError("materialization run card lacks exact input paths")
    input_paths = tuple(Path(str(path)) for path in cast(Sequence[object], raw_inputs))
    authority_mode = card.get("authority_mode")
    if "authority_mode" in card and not isinstance(authority_mode, str):
        raise CommandError("invalid materialization authority mode")
    if authority_mode == "free_only":
        if len(input_paths) != 11:
            raise CommandError("materialization run card input paths differ")
        if controlled_private_root is None:
            raise CommandError(
                "free-only materialization lineage requires a controlled private root"
            )
        if initialization_receipt_path is not None:
            raise CommandError(
                "free-only materialization rejects a ledger initialization receipt"
            )
        raw_outputs = card.get("output_paths")
        if not isinstance(raw_outputs, Sequence) or isinstance(
            raw_outputs, (str, bytes)
        ):
            raise CommandError("materialization run card lacks exact output paths")
        output_paths = tuple(
            Path(str(path)) for path in cast(Sequence[object], raw_outputs)
        )
        if len(output_paths) != 6:
            raise CommandError("materialization run card output paths differ")
        materialized_root = output_paths[0].parent
        (
            preparation_root,
            preparation_summary_path,
            preparation_config_path,
            snapshot_manifest_path,
            target_root,
            free_clearance_path,
            cohort_policy_path,
            approval_checkpoint_path,
            approval_run_card_path,
            fee_schedule_path,
            ledger_path,
        ) = input_paths
        replay_args = argparse.Namespace(
            output_root=materialized_root,
            preparation_root=preparation_root,
            preparation_summary=preparation_summary_path,
            preparation_config=preparation_config_path,
            snapshot_manifest=snapshot_manifest_path,
            target_cohort_root=target_root,
            free_disclosure_clearance=free_clearance_path,
            cohort_policy=cohort_policy_path,
            controlled_private_root=controlled_private_root,
            run_card_output=run_card_path,
            log_output=None,
        )
        publication = _prepare_free_only_cohort_documents(
            replay_args,
            FreeOnlyMaterializationInputs(
                checkpoint_path=approval_checkpoint_path,
                run_card_path=approval_run_card_path,
                fee_schedule_path=fee_schedule_path,
                canonical_ledger_path=ledger_path.resolve(),
            ),
        )
        expected_outputs = (
            manifest_path,
            clearance_path,
            publication.restriction_path,
            publication.derivations_path,
            publication.summary_path,
            document_root,
        )
        if tuple(path.resolve() for path in output_paths) != tuple(
            path.resolve() for path in expected_outputs
        ):
            raise CommandError(
                "materialization lineage outputs differ from parser inputs"
            )
        output_snapshots = {
            path: _read_singly_linked_regular_input(
                path, label="materialization lineage output"
            )
            for path in expected_outputs[:-1]
        }
        document_tree_snapshot = _materializer_tree_snapshot(document_root)
        document_commitments = {
            document.destination.relative_to(document_root).as_posix(): (
                "sha256:" + _required_str(document.manifest_record, "sha256")
            )
            for document in publication.materialization.documents
        }
        verified_document_commitments = {
            relative_path: _bytes_sha256(payload)
            for relative_path, payload in document_tree_snapshot.items()
        }
        if verified_document_commitments != document_commitments:
            raise CommandError("materialization document-tree commitment changed")
        summary_bytes = _projection_json_bytes(
            {
                **publication.materialization.summary,
                "authority_mode": "free_only",
                "target_case_count": publication.target_case_count,
                "source_commitments": publication.source_commitments,
                "output_commitments": {
                    "document-downloads-merged.jsonl": _bytes_sha256(
                        publication.manifest_bytes
                    ),
                    "disclosure-clearance.jsonl": _bytes_sha256(
                        publication.clearance_bytes
                    ),
                    "restriction-evidence.jsonl": _bytes_sha256(
                        publication.restriction_bytes
                    ),
                    "materialization-derivations.jsonl": _bytes_sha256(
                        publication.derivations_bytes
                    ),
                    "documents": document_commitments,
                },
                "next_stage": "plan-parse-documents",
            }
        )
        output_commitments: dict[str, object] = {
            "document_manifest": _file_commitment_from_bytes(
                manifest_path, publication.manifest_bytes
            ),
            "disclosure_clearance": _file_commitment_from_bytes(
                clearance_path, publication.clearance_bytes
            ),
            "restriction_evidence": _file_commitment_from_bytes(
                publication.restriction_path, publication.restriction_bytes
            ),
            "materialization_derivations": _file_commitment_from_bytes(
                publication.derivations_path, publication.derivations_bytes
            ),
            "materialization_summary": {
                "path": str(publication.summary_path.resolve()),
                "sha256": _bytes_sha256(summary_bytes),
            },
            "document_tree": document_commitments,
        }
        if publication.authority_recheck is not None:
            publication.authority_recheck()
        _verify_materializer_resume(
            run_card_path=run_card_path,
            input_paths=publication.input_paths,
            manifest_path=manifest_path,
            manifest_bytes=publication.manifest_bytes,
            clearance_path=clearance_path,
            clearance_bytes=publication.clearance_bytes,
            restriction_path=publication.restriction_path,
            restriction_bytes=publication.restriction_bytes,
            derivations_path=publication.derivations_path,
            derivations_bytes=publication.derivations_bytes,
            summary_path=publication.summary_path,
            summary_bytes=summary_bytes,
            document_root=document_root,
            materialization=publication.materialization,
            source_commitments=publication.source_commitments,
            output_commitments=output_commitments,
            dry_run=False,
            authority_mode="free_only",
        )
        selection_records = tuple(
            _read_records(target_root / "target-cohort-selection.jsonl")
        )
        if selection_path is not None and (
            selection_path.resolve()
            != (target_root / "target-cohort-selection.jsonl").resolve()
            or read_unique_regular_file(selection_path)
            != read_unique_regular_file(target_root / "target-cohort-selection.jsonl")
        ):
            raise CommandError(
                "downstream selection differs from materialized target cohort"
            )
        captured_paths = {
            run_card_path: run_card_bytes,
            **dict(publication.captured_source_snapshots),
            **output_snapshots,
            **{
                document_root / relative_path: payload
                for relative_path, payload in document_tree_snapshot.items()
            },
        }
        _require_snapshot_unchanged(
            captured_paths,
            label="materialization downstream lineage artifact",
        )
        captured = {
            os.path.abspath(path): payload for path, payload in captured_paths.items()
        }
        return _VerifiedMaterializedDownstreamLineage(
            paths=(
                run_card_path,
                publication.restriction_path,
                publication.derivations_path,
            ),
            artifact_bytes=captured,
            manifest_records=tuple(
                _projection_jsonl_records(
                    output_snapshots[manifest_path], source=manifest_path
                )
            ),
            clearance_records=tuple(
                _projection_jsonl_records(
                    output_snapshots[clearance_path], source=clearance_path
                )
            ),
            selection_records=selection_records,
            resolved_lineage_selection_records=selection_records,
            resolved_records=(),
            document_tree=document_tree_snapshot,
            fresh_ledger_namespace=ledger_path.resolve(),
            verified_successor_selection_card=(
                publication.verified_successor_selection_card
            ),
            authenticated_paths=_authenticated_path_aliases(input_paths),
        )
    if authority_mode is not None:
        raise CommandError("unsupported materialization authority mode")
    if len(input_paths) not in {12, 13, 14, 15}:
        raise CommandError("materialization run card input paths differ")
    (
        preparation_root,
        preparation_summary_path,
        preparation_config_path,
        snapshot_manifest_path,
        target_root,
        free_clearance_path,
        recovery_root,
        purchased_clearance_path,
        purchased_clearance_card_path,
        purchase_policy_path,
        cohort_policy_path,
        ledger_path,
        *optional_inputs,
    ) = input_paths
    purchase_result_path: Path | None = None
    purchase_run_card_path: Path | None = None
    if len(input_paths) in {14, 15}:
        purchase_result_path, purchase_run_card_path, *optional_inputs = optional_inputs
    resolved_path = optional_inputs[0] if optional_inputs else None
    raw_outputs = card.get("output_paths")
    if not isinstance(raw_outputs, Sequence) or isinstance(raw_outputs, (str, bytes)):
        raise CommandError("materialization run card lacks exact output paths")
    output_paths = tuple(
        Path(str(path)) for path in cast(Sequence[object], raw_outputs)
    )
    if len(output_paths) != 6:
        raise CommandError("materialization run card output paths differ")
    materialized_root = output_paths[0].parent
    restriction_path = materialized_root / "restriction-evidence.jsonl"
    derivations_path = materialized_root / "materialization-derivations.jsonl"
    summary_path = materialized_root / "cohort-document-materialization.json"
    expected_outputs = (
        manifest_path,
        clearance_path,
        restriction_path,
        derivations_path,
        summary_path,
        document_root,
    )
    if tuple(path.resolve() for path in output_paths) != tuple(
        path.resolve() for path in expected_outputs
    ):
        raise CommandError("materialization lineage outputs differ from parser inputs")
    direct_input_paths = (
        preparation_summary_path,
        preparation_config_path,
        snapshot_manifest_path,
        free_clearance_path,
        purchased_clearance_path,
        purchased_clearance_card_path,
        purchase_policy_path,
        cohort_policy_path,
        ledger_path,
        *(
            (purchase_result_path, purchase_run_card_path)
            if purchase_result_path is not None and purchase_run_card_path is not None
            else ()
        ),
        *((resolved_path,) if resolved_path is not None else ()),
        *((selection_path,) if selection_path is not None else ()),
    )
    direct_output_paths = (
        manifest_path,
        clearance_path,
        restriction_path,
        derivations_path,
        summary_path,
    )
    direct_snapshots = {
        path: _read_singly_linked_regular_input(
            path, label="materialization lineage artifact"
        )
        for path in (*direct_input_paths, *direct_output_paths)
    }
    captured_artifact_bytes: dict[str, bytes] = {
        os.path.abspath(run_card_path): run_card_bytes,
        **{
            os.path.abspath(path): payload for path, payload in direct_snapshots.items()
        },
    }
    try:
        verified_preparation = _verify_completed_preparation_for_frontier(
            preparation_root=preparation_root,
            preparation_summary_path=preparation_summary_path,
            preparation_config_path=preparation_config_path,
            snapshot_manifest_path=snapshot_manifest_path,
        )
        preparation_success_bytes = _read_singly_linked_regular_input(
            verified_preparation.success_run_card_path,
            label="materialization preparation success run card",
        )
        captured_artifact_bytes[
            os.path.abspath(verified_preparation.success_run_card_path)
        ] = preparation_success_bytes
        preverified_recovery: dict[str, object] | None = None
        consolidated_recovery_selection: Sequence[Mapping[str, Any]] | None = None
        consolidated_recovery_card = (
            recovery_root / "run-cards" / "consolidate-replacement-recovery.json"
        )
        if os.path.lexists(consolidated_recovery_card):
            (
                outer_projection,
                preliminary_selection_path,
                preliminary_selection,
            ) = _materializer_consolidated_target_inputs(
                target_root=target_root,
                free_clearance_path=free_clearance_path,
                preparation_summary_path=preparation_summary_path,
                preparation_config_path=preparation_config_path,
                snapshot_manifest_path=snapshot_manifest_path,
                expected_target_count=verified_preparation.target_case_count,
            )
            preverified_recovery = _verify_materializer_recovery(
                recovery_root=recovery_root,
                selection_path=preliminary_selection_path,
                selected_document_keys=_replacement_consolidation_selection_keys(
                    preliminary_selection
                ),
                purchase_policy_path=purchase_policy_path,
                cohort_policy_path=cohort_policy_path,
                ledger_path=ledger_path.resolve(),
            )
            raw_projection = preverified_recovery.get("target_projection")
            if not isinstance(raw_projection, Mapping):
                raise CommandError(
                    "consolidated recovery lacks authenticated target projection"
                )
            projection = _select_materializer_projection_after_recovery(
                outer_projection=outer_projection,
                recovery_projection=cast(Mapping[str, object], raw_projection),
                recovery_selection=preliminary_selection,
            )
            consolidated_recovery_selection = preliminary_selection
            if (
                len(
                    cast(
                        Sequence[Mapping[str, Any]],
                        projection["selection_records"],
                    )
                )
                != verified_preparation.target_case_count
                or free_clearance_path.resolve()
                != (target_root / "disclosure-clearance.jsonl").resolve()
            ):
                raise CommandError(
                    "consolidated recovery target projection differs from materializer"
                )
        else:
            projection = _verify_materializer_projection(
                target_root=target_root,
                free_clearance_path=free_clearance_path,
                preparation_summary_path=preparation_summary_path,
                preparation_config_path=preparation_config_path,
                snapshot_manifest_path=snapshot_manifest_path,
                expected_target_count=verified_preparation.target_case_count,
            )
        _merge_verified_artifact_bytes(
            captured_artifact_bytes,
            cast(Mapping[str, bytes], projection["verified_artifact_bytes"]),
            label="downstream materialization projection",
        )
        committed_selection_path = cast(Path, projection["selection_path"])
        if selection_path is not None and (
            selection_path.resolve() != committed_selection_path.resolve()
            or direct_snapshots[selection_path]
            != captured_artifact_bytes[os.path.abspath(committed_selection_path)]
        ):
            raise CommandError(
                "downstream selection differs from materialized target cohort"
            )
        purchase_policy = verify_case_dev_purchase_policy(
            _projection_json_object(
                direct_snapshots[purchase_policy_path], source=purchase_policy_path
            )
        )
        require_approved_case_dev_purchase_policy(
            purchase_policy, controlled_private_root=controlled_private_root
        )
        verify_case_dev_purchase_policy_cohort_binding(
            purchase_policy,
            _projection_json_object(
                direct_snapshots[cohort_policy_path], source=cohort_policy_path
            ),
        )
        snapshot = read_case_dev_purchase_snapshot(
            ledger_path.resolve(),
            policy=purchase_policy,
            controlled_private_root=controlled_private_root,
            initialization_receipt_path=initialization_receipt_path,
        )
        available_document_keys = cast(
            set[tuple[str, str]], projection["selected_document_keys"]
        )
        selected_document_keys = set(available_document_keys)
        docket_decision_descriptor: _MaterializerDocketDecisionAuthority | None = None
        if purchase_result_path is not None and purchase_run_card_path is not None:
            authenticated_selection_keys = (
                _materializer_complete_selected_document_keys(
                    projection,
                    consolidated_recovery=preverified_recovery is not None,
                )
            )
            with CaseDevPurchaseJournal(
                ledger_path.resolve(),
                policy=purchase_policy,
                read_only=True,
                controlled_private_root=controlled_private_root,
                initialization_receipt_path=initialization_receipt_path,
            ) as journal:
                docket_decision_descriptor = (
                    _verify_materializer_docket_decision_authority(
                        selection_payload=captured_artifact_bytes[
                            os.path.abspath(committed_selection_path)
                        ],
                        snapshot_manifest_path=snapshot_manifest_path,
                        purchase_result_path=purchase_result_path,
                        purchase_run_card_path=purchase_run_card_path,
                        purchase_journal=journal,
                        purchase_policy=purchase_policy,
                        ledger_path=ledger_path.resolve(),
                        controlled_private_root=controlled_private_root,
                        initialization_receipt_path=initialization_receipt_path,
                        selected_document_count=len(authenticated_selection_keys),
                    )
                )
                _merge_verified_artifact_bytes(
                    captured_artifact_bytes,
                    {
                        os.path.abspath(path): payload
                        for path, payload in (
                            docket_decision_descriptor.source_snapshots.items()
                        )
                    },
                    label="downstream materializer docket-decision authority",
                )
                omission_keys = verified_docket_decision_document_keys(
                    docket_decision_descriptor.authority,
                    purchase_journal=journal,
                )
            if not omission_keys <= authenticated_selection_keys:
                raise CommandError(
                    "audit-only docket decision omission is outside the selection"
                )
            selected_document_keys = authenticated_selection_keys - omission_keys
        recovery = (
            preverified_recovery
            if preverified_recovery is not None
            else _verify_materializer_recovery(
                recovery_root=recovery_root,
                selection_path=projection["selection_path"],
                selected_document_keys=selected_document_keys,
                purchase_policy_path=purchase_policy_path,
                cohort_policy_path=cohort_policy_path,
                ledger_path=ledger_path,
                purchase_operations=snapshot.operations,
                purchase_committed_amount_usd=snapshot.committed_amount_usd,
                purchase_state_sha256=snapshot.purchase_state_sha256,
            )
        )
        raw_recovery_bytes = recovery.get("verified_artifact_bytes")
        if isinstance(raw_recovery_bytes, Mapping):
            _merge_verified_artifact_bytes(
                captured_artifact_bytes,
                cast(Mapping[str, bytes], raw_recovery_bytes),
                label="downstream materialization recovery",
            )
        purchased_lineage = _verify_materializer_clearance_lineage(
            manifest_path=cast(Path, recovery["manifest_path"]),
            clearance_path=purchased_clearance_path,
            run_card_path=purchased_clearance_card_path,
        )
        consolidated_resolved_capability = recovery.get(
            "consolidated_resolved_capability"
        )
        if consolidated_resolved_capability is not None:
            if (
                purchased_lineage.get("lineage_kind")
                != "replacement_recovery_consolidation"
            ):
                raise CommandError(
                    "consolidated resolved authority differs from clearance lineage"
                )
            purchased_lineage["consolidated_resolved_capability"] = (
                consolidated_resolved_capability
            )
        raw_clearance_bytes = purchased_lineage.get("verified_artifact_bytes")
        if isinstance(raw_clearance_bytes, Mapping):
            _merge_verified_artifact_bytes(
                captured_artifact_bytes,
                cast(Mapping[str, bytes], raw_clearance_bytes),
                label="downstream materialization clearance",
            )
        _verify_materializer_recovery_clearance_binding(
            recovery=recovery,
            clearance_lineage=purchased_lineage,
        )
        selection_records = cast(
            Sequence[Mapping[str, Any]], projection["selection_records"]
        )
        resolved_lineage_selection_records = (
            consolidated_recovery_selection
            if consolidated_recovery_selection is not None
            else selection_records
        )
        purchased_manifest = cast(
            Sequence[Mapping[str, Any]], recovery["manifest_records"]
        )
        needs_resolved_lineage = _selection_requires_resolved_post_recovery(
            resolved_lineage_selection_records
        ) or any(
            record.get("recovery_origin") == "unknown_status_attempt"
            for record in purchased_manifest
        )
        if needs_resolved_lineage != (resolved_path is not None):
            raise CommandError(
                "materialization lineage resolved-document input coverage differs"
            )
        resolved_records = (
            _projection_jsonl_records(
                direct_snapshots[resolved_path], source=resolved_path
            )
            if resolved_path is not None
            else []
        )
        clearance_kwargs: dict[str, Any] = {}
        if needs_resolved_lineage:
            clearance_kwargs = _materializer_clearance_lineage_kwargs(
                clearance_path=purchased_clearance_path,
                run_card_path=purchased_clearance_card_path,
                lineage=purchased_lineage,
            )
            _require_resolved_post_recovery_dispatch(
                selection_records=resolved_lineage_selection_records,
                download_records=purchased_manifest,
                clearance_records=cast(
                    Sequence[Mapping[str, Any]], purchased_lineage["clearance_records"]
                ),
                resolved_records=resolved_records,
                **clearance_kwargs,
            )
            _require_resolved_operation_bindings_dispatch(
                clearance_kwargs=clearance_kwargs,
                purchase_operation_records=snapshot.operations,
                resolved_records=resolved_records,
                expected_purchase_policy_sha256=purchase_policy.policy_sha256,
            )
        _verify_materializer_purchase_operations(
            snapshot.operations,
            purchased_manifest=purchased_manifest,
        )
        free_sources = _materializer_successor_v2_free_sources(
            projection,
            preparation_root=preparation_root,
            consolidated_recovery=preverified_recovery is not None,
        )
        materialization = prepare_cohort_document_materialization(
            (
                *free_sources,
                DocumentSource(
                    phase="purchased",
                    document_root=cast(Path, recovery["document_root"]),
                    manifest=cast(
                        Sequence[Mapping[str, Any]], recovery["manifest_records"]
                    ),
                    clearance=cast(
                        Sequence[Mapping[str, Any]],
                        purchased_lineage["clearance_records"],
                    ),
                ),
            ),
            selected_document_keys=selected_document_keys,
            output_root=materialized_root,
            resolved_post_recovery_records=resolved_records,
        )
    except (
        CaseDevPurchaseLedgerError,
        CaseDevPurchasePolicyError,
        CohortDocumentMaterializationError,
        OSError,
        ResolvedPostRecoveryError,
        sqlite3.Error,
        UnicodeError,
        ValueError,
    ) as exc:
        raise CommandError(str(exc)) from exc
    expected_manifest = _projection_jsonl_bytes(materialization.manifest)
    expected_clearance = _projection_jsonl_bytes(materialization.clearance)
    if direct_snapshots[manifest_path] != expected_manifest:
        raise CommandError("materialized manifest does not reproduce")
    if direct_snapshots[clearance_path] != expected_clearance:
        raise CommandError("materialized clearance does not reproduce")
    free_keys = {
        _materializer_record_key(record)
        for record in cast(Sequence[Mapping[str, Any]], projection["free_manifest"])
    }
    expected_restrictions = tuple(
        sorted(
            (
                *(
                    record
                    for record in cast(
                        Sequence[Mapping[str, Any]], projection["restriction_records"]
                    )
                    if _materializer_record_key(record) in free_keys
                ),
                *cast(
                    Sequence[Mapping[str, Any]],
                    purchased_lineage["restriction_records"],
                ),
            ),
            key=lambda record: (
                *_materializer_record_key(record),
                _canonical_json_sha256(record),
            ),
        )
    )
    expected_derivations = _build_materializer_derivations(
        materialization=materialization,
        free_manifest=cast(Sequence[Mapping[str, Any]], projection["free_manifest"]),
        free_clearance=cast(Sequence[Mapping[str, Any]], projection["free_clearance"]),
        purchased_manifest=cast(
            Sequence[Mapping[str, Any]], recovery["manifest_records"]
        ),
        purchased_clearance=cast(
            Sequence[Mapping[str, Any]], purchased_lineage["clearance_records"]
        ),
        resolved_records=resolved_records,
    )
    expected_restriction_bytes = _projection_jsonl_bytes(expected_restrictions)
    expected_derivation_bytes = _projection_jsonl_bytes(expected_derivations)
    if direct_snapshots[restriction_path] != expected_restriction_bytes:
        raise CommandError("materialized restriction evidence does not reproduce")
    if direct_snapshots[derivations_path] != expected_derivation_bytes:
        raise CommandError("materialization derivations do not reproduce")

    def verified_commitment(path: Path) -> dict[str, str]:
        try:
            payload = captured_artifact_bytes[os.path.abspath(path)]
        except KeyError as exc:
            raise CommandError(
                f"materialization verified snapshot lacks source: {path}"
            ) from exc
        return _file_commitment_from_bytes(path, payload)

    expected_sources: dict[str, object] = {
        "preparation_summary": verified_commitment(preparation_summary_path),
        "preparation_config": verified_commitment(preparation_config_path),
        "preparation_success_run_card": verified_commitment(
            verified_preparation.success_run_card_path
        ),
        "snapshot_manifest": verified_commitment(snapshot_manifest_path),
        "target_projection": verified_commitment(
            cast(Path, projection["summary_path"])
        ),
        "target_projection_run_card": verified_commitment(
            cast(Path, projection["run_card_path"])
        ),
        "target_selection": verified_commitment(
            cast(Path, projection["selection_path"])
        ),
        "free_download_manifest": verified_commitment(
            cast(Path, projection["free_manifest_path"])
        ),
        "free_disclosure_clearance": verified_commitment(free_clearance_path),
        **_materializer_recovery_source_commitments(recovery),
        "purchased_disclosure_clearance": verified_commitment(purchased_clearance_path),
        "purchased_clearance_run_card": verified_commitment(
            purchased_clearance_card_path
        ),
        "free_restriction_evidence": verified_commitment(
            cast(Path, projection["restriction_path"])
        ),
        "purchased_restriction_evidence": verified_commitment(
            cast(Path, purchased_lineage["restriction_path"])
        ),
        "purchase_policy": verified_commitment(purchase_policy_path),
        "cohort_policy": verified_commitment(cohort_policy_path),
        "purchase_state_sha256": snapshot.purchase_state_sha256,
        **(
            {
                "terminal_purchase_result": verified_commitment(purchase_result_path),
                "terminal_purchase_run_card": verified_commitment(
                    purchase_run_card_path
                ),
                "terminal_purchase_budget_plan": verified_commitment(
                    docket_decision_descriptor.purchase_budget_plan_path
                ),
                "docket_decision_partition": dict(docket_decision_descriptor.partition),
            }
            if docket_decision_descriptor is not None
            and purchase_result_path is not None
            and purchase_run_card_path is not None
            else {}
        ),
        **(
            {"resolved_post_recovery_documents": verified_commitment(resolved_path)}
            if resolved_path is not None
            else {}
        ),
    }
    if card.get("source_commitments") != expected_sources:
        raise CommandError("materialization source commitments do not reproduce")
    expected_docket_partition = (
        dict(docket_decision_descriptor.partition)
        if docket_decision_descriptor is not None
        else None
    )
    if card.get("docket_decision_partition") != expected_docket_partition:
        raise CommandError(
            "materialization docket-decision partition does not reproduce"
        )
    document_commitments = {
        document.destination.relative_to(document_root).as_posix(): (
            "sha256:" + _required_str(document.manifest_record, "sha256")
        )
        for document in materialization.documents
    }
    document_tree_snapshot = _materializer_tree_snapshot(document_root)
    verified_document_commitments = {
        relative_path: _bytes_sha256(payload)
        for relative_path, payload in document_tree_snapshot.items()
    }
    if verified_document_commitments != document_commitments:
        raise CommandError("materialization document-tree commitment changed")
    expected_summary = {
        **materialization.summary,
        "target_case_count": verified_preparation.target_case_count,
        **(
            {"docket_decision_partition": dict(docket_decision_descriptor.partition)}
            if docket_decision_descriptor is not None
            else {}
        ),
        "source_commitments": expected_sources,
        "output_commitments": {
            "document-downloads-merged.jsonl": _bytes_sha256(expected_manifest),
            "disclosure-clearance.jsonl": _bytes_sha256(expected_clearance),
            "restriction-evidence.jsonl": _bytes_sha256(
                _projection_jsonl_bytes(expected_restrictions)
            ),
            "materialization-derivations.jsonl": _bytes_sha256(
                _projection_jsonl_bytes(expected_derivations)
            ),
            "documents": document_commitments,
        },
        "next_stage": "plan-parse-documents",
    }
    expected_summary_bytes = _projection_json_bytes(expected_summary)
    if direct_snapshots[summary_path] != expected_summary_bytes:
        raise CommandError("materialization summary does not reproduce")
    expected_output_commitments = {
        "document_manifest": _file_commitment_from_bytes(
            manifest_path, direct_snapshots[manifest_path]
        ),
        "disclosure_clearance": _file_commitment_from_bytes(
            clearance_path, direct_snapshots[clearance_path]
        ),
        "restriction_evidence": _file_commitment_from_bytes(
            restriction_path, direct_snapshots[restriction_path]
        ),
        "materialization_derivations": _file_commitment_from_bytes(
            derivations_path, direct_snapshots[derivations_path]
        ),
        "materialization_summary": {
            "path": str(summary_path.resolve()),
            "sha256": _bytes_sha256(expected_summary_bytes),
        },
        "document_tree": document_commitments,
    }
    if card.get("output_commitments") != expected_output_commitments:
        raise CommandError("materialization output commitments do not reproduce")
    _require_snapshot_unchanged(
        {
            run_card_path: run_card_bytes,
            **direct_snapshots,
            **{
                Path(path): payload for path, payload in captured_artifact_bytes.items()
            },
            **{
                document_root / relative_path: payload
                for relative_path, payload in document_tree_snapshot.items()
            },
        },
        label="materialization lineage artifact",
    )
    return _VerifiedMaterializedDownstreamLineage(
        paths=(
            run_card_path,
            restriction_path,
            derivations_path,
            *((resolved_path,) if resolved_path is not None else ()),
        ),
        artifact_bytes=dict(captured_artifact_bytes),
        manifest_records=tuple(
            _projection_jsonl_records(
                direct_snapshots[manifest_path], source=manifest_path
            )
        ),
        clearance_records=tuple(
            _projection_jsonl_records(
                direct_snapshots[clearance_path], source=clearance_path
            )
        ),
        selection_records=tuple(selection_records),
        resolved_lineage_selection_records=tuple(resolved_lineage_selection_records),
        resolved_records=tuple(resolved_records),
        document_tree=dict(document_tree_snapshot),
        recovered_public_capability=clearance_kwargs.get(
            "_verified_recovery_capability"
        ),
        consolidated_recovery_capability=clearance_kwargs.get(
            "_verified_consolidated_recovery_capability"
        ),
        docket_decision_authority=docket_decision_descriptor,
        verified_successor_selection_card=(
            _verified_successor_selection_card_from_projection(projection)
        ),
        authenticated_paths=_authenticated_path_aliases(input_paths),
    )


def _require_consistent_materialization_markers(
    manifest_records: Sequence[Mapping[str, Any]],
    clearance_records: Sequence[Mapping[str, Any]],
) -> bool:
    expected = "legalforecast.cohort_document_materialization.v1"
    records = (*manifest_records, *clearance_records)
    present = ["materialization_schema_version" in record for record in records]
    if not any(present):
        return False
    if not all(present):
        raise CommandError("materialization markers do not exactly cover artifacts")
    invalid = [
        _materializer_record_key(record)
        for record in records
        if record.get("materialization_schema_version") != expected
    ]
    if invalid:
        raise CommandError(f"unsupported materialization marker: {invalid[0]}")
    manifest_keys = {_materializer_record_key(record) for record in manifest_records}
    clearance_keys = {_materializer_record_key(record) for record in clearance_records}
    if manifest_keys != clearance_keys:
        raise CommandError("materialized manifest and clearance coverage differ")
    return True


def _verify_optional_finalize_materialization(
    *,
    selection_path: Path,
    clearance_path: Path,
    download_manifest_path: Path | None,
    materialization_card_path: Path | None,
    document_root: Path | None,
    verified_materialization: _VerifiedMaterializedDownstreamLineage | None,
) -> _VerifiedMaterializedDownstreamLineage | tuple[Path, ...]:
    options = (download_manifest_path, materialization_card_path, document_root)
    if any(path is not None for path in options) and not all(
        path is not None for path in options
    ):
        raise CommandError(
            "finalize materialization requires --download-manifest, "
            "--materialization-run-card, and --document-root together"
        )
    if all(path is not None for path in options):
        if verified_materialization is None:
            raise AssertionError("finalize materialization lineage was not verified")
        verified = verified_materialization
        _require_materialized_downstream_lineage_unchanged(
            verified,
            document_root=cast(Path, document_root),
        )
        if not _require_consistent_materialization_markers(
            verified.manifest_records, verified.clearance_records
        ):
            raise CommandError(
                "finalize materialization arguments require exact markers"
            )
        return verified
    clearance_bytes = _read_singly_linked_regular_input(
        clearance_path, label="finalize disclosure clearance"
    )
    clearance_records = _projection_jsonl_records(
        clearance_bytes, source=clearance_path
    )
    has_marker = any(
        "materialization_schema_version" in record for record in clearance_records
    )
    _require_snapshot_unchanged(
        {clearance_path: clearance_bytes}, label="finalize disclosure clearance"
    )
    if has_marker:
        raise CommandError(
            "materialized final corpus requires its manifest, run card, and root"
        )
    return ()


def _materializer_tree_commitments(root: Path) -> dict[str, str]:
    return {
        relative_path: _bytes_sha256(payload)
        for relative_path, payload in _materializer_tree_snapshot(root).items()
    }


def _materializer_tree_snapshot(root: Path) -> dict[str, bytes]:
    _reject_existing_parent_symlink(root, label="document tree")
    if root.is_symlink() or not root.is_dir():
        raise CommandError(f"document tree is missing or unsafe: {root}")
    snapshots: dict[str, bytes] = {}
    for path in sorted(root.rglob("*")):
        if path.is_symlink():
            raise CommandError(f"symlink in document tree: {path}")
        metadata = path.stat(follow_symlinks=False)
        if stat.S_ISDIR(metadata.st_mode):
            continue
        if not stat.S_ISREG(metadata.st_mode):
            raise CommandError(f"special node in document tree is forbidden: {path}")
        if metadata.st_nlink != 1:
            raise CommandError(f"hardlinked document-tree file is forbidden: {path}")
        snapshots[path.relative_to(root).as_posix()] = (
            _read_singly_linked_regular_input(path, label="document tree file")
        )
    return snapshots


def _materializer_file_commitment(path: Path) -> dict[str, str]:
    payload = _require_materializer_artifact(path, label="materializer source")
    canonical_path = Path(os.path.abspath(path))
    return {"path": str(canonical_path), "sha256": _bytes_sha256(payload)}


def _file_commitment_from_bytes(path: Path, payload: bytes) -> dict[str, str]:
    """Commit one already-authenticated immutable input snapshot."""

    return {"path": str(path.resolve()), "sha256": _bytes_sha256(payload)}


def _require_snapshot_unchanged(snapshots: Mapping[Path, bytes], *, label: str) -> None:
    """Fail closed when an immutable input changed after its first read."""

    for path, expected in snapshots.items():
        if _read_singly_linked_regular_input(path, label=label) != expected:
            raise CommandError(f"{label} changed during execution: {path}")


def _snapshot_regular_input_paths(
    paths: Sequence[Path],
    *,
    label: str,
    captured_artifact_bytes: Mapping[str, bytes] | None = None,
) -> dict[Path, bytes]:
    """Capture completion inputs once, reusing authenticated upstream bytes."""

    snapshots: dict[Path, bytes] = {}
    captured = captured_artifact_bytes or {}
    for path in paths:
        payload = captured.get(os.path.abspath(path))
        if payload is None:
            payload = _read_singly_linked_regular_input(path, label=label)
        snapshots[path] = payload
    return snapshots


def _merge_verified_artifact_bytes(
    target: dict[str, bytes],
    incoming: Mapping[str, bytes],
    *,
    label: str,
) -> None:
    """Merge authenticated snapshots without permitting unequal overlap."""

    for raw_path, payload in incoming.items():
        path = os.path.abspath(raw_path)
        existing = target.get(path)
        if existing is not None and existing != payload:
            raise CommandError(f"{label} snapshot collision: {path}")
        target[path] = payload


def _materializer_committed_path(
    commitments: Mapping[str, object],
    name: str,
    *,
    captured_artifact_bytes: Mapping[str, bytes] | None = None,
) -> Path:
    commitment = commitments.get(name)
    if not isinstance(commitment, Mapping):
        raise CommandError(f"clearance run card lacks {name} commitment")
    record = cast(Mapping[str, object], commitment)
    raw_path = record.get("path")
    sha256 = record.get("sha256")
    if not isinstance(raw_path, str) or not _valid_prefixed_sha256(sha256):
        raise CommandError(f"clearance run card has invalid {name} commitment")
    path = Path(raw_path)
    payload = _captured_or_stable_input(
        path,
        label=f"clearance {name}",
        captured_artifact_bytes=captured_artifact_bytes,
    )
    if _bytes_sha256(payload) != sha256:
        raise CommandError(f"clearance {name} commitment changed")
    return path


def _snapshot_committed_file(
    commitments: Mapping[str, object],
    name: str,
    *,
    label: str,
    captured_artifact_bytes: Mapping[str, bytes] | None = None,
) -> tuple[Path, bytes]:
    """Resolve and verify one committed file from a single byte snapshot."""

    commitment = commitments.get(name)
    if not isinstance(commitment, Mapping):
        raise CommandError(f"{label} lacks {name} commitment")
    record = cast(Mapping[str, object], commitment)
    raw_path = record.get("path")
    expected_sha256 = record.get("sha256")
    if not isinstance(raw_path, str) or not _valid_prefixed_sha256(expected_sha256):
        raise CommandError(f"{label} has invalid {name} commitment")
    path = Path(raw_path)
    payload = _captured_or_stable_input(
        path,
        label=f"{label} {name}",
        captured_artifact_bytes=captured_artifact_bytes,
    )
    if _bytes_sha256(payload) != expected_sha256:
        raise CommandError(f"{label} {name} commitment changed")
    return path, payload


def _require_materializer_artifact(path: Path, *, label: str) -> bytes:
    try:
        payload = require_materializer_artifact(path, label=label)
    except MaterializerArtifactValidationError as exc:
        message = str(exc)
    except CohortDocumentMaterializationError as exc:
        raise CommandError(str(exc)) from exc
    else:
        return payload
    raise CommandError(message)


def _require_unique_materializer_keys(
    records: Sequence[Mapping[str, Any]], *, label: str
) -> None:
    _materializer_record_index(records, label=label)


def _materializer_record_index(
    records: Sequence[Mapping[str, Any]], *, label: str
) -> dict[tuple[str, str], Mapping[str, Any]]:
    indexed: dict[tuple[str, str], Mapping[str, Any]] = {}
    for record in records:
        key = _materializer_record_key(record)
        if key in indexed:
            raise CommandError(f"duplicate {label} identity: {key[0]}/{key[1]}")
        indexed[key] = record
    return indexed


def _recovered_public_routing_lineage_matches(
    routing_records: Sequence[Mapping[str, Any]],
    authenticated_records: Sequence[Mapping[str, Any]],
    *,
    routing_schema_version: str,
) -> bool:
    """Compare frozen lineage while preserving its closed legacy shape.

    Direct-queue authority was added to both v2 and v3 routing rows without a
    schema-version bump.  It is safe to tolerate only that missing additive
    field because ``authenticated_records`` rebuilds the authority from the
    independently verified purchase journal; every frozen field remains exact.
    """

    routing = _materializer_record_index(
        routing_records, label="recovered-public routing lineage"
    )
    authenticated = _materializer_record_index(
        authenticated_records, label="authenticated recovered-public lineage"
    )
    if set(routing) != set(authenticated):
        return False
    for key, frozen in routing.items():
        expected = authenticated[key]
        if (
            routing_schema_version
            in {
                "legalforecast.disclosure_provenance_routing_plan.v2",
                "legalforecast.disclosure_provenance_routing_plan.v3",
            }
            and "direct_queue_delivery_authority" not in frozen
        ):
            expected = {
                field: value
                for field, value in expected.items()
                if field != "direct_queue_delivery_authority"
            }
        if frozen != expected:
            return False
    return True


def _recovered_public_routing_plan_matches(
    frozen_plan: Mapping[str, Any],
    replayed_plan: Mapping[str, Any],
) -> bool:
    """Compare a routing plan across the v2/v3 additive-authority change."""

    if frozen_plan == replayed_plan:
        return True
    if frozen_plan.get("schema_version") not in {
        "legalforecast.disclosure_provenance_routing_plan.v2",
        "legalforecast.disclosure_provenance_routing_plan.v3",
    }:
        return False
    frozen_documents = frozen_plan.get("documents")
    replayed_documents = replayed_plan.get("documents")
    if not isinstance(frozen_documents, list) or not isinstance(
        replayed_documents, list
    ):
        return False
    frozen_document_rows = cast(list[object], frozen_documents)
    replayed_document_rows = cast(list[object], replayed_documents)
    if len(frozen_document_rows) != len(replayed_document_rows):
        return False
    projected_documents: list[object] = []
    for frozen_document, replayed_document in zip(
        frozen_document_rows, replayed_document_rows, strict=True
    ):
        if not isinstance(frozen_document, Mapping) or not isinstance(
            replayed_document, Mapping
        ):
            return False
        frozen_document_row = cast(Mapping[str, Any], frozen_document)
        replayed_document_row = cast(Mapping[str, Any], replayed_document)
        frozen_lineage = frozen_document_row.get("recovered_public_lineage")
        replayed_lineage = replayed_document_row.get("recovered_public_lineage")
        projected_document = dict(replayed_document_row)
        if (
            isinstance(frozen_lineage, Mapping)
            and isinstance(replayed_lineage, Mapping)
            and "direct_queue_delivery_authority" not in frozen_lineage
        ):
            projected_lineage = dict(cast(Mapping[str, Any], replayed_lineage))
            projected_lineage.pop("direct_queue_delivery_authority", None)
            projected_document["recovered_public_lineage"] = projected_lineage
        projected_documents.append(projected_document)
    projected_plan = dict(replayed_plan)
    projected_plan["documents"] = projected_documents
    if "document_set_sha256" in projected_plan:
        projected_plan["document_set_sha256"] = hashlib.sha256(
            canonical_json_bytes(projected_documents)
        ).hexdigest()
    return frozen_plan == projected_plan


def _materializer_record_key(record: Mapping[str, Any]) -> tuple[str, str]:
    return (
        _required_str(record, "candidate_id"),
        _required_str(record, "source_document_id"),
    )


def _validate_materializer_writable_paths(
    *,
    output_root: Path,
    writable_paths: Sequence[Path],
    document_root: Path,
    input_paths: Sequence[Path],
) -> None:
    try:
        validate_materializer_writable_paths(
            output_root=output_root,
            writable_paths=writable_paths,
            document_root=document_root,
            input_paths=input_paths,
        )
    except CohortDocumentMaterializationError as exc:
        raise CommandError(str(exc)) from exc


def _reject_unexpected_materializer_outputs(
    output_root: Path, *, expected_files: set[Path]
) -> None:
    if not output_root.exists():
        return
    if output_root.is_symlink() or not output_root.is_dir():
        raise CommandError("materializer output root must be a non-symlink directory")
    try:
        require_non_symlink_components(output_root)
    except CohortDocumentMaterializationError as exc:
        raise CommandError(str(exc)) from exc
    root = output_root.absolute()
    normalized_expected = {path.absolute() for path in expected_files}
    allowed_directories = {root}
    for expected in normalized_expected:
        allowed_directories.update(
            parent for parent in expected.parents if parent.is_relative_to(root)
        )
    for path in output_root.rglob("*"):
        metadata = path.lstat()
        absolute = path.absolute()
        if stat.S_ISLNK(metadata.st_mode):
            raise CommandError(f"symlink in materializer output root: {path}")
        if stat.S_ISDIR(metadata.st_mode):
            if absolute not in allowed_directories:
                raise CommandError(
                    f"unexpected directory in materializer output root: {path}"
                )
            continue
        if not stat.S_ISREG(metadata.st_mode):
            raise CommandError(
                f"special file in materializer output root is forbidden: {path}"
            )
        if metadata.st_nlink != 1:
            raise CommandError(f"hardlinked materializer output is forbidden: {path}")
    unexpected = [
        path
        for path in output_root.rglob("*")
        if stat.S_ISREG(path.lstat().st_mode)
        and path.absolute() not in normalized_expected
    ]
    if unexpected:
        raise CommandError(
            "materializer output root contains unexpected files: "
            + ", ".join(str(path) for path in unexpected[:5])
        )


def _materializer_operation_download_urls(
    operation: Mapping[str, Any],
    *,
    key: tuple[str, str],
) -> set[str]:
    found: set[str] = set()
    for label in ("response", "reconciliation"):
        raw = operation.get(label)
        if raw is None:
            continue
        if not isinstance(raw, Mapping):
            raise CommandError(f"purchase ledger {label} is not an object: {key}")
        typed_raw = cast(Mapping[str, object], raw)
        values = {
            value.strip()
            for field in ("downloadUrl", "download_url", "url")
            if isinstance((value := typed_raw.get(field)), str) and value.strip()
        }
        if len(values) > 1:
            raise CommandError(
                f"purchase ledger {label} has conflicting download URLs: {key}"
            )
        found.update(values)
    return found


def _cmd_acquisition_assemble_cycle(args: argparse.Namespace) -> int:
    output_root = _acquisition_output_root(args)
    batch_roots = tuple(cast(Sequence[Path], args.batch_root))
    dry_run = _acquisition_dry_run(args)
    assembly = assemble_cycle_acquisition(
        batch_roots,
        expected_cycle_hash=cast(str, args.expected_cycle_hash),
        output_root=output_root,
        copy_documents=not dry_run,
    )
    output_paths = _write_cycle_assembly(
        output_root,
        assembly=assembly,
        dry_run=dry_run,
    )
    _write_acquisition_completion(
        args,
        stage="assemble-cycle-acquisition",
        input_paths=batch_roots,
        output_paths=output_paths,
        record_count=len(assembly.screened_cases),
        dry_run=dry_run,
        paid_activity_requested=False,
        paid_activity_executed=False,
        extra={"record_counts": assembly.summary["record_counts"]},
    )
    return 0


def _cmd_acquisition_bind_component(args: argparse.Namespace) -> int:
    component_root = _acquisition_output_root(args)
    snapshot = cast(Path, args.snapshot)
    expected_cycle_hash = cast(str, args.expected_cycle_hash)
    component_ordinal = cast(int, args.component_ordinal)
    predecessor_path = cast(Path | None, args.predecessor_provenance)
    try:
        snapshot_manifest = verify_snapshot(
            snapshot,
            expected_cycle_hash=expected_cycle_hash,
            require_complete=True,
            require_saturated=True,
        )
    except SnapshotVerificationError as exc:
        raise CommandError(str(exc)) from exc
    if component_ordinal == 1:
        if predecessor_path is not None:
            raise CommandError(
                "--predecessor-provenance is forbidden for component ordinal 1"
            )
        predecessor_sha256 = hashlib.sha256(
            (snapshot / "manifest.json").read_bytes()
        ).hexdigest()
        input_paths = (snapshot, component_root)
    elif component_ordinal > 1:
        if predecessor_path is None:
            raise CommandError(
                "--predecessor-provenance is required after component ordinal 1"
            )
        predecessor_sha256 = hashlib.sha256(predecessor_path.read_bytes()).hexdigest()
        input_paths = (snapshot, predecessor_path, component_root)
    else:
        raise CommandError("--component-ordinal must be positive")
    output_path = component_root / COMPONENT_PROVENANCE_FILENAME
    dry_run = _acquisition_dry_run(args)
    if not dry_run:
        write_component_provenance(
            component_root,
            source_snapshot_manifest=snapshot / "manifest.json",
            component_ordinal=component_ordinal,
            predecessor_sha256=predecessor_sha256,
            component_stage=cast(str, args.component_stage),
        )
    _write_acquisition_completion(
        args,
        stage="bind-acquisition-component",
        input_paths=input_paths,
        output_paths=(output_path,),
        record_count=1,
        dry_run=dry_run,
        paid_activity_requested=False,
        paid_activity_executed=False,
        extra={
            "cycle_hash": snapshot_manifest["cycle_hash"],
            "batch_digest": snapshot_manifest["batch_digest"],
            "component_stage": cast(str, args.component_stage),
            "component_ordinal": component_ordinal,
            "predecessor_sha256": predecessor_sha256,
        },
    )
    return 0


def _write_cycle_assembly(
    output_root: Path, *, assembly: CycleAssembly, dry_run: bool
) -> tuple[Path, ...]:
    paths = (
        output_root / "screened-cases.jsonl",
        output_root / "discovery-exclusions.jsonl",
        output_root / "public-packet-selection.jsonl",
        output_root / "public-packet-paid-gaps.jsonl",
        output_root / "case-relevance.jsonl",
        output_root / "core-filter-results.jsonl",
        output_root / "document-downloads-merged.jsonl",
        output_root / "cycle-acquisition-summary.json",
    )
    if dry_run:
        return paths
    for path, records in zip(
        paths[:-1],
        (
            assembly.screened_cases,
            assembly.discovery_exclusions,
            assembly.selections,
            assembly.paid_gaps,
            assembly.case_relevance,
            assembly.core_filter_results,
            assembly.document_manifest,
        ),
        strict=True,
    ):
        _write_jsonl(path, records)
    _write_json(paths[-1], assembly.summary)
    return paths


_ACQUISITION_MERGE_JSONL_FILES = (
    "free-document-requests.jsonl",
    "free-document-downloads.jsonl",
    "parse-document-requests.jsonl",
    "mistral-markdown-conversions.jsonl",
    "document-manifest.jsonl",
    "candidate-manifest.jsonl",
    "extracted_texts.jsonl",
    "packet-build-input.jsonl",
    "packets.jsonl",
    "case-packets.jsonl",
    "packet-audit.jsonl",
    "llm-unitization-audit.jsonl",
    "unitization-review-queue.jsonl",
    "unitization-review-adjudications.jsonl",
    "llm-label-audit.jsonl",
    "lawyer-review-queue.jsonl",
    "lawyer-review-resume-audit.jsonl",
)


def _cmd_acquisition_merge_artifacts(args: argparse.Namespace) -> int:
    output_root = _acquisition_output_root(args)
    source_roots = tuple(cast(Sequence[Path], args.source_root))
    labels_paths = _explicit_or_default_merge_paths(
        cast(Sequence[Path] | None, args.labels),
        source_roots=source_roots,
        filenames=("labels-packet-buildable.jsonl", "labels.jsonl"),
    )
    unit_paths = _explicit_or_default_merge_paths(
        cast(Sequence[Path] | None, args.prediction_units),
        source_roots=source_roots,
        filenames=(
            "prediction-units-packet-buildable-labeled.jsonl",
            "prediction-units.jsonl",
        ),
    )
    dry_run = _acquisition_dry_run(args)

    _validate_merge_sources(source_roots)
    selection_paths = _explicit_or_default_merge_paths(
        cast(Sequence[Path] | None, args.selection),
        source_roots=source_roots,
        filenames=(
            "public-packet-selection-packet-buildable-labeled.jsonl",
            "public-packet-selection.jsonl",
        ),
    )
    jsonl_outputs: list[Path] = []
    record_counts: dict[str, int] = {}
    packet_count = 0
    for filename in _ACQUISITION_MERGE_JSONL_FILES:
        records = _merge_records_from_roots(source_roots, filename=filename)
        if filename in {"packets.jsonl", "case-packets.jsonl"}:
            packet_count = len(records)
        if not records:
            continue
        _validate_acquisition_merge_records(filename, records)
        record_counts[filename] = len(records)
        output_path = output_root / filename
        jsonl_outputs.append(output_path)
        if not dry_run:
            _write_jsonl(output_path, records)

    labels = _merge_records_from_paths(labels_paths)
    _validate_acquisition_merge_records("labels.jsonl", labels)
    units = _merge_records_from_paths(unit_paths)
    _validate_acquisition_merge_records("prediction-units.jsonl", units)
    selections = _merge_records_from_paths(selection_paths)
    _validate_acquisition_merge_records("public-packet-selection.jsonl", selections)
    record_counts["labels.jsonl"] = len(labels)
    record_counts["prediction-units.jsonl"] = len(units)
    record_counts["public-packet-selection.jsonl"] = len(selections)
    if not dry_run:
        _write_jsonl(output_root / "labels.jsonl", labels)
        _write_jsonl(output_root / "prediction-units.jsonl", units)
        _write_jsonl(output_root / "public-packet-selection.jsonl", selections)
        for directory_name in ("documents", "markdown"):
            _copy_merge_directory(source_roots, output_root, directory_name)

    summary_path = output_root / "merge-artifacts-summary.json"
    summary = {
        "dry_run": dry_run,
        "source_roots": [str(root) for root in source_roots],
        "labels": [str(path) for path in labels_paths],
        "prediction_units": [str(path) for path in unit_paths],
        "selection": [str(path) for path in selection_paths],
        "record_counts": record_counts,
    }
    _write_json(summary_path, summary)

    _write_acquisition_completion(
        args,
        stage="merge-artifacts",
        input_paths=(*source_roots, *labels_paths, *unit_paths, *selection_paths),
        output_paths=(
            *jsonl_outputs,
            output_root / "labels.jsonl",
            output_root / "prediction-units.jsonl",
            output_root / "public-packet-selection.jsonl",
            output_root / "documents",
            output_root / "markdown",
            summary_path,
        ),
        record_count=packet_count,
        dry_run=dry_run,
        paid_activity_requested=False,
        paid_activity_executed=False,
        extra={"record_counts": record_counts},
    )
    return 0


def _validate_merge_sources(source_roots: Sequence[Path]) -> None:
    if not source_roots:
        raise CommandError("at least one --source-root is required")
    seen: set[Path] = set()
    for source_root in source_roots:
        if not source_root.is_dir():
            raise CommandError(f"merge source root is not a directory: {source_root}")
        resolved = source_root.resolve()
        if resolved in seen:
            raise CommandError(f"duplicate merge source root: {source_root}")
        seen.add(resolved)


def _explicit_or_default_merge_paths(
    explicit_paths: Sequence[Path] | None,
    *,
    source_roots: Sequence[Path],
    filenames: Sequence[str],
) -> tuple[Path, ...]:
    if explicit_paths:
        paths = tuple(explicit_paths)
    else:
        paths = tuple(
            _default_merge_path(source_root, filenames=filenames)
            for source_root in source_roots
        )
    for path in paths:
        if not path.is_file():
            raise CommandError(f"merge input does not exist: {path}")
    return paths


def _default_merge_path(source_root: Path, *, filenames: Sequence[str]) -> Path:
    for filename in filenames:
        path = source_root / filename
        if path.is_file():
            return path
    candidates = ", ".join(filenames)
    raise CommandError(f"merge source {source_root} has none of: {candidates}")


def _merge_records_from_roots(
    source_roots: Sequence[Path],
    *,
    filename: str,
) -> list[JsonRecord]:
    records: list[JsonRecord] = []
    for source_root in source_roots:
        path = source_root / filename
        if path.is_file():
            records.extend(_read_records(path))
    return records


def _merge_records_from_paths(paths: Sequence[Path]) -> list[JsonRecord]:
    records: list[JsonRecord] = []
    for path in paths:
        records.extend(_read_records(path))
    if not records:
        raise CommandError("merge inputs produced no records")
    return records


def _copy_merge_directory(
    source_roots: Sequence[Path],
    output_root: Path,
    directory_name: str,
) -> None:
    for source_root in source_roots:
        source_dir = source_root / directory_name
        if not source_dir.is_dir():
            continue
        shutil.copytree(source_dir, output_root / directory_name, dirs_exist_ok=True)


def _validate_acquisition_merge_records(
    filename: str,
    records: Sequence[Mapping[str, Any]],
) -> None:
    if not records:
        raise CommandError(f"{filename} must contain at least one record")
    if filename in {"packets.jsonl", "case-packets.jsonl"}:
        _require_unique_merge_keys(
            filename,
            (
                (
                    _required_str(record, "case_id"),
                    _optional_str(record, "ablation")
                    or PacketAblation.FULL_PACKET.value,
                )
                for record in records
            ),
        )
    if filename in {
        "candidate-manifest.jsonl",
        "public-packet-selection.jsonl",
        "packet-build-input.jsonl",
        "prediction-units.jsonl",
    }:
        _require_unique_merge_keys(
            filename,
            (_required_str(record, "case_id") for record in records),
        )
    if filename in {"document-manifest.jsonl", "extracted_texts.jsonl"}:
        _require_unique_merge_keys(
            filename,
            (_required_str(record, "source_document_id") for record in records),
        )
    if filename == "mistral-markdown-conversions.jsonl":
        _require_unique_merge_keys(
            filename,
            (
                (
                    _optional_str(record, "candidate_id")
                    or _optional_str(record, "case_id")
                    or "unknown",
                    _required_str(record, "source_document_id"),
                )
                for record in records
            ),
        )
    if filename == "labels.jsonl":
        _require_unique_merge_keys(
            filename,
            (_required_str(record, "unit_id") for record in records),
        )
    if filename in {"prediction-units.jsonl", "packets.jsonl", "case-packets.jsonl"}:
        _require_unique_merge_keys(
            f"{filename} nested prediction units",
            (
                _required_str(unit, "unit_id")
                for record in records
                for unit in _merge_prediction_unit_records(record)
            ),
        )


def _merge_prediction_unit_records(
    record: Mapping[str, Any],
) -> tuple[Mapping[str, Any], ...]:
    units = record.get("prediction_units")
    if units is None:
        return ()
    if not isinstance(units, list):
        raise CommandError("prediction_units must be a list")
    merged: list[Mapping[str, Any]] = []
    for unit in cast(list[object], units):
        if not isinstance(unit, Mapping):
            raise CommandError("prediction_units items must be objects")
        merged.append(cast(Mapping[str, Any], unit))
    return tuple(merged)


def _require_unique_merge_keys(
    filename: str,
    keys: Iterable[object],
) -> None:
    seen: set[object] = set()
    duplicates: set[object] = set()
    for key in keys:
        if key in seen:
            duplicates.add(key)
        seen.add(key)
    if duplicates:
        sample = ", ".join(str(key) for key in sorted(duplicates, key=str)[:5])
        raise CommandError(f"{filename} has duplicate merge key(s): {sample}")


def _cmd_acquisition_download_free(args: argparse.Namespace) -> int:
    output_root = _acquisition_output_root(args)
    requests_path = cast(Path, args.requests)
    manifest_path = _acquisition_path(
        args,
        "manifest_output",
        output_root / "free-document-downloads.jsonl",
    )
    document_root = _acquisition_path(
        args,
        "document_output_root",
        output_root / "documents" / "free",
    )
    request_records = _read_records(requests_path)
    requests = tuple(
        _free_document_download_request(record) for record in request_records
    )
    dry_run = _acquisition_dry_run(args)
    if dry_run:
        _write_jsonl(
            manifest_path,
            [
                {
                    "stage": "download-free",
                    "dry_run": True,
                    "request_count": len(requests),
                    "document_output_root": str(document_root),
                }
            ],
        )
    else:
        try:
            manifest_already_completed = (
                cast(bool, args.resume)
                and (manifest_path.exists() or manifest_path.is_symlink())
                and not is_free_document_dry_run_manifest(
                    manifest_path,
                    request_count=len(requests),
                    document_output_root=document_root,
                )
            )
            if manifest_already_completed:
                verify_completed_free_document_manifest(
                    requests,
                    output_root=document_root,
                    manifest_path=manifest_path,
                )
            else:
                fixture_path = cast(Path | None, args.fixture_documents)
                live_public_download = cast(bool, args.live_public_download)
                source = _free_document_source(
                    fixture_path=fixture_path,
                    live_public_download=live_public_download,
                )
                records = download_free_docket_documents(
                    requests,
                    output_root=document_root,
                    source=source,
                    allow_existing=cast(bool, args.resume),
                )
                _write_jsonl(
                    manifest_path,
                    [record.to_record() for record in records],
                )
        except (
            CommandError,
            FreeDocumentDownloadError,
            OSError,
            UnicodeError,
            ValueError,
        ) as exc:
            _write_acquisition_failure(
                args,
                stage="download-free",
                input_paths=(requests_path,),
                output_paths=(manifest_path, document_root),
                reason=str(exc),
                paid_activity_requested=False,
            )
            if isinstance(exc, CommandError):
                raise
            raise CommandError(str(exc)) from exc
    _write_acquisition_completion(
        args,
        stage="download-free",
        input_paths=(requests_path,),
        output_paths=(manifest_path, document_root),
        record_count=len(requests),
        dry_run=dry_run,
        paid_activity_requested=False,
        paid_activity_executed=False,
    )
    return 0


def _cmd_acquisition_purchase_missing(args: argparse.Namespace) -> int:
    purchase_policy = _preflight_approved_purchase_runtime(args)
    if purchase_policy is None:
        raise CommandError("purchase-missing requires --purchase-policy")
    live_purchase = cast(bool, args.live_purchase)
    if live_purchase and purchase_policy.has_verified_approval:
        raise CommandError(
            "legacy Case.dev purchase cannot authenticate the approved selection; "
            "use purchase-missing-recap-fetch"
        )
    output_root = _acquisition_output_root(args)
    plan_path = cast(Path, args.budget_plan)
    output_path = _acquisition_path(
        args,
        "purchase_output",
        output_root / "case-dev-pacer-purchases.json",
    )
    plan_bytes = read_unique_regular_file(plan_path)
    plan_artifact = _projection_json_object(plan_bytes, source=plan_path)
    plan = _missing_core_budget_plan(plan_artifact)
    policy_path = cast(Path, args.purchase_policy)
    cohort_policy_path = cast(Path, args.cohort_policy)
    ledger_path = cast(Path, args.purchase_ledger).resolve()
    try:
        verify_case_dev_purchase_policy_cohort_binding(
            purchase_policy,
            _read_json_object(cohort_policy_path),
        )
    except (CaseDevPurchasePolicyError, OSError, UnicodeError, ValueError) as exc:
        raise CommandError(str(exc)) from exc
    if ledger_path != purchase_policy.canonical_ledger_path:
        raise CommandError(
            "--purchase-ledger conflicts with the canonical policy locator"
        )
    dry_run = _acquisition_dry_run(args)
    acknowledge_fees = cast(bool, args.acknowledge_pacer_fees)
    capability = CaseDevPacerCapability(cast(str, args.capability))
    if live_purchase and cast(Path | None, args.case_dev_fixture) is None:
        raise CommandError(
            "legacy Case.dev live document purchase is disabled; use "
            "purchase-missing-recap-fetch"
        )
    if not dry_run and plan.dry_run:
        _write_acquisition_failure(
            args,
            stage="purchase-missing",
            input_paths=(plan_path,),
            output_paths=(output_path,),
            reason="budget_plan_is_dry_run",
            paid_activity_requested=live_purchase,
        )
        raise CommandError(
            "purchase-missing requires a non-dry-run budget plan from "
            "acquisition plan --execute"
        )
    if not dry_run and (not live_purchase or not acknowledge_fees):
        _write_acquisition_failure(
            args,
            stage="purchase-missing",
            input_paths=(plan_path,),
            output_paths=(output_path,),
            reason="live_purchase_and_fee_acknowledgment_required",
            paid_activity_requested=live_purchase,
        )
        raise CommandError(
            "purchase-missing requires --execute, --live-purchase, and "
            "--acknowledge-pacer-fees before any paid request"
        )

    execution_plan = _dry_run_missing_core_budget_plan(plan) if dry_run else plan
    client = (
        _dry_run_case_dev_client()
        if dry_run
        else _case_dev_client(
            command="acquisition purchase-missing",
            fixture_path=cast(Path | None, args.case_dev_fixture),
            live=live_purchase,
        )
    )
    try:
        if dry_run:
            result = CaseDevPacerPurchaseClient(
                client,
                capability=capability,
            ).execute_purchase_plan(
                execution_plan,
                live=False,
                acknowledge_pacer_fees=acknowledge_fees,
            )
        else:
            with CaseDevPurchaseJournal(
                ledger_path,
                policy=purchase_policy,
            ) as journal:
                result = CaseDevPacerPurchaseClient(
                    client,
                    capability=capability,
                    journal=journal,
                ).execute_purchase_plan(
                    execution_plan,
                    live=live_purchase,
                    acknowledge_pacer_fees=acknowledge_fees,
                )
    except (CaseDevPurchaseLedgerError, CaseDevPurchasePolicyError) as exc:
        _write_acquisition_failure(
            args,
            stage="purchase-missing",
            input_paths=(plan_path, policy_path),
            output_paths=(output_path, ledger_path),
            reason=str(exc),
            paid_activity_requested=live_purchase,
            paid_activity_executed=client.request_count > 0,
        )
        raise CommandError(str(exc)) from exc
    _write_json(output_path, result.to_record())
    paid_activity_executed = client.request_count > 0
    _write_acquisition_completion(
        args,
        stage="purchase-missing",
        input_paths=(plan_path, policy_path),
        output_paths=(output_path,) if dry_run else (output_path, ledger_path),
        record_count=result.intended_purchase_count,
        dry_run=dry_run,
        paid_activity_requested=live_purchase,
        paid_activity_executed=paid_activity_executed,
        extra={
            "executed_purchase_count": result.executed_purchase_count,
            "projected_cost_usd": result.projected_cost_usd,
        },
    )
    if not dry_run and result.executed_purchase_count != result.intended_purchase_count:
        return 2
    return 0


def _cmd_acquisition_purchase_missing_recap_fetch(args: argparse.Namespace) -> int:
    if not _acquisition_dry_run(args):
        _preflight_current_purchase_snapshot(args)
    _preflight_approved_purchase_input_bytes(args)
    output_root = cast(Path, args.output_root)
    plan_path = cast(Path, args.budget_plan)
    selection_path = cast(Path, args.selection)
    policy_path = cast(Path, args.purchase_policy)
    cohort_policy_path = cast(Path, args.cohort_policy)
    ledger_path = cast(Path, args.purchase_ledger).resolve()
    output_path = _acquisition_path(
        args,
        "purchase_output",
        output_root / "courtlistener-recap-fetch-purchases.json",
    )
    dry_run = _acquisition_dry_run(args)
    live_purchase = cast(bool, args.live_purchase)
    acknowledge_fees = cast(bool, args.acknowledge_pacer_fees)
    courtlistener_fixture = cast(Path | None, args.courtlistener_fixture)
    broker_fixture = cast(Path | None, args.purchase_broker_fixture)
    attempt_policy_path = cast(Path | None, args.attempt_policy)
    broker_policy_path = cast(Path | None, args.broker_policy)
    direct_courtlistener_purchase = cast(
        bool, getattr(args, "direct_courtlistener_purchase", False)
    )
    replacement_authority_path = cast(Path | None, args.replacement_purchase_authority)
    replacement_private_root = cast(
        Path | None, args.replacement_controlled_private_root
    )
    controlled_private_root = cast(Path | None, args.controlled_private_root)
    initialization_receipt = cast(
        Path | None, args.purchase_ledger_initialization_receipt
    )
    if direct_courtlistener_purchase and not live_purchase:
        raise CommandError("--direct-courtlistener-purchase requires --live-purchase")
    if direct_courtlistener_purchase and broker_policy_path is not None:
        raise CommandError(
            "--direct-courtlistener-purchase cannot be combined with --broker-policy"
        )
    input_paths = (
        plan_path,
        selection_path,
        policy_path,
        cohort_policy_path,
        *((attempt_policy_path,) if attempt_policy_path is not None else ()),
        *((broker_policy_path,) if broker_policy_path is not None else ()),
        *(
            (replacement_authority_path,)
            if replacement_authority_path is not None
            else ()
        ),
    )
    client: CourtListenerRecapFetchClient | None = None
    request_budget: CourtListenerRequestBudget | None = None
    output_initialized = False
    try:
        budget_plan_bytes = read_unique_regular_file(plan_path)
        selection_bytes = read_unique_regular_file(selection_path)
        budget_plan_artifact = _projection_json_object(
            budget_plan_bytes, source=plan_path
        )
        plan = _missing_core_budget_plan(budget_plan_artifact)
        purchase_policy_artifact = _read_json_object(policy_path)
        cohort_policy_artifact = _read_json_object(cohort_policy_path)
        replacement_authority_artifact = (
            _read_json_object(replacement_authority_path)
            if replacement_authority_path is not None
            else None
        )
        selection_records = _projection_jsonl_records(
            selection_bytes, source=selection_path
        )
        purchase_policy = verify_case_dev_purchase_policy(purchase_policy_artifact)
        require_approved_case_dev_purchase_policy(
            purchase_policy, controlled_private_root=controlled_private_root
        )
        if replacement_authority_path is None:
            if replacement_private_root is not None:
                raise CommandError(
                    "replacement private root requires replacement purchase authority"
                )
            verify_approved_purchase_input_bytes(
                purchase_policy,
                controlled_private_root=cast(Path, controlled_private_root),
                budget_plan_bytes=budget_plan_bytes,
                selection_bytes=selection_bytes,
            )
        else:
            if replacement_private_root is None or controlled_private_root is None:
                raise CommandError(
                    "replacement purchase authority requires both the initial and "
                    "replacement controlled private roots"
                )
            verify_replacement_purchase_authority(
                authority_artifact=cast(
                    Mapping[str, object], replacement_authority_artifact
                ),
                controlled_private_root=replacement_private_root,
                initial_purchase_policy_artifact=purchase_policy_artifact,
                initial_controlled_private_root=controlled_private_root,
                cohort_policy_artifact=cohort_policy_artifact,
                budget_plan_bytes=budget_plan_bytes,
                selection_bytes=selection_bytes,
                purchase_ledger_path=ledger_path,
                purchase_ledger_initialization_receipt_path=cast(
                    Path, initialization_receipt
                ),
            )
        verify_case_dev_purchase_policy_cohort_binding(
            purchase_policy, cohort_policy_artifact
        )
        public_documents = public_documents_from_selection(selection_records)
        attempt_documents: Mapping[str, Mapping[str, str]] = {}
        attempt_policy_sha256: str | None = None
        attempt_policy_artifact: Mapping[str, object] | None = None
        if attempt_policy_path is not None:
            attempt_policy_artifact = _read_json_object(attempt_policy_path)
            attempt_documents = verify_recap_fetch_attempt_policy(
                attempt_policy_artifact,
                purchase_policy_artifact=purchase_policy_artifact,
                cohort_policy_artifact=cohort_policy_artifact,
                budget_plan=plan,
                budget_plan_artifact=budget_plan_artifact,
                selection_records=selection_records,
                budget_plan_bytes=budget_plan_bytes,
                selection_bytes=selection_bytes,
                controlled_private_root=cast(Path, controlled_private_root),
                replacement_purchase_authority_artifact=(
                    replacement_authority_artifact
                ),
                replacement_controlled_private_root=replacement_private_root,
                purchase_ledger_initialization_receipt_path=initialization_receipt,
            )
            attempt_policy_sha256 = _required_str(
                attempt_policy_artifact, "policy_sha256"
            )
        if (
            live_purchase
            and replacement_authority_path is not None
            and not direct_courtlistener_purchase
            and broker_policy_path is None
        ):
            raise CommandError(
                "--broker-policy is required for a live replacement purchase; "
                "generate and activate the exact successor policy before brokered "
                "paid admission, or use --direct-courtlistener-purchase"
            )
        if broker_policy_path is not None:
            verify_recap_fetch_broker_policy(
                _read_json_object(broker_policy_path),
                purchase_policy_artifact=purchase_policy_artifact,
                cohort_policy_artifact=cohort_policy_artifact,
                budget_plan=plan,
                budget_plan_artifact=budget_plan_artifact,
                selection_records=selection_records,
                budget_plan_bytes=budget_plan_bytes,
                selection_bytes=selection_bytes,
                controlled_private_root=cast(Path, controlled_private_root),
                attempt_policy_artifact=attempt_policy_artifact,
                replacement_purchase_authority_artifact=(
                    replacement_authority_artifact
                ),
                replacement_controlled_private_root=replacement_private_root,
                purchase_ledger_initialization_receipt_path=initialization_receipt,
            )
        if ledger_path != purchase_policy.canonical_ledger_path:
            raise CommandError(
                "--purchase-ledger conflicts with the canonical policy locator"
            )
        if not dry_run:
            # Authenticate the existing ledger and immutable initialization
            # receipt before loading any environment, transport, broker, budget,
            # client, or provider configuration.
            read_case_dev_purchase_snapshot(
                ledger_path,
                policy=purchase_policy,
                controlled_private_root=controlled_private_root,
                initialization_receipt_path=initialization_receipt,
            )
        if dry_run:
            _acquisition_output_root(args)
            output_initialized = True
            attempts = tuple(
                CaseDevPacerPurchaseAttempt(
                    candidate_id=case_plan.candidate_id,
                    source_document_id=document_id,
                    status=CaseDevPacerPurchaseStatus.PLANNED_DRY_RUN,
                    reason="dry_run_no_paid_request",
                    source_provider="courtlistener.recap-fetch+pacer",
                )
                for case_plan in plan.case_plans
                for document_id in case_plan.purchase_document_ids
            )
            result = CaseDevPacerPurchaseResult(
                live=False,
                acknowledge_pacer_fees=acknowledge_fees,
                capability=CaseDevPacerCapability.DOCUMENT_LEVEL_PURCHASE,
                dry_run=True,
                projected_cost_usd=plan.total_estimated_cost_usd,
                max_projected_budget_usd=plan.max_projected_budget_usd,
                attempts=attempts,
            )
        else:
            if plan.dry_run:
                raise CommandError(
                    "purchase-missing-recap-fetch requires a non-dry-run budget plan"
                )
            if not acknowledge_fees:
                raise CommandError(
                    "purchase-missing-recap-fetch --execute requires "
                    "--acknowledge-pacer-fees"
                )
            if live_purchase:
                if courtlistener_fixture is not None or broker_fixture is not None:
                    raise CommandError(
                        "--live-purchase cannot be combined with offline fixtures"
                    )
                request_ledger = cast(Path | None, args.request_ledger)
                if request_ledger is None:
                    raise CommandError(
                        "--request-ledger is required with --live-purchase"
                    )
                max_wait = cast(float, args.request_budget_max_wait_seconds)
                if max_wait < 0:
                    raise CommandError(
                        "--request-budget-max-wait-seconds cannot be negative"
                    )
                direct_config = (
                    DirectCourtListenerRecapFetchConfig.from_env()
                    if direct_courtlistener_purchase
                    else None
                )
                courtlistener_config = (
                    direct_config.public_config()
                    if direct_config is not None
                    else CourtListenerRecapFetchConfig.from_env()
                )
                # Validate the allowlisted, redirect-refusing transport before the
                # purchase journal is opened or any paid operation can be reserved.
                courtlistener_transport = UrlLibRecapFetchTransport(
                    courtlistener_config.base_url
                )
                profile = cast(str, args.courtlistener_rate_profile)
                request_budget = CourtListenerRequestBudget(
                    request_ledger,
                    limits=_COURTLISTENER_RATE_PROFILES[profile],
                    max_wait_seconds=max_wait,
                )
                purchase_broker = (
                    DirectCourtListenerRecapFetchPurchaseBroker(
                        direct_config,
                        transport=courtlistener_transport,
                        before_request=request_budget.reserve_cancellable,
                    )
                    if direct_config is not None
                    else SignedRecapFetchPurchaseBroker(
                        RecapFetchBrokerConfig.from_env()
                    )
                )
                _acquisition_output_root(args)
                output_initialized = True
                with CaseDevPurchaseJournal(
                    ledger_path,
                    policy=purchase_policy,
                    controlled_private_root=controlled_private_root,
                    initialization_receipt_path=initialization_receipt,
                ) as journal:
                    client = CourtListenerRecapFetchClient(
                        courtlistener_config,
                        journal=journal,
                        transport=courtlistener_transport,
                        purchase_broker=purchase_broker,
                        before_request=request_budget.before_request,
                    )
                    result = client.execute_purchase_plan(
                        plan,
                        public_documents=public_documents,
                        attempt_documents=attempt_documents,
                        attempt_policy_sha256=attempt_policy_sha256,
                        live=True,
                        acknowledge_pacer_fees=True,
                    )
            else:
                if courtlistener_fixture is None or broker_fixture is None:
                    raise CommandError(
                        "offline execution requires --courtlistener-fixture and "
                        "--purchase-broker-fixture"
                    )
                raw_broker_responses = _loads_json(
                    broker_fixture.read_text(encoding="utf-8")
                )
                if isinstance(raw_broker_responses, str) or not isinstance(
                    raw_broker_responses, Sequence
                ):
                    raise CommandError("purchase broker fixture must be a JSON array")
                broker_responses = tuple(
                    _mapping(item, "purchase broker fixture response")
                    for item in cast(Sequence[object], raw_broker_responses)
                )
                courtlistener_transport = FixtureRecapFetchTransport.from_jsonl(
                    courtlistener_fixture
                )
                purchase_broker = FixtureRecapFetchPurchaseBroker(broker_responses)
                _acquisition_output_root(args)
                output_initialized = True
                with CaseDevPurchaseJournal(
                    ledger_path,
                    policy=purchase_policy,
                    controlled_private_root=controlled_private_root,
                    initialization_receipt_path=initialization_receipt,
                ) as journal:
                    client = CourtListenerRecapFetchClient(
                        CourtListenerRecapFetchConfig(api_token="offline-fixture"),
                        journal=journal,
                        transport=courtlistener_transport,
                        purchase_broker=purchase_broker,
                    )
                    result = client.execute_purchase_plan(
                        plan,
                        public_documents=public_documents,
                        attempt_documents=attempt_documents,
                        attempt_policy_sha256=attempt_policy_sha256,
                        live=True,
                        acknowledge_pacer_fees=True,
                    )
    except (
        CommandError,
        CaseDevPurchaseLedgerError,
        CaseDevPurchasePolicyError,
        RecapFetchAttemptPolicyError,
        RecapFetchBrokerPolicyError,
        CourtListenerRecapFetchError,
        CourtListenerRequestBudgetError,
        OSError,
        sqlite3.Error,
        UnicodeError,
        ValueError,
    ) as exc:
        if live_purchase and output_initialized:
            _write_acquisition_failure(
                args,
                stage="purchase-missing-recap-fetch",
                input_paths=input_paths,
                output_paths=(output_path, ledger_path),
                reason=str(exc),
                paid_activity_requested=True,
                paid_activity_executed=(
                    client is not None and client.paid_request_count > 0
                ),
                extra=_recap_fetch_rate_evidence(
                    args,
                    client=client,
                    budget=request_budget,
                    live=True,
                ),
            )
        elif not dry_run and output_initialized:
            _write_acquisition_failure(
                args,
                stage="purchase-missing-recap-fetch",
                input_paths=input_paths,
                output_paths=(output_path, ledger_path),
                reason=str(exc),
                paid_activity_requested=False,
                paid_activity_executed=False,
                extra=_recap_fetch_rate_evidence(
                    args,
                    client=client,
                    budget=None,
                    live=False,
                ),
            )
        raise CommandError(str(exc)) from exc

    paid_executed = (
        live_purchase and client is not None and client.paid_request_count > 0
    )
    rate_evidence = _recap_fetch_rate_evidence(
        args,
        client=client,
        budget=request_budget,
        live=live_purchase,
    )
    _acquisition_output_root(args)
    _write_json(output_path, result.to_record())
    _write_acquisition_completion(
        args,
        stage="purchase-missing-recap-fetch",
        input_paths=input_paths,
        output_paths=(output_path,) if dry_run else (output_path, ledger_path),
        record_count=result.intended_purchase_count,
        dry_run=dry_run,
        paid_activity_requested=live_purchase,
        paid_activity_executed=paid_executed,
        extra={
            "executed_purchase_count": result.executed_purchase_count,
            "quarantined_material_count": result.quarantined_material_count,
            "completed_purchase_count": result.completed_purchase_count,
            **rate_evidence,
        },
    )
    return 0 if result.completed_purchase_count == result.intended_purchase_count else 2


def _authenticated_target_projection_inputs(
    *,
    selection_path: Path,
    case_relevance_path: Path,
    run_card_path: Path,
    captured_artifact_bytes: Mapping[str, bytes] | None = None,
) -> tuple[bytes, bytes]:
    """Authenticate exact target selection and relevance bytes as one snapshot."""

    selection_bytes = _captured_or_stable_input(
        selection_path,
        label="target projection selection",
        captured_artifact_bytes=captured_artifact_bytes,
    )
    relevance_bytes = _captured_or_stable_input(
        case_relevance_path,
        label="target projection case relevance",
        captured_artifact_bytes=captured_artifact_bytes,
    )
    run_card_bytes = _captured_or_stable_input(
        run_card_path,
        label="target projection run card",
        captured_artifact_bytes=captured_artifact_bytes,
    )
    run_card = _projection_json_object(run_card_bytes, source=run_card_path)
    if (
        run_card.get("schema_version") != "legalforecast.acquisition_run_card.v1"
        or run_card.get("stage") != "project-target-cohort"
        or run_card.get("status") != "completed"
        or run_card.get("dry_run") is not False
        or run_card.get("execute") is not True
        or run_card.get("paid_activity_requested") is not False
        or run_card.get("paid_activity_executed") is not False
    ):
        raise CommandError("invalid completed project-target-cohort run card")
    raw_outputs = run_card.get("output_paths")
    raw_commitments = run_card.get("output_commitments")
    if not isinstance(raw_outputs, list) or not isinstance(raw_commitments, Mapping):
        raise CommandError("project-target-cohort run card lacks exact outputs")
    output_paths = {
        os.path.abspath(Path(str(value))) for value in cast(list[object], raw_outputs)
    }
    commitments = cast(Mapping[str, object], raw_commitments)
    normalized_commitments = {
        os.path.abspath(Path(str(raw_path))): digest
        for raw_path, digest in commitments.items()
    }
    for path, payload, label in (
        (selection_path, selection_bytes, "selection"),
        (case_relevance_path, relevance_bytes, "case relevance"),
    ):
        absolute = os.path.abspath(path)
        if absolute not in output_paths or normalized_commitments.get(
            absolute
        ) != _bytes_sha256(payload):
            raise CommandError(
                f"project-target-cohort does not commit exact {label} output"
            )
    return selection_bytes, relevance_bytes


def _project_purchased_case_relevance(
    case_relevance: Sequence[Mapping[str, Any]],
    recovered_manifest: Sequence[Mapping[str, Any]],
) -> tuple[dict[str, object], ...]:
    try:
        return project_purchased_case_relevance(case_relevance, recovered_manifest)
    except RecapFetchQuarantineRecoveryError as exc:
        raise CommandError(str(exc)) from exc


def _cmd_acquisition_recover_recap_fetch_quarantine(
    args: argparse.Namespace,
) -> int:
    if not _acquisition_dry_run(args):
        _preflight_current_purchase_snapshot(args)
    _preflight_approved_purchase_input_bytes(args)
    controlled_private_root = cast(Path | None, args.controlled_private_root)
    initialization_receipt = cast(
        Path | None, args.purchase_ledger_initialization_receipt
    )
    output_root = cast(Path, args.output_root)
    selection_path = cast(Path, args.selection)
    case_relevance_path = cast(Path, args.case_relevance)
    target_projection_run_card_path = cast(Path | None, args.target_projection_run_card)
    purchase_policy_path = cast(Path, args.purchase_policy)
    cohort_policy_path = cast(Path, args.cohort_policy)
    budget_plan_path = cast(Path, args.budget_plan)
    ledger_path = cast(Path, args.purchase_ledger).resolve()
    attempt_policy_path = cast(Path, args.attempt_policy)
    replacement_authority_path = cast(Path | None, args.replacement_purchase_authority)
    replacement_private_root = cast(
        Path | None, args.replacement_controlled_private_root
    )
    manifest_path = _acquisition_path(
        args,
        "manifest_output",
        output_root / "recap-fetch-quarantine-downloads.jsonl",
    )
    purchased_case_relevance_path = _acquisition_path(
        args,
        "case_relevance_output",
        output_root / "purchased-case-relevance.jsonl",
    )
    restriction_path = _acquisition_path(
        args,
        "restriction_evidence_output",
        output_root / "post-recovery-restriction-evidence.jsonl",
    )
    terminal_unavailable_path = _acquisition_path(
        args,
        "terminal_unavailable_output",
        output_root / "terminal-unavailable-operations.jsonl",
    )
    review_requests_path = _acquisition_path(
        args,
        "review_requests_output",
        output_root / "disclosure-review-requests.jsonl",
    )
    document_root = _acquisition_path(
        args,
        "document_output_root",
        output_root / "documents" / "recap-fetch-quarantine",
    )
    courtlistener_fixture = cast(Path | None, args.courtlistener_fixture)
    document_fixture = cast(Path | None, args.fixture_documents)
    live = cast(bool, args.live_courtlistener_recovery)
    dry_run = _acquisition_dry_run(args)
    immutable_input_paths: tuple[Path, ...] = (
        selection_path,
        case_relevance_path,
        *(
            (target_projection_run_card_path,)
            if target_projection_run_card_path is not None
            else ()
        ),
        purchase_policy_path,
        cohort_policy_path,
        budget_plan_path,
        attempt_policy_path,
        *((replacement_authority_path,) if replacement_authority_path else ()),
        *((courtlistener_fixture,) if courtlistener_fixture is not None else ()),
        *((document_fixture,) if document_fixture is not None else ()),
    )
    input_paths = (
        selection_path,
        case_relevance_path,
        *(
            (target_projection_run_card_path,)
            if target_projection_run_card_path is not None
            else ()
        ),
        purchase_policy_path,
        cohort_policy_path,
        budget_plan_path,
        ledger_path,
        attempt_policy_path,
        *((replacement_authority_path,) if replacement_authority_path else ()),
        *((courtlistener_fixture,) if courtlistener_fixture is not None else ()),
        *((document_fixture,) if document_fixture is not None else ()),
    )
    try:
        immutable_input_snapshot = {
            path: _read_singly_linked_regular_input(
                path, label="quarantine recovery input"
            )
            for path in immutable_input_paths
        }
        normalized_input_snapshot = {
            os.path.abspath(path): payload
            for path, payload in immutable_input_snapshot.items()
        }
        replacement_mode = replacement_authority_path is not None
        if replacement_mode:
            if (
                replacement_private_root is None
                or target_projection_run_card_path is not None
                or selection_path.resolve() != case_relevance_path.resolve()
            ):
                raise CommandError(
                    "replacement recovery requires its successor authority, no "
                    "target projection card, and the exact authority-bound selection "
                    "for both --selection and --case-relevance"
                )
            selection_bytes = immutable_input_snapshot[selection_path]
            case_relevance_bytes = selection_bytes
        else:
            if target_projection_run_card_path is None:
                raise CommandError(
                    "initial recovery requires --target-projection-run-card"
                )
            selection_bytes, case_relevance_bytes = (
                _authenticated_target_projection_inputs(
                    selection_path=selection_path,
                    case_relevance_path=case_relevance_path,
                    run_card_path=target_projection_run_card_path,
                    captured_artifact_bytes=normalized_input_snapshot,
                )
            )
        selection_records = _projection_jsonl_records(
            selection_bytes, source=selection_path
        )
        case_relevance_records = _projection_jsonl_records(
            case_relevance_bytes, source=case_relevance_path
        )
        purchase_policy_artifact = _projection_json_object(
            immutable_input_snapshot[purchase_policy_path], source=purchase_policy_path
        )
        cohort_policy_artifact = _projection_json_object(
            immutable_input_snapshot[cohort_policy_path], source=cohort_policy_path
        )
        budget_plan_artifact = _projection_json_object(
            immutable_input_snapshot[budget_plan_path], source=budget_plan_path
        )
        attempt_policy_artifact = _projection_json_object(
            immutable_input_snapshot[attempt_policy_path], source=attempt_policy_path
        )
        policy = verify_case_dev_purchase_policy(purchase_policy_artifact)
        require_approved_case_dev_purchase_policy(
            policy, controlled_private_root=controlled_private_root
        )
        if not replacement_mode:
            verify_approved_purchase_input_bytes(
                policy,
                controlled_private_root=cast(Path, controlled_private_root),
                budget_plan_bytes=immutable_input_snapshot[budget_plan_path],
                selection_bytes=selection_bytes,
            )
        verify_case_dev_purchase_policy_cohort_binding(policy, cohort_policy_artifact)
        if ledger_path != policy.canonical_ledger_path:
            raise RecapFetchQuarantineRecoveryError(
                "--purchase-ledger conflicts with the canonical policy locator"
            )
        plan = _missing_core_budget_plan(budget_plan_artifact)
        allowed_documents = verify_recap_fetch_attempt_policy(
            attempt_policy_artifact,
            purchase_policy_artifact=purchase_policy_artifact,
            cohort_policy_artifact=cohort_policy_artifact,
            budget_plan=plan,
            budget_plan_artifact=budget_plan_artifact,
            selection_records=selection_records,
            budget_plan_bytes=immutable_input_snapshot[budget_plan_path],
            selection_bytes=selection_bytes,
            controlled_private_root=cast(Path, controlled_private_root),
            replacement_purchase_authority_artifact=(
                _projection_json_object(
                    immutable_input_snapshot[replacement_authority_path],
                    source=replacement_authority_path,
                )
                if replacement_authority_path is not None
                else None
            ),
            replacement_controlled_private_root=replacement_private_root,
            purchase_ledger_initialization_receipt_path=initialization_receipt,
        )
        attempt_policy_sha256 = _required_str(attempt_policy_artifact, "policy_sha256")
        purchase_state_sha256: str | None = None
        if not dry_run:
            # Recovery must authenticate the same private approval, immutable
            # initialization receipt, and current ledger before constructing
            # either live or fixture runtime clients and transports.
            read_case_dev_purchase_snapshot(
                ledger_path,
                policy=policy,
                controlled_private_root=controlled_private_root,
                initialization_receipt_path=initialization_receipt,
            )
        _acquisition_output_root(args)
        if dry_run:
            records: Sequence[Mapping[str, Any]] = (
                {
                    "stage": "recover-recap-fetch-quarantine",
                    "dry_run": True,
                    "authorized_document_count": len(allowed_documents),
                    "paid_activity_requested": False,
                },
            )
            _write_jsonl(manifest_path, records)
            _write_jsonl(purchased_case_relevance_path, [])
            _write_jsonl(restriction_path, [])
            terminal_unavailable_records: Sequence[Mapping[str, Any]] = ()
            _write_jsonl(terminal_unavailable_path, terminal_unavailable_records)
            _write_jsonl(review_requests_path, [])
        else:
            if live:
                if courtlistener_fixture is not None or document_fixture is not None:
                    raise RecapFetchQuarantineRecoveryError(
                        "live recovery cannot be combined with offline fixtures"
                    )
                request_ledger = cast(Path | None, args.request_ledger)
                if request_ledger is None:
                    raise RecapFetchQuarantineRecoveryError(
                        "--request-ledger is required for live recovery"
                    )
                max_wait = cast(float, args.request_budget_max_wait_seconds)
                if max_wait < 0:
                    raise RecapFetchQuarantineRecoveryError(
                        "--request-budget-max-wait-seconds cannot be negative"
                    )
                config = CourtListenerRecapFetchConfig.from_env()
                transport = UrlLibRecapFetchTransport(config.base_url)
                source: FreeDocumentSource = UrlLibFreeDocumentSource()
                request_budget = CourtListenerRequestBudget(
                    request_ledger,
                    limits=_COURTLISTENER_RATE_PROFILES[
                        cast(str, args.courtlistener_rate_profile)
                    ],
                    max_wait_seconds=max_wait,
                )
                before_request = request_budget.before_request
            else:
                if courtlistener_fixture is None or document_fixture is None:
                    raise RecapFetchQuarantineRecoveryError(
                        "offline recovery requires --courtlistener-fixture and "
                        "--fixture-documents"
                    )
                config = CourtListenerRecapFetchConfig(api_token="offline-fixture")
                transport = FixtureRecapFetchTransport.from_jsonl_bytes(
                    immutable_input_snapshot[courtlistener_fixture]
                )
                source = _fixture_free_document_source_bytes(
                    immutable_input_snapshot[document_fixture]
                )
                before_request = None
            with CaseDevPurchaseJournal(
                ledger_path,
                policy=policy,
                controlled_private_root=controlled_private_root,
                initialization_receipt_path=initialization_receipt,
            ) as journal:
                (
                    records,
                    restriction_records,
                    terminal_unavailable_records,
                ) = recover_recap_fetch_quarantine_documents(
                    journal=journal,
                    allowed_documents=allowed_documents,
                    attempt_policy_sha256=attempt_policy_sha256,
                    output_root=document_root,
                    source=source,
                    config=config,
                    transport=transport,
                    before_request=before_request,
                )
                write_recap_fetch_quarantine_manifest(manifest_path, records)
                purchased_case_relevance = _project_purchased_case_relevance(
                    case_relevance_records, records
                )
                _write_jsonl(purchased_case_relevance_path, purchased_case_relevance)
                write_recap_fetch_restriction_evidence(
                    restriction_path, restriction_records
                )
                write_recap_fetch_quarantine_manifest(
                    terminal_unavailable_path,
                    terminal_unavailable_records,
                    label="terminal unavailable operations",
                )
                review_requests = build_recap_fetch_disclosure_review_requests(
                    records, restriction_records
                )
                write_recap_fetch_disclosure_review_requests(
                    review_requests_path, review_requests
                )
                purchase_state_sha256 = journal.purchase_state_sha256()
        _require_snapshot_unchanged(
            immutable_input_snapshot, label="quarantine recovery input"
        )
        output_snapshot = {
            manifest_path: _read_singly_linked_regular_input(
                manifest_path, label="quarantine recovery manifest"
            ),
            purchased_case_relevance_path: _read_singly_linked_regular_input(
                purchased_case_relevance_path,
                label="purchased case relevance",
            ),
            restriction_path: _read_singly_linked_regular_input(
                restriction_path, label="quarantine restriction evidence"
            ),
            terminal_unavailable_path: _read_singly_linked_regular_input(
                terminal_unavailable_path,
                label="quarantine terminal unavailable operations",
            ),
            review_requests_path: _read_singly_linked_regular_input(
                review_requests_path, label="quarantine review requests"
            ),
        }
    except (
        CaseDevPurchaseLedgerError,
        CaseDevPurchasePolicyError,
        CourtListenerRecapFetchError,
        CourtListenerRequestBudgetError,
        FreeDocumentDownloadError,
        RecapFetchAttemptPolicyError,
        RecapFetchQuarantineRecoveryError,
        OSError,
        sqlite3.Error,
        UnicodeError,
        ValueError,
    ) as exc:
        _write_acquisition_failure(
            args,
            stage="recover-recap-fetch-quarantine",
            input_paths=input_paths,
            output_paths=(
                manifest_path,
                purchased_case_relevance_path,
                restriction_path,
                terminal_unavailable_path,
                review_requests_path,
                document_root,
                ledger_path,
            ),
            reason=str(exc),
            paid_activity_requested=False,
            paid_activity_executed=False,
        )
        raise CommandError(str(exc)) from exc
    _acquisition_output_root(args)
    _write_acquisition_completion(
        args,
        stage="recover-recap-fetch-quarantine",
        schema_version=_RECAP_FETCH_QUARANTINE_RECOVERY_CARD_SCHEMA,
        input_paths=input_paths,
        output_paths=(
            manifest_path,
            purchased_case_relevance_path,
            restriction_path,
            terminal_unavailable_path,
            review_requests_path,
            document_root,
            ledger_path,
        ),
        record_count=len(records),
        dry_run=dry_run,
        paid_activity_requested=False,
        paid_activity_executed=False,
        extra={
            "source_commitments": (
                {}
                if dry_run
                else {
                    "selection": _file_commitment_from_bytes(
                        selection_path, immutable_input_snapshot[selection_path]
                    ),
                    "case_relevance": _file_commitment_from_bytes(
                        case_relevance_path,
                        immutable_input_snapshot[case_relevance_path],
                    ),
                    **(
                        {
                            "target_projection_run_card": _file_commitment_from_bytes(
                                target_projection_run_card_path,
                                immutable_input_snapshot[
                                    target_projection_run_card_path
                                ],
                            )
                        }
                        if target_projection_run_card_path is not None
                        else {}
                    ),
                    **(
                        {
                            "replacement_purchase_authority": (
                                _file_commitment_from_bytes(
                                    replacement_authority_path,
                                    immutable_input_snapshot[
                                        replacement_authority_path
                                    ],
                                )
                            )
                        }
                        if replacement_authority_path is not None
                        else {}
                    ),
                    "purchase_policy": _file_commitment_from_bytes(
                        purchase_policy_path,
                        immutable_input_snapshot[purchase_policy_path],
                    ),
                    "cohort_policy": _file_commitment_from_bytes(
                        cohort_policy_path, immutable_input_snapshot[cohort_policy_path]
                    ),
                    "budget_plan": _file_commitment_from_bytes(
                        budget_plan_path, immutable_input_snapshot[budget_plan_path]
                    ),
                    "attempt_policy": _file_commitment_from_bytes(
                        attempt_policy_path,
                        immutable_input_snapshot[attempt_policy_path],
                    ),
                    **(
                        {
                            "courtlistener_fixture": _file_commitment_from_bytes(
                                courtlistener_fixture,
                                immutable_input_snapshot[courtlistener_fixture],
                            ),
                            "fixture_documents": _file_commitment_from_bytes(
                                document_fixture,
                                immutable_input_snapshot[document_fixture],
                            ),
                        }
                        if courtlistener_fixture is not None
                        and document_fixture is not None
                        else {}
                    ),
                }
            ),
            "output_commitments": (
                {}
                if dry_run
                else {
                    "quarantine_download_manifest": {
                        "path": str(manifest_path.resolve()),
                        "sha256": _bytes_sha256(output_snapshot[manifest_path]),
                    },
                    "purchased_case_relevance": {
                        "path": str(purchased_case_relevance_path.resolve()),
                        "sha256": _bytes_sha256(
                            output_snapshot[purchased_case_relevance_path]
                        ),
                    },
                    "fresh_restriction_evidence": {
                        "path": str(restriction_path.resolve()),
                        "sha256": _bytes_sha256(output_snapshot[restriction_path]),
                    },
                    "terminal_unavailable_operations": {
                        "path": str(terminal_unavailable_path.resolve()),
                        "sha256": _bytes_sha256(
                            output_snapshot[terminal_unavailable_path]
                        ),
                    },
                    "disclosure_review_requests": {
                        "path": str(review_requests_path.resolve()),
                        "sha256": _bytes_sha256(output_snapshot[review_requests_path]),
                    },
                    "document_tree": _materializer_tree_commitments(document_root),
                    "purchase_state_sha256": purchase_state_sha256,
                }
            ),
            "authority_mode": (
                "replacement_successor"
                if replacement_authority_path is not None
                else "initial_projection"
            ),
            "authorized_document_count": len(allowed_documents),
            "recovered_document_count": 0 if dry_run else len(records),
            "terminal_unavailable_document_count": len(terminal_unavailable_records),
        },
    )
    return 0


def _cmd_acquisition_plan_docket_live_fetches(args: argparse.Namespace) -> int:
    output_root = cast(Path, args.output_root)
    screening_paths = tuple(cast(list[Path], args.screening_candidates))
    fetch_paths = tuple(cast(list[Path], args.fetch_successes))
    ranking_paths = tuple(cast(list[Path], args.case_dev_ranking))
    advisory_paths = tuple(cast(list[Path], args.advisory_candidates))
    policy_path = cast(Path, args.cohort_policy)
    output_path = _acquisition_path(
        args,
        "plan_output",
        output_root / "docket-live-fetch-plan.json",
    )
    policy = _read_json_object(policy_path)
    try:
        verify_cohort_policy(policy)
    except CohortPolicyError as exc:
        raise CommandError(str(exc)) from exc
    dry_run = _acquisition_dry_run(args)
    input_paths = (
        *screening_paths,
        *fetch_paths,
        *ranking_paths,
        *advisory_paths,
        policy_path,
    )
    if dry_run:
        _write_json(
            output_path,
            {
                "stage": "plan-docket-live-fetches",
                "dry_run": True,
                "provider_requests": 0,
            },
        )
        record_count = 0
        projected_cost = "0.00"
        executable_count = 0
        executable_cost = "0.00"
    else:
        plan = plan_docket_live_fetches(
            screening_records=(
                record for path in screening_paths for record in _read_records(path)
            ),
            fetch_success_records=(
                record for path in fetch_paths for record in _read_records(path)
            ),
            ranking_records=(
                record for path in ranking_paths for record in _read_records(path)
            ),
            advisory_records=(
                record for path in advisory_paths for record in _read_records(path)
            ),
            cohort_policy=policy,
            docket_fetch_reservation_usd=cast(str, args.docket_fetch_reservation_usd),
            cycle_committed_spend_usd=cast(str, args.cycle_committed_spend_usd),
            daily_budget_usd=cast(str, args.daily_budget_usd),
            daily_committed_spend_usd=cast(str, args.daily_committed_spend_usd),
            spend_date_utc=cast(str, args.spend_date_utc),
            canonical_journal_path=str(
                (output_root / "case-dev-docket-live-fetch.sqlite3").resolve()
            ),
        )
        _write_json(output_path, plan.to_record())
        record_count = len(plan.items)
        projected_cost = plan.total_projected_cost_usd
        executable_count = len(plan.executable_items)
        executable_cost = plan.executable_projected_cost_usd
    _write_acquisition_completion(
        args,
        stage="plan-docket-live-fetches",
        input_paths=input_paths,
        output_paths=(output_path,),
        record_count=record_count,
        dry_run=dry_run,
        paid_activity_requested=False,
        paid_activity_executed=False,
        extra={
            "provider_requests": 0,
            "projected_cost_usd": projected_cost,
            "executable_count": executable_count,
            "executable_projected_cost_usd": executable_cost,
        },
    )
    return 0


def _cmd_acquisition_execute_docket_live_fetches(args: argparse.Namespace) -> int:
    fixture_path = cast(Path | None, args.case_dev_fixture)
    live_case_dev = cast(bool, args.live_case_dev)
    if live_case_dev:
        raise CommandError(
            "legacy fee-bearing Case.dev docket fetch is disabled; use the "
            "CourtListener-first acquisition path"
        )
    output_root = _acquisition_output_root(args)
    plan_path = cast(Path, args.docket_live_fetch_plan)
    journal_path = _acquisition_path(
        args,
        "journal",
        output_root / "case-dev-docket-live-fetch.sqlite3",
    )
    result_path = _acquisition_path(
        args,
        "result_output",
        output_root / "case-dev-docket-live-fetch-result.json",
    )
    plan = load_docket_live_fetch_plan(_read_json_object(plan_path))
    dry_run = _acquisition_dry_run(args)
    acknowledge_fees = cast(bool, args.acknowledge_pacer_fees)
    if not dry_run and not acknowledge_fees:
        raise CommandError(
            "execute-docket-live-fetches requires --acknowledge-pacer-fees"
        )
    if not dry_run and fixture_path is None and not live_case_dev:
        raise CommandError(
            "execute-docket-live-fetches requires --case-dev-fixture or --live-case-dev"
        )
    if dry_run:
        result = DocketLiveFetchExecutionResult(
            plan_sha256=plan.plan_sha256,
            intended_count=len(plan.executable_items),
            confirmed_count=0,
            statuses={
                item.docket_id: "planned_dry_run" for item in plan.executable_items
            },
            confirmed_candidates=(),
        )
        paid_requested = False
        paid_executed = False
    else:
        client = _case_dev_client(
            command="acquisition execute-docket-live-fetches",
            fixture_path=fixture_path,
            live=live_case_dev,
        )
        try:
            result = execute_docket_live_fetch_plan(
                plan,
                client=client,
                journal_path=journal_path,
                live=True,
                acknowledge_pacer_fees=True,
            )
        except (CaseDevClientError, DocketLiveFetchError, ValueError) as exc:
            paid_post_sent = live_case_dev and client.request_count > 0
            _write_acquisition_failure(
                args,
                stage="execute-docket-live-fetches",
                input_paths=(plan_path,),
                output_paths=(journal_path, result_path),
                reason=str(exc),
                paid_activity_requested=live_case_dev,
                paid_activity_executed=paid_post_sent,
            )
            raise CommandError(str(exc)) from exc
        paid_requested = live_case_dev
        paid_executed = live_case_dev and client.request_count > 0
    _write_json(result_path, result.to_record())
    outputs = (result_path,) if dry_run else (result_path, journal_path)
    _write_acquisition_completion(
        args,
        stage="execute-docket-live-fetches",
        input_paths=(plan_path,),
        output_paths=outputs,
        record_count=result.intended_count,
        dry_run=dry_run,
        paid_activity_requested=paid_requested,
        paid_activity_executed=paid_executed,
        extra={"confirmed_count": result.confirmed_count},
    )
    return 0


def _cmd_acquisition_recover_purchased(args: argparse.Namespace) -> int:
    if cast(bool, args.live_case_dev_download) or cast(
        bool, args.live_courtlistener_download
    ):
        raise CommandError(
            "legacy recover-purchased live downloads are disabled; use the "
            "authenticated RECAP Fetch quarantine recovery path"
        )
    output_root = _acquisition_output_root(args)
    purchase_result_path = cast(Path, args.purchase_result)
    selection_path = cast(Path, args.selection)
    manifest_path = _acquisition_path(
        args,
        "manifest_output",
        output_root / "purchased-document-downloads.jsonl",
    )
    recovery_path = _acquisition_path(
        args,
        "recovery_output",
        output_root / "purchased-document-recovery.jsonl",
    )
    document_root = _acquisition_path(
        args,
        "document_output_root",
        output_root / "documents" / "purchased",
    )
    dry_run = _acquisition_dry_run(args)
    try:
        requests = purchased_document_recovery_requests_from_records(
            _read_json_object(purchase_result_path),
            _read_records(selection_path),
        )
    except PurchasedDocumentRecoveryError as exc:
        _write_acquisition_failure(
            args,
            stage="recover-purchased",
            input_paths=(purchase_result_path, selection_path),
            output_paths=(manifest_path, recovery_path, document_root),
            reason=str(exc),
            paid_activity_requested=False,
        )
        raise CommandError(str(exc)) from exc
    if dry_run:
        _write_jsonl(
            manifest_path,
            [
                {
                    "stage": "recover-purchased",
                    "dry_run": True,
                    "request_count": len(requests),
                    "document_output_root": str(document_root),
                }
            ],
        )
        _write_jsonl(recovery_path, [])
        recovered_count = 0
    else:
        try:
            source = _purchased_document_source(
                fixture_path=cast(Path | None, args.fixture_documents),
                live_case_dev_download=cast(bool, args.live_case_dev_download),
                live_courtlistener_download=cast(
                    bool, args.live_courtlistener_download
                ),
            )
            records = recover_purchased_documents(
                requests,
                output_root=document_root,
                source=source,
                retrieved_at=datetime.now(UTC),
            )
            _write_jsonl(recovery_path, [record.to_record() for record in records])
            manifest = purchased_document_download_manifest_records(records)
            _write_jsonl(manifest_path, manifest)
        except (
            CommandError,
            PurchasedDocumentDownloadError,
            PurchasedDocumentRecoveryError,
        ) as exc:
            _write_acquisition_failure(
                args,
                stage="recover-purchased",
                input_paths=(purchase_result_path, selection_path),
                output_paths=(manifest_path, recovery_path, document_root),
                reason=str(exc),
                paid_activity_requested=False,
            )
            raise CommandError(str(exc)) from exc
        recovered_count = sum(
            record.status
            in {
                PurchasedDocumentRecoveryStatus.RECOVERED,
                PurchasedDocumentRecoveryStatus.RECOVERED_AUDIT_ONLY,
            }
            for record in records
        )
    intended_recovery_count = sum(
        request.purchase_attempt.status.value == "purchased" for request in requests
    )
    if not dry_run and recovered_count != intended_recovery_count:
        reason = (
            f"recovered {recovered_count} of {intended_recovery_count} "
            "purchased documents"
        )
        _write_acquisition_failure(
            args,
            stage="recover-purchased",
            input_paths=(purchase_result_path, selection_path),
            output_paths=(manifest_path, recovery_path, document_root),
            reason=reason,
            paid_activity_requested=False,
        )
        raise CommandError(reason)
    _write_acquisition_completion(
        args,
        stage="recover-purchased",
        input_paths=(purchase_result_path, selection_path),
        output_paths=(manifest_path, recovery_path, document_root),
        record_count=len(requests),
        dry_run=dry_run,
        paid_activity_requested=False,
        paid_activity_executed=False,
        extra={
            "intended_recovery_count": intended_recovery_count,
            "recovered_count": recovered_count,
            "source_commitments": {
                "purchase_result": {
                    "path": str(purchase_result_path.resolve()),
                    "sha256": _path_sha256(purchase_result_path),
                },
                "selection": {
                    "path": str(selection_path.resolve()),
                    "sha256": _path_sha256(selection_path),
                },
            },
            "output_commitments": (
                {}
                if dry_run
                else {
                    "purchased_document_manifest": {
                        "path": str(manifest_path.resolve()),
                        "sha256": _path_sha256(manifest_path),
                    },
                    "purchased_document_recovery": {
                        "path": str(recovery_path.resolve()),
                        "sha256": _path_sha256(recovery_path),
                    },
                    "document_tree": _materializer_tree_commitments(document_root),
                }
            ),
        },
    )
    return 0


def _capture_provenance_document_snapshot(
    manifest_records: Sequence[Mapping[str, Any]], *, document_root: Path
) -> dict[str, bytes]:
    """Read every manifest document once through the strict disclosure path."""

    snapshot: dict[str, bytes] = {}
    for record in manifest_records:
        relative = _required_str(record, "local_path")
        if relative in snapshot:
            raise CommandError("download manifest repeats a local document path")
        try:
            path = safe_disclosure_document_path(document_root, relative)
            snapshot[relative] = read_unique_regular_file(path)
        except (DisclosureClearanceError, ReviewBundleError) as exc:
            raise CommandError(f"unsafe disclosure document: {relative}") from exc
    return snapshot


def _provenance_document_tree_from_snapshot(
    snapshot: Mapping[str, bytes],
) -> dict[str, str]:
    return {
        relative: _bytes_sha256(payload)
        for relative, payload in sorted(snapshot.items())
    }


def _model_review_document_map(
    worksheet: Mapping[str, object],
    document_snapshot: Mapping[str, bytes],
) -> dict[tuple[str, str], bytes]:
    """Bind every worksheet row to one captured manifest document."""

    raw_documents = worksheet.get("documents")
    if not isinstance(raw_documents, list):
        raise ProvenanceClearanceError("model review worksheet lacks documents")
    result: dict[tuple[str, str], bytes] = {}
    for value in cast(list[object], raw_documents):
        if not isinstance(value, Mapping):
            raise ProvenanceClearanceError("model review worksheet row is invalid")
        document = cast(Mapping[str, object], value)
        candidate_id = document.get("candidate_id")
        source_document_id = document.get("source_document_id")
        relative = document.get("local_path")
        if not all(
            isinstance(field, str) and field
            for field in (candidate_id, source_document_id, relative)
        ):
            raise ProvenanceClearanceError(
                "model review worksheet document identity is invalid"
            )
        data = document_snapshot.get(cast(str, relative))
        if data is None:
            raise ProvenanceClearanceError(
                "model review worksheet document is absent from manifest snapshot: "
                f"{relative}"
            )
        result[(cast(str, candidate_id), cast(str, source_document_id))] = data
    return result


def _require_provenance_document_snapshot_unchanged(
    snapshot: Mapping[str, bytes], *, document_root: Path
) -> None:
    try:
        current = {
            relative: read_unique_regular_file(
                safe_disclosure_document_path(document_root, relative)
            )
            for relative in snapshot
        }
    except (DisclosureClearanceError, ReviewBundleError) as exc:
        raise CommandError(
            "disclosure document became unsafe during execution"
        ) from exc
    if current != dict(snapshot):
        raise CommandError("disclosure document bytes changed during execution")


def _recovered_public_lineage_digest(  # pyright: ignore[reportUnusedFunction]
    value: object, *, label: str
) -> str:
    return _recovered_public_replay.recovered_public_lineage_digest(value, label=label)


def _derive_recovered_public_lineage_rows(
    recovery: Mapping[str, object],
    *,
    expected_manifest_path: Path,
    expected_restriction_path: Path,
) -> list[dict[str, object]]:
    try:
        return _recovered_public_replay.derive_recovered_public_lineage_rows(
            recovery,
            expected_manifest_path=expected_manifest_path,
            expected_restriction_path=expected_restriction_path,
        )
    except ValueError as exc:
        raise CommandError(str(exc)) from exc


def _direct_queue_delivery_lineage(  # pyright: ignore[reportUnusedFunction]
    operation: Mapping[str, Any],
    *,
    purchase_policy_sha256: str | None,
    recovery_run_card_sha256: str,
    recovery_manifest_sha256: str,
    recovery_restriction_sha256: str,
    purchase_state_sha256: str,
) -> dict[str, object]:
    return _recovered_public_replay.direct_queue_delivery_lineage(
        operation,
        purchase_policy_sha256=purchase_policy_sha256,
        recovery_run_card_sha256=recovery_run_card_sha256,
        recovery_manifest_sha256=recovery_manifest_sha256,
        recovery_restriction_sha256=recovery_restriction_sha256,
        purchase_state_sha256=purchase_state_sha256,
    )


def _authenticate_recovered_public_raw_evidence(
    *,
    recovery_root: Path,
    run_card_path: Path,
    selection_path: Path,
    purchase_policy_path: Path,
    cohort_policy_path: Path,
    ledger_path: Path,
    initialization_receipt_path: Path,
    controlled_private_root: Path | None,
    successor_history_recovery_root: Path | None = None,
    successor_history_controlled_private_root: Path | None = None,
    authority_transition_capability: object | None = None,
    attempt_transition_capability: object | None = None,
    resolved_transition_prior_snapshot: CaseDevPurchaseSnapshot | None = None,
) -> Mapping[str, object]:
    """Thin adapter to the importable recovered-public replay helper."""

    try:
        return _recovered_public_replay.authenticate_recovered_public_raw_evidence(
            recovery_root=recovery_root,
            run_card_path=run_card_path,
            selection_path=selection_path,
            purchase_policy_path=purchase_policy_path,
            cohort_policy_path=cohort_policy_path,
            ledger_path=ledger_path,
            initialization_receipt_path=initialization_receipt_path,
            controlled_private_root=controlled_private_root,
            successor_history_recovery_root=successor_history_recovery_root,
            successor_history_controlled_private_root=(
                successor_history_controlled_private_root
            ),
            authority_transition_capability=authority_transition_capability,
            attempt_transition_capability=attempt_transition_capability,
            resolved_transition_prior_snapshot=resolved_transition_prior_snapshot,
        )
    except (
        OSError,
        RecapFetchAttemptPolicyError,
        ReplacementPurchaseApprovalError,
        ReplacementRecoverySourceError,
        ValueError,
    ) as exc:
        raise CommandError(str(exc)) from exc


def _verified_recovered_public_clearance_capability(
    args: argparse.Namespace,
    *,
    expected_manifest_path: Path,
    expected_restriction_path: Path,
    expected_case_relevance_path: Path,
    expected_review_requests_path: Path,
    expected_document_root: Path,
) -> tuple[
    object | None,
    dict[str, object] | None,
    tuple[Path, ...],
    dict[str, object] | None,
]:
    """Authenticate recovery and current purchase state before issuing authority."""

    names = (
        "recovery_run_card",
        "selection",
        "purchase_policy",
        "purchase_ledger",
        "purchase_ledger_initialization_receipt",
        "recovery_cohort_policy",
    )
    values = {name: cast(Path | None, getattr(args, name, None)) for name in names}
    if all(value is None for value in values.values()):
        if any(
            getattr(args, name, None) is not None
            for name in (
                "successor_history_recovery_root",
                "successor_history_controlled_private_root",
            )
        ):
            raise CommandError(
                "successor history requires the complete recovered-public "
                "verification argument set"
            )
        return None, None, (), None
    missing = [name for name, value in values.items() if value is None]
    if missing:
        raise CommandError(
            "recovered-public verification arguments must be supplied together: "
            + ", ".join(f"--{name.replace('_', '-')}" for name in missing)
        )
    paths = cast(dict[str, Path], values)
    run_card_path = paths["recovery_run_card"]
    selection_path = paths["selection"]
    purchase_policy_path = paths["purchase_policy"]
    ledger_path = paths["purchase_ledger"].resolve()
    initialization_receipt_path = paths["purchase_ledger_initialization_receipt"]
    cohort_policy_path = paths["recovery_cohort_policy"]
    selection_bytes = _read_singly_linked_regular_input(
        selection_path, label="recovered-public selection"
    )
    purchase_policy_bytes = _read_singly_linked_regular_input(
        purchase_policy_path, label="recovered-public purchase policy"
    )
    cohort_policy_bytes = _read_singly_linked_regular_input(
        cohort_policy_path, label="recovered-public cohort policy"
    )
    initialization_receipt_bytes = _read_singly_linked_regular_input(
        initialization_receipt_path,
        label="recovered-public purchase ledger initialization receipt",
    )
    controlled_private_root = cast(Path | None, args.controlled_private_root)
    successor_history_recovery_root = cast(
        Path | None, getattr(args, "successor_history_recovery_root", None)
    )
    successor_history_controlled_private_root = cast(
        Path | None,
        getattr(args, "successor_history_controlled_private_root", None),
    )
    recovery = _authenticate_recovered_public_raw_evidence(
        recovery_root=run_card_path.parents[1],
        run_card_path=run_card_path,
        selection_path=selection_path,
        purchase_policy_path=purchase_policy_path,
        cohort_policy_path=cohort_policy_path,
        ledger_path=ledger_path,
        initialization_receipt_path=initialization_receipt_path,
        controlled_private_root=controlled_private_root,
        successor_history_recovery_root=successor_history_recovery_root,
        successor_history_controlled_private_root=(
            successor_history_controlled_private_root
        ),
    )
    expected_paths = {
        "manifest_path": expected_manifest_path,
        "restriction_path": expected_restriction_path,
        "case_relevance_path": expected_case_relevance_path,
        "review_requests_path": expected_review_requests_path,
        "document_root": expected_document_root,
    }
    for name, expected in expected_paths.items():
        actual = recovery.get(name)
        if not isinstance(actual, Path) or actual.resolve() != expected.resolve():
            label = name.replace("_", " ")
            raise CommandError(
                f"recovered-public verification committed different {label}"
            )
    terminal_unavailable_path = recovery.get("terminal_unavailable_path")
    if terminal_unavailable_path is not None and (
        not isinstance(terminal_unavailable_path, Path)
        or terminal_unavailable_path.resolve()
        != (
            run_card_path.parents[1] / "terminal-unavailable-operations.jsonl"
        ).resolve()
    ):
        raise CommandError(
            "recovered-public verification committed different terminal "
            "unavailable path"
        )
    raw_verified = recovery.get("verified_artifact_bytes")
    if not isinstance(raw_verified, Mapping):
        raise CommandError("recovered-public verification lacks exact recovery bytes")
    verified_bytes = cast(Mapping[str, bytes], raw_verified)
    run_card_bytes = verified_bytes[os.path.abspath(run_card_path)]
    lineage_rows = _derive_recovered_public_lineage_rows(
        recovery,
        expected_manifest_path=expected_manifest_path,
        expected_restriction_path=expected_restriction_path,
    )
    historical_state_sha256 = recovery.get("historical_purchase_state_sha256")
    if (
        not isinstance(historical_state_sha256, str)
        or re.fullmatch(r"[0-9a-f]{64}", historical_state_sha256) is None
    ):
        raise CommandError(
            "recovered-public verification lacks historical purchase state"
        )
    capability = _issue_recovered_public_clearance_capability(
        recovery_root=run_card_path.parents[1],
        run_card_path=run_card_path,
        selection_path=selection_path,
        purchase_policy_path=purchase_policy_path,
        cohort_policy_path=cohort_policy_path,
        ledger_path=ledger_path,
        initialization_receipt_path=initialization_receipt_path,
        controlled_private_root=controlled_private_root,
        successor_history_recovery_root=successor_history_recovery_root,
        successor_history_controlled_private_root=(
            successor_history_controlled_private_root
        ),
        expected_manifest_path=expected_manifest_path,
        expected_restriction_path=expected_restriction_path,
        expected_case_relevance_path=expected_case_relevance_path,
        expected_review_requests_path=expected_review_requests_path,
        expected_document_root=expected_document_root,
    )
    if _materializer_record_index(
        list(_consume_recovered_public_clearance_capability(capability).values()),
        label="capability-authenticated recovered-public lineage",
    ) != _materializer_record_index(
        lineage_rows, label="recovered-public verification lineage"
    ):
        raise CommandError("recovered-public evidence changed during authentication")
    authority: dict[str, object] = {
        "kind": "verified_recap_fetch_recovery",
        "recovery_run_card": _file_commitment_from_bytes(run_card_path, run_card_bytes),
        "recovery_manifest_sha256": _bytes_sha256(
            verified_bytes[os.path.abspath(expected_manifest_path)]
        ),
        "recovery_restriction_evidence_sha256": _bytes_sha256(
            verified_bytes[os.path.abspath(expected_restriction_path)]
        ),
        "selection": _file_commitment_from_bytes(selection_path, selection_bytes),
        "purchase_policy": _file_commitment_from_bytes(
            purchase_policy_path, purchase_policy_bytes
        ),
        "purchase_ledger": {
            "path": str(ledger_path),
            "purchase_state_sha256": historical_state_sha256,
        },
        "purchase_ledger_initialization_receipt": _file_commitment_from_bytes(
            initialization_receipt_path, initialization_receipt_bytes
        ),
        "cohort_policy": _file_commitment_from_bytes(
            cohort_policy_path, cohort_policy_bytes
        ),
        "document_count": len(lineage_rows),
    }
    raw_history = recovery.get("authenticated_successor_history")
    history = (
        dict(cast(Mapping[str, object], raw_history))
        if isinstance(raw_history, Mapping)
        else None
    )
    if history is not None:
        raw_history_paths = history.get("source_paths")
        if not isinstance(raw_history_paths, tuple) or not all(
            isinstance(path, Path)
            for path in cast(tuple[object, ...], raw_history_paths)
        ):
            raise CommandError("successor history lacks exact source paths")
        history["source_bytes"] = {
            os.path.abspath(path): verified_bytes[os.path.abspath(path)]
            for path in cast(tuple[Path, ...], raw_history_paths)
        }
    return capability, authority, tuple(paths.values()), history


def _authenticated_successor_history_projection(
    authenticated_history: Mapping[str, object] | None,
    *,
    excluded_paths: Sequence[Path],
) -> tuple[dict[str, Path], dict[str, bytes], dict[str, object] | None]:
    """Project replay-authenticated successor history into exact card inputs."""

    if authenticated_history is None:
        return {}, {}, None
    if set(authenticated_history) != {
        "recovery_root",
        "initial_controlled_private_root",
        "controlled_private_root",
        "replayed_purchase_state_sha256",
        "source_paths",
        "source_bytes",
    }:
        raise CommandError("authenticated successor history fields differ")
    history_root = authenticated_history.get("recovery_root")
    history_private_root = authenticated_history.get("controlled_private_root")
    initial_private_root = authenticated_history.get("initial_controlled_private_root")
    history_state = authenticated_history.get("replayed_purchase_state_sha256")
    raw_history_paths = authenticated_history.get("source_paths")
    raw_history_bytes = authenticated_history.get("source_bytes")
    if (
        not isinstance(history_root, Path)
        or not isinstance(initial_private_root, Path)
        or not isinstance(history_private_root, Path)
        or not isinstance(history_state, str)
        or re.fullmatch(r"[0-9a-f]{64}", history_state) is None
        or not isinstance(raw_history_paths, tuple)
        or not all(
            isinstance(path, Path)
            for path in cast(tuple[object, ...], raw_history_paths)
        )
        or not isinstance(raw_history_bytes, Mapping)
    ):
        raise CommandError("authenticated successor history is invalid")
    excluded = {path.resolve() for path in excluded_paths}
    unique_history_paths = tuple(
        path
        for path in cast(tuple[Path, ...], raw_history_paths)
        if path.resolve() not in excluded
    )
    if not unique_history_paths or len(
        {path.resolve() for path in unique_history_paths}
    ) != len(unique_history_paths):
        raise CommandError(
            "authenticated successor history sources are empty or repeated"
        )
    history_paths: dict[str, Path] = {}
    history_bytes: dict[str, bytes] = {}
    for index, path in enumerate(unique_history_paths):
        name = f"successor_history_source_{index:04d}"
        payload = cast(Mapping[str, bytes], raw_history_bytes).get(
            os.path.abspath(path)
        )
        if not isinstance(payload, bytes):
            raise CommandError(
                "authenticated successor history lacks exact source bytes"
            )
        history_paths[name] = path
        history_bytes[name] = payload
    record: dict[str, object] = {
        "recovery_root": str(history_root.resolve()),
        "initial_controlled_private_root": str(initial_private_root.resolve()),
        "controlled_private_root": str(history_private_root.resolve()),
        "replayed_purchase_state_sha256": history_state,
        "source_names": list(history_paths),
    }
    return history_paths, history_bytes, record


def _cmd_acquisition_plan_disclosure_provenance(args: argparse.Namespace) -> int:
    stage = "plan-disclosure-provenance"
    output_root = _acquisition_output_root(args)
    requests_path = cast(Path, args.review_requests)
    manifest_path = cast(Path, args.download_manifest)
    relevance_path = cast(Path, args.case_relevance)
    restriction_path = cast(Path, args.restriction_evidence)
    document_root = cast(Path, args.document_root)
    plan_path = _acquisition_path(
        args, "routing_plan_output", output_root / "disclosure-provenance-plan.json"
    )
    worksheet_path = _acquisition_path(
        args,
        "exception_worksheet_output",
        output_root / "disclosure-exception-worksheet.json",
    )
    private_root = cast(Path, args.controlled_private_store_root)
    inspection_path = private_root / "private-document-inspection-map.jsonl"
    selected_schema = cast(str, args.schema_version)
    if selected_schema == "v2":
        plan_builder = build_provenance_clearance_plan
        worksheet_builder = exception_review_worksheet
        exception_count_field = "john_review_count"
    elif selected_schema == "v3":
        plan_builder = build_provenance_clearance_plan_v3
        worksheet_builder = exception_review_worksheet_v3
        exception_count_field = "exception_review_count"
    else:
        raise CommandError(
            "plan-disclosure-provenance requires --schema-version v2 or v3"
        )
    input_paths = (requests_path, manifest_path, relevance_path, restriction_path)
    committed_input_paths = tuple(path.resolve() for path in input_paths)
    committed_output_paths = (plan_path.resolve(), worksheet_path.resolve())
    _require_controlled_private_review_root(
        private_root,
        output_root=output_root,
        document_root=document_root,
        authenticated_inputs=input_paths,
    )
    _validate_disclosure_review_paths(
        input_paths=input_paths,
        output_paths=(plan_path, worksheet_path, inspection_path),
        protected_roots=(document_root,),
    )
    try:
        _reject_existing_parent_symlink(document_root, label="document root")
        if document_root.is_symlink() or not document_root.is_dir():
            raise CommandError(f"document root is missing or unsafe: {document_root}")
        source_bytes = {
            "review_requests": _read_singly_linked_regular_input(
                requests_path, label="review requests"
            ),
            "download_manifest": _read_singly_linked_regular_input(
                manifest_path, label="download manifest"
            ),
            "case_relevance": _read_singly_linked_regular_input(
                relevance_path, label="case relevance"
            ),
            "restriction_evidence": _read_singly_linked_regular_input(
                restriction_path, label="restriction evidence"
            ),
        }
        manifest_records = _projection_jsonl_records(
            source_bytes["download_manifest"], source=manifest_path
        )
        (
            verified_recovery_capability,
            recovered_public_authority,
            recovery_input_paths,
            authenticated_successor_history,
        ) = _verified_recovered_public_clearance_capability(
            args,
            expected_manifest_path=manifest_path,
            expected_restriction_path=restriction_path,
            expected_case_relevance_path=relevance_path,
            expected_review_requests_path=requests_path,
            expected_document_root=document_root,
        )
        (
            history_source_paths,
            history_source_bytes,
            history_run_card_record,
        ) = _authenticated_successor_history_projection(
            authenticated_successor_history,
            excluded_paths=(
                *input_paths,
                *recovery_input_paths,
                document_root,
            ),
        )
        if verified_recovery_capability is not None and selected_schema != "v3":
            raise ProvenanceClearanceError(
                "recovered-public verification requires --schema-version v3"
            )
        document_snapshot = _capture_provenance_document_snapshot(
            manifest_records, document_root=document_root
        )
        document_scanner = scan_disclosure_document
        if cast(bool, args.resume):
            scanner_source = plan_path if plan_path.is_file() else worksheet_path
            if scanner_source.is_file():
                frozen_scanner_artifact = _projection_json_object(
                    _read_singly_linked_regular_input(
                        scanner_source, label="scanner-version artifact"
                    ),
                    source=scanner_source,
                )
                document_scanner = document_scanner_for_plan(frozen_scanner_artifact)
            else:
                run_card_path, log_path = _disclosure_review_metadata_paths(
                    args, output_root=output_root, stage=stage
                )
                if run_card_path.exists() or log_path.exists():
                    raise ProvenanceClearanceError(
                        "resume requires a frozen routing plan or exception worksheet "
                        "to select the PDF scanner version"
                    )
        plan_kwargs: dict[str, object] = {}
        if verified_recovery_capability is not None:
            plan_kwargs["verified_recovery_capability"] = verified_recovery_capability
        plan = plan_builder(
            _projection_jsonl_records(
                source_bytes["review_requests"], source=requests_path
            ),
            manifest_records,
            _projection_jsonl_records(
                source_bytes["restriction_evidence"], source=restriction_path
            ),
            _projection_jsonl_records(
                source_bytes["case_relevance"], source=relevance_path
            ),
            document_root=document_root,
            review_requests_bytes=source_bytes["review_requests"],
            download_manifest_bytes=source_bytes["download_manifest"],
            restriction_evidence_bytes=source_bytes["restriction_evidence"],
            case_relevance_bytes=source_bytes["case_relevance"],
            document_bytes_by_relative_path=document_snapshot,
            document_scanner=document_scanner,
            **plan_kwargs,
        )
        worksheet = worksheet_builder(plan)
        inspection = build_exception_inspection_map(
            plan,
            document_root=document_root,
            document_bytes_by_relative_path=document_snapshot,
        )
        _require_provenance_document_snapshot_unchanged(
            document_snapshot, document_root=document_root
        )
    except (OSError, ProvenanceClearanceError) as exc:
        raise CommandError(str(exc)) from exc
    plan_bytes = canonical_json_bytes(plan)
    worksheet_bytes = canonical_json_bytes(worksheet)
    dry_run = _acquisition_dry_run(args)
    schema_log_extra: dict[str, object] | None = (
        {
            "routing_plan_schema_version": plan["schema_version"],
            "exception_worksheet_schema_version": worksheet["schema_version"],
        }
        if selected_schema == "v3"
        else None
    )
    source_commitments: dict[str, dict[str, object]] = {
        name: {
            "path": str(path.resolve()),
            "sha256": _bytes_sha256(source_bytes[name]),
        }
        for name, path in {
            "review_requests": requests_path,
            "download_manifest": manifest_path,
            "case_relevance": relevance_path,
            "restriction_evidence": restriction_path,
        }.items()
    }
    source_commitments.update(
        {
            name: {
                "path": str(path.resolve()),
                "sha256": _bytes_sha256(history_source_bytes[name]),
            }
            for name, path in history_source_paths.items()
        }
    )
    document_tree = _provenance_document_tree_from_snapshot(document_snapshot)
    source_commitments["document_root"] = {
        "path": str(document_root.resolve()),
        "tree_sha256": _canonical_json_sha256(document_tree),
        "document_count": len(document_tree),
    }
    if recovered_public_authority is not None:
        source_commitments["recovered_public_authority"] = recovered_public_authority
    output_commitments = (
        {}
        if dry_run
        else {
            "routing_plan": {
                "path": str(plan_path.resolve()),
                "sha256": _bytes_sha256(plan_bytes),
            },
            "exception_worksheet": {
                "path": str(worksheet_path.resolve()),
                "sha256": _bytes_sha256(worksheet_bytes),
            },
        }
    )
    completion_extra: dict[str, object] = {
        "auto_clear_count": plan["auto_clear_count"],
        exception_count_field: plan[exception_count_field],
        "source_commitments": source_commitments,
        "output_commitments": output_commitments,
        "private_inspection_map_written": not dry_run,
        "private_inspection_map_excluded_from_commitments": True,
    }
    if history_run_card_record is not None:
        completion_extra["authenticated_successor_history"] = history_run_card_record
    if selected_schema == "v3":
        completion_extra.update(cast(dict[str, object], schema_log_extra))
    terminal_metadata_present = _completed_disclosure_review_resume(
        args,
        stage=stage,
        input_paths=(
            *committed_input_paths,
            *(path.resolve() for path in history_source_paths.values()),
            *(path.resolve() for path in recovery_input_paths),
            document_root.resolve(),
        ),
        output_paths=committed_output_paths,
        record_count=cast(int, plan["document_count"]),
        expected_extra=completion_extra,
        expected_log_extra=schema_log_extra,
        repair_terminal_metadata=False,
        validate_without_resume=True,
    )
    if terminal_metadata_present and (dry_run or not cast(bool, args.resume)):
        raise CommandError(
            f"{stage} already has completed terminal metadata; use --execute --resume"
        )
    if not dry_run:
        (
            replayed_capability,
            replayed_authority,
            replayed_recovery_paths,
            replayed_history,
        ) = _verified_recovered_public_clearance_capability(
            args,
            expected_manifest_path=manifest_path,
            expected_restriction_path=restriction_path,
            expected_case_relevance_path=relevance_path,
            expected_review_requests_path=requests_path,
            expected_document_root=document_root,
        )
        (
            replayed_history_paths,
            replayed_history_bytes,
            replayed_history_record,
        ) = _authenticated_successor_history_projection(
            replayed_history,
            excluded_paths=(
                *input_paths,
                *replayed_recovery_paths,
                document_root,
            ),
        )
        capability_changed = bool(verified_recovery_capability) != bool(
            replayed_capability
        )
        if verified_recovery_capability is not None and replayed_capability is not None:
            capability_changed = capability_changed or (
                _consume_recovered_public_clearance_capability(
                    verified_recovery_capability
                )
                != _consume_recovered_public_clearance_capability(replayed_capability)
                or _consume_recovered_public_source_snapshots(
                    verified_recovery_capability
                )
                != _consume_recovered_public_source_snapshots(replayed_capability)
            )
        if (
            {name: path.resolve() for name, path in replayed_history_paths.items()}
            != {name: path.resolve() for name, path in history_source_paths.items()}
            or replayed_history_bytes != history_source_bytes
            or replayed_history_record != history_run_card_record
        ):
            raise CommandError(
                "successor history changed before disclosure-plan publication"
            )
        if (
            capability_changed
            or replayed_authority != recovered_public_authority
            or tuple(path.resolve() for path in replayed_recovery_paths)
            != tuple(path.resolve() for path in recovery_input_paths)
        ):
            raise CommandError(
                "recovered-public authority changed before disclosure-plan publication"
            )
        publication_snapshot = {
            path.resolve(): source_bytes[name]
            for name, path in {
                "review_requests": requests_path,
                "download_manifest": manifest_path,
                "case_relevance": relevance_path,
                "restriction_evidence": restriction_path,
            }.items()
        }
        if verified_recovery_capability is not None:
            for path, payload in _consume_recovered_public_source_snapshots(
                verified_recovery_capability
            ).items():
                key = path.resolve()
                existing = publication_snapshot.get(key)
                if existing is not None and existing != payload:
                    raise CommandError(
                        "recovered-public plan snapshots conflict before publication"
                    )
                publication_snapshot[key] = payload
        for name, path in history_source_paths.items():
            key = path.resolve()
            payload = history_source_bytes[name]
            existing = publication_snapshot.get(key)
            if existing is not None and existing != payload:
                raise CommandError(
                    "successor-history plan snapshots conflict before publication"
                )
            publication_snapshot[key] = payload
        _require_snapshot_unchanged(
            publication_snapshot,
            label="authenticated recovered-public disclosure plan",
        )
        _require_provenance_document_snapshot_unchanged(
            document_snapshot, document_root=document_root
        )
        _ensure_disclosure_review_artifact(
            plan_path, plan_bytes, resume=cast(bool, args.resume)
        )
        _ensure_disclosure_review_artifact(
            worksheet_path, worksheet_bytes, resume=cast(bool, args.resume)
        )
        _ensure_disclosure_review_artifact(
            inspection_path, inspection, resume=cast(bool, args.resume)
        )
    if terminal_metadata_present:
        if not _completed_disclosure_review_resume(
            args,
            stage=stage,
            input_paths=(
                *committed_input_paths,
                *(path.resolve() for path in history_source_paths.values()),
                *(path.resolve() for path in recovery_input_paths),
                document_root.resolve(),
            ),
            output_paths=committed_output_paths,
            record_count=cast(int, plan["document_count"]),
            expected_extra=completion_extra,
            expected_log_extra=schema_log_extra,
        ):
            raise CommandError(f"{stage} terminal resume state changed")
        return 0
    _write_acquisition_completion(
        args,
        stage=stage,
        input_paths=(
            *committed_input_paths,
            *(path.resolve() for path in history_source_paths.values()),
            *(path.resolve() for path in recovery_input_paths),
            document_root.resolve(),
        ),
        output_paths=committed_output_paths,
        record_count=cast(int, plan["document_count"]),
        dry_run=dry_run,
        paid_activity_requested=False,
        paid_activity_executed=False,
        extra=completion_extra,
        log_extra=schema_log_extra,
        log_schema_version=(
            _DISCLOSURE_PROVENANCE_STAGE_LOG_SCHEMA_VERSION
            if schema_log_extra
            else _ACQUISITION_STAGE_LOG_SCHEMA_VERSION
        ),
        resumable_terminal_metadata=True,
    )
    return 0


def _cmd_acquisition_clear_provenance_disclosures(
    args: argparse.Namespace,
) -> int:
    stage = "clear-disclosures"
    output_root = _acquisition_output_root(args)
    requests_path = cast(Path, args.review_requests)
    manifest_path = cast(Path, args.download_manifest)
    relevance_path = cast(Path, args.case_relevance)
    document_root = cast(Path, args.document_root)
    restriction_path = cast(Path, args.restriction_evidence)
    plan_path = cast(Path, args.routing_plan)
    worksheet_path = cast(Path, args.exception_worksheet)
    decisions_path = cast(Path, args.exception_decisions)
    recorder_card_path = cast(Path, args.exception_review_run_card)
    cohort_policy_path = cast(Path, args.cohort_policy)
    clearance_path = _acquisition_path(
        args, "clearance_output", output_root / "disclosure-clearance.jsonl"
    )
    quarantine_path = _acquisition_path(
        args, "quarantine_output", output_root / "disclosure-quarantine.jsonl"
    )
    source_paths = {
        "review_requests": requests_path,
        "download_manifest": manifest_path,
        "case_relevance": relevance_path,
        "restriction_evidence": restriction_path,
        "routing_plan": plan_path,
        "exception_worksheet": worksheet_path,
        "exception_decisions": decisions_path,
        "exception_review_run_card": recorder_card_path,
        "cohort_policy": cohort_policy_path,
    }
    _validate_disclosure_review_paths(
        input_paths=tuple(source_paths.values()),
        output_paths=(clearance_path, quarantine_path),
        protected_roots=(document_root,),
    )
    try:
        _reject_existing_parent_symlink(document_root, label="document root")
        if document_root.is_symlink() or not document_root.is_dir():
            raise CommandError(f"document root is missing or unsafe: {document_root}")
        source_bytes = {
            name: _read_singly_linked_regular_input(path, label=name.replace("_", " "))
            for name, path in source_paths.items()
        }
        manifest_records = _projection_jsonl_records(
            source_bytes["download_manifest"], source=manifest_path
        )
        document_snapshot = _capture_provenance_document_snapshot(
            manifest_records, document_root=document_root
        )
        frozen_plan = _projection_json_object(
            source_bytes["routing_plan"], source=plan_path
        )
        recomputed_plan = build_provenance_clearance_plan(
            _projection_jsonl_records(
                source_bytes["review_requests"], source=requests_path
            ),
            manifest_records,
            _projection_jsonl_records(
                source_bytes["restriction_evidence"], source=restriction_path
            ),
            _projection_jsonl_records(
                source_bytes["case_relevance"], source=relevance_path
            ),
            document_root=document_root,
            review_requests_bytes=source_bytes["review_requests"],
            download_manifest_bytes=source_bytes["download_manifest"],
            restriction_evidence_bytes=source_bytes["restriction_evidence"],
            case_relevance_bytes=source_bytes["case_relevance"],
            document_bytes_by_relative_path=document_snapshot,
            document_scanner=document_scanner_for_plan(frozen_plan),
        )
        plan_bytes = canonical_json_bytes(recomputed_plan)
        if plan_bytes != source_bytes["routing_plan"]:
            raise ProvenanceClearanceError(
                "routing plan differs from exact current inputs and document bytes"
            )
        worksheet = exception_review_worksheet(recomputed_plan)
        worksheet_bytes = canonical_json_bytes(worksheet)
        if worksheet_bytes != source_bytes["exception_worksheet"]:
            raise ProvenanceClearanceError(
                "exception worksheet differs from the immutable routing plan"
            )
        decisions = _projection_jsonl_records(
            source_bytes["exception_decisions"], source=decisions_path
        )
        recorder_card = _projection_json_object(
            source_bytes["exception_review_run_card"], source=recorder_card_path
        )
        _validate_provenance_exception_recorder(
            recorder_card,
            worksheet_path=worksheet_path,
            worksheet_bytes=worksheet_bytes,
            decisions_path=decisions_path,
            decisions_bytes=source_bytes["exception_decisions"],
            expected_count=cast(int, recomputed_plan["john_review_count"]),
            routing_plan_sha256=hashlib.sha256(plan_bytes).hexdigest(),
        )
        cohort_policy_sha256 = verify_cohort_policy(
            _projection_json_object(
                source_bytes["cohort_policy"], source=cohort_policy_path
            )
        )
        routing_plan_sha256 = hashlib.sha256(plan_bytes).hexdigest()
        records = build_provenance_clearance_records(
            recomputed_plan,
            decisions,
            routing_plan_sha256=routing_plan_sha256,
        )
        _require_provenance_document_snapshot_unchanged(
            document_snapshot, document_root=document_root
        )
    except (
        CohortPolicyError,
        DisclosureModelReviewAuthorityError,
        OSError,
        ProvenanceClearanceError,
    ) as exc:
        raise CommandError(str(exc)) from exc
    rows = [record.to_record() for record in records]
    quarantined = [row for row in rows if row["status"] != "cleared"]
    clearance_bytes = b"".join(canonical_json_bytes(row) for row in rows)
    quarantine_bytes = b"".join(canonical_json_bytes(row) for row in quarantined)
    dry_run = _acquisition_dry_run(args)
    if not dry_run:
        _ensure_disclosure_review_artifact(
            clearance_path, clearance_bytes, resume=cast(bool, args.resume)
        )
        _ensure_disclosure_review_artifact(
            quarantine_path, quarantine_bytes, resume=cast(bool, args.resume)
        )
    summary = cast(Mapping[str, object], recorder_card["human_batch_summary"])
    clearance_authority = {
        "kind": "provenance_first_with_john_exceptions",
        "authentication_claim": "interactive_hash_confirmation_only",
        "cohort_policy_sha256": "sha256:" + cohort_policy_sha256,
        "routing_plan_sha256": _bytes_sha256(plan_bytes),
        "review_worksheet_sha256": _bytes_sha256(worksheet_bytes),
        "exception_decisions_sha256": _bytes_sha256(
            source_bytes["exception_decisions"]
        ),
        "exception_review_run_card_sha256": _bytes_sha256(
            source_bytes["exception_review_run_card"]
        ),
        "exception_batch_confirmation_sha256": summary["confirmation_sha256"],
        "exception_reviewer_id": summary["intended_reviewer_id"],
        "auto_clear_count": recomputed_plan["auto_clear_count"],
        "john_review_count": recomputed_plan["john_review_count"],
    }
    source_commitments: dict[str, dict[str, object]] = {
        name: {"path": str(path.resolve()), "sha256": _bytes_sha256(source_bytes[name])}
        for name, path in source_paths.items()
    }
    document_tree = _provenance_document_tree_from_snapshot(document_snapshot)
    source_commitments["document_root"] = {
        "path": str(document_root.resolve()),
        "tree_sha256": _canonical_json_sha256(document_tree),
        "document_count": len(document_tree),
    }
    output_commitments = (
        {}
        if dry_run
        else {
            "disclosure_clearance": {
                "path": str(clearance_path.resolve()),
                "sha256": _bytes_sha256(clearance_bytes),
            },
            "disclosure_quarantine": {
                "path": str(quarantine_path.resolve()),
                "sha256": _bytes_sha256(quarantine_bytes),
            },
        }
    )
    completion_extra = {
        "quarantined_document_count": len(quarantined),
        "source_commitments": source_commitments,
        "output_commitments": output_commitments,
        "clearance_authority": clearance_authority,
    }
    if not dry_run and _completed_disclosure_review_resume(
        args,
        stage=stage,
        input_paths=(*tuple(source_paths.values()), document_root),
        output_paths=(clearance_path, quarantine_path),
        record_count=len(records),
        expected_extra=completion_extra,
    ):
        return 0
    _write_acquisition_completion(
        args,
        stage=stage,
        input_paths=(*tuple(source_paths.values()), document_root),
        output_paths=(clearance_path, quarantine_path),
        record_count=len(records),
        dry_run=dry_run,
        paid_activity_requested=False,
        paid_activity_executed=False,
        extra=completion_extra,
        resumable_terminal_metadata=True,
    )
    return 0


def _cmd_acquisition_model_disclosure_review(args: argparse.Namespace) -> int:
    """Publish projections from the frozen authenticated Gemini reviewer."""

    output_root = _acquisition_output_root(args)
    plan_path = cast(Path, args.routing_plan)
    worksheet_path = cast(Path, args.exception_worksheet)
    plan_run_card_path = cast(Path, args.plan_run_card)
    raw_document_root = cast(Path, args.document_root)
    raw_frozen_root = cast(Path, args.frozen_authority_root)
    raw_journal_path = cast(Path, args.provider_journal)
    raw_spend_path = cast(Path, args.provider_spend_authority)
    raw_private_root = cast(Path, args.controlled_private_store_root)
    for path, label in (
        (raw_document_root, "document root"),
        (raw_frozen_root, "frozen authority root"),
        (raw_journal_path, "provider journal"),
        (raw_spend_path, "provider spend authority"),
        (raw_private_root, "controlled private root"),
    ):
        _reject_existing_parent_symlink(path, label=label)
        if path.is_symlink():
            raise CommandError(f"{label} is a symlink: {path}")
    document_root = raw_document_root.resolve()
    frozen_root = raw_frozen_root.resolve()
    journal_path = raw_journal_path.resolve()
    spend_path = raw_spend_path.resolve()
    private_root = raw_private_root.resolve()
    authority_path = _acquisition_path(
        args,
        "authority_output",
        output_root / "disclosure-model-review-authority.json",
    )
    private_path = _acquisition_path(
        args,
        "private_records_output",
        private_root / "disclosure-model-review-private-records.json",
    )
    run_card_path = _acquisition_path(
        args,
        "run_card_output",
        output_root / "run-cards/review-disclosure-exceptions.json",
    )
    resolved_outputs = tuple(
        path.resolve() for path in (authority_path, private_path, run_card_path)
    )
    _validate_disclosure_review_paths(
        input_paths=(plan_path, worksheet_path, plan_run_card_path),
        output_paths=(authority_path, private_path, run_card_path),
        protected_roots=(document_root, frozen_root),
    )
    if journal_path == spend_path:
        raise CommandError("provider journal and spend authority must be distinct")
    if any(
        state_path
        in {plan_path.resolve(), worksheet_path.resolve(), plan_run_card_path.resolve()}
        for state_path in (journal_path, spend_path)
    ):
        raise CommandError("model-review provider state aliases a content input")
    if not private_path.resolve().is_relative_to(private_root):
        raise CommandError(
            "private model-review records must remain in the private root"
        )
    if any(
        output.is_relative_to(document_root)
        or output.is_relative_to(frozen_root)
        or document_root.is_relative_to(output)
        or frozen_root.is_relative_to(output)
        for output in (*resolved_outputs, journal_path, spend_path)
    ):
        raise CommandError(
            "model-review state or output overlaps a protected input root"
        )
    if any(output in {journal_path, spend_path} for output in resolved_outputs):
        raise CommandError("model-review output aliases provider state")
    try:
        plan_bytes = _read_singly_linked_regular_input(plan_path, label="routing plan")
        worksheet_bytes = _read_singly_linked_regular_input(
            worksheet_path, label="exception worksheet"
        )
        plan_run_card_bytes = _read_singly_linked_regular_input(
            plan_run_card_path, label="plan run card"
        )
        plan = _projection_json_object(plan_bytes, source=plan_path)
        worksheet = _projection_json_object(worksheet_bytes, source=worksheet_path)
        documents = validate_exception_review_worksheet_v3(
            worksheet,
            routing_plan=plan,
            routing_plan_bytes=plan_bytes,
            worksheet_bytes=worksheet_bytes,
        )
        raw_plan_documents = plan.get("documents")
        if not isinstance(raw_plan_documents, list) or not all(
            isinstance(document, Mapping)
            for document in cast(list[object], raw_plan_documents)
        ):
            raise ProvenanceClearanceError("v3 routing plan documents are malformed")
        document_snapshot = _capture_provenance_document_snapshot(
            cast(list[Mapping[str, Any]], raw_plan_documents),
            document_root=document_root,
        )
        document_map = _model_review_document_map(worksheet, document_snapshot)
        if set(document_map) != {
            (
                cast(str, document["candidate_id"]),
                cast(str, document["source_document_id"]),
            )
            for document in documents
        }:
            raise ProvenanceClearanceError(
                "model-review worksheet byte coverage changed after validation"
            )
        document_tree = _provenance_document_tree_from_snapshot(document_snapshot)
        _verify_model_review_plan_run_card(
            run_card_bytes=plan_run_card_bytes,
            run_card_path=plan_run_card_path,
            plan_path=plan_path,
            plan_bytes=plan_bytes,
            worksheet_path=worksheet_path,
            worksheet_bytes=worksheet_bytes,
            document_root=document_root,
            document_tree=document_tree,
        )
        _require_provenance_document_snapshot_unchanged(
            document_snapshot, document_root=document_root
        )
    except (OSError, ProvenanceClearanceError, ReviewBundleError) as exc:
        raise CommandError(str(exc)) from exc
    if _acquisition_dry_run(args):
        return 0
    try:
        capability = authenticate_disclosure_model_review(
            routing_plan=plan,
            routing_plan_bytes=plan_bytes,
            worksheet=worksheet,
            worksheet_bytes=worksheet_bytes,
            document_bytes_by_key=document_map,
            provider_journal_path=journal_path,
            provider_spend_authority_path=spend_path,
            source_root=frozen_root,
        )
        authority = public_disclosure_model_review_record(capability)
        private_records = private_disclosure_model_review_records(capability)
        _require_provenance_document_snapshot_unchanged(
            document_snapshot, document_root=document_root
        )
    except (
        DisclosureModelReviewAuthorityError,
        OSError,
        ProviderJournalError,
    ) as exc:
        raise CommandError(str(exc)) from exc
    authority_bytes = canonical_json_bytes(authority)
    private_bytes = canonical_json_bytes(list(private_records))
    provider_call_executed = disclosure_model_review_provider_call_executed(capability)
    run_card = {
        "schema_version": "legalforecast.disclosure_model_review_run_card.v1",
        "stage": "review-disclosure-exceptions",
        "status": "completed",
        "resume": True,
        "dry_run": False,
        "execute": True,
        "provider_activity_requested": True,
        "provider_activity_executed": True,
        "provider_call_executed_this_run": provider_call_executed,
        "paid_activity_requested": True,
        "paid_activity_executed": True,
        "record_count": authority["decision_count"],
        "source_commitments": {
            "routing_plan": {
                "path": str(plan_path.resolve()),
                "sha256": _bytes_sha256(plan_bytes),
            },
            "exception_worksheet": {
                "path": str(worksheet_path.resolve()),
                "sha256": _bytes_sha256(worksheet_bytes),
            },
            "plan_run_card": {
                "path": str(plan_run_card_path.resolve()),
                "sha256": _bytes_sha256(plan_run_card_bytes),
            },
            "document_root": {
                "path": str(document_root),
                "tree_sha256": _canonical_json_sha256(document_tree),
                "document_count": len(document_tree),
            },
        },
        "state_paths": {
            "provider_journal": str(journal_path),
            "provider_spend_authority": str(spend_path),
            "frozen_authority_root": str(frozen_root),
        },
        "model_review_authority": authority,
        "output_commitments": {
            "public_authority": {
                "path": str(authority_path.resolve()),
                "sha256": _bytes_sha256(authority_bytes),
            },
            "private_records": {
                "path": str(private_path.resolve()),
                "sha256": _bytes_sha256(private_bytes),
            },
        },
    }
    resume = cast(bool, args.resume)
    _ensure_disclosure_review_artifact(private_path, private_bytes, resume=resume)
    _ensure_disclosure_review_artifact(authority_path, authority_bytes, resume=resume)
    _ensure_disclosure_review_artifact(
        run_card_path, canonical_json_bytes(run_card), resume=resume
    )
    return 0


def _model_review_eligible_plan_documents(
    plan: Mapping[str, object],
) -> tuple[Mapping[str, object], ...]:
    raw_documents = plan.get("documents")
    if not isinstance(raw_documents, list) or not all(
        isinstance(document, Mapping) for document in cast(list[object], raw_documents)
    ):
        raise ProvenanceClearanceError("v3 routing plan documents are malformed")
    documents = tuple(
        cast(Mapping[str, object], document)
        for document in cast(list[object], raw_documents)
    )
    return model_review_eligible_documents(
        tuple(
            document
            for document in documents
            if document.get("route") == "exception_review"
        )
    )


def _verify_model_review_plan_run_card(
    *,
    run_card_bytes: bytes,
    run_card_path: Path,
    plan_path: Path,
    plan_bytes: bytes,
    worksheet_path: Path,
    worksheet_bytes: bytes,
    document_root: Path,
    document_tree: Mapping[str, str],
) -> None:
    """Bind paid model review to the exact completed disclosure plan."""

    run_card = _projection_json_object(run_card_bytes, source=run_card_path)
    expected_run_card_bytes = (
        json.dumps(dict(run_card), indent=2, sort_keys=True, allow_nan=False) + "\n"
    ).encode("utf-8")
    if run_card_bytes != expected_run_card_bytes:
        raise ProvenanceClearanceError(
            "model review plan run card does not use exact producer serialization"
        )
    if (
        run_card.get("schema_version") != "legalforecast.acquisition_run_card.v1"
        or run_card.get("stage") != "plan-disclosure-provenance"
        or run_card.get("status") != "completed"
        or run_card.get("dry_run") is not False
        or run_card.get("execute") is not True
        or run_card.get("paid_activity_requested") is not False
        or run_card.get("paid_activity_executed") is not False
        or run_card.get("output_paths")
        != [str(plan_path.resolve()), str(worksheet_path.resolve())]
    ):
        raise ProvenanceClearanceError(
            "model review requires the exact completed v3 plan run card"
        )
    raw_sources = run_card.get("source_commitments")
    raw_outputs = run_card.get("output_commitments")
    if not isinstance(raw_sources, Mapping) or not isinstance(raw_outputs, Mapping):
        raise ProvenanceClearanceError("model review plan run card lacks commitments")
    sources = cast(Mapping[str, object], raw_sources)
    outputs = cast(Mapping[str, object], raw_outputs)
    _validate_named_path_commitment(
        outputs,
        name="routing_plan",
        expected_path=plan_path,
        expected_sha256=_bytes_sha256(plan_bytes),
    )
    _validate_named_path_commitment(
        outputs,
        name="exception_worksheet",
        expected_path=worksheet_path,
        expected_sha256=_bytes_sha256(worksheet_bytes),
    )
    document_commitment = sources.get("document_root")
    if not isinstance(document_commitment, Mapping) or dict(
        cast(Mapping[str, object], document_commitment)
    ) != {
        "path": str(document_root.resolve()),
        "tree_sha256": _canonical_json_sha256(document_tree),
        "document_count": len(document_tree),
    }:
        raise ProvenanceClearanceError(
            "model review plan run card document commitment changed"
        )


def _verify_no_model_review_plan_run_card(
    *,
    run_card_bytes: bytes,
    run_card_path: Path,
    plan_path: Path,
    plan_bytes: bytes,
    worksheet_path: Path,
    worksheet_bytes: bytes,
    plan: Mapping[str, Any],
    worksheet: Mapping[str, object],
    source_paths: Mapping[str, Path],
    source_bytes: Mapping[str, bytes],
    document_root: Path,
    document_tree: Mapping[str, str],
    recovered_public_authority: Mapping[str, object] | None,
    recovery_input_paths: Sequence[Path],
    successor_history_source_paths: Mapping[str, Path],
    successor_history_source_bytes: Mapping[str, bytes],
    authenticated_successor_history: Mapping[str, object] | None,
) -> None:
    """Bind provider-free empty-review finalization to the exact completed plan."""

    run_card = _projection_json_object(run_card_bytes, source=run_card_path)
    expected_run_card_bytes = (
        json.dumps(dict(run_card), indent=2, sort_keys=True, allow_nan=False) + "\n"
    ).encode("utf-8")
    if run_card_bytes != expected_run_card_bytes:
        raise ProvenanceClearanceError(
            "no-model-review plan run card does not use exact producer serialization"
        )
    expected_fields = {
        "schema_version",
        "stage",
        "status",
        "dry_run",
        "execute",
        "resume",
        "record_count",
        "input_paths",
        "output_paths",
        "paid_activity_requested",
        "paid_activity_executed",
        "generated_at",
        "auto_clear_count",
        "exception_review_count",
        "source_commitments",
        "output_commitments",
        "private_inspection_map_written",
        "private_inspection_map_excluded_from_commitments",
        "routing_plan_schema_version",
        "exception_worksheet_schema_version",
    }
    if authenticated_successor_history is not None:
        expected_fields.add("authenticated_successor_history")
    generated_at = run_card.get("generated_at")
    try:
        generated_at_is_canonical = (
            isinstance(generated_at, str)
            and _iso_datetime(_parse_datetime(generated_at)) == generated_at
        )
    except ValueError:
        generated_at_is_canonical = False
    expected_input_paths = (
        [
            str(source_paths[name].resolve())
            for name in (
                "review_requests",
                "download_manifest",
                "case_relevance",
                "restriction_evidence",
            )
        ]
        + [str(path.resolve()) for path in successor_history_source_paths.values()]
        + [str(path.resolve()) for path in recovery_input_paths]
        + [str(document_root.resolve())]
    )
    if (
        set(run_card) != expected_fields
        or run_card.get("schema_version") != "legalforecast.acquisition_run_card.v1"
        or run_card.get("stage") != "plan-disclosure-provenance"
        or run_card.get("status") != "completed"
        or run_card.get("dry_run") is not False
        or run_card.get("execute") is not True
        or run_card.get("paid_activity_requested") is not False
        or run_card.get("paid_activity_executed") is not False
        or run_card.get("routing_plan_schema_version") != plan.get("schema_version")
        or run_card.get("exception_worksheet_schema_version")
        != worksheet.get("schema_version")
        or run_card.get("record_count") != plan.get("document_count")
        or run_card.get("auto_clear_count") != plan.get("auto_clear_count")
        or run_card.get("exception_review_count") != plan.get("exception_review_count")
        or run_card.get("private_inspection_map_written") is not True
        or run_card.get("private_inspection_map_excluded_from_commitments") is not True
        or type(run_card.get("resume")) is not bool
        or not generated_at_is_canonical
        or run_card.get("input_paths") != expected_input_paths
        or run_card.get("output_paths")
        != [str(plan_path.resolve()), str(worksheet_path.resolve())]
    ):
        raise ProvenanceClearanceError(
            "no-model-review finalization requires the exact completed v3 plan run card"
        )
    raw_sources = run_card.get("source_commitments")
    raw_outputs = run_card.get("output_commitments")
    if not isinstance(raw_sources, Mapping) or not isinstance(raw_outputs, Mapping):
        raise ProvenanceClearanceError(
            "no-model-review plan run card lacks exact commitments"
        )
    sources = cast(Mapping[str, object], raw_sources)
    outputs = cast(Mapping[str, object], raw_outputs)
    expected_source_names = {
        "review_requests",
        "download_manifest",
        "case_relevance",
        "restriction_evidence",
        "document_root",
    }
    if recovered_public_authority is not None:
        expected_source_names.add("recovered_public_authority")
    expected_source_names.update(successor_history_source_paths)
    if set(sources) != expected_source_names or set(outputs) != {
        "routing_plan",
        "exception_worksheet",
    }:
        raise ProvenanceClearanceError(
            "no-model-review plan run card commitments differ"
        )
    for name in (
        "review_requests",
        "download_manifest",
        "case_relevance",
        "restriction_evidence",
    ):
        _validate_named_path_commitment(
            sources,
            name=name,
            expected_path=source_paths[name],
            expected_sha256=_bytes_sha256(source_bytes[name]),
        )
    if bool(successor_history_source_paths) != bool(
        authenticated_successor_history
    ) or set(successor_history_source_paths) != set(successor_history_source_bytes):
        raise ProvenanceClearanceError(
            "no-model-review plan run card successor history differs"
        )
    for name, path in successor_history_source_paths.items():
        _validate_named_path_commitment(
            sources,
            name=name,
            expected_path=path,
            expected_sha256=_bytes_sha256(successor_history_source_bytes[name]),
        )
    if run_card.get("authenticated_successor_history") != (
        authenticated_successor_history
    ):
        raise ProvenanceClearanceError(
            "no-model-review plan run card successor history changed"
        )
    document_commitment = sources.get("document_root")
    if not isinstance(document_commitment, Mapping) or dict(
        cast(Mapping[str, object], document_commitment)
    ) != {
        "path": str(document_root.resolve()),
        "tree_sha256": _canonical_json_sha256(document_tree),
        "document_count": len(document_tree),
    }:
        raise ProvenanceClearanceError(
            "no-model-review plan run card document commitment changed"
        )
    if sources.get("recovered_public_authority") != recovered_public_authority:
        if recovered_public_authority is not None or (
            "recovered_public_authority" in sources
        ):
            raise ProvenanceClearanceError(
                "no-model-review plan run card recovery authority changed"
            )
    _validate_named_path_commitment(
        outputs,
        name="routing_plan",
        expected_path=plan_path,
        expected_sha256=_bytes_sha256(plan_bytes),
    )
    _validate_named_path_commitment(
        outputs,
        name="exception_worksheet",
        expected_path=worksheet_path,
        expected_sha256=_bytes_sha256(worksheet_bytes),
    )


def _cmd_acquisition_quarantine_provenance_exceptions(
    args: argparse.Namespace,
) -> int:
    """Finalize v3 routing by quarantining every exception without review."""

    output_root = _acquisition_output_root(args)
    requests_path = cast(Path, args.review_requests)
    manifest_path = cast(Path, args.download_manifest)
    relevance_path = cast(Path, args.case_relevance)
    document_root = cast(Path, args.document_root)
    restriction_path = cast(Path, args.restriction_evidence)
    plan_path = cast(Path, args.routing_plan)
    worksheet_path = cast(Path, args.exception_worksheet)
    cohort_policy_path = cast(Path, args.cohort_policy)
    plan_run_card_path = cast(Path | None, args.plan_run_card)
    public_marker_policy_path = cast(Path | None, args.public_marker_clearance_policy)
    public_marker_mode = public_marker_policy_path is not None
    successor_history_recovery_root = cast(
        Path | None, args.successor_history_recovery_root
    )
    successor_history_controlled_private_root = cast(
        Path | None, args.successor_history_controlled_private_root
    )
    successor_history_roots = (
        successor_history_recovery_root,
        successor_history_controlled_private_root,
    )
    require_no_model_review = cast(
        bool, args.require_no_model_review_eligible_exceptions
    )
    quarantine_all_without_review = cast(
        bool, args.quarantine_all_exceptions_without_review
    )
    clearance_path = _acquisition_path(
        args, "clearance_output", output_root / "disclosure-clearance.jsonl"
    )
    quarantine_path = _acquisition_path(
        args, "quarantine_output", output_root / "disclosure-quarantine.jsonl"
    )
    run_card_path = _acquisition_path(
        args,
        "run_card_output",
        output_root / "run-cards/finalize-provenance-quarantine.json",
    )
    source_paths = {
        "review_requests": requests_path,
        "download_manifest": manifest_path,
        "case_relevance": relevance_path,
        "restriction_evidence": restriction_path,
        "routing_plan": plan_path,
        "exception_worksheet": worksheet_path,
        "cohort_policy": cohort_policy_path,
    }
    model_argument_names = (
        "model_review_authority",
        "model_review_private_records",
        "model_review_run_card",
        "frozen_authority_root",
        "provider_journal",
        "provider_spend_authority",
    )
    model_values = tuple(
        cast(Path | None, getattr(args, name)) for name in model_argument_names
    )
    if (require_no_model_review or public_marker_mode) != (
        plan_run_card_path is not None
    ):
        raise CommandError(
            "--plan-run-card is required exactly with the authenticated empty-set "
            "or public-marker policy mode"
        )
    if require_no_model_review and public_marker_mode:
        raise CommandError(
            "public-marker policy and empty-eligible-set modes are mutually exclusive"
        )
    if any(path is not None for path in successor_history_roots) and not all(
        path is not None for path in successor_history_roots
    ):
        raise CommandError(
            "--successor-history-recovery-root and --successor-history-controlled-"
            "private-root must be supplied together"
        )
    if any(path is not None for path in successor_history_roots) and not (
        public_marker_mode and plan_run_card_path is not None
    ):
        raise CommandError(
            "successor history is accepted only for authenticated public-marker "
            "finalization"
        )
    if (require_no_model_review or public_marker_mode) and any(
        value is not None for value in model_values
    ):
        raise CommandError(
            "provider-free policy finalization cannot accept model-review arguments"
        )
    if quarantine_all_without_review and (
        require_no_model_review
        or public_marker_mode
        or any(value is not None for value in model_values)
    ):
        raise CommandError(
            "quarantine-all mode cannot be combined with model review or the "
            "authenticated empty-eligible-set continuation"
        )
    if any(value is not None for value in model_values) and not all(
        value is not None for value in model_values
    ):
        raise CommandError(
            "model-review finalization requires the complete authority argument set"
        )
    model_mode = all(value is not None for value in model_values)
    if (
        not model_mode
        and not require_no_model_review
        and not quarantine_all_without_review
        and not public_marker_mode
    ):
        raise CommandError(
            "finalization requires complete model authority, authenticated "
            "empty-eligible-set proof, public-marker policy, or "
            "--quarantine-all-exceptions-without-review"
        )
    if plan_run_card_path is not None:
        source_paths["plan_run_card"] = plan_run_card_path
    if public_marker_policy_path is not None:
        source_paths["public_marker_clearance_policy"] = public_marker_policy_path
    if model_mode:
        for name, value in zip(model_argument_names[:3], model_values[:3], strict=True):
            source_paths[name] = cast(Path, value)
        raw_frozen_root = cast(Path, args.frozen_authority_root)
        raw_journal_path = cast(Path, args.provider_journal)
        raw_spend_path = cast(Path, args.provider_spend_authority)
        _reject_existing_parent_symlink(raw_frozen_root, label="frozen authority root")
        if raw_frozen_root.is_symlink() or not raw_frozen_root.is_dir():
            raise CommandError("frozen authority root is missing or unsafe")
        frozen_root = raw_frozen_root.resolve()
        model_state_paths = (raw_journal_path, raw_spend_path)
    else:
        frozen_root = None
        model_state_paths = ()
    _validate_disclosure_review_paths(
        input_paths=(*tuple(source_paths.values()), *model_state_paths),
        output_paths=(clearance_path, quarantine_path, run_card_path),
        protected_roots=(document_root, *((frozen_root,) if frozen_root else ())),
    )
    try:
        _reject_existing_parent_symlink(document_root, label="document root")
        if document_root.is_symlink() or not document_root.is_dir():
            raise CommandError(f"document root is missing or unsafe: {document_root}")
        source_bytes = {
            name: _read_singly_linked_regular_input(path, label=name.replace("_", " "))
            for name, path in source_paths.items()
        }
        manifest_records = _projection_jsonl_records(
            source_bytes["download_manifest"], source=manifest_path
        )
        (
            verified_recovery_capability,
            recovered_public_authority,
            recovery_input_paths,
            authenticated_successor_history,
        ) = _verified_recovered_public_clearance_capability(
            args,
            expected_manifest_path=manifest_path,
            expected_restriction_path=restriction_path,
            expected_case_relevance_path=relevance_path,
            expected_review_requests_path=requests_path,
            expected_document_root=document_root,
        )
        (
            history_source_paths,
            history_source_bytes,
            history_run_card_record,
        ) = _authenticated_successor_history_projection(
            authenticated_successor_history,
            excluded_paths=(
                *source_paths.values(),
                *recovery_input_paths,
                document_root,
            ),
        )
        if authenticated_successor_history is None and any(
            path is not None for path in successor_history_roots
        ):
            raise CommandError("successor history verification did not authenticate")
        document_snapshot = _capture_provenance_document_snapshot(
            manifest_records, document_root=document_root
        )
        frozen_plan = _projection_json_object(
            source_bytes["routing_plan"], source=plan_path
        )
        recomputed_plan = build_provenance_clearance_plan_v3(
            _projection_jsonl_records(
                source_bytes["review_requests"], source=requests_path
            ),
            manifest_records,
            _projection_jsonl_records(
                source_bytes["restriction_evidence"], source=restriction_path
            ),
            _projection_jsonl_records(
                source_bytes["case_relevance"], source=relevance_path
            ),
            document_root=document_root,
            review_requests_bytes=source_bytes["review_requests"],
            download_manifest_bytes=source_bytes["download_manifest"],
            restriction_evidence_bytes=source_bytes["restriction_evidence"],
            case_relevance_bytes=source_bytes["case_relevance"],
            document_bytes_by_relative_path=document_snapshot,
            document_scanner=document_scanner_for_plan(frozen_plan),
            verified_recovery_capability=verified_recovery_capability,
        )
        plan_bytes = canonical_json_bytes(recomputed_plan)
        if plan_bytes != source_bytes["routing_plan"]:
            raise ProvenanceClearanceError(
                "v3 routing plan differs from exact current inputs and document bytes"
            )
        worksheet = exception_review_worksheet_v3(recomputed_plan)
        worksheet_bytes = canonical_json_bytes(worksheet)
        if worksheet_bytes != source_bytes["exception_worksheet"]:
            raise ProvenanceClearanceError(
                "v3 exception worksheet differs from the immutable routing plan"
            )
        cohort_policy_artifact = _projection_json_object(
            source_bytes["cohort_policy"], source=cohort_policy_path
        )
        cohort_policy_sha256 = verify_cohort_policy(cohort_policy_artifact)
        public_marker_policy = None
        if public_marker_mode:
            public_marker_policy_artifact = _projection_json_object(
                source_bytes["public_marker_clearance_policy"],
                source=public_marker_policy_path,
            )
            if source_bytes["public_marker_clearance_policy"] != canonical_json_bytes(
                public_marker_policy_artifact
            ):
                raise ProvenanceClearanceError(
                    "public-marker policy requires exact canonical serialization"
                )
            public_marker_policy = verify_public_marker_clearance_policy(
                public_marker_policy_artifact,
                cohort_policy_artifact=cohort_policy_artifact,
            )
        routing_plan_sha256 = hashlib.sha256(plan_bytes).hexdigest()
        no_model_review_eligible_count: int | None = None
        if require_no_model_review:
            eligible = _model_review_eligible_plan_documents(recomputed_plan)
            no_model_review_eligible_count = len(eligible)
            if eligible:
                raise ProvenanceClearanceError(
                    "provider-free no-review finalization found "
                    "model-review-eligible exceptions"
                )
            document_tree = _provenance_document_tree_from_snapshot(document_snapshot)
            _verify_no_model_review_plan_run_card(
                run_card_bytes=source_bytes["plan_run_card"],
                run_card_path=cast(Path, plan_run_card_path),
                plan_path=plan_path,
                plan_bytes=plan_bytes,
                worksheet_path=worksheet_path,
                worksheet_bytes=worksheet_bytes,
                plan=recomputed_plan,
                worksheet=worksheet,
                source_paths=source_paths,
                source_bytes=source_bytes,
                document_root=document_root,
                document_tree=document_tree,
                recovered_public_authority=recovered_public_authority,
                recovery_input_paths=recovery_input_paths,
                successor_history_source_paths=history_source_paths,
                successor_history_source_bytes=history_source_bytes,
                authenticated_successor_history=history_run_card_record,
            )
        if public_marker_mode:
            document_tree = _provenance_document_tree_from_snapshot(document_snapshot)
            _verify_no_model_review_plan_run_card(
                run_card_bytes=source_bytes["plan_run_card"],
                run_card_path=cast(Path, plan_run_card_path),
                plan_path=plan_path,
                plan_bytes=plan_bytes,
                worksheet_path=worksheet_path,
                worksheet_bytes=worksheet_bytes,
                plan=recomputed_plan,
                worksheet=worksheet,
                source_paths=source_paths,
                source_bytes=source_bytes,
                document_root=document_root,
                document_tree=document_tree,
                recovered_public_authority=recovered_public_authority,
                recovery_input_paths=recovery_input_paths,
                successor_history_source_paths=history_source_paths,
                successor_history_source_bytes=history_source_bytes,
                authenticated_successor_history=history_run_card_record,
            )
        if model_mode:
            model_run_card_path = cast(Path, args.model_review_run_card)
            model_run_card = _projection_json_object(
                source_bytes["model_review_run_card"], source=model_run_card_path
            )
            if (
                model_run_card.get("schema_version")
                != "legalforecast.disclosure_model_review_run_card.v1"
                or model_run_card.get("stage") != "review-disclosure-exceptions"
                or model_run_card.get("status") != "completed"
            ):
                raise ProvenanceClearanceError("model review run card is invalid")
            document_map = _model_review_document_map(worksheet, document_snapshot)
            capability = replay_authenticated_disclosure_model_review(
                routing_plan=recomputed_plan,
                routing_plan_bytes=plan_bytes,
                worksheet=worksheet,
                worksheet_bytes=worksheet_bytes,
                document_bytes_by_key=document_map,
                provider_journal_path=cast(Path, args.provider_journal),
                provider_spend_authority_path=cast(Path, args.provider_spend_authority),
                source_root=cast(Path, args.frozen_authority_root),
            )
            replayed_authority = public_disclosure_model_review_record(capability)
            replayed_private = private_disclosure_model_review_records(capability)
            if (
                canonical_json_bytes(replayed_authority)
                != source_bytes["model_review_authority"]
                or canonical_json_bytes(list(replayed_private))
                != source_bytes["model_review_private_records"]
                or model_run_card.get("model_review_authority") != replayed_authority
            ):
                raise ProvenanceClearanceError(
                    "model review projections differ from authenticated replay"
                )
            records = build_authenticated_model_provenance_clearance_records_v3(
                recomputed_plan,
                model_review_capability=capability,
                routing_plan_sha256=routing_plan_sha256,
            )
        elif public_marker_mode:
            records = build_provider_free_public_marker_records_v3(
                recomputed_plan,
                routing_plan_sha256=routing_plan_sha256,
            )
        else:
            records = build_provider_free_quarantine_records_v3(
                recomputed_plan,
                routing_plan_sha256=routing_plan_sha256,
            )
        _require_provenance_document_snapshot_unchanged(
            document_snapshot, document_root=document_root
        )
    except (
        CohortPolicyError,
        DisclosureModelReviewAuthorityError,
        OSError,
        ProvenanceClearanceError,
        PublicMarkerClearancePolicyError,
    ) as exc:
        raise CommandError(str(exc)) from exc

    rows = [record.to_record() for record in records]
    quarantined = [row for row in rows if row["status"] == "quarantined"]
    public_marker_clear_count = (
        len(records) - cast(int, recomputed_plan["auto_clear_count"]) - len(quarantined)
        if public_marker_mode
        else 0
    )
    clearance_bytes = b"".join(canonical_json_bytes(row) for row in rows)
    quarantine_bytes = b"".join(canonical_json_bytes(row) for row in quarantined)
    dry_run = _acquisition_dry_run(args)
    if dry_run:
        return 0
    finalizer_source_paths = {**source_paths, **history_source_paths}
    finalizer_source_bytes = {**source_bytes, **history_source_bytes}
    _validate_disclosure_review_paths(
        input_paths=tuple(finalizer_source_paths.values()),
        output_paths=(clearance_path, quarantine_path, run_card_path),
        protected_roots=(document_root,),
    )
    source_commitments: dict[str, dict[str, object]] = {
        name: {
            "path": str(path.resolve()),
            "sha256": _bytes_sha256(finalizer_source_bytes[name]),
        }
        for name, path in finalizer_source_paths.items()
    }
    document_tree = _provenance_document_tree_from_snapshot(document_snapshot)
    source_commitments["document_root"] = {
        "path": str(document_root.resolve()),
        "tree_sha256": _canonical_json_sha256(document_tree),
        "document_count": len(document_tree),
    }
    output_commitments = {
        "disclosure_clearance": {
            "path": str(clearance_path.resolve()),
            "sha256": _bytes_sha256(clearance_bytes),
        },
        "disclosure_quarantine": {
            "path": str(quarantine_path.resolve()),
            "sha256": _bytes_sha256(quarantine_bytes),
        },
    }
    run_card = {
        "schema_version": (
            "legalforecast.provenance_model_clearance_run_card.v1"
            if model_mode
            else "legalforecast.provenance_public_marker_clearance_run_card.v1"
            if public_marker_mode
            else "legalforecast.provenance_quarantine_clearance_run_card.v1"
        ),
        "stage": "finalize-provenance-quarantine",
        "status": "completed",
        **(
            {"resume": cast(bool, args.resume)}
            if model_mode or public_marker_mode
            else {}
        ),
        "dry_run": False,
        "execute": True,
        "provider_activity_requested": False,
        "provider_activity_executed": False,
        "human_review_requested": False,
        "human_review_executed": False,
        "paid_activity_requested": False,
        "paid_activity_executed": False,
        "record_count": len(records),
        "auto_clear_count": recomputed_plan["auto_clear_count"],
        "exception_quarantine_count": len(quarantined),
        **(
            {"public_marker_clear_count": public_marker_clear_count}
            if public_marker_mode
            else {}
        ),
        "input_paths": [
            str(path.resolve())
            for path in (
                *source_paths.values(),
                *history_source_paths.values(),
                *recovery_input_paths,
                document_root,
            )
        ],
        "source_commitments": source_commitments,
        "output_paths": [
            str(clearance_path.resolve()),
            str(quarantine_path.resolve()),
        ],
        "output_commitments": output_commitments,
        "disposition_policy": {
            "kind": (
                "v3_auto_clear_authenticated_model_else_quarantine"
                if model_mode
                else "v3_authenticated_recovered_public_markers_clear_else_quarantine"
                if public_marker_mode
                else (
                    "v3_auto_clear_no_model_eligible_else_quarantine"
                    if require_no_model_review
                    else "v3_auto_clear_else_quarantine"
                )
            ),
            "routing_plan_schema_version": recomputed_plan["schema_version"],
            "exception_worksheet_schema_version": worksheet["schema_version"],
            "clearance_schema_version": "legalforecast.disclosure_clearance.v1",
            "routing_plan_sha256": _bytes_sha256(plan_bytes),
            "exception_worksheet_sha256": _bytes_sha256(worksheet_bytes),
            "cohort_policy_sha256": "sha256:" + cohort_policy_sha256,
            "auto_clear_count": recomputed_plan["auto_clear_count"],
            "exception_quarantine_count": len(quarantined),
            **(
                {"public_marker_clear_count": public_marker_clear_count}
                if public_marker_mode
                else {}
            ),
            "human_or_model_override_permitted": model_mode,
            **(
                {
                    "public_marker_clearance_policy_schema_version": (
                        PUBLIC_MARKER_CLEARANCE_POLICY_SCHEMA_VERSION
                    ),
                    "public_marker_clearance_policy_sha256": (
                        "sha256:" + cast(Any, public_marker_policy).policy_sha256
                    ),
                    "markers_are_diagnostic_only": True,
                }
                if public_marker_mode
                else {}
            ),
        },
        **(
            {
                "model_review_eligible_exception_count": (
                    no_model_review_eligible_count
                ),
                "no_model_review_eligible_exceptions_required": True,
            }
            if require_no_model_review
            else {}
        ),
        **(
            {"quarantine_all_exceptions_without_review": True}
            if quarantine_all_without_review
            else {}
        ),
        **(
            {
                "model_review_state": {
                    "frozen_authority_root": str(
                        cast(Path, args.frozen_authority_root).resolve()
                    ),
                    "provider_journal": str(
                        cast(Path, args.provider_journal).resolve()
                    ),
                    "provider_spend_authority": str(
                        cast(Path, args.provider_spend_authority).resolve()
                    ),
                }
            }
            if model_mode
            else {}
        ),
        **(
            {"recovered_public_authority": recovered_public_authority}
            if recovered_public_authority is not None
            else {}
        ),
        **(
            {"authenticated_successor_history": history_run_card_record}
            if history_run_card_record is not None
            else {}
        ),
    }
    run_card_bytes = canonical_json_bytes(run_card)
    if history_source_paths:
        _require_snapshot_unchanged(
            {
                path: history_source_bytes[name]
                for name, path in history_source_paths.items()
            },
            label="authenticated successor history",
        )
    if run_card_path.exists() or run_card_path.is_symlink():
        if not cast(bool, args.resume):
            raise CommandError(
                "finalize-provenance-quarantine run card exists and --no-resume was set"
            )
        try:
            existing_run_card = read_unique_regular_file(run_card_path)
        except ReviewBundleError as exc:
            raise CommandError(
                "finalize-provenance-quarantine run card is unsafe"
            ) from exc
        if existing_run_card != run_card_bytes:
            raise CommandError(
                "finalize-provenance-quarantine resume metadata mismatch"
            )
    _ensure_disclosure_review_artifact(
        clearance_path, clearance_bytes, resume=cast(bool, args.resume)
    )
    _ensure_disclosure_review_artifact(
        quarantine_path, quarantine_bytes, resume=cast(bool, args.resume)
    )
    _ensure_disclosure_review_artifact(
        run_card_path, run_card_bytes, resume=cast(bool, args.resume)
    )
    return 0


def _validate_provenance_exception_recorder(
    run_card: Mapping[str, object],
    *,
    worksheet_path: Path,
    worksheet_bytes: bytes,
    decisions_path: Path,
    decisions_bytes: bytes,
    expected_count: int,
    routing_plan_sha256: str,
) -> None:
    if (
        run_card.get("schema_version") != "legalforecast.acquisition_run_card.v1"
        or run_card.get("stage") != "record-disclosure-review-decisions"
        or run_card.get("status") != "completed"
        or run_card.get("dry_run") is not False
        or run_card.get("execute") is not True
        or run_card.get("paid_activity_requested") is not False
        or run_card.get("paid_activity_executed") is not False
        or run_card.get("record_count") != expected_count
        or run_card.get("authentication_claim") != "interactive_hash_confirmation_only"
        or run_card.get("review_worksheet_sha256") != _bytes_sha256(worksheet_bytes)
        or run_card.get("routing_plan_sha256") != routing_plan_sha256
        or run_card.get("decisions_sha256") != _bytes_sha256(decisions_bytes)
    ):
        raise ProvenanceClearanceError(
            "exception decisions lack the exact interactive recorder run card"
        )
    raw_input_paths = run_card.get("input_paths")
    input_paths = (
        cast(list[object], raw_input_paths) if isinstance(raw_input_paths, list) else []
    )
    if (
        len(input_paths) != 2
        or input_paths[0] != str(worksheet_path)
        or not isinstance(input_paths[1], str)
    ):
        raise ProvenanceClearanceError("exception recorder worksheet path mismatch")
    if run_card.get("output_paths") != [str(decisions_path)]:
        raise ProvenanceClearanceError("exception recorder decision path mismatch")
    summary = run_card.get("human_batch_summary")
    if not isinstance(summary, Mapping) or (
        cast(Mapping[str, object], summary).get("document_count") != expected_count
        or cast(Mapping[str, object], summary).get("intended_reviewer_id")
        != "John Hughes"
    ):
        raise ProvenanceClearanceError("exception recorder summary is invalid")
    try:
        _validate_provenance_recorder_checkpoints(
            run_card,
            worksheet_path=worksheet_path,
            worksheet_bytes=worksheet_bytes,
            inspection_path=Path(input_paths[1]),
            decisions_bytes=decisions_bytes,
        )
    except (CommandError, OSError, ReviewBundleError) as exc:
        raise ProvenanceClearanceError(str(exc)) from exc


def _validate_provenance_recorder_checkpoints(
    run_card: Mapping[str, object],
    *,
    worksheet_path: Path,
    worksheet_bytes: bytes,
    inspection_path: Path,
    decisions_bytes: bytes,
) -> None:
    worksheet = _projection_json_object(worksheet_bytes, source=worksheet_path)
    raw_documents = worksheet.get("documents")
    if not isinstance(raw_documents, list):
        raise CommandError("provenance exception worksheet is malformed")
    documents: dict[tuple[str, str], Mapping[str, Any]] = {}
    for raw in cast(list[object], raw_documents):
        if not isinstance(raw, Mapping):
            raise CommandError("provenance exception worksheet is malformed")
        row = cast(Mapping[str, Any], raw)
        key = (
            _required_str(row, "candidate_id"),
            _required_str(row, "source_document_id"),
        )
        if key in documents:
            raise CommandError("provenance exception worksheet repeats a document")
        documents[key] = row
    inspection_bytes = read_unique_regular_file(inspection_path)
    inspection_rows = _projection_jsonl_records(
        inspection_bytes, source=inspection_path
    )
    inspections: dict[tuple[str, str], Mapping[str, Any]] = {}
    for row in inspection_rows:
        if set(row) != {
            "candidate_id",
            "source_document_id",
            "inspection_path",
            "sha256",
            "byte_count",
        }:
            raise CommandError("provenance inspection map is malformed")
        key = (
            _required_str(row, "candidate_id"),
            _required_str(row, "source_document_id"),
        )
        if key in inspections:
            raise CommandError("provenance inspection map repeats a document")
        inspections[key] = row
    if set(inspections) != set(documents):
        raise CommandError("provenance inspection map coverage mismatch")
    raw_checkpoint = run_card.get("private_progress_checkpoint")
    if not isinstance(raw_checkpoint, Mapping):
        raise CommandError("provenance recorder lacks checkpoint commitment")
    checkpoint = cast(Mapping[str, object], raw_checkpoint)
    config_path_text = checkpoint.get("config_path")
    progress_directory_text = checkpoint.get("progress_directory")
    if not isinstance(config_path_text, str) or not isinstance(
        progress_directory_text, str
    ):
        raise CommandError("provenance recorder checkpoint paths are invalid")
    config_path = Path(config_path_text)
    progress_directory = Path(progress_directory_text)
    progress_config: dict[str, object] = {
        "schema_version": "legalforecast.disclosure_review_progress_config.v1",
        "review_worksheet_sha256": _bytes_sha256(worksheet_bytes),
        "private_inspection_map_sha256": _bytes_sha256(inspection_bytes),
        "document_set_sha256": _required_str(worksheet, "document_set_sha256"),
        "document_count": len(documents),
        "intended_reviewer_id": "John Hughes",
    }
    config_bytes = read_unique_regular_file(config_path)
    if (
        config_bytes != canonical_json_bytes(progress_config)
        or checkpoint.get("config_sha256") != _bytes_sha256(config_bytes)
        or checkpoint.get("private_inspection_map_sha256")
        != _bytes_sha256(inspection_bytes)
        or checkpoint.get("completed_document_count") != len(documents)
        or checkpoint.get("progress_tree_sha256")
        != _disclosure_review_progress_tree_sha256(progress_directory)
    ):
        raise CommandError("provenance recorder checkpoint commitment mismatch")
    progress = _load_disclosure_review_progress(
        progress_directory,
        documents=documents,
        inspections=inspections,
        worksheet_bytes=worksheet_bytes,
        inspection_bytes=inspection_bytes,
        intended_reviewer_id="John Hughes",
    )
    if set(progress) != set(documents):
        raise CommandError("provenance recorder checkpoint coverage mismatch")
    if progress:
        expected_decisions, expected_summary = _decision_artifact_from_progress(
            progress
        )
    else:
        expected_decisions = b""
        expected_summary = {
            "document_count": 0,
            "cleared_count": 0,
            "quarantined_count": 0,
            "confirmation_sha256": "sha256:" + hashlib.sha256(b"").hexdigest(),
            "intended_reviewer_id": "John Hughes",
        }
    if (
        decisions_bytes != expected_decisions
        or run_card.get("human_batch_summary") != expected_summary
    ):
        raise CommandError("provenance decisions differ from committed checkpoints")


def _cmd_acquisition_prepare_disclosure_review(args: argparse.Namespace) -> int:
    stage = "prepare-disclosure-review"
    output_root = _acquisition_output_root(args)
    requests_path = cast(Path, args.review_requests)
    manifest_path = cast(Path, args.download_manifest)
    restriction_path = cast(Path, args.restriction_evidence)
    reviewer_policy_path = cast(Path, args.reviewer_policy)
    cohort_policy_path = cast(Path, args.cohort_policy)
    document_root = cast(Path, args.document_root)
    worksheet_path = _acquisition_path(
        args, "worksheet_output", output_root / "disclosure-review-worksheet.json"
    )
    private_root = cast(Path, args.controlled_private_store_root)
    inspection_path = private_root / "private-document-inspection-map.jsonl"
    run_card_path, log_path = _disclosure_review_metadata_paths(
        args, output_root=output_root, stage=stage
    )
    input_paths = (
        requests_path,
        manifest_path,
        restriction_path,
        reviewer_policy_path,
        cohort_policy_path,
    )
    _validate_disclosure_review_paths(
        input_paths=input_paths,
        output_paths=(worksheet_path, inspection_path, run_card_path, log_path),
        protected_roots=(document_root,),
    )
    if (
        output_root.resolve() == private_root.resolve()
        or output_root.resolve().is_relative_to(private_root.resolve())
        or private_root.resolve().is_relative_to(output_root.resolve())
    ):
        raise CommandError(
            "controlled private review store must be separate from acquisition output"
        )
    try:
        request_bytes = requests_path.read_bytes()
        manifest_bytes = manifest_path.read_bytes()
        restriction_bytes = restriction_path.read_bytes()
        reviewer_policy_bytes = reviewer_policy_path.read_bytes()
        disclosure_authority = load_main_disclosure_review_authority(
            _read_json_object(cohort_policy_path),
            reviewer_policy_bytes=reviewer_policy_bytes,
        )
        manifest = _read_records(manifest_path)
        worksheet = prepare_review_worksheet(
            _read_records(requests_path),
            manifest,
            _read_records(restriction_path),
            document_root=document_root,
            review_requests_bytes=request_bytes,
            download_manifest_bytes=manifest_bytes,
            restriction_evidence_bytes=restriction_bytes,
            disclosure_authority=disclosure_authority,
        )
        inspection = build_private_inspection_map(
            worksheet, manifest, document_root=document_root
        )
    except (DisclosureReviewAuthorityError, OSError, ReviewBundleError) as exc:
        raise CommandError(str(exc)) from exc
    if not _acquisition_dry_run(args):
        _ensure_disclosure_review_artifact(
            worksheet_path,
            canonical_json_bytes(worksheet),
            resume=cast(bool, args.resume),
        )
        _ensure_disclosure_review_artifact(
            inspection_path, inspection, resume=cast(bool, args.resume)
        )
        if _completed_disclosure_review_resume(
            args,
            stage=stage,
            input_paths=(*input_paths, document_root),
            output_paths=(worksheet_path,),
            record_count=cast(int, worksheet["document_count"]),
            expected_extra={
                "private_inspection_map_written": True,
                "private_inspection_map_excluded_from_commitments": True,
            },
        ):
            return 0
    _write_acquisition_completion(
        args,
        stage=stage,
        input_paths=(*input_paths, document_root),
        output_paths=(worksheet_path,),
        record_count=cast(int, worksheet["document_count"]),
        dry_run=_acquisition_dry_run(args),
        paid_activity_requested=False,
        paid_activity_executed=False,
        extra={
            "private_inspection_map_written": not _acquisition_dry_run(args),
            "private_inspection_map_excluded_from_commitments": True,
        },
        resumable_terminal_metadata=True,
    )
    return 0


def _cmd_acquisition_review_signer_preflight(args: argparse.Namespace) -> int:
    policy_path = cast(Path, args.reviewer_policy)
    cohort_policy_path = cast(Path, args.cohort_policy)
    try:
        policy_bytes = policy_path.read_bytes()
        disclosure_authority = load_main_disclosure_review_authority(
            _read_json_object(cohort_policy_path),
            reviewer_policy_bytes=policy_bytes,
        )
        policy = reviewer_policy_preflight(
            policy_bytes,
            expected_reviewer_policy_sha256=(
                disclosure_authority.reviewer_policy_sha256
            ),
        )
    except (DisclosureReviewAuthorityError, OSError, ReviewBundleError) as exc:
        raise CommandError(str(exc)) from exc
    statement_path = cast(Path | None, args.signing_statement)
    if statement_path is not None:
        statement = _read_json_object(statement_path)
        if (
            statement.get("schema_version")
            != "legalforecast.disclosure_review_statement.v1"
            or statement.get("reviewer_policy_sha256") != policy.sha256
            or statement.get("authenticated_reviewer_id") != policy.reviewer_id
            or statement.get("authentication_method") != "human_hardware_ssh_signature"
            or statement.get("cycle_id") != disclosure_authority.identity.cycle_id
            or statement.get("cohort_policy_sha256")
            != disclosure_authority.identity.cohort_policy_sha256
            or statement.get("eligibility_anchor")
            != disclosure_authority.identity.eligibility_anchor.isoformat()
            or statement.get("disclosure_authority_sha256")
            != disclosure_authority.authority_sha256
            or statement.get("ssh_public_key_fingerprint")
            != disclosure_authority.ssh_public_key_fingerprint
        ):
            raise CommandError(
                "signing statement differs from hardware reviewer policy"
            )
        summary = statement.get("decision_summary")
        if not isinstance(summary, Mapping):
            raise CommandError("signing statement lacks visible decision summary")
        print(
            json.dumps(
                {
                    "decision_artifact_sha256": statement.get(
                        "decision_artifact_sha256"
                    ),
                    "decision_confirmation_sha256": statement.get(
                        "decision_confirmation_sha256"
                    ),
                    "cleared_count": statement.get("cleared_count"),
                    "quarantined_count": statement.get("quarantined_count"),
                    "decision_summary": summary,
                },
                indent=2,
                sort_keys=True,
                allow_nan=False,
            )
        )
    return 0


def _cmd_acquisition_record_disclosure_review(args: argparse.Namespace) -> int:
    stage = "record-disclosure-review-decisions"
    output_root = _acquisition_output_root(args)
    private_root_argument = cast(Path, args.controlled_private_store_root)
    if not private_root_argument.is_absolute():
        raise CommandError("controlled private review store must be an absolute path")
    _reject_existing_parent_symlink(
        private_root_argument, label="controlled private root"
    )
    private_root = private_root_argument.resolve()
    worksheet_path = cast(Path, args.review_worksheet)
    inspection_path = cast(Path, args.private_inspection_map)
    lexical_inspection_path = Path(os.path.abspath(inspection_path))
    if lexical_inspection_path.parent != private_root:
        raise CommandError(
            "private inspection map must be the direct child of the controlled "
            "private root"
        )
    worksheet_parent = worksheet_path.resolve().parent
    if (
        private_root == worksheet_parent
        or private_root.is_relative_to(worksheet_parent)
        or worksheet_parent.is_relative_to(private_root)
    ):
        raise CommandError(
            "controlled private review store must be separate from the review "
            "worksheet tree"
        )
    intended_reviewer_id = cast(str, args.reviewer_id).strip()
    if not intended_reviewer_id:
        raise CommandError("--reviewer-id must not be empty")
    decisions_path = _acquisition_path(
        args, "decisions_output", private_root / "disclosure-review-decisions.jsonl"
    )
    checkpoint_root = cast(Path | None, args.checkpoint_dir) or (
        private_root / "checkpoints"
    )
    progress_directory = checkpoint_root / "documents"
    progress_config_path = (
        checkpoint_root / "disclosure-review-decisions.progress-config.json"
    )
    run_card_path, log_path = _disclosure_review_metadata_paths(
        args, output_root=output_root, stage=stage
    )
    for label, path in (
        ("--output-root", output_root),
        ("--private-inspection-map", inspection_path),
        ("--decisions-output", decisions_path),
        ("private progress checkpoint directory", progress_directory),
        ("private progress config", progress_config_path),
        ("--run-card-output", run_card_path),
        ("--log-output", log_path),
    ):
        resolved = path.resolve()
        if resolved != private_root and not resolved.is_relative_to(private_root):
            raise CommandError(
                f"{label} must remain inside the controlled private root"
            )
    _validate_disclosure_review_paths(
        input_paths=(worksheet_path, inspection_path),
        output_paths=(
            decisions_path,
            progress_config_path,
            run_card_path,
            log_path,
        ),
    )
    worksheet_bytes = _read_singly_linked_regular_input(
        worksheet_path, label="review worksheet"
    )
    try:
        inspection_bytes = read_unique_regular_file(inspection_path)
    except ReviewBundleError as exc:
        raise CommandError("private inspection map is unsafe") from exc
    worksheet = _projection_json_object(worksheet_bytes, source=worksheet_path)
    provenance_exception_review = (
        worksheet.get("schema_version") == PROVENANCE_EXCEPTION_WORKSHEET_SCHEMA_VERSION
    )
    if provenance_exception_review and intended_reviewer_id != "John Hughes":
        raise CommandError("provenance exception review requires reviewer John Hughes")
    raw_documents = worksheet.get("documents")
    if not isinstance(raw_documents, list) or (
        not raw_documents and not provenance_exception_review
    ):
        raise CommandError("review worksheet has no documents")
    if provenance_exception_review:
        try:
            typed_documents: list[object] = list(
                validate_exception_review_worksheet(worksheet)
            )
        except ProvenanceClearanceError as exc:
            raise CommandError(
                f"provenance exception worksheet is invalid: {exc}"
            ) from exc
    else:
        typed_documents = cast(list[object], raw_documents)
    documents: dict[tuple[str, str], Mapping[str, Any]] = {}
    for item in typed_documents:
        if not isinstance(item, Mapping):
            raise CommandError("review worksheet has a non-object document")
        row = cast(Mapping[str, Any], item)
        key = (
            _required_str(row, "candidate_id"),
            _required_str(row, "source_document_id"),
        )
        if key in documents:
            raise CommandError(f"review worksheet repeats a document: {key}")
        documents[key] = row
    try:
        inspection_text = inspection_bytes.decode("utf-8")
        inspection_rows: list[JsonRecord] = []
        for line_number, line in enumerate(inspection_text.splitlines(), start=1):
            if not line.strip():
                continue
            loaded = _loads_json(line)
            if not isinstance(loaded, Mapping):
                raise ValueError(
                    f"private inspection map:{line_number} must contain an object"
                )
            inspection_rows.append(dict(cast(Mapping[str, Any], loaded)))
    except (UnicodeError, ValueError) as exc:
        raise CommandError("private inspection map is malformed") from exc
    inspections: dict[tuple[str, str], Mapping[str, Any]] = {}
    inspection_fields = {
        "candidate_id",
        "source_document_id",
        "inspection_path",
        "sha256",
        "byte_count",
    }
    for row in inspection_rows:
        if set(row) != inspection_fields:
            raise CommandError("private inspection map has unexpected fields")
        key = (
            _required_str(row, "candidate_id"),
            _required_str(row, "source_document_id"),
        )
        if key in inspections:
            raise CommandError(f"private inspection map repeats a document: {key}")
        inspections[key] = row
    if len(documents) != len(typed_documents) or set(documents) != set(inspections):
        raise CommandError("private inspection map differs from review worksheet")
    progress_resolved = progress_directory.resolve()
    for key, inspection in inspections.items():
        inspection_document = Path(
            _required_str(inspection, "inspection_path")
        ).resolve()
        inspection_parent = inspection_document.parent
        if (
            progress_resolved == inspection_document
            or progress_resolved == inspection_parent
            or progress_resolved.is_relative_to(inspection_parent)
            or inspection_parent.is_relative_to(progress_resolved)
        ):
            raise CommandError(
                f"private checkpoint directory overlaps inspection bytes: {key}"
            )
    progress_config: dict[str, object] = {
        "schema_version": "legalforecast.disclosure_review_progress_config.v1",
        "review_worksheet_sha256": _bytes_sha256(worksheet_bytes),
        "private_inspection_map_sha256": _bytes_sha256(inspection_bytes),
        "document_set_sha256": _required_str(worksheet, "document_set_sha256"),
        "document_count": len(documents),
        "intended_reviewer_id": intended_reviewer_id,
    }
    progress_config_bytes = canonical_json_bytes(progress_config)
    if _acquisition_dry_run(args):
        _write_acquisition_completion(
            args,
            stage=stage,
            input_paths=(worksheet_path, inspection_path),
            output_paths=(decisions_path,),
            record_count=len(documents),
            dry_run=True,
            paid_activity_requested=False,
            paid_activity_executed=False,
        )
        return 0
    if provenance_exception_review and not documents:
        _reject_existing_parent_symlink(progress_directory)
        progress_directory.mkdir(parents=True, exist_ok=True)
        _ensure_disclosure_review_artifact(
            progress_config_path,
            progress_config_bytes,
            resume=cast(bool, args.resume),
        )
        empty_sha256 = hashlib.sha256(b"").hexdigest()
        decision_summary: dict[str, object] = {
            "document_count": 0,
            "cleared_count": 0,
            "quarantined_count": 0,
            "confirmation_sha256": "sha256:" + empty_sha256,
            "intended_reviewer_id": "John Hughes",
        }
        completion_extra = {
            "human_batch_summary": decision_summary,
            "decisions_sha256": _bytes_sha256(b""),
            "private_progress_checkpoint": {
                "config_sha256": _bytes_sha256(progress_config_bytes),
                "progress_tree_sha256": _disclosure_review_progress_tree_sha256(
                    progress_directory
                ),
                "completed_document_count": 0,
                "config_path": str(progress_config_path),
                "progress_directory": str(progress_directory),
                "private_inspection_map_sha256": _bytes_sha256(inspection_bytes),
            },
            "review_worksheet_sha256": _bytes_sha256(worksheet_bytes),
            "routing_plan_sha256": _required_str(worksheet, "routing_plan_sha256"),
            "authentication_claim": "interactive_hash_confirmation_only",
        }
        _ensure_disclosure_review_artifact(
            decisions_path, b"", resume=cast(bool, args.resume)
        )
        if _completed_disclosure_review_resume(
            args,
            stage=stage,
            input_paths=(worksheet_path, inspection_path),
            output_paths=(decisions_path,),
            record_count=0,
            expected_extra=completion_extra,
        ):
            return 0
        _write_acquisition_completion(
            args,
            stage=stage,
            input_paths=(worksheet_path, inspection_path),
            output_paths=(decisions_path,),
            record_count=0,
            dry_run=False,
            paid_activity_requested=False,
            paid_activity_executed=False,
            extra=completion_extra,
            resumable_terminal_metadata=True,
        )
        return 0
    if run_card_path.exists() and not decisions_path.exists():
        existing_card = _read_json_object(run_card_path)
        if existing_card.get("status") == "completed":
            raise CommandError("completed recorder metadata lacks decision artifact")
    if decisions_path.exists() and (run_card_path.exists() or log_path.exists()):
        decision_bytes = decisions_path.read_bytes()
        decisions = _read_records(decisions_path)
        decision_summary = _validate_interactive_review_decisions(decisions)
        _validate_recorded_decisions_against_review_inputs(
            decisions,
            documents=documents,
            inspections=inspections,
        )
        if (
            not progress_config_path.is_file()
            or progress_config_path.read_bytes() != progress_config_bytes
        ):
            raise CommandError("completed recorder progress config mismatch")
        completed_progress = _load_disclosure_review_progress(
            progress_directory,
            documents=documents,
            inspections=inspections,
            worksheet_bytes=worksheet_bytes,
            inspection_bytes=inspection_bytes,
            intended_reviewer_id=intended_reviewer_id,
        )
        if set(completed_progress) != set(documents):
            raise CommandError("completed recorder progress coverage mismatch")
        expected_decision_bytes, checkpoint_summary = _decision_artifact_from_progress(
            completed_progress
        )
        if decision_bytes != expected_decision_bytes or decision_summary != (
            checkpoint_summary
        ):
            raise CommandError(
                "completed decision artifact differs from private checkpoints"
            )
        completed_extra = {
            "human_batch_summary": checkpoint_summary,
            "decisions_sha256": _bytes_sha256(expected_decision_bytes),
            "private_progress_checkpoint": {
                "config_sha256": _bytes_sha256(progress_config_bytes),
                "progress_tree_sha256": _disclosure_review_progress_tree_sha256(
                    progress_directory
                ),
                "completed_document_count": len(decisions),
            },
        }
        if provenance_exception_review:
            completed_checkpoint = cast(
                dict[str, object], completed_extra["private_progress_checkpoint"]
            )
            completed_checkpoint.update(
                {
                    "config_path": str(progress_config_path),
                    "progress_directory": str(progress_directory),
                    "private_inspection_map_sha256": _bytes_sha256(inspection_bytes),
                }
            )
            completed_extra.update(
                {
                    "review_worksheet_sha256": _bytes_sha256(worksheet_bytes),
                    "routing_plan_sha256": _required_str(
                        worksheet, "routing_plan_sha256"
                    ),
                    "authentication_claim": "interactive_hash_confirmation_only",
                }
            )
        if _completed_disclosure_review_resume(
            args,
            stage=stage,
            input_paths=(worksheet_path, inspection_path),
            output_paths=(decisions_path,),
            record_count=len(decisions),
            expected_extra=completed_extra,
        ):
            return 0
        raise CommandError("completed decision artifact lacks exact terminal metadata")
    if not sys.stdin.isatty():
        raise CommandError(
            "interactive disclosure review UI requires a TTY and cannot be "
            "replaced by a hand-authored decision artifact"
        )
    _reject_existing_parent_symlink(progress_directory)
    if progress_directory.exists() and (
        progress_directory.is_symlink() or not progress_directory.is_dir()
    ):
        raise CommandError("private review checkpoint path is not a directory")
    if progress_directory.exists() and not progress_config_path.exists():
        raise CommandError("private review progress lacks its exact input config")
    _ensure_disclosure_review_artifact(
        progress_config_path,
        progress_config_bytes,
        resume=cast(bool, args.resume),
    )
    progress_by_key = _load_disclosure_review_progress(
        progress_directory,
        documents=documents,
        inspections=inspections,
        worksheet_bytes=worksheet_bytes,
        inspection_bytes=inspection_bytes,
        intended_reviewer_id=intended_reviewer_id,
    )
    decision_bases: list[dict[str, object]] = []
    for key in sorted(documents):
        document = documents[key]
        inspection = inspections[key]
        digest, inspection_display = _validate_private_review_inspection(
            key, document=document, inspection=inspection
        )
        prior = progress_by_key.get(key)
        if prior is not None:
            decision_bases.append(_decision_base_from_progress(prior))
            continue
        print(
            f"Review {key[0]}/{key[1]} at {inspection_display}\n"
            f"SHA-256: {digest}\n"
            f"Restriction: {document.get('restriction_status')}\n"
            f"Markers: {document.get('automated_markers')}",
            file=sys.stderr,
        )
        confirmed = input("Type the full inspected SHA-256: ").strip().lower()
        if confirmed != digest:
            raise CommandError(f"inspection hash confirmation mismatch: {key}")
        decision = input("Decision [cleared/quarantined]: ").strip().lower()
        if decision not in {"cleared", "quarantined"}:
            raise CommandError(f"invalid disclosure decision: {key}")
        markers = document.get("automated_markers")
        provenance_clearance_forbidden = (
            provenance_exception_review
            and document.get("human_clearance_permitted") is not True
        )
        legacy_clearance_forbidden = not provenance_exception_review and (
            markers != []
            or document.get("restriction_status") not in {"public", "redacted"}
        )
        if decision == "cleared" and (
            provenance_clearance_forbidden or legacy_clearance_forbidden
        ):
            raise CommandError(f"flagged document cannot be cleared: {key}")
        # The human decision applies to the bytes just inspected. Re-open and
        # rehash after the prompt so a concurrent replacement cannot be
        # checkpointed as though the reviewer saw the committed document.
        _validate_private_review_inspection(
            key, document=document, inspection=inspection
        )
        recorded_at = _iso_datetime(datetime.now(UTC))
        progress: dict[str, object] = {
            "schema_version": "legalforecast.disclosure_review_progress.v1",
            "candidate_id": key[0],
            "source_document_id": key[1],
            "worksheet_document_sha256": _canonical_json_sha256(document),
            "inspection_record_sha256": _canonical_json_sha256(inspection),
            "review_worksheet_sha256": _bytes_sha256(worksheet_bytes),
            "private_inspection_map_sha256": _bytes_sha256(inspection_bytes),
            "status": decision,
            "reviewed_at": recorded_at,
            "inspected_at": recorded_at,
            "inspected_sha256": digest,
            "recording_method": "interactive_review_cli",
            "intended_reviewer_id": intended_reviewer_id,
        }
        progress_checkpoint = _disclosure_review_progress_path(progress_directory, key)
        _ensure_disclosure_review_artifact(
            progress_checkpoint,
            canonical_json_bytes(progress),
            resume=cast(bool, args.resume),
        )
        decision_bases.append(_decision_base_from_progress(progress))
    # Final decisions are always re-derived from the durable checkpoint bytes,
    # never from the transient in-memory rows used while prompting.
    progress_by_key = _load_disclosure_review_progress(
        progress_directory,
        documents=documents,
        inspections=inspections,
        worksheet_bytes=worksheet_bytes,
        inspection_bytes=inspection_bytes,
        intended_reviewer_id=intended_reviewer_id,
    )
    if set(progress_by_key) != set(documents):
        raise CommandError("private disclosure review progress coverage mismatch")
    decision_bytes, decision_summary = _decision_artifact_from_progress(progress_by_key)
    confirmation_sha256 = cast(
        str, decision_summary["confirmation_sha256"]
    ).removeprefix("sha256:")
    cleared_count = cast(int, decision_summary["cleared_count"])
    quarantined_count = cast(int, decision_summary["quarantined_count"])
    confirmation = (
        f"CONFIRM {len(decision_bases)} {cleared_count} {quarantined_count} "
        f"{confirmation_sha256}"
    )
    print(
        "Batch summary: "
        f"documents={len(decision_bases)} cleared={cleared_count} "
        f"quarantined={quarantined_count} sha256={confirmation_sha256}",
        file=sys.stderr,
    )
    if input(f"Type exactly '{confirmation}': ").strip() != confirmation:
        raise CommandError("human batch confirmation mismatch")
    confirmed_progress = _load_disclosure_review_progress(
        progress_directory,
        documents=documents,
        inspections=inspections,
        worksheet_bytes=worksheet_bytes,
        inspection_bytes=inspection_bytes,
        intended_reviewer_id=intended_reviewer_id,
    )
    confirmed_decision_bytes, confirmed_summary = _decision_artifact_from_progress(
        confirmed_progress
    )
    if (
        confirmed_decision_bytes != decision_bytes
        or confirmed_summary != decision_summary
    ):
        raise CommandError("private checkpoints changed during batch confirmation")
    progress_by_key = confirmed_progress
    decision_bytes = confirmed_decision_bytes
    decision_count = len(progress_by_key)
    completion_extra = {
        "human_batch_summary": decision_summary,
        "decisions_sha256": _bytes_sha256(decision_bytes),
        "private_progress_checkpoint": {
            "config_sha256": _bytes_sha256(progress_config_bytes),
            "progress_tree_sha256": _disclosure_review_progress_tree_sha256(
                progress_directory
            ),
            "completed_document_count": decision_count,
        },
    }
    if provenance_exception_review:
        completion_checkpoint = cast(
            dict[str, object], completion_extra["private_progress_checkpoint"]
        )
        completion_checkpoint.update(
            {
                "config_path": str(progress_config_path),
                "progress_directory": str(progress_directory),
                "private_inspection_map_sha256": _bytes_sha256(inspection_bytes),
            }
        )
        completion_extra.update(
            {
                "review_worksheet_sha256": _bytes_sha256(worksheet_bytes),
                "routing_plan_sha256": _required_str(worksheet, "routing_plan_sha256"),
                "authentication_claim": "interactive_hash_confirmation_only",
            }
        )
    _ensure_disclosure_review_artifact(
        decisions_path, decision_bytes, resume=cast(bool, args.resume)
    )
    if _completed_disclosure_review_resume(
        args,
        stage=stage,
        input_paths=(worksheet_path, inspection_path),
        output_paths=(decisions_path,),
        record_count=decision_count,
        expected_extra=completion_extra,
    ):
        return 0
    _write_acquisition_completion(
        args,
        stage=stage,
        input_paths=(worksheet_path, inspection_path),
        output_paths=(decisions_path,),
        record_count=decision_count,
        dry_run=False,
        paid_activity_requested=False,
        paid_activity_executed=False,
        extra=completion_extra,
        resumable_terminal_metadata=True,
    )
    return 0


def _validate_private_review_inspection(
    key: tuple[str, str],
    *,
    document: Mapping[str, Any],
    inspection: Mapping[str, Any],
) -> tuple[str, str]:
    digest = _required_str(document, "sha256")
    if _required_str(inspection, "sha256") != digest or inspection.get(
        "byte_count"
    ) != document.get("byte_count"):
        raise CommandError(f"private inspection commitment mismatch: {key}")
    inspection_display = _required_str(inspection, "inspection_path")
    inspected_path = Path(inspection_display)
    try:
        inspected_bytes = read_unique_regular_file(inspected_path)
    except ReviewBundleError as exc:
        raise CommandError(f"private inspection bytes are unavailable: {key}") from exc
    if hashlib.sha256(inspected_bytes).hexdigest() != digest or len(
        inspected_bytes
    ) != document.get("byte_count"):
        raise CommandError(f"private inspection bytes changed: {key}")
    return digest, inspection_display


def _load_disclosure_review_progress(
    progress_directory: Path,
    *,
    documents: Mapping[tuple[str, str], Mapping[str, Any]],
    inspections: Mapping[tuple[str, str], Mapping[str, Any]],
    worksheet_bytes: bytes,
    inspection_bytes: bytes,
    intended_reviewer_id: str,
) -> dict[tuple[str, str], Mapping[str, Any]]:
    if not progress_directory.exists():
        return {}
    fields = {
        "schema_version",
        "candidate_id",
        "source_document_id",
        "worksheet_document_sha256",
        "inspection_record_sha256",
        "review_worksheet_sha256",
        "private_inspection_map_sha256",
        "status",
        "reviewed_at",
        "inspected_at",
        "inspected_sha256",
        "recording_method",
        "intended_reviewer_id",
    }
    progress_by_key: dict[tuple[str, str], Mapping[str, Any]] = {}
    checkpoint_paths = sorted(progress_directory.glob("*.json"))
    for checkpoint_path in checkpoint_paths:
        _recover_disclosure_review_publish_alias(checkpoint_path)
        try:
            checkpoint_bytes = read_unique_regular_file(checkpoint_path)
            loaded = _loads_json(checkpoint_bytes.decode("utf-8"))
        except (ReviewBundleError, UnicodeError, ValueError) as exc:
            raise CommandError(
                "private disclosure review checkpoint is unsafe"
            ) from exc
        if not isinstance(loaded, Mapping):
            raise CommandError("private disclosure review checkpoint is unsafe")
        row = dict(cast(Mapping[str, Any], loaded))
        canonical_checkpoint = canonical_json_bytes(row)
        try:
            checkpoint_bytes = read_unique_regular_file(checkpoint_path)
        except ReviewBundleError as exc:
            raise CommandError(
                "private disclosure review checkpoint is unsafe"
            ) from exc
        if checkpoint_bytes != canonical_checkpoint:
            raise CommandError("private disclosure review checkpoint is unsafe")
        key = (
            _required_str(row, "candidate_id"),
            _required_str(row, "source_document_id"),
        )
        if (
            set(row) != fields
            or row.get("schema_version")
            != "legalforecast.disclosure_review_progress.v1"
            or row.get("recording_method") != "interactive_review_cli"
            or row.get("intended_reviewer_id") != intended_reviewer_id
            or row.get("status") not in {"cleared", "quarantined"}
            or key not in documents
            or key in progress_by_key
            or row.get("worksheet_document_sha256")
            != _canonical_json_sha256(documents[key])
            or row.get("inspection_record_sha256")
            != _canonical_json_sha256(inspections[key])
            or row.get("review_worksheet_sha256") != _bytes_sha256(worksheet_bytes)
            or row.get("private_inspection_map_sha256")
            != _bytes_sha256(inspection_bytes)
            or row.get("inspected_sha256") != documents[key].get("sha256")
        ):
            raise CommandError("private disclosure review progress is invalid")
        if checkpoint_path != _disclosure_review_progress_path(progress_directory, key):
            raise CommandError("private disclosure review checkpoint name is invalid")
        _parse_datetime(_required_str(row, "reviewed_at"))
        _parse_datetime(_required_str(row, "inspected_at"))
        progress_by_key[key] = row
    if set(progress_directory.iterdir()) != set(checkpoint_paths):
        raise CommandError("private disclosure review checkpoint directory has junk")
    return progress_by_key


def _disclosure_review_progress_path(
    progress_directory: Path, key: tuple[str, str]
) -> Path:
    identity = canonical_json_bytes(
        {"candidate_id": key[0], "source_document_id": key[1]}
    )
    return progress_directory / f"{hashlib.sha256(identity).hexdigest()}.json"


def _disclosure_review_progress_tree_sha256(progress_directory: Path) -> str:
    records: list[dict[str, object]] = []
    for path in sorted(progress_directory.iterdir()):
        if path.suffix != ".json":
            continue
        try:
            payload = read_unique_regular_file(path)
        except ReviewBundleError as exc:
            raise CommandError(
                "private disclosure review checkpoint is unsafe"
            ) from exc
        records.append({"name": path.name, "sha256": _bytes_sha256(payload)})
    return _bytes_sha256(canonical_json_bytes(records))


def _decision_base_from_progress(progress: Mapping[str, Any]) -> dict[str, object]:
    return {
        name: progress[name]
        for name in (
            "candidate_id",
            "source_document_id",
            "status",
            "reviewed_at",
            "inspected_at",
            "inspected_sha256",
            "recording_method",
            "intended_reviewer_id",
        )
    }


def _decision_artifact_from_progress(
    progress_by_key: Mapping[tuple[str, str], Mapping[str, Any]],
) -> tuple[bytes, dict[str, object]]:
    """Derive the sole canonical decision artifact from durable checkpoints."""

    decision_bases = [
        _decision_base_from_progress(progress_by_key[key])
        for key in sorted(progress_by_key)
    ]
    confirmation_sha256 = hashlib.sha256(
        b"".join(canonical_json_bytes(row) for row in decision_bases)
    ).hexdigest()
    decisions = [
        {**row, "batch_confirmation_sha256": confirmation_sha256}
        for row in decision_bases
    ]
    reviewer_ids = {cast(str, row["intended_reviewer_id"]) for row in decision_bases}
    if not decisions or len(reviewer_ids) != 1:
        raise CommandError("private disclosure review progress reviewer mismatch")
    cleared_count = sum(row["status"] == "cleared" for row in decision_bases)
    return (
        b"".join(canonical_json_bytes(row) for row in decisions),
        {
            "document_count": len(decisions),
            "cleared_count": cleared_count,
            "quarantined_count": len(decisions) - cleared_count,
            "confirmation_sha256": "sha256:" + confirmation_sha256,
            "intended_reviewer_id": reviewer_ids.pop(),
        },
    )


def _validate_recorded_decisions_against_review_inputs(
    decisions: Sequence[Mapping[str, Any]],
    *,
    documents: Mapping[tuple[str, str], Mapping[str, Any]],
    inspections: Mapping[tuple[str, str], Mapping[str, Any]],
) -> None:
    index: dict[tuple[str, str], Mapping[str, Any]] = {}
    for decision in decisions:
        key = (
            _required_str(decision, "candidate_id"),
            _required_str(decision, "source_document_id"),
        )
        if key in index or key not in documents:
            raise CommandError("recorded disclosure decision coverage mismatch")
        _validate_private_review_inspection(
            key, document=documents[key], inspection=inspections[key]
        )
        if decision.get("inspected_sha256") != documents[key].get("sha256"):
            raise CommandError(f"recorded decision inspected wrong bytes: {key}")
        index[key] = decision
    if set(index) != set(documents):
        raise CommandError("recorded disclosure decision coverage mismatch")


def _cmd_acquisition_build_disclosure_review(args: argparse.Namespace) -> int:
    stage = "build-disclosure-review-bundle"
    output_root = _acquisition_output_root(args)
    worksheet_path = cast(Path, args.review_worksheet)
    decisions_path = cast(Path, args.decisions)
    policy_path = cast(Path, args.reviewer_policy)
    cohort_policy_path = cast(Path, args.cohort_policy)
    reviews_path = _acquisition_path(
        args, "reviews_output", output_root / "disclosure-reviews.jsonl"
    )
    statement_path = _acquisition_path(
        args,
        "signing_statement_output",
        output_root / "disclosure-review-signing-statement.json",
    )
    input_paths = (worksheet_path, decisions_path, policy_path, cohort_policy_path)
    run_card_path, log_path = _disclosure_review_metadata_paths(
        args, output_root=output_root, stage=stage
    )
    _validate_disclosure_review_paths(
        input_paths=input_paths,
        output_paths=(reviews_path, statement_path, run_card_path, log_path),
    )
    try:
        worksheet_bytes = worksheet_path.read_bytes()
        worksheet = _read_json_object(worksheet_path)
        policy_bytes = policy_path.read_bytes()
        disclosure_authority = load_main_disclosure_review_authority(
            _read_json_object(cohort_policy_path),
            reviewer_policy_bytes=policy_bytes,
        )
        policy = reviewer_policy_preflight(
            policy_bytes,
            expected_reviewer_policy_sha256=(
                disclosure_authority.reviewer_policy_sha256
            ),
        )
        controlled_store_uri = cast(str, args.controlled_store_uri)
        decision_bytes = decisions_path.read_bytes()
        decisions = _read_records(decisions_path)
        decision_summary = _validate_interactive_review_decisions(decisions)
        if decision_summary["intended_reviewer_id"] != policy.reviewer_id:
            raise ReviewBundleError("decision artifact has the wrong intended reviewer")
        review_bytes = build_review_artifact(
            worksheet,
            decisions,
            reviewer_id=policy.reviewer_id,
            controlled_store_uri=controlled_store_uri,
        )
        statement = build_signing_statement(
            review_bytes,
            decision_bytes,
            worksheet_bytes,
            worksheet,
            reviewer_policy=_read_json_object(policy_path),
            reviewer_policy_bytes=policy_bytes,
            disclosure_authority=disclosure_authority,
            controlled_store_uri=controlled_store_uri,
            authenticated_at=cast(str, args.authenticated_at),
        )
    except (DisclosureReviewAuthorityError, OSError, ReviewBundleError) as exc:
        raise CommandError(str(exc)) from exc
    if not _acquisition_dry_run(args):
        _ensure_disclosure_review_artifact(
            reviews_path, review_bytes, resume=cast(bool, args.resume)
        )
        _ensure_disclosure_review_artifact(
            statement_path,
            canonical_json_bytes(statement),
            resume=cast(bool, args.resume),
        )
        if _completed_disclosure_review_resume(
            args,
            stage=stage,
            input_paths=input_paths,
            output_paths=(reviews_path, statement_path),
            record_count=len(_read_records(decisions_path)),
            expected_extra={
                "human_batch_summary": decision_summary,
                "decisions_sha256": _bytes_sha256(decisions_path.read_bytes()),
            },
        ):
            return 0
    _write_acquisition_completion(
        args,
        stage=stage,
        input_paths=input_paths,
        output_paths=(reviews_path, statement_path),
        record_count=len(_read_records(decisions_path)),
        dry_run=_acquisition_dry_run(args),
        paid_activity_requested=False,
        paid_activity_executed=False,
        extra={
            "human_batch_summary": decision_summary,
            "decisions_sha256": _bytes_sha256(decisions_path.read_bytes()),
        },
        resumable_terminal_metadata=True,
    )
    return 0


def _cmd_acquisition_seal_disclosure_review(args: argparse.Namespace) -> int:
    stage = "seal-disclosure-review-bundle"
    output_root = _acquisition_output_root(args)
    request_path = cast(Path, args.review_requests)
    manifest_path = cast(Path, args.download_manifest)
    restriction_path = cast(Path, args.restriction_evidence)
    worksheet_path = cast(Path, args.review_worksheet)
    reviews_path = cast(Path, args.reviews)
    decisions_path = cast(Path, args.decisions)
    statement_path = cast(Path, args.signing_statement)
    signature_path = cast(Path, args.signature)
    policy_path = cast(Path, args.reviewer_policy)
    cohort_policy_path = cast(Path, args.cohort_policy)
    receipt_path = _acquisition_path(
        args,
        "review_receipt_output",
        output_root / "disclosure-review-receipt.json",
    )
    input_paths = (
        request_path,
        manifest_path,
        restriction_path,
        worksheet_path,
        reviews_path,
        decisions_path,
        statement_path,
        signature_path,
        policy_path,
        cohort_policy_path,
    )
    run_card_path, log_path = _disclosure_review_metadata_paths(
        args, output_root=output_root, stage=stage
    )
    _validate_disclosure_review_paths(
        input_paths=input_paths,
        output_paths=(receipt_path, run_card_path, log_path),
    )
    try:
        reviewer_policy_bytes = policy_path.read_bytes()
        disclosure_authority = load_main_disclosure_review_authority(
            _read_json_object(cohort_policy_path),
            reviewer_policy_bytes=reviewer_policy_bytes,
        )
        receipt = seal_review_receipt(
            reviews_path.read_bytes(),
            decisions_path.read_bytes(),
            worksheet_path.read_bytes(),
            _read_json_object(worksheet_path),
            _read_json_object(statement_path),
            signature_path.read_bytes(),
            reviewer_policy=_read_json_object(policy_path),
            reviewer_policy_bytes=reviewer_policy_bytes,
            disclosure_authority=disclosure_authority,
            review_requests_bytes=request_path.read_bytes(),
            download_manifest_bytes=manifest_path.read_bytes(),
            restriction_evidence_bytes=restriction_path.read_bytes(),
        )
    except (DisclosureReviewAuthorityError, OSError, ReviewBundleError) as exc:
        raise CommandError(str(exc)) from exc
    if not _acquisition_dry_run(args):
        _ensure_disclosure_review_artifact(
            receipt_path,
            canonical_json_bytes(receipt),
            resume=cast(bool, args.resume),
        )
        if _completed_disclosure_review_resume(
            args,
            stage=stage,
            input_paths=input_paths,
            output_paths=(receipt_path,),
            record_count=cast(int, _read_json_object(statement_path)["document_count"]),
        ):
            return 0
    _write_acquisition_completion(
        args,
        stage=stage,
        input_paths=input_paths,
        output_paths=(receipt_path,),
        record_count=cast(int, _read_json_object(statement_path)["document_count"]),
        dry_run=_acquisition_dry_run(args),
        paid_activity_requested=False,
        paid_activity_executed=False,
        resumable_terminal_metadata=True,
    )
    return 0


def _cmd_acquisition_disclosure_clearance(args: argparse.Namespace) -> int:
    stage = "clear-disclosures"
    output_root = _acquisition_output_root(args)
    requests_path = cast(Path, args.review_requests)
    manifest_path = cast(Path, args.download_manifest)
    document_root = cast(Path, args.document_root)
    worksheet_path = cast(Path, args.review_worksheet)
    reviews_path = cast(Path, args.reviews)
    review_receipt_path = cast(Path, args.review_receipt)
    reviewer_policy_path = cast(Path, args.reviewer_policy)
    cohort_policy_path = cast(Path, args.cohort_policy)
    restriction_path = cast(Path, args.restriction_evidence)
    clearance_path = _acquisition_path(
        args, "clearance_output", output_root / "disclosure-clearance.jsonl"
    )
    quarantine_path = _acquisition_path(
        args, "quarantine_output", output_root / "disclosure-quarantine.jsonl"
    )
    source_paths = (
        manifest_path,
        requests_path,
        worksheet_path,
        reviews_path,
        review_receipt_path,
        reviewer_policy_path,
        cohort_policy_path,
        restriction_path,
    )
    run_card_path, log_path = _disclosure_review_metadata_paths(
        args, output_root=output_root, stage=stage
    )
    _validate_disclosure_review_paths(
        input_paths=source_paths,
        output_paths=(clearance_path, quarantine_path, run_card_path, log_path),
        protected_roots=(document_root,),
    )
    documents = _read_records(manifest_path)
    reviews = _read_records(reviews_path)
    restrictions = _read_records(restriction_path)
    try:
        requests_bytes = requests_path.read_bytes()
        manifest_bytes = manifest_path.read_bytes()
        restriction_bytes = restriction_path.read_bytes()
        reviewer_policy_bytes = reviewer_policy_path.read_bytes()
        disclosure_authority = load_main_disclosure_review_authority(
            _read_json_object(cohort_policy_path),
            reviewer_policy_bytes=reviewer_policy_bytes,
        )
        recomputed_worksheet = prepare_review_worksheet(
            _read_records(requests_path),
            documents,
            restrictions,
            document_root=document_root,
            review_requests_bytes=requests_bytes,
            download_manifest_bytes=manifest_bytes,
            restriction_evidence_bytes=restriction_bytes,
            disclosure_authority=disclosure_authority,
        )
        worksheet_bytes = worksheet_path.read_bytes()
        if canonical_json_bytes(recomputed_worksheet) != worksheet_bytes:
            raise ReviewBundleError(
                "signed review worksheet differs from exact current "
                "input/document bytes"
            )
        review_authority = validate_review_receipt(
            reviews_path.read_bytes(),
            _read_json_object(review_receipt_path),
            reviewer_policy_bytes=reviewer_policy_bytes,
            disclosure_authority=disclosure_authority,
            worksheet_bytes=worksheet_bytes,
            worksheet=recomputed_worksheet,
            review_requests_bytes=requests_bytes,
            download_manifest_bytes=manifest_bytes,
            restriction_evidence_bytes=restriction_bytes,
        )
        records = build_clearance_records(
            documents,
            document_root=document_root,
            reviews=reviews,
            review_authority=review_authority,
            restriction_records=restrictions,
        )
    except (
        DisclosureClearanceError,
        DisclosureReviewAuthorityError,
        OSError,
        ReviewBundleError,
    ) as exc:
        raise CommandError(str(exc)) from exc
    clearance_rows = [record.to_record() for record in records]
    quarantined = [row for row in clearance_rows if row["status"] != "cleared"]
    dry_run = _acquisition_dry_run(args)
    if not dry_run:
        clearance_bytes = b"".join(canonical_json_bytes(row) for row in clearance_rows)
        quarantine_bytes = b"".join(canonical_json_bytes(row) for row in quarantined)
        _ensure_disclosure_review_artifact(
            clearance_path, clearance_bytes, resume=cast(bool, args.resume)
        )
        _ensure_disclosure_review_artifact(
            quarantine_path, quarantine_bytes, resume=cast(bool, args.resume)
        )
    source_commitments = {
        "download_manifest": {
            "path": str(manifest_path.resolve()),
            "sha256": _path_sha256(manifest_path),
        },
        "review_requests": {
            "path": str(requests_path.resolve()),
            "sha256": _path_sha256(requests_path),
        },
        "review_worksheet": {
            "path": str(worksheet_path.resolve()),
            "sha256": _path_sha256(worksheet_path),
        },
        "reviews": {
            "path": str(reviews_path.resolve()),
            "sha256": _path_sha256(reviews_path),
        },
        "review_receipt": {
            "path": str(review_receipt_path.resolve()),
            "sha256": _path_sha256(review_receipt_path),
        },
        "reviewer_policy": {
            "path": str(reviewer_policy_path.resolve()),
            "sha256": _path_sha256(reviewer_policy_path),
        },
        "cohort_policy": {
            "path": str(cohort_policy_path.resolve()),
            "sha256": _path_sha256(cohort_policy_path),
        },
        "restriction_evidence": {
            "path": str(restriction_path.resolve()),
            "sha256": _path_sha256(restriction_path),
        },
    }
    output_commitments = (
        {}
        if dry_run
        else {
            "disclosure_clearance": {
                "path": str(clearance_path.resolve()),
                "sha256": _path_sha256(clearance_path),
            },
            "disclosure_quarantine": {
                "path": str(quarantine_path.resolve()),
                "sha256": _path_sha256(quarantine_path),
            },
        }
    )
    completion_inputs = (*source_paths, document_root)
    if not dry_run and _completed_disclosure_review_resume(
        args,
        stage=stage,
        input_paths=completion_inputs,
        output_paths=(clearance_path, quarantine_path),
        record_count=len(records),
        expected_extra={
            "quarantined_document_count": len(quarantined),
            "source_commitments": source_commitments,
            "output_commitments": output_commitments,
            "review_authority": _clearance_review_authority_record(
                review_authority, disclosure_authority
            ),
        },
    ):
        return 0
    _write_acquisition_completion(
        args,
        stage=stage,
        input_paths=completion_inputs,
        output_paths=(clearance_path, quarantine_path),
        record_count=len(records),
        dry_run=dry_run,
        paid_activity_requested=False,
        paid_activity_executed=False,
        extra={
            "quarantined_document_count": len(quarantined),
            "source_commitments": source_commitments,
            "output_commitments": output_commitments,
            "review_authority": _clearance_review_authority_record(
                review_authority, disclosure_authority
            ),
        },
    )
    return 0


def _clearance_review_authority_record(
    review_authority: ReviewAuthority,
    disclosure_authority: DisclosureReviewAuthority,
) -> dict[str, str]:
    """Bind receipt identity to the independently main-pinned authority."""

    return {
        "reviewer_id": review_authority.reviewer_id,
        "controlled_store_uri": review_authority.controlled_store_uri,
        "authentication_method": review_authority.authentication_method,
        "authenticated_at": review_authority.authenticated_at,
        "review_artifact_sha256": ("sha256:" + review_authority.review_artifact_sha256),
        "reviewer_policy_sha256": ("sha256:" + review_authority.reviewer_policy_sha256),
        "cycle_id": disclosure_authority.identity.cycle_id,
        "cohort_policy_sha256": (
            "sha256:" + disclosure_authority.identity.cohort_policy_sha256
        ),
        "eligibility_anchor": (
            disclosure_authority.identity.eligibility_anchor.isoformat()
        ),
        "disclosure_authority_sha256": (
            "sha256:" + disclosure_authority.authority_sha256
        ),
        "ssh_public_key_fingerprint": (disclosure_authority.ssh_public_key_fingerprint),
    }


def _validate_interactive_review_decisions(
    decisions: Sequence[Mapping[str, Any]],
) -> dict[str, object]:
    """Require the supported private interactive recorder's exact artifact."""

    if not decisions:
        raise ReviewBundleError("interactive decision artifact is empty")
    fields = {
        "candidate_id",
        "source_document_id",
        "status",
        "reviewed_at",
        "inspected_at",
        "inspected_sha256",
        "recording_method",
        "intended_reviewer_id",
        "batch_confirmation_sha256",
    }
    base_rows: list[dict[str, object]] = []
    pins: set[str] = set()
    for row in decisions:
        if set(row) != fields or row.get("recording_method") != (
            "interactive_review_cli"
        ):
            raise ReviewBundleError(
                "decisions must come from record-disclosure-review-decisions"
            )
        pin = _required_str(row, "batch_confirmation_sha256")
        if not re.fullmatch(r"[0-9a-f]{64}", pin):
            raise ReviewBundleError("decision batch confirmation is malformed")
        pins.add(pin)
        base_rows.append(
            {
                name: value
                for name, value in row.items()
                if name != "batch_confirmation_sha256"
            }
        )
    expected = hashlib.sha256(
        b"".join(canonical_json_bytes(row) for row in base_rows)
    ).hexdigest()
    if pins != {expected}:
        raise ReviewBundleError("decision batch confirmation hash mismatch")
    cleared = sum(row.get("status") == "cleared" for row in decisions)
    reviewer_ids = {_required_str(row, "intended_reviewer_id") for row in decisions}
    if len(reviewer_ids) != 1:
        raise ReviewBundleError("decision artifact has conflicting reviewer IDs")
    return {
        "document_count": len(decisions),
        "cleared_count": cleared,
        "quarantined_count": len(decisions) - cleared,
        "confirmation_sha256": "sha256:" + expected,
        "intended_reviewer_id": next(iter(reviewer_ids)),
    }


def _authenticated_clearance_lineage_inputs(
    args: argparse.Namespace,
    *,
    clearance_path: Path,
) -> tuple[dict[str, Any], tuple[Path, ...]]:
    clearance_run_card_path = cast(Path | None, args.clearance_run_card)
    restriction_path = cast(Path | None, args.restriction_evidence)
    if clearance_run_card_path is not None:
        run_card_bytes = _read_singly_linked_regular_input(
            clearance_run_card_path, label="clearance run card"
        )
        run_card = _projection_json_object(
            run_card_bytes, source=clearance_run_card_path
        )
        authority = run_card.get("clearance_authority")
        authority_kind = (
            cast(Mapping[str, object], authority).get("kind")
            if isinstance(authority, Mapping)
            else None
        )
        provider_free_run_card = run_card.get("schema_version") in {
            "legalforecast.provenance_quarantine_clearance_run_card.v1",
            "legalforecast.provenance_public_marker_clearance_run_card.v1",
        }
        if (
            authority_kind == "provenance_first_with_john_exceptions"
            or provider_free_run_card
        ):
            clearance_snapshot = _capture_clearance_artifact_snapshot(
                run_card=run_card,
                run_card_path=clearance_run_card_path,
                clearance_path=clearance_path,
                initial_artifact_bytes={
                    os.path.abspath(clearance_run_card_path): run_card_bytes,
                    os.path.abspath(clearance_path): _read_singly_linked_regular_input(
                        clearance_path, label="disclosure clearance"
                    ),
                },
            )
            sources = run_card.get("source_commitments")
            if not isinstance(sources, Mapping):
                raise ResolvedPostRecoveryError(
                    "provenance clearance lacks source commitments"
                )
            manifest_path = _materializer_committed_path(
                cast(Mapping[str, object], sources),
                "download_manifest",
                captured_artifact_bytes=clearance_snapshot,
            )
            lineage = _verify_materializer_clearance_lineage(
                manifest_path=manifest_path,
                clearance_path=clearance_path,
                run_card_path=clearance_run_card_path,
                captured_artifact_bytes=clearance_snapshot,
            )
            if (
                restriction_path is not None
                and cast(Path, lineage["restriction_path"]).resolve()
                != restriction_path.resolve()
            ):
                raise ResolvedPostRecoveryError(
                    "clear-disclosures committed different restriction evidence"
                )
            lineage_path_names = (
                (
                    "manifest_path",
                    "case_relevance_path",
                    "restriction_path",
                    "requests_path",
                    "worksheet_path",
                    "routing_plan_path",
                    "cohort_policy_path",
                    *(
                        ("public_marker_policy_path",)
                        if run_card.get("schema_version")
                        == (
                            "legalforecast."
                            "provenance_public_marker_clearance_run_card.v1"
                        )
                        else ()
                    ),
                )
                if provider_free_run_card
                else (
                    "manifest_path",
                    "restriction_path",
                    "requests_path",
                    "worksheet_path",
                    "decisions_path",
                    "recorder_path",
                    "routing_plan_path",
                    "cohort_policy_path",
                )
            )
            paths = tuple(cast(Path, lineage[name]) for name in lineage_path_names)
            return (
                _materializer_clearance_lineage_kwargs(
                    clearance_path=clearance_path,
                    run_card_path=clearance_run_card_path,
                    lineage=lineage,
                ),
                (clearance_run_card_path, *paths),
            )
    raw_paths = (
        clearance_run_card_path,
        cast(Path | None, args.reviews),
        cast(Path | None, args.review_receipt),
        cast(Path | None, args.restriction_evidence),
    )
    if any(path is None for path in raw_paths):
        raise ResolvedPostRecoveryError(
            "unknown-origin material requires --clearance-run-card, --reviews, "
            "--review-receipt, and --restriction-evidence"
        )
    clearance_run_card_path, reviews_path, review_receipt_path, restriction_path = cast(
        tuple[Path, Path, Path, Path], raw_paths
    )
    return _authenticated_clearance_lineage_from_run_card(
        clearance_path=clearance_path,
        clearance_run_card_path=clearance_run_card_path,
        expected_reviews_path=reviews_path,
        expected_review_receipt_path=review_receipt_path,
        expected_restriction_path=restriction_path,
    )


def _authenticated_clearance_lineage_from_run_card(
    *,
    clearance_path: Path,
    clearance_run_card_path: Path,
    expected_download_manifest_path: Path | None = None,
    expected_reviews_path: Path | None = None,
    expected_review_receipt_path: Path | None = None,
    expected_restriction_path: Path | None = None,
    captured_artifact_bytes: Mapping[str, bytes] | None = None,
) -> tuple[dict[str, Any], tuple[Path, ...]]:
    """Load every exact signed-clearance input from its committed run card."""

    run_card_bytes = _captured_or_stable_input(
        clearance_run_card_path,
        label="clearance run card",
        captured_artifact_bytes=captured_artifact_bytes,
    )
    run_card = _projection_json_object(run_card_bytes, source=clearance_run_card_path)
    committed_clearance_path = _named_committed_path(
        run_card,
        commitment_group="output_commitments",
        name="disclosure_clearance",
    )
    if committed_clearance_path.resolve() != clearance_path.resolve():
        raise ResolvedPostRecoveryError(
            "clear-disclosures run card committed a different clearance artifact"
        )
    reviews_path = _named_committed_path(
        run_card, commitment_group="source_commitments", name="reviews"
    )
    review_receipt_path = _named_committed_path(
        run_card, commitment_group="source_commitments", name="review_receipt"
    )
    restriction_path = _named_committed_path(
        run_card, commitment_group="source_commitments", name="restriction_evidence"
    )
    review_requests_path = _named_committed_path(
        run_card, commitment_group="source_commitments", name="review_requests"
    )
    review_worksheet_path = _named_committed_path(
        run_card, commitment_group="source_commitments", name="review_worksheet"
    )
    reviewer_policy_path = _named_committed_path(
        run_card, commitment_group="source_commitments", name="reviewer_policy"
    )
    cohort_policy_path = _named_committed_path(
        run_card, commitment_group="source_commitments", name="cohort_policy"
    )
    download_manifest_path = _named_committed_path(
        run_card, commitment_group="source_commitments", name="download_manifest"
    )
    expected_paths = (
        ("download manifest", expected_download_manifest_path, download_manifest_path),
        ("reviews", expected_reviews_path, reviews_path),
        ("review receipt", expected_review_receipt_path, review_receipt_path),
        ("restriction evidence", expected_restriction_path, restriction_path),
    )
    for label, expected, committed in expected_paths:
        if expected is not None and expected.resolve() != committed.resolve():
            raise ResolvedPostRecoveryError(
                f"clear-disclosures committed different {label} bytes"
            )
    exact_bytes = {
        "clearance": _captured_or_stable_input(
            clearance_path,
            label="disclosure clearance",
            captured_artifact_bytes=captured_artifact_bytes,
        ),
        "reviews": _captured_or_stable_input(
            reviews_path,
            label="reviews",
            captured_artifact_bytes=captured_artifact_bytes,
        ),
        "receipt": _captured_or_stable_input(
            review_receipt_path,
            label="review receipt",
            captured_artifact_bytes=captured_artifact_bytes,
        ),
        "requests": _captured_or_stable_input(
            review_requests_path,
            label="review requests",
            captured_artifact_bytes=captured_artifact_bytes,
        ),
        "worksheet": _captured_or_stable_input(
            review_worksheet_path,
            label="review worksheet",
            captured_artifact_bytes=captured_artifact_bytes,
        ),
        "reviewer_policy": _captured_or_stable_input(
            reviewer_policy_path,
            label="reviewer policy",
            captured_artifact_bytes=captured_artifact_bytes,
        ),
        "cohort_policy": _captured_or_stable_input(
            cohort_policy_path,
            label="cohort policy",
            captured_artifact_bytes=captured_artifact_bytes,
        ),
        "manifest": _captured_or_stable_input(
            download_manifest_path,
            label="download manifest",
            captured_artifact_bytes=captured_artifact_bytes,
        ),
        "restriction": _captured_or_stable_input(
            restriction_path,
            label="restriction evidence",
            captured_artifact_bytes=captured_artifact_bytes,
        ),
    }
    reviewer_policy_bytes = exact_bytes["reviewer_policy"]
    cohort_policy_bytes = exact_bytes["cohort_policy"]
    try:
        disclosure_authority = load_main_disclosure_review_authority(
            _projection_json_object(cohort_policy_bytes, source=cohort_policy_path),
            reviewer_policy_bytes=reviewer_policy_bytes,
        )
    except DisclosureReviewAuthorityError as exc:
        raise ResolvedPostRecoveryError(str(exc)) from exc
    return (
        {
            "clearance_artifact_bytes": exact_bytes["clearance"],
            "clearance_run_card": run_card,
            "clearance_run_card_bytes": run_card_bytes,
            "reviews_artifact_bytes": exact_bytes["reviews"],
            "review_receipt_artifact": _projection_json_object(
                exact_bytes["receipt"], source=review_receipt_path
            ),
            "review_receipt_bytes": exact_bytes["receipt"],
            "review_requests_artifact_bytes": exact_bytes["requests"],
            "review_worksheet_artifact": _projection_json_object(
                exact_bytes["worksheet"], source=review_worksheet_path
            ),
            "review_worksheet_bytes": exact_bytes["worksheet"],
            "reviewer_policy_bytes": reviewer_policy_bytes,
            "disclosure_authority": disclosure_authority,
            "cohort_policy_artifact_bytes": cohort_policy_bytes,
            "download_manifest_artifact_bytes": exact_bytes["manifest"],
            "restriction_records": _projection_jsonl_records(
                exact_bytes["restriction"], source=restriction_path
            ),
            "restriction_artifact_bytes": exact_bytes["restriction"],
        },
        (
            clearance_run_card_path,
            reviews_path,
            review_receipt_path,
            restriction_path,
            review_requests_path,
            review_worksheet_path,
            reviewer_policy_path,
            cohort_policy_path,
            download_manifest_path,
        ),
    )


def _verify_authenticated_clearance_run_card_with_capability(
    *,
    clearance_path: Path,
    clearance_run_card_path: Path,
    expected_download_manifest_path: Path | None = None,
    expected_restriction_path: Path | None = None,
    captured_artifact_bytes: Mapping[str, bytes] | None = None,
    _verified_source_root_relocations: Mapping[str, Path] | None = None,
    allow_legacy_implicit_quarantine: bool = False,
    authority_transition_capability: object | None = None,
    attempt_transition_capability: object | None = None,
    resolved_transition_prior_snapshot: CaseDevPurchaseSnapshot | None = None,
    recovery_authority_transition_capability: object | None = None,
    recovery_attempt_transition_capability: object | None = None,
) -> tuple[tuple[Path, ...], object | None]:
    """Independently replay signed clearance and return its immutable inputs."""

    run_card_bytes = _captured_or_stable_input(
        clearance_run_card_path,
        label="clearance run card",
        captured_artifact_bytes=captured_artifact_bytes,
    )
    run_card = _projection_json_object(run_card_bytes, source=clearance_run_card_path)
    provider_free_schema = run_card.get("schema_version") in {
        "legalforecast.provenance_quarantine_clearance_run_card.v1",
        "legalforecast.provenance_public_marker_clearance_run_card.v1",
    }
    model_schema = (
        run_card.get("schema_version")
        == "legalforecast.provenance_model_clearance_run_card.v1"
    )
    if (
        provider_free_schema or model_schema
    ) and run_card_bytes != canonical_json_bytes(run_card):
        raise CommandError("provenance clearance run card is not canonical")
    verified_snapshot = _complete_clearance_artifact_snapshot(
        run_card=run_card,
        run_card_path=clearance_run_card_path,
        run_card_bytes=run_card_bytes,
        clearance_path=clearance_path,
        captured_artifact_bytes=captured_artifact_bytes,
    )
    if provider_free_schema or model_schema:
        return _verify_provider_free_provenance_quarantine_run_card(
            clearance_path=clearance_path,
            clearance_run_card_path=clearance_run_card_path,
            run_card=run_card,
            expected_download_manifest_path=expected_download_manifest_path,
            expected_restriction_path=expected_restriction_path,
            captured_artifact_bytes=verified_snapshot,
            _verified_source_root_relocations=_verified_source_root_relocations,
            allow_legacy_implicit_quarantine=allow_legacy_implicit_quarantine,
            authority_transition_capability=authority_transition_capability,
            attempt_transition_capability=attempt_transition_capability,
            resolved_transition_prior_snapshot=resolved_transition_prior_snapshot,
            recovery_authority_transition_capability=(
                recovery_authority_transition_capability
            ),
            recovery_attempt_transition_capability=(
                recovery_attempt_transition_capability
            ),
        )
    authority = run_card.get("clearance_authority")
    authority_kind = (
        cast(Mapping[str, object], authority).get("kind")
        if isinstance(authority, Mapping)
        else None
    )
    if authority_kind == "provenance_first_with_john_exceptions":
        return (
            _verify_provenance_clearance_run_card(
                clearance_path=clearance_path,
                clearance_run_card_path=clearance_run_card_path,
                run_card=run_card,
                expected_download_manifest_path=expected_download_manifest_path,
                expected_restriction_path=expected_restriction_path,
                captured_artifact_bytes=verified_snapshot,
            ),
            None,
        )

    kwargs, paths = _authenticated_clearance_lineage_from_run_card(
        clearance_path=clearance_path,
        clearance_run_card_path=clearance_run_card_path,
        expected_download_manifest_path=expected_download_manifest_path,
        expected_restriction_path=expected_restriction_path,
        captured_artifact_bytes=verified_snapshot,
    )
    try:
        validate_authenticated_clearance_lineage(
            clearance_records=_projection_jsonl_records(
                cast(bytes, kwargs["clearance_artifact_bytes"]),
                source=clearance_path,
            ),
            **kwargs,
        )
    except (OSError, ResolvedPostRecoveryError) as exc:
        raise CommandError(str(exc)) from exc
    return paths, None


def _verify_authenticated_clearance_run_card(
    *,
    clearance_path: Path,
    clearance_run_card_path: Path,
    expected_download_manifest_path: Path | None = None,
    expected_restriction_path: Path | None = None,
    captured_artifact_bytes: Mapping[str, bytes] | None = None,
    _verified_source_root_relocations: Mapping[str, Path] | None = None,
    allow_legacy_implicit_quarantine: bool = False,
) -> tuple[Path, ...]:
    """Independently replay signed clearance and return immutable inputs."""

    paths, _ = _verify_authenticated_clearance_run_card_with_capability(
        clearance_path=clearance_path,
        clearance_run_card_path=clearance_run_card_path,
        expected_download_manifest_path=expected_download_manifest_path,
        expected_restriction_path=expected_restriction_path,
        captured_artifact_bytes=captured_artifact_bytes,
        _verified_source_root_relocations=_verified_source_root_relocations,
        allow_legacy_implicit_quarantine=allow_legacy_implicit_quarantine,
    )
    return paths


def _verify_provenance_clearance_run_card(
    *,
    clearance_path: Path,
    clearance_run_card_path: Path,
    run_card: Mapping[str, Any],
    expected_download_manifest_path: Path | None,
    expected_restriction_path: Path | None,
    captured_artifact_bytes: Mapping[str, bytes] | None = None,
) -> tuple[Path, ...]:
    """Replay provenance routing, interactive exceptions, and final clearance."""

    if (
        run_card.get("schema_version") != "legalforecast.acquisition_run_card.v1"
        or run_card.get("stage") != "clear-disclosures"
        or run_card.get("status") != "completed"
        or run_card.get("dry_run") is not False
        or run_card.get("execute") is not True
        or run_card.get("paid_activity_requested") is not False
        or run_card.get("paid_activity_executed") is not False
    ):
        raise CommandError("invalid provenance clearance run card")
    raw_sources = run_card.get("source_commitments")
    raw_outputs = run_card.get("output_commitments")
    raw_authority = run_card.get("clearance_authority")
    if (
        not isinstance(raw_sources, Mapping)
        or not isinstance(raw_outputs, Mapping)
        or not isinstance(raw_authority, Mapping)
    ):
        raise CommandError("provenance clearance run card lacks exact commitments")
    sources = cast(Mapping[str, object], raw_sources)
    outputs = cast(Mapping[str, object], raw_outputs)
    authority = cast(Mapping[str, object], raw_authority)
    source_names = (
        "review_requests",
        "download_manifest",
        "case_relevance",
        "restriction_evidence",
        "routing_plan",
        "exception_worksheet",
        "exception_decisions",
        "exception_review_run_card",
        "cohort_policy",
    )
    paths = {
        name: _materializer_committed_path(
            sources,
            name,
            captured_artifact_bytes=captured_artifact_bytes,
        )
        for name in source_names
    }
    document_commitment = sources.get("document_root")
    if not isinstance(document_commitment, Mapping):
        raise CommandError("provenance clearance lacks document-root commitment")
    document_root_text = cast(Mapping[str, object], document_commitment).get("path")
    if not isinstance(document_root_text, str) or not document_root_text:
        raise CommandError("provenance clearance document root is invalid")
    document_root = Path(document_root_text)
    _reject_existing_parent_symlink(document_root, label="document root")
    if document_root.is_symlink() or not document_root.is_dir():
        raise CommandError(f"document root is missing or unsafe: {document_root}")
    if expected_download_manifest_path is not None and (
        paths["download_manifest"].resolve()
        != expected_download_manifest_path.resolve()
    ):
        raise CommandError("clear-disclosures committed different download manifest")
    if expected_restriction_path is not None and (
        paths["restriction_evidence"].resolve() != expected_restriction_path.resolve()
    ):
        raise CommandError("clear-disclosures committed different restriction evidence")
    committed_clearance = _materializer_committed_path(outputs, "disclosure_clearance")
    if committed_clearance.resolve() != clearance_path.resolve():
        raise CommandError("clear-disclosures committed different clearance artifact")
    try:
        source_bytes = {
            name: _captured_or_stable_input(
                path,
                label=name.replace("_", " "),
                captured_artifact_bytes=captured_artifact_bytes,
            )
            for name, path in paths.items()
        }
        for name, path in paths.items():
            _validate_named_path_commitment(
                sources,
                name=name,
                expected_path=path,
                expected_sha256=_bytes_sha256(source_bytes[name]),
            )
        clearance_bytes = _captured_or_stable_input(
            clearance_path,
            label="disclosure clearance",
            captured_artifact_bytes=captured_artifact_bytes,
        )
        _validate_named_path_commitment(
            outputs,
            name="disclosure_clearance",
            expected_path=clearance_path,
            expected_sha256=_bytes_sha256(clearance_bytes),
        )
        manifest_records = _projection_jsonl_records(
            source_bytes["download_manifest"], source=paths["download_manifest"]
        )
        document_snapshot = _capture_provenance_document_snapshot(
            manifest_records, document_root=document_root
        )
        tree = _provenance_document_tree_from_snapshot(document_snapshot)
        document_count = cast(Mapping[str, object], document_commitment).get(
            "document_count"
        )
        if (
            cast(Mapping[str, object], document_commitment).get("tree_sha256")
            != _canonical_json_sha256(tree)
            or type(document_count) is not int
            or document_count != len(tree)
        ):
            raise ProvenanceClearanceError("document-root commitment changed")
        frozen_plan = _projection_json_object(
            source_bytes["routing_plan"], source=paths["routing_plan"]
        )
        plan = build_provenance_clearance_plan(
            _projection_jsonl_records(
                source_bytes["review_requests"], source=paths["review_requests"]
            ),
            manifest_records,
            _projection_jsonl_records(
                source_bytes["restriction_evidence"],
                source=paths["restriction_evidence"],
            ),
            _projection_jsonl_records(
                source_bytes["case_relevance"], source=paths["case_relevance"]
            ),
            document_root=document_root,
            review_requests_bytes=source_bytes["review_requests"],
            download_manifest_bytes=source_bytes["download_manifest"],
            restriction_evidence_bytes=source_bytes["restriction_evidence"],
            case_relevance_bytes=source_bytes["case_relevance"],
            document_bytes_by_relative_path=document_snapshot,
            document_scanner=document_scanner_for_plan(frozen_plan),
        )
        plan_bytes = canonical_json_bytes(plan)
        if plan_bytes != source_bytes["routing_plan"]:
            raise ProvenanceClearanceError("routing plan replay mismatch")
        worksheet = exception_review_worksheet(plan)
        worksheet_bytes = canonical_json_bytes(worksheet)
        if worksheet_bytes != source_bytes["exception_worksheet"]:
            raise ProvenanceClearanceError("exception worksheet replay mismatch")
        recorder = _projection_json_object(
            source_bytes["exception_review_run_card"],
            source=paths["exception_review_run_card"],
        )
        decisions = _projection_jsonl_records(
            source_bytes["exception_decisions"],
            source=paths["exception_decisions"],
        )
        routing_plan_sha256 = hashlib.sha256(plan_bytes).hexdigest()
        _validate_provenance_exception_recorder(
            recorder,
            worksheet_path=paths["exception_worksheet"],
            worksheet_bytes=worksheet_bytes,
            decisions_path=paths["exception_decisions"],
            decisions_bytes=source_bytes["exception_decisions"],
            expected_count=cast(int, plan["john_review_count"]),
            routing_plan_sha256=routing_plan_sha256,
        )
        cohort_sha256 = verify_cohort_policy(
            _projection_json_object(
                source_bytes["cohort_policy"], source=paths["cohort_policy"]
            )
        )
        records = build_provenance_clearance_records(
            plan, decisions, routing_plan_sha256=routing_plan_sha256
        )
        expected_clearance = b"".join(
            canonical_json_bytes(record.to_record()) for record in records
        )
        if clearance_bytes != expected_clearance:
            raise ProvenanceClearanceError("clearance artifact replay mismatch")
        summary = cast(Mapping[str, object], recorder["human_batch_summary"])
        expected_authority = {
            "kind": "provenance_first_with_john_exceptions",
            "authentication_claim": "interactive_hash_confirmation_only",
            "cohort_policy_sha256": "sha256:" + cohort_sha256,
            "routing_plan_sha256": _bytes_sha256(plan_bytes),
            "review_worksheet_sha256": _bytes_sha256(worksheet_bytes),
            "exception_decisions_sha256": _bytes_sha256(
                source_bytes["exception_decisions"]
            ),
            "exception_review_run_card_sha256": _bytes_sha256(
                source_bytes["exception_review_run_card"]
            ),
            "exception_batch_confirmation_sha256": summary["confirmation_sha256"],
            "exception_reviewer_id": summary["intended_reviewer_id"],
            "auto_clear_count": plan["auto_clear_count"],
            "john_review_count": plan["john_review_count"],
        }
        if dict(authority) != expected_authority:
            raise ProvenanceClearanceError("clearance authority replay mismatch")
        _require_provenance_document_snapshot_unchanged(
            document_snapshot, document_root=document_root
        )
    except (
        CohortPolicyError,
        OSError,
        ProvenanceClearanceError,
        TargetCohortProjectionError,
    ) as exc:
        raise CommandError(str(exc)) from exc
    return (
        clearance_run_card_path,
        *tuple(paths[name] for name in source_names),
        document_root,
    )


def _verify_provider_free_provenance_quarantine_run_card(
    *,
    clearance_path: Path,
    clearance_run_card_path: Path,
    run_card: Mapping[str, Any],
    expected_download_manifest_path: Path | None,
    expected_restriction_path: Path | None,
    captured_artifact_bytes: Mapping[str, bytes] | None = None,
    _verified_source_root_relocations: Mapping[str, Path] | None = None,
    allow_legacy_implicit_quarantine: bool = False,
    authority_transition_capability: object | None = None,
    attempt_transition_capability: object | None = None,
    resolved_transition_prior_snapshot: CaseDevPurchaseSnapshot | None = None,
    recovery_authority_transition_capability: object | None = None,
    recovery_attempt_transition_capability: object | None = None,
) -> tuple[tuple[Path, ...], object | None]:
    """Replay a v3 plan whose exception rows are all quarantined."""

    raw_recovered_authority = run_card.get("recovered_public_authority")
    recovered_authority = (
        cast(Mapping[str, object], raw_recovered_authority)
        if isinstance(raw_recovered_authority, Mapping)
        else None
    )
    raw_successor_history = run_card.get("authenticated_successor_history")
    successor_history = (
        cast(Mapping[str, object], raw_successor_history)
        if isinstance(raw_successor_history, Mapping)
        else None
    )
    transition_pairs = (
        authority_transition_capability,
        attempt_transition_capability,
        recovery_authority_transition_capability,
        recovery_attempt_transition_capability,
    )
    transition_inputs_present = resolved_transition_prior_snapshot is not None or any(
        value is not None for value in transition_pairs
    )
    if transition_inputs_present and recovered_authority is None:
        raise CommandError(
            "resolved transition clearance replay requires recovered-public authority"
        )
    if successor_history is not None:
        transition_shape_valid = not transition_inputs_present or (
            resolved_transition_prior_snapshot is not None
            and all(value is not None for value in transition_pairs)
        )
    else:
        transition_shape_valid = not transition_inputs_present or (
            resolved_transition_prior_snapshot is None
            and authority_transition_capability is not None
            and recovery_authority_transition_capability is not None
            and attempt_transition_capability is None
            and recovery_attempt_transition_capability is None
        )
    if not transition_shape_valid:
        raise CommandError(
            "resolved transition clearance replay capability shape differs"
        )
    successor_history_source_names: tuple[str, ...] = ()
    if successor_history is not None:
        raw_names = successor_history.get("source_names")
        history_state = successor_history.get("replayed_purchase_state_sha256")
        if (
            set(successor_history)
            != {
                "recovery_root",
                "initial_controlled_private_root",
                "controlled_private_root",
                "replayed_purchase_state_sha256",
                "source_names",
            }
            or not isinstance(successor_history.get("recovery_root"), str)
            or not successor_history.get("recovery_root")
            or not isinstance(
                successor_history.get("initial_controlled_private_root"), str
            )
            or not successor_history.get("initial_controlled_private_root")
            or not isinstance(successor_history.get("controlled_private_root"), str)
            or not successor_history.get("controlled_private_root")
            or not isinstance(history_state, str)
            or re.fullmatch(r"[0-9a-f]{64}", history_state) is None
            or not isinstance(raw_names, list)
            or not all(isinstance(name, str) for name in cast(list[object], raw_names))
        ):
            raise CommandError("invalid authenticated successor history")
        successor_history_source_names = tuple(cast(list[str], raw_names))
        if (
            not successor_history_source_names
            or successor_history_source_names
            != tuple(
                f"successor_history_source_{index:04d}"
                for index in range(len(successor_history_source_names))
            )
        ):
            raise CommandError("authenticated successor history sources differ")
    expected_fields = {
        "schema_version",
        "stage",
        "status",
        "dry_run",
        "execute",
        "provider_activity_requested",
        "provider_activity_executed",
        "human_review_requested",
        "human_review_executed",
        "paid_activity_requested",
        "paid_activity_executed",
        "record_count",
        "auto_clear_count",
        "exception_quarantine_count",
        "input_paths",
        "source_commitments",
        "output_paths",
        "output_commitments",
        "disposition_policy",
    }
    model_schema = (
        run_card.get("schema_version")
        == "legalforecast.provenance_model_clearance_run_card.v1"
    )
    public_marker_schema = (
        run_card.get("schema_version")
        == "legalforecast.provenance_public_marker_clearance_run_card.v1"
    )
    no_model_review_mode = (
        run_card.get("no_model_review_eligible_exceptions_required") is True
    )
    explicit_quarantine_all_mode = (
        run_card.get("quarantine_all_exceptions_without_review") is True
    )
    raw_policy = run_card.get("disposition_policy")
    legacy_implicit_quarantine_mode = (
        allow_legacy_implicit_quarantine
        and _bytes_sha256(canonical_json_bytes(run_card))
        == _APPROVED_V4_LEGACY_CLEARANCE_RUN_CARD_SHA256
        and not model_schema
        and not public_marker_schema
        and not no_model_review_mode
        and not explicit_quarantine_all_mode
        and isinstance(raw_policy, Mapping)
        and cast(Mapping[str, object], raw_policy).get("kind")
        == "v3_auto_clear_else_quarantine"
    )
    if recovered_authority is not None:
        expected_fields.add("recovered_public_authority")
    if successor_history is not None:
        expected_fields.add("authenticated_successor_history")
    if model_schema:
        expected_fields.add("model_review_state")
        expected_fields.add("resume")
    if public_marker_schema:
        expected_fields.add("resume")
    if no_model_review_mode:
        expected_fields.add("model_review_eligible_exception_count")
        expected_fields.add("no_model_review_eligible_exceptions_required")
    if explicit_quarantine_all_mode:
        expected_fields.add("quarantine_all_exceptions_without_review")
    if public_marker_schema:
        expected_fields.add("public_marker_clear_count")
    if (
        set(run_card) != expected_fields
        or run_card.get("schema_version")
        not in {
            "legalforecast.provenance_quarantine_clearance_run_card.v1",
            "legalforecast.provenance_model_clearance_run_card.v1",
            "legalforecast.provenance_public_marker_clearance_run_card.v1",
        }
        or run_card.get("stage") != "finalize-provenance-quarantine"
        or run_card.get("status") != "completed"
        or run_card.get("dry_run") is not False
        or run_card.get("execute") is not True
        or run_card.get("provider_activity_requested") is not False
        or run_card.get("provider_activity_executed") is not False
        or run_card.get("human_review_requested") is not False
        or run_card.get("human_review_executed") is not False
        or run_card.get("paid_activity_requested") is not False
        or run_card.get("paid_activity_executed") is not False
        or (
            (model_schema or public_marker_schema)
            and not isinstance(run_card.get("resume"), bool)
        )
        or sum(
            (
                model_schema,
                public_marker_schema,
                no_model_review_mode,
                explicit_quarantine_all_mode,
                legacy_implicit_quarantine_mode,
            )
        )
        != 1
        or (no_model_review_mode and (model_schema or public_marker_schema))
        or (
            successor_history is not None
            and (not public_marker_schema or recovered_authority is None)
        )
        or (explicit_quarantine_all_mode and (model_schema or no_model_review_mode))
        or (
            no_model_review_mode
            and run_card.get("model_review_eligible_exception_count") != 0
        )
    ):
        raise CommandError("invalid provenance clearance run card")
    raw_sources = run_card.get("source_commitments")
    raw_outputs = run_card.get("output_commitments")
    if (
        not isinstance(raw_sources, Mapping)
        or not isinstance(raw_outputs, Mapping)
        or not isinstance(raw_policy, Mapping)
    ):
        raise CommandError(
            "provider-free provenance quarantine lacks exact commitments"
        )
    sources = cast(Mapping[str, object], raw_sources)
    outputs = cast(Mapping[str, object], raw_outputs)
    disposition_policy = cast(Mapping[str, object], raw_policy)
    source_names = (
        (
            "review_requests",
            "download_manifest",
            "case_relevance",
            "restriction_evidence",
            "routing_plan",
            "exception_worksheet",
            "cohort_policy",
        )
        + (
            (
                "model_review_authority",
                "model_review_private_records",
                "model_review_run_card",
            )
            if model_schema
            else ()
        )
        + (("plan_run_card",) if no_model_review_mode else ())
        + (
            ("plan_run_card", "public_marker_clearance_policy")
            if public_marker_schema
            else ()
        )
        + successor_history_source_names
    )
    paths = {
        name: _materializer_committed_path(
            sources,
            name,
            captured_artifact_bytes=captured_artifact_bytes,
        )
        for name in source_names
    }
    if set(sources) != {*source_names, "document_root"}:
        raise CommandError(
            "provider-free provenance quarantine source commitments differ"
        )
    if set(outputs) != {"disclosure_clearance", "disclosure_quarantine"}:
        raise CommandError(
            "provider-free provenance quarantine output commitments differ"
        )
    document_commitment = sources.get("document_root")
    if not isinstance(document_commitment, Mapping):
        raise CommandError(
            "provider-free provenance quarantine lacks document-root commitment"
        )
    document_root_text = cast(Mapping[str, object], document_commitment).get("path")
    if not isinstance(document_root_text, str) or not document_root_text:
        raise CommandError("provider-free quarantine document root is invalid")
    document_root = Path(document_root_text)
    _reject_existing_parent_symlink(document_root, label="document root")
    if document_root.is_symlink() or not document_root.is_dir():
        raise CommandError(f"document root is missing or unsafe: {document_root}")
    if expected_download_manifest_path is not None and (
        paths["download_manifest"].resolve()
        != expected_download_manifest_path.resolve()
    ):
        raise CommandError(
            "provider-free quarantine committed different download manifest"
        )
    if expected_restriction_path is not None and (
        paths["restriction_evidence"].resolve() != expected_restriction_path.resolve()
    ):
        raise CommandError(
            "provider-free quarantine committed different restriction evidence"
        )
    committed_clearance = _materializer_committed_path(
        outputs,
        "disclosure_clearance",
        captured_artifact_bytes=captured_artifact_bytes,
    )
    committed_quarantine = _materializer_committed_path(
        outputs,
        "disclosure_quarantine",
        captured_artifact_bytes=captured_artifact_bytes,
    )
    if committed_clearance.resolve() != clearance_path.resolve():
        raise CommandError(
            "provider-free quarantine committed different clearance artifact"
        )
    recovery_input_paths: tuple[Path, ...] = ()
    recovery_capability: object | None = None
    recovery: Mapping[str, object] | None = None
    recovery_run_card_path: Path | None = None
    selection_path: Path | None = None
    selected_document_keys: set[tuple[str, str]] | None = None
    purchase_policy_path: Path | None = None
    initialization_receipt_path: Path | None = None
    recovery_cohort_policy_path: Path | None = None
    ledger_path: Path | None = None
    state_sha256: str | None = None
    successor_history_source_snapshot: dict[str, bytes] = {}
    if successor_history is not None:
        for name in successor_history_source_names:
            path = paths[name]
            payload = _captured_or_stable_input(
                path,
                label=name.replace("_", " "),
                captured_artifact_bytes=captured_artifact_bytes,
            )
            _validate_named_path_commitment(
                sources,
                name=name,
                expected_path=path,
                expected_sha256=_bytes_sha256(payload),
            )
            successor_history_source_snapshot[os.path.abspath(path)] = payload
    if recovered_authority is not None:
        if (
            set(recovered_authority)
            != {
                "kind",
                "recovery_run_card",
                "recovery_manifest_sha256",
                "recovery_restriction_evidence_sha256",
                "selection",
                "purchase_policy",
                "purchase_ledger",
                "purchase_ledger_initialization_receipt",
                "cohort_policy",
                "document_count",
            }
            or recovered_authority.get("kind") != "verified_recap_fetch_recovery"
        ):
            raise CommandError("invalid recovered-public clearance authority")
        recovery_run_card_path = _materializer_committed_path(
            recovered_authority, "recovery_run_card"
        )
        selection_path = _materializer_committed_path(recovered_authority, "selection")
        purchase_policy_path = _materializer_committed_path(
            recovered_authority, "purchase_policy"
        )
        initialization_receipt_path = _materializer_committed_path(
            recovered_authority, "purchase_ledger_initialization_receipt"
        )
        recovery_cohort_policy_path = _materializer_committed_path(
            recovered_authority, "cohort_policy"
        )
        raw_ledger = recovered_authority.get("purchase_ledger")
        if not isinstance(raw_ledger, Mapping):
            raise CommandError("recovered-public authority lacks purchase ledger")
        ledger_commitment = cast(Mapping[str, object], raw_ledger)
        ledger_path_text = ledger_commitment.get("path")
        raw_state_sha256 = ledger_commitment.get("purchase_state_sha256")
        if (
            not isinstance(ledger_path_text, str)
            or not ledger_path_text
            or not isinstance(raw_state_sha256, str)
            or re.fullmatch(r"[0-9a-f]{64}", raw_state_sha256) is None
        ):
            raise CommandError("invalid recovered-public purchase ledger commitment")
        ledger_path = Path(ledger_path_text)
        state_sha256 = raw_state_sha256
        selection_records = _projection_jsonl_records(
            _read_singly_linked_regular_input(
                selection_path, label="recovered-public selection"
            ),
            source=selection_path,
        )
        purchase_policy_bytes = _read_singly_linked_regular_input(
            purchase_policy_path, label="recovered-public purchase policy"
        )
        recovery_cohort_policy_bytes = _read_singly_linked_regular_input(
            recovery_cohort_policy_path,
            label="recovered-public cohort policy",
        )
        purchase_policy = verify_case_dev_purchase_policy(
            _projection_json_object(purchase_policy_bytes, source=purchase_policy_path)
        )
        require_approved_case_dev_purchase_policy(purchase_policy)
        verify_case_dev_purchase_policy_cohort_binding(
            purchase_policy,
            _projection_json_object(
                recovery_cohort_policy_bytes,
                source=recovery_cohort_policy_path,
            ),
        )
        if ledger_path.resolve() != purchase_policy.canonical_ledger_path:
            raise CommandError(
                "recovered-public ledger conflicts with the canonical policy locator"
            )
        purchase_snapshot = read_case_dev_purchase_snapshot(
            ledger_path,
            policy=purchase_policy,
            initialization_receipt_path=initialization_receipt_path,
        )
        selected_document_keys = _replacement_consolidation_selection_keys(
            selection_records
        )
        verification_snapshot = purchase_snapshot
        if successor_history is not None:
            history_recovery_root = Path(cast(str, successor_history["recovery_root"]))
            history_private_root = Path(
                cast(str, successor_history["controlled_private_root"])
            )

            def capture_successor_history(path: Path, *, label: str) -> bytes:
                payload = successor_history_source_snapshot.get(os.path.abspath(path))
                if payload is None:
                    return _read_singly_linked_regular_input(path, label=label)
                return payload

            try:
                verification_snapshot, verified_history_bytes = (
                    _authenticated_pre_successor_purchase_snapshot(
                        successor_recovery_root=history_recovery_root,
                        successor_controlled_private_root=history_private_root,
                        current_snapshot=(
                            resolved_transition_prior_snapshot or purchase_snapshot
                        ),
                        policy=purchase_policy,
                        policy_artifact=_projection_json_object(
                            purchase_policy_bytes, source=purchase_policy_path
                        ),
                        cohort_artifact=_projection_json_object(
                            recovery_cohort_policy_bytes,
                            source=recovery_cohort_policy_path,
                        ),
                        purchase_policy_path=purchase_policy_path,
                        cohort_policy_path=recovery_cohort_policy_path,
                        ledger_path=ledger_path,
                        initial_controlled_private_root=Path(
                            cast(
                                str,
                                successor_history["initial_controlled_private_root"],
                            )
                        ),
                        initialization_receipt_path=initialization_receipt_path,
                        capture=capture_successor_history,
                        authority_transition_capability=(
                            authority_transition_capability
                        ),
                        attempt_transition_capability=(attempt_transition_capability),
                    )
                )
            except (
                OSError,
                RecapFetchAttemptPolicyError,
                ReplacementPurchaseApprovalError,
                ReplacementRecoverySourceError,
                ValueError,
            ) as exc:
                raise CommandError(str(exc)) from exc
            core_history_paths = {
                path.resolve()
                for path in (
                    selection_path,
                    purchase_policy_path,
                    ledger_path,
                    initialization_receipt_path,
                    recovery_cohort_policy_path,
                )
            }
            unique_verified_history = {
                os.path.abspath(Path(path).resolve()): payload
                for path, payload in verified_history_bytes.items()
                if Path(path).resolve() not in core_history_paths
            }
            if unique_verified_history != successor_history_source_snapshot:
                raise CommandError(
                    "authenticated successor history source coverage changed"
                )
            if successor_history.get("replayed_purchase_state_sha256") != (
                verification_snapshot.purchase_state_sha256
            ):
                raise CommandError(
                    "authenticated successor history purchase state changed"
                )
        elif authority_transition_capability is not None:
            try:
                verification_snapshot = (
                    _consume_live_resolved_transition_prior_snapshot(
                        authority_transition_capability
                    )
                )
            except (OSError, ReplacementPurchaseApprovalError, ValueError) as exc:
                raise CommandError(str(exc)) from exc
        recovery = _verify_materializer_quarantine_recovery(
            recovery_root=recovery_run_card_path.parents[1],
            run_card_path=recovery_run_card_path,
            selection_path=selection_path,
            selected_document_keys=selected_document_keys,
            purchase_policy_path=purchase_policy_path,
            cohort_policy_path=recovery_cohort_policy_path,
            ledger_path=ledger_path,
            purchase_operations=verification_snapshot.operations,
            purchase_committed_amount_usd=verification_snapshot.committed_amount_usd,
            purchase_state_sha256=verification_snapshot.purchase_state_sha256,
        )
        historical_state_sha256 = recovery.get("historical_purchase_state_sha256")
        if state_sha256 != historical_state_sha256:
            raise CommandError("recovered-public purchase state changed")
        for field, expected in (
            ("manifest_path", paths["download_manifest"]),
            ("restriction_path", paths["restriction_evidence"]),
            ("case_relevance_path", paths["case_relevance"]),
            ("review_requests_path", paths["review_requests"]),
            ("document_root", document_root),
        ):
            actual = recovery.get(field)
            if not isinstance(actual, Path) or actual.resolve() != expected.resolve():
                raise CommandError(
                    f"recovered-public authority changed {field.replace('_', ' ')}"
                )
        terminal_unavailable_path = recovery.get("terminal_unavailable_path")
        if terminal_unavailable_path is not None and (
            not isinstance(terminal_unavailable_path, Path)
            or terminal_unavailable_path.resolve()
            != (
                recovery_run_card_path.parents[1]
                / "terminal-unavailable-operations.jsonl"
            ).resolve()
        ):
            raise CommandError(
                "recovered-public authority changed terminal unavailable path"
            )
        recovery_input_paths = (
            recovery_run_card_path,
            selection_path,
            purchase_policy_path,
            ledger_path,
            initialization_receipt_path,
            recovery_cohort_policy_path,
        )
    if run_card.get("input_paths") != [
        str(paths[name].resolve()) for name in source_names
    ] + [str(path.resolve()) for path in recovery_input_paths] + [
        str(document_root.resolve())
    ]:
        raise CommandError("provider-free provenance quarantine input paths differ")
    if run_card.get("output_paths") != [
        str(committed_clearance.resolve()),
        str(committed_quarantine.resolve()),
    ]:
        raise CommandError("provider-free provenance quarantine output paths differ")
    try:
        source_bytes = {
            name: _captured_or_stable_input(
                path,
                label=name.replace("_", " "),
                captured_artifact_bytes=captured_artifact_bytes,
            )
            for name, path in paths.items()
        }
        for name, path in paths.items():
            _validate_named_path_commitment(
                sources,
                name=name,
                expected_path=path,
                expected_sha256=_bytes_sha256(source_bytes[name]),
            )
        clearance_bytes = _captured_or_stable_input(
            clearance_path,
            label="disclosure clearance",
            captured_artifact_bytes=captured_artifact_bytes,
        )
        quarantine_bytes = _captured_or_stable_input(
            committed_quarantine,
            label="disclosure quarantine",
            captured_artifact_bytes=captured_artifact_bytes,
        )
        _validate_named_path_commitment(
            outputs,
            name="disclosure_clearance",
            expected_path=clearance_path,
            expected_sha256=_bytes_sha256(clearance_bytes),
        )
        _validate_named_path_commitment(
            outputs,
            name="disclosure_quarantine",
            expected_path=committed_quarantine,
            expected_sha256=_bytes_sha256(quarantine_bytes),
        )
        manifest_records = _projection_jsonl_records(
            source_bytes["download_manifest"], source=paths["download_manifest"]
        )
        document_snapshot = _capture_provenance_document_snapshot(
            manifest_records, document_root=document_root
        )
        tree = _provenance_document_tree_from_snapshot(document_snapshot)
        document_count = cast(Mapping[str, object], document_commitment).get(
            "document_count"
        )
        if (
            cast(Mapping[str, object], document_commitment).get("tree_sha256")
            != _canonical_json_sha256(tree)
            or type(document_count) is not int
            or document_count != len(tree)
        ):
            raise ProvenanceClearanceError("document-root commitment changed")
        frozen_plan = _projection_json_object(
            source_bytes["routing_plan"], source=paths["routing_plan"]
        )
        if recovered_authority is not None:
            raw_documents = frozen_plan.get("documents")
            if (
                not isinstance(raw_documents, list)
                or recovery is None
                or recovery_run_card_path is None
                or selection_path is None
                or selected_document_keys is None
                or purchase_policy_path is None
                or initialization_receipt_path is None
                or recovery_cohort_policy_path is None
                or ledger_path is None
                or state_sha256 is None
            ):
                raise ProvenanceClearanceError(
                    "recovered-public routing plan lacks documents"
                )
            lineage_rows: list[Mapping[str, object]] = []
            for raw_document in cast(list[object], raw_documents):
                if not isinstance(raw_document, Mapping):
                    raise ProvenanceClearanceError(
                        "recovered-public routing plan document is invalid"
                    )
                raw_lineage = cast(Mapping[str, object], raw_document).get(
                    "recovered_public_lineage"
                )
                if isinstance(raw_lineage, Mapping):
                    lineage_rows.append(cast(Mapping[str, object], raw_lineage))
            purchase_policy_bytes = _read_singly_linked_regular_input(
                purchase_policy_path, label="recovered-public purchase policy"
            )
            recovery_cohort_policy_bytes = _read_singly_linked_regular_input(
                recovery_cohort_policy_path,
                label="recovered-public cohort policy",
            )
            purchase_policy = verify_case_dev_purchase_policy(
                _projection_json_object(
                    purchase_policy_bytes, source=purchase_policy_path
                )
            )
            require_approved_case_dev_purchase_policy(purchase_policy)
            verify_case_dev_purchase_policy_cohort_binding(
                purchase_policy,
                _projection_json_object(
                    recovery_cohort_policy_bytes,
                    source=recovery_cohort_policy_path,
                ),
            )
            if ledger_path.resolve() != purchase_policy.canonical_ledger_path:
                raise CommandError(
                    "recovered-public ledger conflicts with the canonical policy "
                    "locator"
                )
            purchase_snapshot = read_case_dev_purchase_snapshot(
                ledger_path,
                policy=purchase_policy,
                initialization_receipt_path=initialization_receipt_path,
            )
            expected_lineage_rows = _derive_recovered_public_lineage_rows(
                recovery,
                expected_manifest_path=paths["download_manifest"],
                expected_restriction_path=paths["restriction_evidence"],
            )
            recovery_bytes = cast(
                Mapping[str, bytes], recovery["verified_artifact_bytes"]
            )
            expected_authority = {
                "recovery_manifest_sha256": _bytes_sha256(
                    recovery_bytes[
                        os.path.abspath(cast(Path, recovery["manifest_path"]))
                    ]
                ),
                "recovery_restriction_evidence_sha256": _bytes_sha256(
                    recovery_bytes[
                        os.path.abspath(cast(Path, recovery["restriction_path"]))
                    ]
                ),
            }
            if (
                type(recovered_authority.get("document_count")) is not int
                or recovered_authority.get("document_count")
                != len(expected_lineage_rows)
                or any(
                    recovered_authority.get(field) != value
                    for field, value in expected_authority.items()
                )
                or state_sha256 != recovery.get("historical_purchase_state_sha256")
            ):
                raise ProvenanceClearanceError(
                    "recovered-public authority evidence changed"
                )
            if not _recovered_public_routing_lineage_matches(
                lineage_rows,
                expected_lineage_rows,
                routing_schema_version=_required_str(frozen_plan, "schema_version"),
            ):
                raise ProvenanceClearanceError(
                    "recovered-public routing lineage changed"
                )
            recovery_capability = _issue_recovered_public_clearance_capability(
                recovery_root=recovery_run_card_path.parents[1],
                run_card_path=recovery_run_card_path,
                selection_path=selection_path,
                purchase_policy_path=purchase_policy_path,
                cohort_policy_path=recovery_cohort_policy_path,
                ledger_path=ledger_path,
                initialization_receipt_path=initialization_receipt_path,
                controlled_private_root=(
                    Path(
                        cast(
                            str,
                            successor_history["initial_controlled_private_root"],
                        )
                    )
                    if successor_history is not None
                    else None
                ),
                successor_history_recovery_root=(
                    Path(cast(str, successor_history["recovery_root"]))
                    if successor_history is not None
                    else None
                ),
                successor_history_controlled_private_root=(
                    Path(cast(str, successor_history["controlled_private_root"]))
                    if successor_history is not None
                    else None
                ),
                authority_transition_capability=(
                    recovery_authority_transition_capability
                ),
                attempt_transition_capability=(recovery_attempt_transition_capability),
                resolved_transition_prior_snapshot=(resolved_transition_prior_snapshot),
                expected_manifest_path=paths["download_manifest"],
                expected_restriction_path=paths["restriction_evidence"],
                expected_case_relevance_path=paths["case_relevance"],
                expected_review_requests_path=paths["review_requests"],
                expected_document_root=document_root,
            )
            if _materializer_record_index(
                list(
                    _consume_recovered_public_clearance_capability(
                        recovery_capability
                    ).values()
                ),
                label="capability-authenticated recovered-public lineage",
            ) != _materializer_record_index(
                expected_lineage_rows,
                label="recovered-public replay lineage",
            ):
                raise ProvenanceClearanceError(
                    "recovered-public evidence changed during authentication"
                )
        plan = build_provenance_clearance_plan_v3(
            _projection_jsonl_records(
                source_bytes["review_requests"], source=paths["review_requests"]
            ),
            manifest_records,
            _projection_jsonl_records(
                source_bytes["restriction_evidence"],
                source=paths["restriction_evidence"],
            ),
            _projection_jsonl_records(
                source_bytes["case_relevance"], source=paths["case_relevance"]
            ),
            document_root=document_root,
            review_requests_bytes=source_bytes["review_requests"],
            download_manifest_bytes=source_bytes["download_manifest"],
            restriction_evidence_bytes=source_bytes["restriction_evidence"],
            case_relevance_bytes=source_bytes["case_relevance"],
            document_bytes_by_relative_path=document_snapshot,
            document_scanner=document_scanner_for_plan(frozen_plan),
            verified_recovery_capability=recovery_capability,
        )
        plan_bytes = canonical_json_bytes(plan)
        if not _recovered_public_routing_plan_matches(frozen_plan, plan):
            raise ProvenanceClearanceError("v3 routing plan replay mismatch")
        plan = frozen_plan
        plan_bytes = source_bytes["routing_plan"]
        worksheet = exception_review_worksheet_v3(plan)
        worksheet_bytes = canonical_json_bytes(worksheet)
        if worksheet_bytes != source_bytes["exception_worksheet"]:
            raise ProvenanceClearanceError("v3 exception worksheet replay mismatch")
        cohort_sha256 = verify_cohort_policy(
            _projection_json_object(
                source_bytes["cohort_policy"], source=paths["cohort_policy"]
            )
        )
        routing_plan_sha256 = hashlib.sha256(plan_bytes).hexdigest()
        plan_history_paths = {
            name: paths[name] for name in successor_history_source_names
        }
        plan_history_bytes = {
            name: source_bytes[name] for name in successor_history_source_names
        }
        public_marker_policy: PublicMarkerClearancePolicy | None = None
        if no_model_review_mode or public_marker_schema:
            if public_marker_schema:
                public_marker_policy_artifact = _projection_json_object(
                    source_bytes["public_marker_clearance_policy"],
                    source=paths["public_marker_clearance_policy"],
                )
                if source_bytes[
                    "public_marker_clearance_policy"
                ] != canonical_json_bytes(public_marker_policy_artifact):
                    raise ProvenanceClearanceError(
                        "public-marker policy requires exact canonical serialization"
                    )
                public_marker_policy = verify_public_marker_clearance_policy(
                    public_marker_policy_artifact,
                    cohort_policy_artifact=_projection_json_object(
                        source_bytes["cohort_policy"], source=paths["cohort_policy"]
                    ),
                )
        if no_model_review_mode:
            eligible = _model_review_eligible_plan_documents(plan)
            if eligible:
                raise ProvenanceClearanceError(
                    "provider-free no-review finalization found "
                    "model-review-eligible exceptions"
                )
            _verify_no_model_review_plan_run_card(
                run_card_bytes=source_bytes["plan_run_card"],
                run_card_path=paths["plan_run_card"],
                plan_path=paths["routing_plan"],
                plan_bytes=plan_bytes,
                worksheet_path=paths["exception_worksheet"],
                worksheet_bytes=worksheet_bytes,
                plan=plan,
                worksheet=worksheet,
                source_paths=paths,
                source_bytes=source_bytes,
                document_root=document_root,
                document_tree=tree,
                recovered_public_authority=recovered_authority,
                recovery_input_paths=recovery_input_paths,
                successor_history_source_paths=plan_history_paths,
                successor_history_source_bytes=plan_history_bytes,
                authenticated_successor_history=successor_history,
            )
        if public_marker_schema:
            _verify_no_model_review_plan_run_card(
                run_card_bytes=source_bytes["plan_run_card"],
                run_card_path=paths["plan_run_card"],
                plan_path=paths["routing_plan"],
                plan_bytes=plan_bytes,
                worksheet_path=paths["exception_worksheet"],
                worksheet_bytes=worksheet_bytes,
                plan=plan,
                worksheet=worksheet,
                source_paths=paths,
                source_bytes=source_bytes,
                document_root=document_root,
                document_tree=tree,
                recovered_public_authority=recovered_authority,
                recovery_input_paths=recovery_input_paths,
                successor_history_source_paths=plan_history_paths,
                successor_history_source_bytes=plan_history_bytes,
                authenticated_successor_history=successor_history,
            )
        if model_schema:
            raw_model_state = run_card.get("model_review_state")
            if not isinstance(raw_model_state, Mapping):
                raise ProvenanceClearanceError("model review replay state is invalid")
            model_state = cast(Mapping[str, object], raw_model_state)
            state_values = tuple(
                model_state.get(name)
                for name in (
                    "frozen_authority_root",
                    "provider_journal",
                    "provider_spend_authority",
                )
            )
            if not all(isinstance(value, str) and value for value in state_values):
                raise ProvenanceClearanceError("model review replay state is invalid")
            frozen_source_root = Path(cast(str, state_values[0])).absolute()
            source_root_relocations = _verified_source_root_relocations or {}
            frozen_source_root_key = os.path.abspath(frozen_source_root)
            if source_root_relocations and set(source_root_relocations) != {
                frozen_source_root_key
            }:
                raise ProvenanceClearanceError(
                    "model review source-root relocation differs from frozen authority"
                )
            replay_source_root = source_root_relocations.get(
                frozen_source_root_key, frozen_source_root
            ).absolute()
            if replay_source_root != frozen_source_root:
                if os.path.lexists(frozen_source_root):
                    raise ProvenanceClearanceError(
                        "model review frozen authority root still exists"
                    )
                if replay_source_root.is_symlink() or not replay_source_root.is_dir():
                    raise ProvenanceClearanceError(
                        "model review replacement authority root is invalid"
                    )
            document_map = _model_review_document_map(worksheet, document_snapshot)
            capability = replay_authenticated_disclosure_model_review(
                routing_plan=plan,
                routing_plan_bytes=plan_bytes,
                worksheet=worksheet,
                worksheet_bytes=worksheet_bytes,
                document_bytes_by_key=document_map,
                provider_journal_path=Path(cast(str, state_values[1])),
                provider_spend_authority_path=Path(cast(str, state_values[2])),
                source_root=replay_source_root,
            )
            replayed_authority = public_disclosure_model_review_record(capability)
            replayed_private = private_disclosure_model_review_records(capability)
            model_card = _projection_json_object(
                source_bytes["model_review_run_card"],
                source=paths["model_review_run_card"],
            )
            if (
                canonical_json_bytes(replayed_authority)
                != source_bytes["model_review_authority"]
                or canonical_json_bytes(list(replayed_private))
                != source_bytes["model_review_private_records"]
                or model_card.get("model_review_authority") != replayed_authority
            ):
                raise ProvenanceClearanceError("model review replay differs")
            records = build_authenticated_model_provenance_clearance_records_v3(
                plan,
                model_review_capability=capability,
                routing_plan_sha256=routing_plan_sha256,
            )
        elif public_marker_schema:
            records = build_provider_free_public_marker_records_v3(
                plan, routing_plan_sha256=routing_plan_sha256
            )
        else:
            records = build_provider_free_quarantine_records_v3(
                plan, routing_plan_sha256=routing_plan_sha256
            )
        expected_clearance = b"".join(
            canonical_json_bytes(record.to_record()) for record in records
        )
        expected_quarantine = b"".join(
            canonical_json_bytes(record.to_record())
            for record in records
            if record.status == "quarantined"
        )
        if clearance_bytes != expected_clearance:
            raise ProvenanceClearanceError("clearance artifact replay mismatch")
        if quarantine_bytes != expected_quarantine:
            raise ProvenanceClearanceError("quarantine artifact replay mismatch")
        expected_policy = {
            "kind": (
                "v3_auto_clear_authenticated_model_else_quarantine"
                if model_schema
                else "v3_authenticated_recovered_public_markers_clear_else_quarantine"
                if public_marker_schema
                else (
                    "v3_auto_clear_no_model_eligible_else_quarantine"
                    if no_model_review_mode
                    else "v3_auto_clear_else_quarantine"
                )
            ),
            "routing_plan_schema_version": plan["schema_version"],
            "exception_worksheet_schema_version": worksheet["schema_version"],
            "clearance_schema_version": "legalforecast.disclosure_clearance.v1",
            "routing_plan_sha256": _bytes_sha256(plan_bytes),
            "exception_worksheet_sha256": _bytes_sha256(worksheet_bytes),
            "cohort_policy_sha256": "sha256:" + cohort_sha256,
            "auto_clear_count": plan["auto_clear_count"],
            "exception_quarantine_count": sum(
                record.status == "quarantined" for record in records
            ),
            **(
                {
                    "public_marker_clear_count": (
                        len(records)
                        - cast(int, plan["auto_clear_count"])
                        - sum(record.status == "quarantined" for record in records)
                    )
                }
                if public_marker_schema
                else {}
            ),
            "human_or_model_override_permitted": model_schema,
            **(
                {
                    "public_marker_clearance_policy_schema_version": (
                        PUBLIC_MARKER_CLEARANCE_POLICY_SCHEMA_VERSION
                    ),
                    "public_marker_clearance_policy_sha256": (
                        "sha256:" + cast(Any, public_marker_policy).policy_sha256
                    ),
                    "markers_are_diagnostic_only": True,
                }
                if public_marker_schema
                else {}
            ),
        }
        if (
            type(disposition_policy.get("auto_clear_count")) is not int
            or type(disposition_policy.get("exception_quarantine_count")) is not int
            or dict(disposition_policy) != expected_policy
        ):
            raise ProvenanceClearanceError(
                "provider-free disposition policy replay mismatch"
            )
        expected_counts = {
            "record_count": len(records),
            "auto_clear_count": plan["auto_clear_count"],
            "exception_quarantine_count": sum(
                record.status == "quarantined" for record in records
            ),
            **(
                {
                    "public_marker_clear_count": (
                        len(records)
                        - cast(int, plan["auto_clear_count"])
                        - sum(record.status == "quarantined" for record in records)
                    )
                }
                if public_marker_schema
                else {}
            ),
        }
        if any(
            type(run_card.get(name)) is not int or run_card.get(name) != expected_value
            for name, expected_value in expected_counts.items()
        ):
            raise ProvenanceClearanceError("provider-free quarantine summary mismatch")
        if successor_history_source_snapshot:
            _require_snapshot_unchanged(
                {
                    Path(path): payload
                    for path, payload in successor_history_source_snapshot.items()
                },
                label="authenticated successor history",
            )
        _require_provenance_document_snapshot_unchanged(
            document_snapshot, document_root=document_root
        )
    except (
        CaseDevPurchaseLedgerError,
        CaseDevPurchasePolicyError,
        CohortPolicyError,
        OSError,
        ProvenanceClearanceError,
        PublicMarkerClearancePolicyError,
        TargetCohortProjectionError,
    ) as exc:
        raise CommandError(str(exc)) from exc
    return (
        (
            clearance_run_card_path,
            *tuple(paths[name] for name in source_names),
            committed_quarantine,
            document_root,
        ),
        recovery_capability,
    )


def _selection_requires_resolved_post_recovery(
    selection_records: Sequence[Mapping[str, Any]],
) -> bool:
    for selection in selection_records:
        documents = selection.get("documents")
        if not isinstance(documents, Sequence) or isinstance(documents, (str, bytes)):
            raise ResolvedPostRecoveryError("selection documents must be a list")
        for item in cast(Sequence[object], documents):
            if not isinstance(item, Mapping):
                raise ResolvedPostRecoveryError("selected document must be an object")
            document = cast(Mapping[str, Any], item)
            if document.get("requires_paid_recovery") is True and (
                document.get("redaction_or_seal_status") != "public"
                or document.get("is_sealed") is not False
                or document.get("is_private") is not False
            ):
                return True
    return False


def _require_current_purchase_lineage(
    args: argparse.Namespace,
    *,
    needs_resolved_lineage: bool,
    resolved_records: Sequence[Mapping[str, Any]],
    clearance_kwargs: Mapping[str, Any],
) -> tuple[tuple[Path, ...], str | None]:
    if not needs_resolved_lineage:
        return (), None
    policy_path = cast(Path | None, args.purchase_policy)
    ledger_path = cast(Path | None, args.purchase_ledger)
    if policy_path is None or ledger_path is None:
        raise CommandError(
            "unknown-origin material requires --purchase-policy and "
            "--purchase-ledger for current receipt-state validation"
        )
    try:
        policy = verify_case_dev_purchase_policy(_read_json_object(policy_path))
        controlled_private_root = cast(Path | None, args.controlled_private_root)
        initialization_receipt = cast(
            Path | None, args.purchase_ledger_initialization_receipt
        )
        require_approved_case_dev_purchase_policy(
            policy, controlled_private_root=controlled_private_root
        )
        resolved_ledger = ledger_path.resolve()
        if resolved_ledger != policy.canonical_ledger_path:
            raise ResolvedPostRecoveryError(
                "--purchase-ledger conflicts with the canonical policy locator"
            )
        snapshot = read_case_dev_purchase_snapshot(
            resolved_ledger,
            policy=policy,
            controlled_private_root=controlled_private_root,
            initialization_receipt_path=initialization_receipt,
        )
        _require_resolved_operation_bindings_dispatch(
            clearance_kwargs=clearance_kwargs,
            purchase_operation_records=snapshot.operations,
            resolved_records=resolved_records,
            expected_purchase_policy_sha256=policy.policy_sha256,
        )
        state_sha256 = snapshot.purchase_state_sha256
    except (
        CaseDevPurchaseLedgerError,
        CaseDevPurchasePolicyError,
        ResolvedPostRecoveryError,
        OSError,
        sqlite3.Error,
        UnicodeError,
        ValueError,
    ) as exc:
        raise CommandError(str(exc)) from exc
    return (policy_path, resolved_ledger), state_sha256


def _publish_resolved_post_recovery_documents(
    *,
    resolved_path: Path,
    resolved_records: Sequence[Mapping[str, Any]],
    purchase_journal: CaseDevPurchaseJournal,
    authenticated_source_snapshots: Mapping[Path, bytes],
) -> None:
    """Publish only while every verifier-owned source stays immutable."""

    if authenticated_source_snapshots:
        _require_snapshot_unchanged(
            authenticated_source_snapshots,
            label="resolved post-recovery authenticated source",
        )
    write_resolved_post_recovery_documents(resolved_path, resolved_records)
    for record in resolved_records:
        purchase_journal.clear_unknown_material(
            _required_str(record, "source_document_id"),
            resolved_record=record,
        )


def _merge_authenticated_source_snapshots(
    *sources: Mapping[Path, bytes],
) -> dict[Path, bytes]:
    """Merge verifier snapshots by resolved path without allowing rebinding."""

    merged: dict[Path, bytes] = {}
    for source in sources:
        for path, payload in source.items():
            resolved_path = path.resolve()
            existing = merged.get(resolved_path)
            if existing is not None and existing != payload:
                raise ResolvedPostRecoveryError(
                    "authenticated source snapshot collision"
                )
            merged[resolved_path] = payload
    return merged


def _require_terminal_disposition_bundle(
    *,
    terminal_record_count: int,
    terminal_disposition_paths: tuple[Path, Path, Path, Path] | tuple[()],
) -> None:
    """Require disposition evidence exactly when recovery has terminal rows."""

    if bool(terminal_record_count) != bool(terminal_disposition_paths):
        raise CommandError(
            "terminal-disposition inputs must exactly match a nonempty "
            "terminal-unavailable recovery partition"
        )


def _cmd_acquisition_resolve_post_recovery(args: argparse.Namespace) -> int:
    if not _acquisition_dry_run(args):
        _preflight_current_purchase_snapshot(args)
    _preflight_approved_purchase_input_bytes(args)
    output_root = cast(Path, args.output_root)
    selection_path = cast(Path, args.selection)
    purchase_policy_path = cast(Path, args.purchase_policy)
    cohort_policy_path = cast(Path, args.cohort_policy)
    budget_plan_path = cast(Path, args.budget_plan)
    ledger_path = cast(Path, args.purchase_ledger).resolve()
    controlled_private_root = cast(Path | None, args.controlled_private_root)
    initialization_receipt = cast(
        Path | None, args.purchase_ledger_initialization_receipt
    )
    attempt_policy_path = cast(Path, args.attempt_policy)
    replacement_authority_path = cast(
        Path | None, getattr(args, "replacement_purchase_authority", None)
    )
    replacement_private_root = cast(
        Path | None, getattr(args, "replacement_controlled_private_root", None)
    )
    download_path = cast(Path, args.download_manifest)
    clearance_path = cast(Path, args.disclosure_clearance)
    terminal_disposition_inputs = cast(
        tuple[Path | None, Path | None, Path | None, Path | None],
        (
            getattr(args, "terminal_disposition_selection", None),
            getattr(args, "terminal_disposition_snapshot_manifest", None),
            getattr(args, "terminal_purchase_result", None),
            getattr(args, "terminal_purchase_run_card", None),
        ),
    )
    if any(path is not None for path in terminal_disposition_inputs) and not all(
        path is not None for path in terminal_disposition_inputs
    ):
        raise CommandError(
            "terminal disposition selection, snapshot, purchase result, and "
            "purchase run card must be supplied together"
        )
    terminal_disposition_paths = cast(
        tuple[Path, Path, Path, Path] | tuple[()],
        terminal_disposition_inputs if all(terminal_disposition_inputs) else (),
    )
    resolved_path = _acquisition_path(
        args,
        "resolved_output",
        output_root / "resolved-post-recovery-documents.jsonl",
    )
    selection_bytes = read_unique_regular_file(selection_path)
    budget_plan_bytes = read_unique_regular_file(budget_plan_path)
    selection_records = _projection_jsonl_records(
        selection_bytes, source=selection_path
    )
    download_records = _read_records(download_path)
    clearance_records = _read_records(clearance_path)
    purchase_policy_artifact = _read_json_object(purchase_policy_path)
    cohort_policy_artifact = _read_json_object(cohort_policy_path)
    budget_plan_artifact = _projection_json_object(
        budget_plan_bytes, source=budget_plan_path
    )
    attempt_policy_artifact = _read_json_object(attempt_policy_path)
    replacement_authority_artifact = (
        _read_json_object(replacement_authority_path)
        if replacement_authority_path is not None
        else None
    )
    clearance_kwargs, clearance_paths = _authenticated_clearance_lineage_inputs(
        args, clearance_path=clearance_path
    )
    raw_clearance_snapshots = clearance_kwargs.get(
        "_verified_clearance_source_snapshots", {}
    )
    if not isinstance(raw_clearance_snapshots, Mapping) or any(
        not isinstance(path, str) or not isinstance(payload, bytes)
        for path, payload in cast(
            Mapping[object, object], raw_clearance_snapshots
        ).items()
    ):
        raise CommandError("clearance verification returned invalid source snapshots")
    clearance_source_snapshots = {
        Path(cast(str, path)).resolve(): cast(bytes, payload)
        for path, payload in cast(
            Mapping[object, object], raw_clearance_snapshots
        ).items()
    }
    recovery_capability = clearance_kwargs.get("_verified_recovery_capability")
    terminal_partition = (
        _consume_recovered_public_terminal_partition(recovery_capability)
        if recovery_capability is not None
        else None
    )
    terminal_disposition_snapshots: Mapping[Path, bytes] = {}
    terminal_partition_count = (
        terminal_partition.record_count if terminal_partition is not None else 0
    )
    _require_terminal_disposition_bundle(
        terminal_record_count=terminal_partition_count,
        terminal_disposition_paths=terminal_disposition_paths,
    )
    try:
        policy = verify_case_dev_purchase_policy(purchase_policy_artifact)
        require_approved_case_dev_purchase_policy(
            policy, controlled_private_root=controlled_private_root
        )
        if replacement_authority_artifact is None:
            verify_approved_purchase_input_bytes(
                policy,
                controlled_private_root=cast(Path, controlled_private_root),
                budget_plan_bytes=budget_plan_bytes,
                selection_bytes=selection_bytes,
            )
        else:
            verify_replacement_purchase_authority(
                authority_artifact=replacement_authority_artifact,
                controlled_private_root=cast(Path, replacement_private_root),
                initial_purchase_policy_artifact=purchase_policy_artifact,
                initial_controlled_private_root=cast(Path, controlled_private_root),
                cohort_policy_artifact=cohort_policy_artifact,
                budget_plan_bytes=budget_plan_bytes,
                selection_bytes=selection_bytes,
                purchase_ledger_path=ledger_path,
                purchase_ledger_initialization_receipt_path=cast(
                    Path, initialization_receipt
                ),
            )
        verify_case_dev_purchase_policy_cohort_binding(policy, cohort_policy_artifact)
        if ledger_path != policy.canonical_ledger_path:
            raise ResolvedPostRecoveryError(
                "--purchase-ledger conflicts with the canonical policy locator"
            )
        plan = _missing_core_budget_plan(budget_plan_artifact)
        verify_recap_fetch_attempt_policy(
            attempt_policy_artifact,
            purchase_policy_artifact=purchase_policy_artifact,
            cohort_policy_artifact=cohort_policy_artifact,
            budget_plan=plan,
            budget_plan_artifact=budget_plan_artifact,
            selection_records=selection_records,
            budget_plan_bytes=budget_plan_bytes,
            selection_bytes=selection_bytes,
            controlled_private_root=cast(Path, controlled_private_root),
            replacement_purchase_authority_artifact=(replacement_authority_artifact),
            replacement_controlled_private_root=replacement_private_root,
            purchase_ledger_initialization_receipt_path=initialization_receipt,
        )
        dry_run = _acquisition_dry_run(args)
        _acquisition_output_root(args)
        with CaseDevPurchaseJournal(
            ledger_path,
            policy=policy,
            controlled_private_root=controlled_private_root,
            initialization_receipt_path=initialization_receipt,
        ) as journal:
            if terminal_disposition_paths:
                (
                    disposition_selection_path,
                    disposition_snapshot_path,
                    terminal_purchase_result_path,
                    terminal_purchase_run_card_path,
                ) = terminal_disposition_paths
                disposition_selection_bytes = read_unique_regular_file(
                    disposition_selection_path
                )
                disposition_selection_records = _projection_jsonl_records(
                    disposition_selection_bytes,
                    source=disposition_selection_path,
                )
                selected_document_count = len(
                    _replacement_consolidation_selection_keys(
                        disposition_selection_records
                    )
                )
                disposition = _verify_materializer_docket_decision_authority(
                    selection_payload=disposition_selection_bytes,
                    selection_path=disposition_selection_path,
                    snapshot_manifest_path=disposition_snapshot_path,
                    purchase_result_path=terminal_purchase_result_path,
                    purchase_run_card_path=terminal_purchase_run_card_path,
                    purchase_journal=journal,
                    purchase_policy=policy,
                    ledger_path=ledger_path,
                    controlled_private_root=controlled_private_root,
                    initialization_receipt_path=initialization_receipt,
                    selected_document_count=selected_document_count,
                )
                terminal_disposition_snapshots = {
                    path.resolve(): payload
                    for path, payload in disposition.source_snapshots.items()
                }
                clearance_kwargs["_verified_terminal_disposition_capability"] = (
                    _issue_terminal_disposition_capability(
                        authority=disposition.authority,
                        purchase_journal=journal,
                        verified_recovery_capability=recovery_capability,
                    )
                )
            before_state_sha256 = journal.purchase_state_sha256()
            operations = journal.operation_records()
            if cast(bool, getattr(args, "collect_all", False)):
                collect_all_kwargs = dict(clearance_kwargs)
                collect_all_kwargs.pop("_verified_clearance_source_snapshots", None)
                validation = collect_resolved_post_recovery_build_issues(
                    selection_records=selection_records,
                    purchase_operation_records=operations,
                    download_records=download_records,
                    clearance_records=clearance_records,
                    attempt_policy_artifact=attempt_policy_artifact,
                    **collect_all_kwargs,
                )
                existing_issues = list(validation.issues)
                mode = "build"
                if resolved_path.exists():
                    mode = "require"
                    resolved_records = _read_records(resolved_path)
                    try:
                        _require_resolved_post_recovery_dispatch(
                            selection_records=selection_records,
                            download_records=download_records,
                            clearance_records=clearance_records,
                            resolved_records=resolved_records,
                            **clearance_kwargs,
                        )
                    except ResolvedPostRecoveryError as exc:
                        existing_issues.append(
                            RecoveryChainValidationIssue(
                                code="RESOLVED_OUTPUT_VALIDATION",
                                status=RECOVERY_CHAIN_VALIDATION_FAILED,
                                layer="resolved_output",
                                artifact="global",
                                message=str(exc),
                            )
                        )
                    try:
                        _require_resolved_operation_bindings_dispatch(
                            clearance_kwargs=clearance_kwargs,
                            purchase_operation_records=operations,
                            resolved_records=resolved_records,
                            expected_purchase_policy_sha256=policy.policy_sha256,
                        )
                    except ResolvedPostRecoveryError as exc:
                        existing_issues.append(
                            RecoveryChainValidationIssue(
                                code="RESOLVED_OPERATION_BINDINGS",
                                status=RECOVERY_CHAIN_VALIDATION_FAILED,
                                layer="resolved_output",
                                artifact="global",
                                message=str(exc),
                            )
                        )
                collect_all_result = {
                    "ok": not existing_issues,
                    "mode": mode,
                    "issue_count": len(existing_issues),
                    "issues": [
                        issue.to_record()
                        for issue in sorted(
                            existing_issues, key=lambda issue: issue.sort_key()
                        )
                    ],
                }
                print(
                    json.dumps(collect_all_result, indent=2, sort_keys=True),
                    file=sys.stdout,
                )
                return 0 if collect_all_result["ok"] else 1
            if resolved_path.exists():
                resolved_records = _read_records(resolved_path)
                _require_resolved_post_recovery_dispatch(
                    selection_records=selection_records,
                    download_records=download_records,
                    clearance_records=clearance_records,
                    resolved_records=resolved_records,
                    **clearance_kwargs,
                )
                _require_resolved_operation_bindings_dispatch(
                    clearance_kwargs=clearance_kwargs,
                    purchase_operation_records=operations,
                    resolved_records=resolved_records,
                    expected_purchase_policy_sha256=policy.policy_sha256,
                )
            else:
                resolved_records = _build_resolved_post_recovery_dispatch(
                    selection_records=selection_records,
                    purchase_operation_records=operations,
                    download_records=download_records,
                    clearance_records=clearance_records,
                    attempt_policy_artifact=attempt_policy_artifact,
                    **clearance_kwargs,
                )
            authenticated_source_snapshots = _merge_authenticated_source_snapshots(
                clearance_source_snapshots,
                terminal_disposition_snapshots,
            )
            if not dry_run:
                _publish_resolved_post_recovery_documents(
                    resolved_path=resolved_path,
                    resolved_records=resolved_records,
                    purchase_journal=journal,
                    authenticated_source_snapshots=authenticated_source_snapshots,
                )
                _require_resolved_operation_bindings_dispatch(
                    clearance_kwargs=clearance_kwargs,
                    purchase_operation_records=journal.operation_records(),
                    resolved_records=resolved_records,
                    expected_purchase_policy_sha256=policy.policy_sha256,
                )
            after_state_sha256 = journal.purchase_state_sha256()
    except (
        CaseDevPurchaseLedgerError,
        CaseDevPurchasePolicyError,
        RecapFetchAttemptPolicyError,
        ResolvedPostRecoveryError,
        DocketDecisionTextSourceError,
        OSError,
        UnicodeError,
        ValueError,
    ) as exc:
        raise CommandError(str(exc)) from exc
    base_input_paths = (
        selection_path,
        purchase_policy_path,
        cohort_policy_path,
        budget_plan_path,
        ledger_path,
        attempt_policy_path,
        *((replacement_authority_path,) if replacement_authority_path else ()),
        download_path,
        clearance_path,
        *clearance_paths,
        *((terminal_partition.path,) if terminal_partition is not None else ()),
        *terminal_disposition_paths,
    )
    authenticated_snapshot_by_path = {
        path.resolve(): payload
        for path, payload in authenticated_source_snapshots.items()
    }
    base_input_resolved = {path.resolve() for path in base_input_paths}
    input_paths = (
        *base_input_paths,
        *tuple(
            sorted(
                (
                    path
                    for path in authenticated_snapshot_by_path
                    if path.resolve() not in base_input_resolved
                ),
                key=str,
            )
        ),
    )
    if authenticated_snapshot_by_path:
        _require_snapshot_unchanged(
            authenticated_snapshot_by_path,
            label="resolved post-recovery completion source",
        )
    _write_acquisition_completion(
        args,
        stage="resolve-post-recovery-documents",
        input_paths=input_paths,
        output_paths=(resolved_path, ledger_path),
        record_count=len(resolved_records),
        dry_run=dry_run,
        paid_activity_requested=False,
        paid_activity_executed=False,
        extra={
            "source_commitments": {
                f"input_{index:02d}": {
                    "path": str(path.resolve()),
                    "sha256": (
                        _bytes_sha256(authenticated_snapshot_by_path[path.resolve()])
                        if path.resolve() in authenticated_snapshot_by_path
                        else _path_sha256(path)
                    ),
                }
                for index, path in enumerate(input_paths)
            },
            "output_commitments": (
                {}
                if dry_run
                else {
                    "resolved_post_recovery_documents": {
                        "path": str(resolved_path.resolve()),
                        "sha256": _path_sha256(resolved_path),
                    },
                    "purchase_state_sha256": after_state_sha256,
                }
            ),
            "purchase_state_before_sha256": before_state_sha256,
            "purchase_state_after_sha256": after_state_sha256,
            **(
                {
                    "terminal_unavailable_partition": {
                        "path": str(terminal_partition.path.resolve()),
                        "sha256": "sha256:" + terminal_partition.sha256,
                        "record_count": terminal_partition.record_count,
                    }
                }
                if terminal_partition is not None
                else {}
            ),
            **(
                {
                    "terminal_disposition_sources": {
                        "selection": str(terminal_disposition_paths[0].resolve()),
                        "snapshot_manifest": str(
                            terminal_disposition_paths[1].resolve()
                        ),
                        "purchase_result": str(terminal_disposition_paths[2].resolve()),
                        "purchase_run_card": str(
                            terminal_disposition_paths[3].resolve()
                        ),
                    }
                }
                if terminal_disposition_paths
                else {}
            ),
        },
    )
    return 0


def _cmd_acquisition_plan_parse_documents(args: argparse.Namespace) -> int:
    """Publish deterministic parser requests from materialized documents."""

    with cache_disclosure_document_scans():
        return _cmd_acquisition_plan_parse_documents_cached(args)


def _cmd_acquisition_plan_parse_documents_cached(args: argparse.Namespace) -> int:
    _preflight_materialization_purchase_runtime(args)
    dry_run = _acquisition_dry_run(args)
    if (
        not dry_run
        and cast(Path | None, getattr(args, "materialization_run_card", None)) is None
    ):
        raise CommandError(
            "executed parse planning requires canonical materialized documents "
            "and --materialization-run-card"
        )
    prospective_output_root = cast(Path, args.output_root)
    selection_path = cast(Path | None, args.selection)
    download_manifest_path = cast(Path, args.download_manifest)
    clearance_path = cast(Path, args.disclosure_clearance)
    resolved_path = cast(Path | None, args.resolved_post_recovery_documents)
    document_root = _acquisition_path(
        args,
        "document_root",
        prospective_output_root / "documents" / "free",
    )
    markdown_output_root = cast(Path, args.markdown_output_root)
    materialization_card_path = cast(Path | None, args.materialization_run_card)
    materialization_lineage: _VerifiedMaterializedDownstreamLineage | None = None
    if materialization_card_path is not None:
        materialization_lineage = _verify_materialized_downstream_lineage(
            run_card_path=materialization_card_path,
            manifest_path=download_manifest_path,
            clearance_path=clearance_path,
            document_root=document_root,
            selection_path=selection_path,
            controlled_private_root=cast(Path | None, args.controlled_private_root),
            initialization_receipt_path=cast(
                Path | None, args.purchase_ledger_initialization_receipt
            ),
        )
    output_root = _acquisition_output_root(args)
    requests_path = _acquisition_path(
        args,
        "requests_output",
        output_root / "parse-document-requests.jsonl",
    )
    if materialization_lineage is not None:
        records = list(materialization_lineage.manifest_records)
        clearance_records = list(materialization_lineage.clearance_records)
        selection_records = list(materialization_lineage.selection_records)
    else:
        records = _read_records(download_manifest_path)
        clearance_records = _read_records(clearance_path)
        selection_records = (
            _read_records(selection_path) if selection_path is not None else []
        )
    is_materialized = _require_consistent_materialization_markers(
        records, clearance_records
    )
    if is_materialized and materialization_card_path is None:
        raise CommandError("materialized documents require --materialization-run-card")
    materialization_paths: Sequence[Path] = ()
    if materialization_card_path is not None:
        if materialization_lineage is None:
            raise CommandError("materialization lineage verification was skipped")
        materialization_paths = materialization_lineage.paths
        committed_resolved_path = (
            materialization_paths[3] if len(materialization_paths) == 4 else None
        )
        if resolved_path is not None and (
            committed_resolved_path is None
            or resolved_path.resolve() != committed_resolved_path.resolve()
        ):
            raise CommandError(
                "--resolved-post-recovery-documents differs from materialization"
            )
        resolved_path = committed_resolved_path
    if not is_materialized and materialization_card_path is not None:
        raise CommandError(
            "--materialization-run-card requires exact materialization markers"
        )
    if not dry_run and not is_materialized:
        raise CommandError(
            "executed parse planning requires canonical materialized documents "
            "and --materialization-run-card"
        )
    resolved_records = (
        list(materialization_lineage.resolved_records)
        if materialization_lineage is not None
        else (_read_records(resolved_path) if resolved_path is not None else [])
    )
    needs_resolved_lineage = _selection_requires_resolved_post_recovery(
        selection_records
    ) or any(
        record.get("recovery_origin") == "unknown_status_attempt" for record in records
    )
    if needs_resolved_lineage and selection_path is None:
        raise CommandError(
            "unknown-origin material requires --selection for exact lineage"
        )
    clearance_kwargs: dict[str, Any] = {}
    clearance_lineage_paths: tuple[Path, ...] = ()
    if needs_resolved_lineage and not is_materialized:
        clearance_kwargs, clearance_lineage_paths = (
            _authenticated_clearance_lineage_inputs(args, clearance_path=clearance_path)
        )
    try:
        require_cleared_documents(
            records,
            document_root=document_root,
            clearance_records=clearance_records,
        )
        if needs_resolved_lineage and not is_materialized:
            _require_resolved_post_recovery_dispatch(
                selection_records=selection_records,
                download_records=records,
                clearance_records=clearance_records,
                resolved_records=resolved_records,
                **clearance_kwargs,
            )
    except (DisclosureClearanceError, ResolvedPostRecoveryError, OSError) as exc:
        raise CommandError(str(exc)) from exc
    if is_materialized:
        purchase_lineage_paths, purchase_state_sha256 = (), None
    else:
        purchase_lineage_paths, purchase_state_sha256 = (
            _require_current_purchase_lineage(
                args,
                needs_resolved_lineage=needs_resolved_lineage,
                resolved_records=resolved_records,
                clearance_kwargs=clearance_kwargs,
            )
        )
    resolved_index = {
        (
            _required_str(record, "candidate_id"),
            _required_str(record, "source_document_id"),
        ): record
        for record in resolved_records
    }
    request_records = tuple(
        {
            **_planned_parse_document_request(
                record,
                document_root=document_root,
                markdown_output_root=markdown_output_root,
            ),
            **(
                {
                    "recovery_origin": "unknown_status_attempt",
                    "resolved_post_recovery_sha256": _required_str(
                        resolved_index[
                            (
                                _required_str(record, "candidate_id"),
                                _required_str(record, "source_document_id"),
                            )
                        ],
                        "record_sha256",
                    ),
                }
                if (
                    _required_str(record, "candidate_id"),
                    _required_str(record, "source_document_id"),
                )
                in resolved_index
                else {}
            ),
        }
        for record in records
    )
    completion_input_paths = (
        *((selection_path,) if selection_path is not None else ()),
        download_manifest_path,
        clearance_path,
        *materialization_paths,
        *clearance_lineage_paths,
        *(
            (resolved_path,)
            if resolved_path is not None and not is_materialized
            else ()
        ),
        *purchase_lineage_paths,
    )
    completion_input_snapshots = _snapshot_regular_input_paths(
        completion_input_paths,
        label="plan-parse-documents input",
        captured_artifact_bytes=(
            materialization_lineage.artifact_bytes
            if materialization_lineage is not None
            else None
        ),
    )
    if dry_run:
        output_records: Sequence[Mapping[str, Any]] = (
            {
                "stage": "plan-parse-documents",
                "dry_run": True,
                "request_count": len(request_records),
            },
        )
    else:
        output_records = request_records
    requests_bytes = _projection_jsonl_bytes(output_records)
    _write_jsonl(requests_path, output_records)
    _require_snapshot_unchanged(
        completion_input_snapshots, label="plan-parse-documents input"
    )
    _write_acquisition_completion(
        args,
        stage="plan-parse-documents",
        input_paths=completion_input_paths,
        output_paths=(requests_path,),
        record_count=len(request_records),
        dry_run=dry_run,
        paid_activity_requested=False,
        paid_activity_executed=False,
        extra={
            "source_commitments": {
                f"input_{index:02d}": {
                    "path": str(path.resolve()),
                    "sha256": _bytes_sha256(completion_input_snapshots[path]),
                }
                for index, path in enumerate(completion_input_paths)
            },
            "output_commitments": (
                {}
                if dry_run
                else {
                    "parse_requests": {
                        "path": str(requests_path.resolve()),
                        "sha256": _bytes_sha256(requests_bytes),
                    }
                }
            ),
            "purchase_state_sha256": purchase_state_sha256,
        },
    )
    return 0


def _cmd_acquisition_parse_documents(args: argparse.Namespace) -> int:
    """Convert the planned immutable PDFs to Markdown."""

    with cache_disclosure_document_scans():
        return _cmd_acquisition_parse_documents_cached(args)


def _cmd_acquisition_parse_documents_cached(args: argparse.Namespace) -> int:
    _preflight_materialization_purchase_runtime(args)
    dry_run = _acquisition_dry_run(args)
    reuse_run_card_path = cast(
        Path | None, getattr(args, "reuse_live_mistral_run_card", None)
    )
    reuse_markdown_root = cast(Path | None, getattr(args, "reuse_markdown_root", None))
    if (reuse_run_card_path is None) != (reuse_markdown_root is None):
        raise CommandError(
            "--reuse-live-mistral-run-card and --reuse-markdown-root must be "
            "used together"
        )
    if reuse_run_card_path is not None:
        if dry_run:
            raise CommandError("live-Mistral parse reuse requires --execute")
        if not cast(bool, args.resume):
            raise CommandError("live-Mistral parse reuse requires --resume")
        if cast(Path | None, getattr(args, "fixture_markdown_dir", None)) is not None:
            raise CommandError("live-Mistral parse reuse cannot use fixture Markdown")
    if not dry_run and cast(Path | None, args.materialization_run_card) is None:
        raise CommandError(
            "executed parsing requires canonical materialized documents and "
            "--materialization-run-card"
        )
    selection_path = cast(Path | None, args.selection)
    requests_path = cast(Path, args.requests)
    clearance_path = cast(Path, args.disclosure_clearance)
    resolved_path = cast(Path | None, args.resolved_post_recovery_documents)
    materialization_card_path = cast(Path | None, args.materialization_run_card)
    materialization_lineage: _VerifiedMaterializedDownstreamLineage | None = None
    materialization_card_bytes: bytes | None = None
    materialized_document_root: Path | None = None
    if materialization_card_path is not None:
        materialization_card_bytes = _read_singly_linked_regular_input(
            materialization_card_path, label="parse materialization run card"
        )
        materialization_card = _projection_json_object(
            materialization_card_bytes, source=materialization_card_path
        )
        materialization_outputs = materialization_card.get("output_paths")
        if not isinstance(materialization_outputs, Sequence) or isinstance(
            materialization_outputs, (str, bytes)
        ):
            raise CommandError("materialization run card lacks exact outputs")
        materialization_output_paths = tuple(
            Path(str(path)) for path in cast(Sequence[object], materialization_outputs)
        )
        if len(materialization_output_paths) != 6:
            raise CommandError("materialization run card output paths differ")
        materialized_document_root = materialization_output_paths[5]
        materialization_lineage = _verify_materialized_downstream_lineage(
            run_card_path=materialization_card_path,
            manifest_path=materialization_output_paths[0],
            clearance_path=clearance_path,
            document_root=materialization_output_paths[5],
            selection_path=selection_path,
            controlled_private_root=cast(Path | None, args.controlled_private_root),
            initialization_receipt_path=cast(
                Path | None, args.purchase_ledger_initialization_receipt
            ),
        )
    output_root = cast(Path, args.output_root)
    manifest_path = _acquisition_path(
        args,
        "manifest_output",
        output_root / "mistral-markdown-conversions.jsonl",
    )
    request_bytes = _read_singly_linked_regular_input(
        requests_path, label="parse document requests"
    )
    request_records = _projection_jsonl_records(request_bytes, source=requests_path)
    if materialization_lineage is not None:
        clearance_records = list(materialization_lineage.clearance_records)
    else:
        clearance_records = _read_records(clearance_path)
    is_materialized = _require_consistent_materialization_markers(
        request_records, clearance_records
    )
    if is_materialized and materialization_card_path is None:
        raise CommandError(
            "materialized parse requests require --materialization-run-card"
        )
    if not is_materialized and materialization_card_path is not None:
        raise CommandError(
            "--materialization-run-card requires exact materialization markers"
        )
    if not dry_run and not is_materialized:
        raise CommandError(
            "executed parsing requires canonical materialized documents and "
            "--materialization-run-card"
        )
    materialization_paths: Sequence[Path] = ()
    if materialization_card_path is not None:
        if materialization_lineage is None:
            raise CommandError("materialization lineage verification was skipped")
        materialization_paths = materialization_lineage.paths
        committed_resolved_path = (
            materialization_paths[3] if len(materialization_paths) == 4 else None
        )
        if resolved_path is not None and (
            committed_resolved_path is None
            or resolved_path.resolve() != committed_resolved_path.resolve()
        ):
            raise CommandError(
                "--resolved-post-recovery-documents differs from materialization"
            )
        resolved_path = committed_resolved_path
    selection_records = (
        list(materialization_lineage.selection_records)
        if materialization_lineage is not None
        else (_read_records(selection_path) if selection_path is not None else [])
    )
    resolved_lineage_selection_records = (
        list(materialization_lineage.resolved_lineage_selection_records)
        if materialization_lineage is not None
        and materialization_lineage.resolved_lineage_selection_records is not None
        else selection_records
    )
    resolved_records = (
        list(materialization_lineage.resolved_records)
        if materialization_lineage is not None
        else (_read_records(resolved_path) if resolved_path is not None else [])
    )
    stable_parse_inputs = {requests_path: request_bytes}
    if materialization_card_path is not None and materialization_card_bytes is not None:
        stable_parse_inputs[materialization_card_path] = materialization_card_bytes
    _require_snapshot_unchanged(
        stable_parse_inputs, label="parse materialization input"
    )
    needs_resolved_lineage = (
        _selection_requires_resolved_post_recovery(resolved_lineage_selection_records)
        or any(
            record.get("recovery_origin") == "unknown_status_attempt"
            for record in request_records
        )
        or bool(resolved_records)
    )
    if needs_resolved_lineage and selection_path is None:
        raise CommandError(
            "unknown-origin material requires --selection for exact lineage"
        )
    clearance_lineage_paths: tuple[Path, ...] = ()
    _clearance_kwargs: dict[str, Any] = {}
    if needs_resolved_lineage and not is_materialized:
        _clearance_kwargs, clearance_lineage_paths = (
            _authenticated_clearance_lineage_inputs(args, clearance_path=clearance_path)
        )
    if not dry_run:
        try:
            require_cleared_parse_requests(request_records, clearance_records)
            if needs_resolved_lineage:
                parse_clearance_kwargs = _clearance_kwargs
                if is_materialized and materialization_lineage is not None:
                    recovered_capability = (
                        materialization_lineage.recovered_public_capability
                    )
                    consolidated_capability = (
                        materialization_lineage.consolidated_recovery_capability
                    )
                    if (
                        recovered_capability is not None
                        and consolidated_capability is not None
                    ):
                        raise CommandError(
                            "materialization has conflicting recovery capabilities"
                        )
                    parse_clearance_kwargs = {
                        **(
                            {"_verified_recovery_capability": recovered_capability}
                            if recovered_capability is not None
                            else {}
                        ),
                        **(
                            {
                                "_verified_consolidated_recovery_capability": (
                                    consolidated_capability
                                )
                            }
                            if consolidated_capability is not None
                            else {}
                        ),
                    }
                _require_resolved_parse_requests_dispatch(
                    clearance_kwargs=parse_clearance_kwargs,
                    selection_records=resolved_lineage_selection_records,
                    request_records=request_records,
                    resolved_records=resolved_records,
                )
            for request_record in request_records:
                verify_parse_request_bytes(request_record)
        except (DisclosureClearanceError, ResolvedPostRecoveryError) as exc:
            raise CommandError(str(exc)) from exc
    if is_materialized:
        purchase_lineage_paths, purchase_state_sha256 = (), None
    else:
        purchase_lineage_paths, purchase_state_sha256 = (
            _require_current_purchase_lineage(
                args,
                needs_resolved_lineage=needs_resolved_lineage,
                resolved_records=resolved_records,
                clearance_kwargs=_clearance_kwargs,
            )
        )
    completion_input_paths = (
        *((selection_path,) if selection_path is not None else ()),
        requests_path,
        clearance_path,
        *materialization_paths,
        *clearance_lineage_paths,
        *(
            (resolved_path,)
            if resolved_path is not None and not is_materialized
            else ()
        ),
        *purchase_lineage_paths,
    )
    completion_input_snapshots = _snapshot_regular_input_paths(
        completion_input_paths,
        label="parse-documents input",
        captured_artifact_bytes=(
            materialization_lineage.artifact_bytes
            if materialization_lineage is not None
            else None
        ),
    )
    if completion_input_snapshots[requests_path] != request_bytes:
        raise CommandError("parse document requests changed during execution")
    if (
        materialization_card_path is not None
        and materialization_card_bytes is not None
        and completion_input_snapshots[materialization_card_path]
        != materialization_card_bytes
    ):
        raise CommandError("parse materialization run card changed during execution")
    document_source_snapshots = (
        dict(materialization_lineage.document_tree)
        if materialization_lineage is not None
        else {}
    )
    requests = tuple(
        _mistral_markdown_request(
            record,
            output_root=output_root,
            captured_source_bytes=(
                document_source_snapshots.get(
                    Path(_required_str(record, "input_path"))
                    .resolve()
                    .relative_to(cast(Path, materialized_document_root).resolve())
                    .as_posix()
                )
                if materialization_lineage is not None and document_source_snapshots
                else None
            ),
        )
        for record in request_records
    )
    if (
        materialization_lineage is not None
        and document_source_snapshots
        and any(request.captured_source_bytes is None for request in requests)
    ):
        raise CommandError(
            "parse source is missing from materialized document snapshot"
        )
    fixture_markdown_dir = cast(Path | None, args.fixture_markdown_dir)
    parser_root = cast(Path | None, args.parser_root)
    _acquisition_output_root(args)
    source_commitments = _parse_document_source_commitments(
        completion_input_snapshots=completion_input_snapshots,
        requests_path=requests_path,
        clearance_path=clearance_path,
        selection_path=selection_path,
        materialization_card_path=materialization_card_path,
        clearance_lineage_paths=clearance_lineage_paths,
        resolved_path=resolved_path,
        purchase_lineage_paths=purchase_lineage_paths,
    )
    effective_parser_root = (
        MistralParserConfig().parser_root if parser_root is None else parser_root
    )
    reuse_source: JsonRecord | None = None
    completed_reuse: tuple[tuple[JsonRecord, ...], JsonRecord] | None = None
    if not dry_run and reuse_run_card_path is not None:
        if reuse_markdown_root is None:
            raise AssertionError("reuse Markdown root was not validated")
        completed_reuse = _authenticate_completed_current_mistral_reuse(
            run_card_path=_acquisition_path(
                args,
                "run_card_output",
                output_root / "run-cards" / "parse-documents.json",
            ),
            manifest_path=manifest_path,
            requests=requests,
            output_root=output_root,
            input_paths=completion_input_paths,
            source_commitments=source_commitments,
            purchase_state_sha256=purchase_state_sha256,
            effective_parser_root=effective_parser_root,
            prior_run_card_path=reuse_run_card_path,
            prior_markdown_root=reuse_markdown_root,
        )
        if completed_reuse is not None:
            _require_snapshot_unchanged(
                completion_input_snapshots, label="parse-documents input"
            )
            if (
                materialization_lineage is not None
                and document_source_snapshots
                and _materializer_tree_snapshot(cast(Path, materialized_document_root))
                != document_source_snapshots
            ):
                raise CommandError(
                    "parse materialized document tree changed during execution"
                )
            return 0
    if dry_run:
        output_records: Sequence[Mapping[str, Any]] = (
            {
                "stage": "parse-documents",
                "dry_run": True,
                "request_count": len(requests),
                "parser_root": str(cast(Path | None, args.parser_root)),
            },
        )
    else:
        if reuse_run_card_path is not None:
            if reuse_markdown_root is None:
                raise AssertionError("reuse Markdown root was not validated")
            reuse_plan = _reuse_live_mistral_parse_outputs(
                prior_run_card_path=reuse_run_card_path,
                prior_markdown_root=reuse_markdown_root,
                requests=requests,
                output_root=output_root,
            )
            gap_records = (
                convert_documents_to_markdown(
                    reuse_plan.gaps,
                    config=MistralParserConfig(
                        parser_root=(
                            MistralParserConfig().parser_root
                            if parser_root is None
                            else parser_root
                        ),
                        timeout_seconds=cast(int, args.timeout_seconds),
                    ),
                )
                if reuse_plan.gaps
                else ()
            )
            parsed_gap_records = tuple(
                {
                    **record.to_record(),
                    "source_sha256": cast(str, request.expected_sha256),
                    "source_byte_count": cast(int, request.expected_byte_count),
                }
                for record, request in zip(gap_records, reuse_plan.gaps, strict=True)
            )
            parsed_gap_by_key = _parse_reuse_record_index(
                parsed_gap_records, label="fresh parser gap manifest"
            )
            expected_gap_by_key = _parse_reuse_request_object_index(
                reuse_plan.gaps, label="fresh parser gap requests"
            )
            if set(parsed_gap_by_key) != set(expected_gap_by_key):
                raise CommandError("fresh parser gap outputs differ from requests")
            for key, record in parsed_gap_by_key.items():
                _require_reuse_record_matches_current_output(
                    record,
                    destination_markdown=expected_gap_by_key[key].markdown_output_path,
                    output_root=output_root,
                )
            combined_by_key = {
                **reuse_plan.records_by_key,
                **parsed_gap_by_key,
            }
            output_records = tuple(
                combined_by_key[
                    (
                        request.candidate_id,
                        request.source_document_id,
                        cast(str, request.expected_sha256),
                        cast(int, request.expected_byte_count),
                    )
                ]
                for request in requests
            )
            reuse_source = reuse_plan.source
        elif fixture_markdown_dir is None:
            records = convert_documents_to_markdown(
                requests,
                config=MistralParserConfig(
                    parser_root=(
                        MistralParserConfig().parser_root
                        if parser_root is None
                        else parser_root
                    ),
                    timeout_seconds=cast(int, args.timeout_seconds),
                ),
            )
            output_records = tuple(
                {
                    **record.to_record(),
                    "source_sha256": _required_str(request, "expected_sha256"),
                    "source_byte_count": _required_int(request, "expected_byte_count"),
                }
                for record, request in zip(records, request_records, strict=True)
            )
        else:
            records = _fixture_markdown_conversion_records(
                requests,
                fixture_markdown_dir=fixture_markdown_dir,
                generated_at=datetime.now(UTC),
            )
            output_records = tuple(
                {
                    **record.to_record(),
                    "source_sha256": _required_str(request, "expected_sha256"),
                    "source_byte_count": _required_int(request, "expected_byte_count"),
                }
                for record, request in zip(records, request_records, strict=True)
            )
    manifest_bytes = _projection_jsonl_bytes(output_records)
    if reuse_source is not None:
        _write_immutable_bytes(manifest_path, manifest_bytes, resume=True)
    else:
        _write_jsonl(manifest_path, output_records)
    _require_snapshot_unchanged(
        completion_input_snapshots, label="parse-documents input"
    )
    if (
        materialization_lineage is not None
        and document_source_snapshots
        and _materializer_tree_snapshot(cast(Path, materialized_document_root))
        != document_source_snapshots
    ):
        raise CommandError("parse materialized document tree changed during execution")
    output_commitments = (
        {}
        if dry_run
        else {
            "parser_manifest": {
                "path": str(manifest_path.resolve()),
                "sha256": _bytes_sha256(manifest_bytes),
            }
        }
    )
    _write_acquisition_completion(
        args,
        stage="parse-documents",
        input_paths=completion_input_paths,
        output_paths=(manifest_path,),
        record_count=len(requests),
        dry_run=dry_run,
        paid_activity_requested=False,
        paid_activity_executed=False,
        extra={
            "source_commitments": source_commitments,
            "output_commitments": output_commitments,
            "parser_execution": {
                "mode": (
                    "live_mistral"
                    if fixture_markdown_dir is None
                    else "fixture_markdown"
                ),
                "engine": (
                    "mistral" if fixture_markdown_dir is None else "fixture_markdown"
                ),
                "parser_revision": (
                    EXPECTED_PARSER_REVISION if fixture_markdown_dir is None else None
                ),
                "parser_root": str(effective_parser_root.expanduser().resolve()),
                "fixture_markdown": fixture_markdown_dir is not None,
                **(
                    {
                        "reused_authenticated_output": True,
                        "reused_live_mistral": reuse_source,
                    }
                    if reuse_source is not None
                    else {}
                ),
            },
            "purchase_state_sha256": purchase_state_sha256,
        },
    )
    return 0


def _parse_document_source_commitments(
    *,
    completion_input_snapshots: Mapping[Path, bytes],
    requests_path: Path,
    clearance_path: Path,
    selection_path: Path | None,
    materialization_card_path: Path | None,
    clearance_lineage_paths: Sequence[Path],
    resolved_path: Path | None,
    purchase_lineage_paths: Sequence[Path],
) -> JsonRecord:
    return {
        "requests": {
            "path": str(requests_path.resolve()),
            "sha256": _bytes_sha256(completion_input_snapshots[requests_path]),
        },
        "disclosure_clearance": {
            "path": str(clearance_path.resolve()),
            "sha256": _bytes_sha256(completion_input_snapshots[clearance_path]),
        },
        **(
            {
                "selection": {
                    "path": str(selection_path.resolve()),
                    "sha256": _bytes_sha256(completion_input_snapshots[selection_path]),
                }
            }
            if selection_path is not None
            else {}
        ),
        **(
            {
                "materialization_run_card": {
                    "path": str(materialization_card_path.resolve()),
                    "sha256": _bytes_sha256(
                        completion_input_snapshots[materialization_card_path]
                    ),
                }
            }
            if materialization_card_path is not None
            else {}
        ),
        **{
            f"clearance_lineage_{index:02d}": {
                "path": str(path.resolve()),
                "sha256": _bytes_sha256(completion_input_snapshots[path]),
            }
            for index, path in enumerate(clearance_lineage_paths)
        },
        **(
            {
                "resolved_post_recovery_documents": {
                    "path": str(resolved_path.resolve()),
                    "sha256": _bytes_sha256(completion_input_snapshots[resolved_path]),
                }
            }
            if resolved_path is not None
            else {}
        ),
        **{
            f"purchase_lineage_{index:02d}": {
                "path": str(path.resolve()),
                "sha256": _bytes_sha256(completion_input_snapshots[path]),
            }
            for index, path in enumerate(purchase_lineage_paths)
        },
    }


def _authenticate_completed_current_mistral_reuse(
    *,
    run_card_path: Path,
    manifest_path: Path,
    requests: Sequence[MistralMarkdownConversionRequest],
    output_root: Path,
    input_paths: Sequence[Path],
    source_commitments: Mapping[str, object],
    purchase_state_sha256: str | None,
    effective_parser_root: Path,
    prior_run_card_path: Path,
    prior_markdown_root: Path,
) -> tuple[tuple[JsonRecord, ...], JsonRecord] | None:
    """Authenticate a completed mixed reuse run before treating resume as a no-op."""

    card_exists = run_card_path.exists() or run_card_path.is_symlink()
    manifest_exists = manifest_path.exists() or manifest_path.is_symlink()
    if not card_exists and not manifest_exists:
        return None
    if card_exists != manifest_exists:
        raise CommandError("completed parse reuse has a partial terminal output")

    prior = _authenticate_live_mistral_parse_reuse(
        prior_run_card_path=prior_run_card_path,
        prior_markdown_root=prior_markdown_root,
    )
    current_by_key = _parse_reuse_request_object_index(
        requests, label="completed current parse requests"
    )
    expected_reuse_source: JsonRecord = {
        **prior.source,
        "reused_record_count": len(set(prior.artifacts_by_key) & set(current_by_key)),
        "parsed_gap_count": len(set(current_by_key) - set(prior.artifacts_by_key)),
    }

    card_bytes = _read_singly_linked_regular_input(
        run_card_path, label="completed current parse run card"
    )
    card = _projection_json_object(card_bytes, source=run_card_path)
    _require_reusable_live_mistral_run_card(card)
    execution = cast(Mapping[str, object], card["parser_execution"])
    generated_at = card.get("generated_at")
    if (
        card.get("resume") is not True
        or card.get("record_count") != len(requests)
        or card.get("input_paths") != [str(path) for path in input_paths]
        or card.get("output_paths") != [str(manifest_path)]
        or card.get("paid_activity_requested") is not False
        or card.get("paid_activity_executed") is not False
        or card.get("source_commitments") != source_commitments
        or card.get("purchase_state_sha256") != purchase_state_sha256
        or not isinstance(generated_at, str)
        or not generated_at.strip()
        or execution.get("parser_root")
        != str(effective_parser_root.expanduser().resolve())
        or execution.get("reused_authenticated_output") is not True
        or execution.get("reused_live_mistral") != expected_reuse_source
    ):
        raise CommandError("completed current parse reuse card differs")

    manifest_bytes = _read_singly_linked_regular_input(
        manifest_path, label="completed current parser manifest"
    )
    if card.get("output_commitments") != {
        "parser_manifest": {
            "path": str(manifest_path.resolve()),
            "sha256": _bytes_sha256(manifest_bytes),
        }
    }:
        raise CommandError("completed current parser manifest commitment differs")
    records = tuple(_projection_jsonl_records(manifest_bytes, source=manifest_path))
    if len(records) != len(requests):
        raise CommandError("completed current parser manifest count differs")
    record_index = _parse_reuse_record_index(
        records, label="completed current parser manifest"
    )
    expected_keys = tuple(current_by_key)
    actual_keys = tuple(
        _parse_reuse_key(record, label="completed current parser manifest")
        for record in records
    )
    if actual_keys != expected_keys or set(record_index) != set(current_by_key):
        raise CommandError("completed current parser manifest order differs")
    for key, request in current_by_key.items():
        record = record_index[key]
        _require_reuse_record_matches_request(
            record,
            {
                "candidate_id": request.candidate_id,
                "source_document_id": request.source_document_id,
                "expected_sha256": request.expected_sha256,
                "expected_byte_count": request.expected_byte_count,
            },
            label="completed current parser manifest",
        )
        _require_reuse_record_matches_current_output(
            record,
            destination_markdown=request.markdown_output_path,
            output_root=output_root,
        )
        metadata_path = request.markdown_output_path.with_suffix(".metadata.json")
        markdown_bytes = _read_singly_linked_regular_input(
            request.markdown_output_path, label="completed current Markdown"
        )
        metadata_bytes = _read_singly_linked_regular_input(
            metadata_path, label="completed current Markdown metadata"
        )
        try:
            markdown = markdown_bytes.decode("utf-8")
        except UnicodeDecodeError as exc:
            raise CommandError("completed current Markdown is not UTF-8") from exc
        if _projection_json_object(metadata_bytes, source=metadata_path) != record:
            raise CommandError("completed current Markdown metadata differs")
        _require_reusable_live_mistral_record(record, markdown=markdown)
    return records, expected_reuse_source


def _fixture_rehearsal_input_commitment(path: Path) -> JsonRecord:
    if path.is_symlink():
        raise CommandError(f"fixture rehearsal input is a symlink: {path}")
    if path.is_file():
        return {
            "kind": "file",
            "path": str(path.resolve()),
            "sha256": _path_sha256(path),
            "byte_count": path.stat(follow_symlinks=False).st_size,
        }
    if path.is_dir():
        tree = _materializer_tree_commitments(path)
        return {
            "kind": "directory",
            "path": str(path.resolve()),
            "tree_sha256": _canonical_json_sha256(tree),
            "files": tree,
        }
    raise CommandError(f"fixture rehearsal input is missing: {path}")


def _write_fixture_rehearsal_artifact(
    path: Path,
    records: Sequence[Mapping[str, Any]],
    *,
    stage: str,
) -> tuple[Path, Path]:
    live_shaped_records = tuple(dict(record) for record in records)
    _write_jsonl(path, live_shaped_records)
    sidecar_path = Path(str(path) + ".fixture-artifact.json")
    _write_json(
        sidecar_path,
        {
            **REHEARSAL_PROVENANCE,
            "schema_version": "legalforecast.fixture_artifact_manifest.v1",
            "stage": stage,
            "artifact_path": str(path.resolve()),
            "artifact_sha256": _path_sha256(path),
            "artifact_byte_count": path.stat(follow_symlinks=False).st_size,
            "record_count": len(live_shaped_records),
        },
    )
    return path, sidecar_path


def _write_fixture_rehearsal_json_artifact(
    path: Path,
    payload: Mapping[str, Any],
    *,
    stage: str,
) -> tuple[Path, Path]:
    _write_json(path, {**REHEARSAL_PROVENANCE, **dict(payload)})
    sidecar_path = Path(str(path) + ".fixture-artifact.json")
    _write_json(
        sidecar_path,
        {
            **REHEARSAL_PROVENANCE,
            "schema_version": "legalforecast.fixture_artifact_manifest.v1",
            "stage": stage,
            "artifact_path": str(path.resolve()),
            "artifact_sha256": _path_sha256(path),
            "artifact_byte_count": path.stat(follow_symlinks=False).st_size,
            "record_count": 1,
        },
    )
    return path, sidecar_path


def _fixture_rehearsal_sidecar_path(path: Path) -> Path:
    return Path(str(path) + ".fixture-artifact.json")


def _write_fixture_rehearsal_json_sidecar(path: Path, *, stage: str) -> Path:
    sidecar_path = _fixture_rehearsal_sidecar_path(path)
    _write_json(
        sidecar_path,
        {
            **REHEARSAL_PROVENANCE,
            "schema_version": "legalforecast.fixture_artifact_manifest.v1",
            "stage": stage,
            "artifact_path": str(path.resolve()),
            "artifact_sha256": _path_sha256(path),
            "artifact_byte_count": path.stat(follow_symlinks=False).st_size,
            "record_count": 1,
        },
    )
    return sidecar_path


def _fixture_rehearsal_record_count(path: Path) -> int:
    if path.suffix == ".jsonl":
        return len(_read_records(path))
    if path.suffix == ".json":
        _read_json_object(path)
        return 1
    raise CommandError(f"unsupported fixture artifact type: {path}")


def _verify_fixture_rehearsal_artifact(
    path: Path,
    *,
    sidecar_path: Path,
    stage: str,
) -> None:
    if path.is_symlink() or not path.is_file():
        raise CommandError(f"fixture stage artifact is missing or unsafe: {path}")
    if sidecar_path.is_symlink() or not sidecar_path.is_file():
        raise CommandError(
            f"fixture stage artifact sidecar is missing or unsafe: {sidecar_path}"
        )
    sidecar = _read_json_object(sidecar_path)
    if (
        sidecar.get("schema_version") != "legalforecast.fixture_artifact_manifest.v1"
        or sidecar.get("stage") != stage
        or sidecar.get("artifact_path") != str(path.resolve())
        or sidecar.get("artifact_sha256") != _path_sha256(path)
        or sidecar.get("artifact_byte_count")
        != path.stat(follow_symlinks=False).st_size
        or sidecar.get("record_count") != _fixture_rehearsal_record_count(path)
        or any(
            sidecar.get(key) != value
            for key, value in REHEARSAL_PROVENANCE.items()
            if key != "schema_version"
        )
    ):
        raise CommandError(f"invalid fixture artifact sidecar: {path}")


def _verify_fixture_rehearsal_stage_card(
    stage_card_path: Path,
    *,
    stage: str,
    input_commitments: Mapping[str, JsonRecord],
    prior_stage_card_path: Path | None,
    expected_record_count: int,
    expected_primary_paths: Sequence[Path] | None = None,
) -> JsonRecord:
    if stage_card_path.is_symlink() or not stage_card_path.is_file():
        raise CommandError(f"fixture rehearsal stage card is missing: {stage}")
    _verify_fixture_rehearsal_artifact(
        stage_card_path,
        sidecar_path=_fixture_rehearsal_sidecar_path(stage_card_path),
        stage=stage,
    )
    stage_card = _read_json_object(stage_card_path)
    prior_stage = prior_stage_card_path.stem if prior_stage_card_path else None
    prior_stage_sha256 = (
        _path_sha256(prior_stage_card_path) if prior_stage_card_path else None
    )
    if (
        stage_card.get("schema_version") != "legalforecast.fixture_stage_run_card.v1"
        or stage_card.get("stage") != stage
        or stage_card.get("status") != "completed"
        or stage_card.get("execute") is not True
        or stage_card.get("record_count") != expected_record_count
        or stage_card.get("prior_stage") != prior_stage
        or stage_card.get("prior_stage_card_sha256") != prior_stage_sha256
        or _required_record(stage_card, "input_commitments") != input_commitments
        or any(
            stage_card.get(key) != value
            for key, value in REHEARSAL_PROVENANCE.items()
            if key != "schema_version"
        )
    ):
        raise CommandError(f"invalid fixture stage card: {stage}")
    stage_outputs = _required_record(stage_card, "output_commitments")
    output_paths = tuple(Path(raw_path) for raw_path in stage_outputs)
    sidecars = {
        Path(str(path).removesuffix(".fixture-artifact.json")): path
        for path in output_paths
        if str(path).endswith(".fixture-artifact.json")
    }
    primary_paths = tuple(
        path for path in output_paths if path not in sidecars.values()
    )
    if set(primary_paths) != set(sidecars):
        raise CommandError(f"fixture stage artifacts lack mandatory sidecars: {stage}")
    if expected_primary_paths is not None and set(primary_paths) != {
        path.resolve() for path in expected_primary_paths
    }:
        raise CommandError(f"fixture stage output paths differ: {stage}")
    for output_path, expected_sha256 in stage_outputs.items():
        path = Path(output_path)
        if path.is_symlink() or not path.is_file():
            raise CommandError(f"fixture stage output is missing or unsafe: {path}")
        if expected_sha256 != _path_sha256(path):
            raise CommandError(f"fixture stage output commitment changed: {path}")
    for primary_path in primary_paths:
        _verify_fixture_rehearsal_artifact(
            primary_path,
            sidecar_path=sidecars[primary_path],
            stage=stage,
        )
    return stage_card


def _complete_fixture_rehearsal_stage(
    args: argparse.Namespace,
    *,
    stage: str,
    input_paths: Sequence[Path],
    input_commitments: Mapping[str, JsonRecord],
    artifacts: Sequence[tuple[Path, Path]],
    record_count: int,
    prior_stage: str | None,
    fixture_traces: Sequence[Mapping[str, Any]] = (),
    expected_prior_stage_card_sha256: str | None = None,
    expected_prior_stage_record_count: int | None = None,
) -> int:
    observed = {
        str(path.resolve()): _fixture_rehearsal_input_commitment(path)
        for path in input_paths
    }
    if observed != input_commitments:
        raise CommandError("fixture rehearsal input changed during stage execution")
    output_paths = tuple(path for pair in artifacts for path in pair)
    output_commitments = {
        str(path.resolve()): _path_sha256(path) for path in output_paths
    }
    prior_card_path = (
        _acquisition_output_root(args) / "run-cards" / f"{prior_stage}.json"
        if prior_stage is not None
        else None
    )
    if prior_card_path is not None:
        assert prior_stage is not None
        if expected_prior_stage_record_count is None:
            raise CommandError(
                f"fixture rehearsal prior stage record count is required: {prior_stage}"
            )
        if prior_card_path.is_symlink() or not prior_card_path.is_file():
            raise CommandError(
                f"fixture rehearsal prior stage card is missing: {prior_stage}"
            )
        prior_card_sha256 = _path_sha256(prior_card_path)
        if (
            expected_prior_stage_card_sha256 is not None
            and prior_card_sha256 != expected_prior_stage_card_sha256
        ):
            raise CommandError(
                f"fixture rehearsal prior stage card changed: {prior_stage}"
            )
        prior_card = _read_json_object(prior_card_path)
        raw_prior_stage = prior_card.get("prior_stage")
        prior_prior_card_path = (
            _acquisition_output_root(args) / "run-cards" / f"{raw_prior_stage}.json"
            if isinstance(raw_prior_stage, str)
            else None
        )
        _verify_fixture_rehearsal_stage_card(
            prior_card_path,
            stage=prior_stage,
            input_commitments=input_commitments,
            prior_stage_card_path=prior_prior_card_path,
            expected_record_count=expected_prior_stage_record_count,
        )
    else:
        prior_card_sha256 = None
    _write_acquisition_completion(
        args,
        stage=stage,
        input_paths=(*input_paths, *((prior_card_path,) if prior_card_path else ())),
        output_paths=output_paths,
        record_count=record_count,
        dry_run=False,
        paid_activity_requested=False,
        paid_activity_executed=False,
        extra={
            **REHEARSAL_PROVENANCE,
            "schema_version": "legalforecast.fixture_stage_run_card.v1",
            "input_commitments": dict(input_commitments),
            "output_commitments": output_commitments,
            "prior_stage": prior_stage,
            "prior_stage_card_sha256": prior_card_sha256,
            "fixture_traces": list(fixture_traces),
            "provider_journal_created": False,
            "provider_billing_usd": "0.00",
        },
    )
    stage_card_path = _acquisition_path(
        args,
        "run_card_output",
        _acquisition_output_root(args) / "run-cards" / f"{stage}.json",
    )
    _write_fixture_rehearsal_json_sidecar(stage_card_path, stage=stage)
    return 0


def _cmd_acquisition_rehearse_downstream(args: argparse.Namespace) -> int:
    """Exercise the downstream chain without creating production authority."""

    if _acquisition_dry_run(args):
        raise CommandError(
            "rehearse-downstream is already provider-free and requires --execute"
        )
    _preflight_materialization_purchase_runtime(args)
    selection_path = cast(Path, args.selection)
    selection_card_path = cast(Path, args.selection_run_card)
    manifest_path = cast(Path, args.download_manifest)
    clearance_path = cast(Path, args.disclosure_clearance)
    restriction_path = cast(Path, args.restriction_evidence)
    materialization_card_path = cast(Path, args.materialization_run_card)
    parse_plan_card_path = cast(Path, args.parse_plan_run_card)
    parse_requests_path = cast(Path, args.parse_requests)
    parser_manifest_path = cast(Path, args.parser_manifest)
    parser_card_path = cast(Path, args.parser_run_card)
    document_root = cast(Path, args.document_root)
    markdown_root = cast(Path, args.markdown_root)
    raw_html_dir = cast(Path, args.raw_html_dir)
    response_fixture_path = cast(Path, args.response_fixtures)
    target_count = cast(int, args.target_case_count)
    if target_count <= 0:
        raise CommandError("--target-case-count must be positive")
    try:
        verified_materialization = _verify_materialized_downstream_lineage(
            run_card_path=materialization_card_path,
            manifest_path=manifest_path,
            clearance_path=clearance_path,
            document_root=document_root,
            selection_path=selection_path,
            controlled_private_root=cast(Path | None, args.controlled_private_root),
            initialization_receipt_path=cast(
                Path | None, args.purchase_ledger_initialization_receipt
            ),
        )
    except (CommandError, OSError) as exc:
        raise CommandError(str(exc)) from exc
    input_paths = (
        selection_path,
        selection_card_path,
        manifest_path,
        clearance_path,
        restriction_path,
        materialization_card_path,
        parse_plan_card_path,
        parse_requests_path,
        parser_manifest_path,
        parser_card_path,
        document_root,
        markdown_root,
        raw_html_dir,
        cast(Path, args.unitizer_model_registry),
        cast(Path, args.reviewer_model_registry),
        cast(Path, args.judge_model_registry),
        cast(Path, args.evaluated_model_registry),
        response_fixture_path,
    )
    for path in input_paths:
        if path.is_symlink() or not path.exists():
            raise CommandError(f"rehearsal input is missing or a symlink: {path}")
    rehearsal_file_snapshots = {
        path: _read_singly_linked_regular_input(path, label="rehearsal input")
        for path in input_paths
        if path.is_file()
    }

    def require_rehearsal_inputs_unchanged() -> None:
        _require_snapshot_unchanged(rehearsal_file_snapshots, label="rehearsal input")

    output_root = cast(Path, args.output_root)
    for path, payload in rehearsal_file_snapshots.items():
        materialized_payload = verified_materialization.artifact_bytes.get(
            os.path.abspath(path)
        )
        if materialized_payload is not None and materialized_payload != payload:
            raise CommandError(f"rehearsal materialization input changed: {path}")
    input_commitments = {
        str(path.resolve()): (
            {
                "kind": "file",
                "path": str(path.resolve()),
                "sha256": _bytes_sha256(rehearsal_file_snapshots[path]),
                "byte_count": len(rehearsal_file_snapshots[path]),
            }
            if path in rehearsal_file_snapshots
            else _fixture_rehearsal_input_commitment(path)
        )
        for path in input_paths
    }
    target_stage = cast(str, args.rehearsal_stage)
    staged_invocation = cast(str, args.acquisition_command) != "rehearse-downstream"
    rehearsal_stage_order = (
        "decision-texts",
        "stage-a-unitize",
        "stage-a-review",
        "stage-a-apply",
        "stage-b-label",
        "stage-b-apply",
        "packet-plan",
        "packet-build",
    )
    try:
        target_stage_index = rehearsal_stage_order.index(target_stage)
    except ValueError as exc:
        raise CommandError(
            f"unsupported fixture rehearsal stage: {target_stage}"
        ) from exc
    verified_stage_card_sha256: dict[str, str] = {}

    def pin_completed_stage_card(stage: str, default_path: Path) -> None:
        stage_card_path = _acquisition_path(args, "run_card_output", default_path)
        verified_stage_card_sha256[stage] = _path_sha256(stage_card_path)

    selections = verified_materialization.selection_records
    candidate_ids = tuple(_required_str(row, "candidate_id") for row in selections)
    if len(candidate_ids) != target_count or len(set(candidate_ids)) != target_count:
        raise CommandError(
            "rehearsal selection must contain exactly the unique target-case count"
        )
    if any(record.get("selected") is not True for record in selections):
        raise CommandError("rehearsal selection contains an unselected row")
    if any(
        date.fromisoformat(_required_str(record, "decision_date"))
        < CYCLE_1_ELIGIBILITY_ANCHOR
        for record in selections
    ):
        raise CommandError("rehearsal selection contains a pre-anchor decision")
    selection_card = _projection_json_object(
        rehearsal_file_snapshots[selection_card_path], source=selection_card_path
    )
    selection_outputs = selection_card.get("output_commitments")
    selection_output_sha256 = (
        cast(Mapping[object, object], selection_outputs).get(
            str(selection_path.resolve())
        )
        if isinstance(selection_outputs, Mapping)
        else None
    )
    if (
        selection_card.get("stage") != "project-target-cohort"
        or selection_card.get("status") != "completed"
        or selection_card.get("execute") is not True
        or selection_card.get("record_count") != target_count
        or not isinstance(selection_outputs, Mapping)
        or selection_output_sha256
        != _bytes_sha256(
            verified_materialization.artifact_bytes[os.path.abspath(selection_path)]
        )
    ):
        raise CommandError("invalid exact target-cohort selection run card")

    downloads = verified_materialization.manifest_records
    clearances = verified_materialization.clearance_records
    restrictions = tuple(
        _projection_jsonl_records(
            verified_materialization.artifact_bytes[os.path.abspath(restriction_path)],
            source=restriction_path,
        )
    )
    parser_records = tuple(
        _projection_jsonl_records(
            rehearsal_file_snapshots[parser_manifest_path], source=parser_manifest_path
        )
    )
    parse_requests = tuple(
        _projection_jsonl_records(
            rehearsal_file_snapshots[parse_requests_path], source=parse_requests_path
        )
    )
    parse_plan_card = _projection_json_object(
        rehearsal_file_snapshots[parse_plan_card_path], source=parse_plan_card_path
    )
    parse_plan_outputs = _required_record(parse_plan_card, "output_commitments")
    parse_request_commitment = _required_record(parse_plan_outputs, "parse_requests")
    if (
        parse_plan_card.get("stage") != "plan-parse-documents"
        or parse_plan_card.get("status") != "completed"
        or parse_plan_card.get("execute") is not True
        or parse_request_commitment.get("sha256")
        != _bytes_sha256(rehearsal_file_snapshots[parse_requests_path])
    ):
        raise CommandError("invalid completed plan-parse-documents run card")
    parser_card = _projection_json_object(
        rehearsal_file_snapshots[parser_card_path], source=parser_card_path
    )
    parser_execution = _required_record(parser_card, "parser_execution")
    if (
        parser_card.get("stage") != "parse-documents"
        or parser_card.get("status") != "completed"
        or parser_card.get("execute") is not True
        or parser_execution.get("mode") != "fixture_markdown"
        or parser_execution.get("engine") != "fixture_markdown"
        or parser_execution.get("fixture_markdown") is not True
    ):
        raise CommandError(
            "rehearse-downstream requires an executed fixture-Markdown parser card"
        )
    parser_sources = _required_record(parser_card, "source_commitments")
    parser_outputs = _required_record(parser_card, "output_commitments")
    if _required_record(parser_sources, "requests").get("sha256") != _bytes_sha256(
        rehearsal_file_snapshots[parse_requests_path]
    ) or _required_record(parser_outputs, "parser_manifest").get(
        "sha256"
    ) != _bytes_sha256(rehearsal_file_snapshots[parser_manifest_path]):
        raise CommandError("fixture parser card hash commitments changed")
    request_index = {
        (
            _required_str(row, "candidate_id"),
            _required_str(row, "source_document_id"),
        ): row
        for row in parse_requests
    }
    parser_index = {
        (
            _required_str(row, "candidate_id"),
            _required_str(row, "source_document_id"),
        ): row
        for row in parser_records
    }
    if set(request_index) != set(parser_index):
        raise CommandError(
            "parse request and parser candidate/document coverage differs"
        )
    for key, parser_record in parser_index.items():
        request = request_index[key]
        if _required_str(request, "expected_sha256").removeprefix(
            "sha256:"
        ) != _required_str(parser_record, "source_sha256").removeprefix(
            "sha256:"
        ) or _required_int(request, "expected_byte_count") != _required_int(
            parser_record, "source_byte_count"
        ):
            raise CommandError(f"fixture parser source commitment changed: {key}")

    commitments = {
        "selection_sha256": _bytes_sha256(rehearsal_file_snapshots[selection_path]),
        "selection_run_card_sha256": _bytes_sha256(
            rehearsal_file_snapshots[selection_card_path]
        ),
        "download_manifest_sha256": _bytes_sha256(
            rehearsal_file_snapshots[manifest_path]
        ),
        "disclosure_clearance_sha256": _bytes_sha256(
            rehearsal_file_snapshots[clearance_path]
        ),
        "clearance_run_card_sha256": _bytes_sha256(
            rehearsal_file_snapshots[materialization_card_path]
        ),
        "restriction_evidence_sha256": _bytes_sha256(
            rehearsal_file_snapshots[restriction_path]
        ),
        "parser_manifest_sha256": _bytes_sha256(
            rehearsal_file_snapshots[parser_manifest_path]
        ),
        "parser_run_card_sha256": _bytes_sha256(
            rehearsal_file_snapshots[parser_card_path]
        ),
    }
    try:
        fixture_bundle = load_deterministic_response_fixture_bundle_bytes(
            rehearsal_file_snapshots[response_fixture_path],
            source=response_fixture_path,
        )
        fixtures = fixture_bundle.fixtures
        unitizer_entries, unitizer_sha = _registry_entries_for_keys_bytes(
            rehearsal_file_snapshots[cast(Path, args.unitizer_model_registry)],
            (cast(str, args.unitizer_model_key),),
        )
        unitizer_entry = unitizer_entries[0]
        reviewer_entries, reviewer_sha = _registry_entries_for_keys_bytes(
            rehearsal_file_snapshots[cast(Path, args.reviewer_model_registry)],
            (cast(str, args.reviewer_model_key),),
        )
        reviewer_entry = reviewer_entries[0]
        judge_keys = tuple(cast(list[str], args.judge_model_key))
        _require_explicit_unique_model_keys(judge_keys)
        judge_registry_path = cast(Path, args.judge_model_registry)
        judge_entries, judge_sha = _registry_entries_for_keys_bytes(
            rehearsal_file_snapshots[judge_registry_path], judge_keys
        )
        frozen_judge_keys = {
            entry.registry_key
            for entry in load_model_registry_bytes(
                rehearsal_file_snapshots[judge_registry_path]
            ).entries
        }
        if {entry.registry_key for entry in judge_entries} != frozen_judge_keys:
            raise CommandError("rehearsal must select the complete frozen judge panel")
        evaluated_entries = load_model_registry_bytes(
            rehearsal_file_snapshots[cast(Path, args.evaluated_model_registry)]
        ).entries
        evaluated_identities = {
            (entry.provider, entry.model_id, entry.model_version_or_snapshot)
            for entry in evaluated_entries
        }
        overlaps = sorted(
            entry.registry_key
            for entry in judge_entries
            if (entry.provider, entry.model_id, entry.model_version_or_snapshot)
            in evaluated_identities
        )
        if overlaps:
            raise CommandError(
                "rehearsal judge panel overlaps evaluated registry: "
                + ", ".join(overlaps)
            )
    except (DecisionTextArtifactError, DownstreamRehearsalError, ValueError) as exc:
        raise CommandError(str(exc)) from exc

    _acquisition_output_root(args)

    decision_stage = "rehearsal-build-decision-texts"
    decision_texts_path = output_root / "rehearsal-decision-texts.jsonl"
    decision_manifest_path = output_root / "rehearsal-decision-texts-manifest.json"
    decision_artifact_card_path = output_root / "rehearsal-decision-texts-run-card.json"
    decision_primary_paths = (
        decision_texts_path.resolve(),
        decision_manifest_path.resolve(),
        decision_artifact_card_path.resolve(),
    )
    decision_stage_card_path = output_root / "run-cards" / f"{decision_stage}.json"
    if staged_invocation and target_stage_index > 0:
        _verify_fixture_rehearsal_stage_card(
            decision_stage_card_path,
            stage=decision_stage,
            input_commitments=input_commitments,
            prior_stage_card_path=None,
            expected_record_count=target_count,
            expected_primary_paths=decision_primary_paths,
        )
        verified_stage_card_sha256[decision_stage] = _path_sha256(
            decision_stage_card_path
        )
        decision_records = tuple(_read_records(decision_texts_path))
        decision_manifest = _read_json_object(decision_manifest_path)
        decision_artifact_card = _read_json_object(decision_artifact_card_path)
        if (
            decision_manifest.get("schema_version")
            != "legalforecast.fixture_decision_text_manifest.v1"
            or decision_manifest.get("record_count") != len(decision_records)
            or decision_manifest.get("decision_texts_sha256")
            != _path_sha256(decision_texts_path)
            or decision_manifest.get("input_commitments") != commitments
            or decision_manifest.get("outcome_material_model_visible") is not False
            or decision_artifact_card.get("schema_version")
            != "legalforecast.fixture_acquisition_run_card.v1"
            or decision_artifact_card.get("stage") != decision_stage
            or decision_artifact_card.get("status") != "completed"
            or decision_artifact_card.get("execute") is not True
            or decision_artifact_card.get("record_count") != len(decision_records)
            or decision_artifact_card.get("decision_texts_sha256")
            != _path_sha256(decision_texts_path)
            or decision_artifact_card.get("decision_texts_manifest_sha256")
            != _path_sha256(decision_manifest_path)
            or decision_artifact_card.get("input_commitments") != commitments
            or decision_artifact_card.get("provider_call_executed") is not False
        ):
            raise CommandError("invalid fixture decision-text artifact chain")
    else:
        try:
            decision_records = build_fixture_rehearsal_decision_text_records(
                selections=selections,
                download_manifest=downloads,
                clearance_records=clearances,
                restriction_records=restrictions,
                parser_records=parser_records,
                markdown_root=markdown_root.resolve(),
                input_commitments=commitments,
            )
        except (DecisionTextArtifactError, ValueError) as exc:
            raise CommandError(str(exc)) from exc
        decision_artifacts = [
            _write_fixture_rehearsal_artifact(
                decision_texts_path, decision_records, stage=decision_stage
            )
        ]
        decision_manifest = {
            "schema_version": "legalforecast.fixture_decision_text_manifest.v1",
            "record_count": len(decision_records),
            "decision_texts_sha256": _path_sha256(decision_texts_path),
            "candidate_ids_sha256": "sha256:"
            + hashlib.sha256(
                json.dumps(candidate_ids, separators=(",", ":")).encode("utf-8")
            ).hexdigest(),
            "input_commitments": commitments,
            "outcome_material_model_visible": False,
        }
        decision_artifacts.append(
            _write_fixture_rehearsal_json_artifact(
                decision_manifest_path, decision_manifest, stage=decision_stage
            )
        )
        decision_artifacts.append(
            _write_fixture_rehearsal_json_artifact(
                decision_artifact_card_path,
                {
                    "schema_version": ("legalforecast.fixture_acquisition_run_card.v1"),
                    "stage": decision_stage,
                    "status": "completed",
                    "execute": True,
                    "record_count": len(decision_records),
                    "decision_texts_sha256": _path_sha256(decision_texts_path),
                    "decision_texts_manifest_sha256": _path_sha256(
                        decision_manifest_path
                    ),
                    "input_commitments": commitments,
                    "provider_call_executed": False,
                },
                stage=decision_stage,
            )
        )
        _complete_fixture_rehearsal_stage(
            args,
            stage=decision_stage,
            input_paths=input_paths,
            input_commitments=input_commitments,
            artifacts=decision_artifacts,
            record_count=len(decision_records),
            prior_stage=None,
        )
        pin_completed_stage_card(decision_stage, decision_stage_card_path)
    if target_stage == "decision-texts":
        require_rehearsal_inputs_unchanged()
        return 0

    raw_units_path = output_root / "rehearsal-raw-prediction-units.jsonl"
    unit_audit_path = output_root / "rehearsal-llm-unitize-audit.jsonl"
    original_review_path = output_root / "rehearsal-unitization-review-queue.jsonl"
    unitize_stage = "rehearsal-stage-a-unitize"
    unitize_stage_card_path = output_root / "run-cards" / f"{unitize_stage}.json"
    if staged_invocation and target_stage_index > 1:
        unitize_card = _verify_fixture_rehearsal_stage_card(
            unitize_stage_card_path,
            stage=unitize_stage,
            input_commitments=input_commitments,
            prior_stage_card_path=decision_stage_card_path,
            expected_record_count=_fixture_rehearsal_record_count(raw_units_path),
            expected_primary_paths=(
                raw_units_path.resolve(),
                unit_audit_path.resolve(),
                original_review_path.resolve(),
            ),
        )
        verified_stage_card_sha256[unitize_stage] = _path_sha256(
            unitize_stage_card_path
        )
        raw_prediction_units = tuple(_read_records(raw_units_path))
        original_review_queue = tuple(_read_records(original_review_path))
        unitization_traces = tuple(
            _required_record_sequence(unitize_card, "fixture_traces")
        )
    else:
        try:
            unitized = run_fixture_unitization(
                selection_records=selections,
                parser_records=parser_records,
                markdown_root=markdown_root,
                unitizer_entry=unitizer_entry,
                unitizer_registry_sha256=unitizer_sha,
                fixtures=fixtures,
            )
        except (
            DecisionTextArtifactError,
            DownstreamRehearsalError,
            ValueError,
        ) as exc:
            raise CommandError(str(exc)) from exc
        raw_prediction_units = tuple(unitized.raw_prediction_units)
        unitization_audit = tuple(unitized.unitization_audit)
        original_review_queue = tuple(unitized.original_review_queue)
        unitization_traces = tuple(trace.to_record() for trace in unitized.traces)
        unitize_artifacts = [
            _write_fixture_rehearsal_artifact(
                raw_units_path, raw_prediction_units, stage=unitize_stage
            ),
            _write_fixture_rehearsal_artifact(
                unit_audit_path, unitization_audit, stage=unitize_stage
            ),
            _write_fixture_rehearsal_artifact(
                original_review_path, original_review_queue, stage=unitize_stage
            ),
        ]
        _complete_fixture_rehearsal_stage(
            args,
            stage=unitize_stage,
            input_paths=input_paths,
            input_commitments=input_commitments,
            artifacts=unitize_artifacts,
            record_count=len(raw_prediction_units),
            prior_stage=decision_stage,
            fixture_traces=unitization_traces,
            expected_prior_stage_card_sha256=verified_stage_card_sha256.get(
                decision_stage
            ),
            expected_prior_stage_record_count=len(decision_records),
        )
        pin_completed_stage_card(unitize_stage, unitize_stage_card_path)
    if target_stage == "stage-a-unitize":
        require_rehearsal_inputs_unchanged()
        return 0

    structural_flags_path = output_root / "rehearsal-stage-a-structural-flags.jsonl"
    structural_audit_path = output_root / "rehearsal-stage-a-review-audit.jsonl"
    merged_review_path = output_root / "rehearsal-unitization-review-final.jsonl"
    review_stage = "rehearsal-stage-a-review"
    review_stage_card_path = output_root / "run-cards" / f"{review_stage}.json"
    if staged_invocation and target_stage_index > 2:
        review_card = _verify_fixture_rehearsal_stage_card(
            review_stage_card_path,
            stage=review_stage,
            input_commitments=input_commitments,
            prior_stage_card_path=unitize_stage_card_path,
            expected_record_count=_fixture_rehearsal_record_count(
                structural_flags_path
            ),
            expected_primary_paths=(
                structural_flags_path.resolve(),
                structural_audit_path.resolve(),
                merged_review_path.resolve(),
            ),
        )
        verified_stage_card_sha256[review_stage] = _path_sha256(review_stage_card_path)
        merged_review_queue = tuple(_read_records(merged_review_path))
        review_traces = tuple(_required_record_sequence(review_card, "fixture_traces"))
    else:
        try:
            reviewed = run_fixture_structural_review(
                selection_records=selections,
                parser_records=parser_records,
                prediction_unit_records=raw_prediction_units,
                original_review_queue=original_review_queue,
                markdown_root=markdown_root,
                reviewer_entry=reviewer_entry,
                reviewer_registry_sha256=reviewer_sha,
                fixtures=fixtures,
            )
        except (DownstreamRehearsalError, ValueError) as exc:
            raise CommandError(str(exc)) from exc
        structural_flags = tuple(reviewed.structural_flags)
        structural_review_audit = tuple(reviewed.structural_review_audit)
        merged_review_queue = tuple(reviewed.merged_review_queue)
        review_traces = tuple(trace.to_record() for trace in reviewed.traces)
        review_artifacts = [
            _write_fixture_rehearsal_artifact(
                structural_flags_path, structural_flags, stage=review_stage
            ),
            _write_fixture_rehearsal_artifact(
                structural_audit_path,
                structural_review_audit,
                stage=review_stage,
            ),
            _write_fixture_rehearsal_artifact(
                merged_review_path, merged_review_queue, stage=review_stage
            ),
        ]
        _complete_fixture_rehearsal_stage(
            args,
            stage=review_stage,
            input_paths=input_paths,
            input_commitments=input_commitments,
            artifacts=review_artifacts,
            record_count=len(structural_flags),
            prior_stage=unitize_stage,
            fixture_traces=review_traces,
            expected_prior_stage_card_sha256=verified_stage_card_sha256.get(
                unitize_stage
            ),
            expected_prior_stage_record_count=len(raw_prediction_units),
        )
        pin_completed_stage_card(review_stage, review_stage_card_path)
    if target_stage == "stage-a-review":
        require_rehearsal_inputs_unchanged()
        return 0

    finalized_units_path = output_root / "rehearsal-finalized-prediction-units.jsonl"
    apply_a_stage = "rehearsal-stage-a-apply"
    apply_a_stage_card_path = output_root / "run-cards" / f"{apply_a_stage}.json"
    if staged_invocation and target_stage_index > 3:
        _verify_fixture_rehearsal_stage_card(
            apply_a_stage_card_path,
            stage=apply_a_stage,
            input_commitments=input_commitments,
            prior_stage_card_path=review_stage_card_path,
            expected_record_count=_fixture_rehearsal_record_count(finalized_units_path),
            expected_primary_paths=(finalized_units_path.resolve(),),
        )
        verified_stage_card_sha256[apply_a_stage] = _path_sha256(
            apply_a_stage_card_path
        )
        finalized_units = tuple(_read_records(finalized_units_path))
    else:
        try:
            finalized_units = apply_fixture_unitization_review(
                prediction_unit_records=raw_prediction_units,
                review_records=merged_review_queue,
            )
        except DownstreamRehearsalError as exc:
            raise CommandError(str(exc)) from exc
        apply_a_artifacts = [
            _write_fixture_rehearsal_artifact(
                finalized_units_path, finalized_units, stage=apply_a_stage
            )
        ]
        _complete_fixture_rehearsal_stage(
            args,
            stage=apply_a_stage,
            input_paths=input_paths,
            input_commitments=input_commitments,
            artifacts=apply_a_artifacts,
            record_count=len(finalized_units),
            prior_stage=review_stage,
            expected_prior_stage_card_sha256=verified_stage_card_sha256.get(
                review_stage
            ),
            expected_prior_stage_record_count=_fixture_rehearsal_record_count(
                structural_flags_path
            ),
        )
        pin_completed_stage_card(apply_a_stage, apply_a_stage_card_path)
    if target_stage == "stage-a-apply":
        require_rehearsal_inputs_unchanged()
        return 0

    decision_artifact = VerifiedDecisionTextArtifact(
        records=decision_records,
        decision_texts_sha256=_path_sha256(decision_texts_path),
        manifest_sha256=_path_sha256(decision_manifest_path),
        run_card_sha256=_path_sha256(decision_artifact_card_path),
        finalized_prediction_units_sha256=_path_sha256(finalized_units_path),
        finalized_unit_envelope_sha256s={
            _required_str(row, "candidate_id"): "sha256:" + canonical_sha256(row)
            for row in finalized_units
        },
        input_commitments=commitments,
    )

    labels_path = output_root / "rehearsal-labels.jsonl"
    label_audit_path = output_root / "rehearsal-llm-label-audit.jsonl"
    lawyer_queue_path = output_root / "rehearsal-lawyer-review-queue.jsonl"
    label_stage = "rehearsal-stage-b-label"
    label_stage_card_path = output_root / "run-cards" / f"{label_stage}.json"
    if staged_invocation and target_stage_index > 4:
        label_card = _verify_fixture_rehearsal_stage_card(
            label_stage_card_path,
            stage=label_stage,
            input_commitments=input_commitments,
            prior_stage_card_path=apply_a_stage_card_path,
            expected_record_count=_fixture_rehearsal_record_count(labels_path),
            expected_primary_paths=(
                labels_path.resolve(),
                label_audit_path.resolve(),
                lawyer_queue_path.resolve(),
            ),
        )
        verified_stage_card_sha256[label_stage] = _path_sha256(label_stage_card_path)
        label_records = tuple(_read_records(labels_path))
        labeling_audit = tuple(_read_records(label_audit_path))
        lawyer_review_queue = tuple(_read_records(lawyer_queue_path))
        label_traces = tuple(_required_record_sequence(label_card, "fixture_traces"))
        try:
            decision_artifact.verify_stage_b_audit_commitments(labeling_audit)
        except DecisionTextArtifactError as exc:
            raise CommandError(str(exc)) from exc
    else:
        try:
            stage_b = run_fixture_stage_b(
                selection_records=selections,
                finalized_prediction_units=finalized_units,
                decision_text_artifact=decision_artifact,
                judge_entries=judge_entries,
                judge_registry_sha256=judge_sha,
                fixtures=fixtures,
                apply_review=False,
            )
            decision_artifact.verify_stage_b_audit_commitments(stage_b.labeling_audit)
        except (
            DecisionTextArtifactError,
            DownstreamRehearsalError,
            ValueError,
        ) as exc:
            raise CommandError(str(exc)) from exc
        label_records = tuple(stage_b.labels)
        labeling_audit = tuple(stage_b.labeling_audit)
        lawyer_review_queue = tuple(stage_b.lawyer_review_queue)
        label_traces = tuple(trace.to_record() for trace in stage_b.traces)
        label_artifacts = [
            _write_fixture_rehearsal_artifact(
                labels_path, label_records, stage=label_stage
            ),
            _write_fixture_rehearsal_artifact(
                label_audit_path, labeling_audit, stage=label_stage
            ),
            _write_fixture_rehearsal_artifact(
                lawyer_queue_path, lawyer_review_queue, stage=label_stage
            ),
        ]
        _complete_fixture_rehearsal_stage(
            args,
            stage=label_stage,
            input_paths=input_paths,
            input_commitments=input_commitments,
            artifacts=label_artifacts,
            record_count=len(label_records),
            prior_stage=apply_a_stage,
            fixture_traces=label_traces,
            expected_prior_stage_card_sha256=verified_stage_card_sha256.get(
                apply_a_stage
            ),
            expected_prior_stage_record_count=len(finalized_units),
        )
        pin_completed_stage_card(label_stage, label_stage_card_path)
    if target_stage == "stage-b-label":
        require_rehearsal_inputs_unchanged()
        return 0

    label_apply_path = output_root / "rehearsal-label-apply-audit.jsonl"
    apply_b_stage = "rehearsal-stage-b-apply"
    apply_b_stage_card_path = output_root / "run-cards" / f"{apply_b_stage}.json"
    if staged_invocation and target_stage_index > 5:
        _verify_fixture_rehearsal_stage_card(
            apply_b_stage_card_path,
            stage=apply_b_stage,
            input_commitments=input_commitments,
            prior_stage_card_path=label_stage_card_path,
            expected_record_count=_fixture_rehearsal_record_count(labels_path),
            expected_primary_paths=(label_apply_path.resolve(),),
        )
        verified_stage_card_sha256[apply_b_stage] = _path_sha256(
            apply_b_stage_card_path
        )
    else:
        try:
            apply_fixture_label_review(review_records=lawyer_review_queue)
        except DownstreamRehearsalError as exc:
            raise CommandError(str(exc)) from exc
        label_apply_audit = (
            {
                "stage": "rehearsal-apply-lawyer-review",
                "status": "completed_no_pending_reviews",
                "label_count": len(label_records),
                "provider_call_executed": False,
            },
        )
        apply_b_artifacts = [
            _write_fixture_rehearsal_artifact(
                label_apply_path,
                label_apply_audit,
                stage=apply_b_stage,
            )
        ]
        _complete_fixture_rehearsal_stage(
            args,
            stage=apply_b_stage,
            input_paths=input_paths,
            input_commitments=input_commitments,
            artifacts=apply_b_artifacts,
            record_count=len(label_records),
            prior_stage=label_stage,
            expected_prior_stage_card_sha256=verified_stage_card_sha256.get(
                label_stage
            ),
            expected_prior_stage_record_count=len(label_records),
        )
        pin_completed_stage_card(apply_b_stage, apply_b_stage_card_path)
    if target_stage == "stage-b-apply":
        require_rehearsal_inputs_unchanged()
        return 0

    packet_input_path = output_root / "rehearsal-packet-build-input.jsonl"
    packet_plan_stage = "rehearsal-plan-packet-inputs"
    packet_plan_stage_card_path = (
        output_root / "run-cards" / f"{packet_plan_stage}.json"
    )
    if staged_invocation and target_stage_index > 6:
        _verify_fixture_rehearsal_stage_card(
            packet_plan_stage_card_path,
            stage=packet_plan_stage,
            input_commitments=input_commitments,
            prior_stage_card_path=apply_b_stage_card_path,
            expected_record_count=_fixture_rehearsal_record_count(packet_input_path),
            expected_primary_paths=(packet_input_path.resolve(),),
        )
        verified_stage_card_sha256[packet_plan_stage] = _path_sha256(
            packet_plan_stage_card_path
        )
        packet_build_records = tuple(_read_records(packet_input_path))
        if len(packet_build_records) != target_count:
            raise CommandError(
                "fixture packet plan does not preserve the exact clean cohort"
            )
    else:
        plan = plan_packet_build_inputs(
            selection_records=selections,
            download_records=downloads,
            parser_records=parser_records,
            prediction_unit_records=finalized_units,
            raw_html_dir=raw_html_dir,
            document_root=document_root,
            markdown_root=markdown_root,
            source_dir=output_root,
            generated_at=_parse_datetime(cast(str, args.generated_at)),
            decision_filed_on_or_after=CYCLE_1_ELIGIBILITY_ANCHOR,
        )
        if plan.case_count != target_count or plan.exclusion_ledger_records:
            raise CommandError(
                "fixture packet planning did not preserve the exact clean cohort"
            )
        packet_build_records = tuple(plan.packet_build_records)
        packet_plan_artifacts = [
            _write_fixture_rehearsal_artifact(
                packet_input_path, packet_build_records, stage=packet_plan_stage
            )
        ]
        _complete_fixture_rehearsal_stage(
            args,
            stage=packet_plan_stage,
            input_paths=input_paths,
            input_commitments=input_commitments,
            artifacts=packet_plan_artifacts,
            record_count=len(packet_build_records),
            prior_stage=apply_b_stage,
            expected_prior_stage_card_sha256=verified_stage_card_sha256.get(
                apply_b_stage
            ),
            expected_prior_stage_record_count=len(label_records),
        )
        pin_completed_stage_card(packet_plan_stage, packet_plan_stage_card_path)
    if target_stage == "packet-plan":
        require_rehearsal_inputs_unchanged()
        return 0

    packet_path = output_root / "rehearsal-packets.jsonl"
    case_packet_path = output_root / "rehearsal-case-packets.jsonl"
    packet_audit_path = output_root / "rehearsal-packet-audit.jsonl"
    assemblies = tuple(
        _model_packet_assembly(record, ablation=PacketAblation.FULL_PACKET)
        for record in packet_build_records
    )
    packet_stage = "rehearsal-build-packets"
    packet_artifacts = [
        _write_fixture_rehearsal_artifact(
            packet_path,
            tuple(item.model_packet.to_record() for item in assemblies),
            stage=packet_stage,
        ),
        _write_fixture_rehearsal_artifact(
            case_packet_path,
            tuple(item.case_packet.to_record() for item in assemblies),
            stage=packet_stage,
        ),
        _write_fixture_rehearsal_artifact(
            packet_audit_path,
            tuple(item.audit_bundle for item in assemblies),
            stage=packet_stage,
        ),
    ]
    decision_ids = {
        _required_str(record, "candidate_id"): (
            _required_str(record, "candidate_id")
            + "-"
            + _required_str(record, "document_id")
        )
        for record in decision_records
    }
    for assembly in assemblies:
        packet = assembly.model_packet.to_record()
        candidate_id = _required_str(packet, "candidate_id")
        expected_decision_id = decision_ids[candidate_id]
        excluded_ids = set(cast(Sequence[str], packet.get("excluded_document_ids", [])))
        if expected_decision_id not in excluded_ids:
            raise CommandError(
                "rehearsal packet failed to record outcome-material exclusion"
            )
        mounted = {
            candidate_id + "-" + _required_str(document, "source_document_id")
            for document in _required_record_sequence(packet, "documents")
        }
        if expected_decision_id in mounted:
            raise CommandError("outcome-bearing decision entered a model packet")
    _complete_fixture_rehearsal_stage(
        args,
        stage=packet_stage,
        input_paths=input_paths,
        input_commitments=input_commitments,
        artifacts=packet_artifacts,
        record_count=len(assemblies),
        prior_stage=packet_plan_stage,
        expected_prior_stage_card_sha256=verified_stage_card_sha256.get(
            packet_plan_stage
        ),
        expected_prior_stage_record_count=len(packet_build_records),
    )
    packet_stage_card_path = output_root / "run-cards" / f"{packet_stage}.json"
    pin_completed_stage_card(packet_stage, packet_stage_card_path)
    summary_path = output_root / "rehearsal-final-summary.json"
    unit_count = sum(
        len(_required_record_sequence(row, "prediction_units"))
        for row in finalized_units
    )
    try:
        fixture_bundle.require_unchanged()
    except DownstreamRehearsalError as exc:
        raise CommandError(str(exc)) from exc
    stage_names = (
        decision_stage,
        unitize_stage,
        review_stage,
        apply_a_stage,
        label_stage,
        apply_b_stage,
        packet_plan_stage,
        packet_stage,
    )
    stage_cards = tuple(
        output_root / "run-cards" / f"{stage_name}.json" for stage_name in stage_names
    )
    stage_card_sidecars = tuple(
        _fixture_rehearsal_sidecar_path(stage_card) for stage_card in stage_cards
    )
    all_output_paths: list[Path] = []
    for stage_name, stage_card in zip(stage_names, stage_cards, strict=True):
        if verified_stage_card_sha256.get(stage_name) != _path_sha256(stage_card):
            raise CommandError(f"fixture rehearsal stage card changed: {stage_name}")
        stage_card_payload = _read_json_object(stage_card)
        all_output_paths.extend(
            Path(str(value))
            for value in _required_record(stage_card_payload, "output_commitments")
        )
    all_outputs = tuple(all_output_paths)
    summary_artifact = _write_fixture_rehearsal_json_artifact(
        summary_path,
        {
            **rehearsal_provenance(response_fixtures=fixture_bundle),
            "stage": "rehearse-downstream",
            "status": "completed_fixture_only",
            "target_case_count": target_count,
            "selected_case_count": len(selections),
            "finalized_case_count": len(finalized_units),
            "decision_text_count": len(decision_records),
            "packet_case_count": len(assemblies),
            "prediction_unit_count": unit_count,
            "label_count": len(label_records),
            "pending_stage_a_review_count": len(merged_review_queue),
            "pending_stage_b_review_count": len(lawyer_review_queue),
            "provider_fixture_call_count": (
                len(unitization_traces) + len(review_traces) + len(label_traces)
            ),
            "provider_journal_created": False,
            "provider_billing_usd": "0.00",
            "packet_outcome_material_excluded": True,
            "input_commitments": {
                key: dict(value) for key, value in input_commitments.items()
            },
            "output_commitments": {
                str(path.resolve()): _path_sha256(path)
                for path in (*all_outputs, *stage_cards, *stage_card_sidecars)
            },
            "stage_cards": [str(path.resolve()) for path in stage_cards],
            "fixture_traces": [
                dict(trace)
                for trace in (*unitization_traces, *review_traces, *label_traces)
            ],
        },
        stage="rehearse-downstream",
    )
    _write_acquisition_completion(
        args,
        stage="rehearse-downstream",
        input_paths=input_paths,
        output_paths=(
            *all_outputs,
            *stage_cards,
            *stage_card_sidecars,
            *summary_artifact,
        ),
        record_count=target_count,
        dry_run=False,
        paid_activity_requested=False,
        paid_activity_executed=False,
        extra={
            **REHEARSAL_PROVENANCE,
            "provider_journal_created": False,
            "provider_billing_usd": "0.00",
            "summary_sha256": _path_sha256(summary_path),
            "summary_sidecar_sha256": _path_sha256(summary_artifact[1]),
        },
    )
    require_rehearsal_inputs_unchanged()
    return 0


def _cmd_acquisition_finalize_rehearsal(args: argparse.Namespace) -> int:
    """Finalize fixture evidence without creating official corpus authority."""

    if _acquisition_dry_run(args):
        raise CommandError(
            "finalize-rehearsal-corpus is provider-free and requires --execute"
        )
    output_root = _acquisition_output_root(args)
    summary_path = cast(Path, args.rehearsal_summary)
    summary_sidecar_path = _fixture_rehearsal_sidecar_path(summary_path)
    run_card_path = cast(Path, args.rehearsal_run_card)
    selection_path = cast(Path, args.selection)
    units_path = cast(Path, args.prediction_units)
    decisions_path = cast(Path, args.decision_texts)
    labels_path = cast(Path, args.labels)
    packets_path = cast(Path, args.packets)
    target_count = cast(int, args.target_case_count)
    if target_count <= 0:
        raise CommandError("--target-case-count must be positive")
    rehearsal_root = summary_path.resolve().parent
    canonical_role_paths = {
        "rehearsal run card": rehearsal_root / "run-cards/rehearse-downstream.json",
        "prediction units": (
            rehearsal_root / "rehearsal-finalized-prediction-units.jsonl"
        ),
        "decision texts": rehearsal_root / "rehearsal-decision-texts.jsonl",
        "labels": rehearsal_root / "rehearsal-labels.jsonl",
        "packets": rehearsal_root / "rehearsal-packets.jsonl",
    }
    supplied_role_paths = {
        "rehearsal run card": run_card_path,
        "prediction units": units_path,
        "decision texts": decisions_path,
        "labels": labels_path,
        "packets": packets_path,
    }
    for role, expected_path in canonical_role_paths.items():
        if supplied_role_paths[role].resolve() != expected_path.resolve():
            raise CommandError(
                f"fixture rehearsal finalization {role} path differs: "
                f"{supplied_role_paths[role]}"
            )
    input_paths = (
        summary_path,
        summary_sidecar_path,
        run_card_path,
        selection_path,
        units_path,
        decisions_path,
        labels_path,
        packets_path,
    )
    for path in input_paths:
        if path.is_symlink() or not path.is_file():
            raise CommandError(
                f"fixture rehearsal finalization input is not a regular file: {path}"
            )
    finalization_input_commitments = {
        str(path.resolve()): _path_sha256(path) for path in input_paths
    }
    summary = _read_json_object(summary_path)
    run_card = _read_json_object(run_card_path)
    expected_fixture_authority = {
        "provenance_class": "fixture_only",
        "official_eligible": False,
        "authorizes_freeze": False,
        "authorizes_evaluation": False,
        "authorizes_dispatch": False,
    }
    raw_run_card_outputs = run_card.get("output_paths")
    run_card_outputs: set[str] = set()
    if isinstance(raw_run_card_outputs, Sequence) and not isinstance(
        raw_run_card_outputs, (str, bytes)
    ):
        run_card_outputs = {
            str(Path(str(path)).resolve())
            for path in cast(Sequence[object], raw_run_card_outputs)
        }
    raw_run_card_inputs = run_card.get("input_paths")
    run_card_inputs: tuple[str, ...] = ()
    if isinstance(raw_run_card_inputs, Sequence) and not isinstance(
        raw_run_card_inputs, (str, bytes)
    ):
        run_card_inputs = tuple(
            str(Path(str(path)).resolve())
            for path in cast(Sequence[object], raw_run_card_inputs)
        )
    if (
        summary.get("schema_version") != "legalforecast.downstream_rehearsal.v1"
        or summary.get("stage") != "rehearse-downstream"
        or summary.get("status") != "completed_fixture_only"
        or any(
            summary.get(key) != value
            for key, value in expected_fixture_authority.items()
        )
        or run_card.get("stage") != "rehearse-downstream"
        or run_card.get("status") != "completed"
        or run_card.get("execute") is not True
        or any(
            run_card.get(key) != value
            for key, value in expected_fixture_authority.items()
        )
        or run_card.get("summary_sha256") != _path_sha256(summary_path)
        or run_card.get("summary_sidecar_sha256") != _path_sha256(summary_sidecar_path)
        or str(summary_path.resolve()) not in run_card_outputs
        or str(summary_sidecar_path.resolve()) not in run_card_outputs
        or not run_card_inputs
        or run_card_inputs[0] != str(selection_path.resolve())
    ):
        raise CommandError("invalid fixture-only downstream rehearsal authority")
    _verify_fixture_rehearsal_artifact(
        summary_path,
        sidecar_path=summary_sidecar_path,
        stage="rehearse-downstream",
    )
    output_commitments = _required_record(summary, "output_commitments")
    for raw_path, expected_sha256 in output_commitments.items():
        committed_path = Path(raw_path)
        if committed_path.is_symlink() or not committed_path.is_file():
            raise CommandError(
                "fixture rehearsal committed output is missing or unsafe: "
                f"{committed_path}"
            )
        if expected_sha256 != _path_sha256(committed_path):
            raise CommandError(
                f"fixture rehearsal output commitment changed: {committed_path}"
            )
    for path in (units_path, decisions_path, labels_path, packets_path):
        if str(path.resolve()) not in output_commitments:
            raise CommandError(f"fixture rehearsal output is uncommitted: {path}")
    input_commitments = _required_record(summary, "input_commitments")
    for raw_path, raw_commitment in input_commitments.items():
        expected_commitment = cast(Mapping[str, object], raw_commitment)
        if _fixture_rehearsal_input_commitment(Path(raw_path)) != expected_commitment:
            raise CommandError(
                f"fixture rehearsal input commitment changed: {raw_path}"
            )
    raw_selection_commitment = input_commitments.get(str(selection_path.resolve()))
    if not isinstance(raw_selection_commitment, Mapping):
        raise CommandError("fixture rehearsal selection commitment is missing")
    selection_commitment = cast(Mapping[str, object], raw_selection_commitment)
    if selection_commitment.get("sha256") != _path_sha256(selection_path):
        raise CommandError("fixture rehearsal selection commitment changed")

    expected_stage_names = (
        "rehearsal-build-decision-texts",
        "rehearsal-stage-a-unitize",
        "rehearsal-stage-a-review",
        "rehearsal-stage-a-apply",
        "rehearsal-stage-b-label",
        "rehearsal-stage-b-apply",
        "rehearsal-plan-packet-inputs",
        "rehearsal-build-packets",
    )
    expected_stage_primary_paths = {
        "rehearsal-build-decision-texts": (
            rehearsal_root / "rehearsal-decision-texts.jsonl",
            rehearsal_root / "rehearsal-decision-texts-manifest.json",
            rehearsal_root / "rehearsal-decision-texts-run-card.json",
        ),
        "rehearsal-stage-a-unitize": (
            rehearsal_root / "rehearsal-raw-prediction-units.jsonl",
            rehearsal_root / "rehearsal-llm-unitize-audit.jsonl",
            rehearsal_root / "rehearsal-unitization-review-queue.jsonl",
        ),
        "rehearsal-stage-a-review": (
            rehearsal_root / "rehearsal-stage-a-structural-flags.jsonl",
            rehearsal_root / "rehearsal-stage-a-review-audit.jsonl",
            rehearsal_root / "rehearsal-unitization-review-final.jsonl",
        ),
        "rehearsal-stage-a-apply": (
            rehearsal_root / "rehearsal-finalized-prediction-units.jsonl",
        ),
        "rehearsal-stage-b-label": (
            rehearsal_root / "rehearsal-labels.jsonl",
            rehearsal_root / "rehearsal-llm-label-audit.jsonl",
            rehearsal_root / "rehearsal-lawyer-review-queue.jsonl",
        ),
        "rehearsal-stage-b-apply": (
            rehearsal_root / "rehearsal-label-apply-audit.jsonl",
        ),
        "rehearsal-plan-packet-inputs": (
            rehearsal_root / "rehearsal-packet-build-input.jsonl",
        ),
        "rehearsal-build-packets": (
            rehearsal_root / "rehearsal-packets.jsonl",
            rehearsal_root / "rehearsal-case-packets.jsonl",
            rehearsal_root / "rehearsal-packet-audit.jsonl",
        ),
    }

    def committed_record_count(path: Path, *, stage: str) -> int:
        if path.is_symlink() or not path.is_file():
            raise CommandError(
                f"fixture stage output is missing or unsafe: {stage}: {path}"
            )
        return _fixture_rehearsal_record_count(path)

    expected_stage_record_counts = {
        "rehearsal-build-decision-texts": committed_record_count(
            rehearsal_root / "rehearsal-decision-texts.jsonl",
            stage="rehearsal-build-decision-texts",
        ),
        "rehearsal-stage-a-unitize": committed_record_count(
            rehearsal_root / "rehearsal-raw-prediction-units.jsonl",
            stage="rehearsal-stage-a-unitize",
        ),
        "rehearsal-stage-a-review": committed_record_count(
            rehearsal_root / "rehearsal-stage-a-structural-flags.jsonl",
            stage="rehearsal-stage-a-review",
        ),
        "rehearsal-stage-a-apply": committed_record_count(
            rehearsal_root / "rehearsal-finalized-prediction-units.jsonl",
            stage="rehearsal-stage-a-apply",
        ),
        "rehearsal-stage-b-label": committed_record_count(
            rehearsal_root / "rehearsal-labels.jsonl",
            stage="rehearsal-stage-b-label",
        ),
        "rehearsal-stage-b-apply": committed_record_count(
            rehearsal_root / "rehearsal-labels.jsonl",
            stage="rehearsal-stage-b-apply",
        ),
        "rehearsal-plan-packet-inputs": committed_record_count(
            rehearsal_root / "rehearsal-packet-build-input.jsonl",
            stage="rehearsal-plan-packet-inputs",
        ),
        "rehearsal-build-packets": committed_record_count(
            rehearsal_root / "rehearsal-packets.jsonl",
            stage="rehearsal-build-packets",
        ),
    }
    raw_stage_cards = summary.get("stage_cards")
    if not isinstance(raw_stage_cards, Sequence) or isinstance(
        raw_stage_cards, (str, bytes)
    ):
        raise CommandError("fixture rehearsal summary lacks stage-card sequence")
    stage_card_paths = tuple(
        Path(str(value)) for value in cast(Sequence[object], raw_stage_cards)
    )
    canonical_stage_card_paths = tuple(
        rehearsal_root / "run-cards" / f"{stage}.json" for stage in expected_stage_names
    )
    if tuple(path.resolve() for path in stage_card_paths) != tuple(
        path.resolve() for path in canonical_stage_card_paths
    ):
        raise CommandError("fixture rehearsal stage-card sequence differs")
    prior_card: Path | None = None
    for expected_stage, stage_card_path in zip(
        expected_stage_names, stage_card_paths, strict=True
    ):
        stage_card = _verify_fixture_rehearsal_stage_card(
            stage_card_path,
            stage=expected_stage,
            input_commitments=cast(Mapping[str, JsonRecord], input_commitments),
            prior_stage_card_path=prior_card,
            expected_record_count=expected_stage_record_counts[expected_stage],
            expected_primary_paths=expected_stage_primary_paths[expected_stage],
        )
        stage_outputs = _required_record(stage_card, "output_commitments")
        for raw_path, digest in stage_outputs.items():
            if output_commitments.get(raw_path) != digest:
                raise CommandError(
                    f"fixture stage output is absent from final summary: {raw_path}"
                )
        prior_card = stage_card_path

    decision_manifest = _read_json_object(
        rehearsal_root / "rehearsal-decision-texts-manifest.json"
    )
    decision_input_commitments = _required_record(
        decision_manifest, "input_commitments"
    )
    if decision_input_commitments.get("selection_sha256") != _path_sha256(
        selection_path
    ):
        raise CommandError("fixture rehearsal selection role commitment changed")

    selections = tuple(_read_records(selection_path))
    units = tuple(_read_records(units_path))
    decisions = tuple(_read_records(decisions_path))
    labels = tuple(_read_records(labels_path))
    packets = tuple(_read_records(packets_path))

    def candidate_ids(records: Sequence[Mapping[str, Any]]) -> tuple[str, ...]:
        return tuple(_required_str(record, "candidate_id") for record in records)

    selection_ids = candidate_ids(selections)
    unit_candidate_ids = candidate_ids(units)
    decision_candidate_ids = candidate_ids(decisions)
    packet_candidate_ids = candidate_ids(packets)
    exact_candidate_set = set(selection_ids)
    unit_pairs = tuple(
        (_required_str(unit, "unit_id"), _required_str(record, "candidate_id"))
        for record in units
        for unit in _required_record_sequence(record, "prediction_units")
    )
    unit_ids = tuple(unit_id for unit_id, _ in unit_pairs)
    label_unit_ids = tuple(_required_str(record, "unit_id") for record in labels)
    if (
        len(selection_ids) != len(set(selection_ids))
        or len(unit_candidate_ids) != len(set(unit_candidate_ids))
        or len(decision_candidate_ids) != len(set(decision_candidate_ids))
        or len(packet_candidate_ids) != len(set(packet_candidate_ids))
        or len(unit_ids) != len(set(unit_ids))
        or len(label_unit_ids) != len(set(label_unit_ids))
    ):
        raise CommandError("fixture rehearsal corpus contains duplicate records")
    unit_owner = dict(unit_pairs)
    labeled_unit_ids = set(label_unit_ids)
    if (
        len(selection_ids) != target_count
        or len(exact_candidate_set) != target_count
        or len(unit_candidate_ids) != target_count
        or len(decision_candidate_ids) != target_count
        or len(packet_candidate_ids) != target_count
        or set(unit_candidate_ids) != exact_candidate_set
        or set(decision_candidate_ids) != exact_candidate_set
        or set(packet_candidate_ids) != exact_candidate_set
        or labeled_unit_ids != set(unit_owner)
        or {unit_owner[unit_id] for unit_id in labeled_unit_ids} != exact_candidate_set
    ):
        raise CommandError("fixture rehearsal corpus candidate coverage is not exact")
    if (
        summary.get("target_case_count") != target_count
        or summary.get("selected_case_count") != target_count
        or summary.get("finalized_case_count") != target_count
        or summary.get("decision_text_count") != target_count
        or summary.get("packet_case_count") != target_count
        or summary.get("prediction_unit_count") != len(unit_ids)
        or summary.get("label_count") != len(label_unit_ids)
        or summary.get("pending_stage_a_review_count") != 0
        or summary.get("pending_stage_b_review_count") != 0
        or summary.get("provider_journal_created") is not False
        or summary.get("provider_billing_usd") != "0.00"
        or summary.get("packet_outcome_material_excluded") is not True
    ):
        raise CommandError("fixture rehearsal final count reconciliation failed")
    decision_ids = {
        _required_str(record, "candidate_id"): (
            _required_str(record, "candidate_id")
            + "-"
            + _required_str(record, "document_id")
        )
        for record in decisions
    }
    for packet in packets:
        candidate_id = _required_str(packet, "candidate_id")
        expected_decision_id = decision_ids[candidate_id]
        mounted = {
            candidate_id + "-" + _required_str(document, "source_document_id")
            for document in _required_record_sequence(packet, "documents")
        }
        excluded = set(cast(Sequence[str], packet.get("excluded_document_ids", [])))
        if expected_decision_id in mounted or expected_decision_id not in excluded:
            raise CommandError(
                "fixture rehearsal finalization found outcome material in a packet"
            )

    for raw_path, expected_sha256 in output_commitments.items():
        committed_path = Path(raw_path)
        if committed_path.is_symlink() or not committed_path.is_file():
            raise CommandError(
                "fixture rehearsal committed output is missing or unsafe: "
                f"{committed_path}"
            )
        if expected_sha256 != _path_sha256(committed_path):
            raise CommandError(
                f"fixture rehearsal output commitment changed: {committed_path}"
            )
    for raw_path, raw_commitment in input_commitments.items():
        expected_commitment = cast(Mapping[str, object], raw_commitment)
        if _fixture_rehearsal_input_commitment(Path(raw_path)) != expected_commitment:
            raise CommandError(
                f"fixture rehearsal input commitment changed: {raw_path}"
            )
    observed_finalization_inputs = {
        str(path.resolve()): _path_sha256(path) for path in input_paths
    }
    if observed_finalization_inputs != finalization_input_commitments:
        raise CommandError(
            "fixture rehearsal finalization input changed during validation"
        )

    corpus_path = _acquisition_path(
        args,
        "corpus_output",
        output_root / "fixture-rehearsal-corpus.json",
    )
    corpus = {
        **REHEARSAL_PROVENANCE,
        "schema_version": "legalforecast.fixture_rehearsal_corpus.v1",
        "stage": "finalize-rehearsal-corpus",
        "status": "completed_fixture_only",
        "target_case_count": target_count,
        "clean_case_count": target_count,
        "candidate_ids": list(selection_ids),
        "pending_stage_a_review_count": 0,
        "pending_stage_b_review_count": 0,
        "provider_journal_created": False,
        "provider_billing_usd": "0.00",
        "packet_outcome_material_excluded": True,
        "input_commitments": finalization_input_commitments,
    }
    _write_json(corpus_path, corpus)
    _write_acquisition_completion(
        args,
        stage="finalize-rehearsal-corpus",
        input_paths=input_paths,
        output_paths=(corpus_path,),
        record_count=target_count,
        dry_run=False,
        paid_activity_requested=False,
        paid_activity_executed=False,
        extra={
            **REHEARSAL_PROVENANCE,
            "corpus_sha256": _path_sha256(corpus_path),
            "provider_journal_created": False,
            "provider_billing_usd": "0.00",
        },
    )
    return 0


def _require_paid_baton_execute(args: argparse.Namespace) -> None:
    if not cast(bool, args.execute):
        raise CommandError(
            f"acquisition {args.acquisition_command} requires --execute; "
            "no provider or paid activity is performed by this command"
        )


def _paid_baton_identity(
    args: argparse.Namespace, *, outcome: str = "ready"
) -> BatonIdentity:
    return BatonIdentity(
        release_sha=cast(str, args.release_sha),
        stage=cast(str, args.stage),
        provider=cast(str, args.provider),
        sequence=cast(int, args.sequence_ordinal),
        outcome=outcome,
    )


def _bare_sha256(value: str, *, label: str) -> str:
    digest = value.removeprefix("sha256:")
    if re.fullmatch(r"[0-9a-f]{64}", digest) is None:
        raise CommandError(f"{label} must be a lowercase SHA-256")
    return digest


def _require_closed_baton_artifact_root(
    root: Path, *, names: tuple[str, str]
) -> tuple[Path, Path]:
    try:
        root_metadata = root.lstat()
    except FileNotFoundError as exc:
        raise CommandError(f"baton artifact root is missing: {root}") from exc
    if root.is_symlink() or not stat.S_ISDIR(root_metadata.st_mode):
        raise CommandError(f"baton artifact root is not a real directory: {root}")
    members = list(root.iterdir())
    if sorted(path.name for path in members) != sorted(names):
        raise CommandError(
            "baton artifact root must contain exactly: " + ", ".join(names)
        )
    by_name = {path.name: path for path in members}
    for name in names:
        metadata = by_name[name].lstat()
        if not stat.S_ISREG(metadata.st_mode) or metadata.st_nlink != 1:
            raise CommandError(
                f"baton artifact member is not a unique regular file: {name}"
            )
    return by_name[names[0]], by_name[names[1]]


def _require_baton_receipt(
    path: Path,
    *,
    identity: BatonIdentity | None = None,
    package_manifest_sha256: str | None = None,
) -> BatonReceipt:
    receipt = load_baton_receipt(path)
    if identity is not None and receipt.identity != identity:
        raise CommandError("baton receipt identity differs from protected inputs")
    if package_manifest_sha256 is not None and (
        receipt.package_manifest_sha256
        != _bare_sha256(package_manifest_sha256, label="package manifest commitment")
    ):
        raise CommandError(
            "baton receipt package manifest differs from protected inputs"
        )
    return receipt


def _print_baton_receipt(receipt: BatonReceipt) -> None:
    print(json.dumps(receipt.to_record(), sort_keys=True, allow_nan=False))


def _cmd_acquisition_build_paid_labeling_source(args: argparse.Namespace) -> int:
    _require_paid_baton_execute(args)
    identity = _paid_baton_identity(args)
    predecessor_path = cast(Path | None, args.predecessor_receipt)
    predecessor = (
        None
        if predecessor_path is None
        else PredecessorBinding.from_receipt(_require_baton_receipt(predecessor_path))
    )
    receipt = build_source_baton(
        source_root=cast(Path, args.source_root),
        identity=identity,
        predecessor=predecessor,
        age_executable=cast(Path, args.age_executable),
        age_recipient=cast(str, args.age_recipient),
        ciphertext_output=cast(Path, args.output_ciphertext),
        receipt_output=cast(Path, args.receipt_output),
    )
    _print_baton_receipt(receipt)
    return 0


def _cmd_acquisition_assemble_paid_labeling_baton(
    args: argparse.Namespace,
) -> int:
    _require_paid_baton_execute(args)
    identity = _paid_baton_identity(args)
    predecessor_root = cast(Path | None, args.predecessor_root)
    predecessor_manifest = cast(str | None, args.predecessor_package_manifest_sha256)
    if (predecessor_root is None) != (predecessor_manifest is None):
        raise CommandError(
            "--predecessor-root and --predecessor-package-manifest-sha256 "
            "must be supplied together"
        )
    predecessor_ciphertext: Path | None = None
    predecessor: PredecessorBinding | None = None
    if predecessor_root is not None and predecessor_manifest is not None:
        predecessor_ciphertext, predecessor_receipt = (
            _require_closed_baton_artifact_root(
                predecessor_root,
                names=("official-paid-labeling-result.age", "result-receipt.json"),
            )
        )
        predecessor = PredecessorBinding.from_receipt(
            _require_baton_receipt(
                predecessor_receipt,
                package_manifest_sha256=predecessor_manifest,
            )
        )
    receipt = assemble_paid_labeling_baton(
        source_ciphertext=cast(Path, args.source_ciphertext),
        expected_source_ciphertext_sha256=_bare_sha256(
            cast(str, args.source_ciphertext_sha256),
            label="source ciphertext commitment",
        ),
        expected_source_package_manifest_sha256=_bare_sha256(
            cast(str, args.source_package_manifest_sha256),
            label="source package manifest commitment",
        ),
        expected_identity=identity,
        predecessor_ciphertext=predecessor_ciphertext,
        predecessor=predecessor,
        age_executable=cast(Path, args.age_executable),
        age_identity_file=cast(Path, args.age_identity_file),
        age_recipient=cast(str, args.age_recipient),
        job_root=cast(Path, args.job_root),
        ciphertext_output=cast(Path, args.output_ciphertext),
        receipt_output=cast(Path, args.receipt_output),
    )
    _print_baton_receipt(receipt)
    return 0


def _cmd_acquisition_open_paid_labeling_baton(args: argparse.Namespace) -> int:
    _require_paid_baton_execute(args)
    identity = _paid_baton_identity(args)
    ciphertext, receipt_path = _require_closed_baton_artifact_root(
        cast(Path, args.artifact_root),
        names=("official-paid-labeling-baton.age", "baton-receipt.json"),
    )
    receipt = _require_baton_receipt(
        receipt_path,
        identity=identity,
        package_manifest_sha256=cast(str, args.expected_package_manifest_sha256),
    )
    opened = open_paid_labeling_baton(
        ciphertext=ciphertext,
        expected_ciphertext_sha256=receipt.ciphertext_sha256,
        expected_package_manifest_sha256=receipt.package_manifest_sha256,
        expected_job_manifest_sha256=_bare_sha256(
            cast(str, args.expected_job_manifest_sha256),
            label="job manifest commitment",
        ),
        expected_identity=identity,
        expected_predecessor=receipt.predecessor,
        age_executable=cast(Path, args.age_executable),
        age_identity_file=cast(Path, args.age_identity_file),
        job_root=cast(Path, args.job_root),
    )
    _print_baton_receipt(opened)
    return 0


def _cmd_acquisition_seal_paid_labeling_result(args: argparse.Namespace) -> int:
    _require_paid_baton_execute(args)
    expected_identity = _paid_baton_identity(args)
    job_root = cast(Path, args.job_root)
    package_manifest = cast(Path, args.input_package_manifest)
    canonical_manifest = job_root / "official-paid-labeling-package.json"
    if package_manifest.resolve(strict=False) != canonical_manifest.resolve(
        strict=False
    ):
        raise CommandError(
            "--input-package-manifest must name the manifest in --job-root"
        )
    manifest_sha256 = _bare_sha256(
        cast(str, args.expected_input_package_manifest_sha256),
        label="input package manifest commitment",
    )
    manifest_bytes = _read_singly_linked_regular_input(
        package_manifest, label="paid-labeling input package manifest"
    )
    if hashlib.sha256(manifest_bytes).hexdigest() != manifest_sha256:
        raise CommandError(
            "input package manifest differs from the protected commitment"
        )
    manifest = _read_json_object_payload(
        manifest_bytes, label="paid-labeling input package manifest"
    )
    manifest_identity = BatonIdentity.from_record(manifest.get("identity"))
    if manifest_identity != expected_identity:
        raise CommandError("input package identity differs from protected stage inputs")
    raw_predecessor = manifest.get("predecessor")
    predecessor = (
        None
        if raw_predecessor is None
        else PredecessorBinding.from_record(raw_predecessor)
    )
    receipt = seal_paid_labeling_baton(
        job_root=job_root,
        expected_input_package_manifest_sha256=manifest_sha256,
        outcome=cast(str, args.provider_stage_outcome),
        predecessor=predecessor,
        age_executable=cast(Path, args.age_executable),
        age_recipient=cast(str, args.age_recipient),
        ciphertext_output=cast(Path, args.output_ciphertext),
        receipt_output=cast(Path, args.receipt_output),
    )
    _print_baton_receipt(receipt)
    return 0


def _cmd_acquisition_build_decision_texts(args: argparse.Namespace) -> int:
    """Materialize authenticated, audit-only first-disposition text."""

    _preflight_materialization_purchase_runtime(args)
    dry_run = _acquisition_dry_run(args)
    if (
        not dry_run
        and cast(Path | None, getattr(args, "materialization_run_card", None)) is None
    ):
        raise CommandError(
            "executed decision-text construction requires canonical materialization"
        )
    clearance_card_path = cast(Path | None, args.clearance_run_card)
    materialization_card_path = cast(Path | None, args.materialization_run_card)
    verified_materialization: _VerifiedMaterializedDownstreamLineage | None = None
    if materialization_card_path is not None:
        early_materialization_card = _projection_json_object(
            _read_singly_linked_regular_input(
                materialization_card_path,
                label="decision text materialization run card",
            ),
            source=materialization_card_path,
        )
        raw_materialization_outputs = early_materialization_card.get("output_paths")
        if not isinstance(raw_materialization_outputs, Sequence) or isinstance(
            raw_materialization_outputs, (str, bytes)
        ):
            raise CommandError("materialization run card lacks exact outputs")
        early_materialization_outputs = tuple(
            Path(str(path))
            for path in cast(Sequence[object], raw_materialization_outputs)
        )
        if len(early_materialization_outputs) != 6:
            raise CommandError("materialization run card output paths differ")
        verified_materialization = _verify_materialized_downstream_lineage(
            run_card_path=materialization_card_path,
            manifest_path=cast(Path, args.download_manifest),
            clearance_path=cast(Path, args.disclosure_clearance),
            document_root=early_materialization_outputs[5],
            selection_path=cast(Path, args.selection),
            controlled_private_root=cast(Path | None, args.controlled_private_root),
            initialization_receipt_path=cast(
                Path | None, args.purchase_ledger_initialization_receipt
            ),
        )
    output_root = cast(Path, args.output_root)
    source_paths = {
        "selection": cast(Path, args.selection),
        "selection_run_card": cast(Path, args.selection_run_card),
        "download_manifest": cast(Path, args.download_manifest),
        "disclosure_clearance": cast(Path, args.disclosure_clearance),
        "restriction_evidence": cast(Path, args.restriction_evidence),
        "parser_manifest": cast(Path, args.parser_manifest),
        "parser_run_card": cast(Path, args.parser_run_card),
        **(
            {"clearance_run_card": clearance_card_path}
            if clearance_card_path is not None
            else {}
        ),
        **(
            {"materialization_run_card": materialization_card_path}
            if materialization_card_path is not None
            else {}
        ),
    }
    markdown_root = cast(Path, args.markdown_root)
    decision_texts_path = _acquisition_path(
        args,
        "decision_texts_output",
        output_root / "decision-texts.jsonl",
    )
    manifest_path = _acquisition_path(
        args,
        "decision_texts_manifest_output",
        output_root / "decision-texts-manifest.json",
    )
    source_bytes = {
        name: _read_singly_linked_regular_input(
            path, label=f"decision text {name.replace('_', ' ')}"
        )
        for name, path in source_paths.items()
    }
    source_sha256 = {
        name: _bytes_sha256(payload) for name, payload in source_bytes.items()
    }
    selection_records = _projection_jsonl_records(
        source_bytes["selection"], source=source_paths["selection"]
    )
    parser_records = _projection_jsonl_records(
        source_bytes["parser_manifest"], source=source_paths["parser_manifest"]
    )
    download_records = _projection_jsonl_records(
        source_bytes["download_manifest"], source=source_paths["download_manifest"]
    )
    clearance_records = _projection_jsonl_records(
        source_bytes["disclosure_clearance"],
        source=source_paths["disclosure_clearance"],
    )
    is_materialized = _require_consistent_materialization_markers(
        download_records, clearance_records
    )
    if is_materialized:
        if materialization_card_path is None or clearance_card_path is not None:
            raise CommandError(
                "materialized decision texts require only --materialization-run-card"
            )
        materialization_card = _projection_json_object(
            source_bytes["materialization_run_card"],
            source=materialization_card_path,
        )
        materialization_outputs = materialization_card.get("output_paths")
        if not isinstance(materialization_outputs, Sequence) or isinstance(
            materialization_outputs, (str, bytes)
        ):
            raise CommandError("materialization run card lacks exact outputs")
        typed_outputs = tuple(
            Path(str(path)) for path in cast(Sequence[object], materialization_outputs)
        )
        if len(typed_outputs) != 6:
            raise CommandError("materialization run card output paths differ")
        if verified_materialization is None:
            raise CommandError("materialization lineage verification was skipped")
        if source_paths["restriction_evidence"].resolve() != typed_outputs[2].resolve():
            raise CommandError(
                "decision restriction evidence differs from materialization"
            )
    else:
        if clearance_card_path is None or materialization_card_path is not None:
            raise CommandError(
                "source decision texts require only --clearance-run-card"
            )
        clearance_run_card = _projection_json_object(
            source_bytes["clearance_run_card"],
            source=source_paths["clearance_run_card"],
        )
        clearance_snapshot = _capture_clearance_artifact_snapshot(
            run_card=clearance_run_card,
            run_card_path=source_paths["clearance_run_card"],
            clearance_path=source_paths["disclosure_clearance"],
            initial_artifact_bytes={
                os.path.abspath(path): source_bytes[name]
                for name, path in source_paths.items()
            },
        )
        _verify_authenticated_clearance_run_card(
            clearance_path=source_paths["disclosure_clearance"],
            clearance_run_card_path=source_paths["clearance_run_card"],
            expected_download_manifest_path=source_paths["download_manifest"],
            expected_restriction_path=source_paths["restriction_evidence"],
            captured_artifact_bytes=clearance_snapshot,
        )
    for name, path in source_paths.items():
        if (
            _read_singly_linked_regular_input(
                path, label=f"decision text {name.replace('_', ' ')}"
            )
            != source_bytes[name]
        ):
            raise CommandError(
                f"decision text {name.replace('_', ' ')} changed during lineage replay"
            )
    selection_run_card = _projection_json_object(
        source_bytes["selection_run_card"],
        source=source_paths["selection_run_card"],
    )
    _validate_selection_run_card_commitment(
        selection_run_card,
        selection_path=source_paths["selection"],
        selection_bytes=source_bytes["selection"],
        selection_sha256=source_sha256["selection"],
        selection_record_count=len(selection_records),
        selection_run_card_path=source_paths["selection_run_card"],
        selection_run_card_bytes=source_bytes["selection_run_card"],
        verified_successor_selection_card=(
            None
            if verified_materialization is None
            else verified_materialization.verified_successor_selection_card
        ),
    )
    parser_run_card = _projection_json_object(
        source_bytes["parser_run_card"],
        source=source_paths["parser_run_card"],
    )
    _validate_parser_run_card_commitments(
        parser_run_card,
        parser_manifest_path=source_paths["parser_manifest"],
        parser_manifest_sha256=source_sha256["parser_manifest"],
        clearance_path=source_paths["disclosure_clearance"],
        clearance_sha256=source_sha256["disclosure_clearance"],
        parser_record_count=len(parser_records),
    )
    commitment_sources = dict(source_sha256)
    if is_materialized:
        commitment_sources["clearance_run_card"] = commitment_sources.pop(
            "materialization_run_card"
        )
    commitments = {
        f"{name}_sha256": digest for name, digest in commitment_sources.items()
    }
    try:
        restriction_records = _projection_jsonl_records(
            source_bytes["restriction_evidence"],
            source=source_paths["restriction_evidence"],
        )
        records = _consume_materialized_docket_decision_authority(
            (_downstream_docket_decision_descriptor(verified_materialization)),
            lambda authority, journal: build_decision_text_records(
                selections=selection_records,
                download_manifest=download_records,
                clearance_records=clearance_records,
                restriction_records=restriction_records,
                parser_records=parser_records,
                markdown_root=markdown_root,
                input_commitments=commitments,
                docket_decision_authority=authority,
                purchase_journal=journal,
            ),
        )
    except DecisionTextArtifactError as exc:
        raise CommandError(str(exc)) from exc
    decision_texts_payload = _projection_jsonl_bytes(records)
    manifest = {
        "schema_version": DECISION_TEXT_MANIFEST_SCHEMA_VERSION,
        "eligibility_anchor": CYCLE_1_ELIGIBILITY_ANCHOR.isoformat(),
        "record_count": len(records),
        "candidate_ids_sha256": _canonical_json_sha256(
            [record["candidate_id"] for record in records]
        ),
        "decision_texts_sha256": _bytes_sha256(decision_texts_payload),
        "input_commitments": dict(sorted(commitments.items())),
        "outcome_material_model_visible": False,
        "paid_activity_requested": False,
        "paid_activity_executed": False,
    }
    manifest_payload = _projection_json_bytes(manifest)
    _acquisition_output_root(args)
    if not dry_run:
        if not is_materialized:
            raise CommandError(
                "executed decision-text construction requires canonical materialization"
            )
        _ensure_projection_artifact(
            decision_texts_path,
            decision_texts_payload,
            resume=cast(bool, args.resume),
            stage="build-decision-texts",
        )
        _ensure_projection_artifact(
            manifest_path,
            manifest_payload,
            resume=cast(bool, args.resume),
            stage="build-decision-texts",
        )
    _write_acquisition_completion(
        args,
        stage="build-decision-texts",
        input_paths=(*source_paths.values(), markdown_root),
        output_paths=(decision_texts_path, manifest_path),
        record_count=len(records),
        dry_run=dry_run,
        paid_activity_requested=False,
        paid_activity_executed=False,
        extra={
            "eligibility_anchor": CYCLE_1_ELIGIBILITY_ANCHOR.isoformat(),
            "decision_texts_sha256": _bytes_sha256(decision_texts_payload),
            "decision_texts_manifest_sha256": _bytes_sha256(manifest_payload),
            "input_commitments": dict(sorted(commitments.items())),
        },
    )
    return 0


def _verify_decision_text_artifact_with_materialization(
    *,
    args: argparse.Namespace,
    decision_texts_path: Path,
    manifest_path: Path,
    run_card_path: Path,
    selections: Sequence[Mapping[str, Any]],
    selection_path: Path,
    parser_records: Sequence[Mapping[str, Any]],
    parser_manifest_path: Path,
    finalized_unit_records: Sequence[Mapping[str, Any]],
    finalized_units_path: Path,
    markdown_root: Path,
) -> VerifiedDecisionTextArtifact:
    """Verify Stage B text, replaying docket authority when its build used it."""

    decision_records = _projection_jsonl_records(
        _read_singly_linked_regular_input(
            decision_texts_path, label="decision text artifact"
        ),
        source=decision_texts_path,
    )
    if not any(
        record.get("source_provenance") == "authenticated_docket_entry_text"
        for record in decision_records
    ):
        return verify_decision_text_artifact(
            decision_texts_path=decision_texts_path,
            manifest_path=manifest_path,
            run_card_path=run_card_path,
            selections=selections,
            selection_path=selection_path,
            parser_records=parser_records,
            parser_manifest_path=parser_manifest_path,
            finalized_unit_records=finalized_unit_records,
            finalized_units_path=finalized_units_path,
            markdown_root=markdown_root,
        )
    run_card = _projection_json_object(
        _read_singly_linked_regular_input(
            run_card_path, label="decision text lineage run card"
        ),
        source=run_card_path,
    )
    raw_inputs = run_card.get("input_paths")
    if not isinstance(raw_inputs, Sequence) or isinstance(raw_inputs, (str, bytes)):
        raise CommandError("decision text run card lacks exact input paths")
    materialization_cards: list[Path] = []
    for raw_path in cast(Sequence[object], raw_inputs):
        path = Path(str(raw_path))
        if path.resolve() == markdown_root.resolve():
            continue
        payload = _read_singly_linked_regular_input(
            path, label="decision text lineage input"
        )
        try:
            card = _projection_json_object(payload, source=path)
        except CommandError:
            continue
        if card.get("stage") == "materialize-cohort-documents":
            materialization_cards.append(path)
    if len(materialization_cards) > 1:
        raise CommandError(
            "decision text run card has ambiguous materialization lineage"
        )
    if not materialization_cards:
        raise CommandError(
            "decision text artifact declares authenticated docket entries but its "
            "run card has no materialization lineage"
        )
    materialization_card_path = materialization_cards[0]
    materialization_card = _projection_json_object(
        _read_singly_linked_regular_input(
            materialization_card_path, label="decision text materialization run card"
        ),
        source=materialization_card_path,
    )
    outputs = materialization_card.get("output_paths")
    typed_output_values = (
        cast(Sequence[object], outputs)
        if isinstance(outputs, Sequence) and not isinstance(outputs, (str, bytes))
        else ()
    )
    if not typed_output_values or len(typed_output_values) != 6:
        raise CommandError("materialization run card output paths differ")
    typed_outputs = tuple(Path(str(path)) for path in typed_output_values)
    verified = _verify_materialized_downstream_lineage(
        run_card_path=materialization_card_path,
        manifest_path=typed_outputs[0],
        clearance_path=typed_outputs[1],
        document_root=typed_outputs[5],
        selection_path=selection_path,
        controlled_private_root=cast(Path | None, args.controlled_private_root),
        initialization_receipt_path=cast(
            Path | None, args.purchase_ledger_initialization_receipt
        ),
    )
    return cast(
        VerifiedDecisionTextArtifact,
        _consume_materialized_docket_decision_authority(
            _downstream_docket_decision_descriptor(verified),
            lambda authority, journal: verify_decision_text_artifact(
                decision_texts_path=decision_texts_path,
                manifest_path=manifest_path,
                run_card_path=run_card_path,
                selections=selections,
                selection_path=selection_path,
                parser_records=parser_records,
                parser_manifest_path=parser_manifest_path,
                finalized_unit_records=finalized_unit_records,
                finalized_units_path=finalized_units_path,
                markdown_root=markdown_root,
                docket_decision_authority=authority,
                purchase_journal=journal,
            ),
        ),
    )


_STAGE_A_UNITIZATION_LINEAGE_SCHEMA_VERSION = (
    "legalforecast.stage_a_unitization_lineage.v1"
)
_VERIFIED_STAGE_A_PARSE_LINEAGE_SEAL = object()


@dataclass(frozen=True, slots=True)
class _VerifiedStageAParseLineage:
    """Provider-free authenticated selection, parser, and Markdown lineage."""

    selection_records: tuple[JsonRecord, ...]
    selection_bytes: bytes
    parser_records: tuple[JsonRecord, ...]
    parser_manifest_bytes: bytes
    document_root: Path
    markdown_root: Path
    cohort_cycle_id: str
    input_paths: tuple[Path, ...]
    input_commitments: Mapping[str, object]
    markdown_tree: Mapping[str, object]
    file_snapshots: Mapping[Path, bytes]
    document_tree: Mapping[str, bytes]
    markdown_bytes: Mapping[str, bytes]
    download_records: tuple[JsonRecord, ...] = ()
    verifier_seal: object | None = dataclasses.field(
        repr=False, compare=False, default=None
    )


@dataclass(frozen=True, slots=True)
class _StageAUnitizationLineage:
    selection_records: tuple[JsonRecord, ...]
    parser_records: tuple[JsonRecord, ...]
    registry_entry: ModelRegistryEntry
    registry_sha256: str
    provider_caps: ProviderCycleCaps
    provider_caps_sha256: str
    provider_journal_path: Path
    document_root: Path
    markdown_root: Path
    cohort_cycle_id: str
    input_paths: tuple[Path, ...]
    input_commitments: Mapping[str, object]
    markdown_tree: Mapping[str, object]
    file_snapshots: Mapping[Path, bytes]
    document_tree: Mapping[str, bytes]
    markdown_bytes: Mapping[str, bytes]
    download_records: tuple[JsonRecord, ...] = ()
    verified_provider_attempt_rows: tuple[JsonRecord, ...] = ()


def _required_stage_a_lineage_path(
    args: argparse.Namespace, attribute: str, flag: str
) -> Path:
    path = cast(Path | None, getattr(args, attribute, None))
    if path is None:
        raise CommandError(
            "authenticated Stage A lineage requires " + flag + " with --execute"
        )
    return path


def _verify_stage_a_unitization_lineage_uncached(
    args: argparse.Namespace,
    *,
    markdown_root: Path,
    parse_lineage: object | None = None,
) -> _StageAUnitizationLineage:
    if parse_lineage is None:
        parse_lineage = _verify_stage_a_parse_lineage_uncached(
            args, markdown_root=markdown_root
        )
    elif (
        not isinstance(parse_lineage, _VerifiedStageAParseLineage)
        or parse_lineage.verifier_seal is not _VERIFIED_STAGE_A_PARSE_LINEAGE_SEAL
    ):
        raise CommandError("Stage A parse-lineage handoff is not verifier-owned")
    registry_path = cast(Path, args.model_registry)
    caps_path = _required_stage_a_lineage_path(
        args, "provider_cycle_caps", "--provider-cycle-caps"
    )
    provider_journal_path = _required_stage_a_lineage_path(
        args, "provider_journal", "--provider-journal"
    )
    for path in (registry_path, caps_path):
        if path.is_symlink() or not path.is_file():
            raise CommandError(f"authenticated Stage A input is not a file: {path}")
    if provider_journal_path.exists() and (
        provider_journal_path.is_symlink() or not provider_journal_path.is_file()
    ):
        raise CommandError(
            f"shared provider journal is not a regular file: {provider_journal_path}"
        )
    provider_snapshots = {
        path: _read_singly_linked_regular_input(
            path, label="authenticated Stage A input"
        )
        for path in (registry_path, caps_path)
    }
    try:
        provider_caps = load_provider_cycle_caps_bytes(
            provider_snapshots[caps_path], source=caps_path
        )
    except ProviderJournalError as exc:
        raise CommandError(str(exc)) from exc
    if provider_caps.cycle_id != parse_lineage.cohort_cycle_id:
        raise CommandError(
            "provider cycle caps cycle_id differs from authenticated cohort: "
            f"{provider_caps.cycle_id!r} != {parse_lineage.cohort_cycle_id!r}"
        )
    registry_entries, registry_sha256 = _registry_entries_for_keys_bytes(
        provider_snapshots[registry_path], (cast(str, args.model_key),)
    )
    registry_entry = registry_entries[0]
    provider_caps.cap_usd(registry_entry.provider)
    _require_stage_a_parse_lineage_unchanged(parse_lineage)
    _require_snapshot_unchanged(
        provider_snapshots, label="authenticated Stage A provider input"
    )
    return _StageAUnitizationLineage(
        selection_records=parse_lineage.selection_records,
        parser_records=parse_lineage.parser_records,
        download_records=parse_lineage.download_records,
        registry_entry=registry_entry,
        registry_sha256=registry_sha256,
        provider_caps=provider_caps,
        provider_caps_sha256=hashlib.sha256(provider_snapshots[caps_path]).hexdigest(),
        provider_journal_path=provider_journal_path,
        document_root=parse_lineage.document_root,
        markdown_root=parse_lineage.markdown_root,
        cohort_cycle_id=parse_lineage.cohort_cycle_id,
        input_paths=(
            *parse_lineage.input_paths[:10],
            registry_path,
            caps_path,
            provider_journal_path,
            *parse_lineage.input_paths[10:],
        ),
        input_commitments={
            **parse_lineage.input_commitments,
            "model_registry": _stage_a_file_commitment(
                registry_path, payload=provider_snapshots[registry_path]
            ),
            "provider_cycle_caps": _stage_a_file_commitment(
                caps_path, payload=provider_snapshots[caps_path]
            ),
        },
        markdown_tree=parse_lineage.markdown_tree,
        file_snapshots={**parse_lineage.file_snapshots, **provider_snapshots},
        document_tree=parse_lineage.document_tree,
        markdown_bytes=parse_lineage.markdown_bytes,
    )


def _verify_stage_a_parse_lineage_uncached(
    args: argparse.Namespace,
    *,
    markdown_root: Path,
) -> _VerifiedStageAParseLineage:
    """Authenticate parser inputs before model registry or journal concerns."""

    selection_path = cast(Path, args.selection)
    selection_run_card_path = _required_stage_a_lineage_path(
        args, "selection_run_card", "--selection-run-card"
    )
    manifest_path = _required_stage_a_lineage_path(
        args, "download_manifest", "--download-manifest"
    )
    clearance_path = _required_stage_a_lineage_path(
        args, "disclosure_clearance", "--disclosure-clearance"
    )
    materialization_card_path = _required_stage_a_lineage_path(
        args, "materialization_run_card", "--materialization-run-card"
    )
    document_root = _required_stage_a_lineage_path(
        args, "document_root", "--document-root"
    )
    requests_path = _required_stage_a_lineage_path(
        args, "parse_requests", "--parse-requests"
    )
    parser_manifest_path = cast(Path, args.parser_manifest)
    parser_run_card_path = _required_stage_a_lineage_path(
        args, "parser_run_card", "--parser-run-card"
    )
    regular_files = (
        selection_path,
        selection_run_card_path,
        manifest_path,
        clearance_path,
        materialization_card_path,
        requests_path,
        parser_manifest_path,
        parser_run_card_path,
    )
    for path in regular_files:
        if path.is_symlink() or not path.is_file():
            raise CommandError(f"authenticated Stage A input is not a file: {path}")
    stage_a_file_snapshots = {
        path: _read_singly_linked_regular_input(
            path, label="authenticated Stage A input"
        )
        for path in regular_files
    }
    if document_root.is_symlink() or not document_root.is_dir():
        raise CommandError(
            f"authenticated Stage A document root is invalid: {document_root}"
        )
    if markdown_root.is_symlink() or not markdown_root.is_dir():
        raise CommandError(
            f"authenticated Stage A Markdown root is invalid: {markdown_root}"
        )
    parser_records = tuple(
        _projection_jsonl_records(
            stage_a_file_snapshots[parser_manifest_path], source=parser_manifest_path
        )
    )
    verified_materialization = _verify_materialized_downstream_lineage(
        run_card_path=materialization_card_path,
        manifest_path=manifest_path,
        clearance_path=clearance_path,
        document_root=document_root,
        selection_path=selection_path,
        controlled_private_root=cast(
            Path | None, getattr(args, "controlled_private_root", None)
        ),
        initialization_receipt_path=cast(
            Path | None,
            getattr(args, "purchase_ledger_initialization_receipt", None),
        ),
    )
    for path in (
        selection_path,
        manifest_path,
        clearance_path,
        materialization_card_path,
    ):
        if (
            verified_materialization.artifact_bytes[os.path.abspath(path)]
            != stage_a_file_snapshots[path]
        ):
            raise CommandError(f"authenticated Stage A input changed: {path}")
    selection_records = verified_materialization.selection_records
    selection_card_bytes = stage_a_file_snapshots[selection_run_card_path]
    selection_card = _projection_json_object(
        selection_card_bytes, source=selection_run_card_path
    )
    selection_bytes = verified_materialization.artifact_bytes[
        os.path.abspath(selection_path)
    ]
    _validate_selection_run_card_commitment(
        selection_card,
        selection_path=selection_path,
        selection_bytes=selection_bytes,
        selection_sha256=_bytes_sha256(selection_bytes),
        selection_record_count=len(selection_records),
        selection_run_card_path=selection_run_card_path,
        selection_run_card_bytes=selection_card_bytes,
        verified_successor_selection_card=(
            verified_materialization.verified_successor_selection_card
        ),
    )
    materialization_paths = verified_materialization.paths
    markdown_tree, markdown_bytes = _stage_a_markdown_tree_snapshot(
        parser_records, markdown_root=markdown_root
    )
    _verify_stage_a_parse_lineage(
        selection_path=selection_path,
        manifest_path=manifest_path,
        clearance_path=clearance_path,
        document_root=document_root,
        materialization_paths=materialization_paths,
        requests_path=requests_path,
        parser_manifest_path=parser_manifest_path,
        parser_records=parser_records,
        parser_run_card_path=parser_run_card_path,
        selection_bytes=stage_a_file_snapshots[selection_path],
        requests_bytes=stage_a_file_snapshots[requests_path],
        parser_manifest_bytes=stage_a_file_snapshots[parser_manifest_path],
        parser_run_card_bytes=stage_a_file_snapshots[parser_run_card_path],
        markdown_root=markdown_root,
        download_records=verified_materialization.manifest_records,
        clearance_bytes=verified_materialization.artifact_bytes[
            os.path.abspath(clearance_path)
        ],
        markdown_bytes=markdown_bytes,
    )
    cohort_cycle_id = _materialization_cohort_cycle_id(
        materialization_card_path,
        captured_artifact_bytes=verified_materialization.artifact_bytes,
    )
    input_paths = (
        selection_path,
        selection_run_card_path,
        manifest_path,
        clearance_path,
        materialization_card_path,
        document_root,
        requests_path,
        parser_manifest_path,
        parser_run_card_path,
        markdown_root,
        *materialization_paths[1:],
    )
    file_commitments = {
        name: _stage_a_file_commitment(path, payload=stage_a_file_snapshots[path])
        for name, path in (
            ("selection", selection_path),
            ("selection_run_card", selection_run_card_path),
            ("download_manifest", manifest_path),
            ("disclosure_clearance", clearance_path),
            ("materialization_run_card", materialization_card_path),
            ("parse_requests", requests_path),
            ("parser_manifest", parser_manifest_path),
            ("parser_run_card", parser_run_card_path),
        )
    }
    _require_snapshot_unchanged(
        stage_a_file_snapshots, label="authenticated Stage A input"
    )
    if _materializer_tree_snapshot(document_root) != dict(
        verified_materialization.document_tree
    ):
        raise CommandError("authenticated Stage A document tree changed")
    return _VerifiedStageAParseLineage(
        selection_records=tuple(dict(record) for record in selection_records),
        selection_bytes=stage_a_file_snapshots[selection_path],
        parser_records=parser_records,
        download_records=tuple(
            dict(record) for record in verified_materialization.manifest_records
        ),
        parser_manifest_bytes=stage_a_file_snapshots[parser_manifest_path],
        document_root=document_root,
        markdown_root=markdown_root,
        cohort_cycle_id=cohort_cycle_id,
        input_paths=input_paths,
        input_commitments={
            **file_commitments,
            "document_tree": {
                path: _bytes_sha256(payload)
                for path, payload in verified_materialization.document_tree.items()
            },
            "markdown_tree": dict(markdown_tree),
        },
        markdown_tree=markdown_tree,
        file_snapshots=dict(stage_a_file_snapshots),
        document_tree=dict(verified_materialization.document_tree),
        markdown_bytes=markdown_bytes,
        verifier_seal=_VERIFIED_STAGE_A_PARSE_LINEAGE_SEAL,
    )


def _verify_stage_a_unitization_lineage(
    args: argparse.Namespace,
    *,
    markdown_root: Path,
    parse_lineage: _VerifiedStageAParseLineage | None = None,
) -> _StageAUnitizationLineage:
    """Replay Stage A lineage while reusing identical authenticated PDF scans."""

    # The replay still reads and hashes every artifact at every authority boundary.
    # This only reuses a scan when the scanner version, byte length, and SHA-256
    # all match within this top-level preflight.
    with cache_disclosure_document_scans():
        return _verify_stage_a_unitization_lineage_uncached(
            args,
            markdown_root=markdown_root,
            parse_lineage=parse_lineage,
        )


def _verify_verified_stage_a_parse_lineage(
    args: argparse.Namespace,
    *,
    markdown_root: Path,
) -> _VerifiedStageAParseLineage:
    """Replay provider-free parser lineage while reusing verified PDF scans."""

    with cache_disclosure_document_scans():
        return _verify_stage_a_parse_lineage_uncached(args, markdown_root=markdown_root)


def _require_stage_a_parse_lineage_unchanged(
    lineage: _VerifiedStageAParseLineage,
) -> None:
    """Close the parser-lineage TOCTOU interval before a downstream decision."""

    _require_snapshot_unchanged(
        lineage.file_snapshots, label="authenticated Stage A parser input"
    )
    if _materializer_tree_snapshot(lineage.document_root) != dict(
        lineage.document_tree
    ):
        raise CommandError("authenticated Stage A document tree changed")
    markdown_paths = {
        lineage.markdown_root / relative_path: payload
        for relative_path, payload in lineage.markdown_bytes.items()
    }
    _require_snapshot_unchanged(markdown_paths, label="authenticated Stage A Markdown")


def _require_v4_eligibility_lineage_matches_unitization(
    eligibility_lineage: _VerifiedStageAParseLineage,
    unitization_lineage: _StageAUnitizationLineage,
) -> None:
    """Bind the clean audit snapshot to the later provider-bearing replay."""

    matching_commitments = {
        name: unitization_lineage.input_commitments.get(name)
        for name in eligibility_lineage.input_commitments
    }
    if any(
        (
            eligibility_lineage.selection_records
            != unitization_lineage.selection_records,
            eligibility_lineage.parser_records != unitization_lineage.parser_records,
            eligibility_lineage.document_root.resolve()
            != unitization_lineage.document_root.resolve(),
            eligibility_lineage.markdown_root.resolve()
            != unitization_lineage.markdown_root.resolve(),
            eligibility_lineage.cohort_cycle_id != unitization_lineage.cohort_cycle_id,
            dict(eligibility_lineage.input_commitments) != matching_commitments,
            dict(eligibility_lineage.markdown_tree)
            != dict(unitization_lineage.markdown_tree),
            dict(eligibility_lineage.document_tree)
            != dict(unitization_lineage.document_tree),
            dict(eligibility_lineage.markdown_bytes)
            != dict(unitization_lineage.markdown_bytes),
        )
    ):
        raise CommandError(
            "v4 target-document eligibility lineage differs from provider-bearing "
            "Stage A lineage"
        )
    for path, payload in eligibility_lineage.file_snapshots.items():
        if unitization_lineage.file_snapshots.get(path) != payload:
            raise CommandError(
                "v4 target-document eligibility snapshot differs from "
                "provider-bearing Stage A lineage"
            )


def _stage_a_file_commitment(path: Path, *, payload: bytes | None = None) -> JsonRecord:
    return {
        "path": str(path.resolve()),
        "sha256": _bytes_sha256(payload) if payload is not None else _path_sha256(path),
    }


def _stage_a_captured_payload(
    path: Path, *, captured_input_bytes: Mapping[str, bytes] | None
) -> bytes | None:
    """Return the caller-authenticated bytes for one path, when it captured it.

    This is a partial overlay, unlike `_captured_or_stable_input`: a caller
    that already authenticated a subset of an artifact chain binds exactly that
    subset, and every other path is still read fresh.  Reusing the captured
    bytes is what stops a verifier from authenticating one byte set while the
    caller commits another, which a re-read cannot detect when an input is
    swapped and restored around the read.
    """

    if captured_input_bytes is None:
        return None
    return captured_input_bytes.get(str(path.resolve()))


def _stage_a_captured_records(
    path: Path,
    *,
    label: str,
    captured_input_bytes: Mapping[str, bytes] | None,
) -> list[JsonRecord]:
    """Parse records from caller-authenticated bytes, or read the path fresh.

    Every Stage A artifact a caller captures is JSONL, and the capturing
    command already parses those same bytes with `_read_jsonl_payload`, so
    reuse decodes them identically rather than re-reading the path.
    """

    payload = _stage_a_captured_payload(path, captured_input_bytes=captured_input_bytes)
    if payload is None:
        return _read_records(path)
    try:
        return _read_jsonl_payload(payload, label=label)
    except ValueError as exc:
        raise CommandError(str(exc)) from exc


def _stage_a_captured_json_object(
    path: Path,
    *,
    label: str,
    captured_input_bytes: Mapping[str, bytes] | None,
) -> JsonRecord:
    """Parse one JSON object from caller-authenticated bytes, or read it fresh."""

    payload = _stage_a_captured_payload(path, captured_input_bytes=captured_input_bytes)
    if payload is None:
        return _read_json_object(path)
    try:
        return _read_json_object_payload(payload, label=label)
    except ValueError as exc:
        raise CommandError(str(exc)) from exc


def _materialization_cohort_cycle_id(
    run_card_path: Path,
    *,
    captured_artifact_bytes: Mapping[str, bytes] | None = None,
) -> str:
    card_bytes = _captured_or_stable_input(
        run_card_path,
        label="materialization run card",
        captured_artifact_bytes=captured_artifact_bytes,
    )
    card = _projection_json_object(card_bytes, source=run_card_path)
    inputs = card.get("input_paths")
    if not isinstance(inputs, Sequence) or isinstance(inputs, (str, bytes)):
        raise CommandError("materialization run card lacks cohort-policy input")
    typed = tuple(Path(str(path)) for path in cast(Sequence[object], inputs))
    if len(typed) not in {12, 13, 14, 15}:
        raise CommandError("materialization run card input paths differ")
    cohort_policy_path = typed[10]
    try:
        policy_bytes = _captured_or_stable_input(
            cohort_policy_path,
            label="materialization cohort policy",
            captured_artifact_bytes=captured_artifact_bytes,
        )
        artifact = _projection_json_object(policy_bytes, source=cohort_policy_path)
        verify_cohort_policy(artifact)
    except (CohortPolicyError, OSError, ValueError) as exc:
        raise CommandError(f"invalid materialization cohort policy: {exc}") from exc
    policy = artifact.get("policy")
    if not isinstance(policy, Mapping):
        raise CommandError("materialization cohort policy lacks policy object")
    cycle_id = cast(Mapping[str, object], policy).get("cycle_id")
    if not isinstance(cycle_id, str) or not cycle_id.strip():
        raise CommandError("materialization cohort policy lacks cycle_id")
    return cycle_id.strip()


def _verify_stage_a_parse_lineage(
    *,
    selection_path: Path,
    manifest_path: Path,
    clearance_path: Path,
    document_root: Path,
    materialization_paths: Sequence[Path],
    requests_path: Path,
    parser_manifest_path: Path,
    parser_records: Sequence[Mapping[str, Any]],
    parser_run_card_path: Path,
    selection_bytes: bytes,
    requests_bytes: bytes,
    parser_manifest_bytes: bytes,
    parser_run_card_bytes: bytes,
    markdown_root: Path,
    download_records: Sequence[Mapping[str, Any]],
    clearance_bytes: bytes,
    markdown_bytes: Mapping[str, bytes],
) -> None:
    parser_card = _projection_json_object(
        parser_run_card_bytes, source=parser_run_card_path
    )
    _validate_parser_run_card_commitments(
        parser_card,
        parser_manifest_path=parser_manifest_path,
        parser_manifest_sha256=_bytes_sha256(parser_manifest_bytes),
        clearance_path=clearance_path,
        clearance_sha256=_bytes_sha256(clearance_bytes),
        parser_record_count=len(parser_records),
    )
    expected_inputs = (
        selection_path,
        requests_path,
        clearance_path,
        *materialization_paths,
    )
    raw_inputs = parser_card.get("input_paths")
    raw_outputs = parser_card.get("output_paths")
    if not isinstance(raw_inputs, Sequence) or isinstance(raw_inputs, (str, bytes)):
        raise CommandError("parse-documents run card lacks exact input paths")
    if not isinstance(raw_outputs, Sequence) or isinstance(raw_outputs, (str, bytes)):
        raise CommandError("parse-documents run card lacks exact output paths")
    actual_inputs = tuple(
        Path(str(path)).resolve() for path in cast(Sequence[object], raw_inputs)
    )
    if actual_inputs != tuple(path.resolve() for path in expected_inputs):
        raise CommandError("parse-documents inputs differ from materialized lineage")
    actual_outputs = tuple(
        Path(str(path)).resolve() for path in cast(Sequence[object], raw_outputs)
    )
    if actual_outputs != (parser_manifest_path.resolve(),):
        raise CommandError("parse-documents output differs from parser manifest")
    commitments = parser_card.get("source_commitments")
    if not isinstance(commitments, Mapping):
        raise CommandError("parse-documents run card lacks source commitments")
    for name, path in (
        ("selection", selection_path),
        ("requests", requests_path),
        ("disclosure_clearance", clearance_path),
    ):
        _validate_named_path_commitment(
            cast(Mapping[str, object], commitments),
            name=name,
            expected_path=path,
            expected_sha256=(
                _bytes_sha256(clearance_bytes)
                if path == clearance_path
                else _bytes_sha256(
                    requests_bytes if path == requests_path else selection_bytes
                )
            ),
        )
    _verify_stage_a_parse_records(
        download_records=download_records,
        request_records=_projection_jsonl_records(requests_bytes, source=requests_path),
        parser_records=parser_records,
        document_root=document_root,
        parser_output_root=parser_manifest_path.parent,
        markdown_root=markdown_root,
        markdown_bytes=markdown_bytes,
    )


def _verify_stage_a_parse_records(
    *,
    download_records: Sequence[Mapping[str, Any]],
    request_records: Sequence[Mapping[str, Any]],
    parser_records: Sequence[Mapping[str, Any]],
    document_root: Path,
    parser_output_root: Path,
    markdown_root: Path,
    markdown_bytes: Mapping[str, bytes],
) -> None:
    def keyed(
        records: Sequence[Mapping[str, Any]], *, label: str
    ) -> dict[tuple[str, str], Mapping[str, Any]]:
        result: dict[tuple[str, str], Mapping[str, Any]] = {}
        for record in records:
            key = (
                _required_str(record, "candidate_id"),
                _required_str(record, "source_document_id"),
            )
            if key in result:
                raise CommandError(f"duplicate {label} row: {key[0]}/{key[1]}")
            result[key] = record
        return result

    downloads = keyed(download_records, label="materialized manifest")
    requests = keyed(request_records, label="parse request")
    parsed = keyed(parser_records, label="parser manifest")
    if not downloads or set(downloads) != set(requests) or set(requests) != set(parsed):
        raise CommandError(
            "materialized documents, parse requests, and parser manifest differ"
        )
    for key, download in downloads.items():
        request = requests[key]
        parser = parsed[key]
        local_path = Path(_required_str(download, "local_path"))
        expected_input = (
            local_path if local_path.is_absolute() else document_root / local_path
        ).resolve()
        request_input = Path(_required_str(request, "input_path")).resolve()
        if request_input != expected_input:
            raise CommandError(f"parse request input differs: {key[0]}/{key[1]}")
        if request.get("expected_sha256") != _required_str(
            download, "sha256"
        ).removeprefix("sha256:") or request.get(
            "expected_byte_count"
        ) != _required_int(download, "byte_count"):
            raise CommandError(f"parse request source commitment differs: {key}")
        if parser.get("status") != "succeeded" or parser.get("quality_flags") != []:
            raise CommandError(f"parser record is not clean and successful: {key}")
        if parser.get("source_sha256") != request.get("expected_sha256") or parser.get(
            "source_byte_count"
        ) != request.get("expected_byte_count"):
            raise CommandError(f"parser source commitment differs: {key}")
        request_markdown = Path(_required_str(request, "markdown_output_path"))
        expected_markdown = (
            request_markdown
            if request_markdown.is_absolute()
            else parser_output_root / request_markdown
        ).resolve()
        parser_markdown = _stage_a_markdown_path(parser, markdown_root=markdown_root)
        if parser_markdown != expected_markdown:
            raise CommandError(f"parser Markdown path differs: {key}")
        extracted = parser.get("extracted_text")
        if not isinstance(extracted, Mapping):
            raise CommandError(f"parser record lacks extracted text: {key}")
        extracted_record = cast(Mapping[str, object], extracted)
        if extracted_record.get("extraction_method") != "mistral_parser_markdown":
            raise CommandError(f"parser record is not live Mistral output: {key}")
        expected_text_sha = extracted_record.get("text_sha256")
        relative_markdown = parser_markdown.relative_to(
            markdown_root.resolve()
        ).as_posix()
        try:
            markdown_payload = markdown_bytes[relative_markdown]
        except KeyError as exc:
            raise CommandError(f"parser Markdown snapshot is missing: {key}") from exc
        actual_text_sha = hashlib.sha256(markdown_payload).hexdigest()
        if not isinstance(expected_text_sha, str) or (
            expected_text_sha.removeprefix("sha256:") != actual_text_sha
        ):
            raise CommandError(f"parser Markdown hash differs: {key}")


def _stage_a_markdown_path(record: Mapping[str, Any], *, markdown_root: Path) -> Path:
    raw = Path(_required_str(record, "markdown_path"))
    path = (raw if raw.is_absolute() else markdown_root / raw).resolve()
    root = markdown_root.resolve()
    if not path.is_relative_to(root):
        raise CommandError(f"parser Markdown escapes trusted root: {path}")
    if path.is_symlink() or not path.is_file():
        raise CommandError(f"parser Markdown is not a regular file: {path}")
    return path


def _stage_a_markdown_tree_snapshot(
    parser_records: Sequence[Mapping[str, Any]], *, markdown_root: Path
) -> tuple[dict[str, JsonRecord], dict[str, bytes]]:
    root = markdown_root.resolve()
    expected_paths = {
        _stage_a_markdown_path(record, markdown_root=markdown_root)
        for record in parser_records
    }
    observed_paths: set[Path] = set()
    for path in markdown_root.rglob("*"):
        if path.is_symlink():
            raise CommandError(f"Markdown tree contains a symlink: {path}")
        if path.is_file() and path.suffix.casefold() == ".md":
            observed_paths.add(path.resolve())
    if observed_paths != expected_paths:
        raise CommandError("Markdown tree differs from exact parser manifest")
    snapshots = {
        path.relative_to(root).as_posix(): _read_singly_linked_regular_input(
            path, label="Stage A Markdown"
        )
        for path in sorted(expected_paths)
    }
    return {
        path.relative_to(root).as_posix(): {
            "path": str(path),
            "sha256": _bytes_sha256(snapshots[path.relative_to(root).as_posix()]),
            "byte_count": len(snapshots[path.relative_to(root).as_posix()]),
        }
        for path in sorted(expected_paths)
    }, snapshots


def _require_stage_a_lineage_unchanged(
    lineage: _StageAUnitizationLineage,
) -> None:
    _require_snapshot_unchanged(
        lineage.file_snapshots, label="authenticated Stage A input"
    )
    if _materializer_tree_snapshot(lineage.document_root) != dict(
        lineage.document_tree
    ):
        raise CommandError("authenticated Stage A document tree changed")
    markdown_paths = {
        lineage.markdown_root / relative_path: payload
        for relative_path, payload in lineage.markdown_bytes.items()
    }
    _require_snapshot_unchanged(markdown_paths, label="authenticated Stage A Markdown")


